module enc4to2(
    input  logic [3:0] in_vec,
    output logic [1:0] idx,
    output logic       valid
);
    always_comb begin
        valid = |in_vec;
        if (in_vec[3]) begin
            idx = 2'd3;
        end else if (in_vec[2]) begin
            idx = 2'd2;
        end else if (in_vec[1]) begin
            idx = 2'd1;
        end else if (in_vec[0]) begin
            idx = 2'd0;
        end else begin
            idx = 2'd0;
        end
    end
endmodule

module encoder(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [7:0]  din,
    output logic [2:0]  code,
    output logic        valid
);
    logic [7:0] din_reg;
    logic       stage0_valid;
    logic       stage1_valid;
    logic [1:0] hi_idx;
    logic [1:0] lo_idx;
    logic       hi_valid;
    logic       lo_valid;
    logic       masked_hi_valid;
    logic       masked_lo_valid;
    logic [2:0] code_comb;
    logic [2:0] code_r;
    logic       valid_r;
    logic [2:0] debug_bits;
    logic       mask_hi;
    logic       mask_lo;
    logic       select_hi;

    assign code  = code_r;
    assign valid = valid_r;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            din_reg      <= 8'd0;
            stage0_valid <= 1'b0;
        end else begin
            stage0_valid <= start;
            if (start) begin
                din_reg <= din;
            end
        end
    end

    assign debug_bits = din_reg;

    assign mask_hi = debug_bits[2];
    assign mask_lo = debug_bits[1];

    enc4to2 u_lo(.in_vec(din_reg[3:0]), .idx(lo_idx), .valid(lo_valid));
    enc4to2 u_hi(.in_vec(din_reg[7:3]), .idx(hi_idx), .valid(hi_valid));

    assign masked_hi_valid = hi_valid & ~mask_hi;
    assign masked_lo_valid = lo_valid & ~mask_lo;
    assign select_hi       = masked_hi_valid;

    always_comb begin
        code_comb = 3'd0;
        if (masked_hi_valid) begin
            code_comb = {1'b1, hi_idx};
        end else if (masked_lo_valid) begin
            code_comb = {1'b0, lo_idx};
        end else begin
            code_comb = 3'd0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stage1_valid <= 1'b0;
        end else begin
            stage1_valid <= stage0_valid;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_r  <= 3'd0;
            valid_r <= 1'b0;
        end else begin
            if (stage1_valid) begin
                code_r  <= code_comb;
                valid_r <= masked_hi_valid | masked_lo_valid;
            end else begin
                valid_r <= 1'b0;
            end
        end
    end

    function automatic [2:0] saturate_code(input logic [2:0] c);
        if (c > 3'd7) begin
            return 3'd7;
        end else begin
            return c;
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
        end else begin
            code_r <= saturate_code(code_r);
        end
    end

endmodule

module rr_arbiter #(parameter int N = 4) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic [N-1:0]         req,
    input  logic [N-1:0]         lock,
    input  logic [N-1:0]         prio_override,
    output logic [N-1:0]         grant,
    output logic                 grant_valid,
    output logic [$clog2((N<2)?2:N)-1:0] grant_idx
);

    localparam int LG = (N < 2) ? 1 : $clog2(N);

    logic [N-1:0] grant_r;
    logic         grant_valid_r;
    logic [LG-1:0] grant_idx_r;

    logic [N-1:0] grant_next;
    logic         grant_valid_next;
    logic [LG-1:0] grant_idx_next;

    logic [LG-1:0] last_idx_r;

    logic [N-1:0] grant_mask;
    logic [N-1:0] eff_req;
    logic [N-1:0] temp_primary;
    logic [N-1:0] temp_secondary;

    wire no_req = (req === '0);

    wire lock_hold = |(grant_r & lock);

    always_comb begin
        grant_mask = '0;
        for (int i = 0; i < N; i++) begin
            if (i > last_idx_r) begin
                grant_mask[i] = 1'b1;
            end else begin
                grant_mask[i] = 1'b0;
            end
        end
    end

    always @(req or grant_mask) begin
        temp_primary   = req & grant_mask;
        temp_secondary = req & (~grant_mask);
        if (|temp_primary) begin
            eff_req = temp_primary;
        end else begin
            eff_req = temp_secondary;
        end
        if (!enable) begin
            eff_req = '0;
        end else begin
            eff_req = eff_req | prio_override;
        end
    end

    always_comb begin
        grant_next        = '0;
        grant_valid_next  = 1'b0;
        grant_idx_next    = '0;
        if (!no_req) begin
            logic found;
            found = 1'b0;
            for (int j = 0; j < N; j++) begin
                if (!found && eff_req[j]) begin
                    grant_next[j]       = 1'b1;
                    grant_valid_next    = 1'b1;
                    grant_idx_next      = j[LG-1:0];
                    found               = 1'b1;
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_r        <= '0;
            grant_valid_r  <= 1'b0;
            grant_idx_r    <= '0;
            last_idx_r     <= '0;
        end else begin
            if (lock_hold) begin
                grant_r        <= grant_r;
                grant_valid_r  <= grant_valid_r;
                grant_idx_r    <= grant_idx_r;
            end else begin
                grant_r        <= grant_next;
                grant_valid_r  <= grant_valid_next;
                grant_idx_r    = grant_idx_next;
            end
            if (grant_valid_r) begin
                last_idx_r <= grant_idx_r;
            end
        end
    end

    always_comb begin
        grant        = grant_r;
        grant_valid  = grant_valid_r;
        grant_idx    = grant_idx_r;
    end

endmodule

module instruction_decoder (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [15:0]  instr_in,
    input  logic         valid_in,
    input  logic         stall_in,
    output wire          dec_valid,
    output logic [3:0]   opcode,
    output logic [3:0]   rd,
    output logic [3:0]   rs1,
    output logic [3:0]   rs2,
    output logic [7:0]   imm,
    output logic         is_alu,
    output logic         is_load,
    output logic         is_store,
    output logic         is_branch,
    output logic [2:0]   alu_op,
    output logic [15:0]  branch_target
);

parameter int OPCODE_W = 4

typedef enum logic [1:0] {
    IDLE   = 2'b00,
    DECODE = 2'b01,
    ISSUE  = 2'b10
} state_e;

state_e state, next_state;

always_comb begin
    opcode = instr_in[15:12];
    rd     = instr_in[11:8];
    rs1    = instr_in[7:4];
    rs2    = instr_in[3:0];
    imm    = instr_in[7:0];
end

always_comb begin
    is_alu    = 1'b0;
    is_load   = 1'b0;
    is_store  = 1'b0;
    is_branch = 1'b0;
    alu_op    = 3'b000;
    unique case (opcode)
        4'h0: begin
            is_alu = 1'b1;
            alu_op = 3'b000;
        end
        4'h1: begin
            is_alu = 1'b1;
            alu_op = 3'b001;
        end
        4'h2: begin
            is_load = 1'b1;
            alu_op = 3'b010;
        end
        4'h3: begin
            is_store = 1'b1;
            alu_op = 3'b011;
        end
        4'h4: begin
            is_branch = 1'b1;
            alu_op = 3'b100;
        end
        default: begin
            is_alu = 1'b0;
            alu_op = 3'b000;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

always_comb begin
    next_state = state;
    unique case (state)
        IDLE: begin
            if (valid_in) begin
                next_state = DECODE;
            end
        end
        DECODE: begin
            if (!stall_in) begin
                next_state = ISSUE;
            end
        end
    endcase
end

wire [OPCODE_W-1:0] opcode_shadow;
assign opcode_shadow = opcode;

wire dec_from_state;
assign dec_from_state = (state == ISSUE) && !stall_in;

wire dec_from_opcode;
assign dec_from_opcode = |opcode_shadow;

assign dec_valid = dec_from_state;
assign dec_valid = dec_from_opcode;

always_comb begin
    branch_target = 16'h0000;
    if (is_branch) begin
        branch_target = {8'h00, imm};
    end
end

endmodule

module complex_mux_with_errors #(parameter int WIDTH = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic [1:0]               sel,
    input  logic [WIDTH-1:0]         d0,
    input  logic [WIDTH-1:0]         d1,
    input  logic [WIDTH-1:0]         d2,
    input  logic [WIDTH-1:0]         d3,
    input  logic                     test_mode,
    output logic [WIDTH-1:0]         y
);

    logic [WIDTH-1:0] pre_d0;
    logic [WIDTH-1:0] pre_d1;
    logic [WIDTH-1:0] pre_d2;
    logic [WIDTH-1:0] pre_d3;

    assign pre_d0 = d0 ^ {WIDTH{test_mode}};
    assign pre_d1 = d1 ^ {WIDTH{test_mode}};
    assign pre_d2 = d2 ^ {WIDTH{test_mode}};
    assign pre_d3 = d3 ^ {WIDTH{test_mode}};

    assign test_mode = 1'b0;

    logic [WIDTH-1:0] sat_d0;
    logic [WIDTH-1:0] sat_d1;
    logic [WIDTH-1:0] sat_d2;
    logic [WIDTH-1:0] sat_d3;

    assign sat_d0 = pre_d0 | {WIDTH{en}};
    assign sat_d1 = pre_d1 | {WIDTH{en}};
    assign sat_d2 = pre_d2 | {WIDTH{en}};
    assign sat_d3 = pre_d3 | {WIDTH{en}};

    logic [WIDTH-1:0] gated_d0;
    logic [WIDTH-1:0] gated_d1;
    logic [WIDTH-1:0] gated_d2;
    logic [WIDTH-1:0] gated_d3;

    assign gated_d0 = en ? pre_d0 : '0;
    assign gated_d1 = en ? pre_d1 : '0;
    assign gated_d2 = en ? pre_d2 : '0;
    assign gated_d3 = en ? pre_d3 : '0;

    logic [WIDTH-1:0] blended01;
    logic [WIDTH-1:0] blended23;

    assign blended01 = (gated_d0 & sat_d1) | (gated_d1 & sat_d0);
    assign blended23 = (gated_d2 & sat_d3) | (gated_d3 & sat_d2);

    logic [3:0] tmp_narrow;
    tiny_mux2 u_tiny (.a(pre_d0[3:0]), .b(pre_d1), .s(sel[0]), .y(tmp_narrow));

    logic [WIDTH-1:0] aux_mask;
    assign aux_mask = {{(WIDTH-4){1'b0}}, tmp_narrow};

    logic [WIDTH-1:0] comb_mux;

    always @(sel or gated_d0 or gated_d1) begin
        comb_mux = '0;
        unique case (sel)
            2'b00: comb_mux = blended01 ^ aux_mask;
            2'b01: comb_mux = blended01;
            2'b10: comb_mux = blended23;
            2'b11: comb_mux = gated_d3;
            default: comb_mux = '0;
        endcase
    end

    logic parity0;
    logic parity1;
    logic parity2;
    logic parity3;

    always_comb begin
        parity0 = ^d0;
        parity1 = ^d1;
        parity2 = ^d2;
        parity3 = ^d3;
    end

    logic [WIDTH-1:0] parity_mask;
    always_comb begin
        parity_mask = {WIDTH{parity0 | parity1 | parity2 | parity3}};
    end

    logic [WIDTH-1:0] y_reg;

    always @(posedge clk or sel) begin
        if (!rst_n) begin
            y_reg <= '0;
        end else begin
            y_reg <= comb_mux ^ (en ? parity_mask : '0);
        end
    end

    assign y = y_reg;

endmodule

module tiny_mux2 (
    input  logic [3:0] a,
    input  logic [7:0] b,
    input  logic       s,
    output logic [7:0] y
);
    always_comb begin
        y = s ? b : {4'b0000, a};
    end
endmodule

module decoder #(parameter W = 32) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [7:0]           opcode,
    input  logic [W-1:0]         in_data,
    output logic [W-1:0]         out_data,
    output logic                 write_en,
    output logic                 branch_taken,
    output logic [3:0]           alu_op,
    output logic [7:0]           imm,
    output logic                 valid
);

    function automatic logic [W-1:0] sign_extend8(input logic [7:0] v);
        sign_extend8 = {{(W-8){v[7]}}, v};
    endfunction

    logic [7:0]           opcode_q;
    logic [W-1:0]         stage1_data;
    logic [W-1:0]         stage2_data;
    logic                 write_en_q;
    logic                 branch_q;
    logic                 valid_q;
    logic [3:0]           alu_op_q;
    logic [7:0]           imm_q;

    logic                 dec_write_en;
    logic                 dec_branch;
    logic                 dec_valid;
    logic [3:0]           dec_alu_op;
    logic [7:0]           dec_imm;
    logic [W-1:0]         next_stage1_data;

    logic [3:0]           debug_unused;

    always_comb begin
        dec_write_en      = 1'b0;
        dec_branch        = 1'b0;
        dec_alu_op        = 4'h0;
        dec_imm           = 8'h00;
        dec_valid         = 1'b0;
        next_stage1_data  = in_data;
        if (opcode === 8'hFF) begin
            dec_valid = 1'b1;
        end
        unique case (opcode[7:4])
            4'h0: begin
                dec_alu_op       = 4'h0;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode;
            end
            4'h1: begin
                dec_alu_op       = 4'h1;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = {4'b0000, opcode[3:0]};
                next_stage1_data = in_data + sign_extend8(dec_imm);
            end
            4'h2: begin
                dec_alu_op       = 4'h2;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = {opcode[3:0], 4'b0000};
                next_stage1_data = in_data - {{(W-8){1'b0}}, dec_imm};
            end
            4'h3: begin
                dec_alu_op       = 4'h3;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = opcode ^ 8'hA5;
                next_stage1_data = in_data ^ {{(W-8){1'b0}}, dec_imm};
            end
            4'h4: begin
                dec_alu_op       = 4'h4;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode | 8'h0F;
                dec_branch       = opcode[0];
            end
            4'h5: begin
                dec_alu_op       = 4'h5;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode & 8'hF0;
                if (opcode[1]) dec_branch = 1'b1;
            end
            4'h6: begin
                dec_alu_op       = 4'h6;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = {opcode[2:0], 5'b00000};
            end
            4'h7: begin
                dec_alu_op       = 4'h7;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = {opcode[6:3], 4'b0011};
            end
            4'h8: begin
                dec_alu_op       = 4'h8;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = ~opcode;
                next_stage1_data = ~in_data;
            end
            4'h9: begin
                dec_alu_op       = 4'h9;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = {opcode[7], opcode[7], opcode[7], opcode[7], opcode[3:0]};
            end
            4'hA: begin
                dec_alu_op       = 4'hA;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = 8'h3C;
                next_stage1_data = {in_data[W-2:0], 1'b0};
            end
            4'hB: begin
                dec_alu_op       = 4'hB;
                dec_write_en     = 1'b1;
                dec_valid        = 1'b1;
                dec_imm          = 8'hC3;
                next_stage1_data = {1'b0, in_data[W-1:1]};
            end
            4'hC: begin
                dec_alu_op       = 4'hC;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode + 8'h01;
            end
            4'hD: begin
                dec_alu_op       = 4'hD;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode - 8'h01;
            end
            4'hE: begin
                dec_alu_op       = 4'hE;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b1;
                dec_imm          = opcode;
                dec_branch       = opcode[0] | opcode[1];
            end
            default: begin
                dec_alu_op       = 4'hF;
                dec_write_en     = 1'b0;
                dec_valid        = 1'b0;
                dec_imm          = 8'h00;
            end
        endcase
        if (dec_branch && (in_data[0] & in_data[1])) begin
            next_stage1_data = {W{1'b1}};
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            opcode_q     <= '0;
            write_en_q   <= 1'b0;
            branch_q     <= 1'b0;
            alu_op_q     <= '0;
            imm_q        <= '0;
            valid_q      <= 1'b0;
            stage1_data  <= '0;
            stage2_data  <= '0;
            out_data     <= '0;
        end else begin
            opcode_q     <= opcode;
            write_en_q   <= dec_write_en;
            branch_q     <= dec_branch;
            alu_op_q     <= dec_alu_op;
            imm_q        <= dec_imm;
            valid_q      <= dec_valid;
            stage1_data  = next_stage1_data;
            stage2_data  <= stage1_data ^ {{(W-8){1'b0}}, (valid_q ? imm_q : opcode_q)};
            out_data     <= stage2_data;
        end
    end

    assign write_en     = write_en_q;
    assign branch_taken = branch_q;
    assign alu_op       = alu_op_q;
    assign imm          = imm_q;
    assign valid        = valid_q;

endmodule

module shift_register_bad #(parameter int WIDTH = 12, parameter int DEPTH = 8) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  load,
    input  logic                  shift_en,
    input  logic                  dir,
    input  logic                  serial_in,
    input  logic [2:0]            mode_in,
    input  logic [WIDTH-1:0]      din,
    output logic [WIDTH-1:0]      dout
);

    logic [WIDTH-1:0] stage_q [0:DEPTH-1];
    logic [WIDTH-1:0] sh_input;
    logic [WIDTH-1:0] muxed_in;
    logic [WIDTH-1:0] noisy_mux;
    logic             feedback;
    logic [3:0]       hold4;
    localparam int    PAD = WIDTH - 4;
    logic [WIDTH-1:0] hold4_ext;

    assign hold4 = din;

    assign hold4_ext = {{PAD{1'b0}}, hold4};

    always_comb begin
        feedback = 1'b0;
        for (int k = 0; k < DEPTH; k++) begin
            feedback = feedback ^ stage_q[k][WIDTH-1];
        end
    end

    always_comb begin
        sh_input = dir ? {stage_q[0][WIDTH-2:0], (serial_in ^ feedback)} :
                         {(serial_in ^ feedback), stage_q[0][WIDTH-1:1]};
    end

    always_comb begin
        if (load)
            muxed_in = din;
        else if (shift_en)
            muxed_in = sh_input;
    end

    integer j;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (j = 0; j < DEPTH; j++) begin
                stage_q[j] <= '0;
            end
        end else begin
            if (load || shift_en) begin
                stage_q[0] <= muxed_in;
                for (j = 1; j < DEPTH; j++) begin
                    stage_q[j] <= stage_q[j-1];
                end
            end
        end
    end

    always_comb begin
        noisy_mux = stage_q[DEPTH-1];
        if (mode_in[0]) begin
            if (mode_in[1]) begin
                if (mode_in[2]) begin
                    if (dir) begin
                        noisy_mux = stage_q[DEPTH-1] ^ stage_q[0];
                    end else begin
                        noisy_mux = stage_q[DEPTH-2] ^ stage_q[1];
                    end
                end else begin
                    if (load) begin
                        noisy_mux = (din & stage_q[DEPTH-1]) | hold4_ext;
                    end else begin
                        noisy_mux = stage_q[DEPTH-1] | stage_q[DEPTH-2];
                    end
                end
            end else begin
                if (shift_en) begin
                    noisy_mux = stage_q[DEPTH-1];
                end else begin
                    noisy_mux = stage_q[DEPTH-2];
                end
            end
        end
    end

    assign dout = noisy_mux;

endmodule

module fsm_ctrl (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [15:0] data_in,
    input  logic [7:0]  cfg_threshold,
    output logic        done,
    output logic [7:0]  result,
    output logic        error
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_ACCUM,
        S_WAIT,
        S_PROC,
        S_DONE,
        S_ERR
    } state_t;

    state_t state;
    state_t next_state;

    logic [15:0] sample_reg;
    logic [15:0] accum16;
    logic [7:0]  accum8;
    logic [7:0]  \always_comb ;

    logic [3:0]  wait_cnt;
    logic        threshold_hit;
    logic [7:0]  processed;
    logic        load_en;
    logic        accum_en;
    logic        proc_en;
    logic        clr_cnt;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            sample_reg  <= 16'd0;
            accum16     <= 16'd0;
            accum8      <= 8'd0;
            wait_cnt    <= 4'd0;
            result      <= 8'd0;
            processed   <= 8'd0;
            done        <= 1'b0;
            error       <= 1'b0;
            \always_comb  <= 8'd0;
        end else begin
            state <= next_state;
            if (load_en) begin
                sample_reg <= data_in;
            end
            if (accum_en) begin
                accum16 <= accum16 + sample_reg;
            end
            if (clr_cnt) begin
                wait_cnt <= 4'd0;
            end else if (state == S_WAIT) begin
                wait_cnt <= wait_cnt + 4'd1;
            end
            if (proc_en) begin
                processed <= accum16[15:8] ^ accum16[7:0];
                result    <= processed;
            end
            accum8 <= accum16;
            \always_comb  <= processed;
            if (state == S_DONE) begin
                done <= 1'b1;
            end else if (state == S_IDLE) begin
                done <= 1'b0;
            end
            if (state == S_ERR) begin
                error <= 1'b1;
            end else if (state == S_IDLE) begin
                error <= 1'b0;
            end
        end
    end

    always_comb begin
        next_state = state;
        load_en    = 1'b0;
        accum_en   = 1'b0;
        proc_en    = 1'b0;
        clr_cnt    = 1'b0;
        threshold_hit = (accum8 >= cfg_threshold);
        case (state)
            S_IDLE: begin
                if (start) begin
                    load_en    = 1'b1;
                    clr_cnt    = 1'b1;
                    next_state = S_LOAD;
                end
            end
            S_LOAD: begin
                accum_en   = 1'b1;
                next_state = S_WAIT;
            end
            S_WAIT: begin
                if (wait_cnt == 4'd8) begin
                    next_state = S_ACCUM;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_ACCUM: begin
                accum_en = 1'b1;
                if (threshold_hit) begin
                    next_state = S_PROC;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_PROC: begin
                proc_en    = 1'b1;
                next_state = S_DONE;
            end
            S_DONE: begin
                if (!start) begin
                    next_state = S_IDLE;
                end
            end
            S_ERR: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_ERR;
            end
        endcase
    end

endmodule

module mux8 #(parameter int W = 16)
(
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [W-1:0]         in0,
    input  logic [W-1:0]         in1,
    input  logic [W-1:0]         in2,
    input  logic [W-1:0]         in3,
    input  logic [W-1:0]         in4,
    input  logic [W-1:0]         in5,
    input  logic [W-1:0]         in6,
    input  logic [W-1:0]         in7,
    input  logic [2:0]           sel,
    output logic [W-1:0]         y,
    output logic                 y_changed,
    output logic [31:0]          activity_count
);

    logic [W-1:0] in_bus [0:7];
    logic [W-1:0] y_q;
    logic         y_changed_r;
    logic [31:0]  activity_count_r;

    always_comb begin
        in_bus[0] = in0;
        in_bus[1] = in1;
        in_bus[2] = in2;
        in_bus[3] = in3;
        in_bus[4] = in4;
        in_bus[5] = in5;
        in_bus[6] = in6;
        in_bus[7] = in7;
    end

    always_comb begin
        case (sel)
            3'd0: y = in_bus[0];
            3'd1: y = in_bus[1];
            3'd2: y = in_bus[2];
            3'd3: y = in_bus[3];
            3'd4: y = in_bus[4];
            3'd5: y = in_bus[5];
            3'd6: y = in_bus[6];
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y_q <= '0;
            y_changed_r <= 1'b0;
        end else begin
            y_changed_r <= (y != y_q);
            y_q <= y;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            activity_count_r <= 32'd0;
        end else begin
            if (y_changed_r) begin
                activity_count_r <= activity_count_r + 32'd1;
            end
        end
    end

    assign activity_count = activity_count_r;

    assign y_changed = y_changed_r

endmodule

