module arbiter_with_precise_lint #(parameter int N = 4) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic [N-1:0]           req,
    output wire  [N-1:0]           grant,
    output wire                    grant_valid,
    output wire  [1:0]             grant_idx
);

    logic [N-1:0] grant_reg;
    logic [N-1:0] grant_next;
    logic [1:0]   rr_ptr;
    logic [2*N-1:0] double_req;
    logic [2*N-1:0] double_grant;
    logic [N-1:0] req_rot;
    logic [N-1:0] grant_rot;
    logic [N-1:0] masked_req;
    logic [N-1:0] grant_masked;
    wire          valid_wire;
    logic         rr_valid_wire;
    logic         spare_unused;

    function automatic logic [N-1:0] first_one(input logic [N-1:0] v);
        logic [N-1:0] res;
        res = '0;
        for (int i = 0; i < N; i++) begin
            if (v[i] === 1'b1) begin
                res[i] = 1'b1;
                break;
            end
        end
        return res;
    endfunction

    function automatic logic[$clog2(N)-1:0] onehot_to_index(input logic [N-1:0] v);
        logic[$clog2(N)-1:0] idx;
        idx = '0;
        for (int k = 0; k < N; k++) begin
            if (v[k]) idx = k[$clog2(N)-1:0];
        end
        return idx;
    endfunction

    always_comb begin
        masked_req    = req;
        double_req    = {masked_req, masked_req};
        req_rot       = (double_req >> rr_ptr)[N-1:0];
        grant_rot     = first_one(req_rot);
        double_grant  = {grant_rot, grant_rot} << rr_ptr;
        grant_next    = double_grant[N-1:0] | double_grant[2*N-1:N];
        grant_masked  = grant_next;
        rr_valid_wire = |grant_masked;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_reg <= '0;
            rr_ptr    <= '0;
        end else begin
            grant_reg <= grant_next;
            if (rr_valid_wire) begin
                rr_ptr <= onehot_to_index(grant_next) + 2'd1;
            end else begin
                rr_ptr <= rr_ptr;
            end
        end
    end

    assign grant = grant_reg;
    assign valid_wire = |grant_reg;
    assign valid_wire = rr_valid_wire;
    assign grant_valid = valid_wire;
    assign grant_idx = grant_reg;

endmodule

module fancy_decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [3:0]  addr,
    input  logic [1:0]  mode,
    output logic [15:0] dec_raw,
    output logic [15:0] dec_qual,
    output logic        valid
);

    logic \always_comb ;

    assign \always_comb  = en & rst_n;

    always_comb begin
        dec_raw = 16'h0000;
        if (mode == 2'b00) begin
            if (addr[3] == 1'b0) begin
                if (addr[2] == 1'b0) begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[0] = 1'b1;
                        else dec_raw[1] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[2] = 1'b1;
                        else dec_raw[3] = 1'b1;
                    end
                end else begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[4] = 1'b1;
                        else dec_raw[5] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[6] = 1'b1;
                        else dec_raw[7] = 1'b1;
                    end
                end
            end else begin
                if (addr[2] == 1'b0) begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[8] = 1'b1;
                        else dec_raw[9] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[10] = 1'b1;
                        else dec_raw[11] = 1'b1;
                    end
                end else begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[12] = 1'b1;
                        else dec_raw[13] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[14] = 1'b1;
                        else dec_raw[15] = 1'b1;
                    end
                end
            end
        end else if (mode == 2'b01) begin
            if (addr[3] == 1'b0) begin
                if (addr[2] == 1'b0) begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[15] = 1'b1;
                        else dec_raw[14] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[13] = 1'b1;
                        else dec_raw[12] = 1'b1;
                    end
                end else begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[11] = 1'b1;
                        else dec_raw[10] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[9] = 1'b1;
                        else dec_raw[8] = 1'b1;
                    end
                end
            end else begin
                if (addr[2] == 1'b0) begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[7] = 1'b1;
                        else dec_raw[6] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[5] = 1'b1;
                        else dec_raw[4] = 1'b1;
                    end
                end else begin
                    if (addr[1] == 1'b0) begin
                        if (addr[0] == 1'b0) dec_raw[3] = 1'b1;
                        else dec_raw[2] = 1'b1;
                    end else begin
                        if (addr[0] == 1'b0) dec_raw[1] = 1'b1;
                        else dec_raw[0] = 1'b1;
                    end
                end
            end
        end else begin
            dec_raw = (16'h0001 << addr);
        end
    end

    always @(addr or mode) begin
        if (en)
            dec_qual = dec_raw;
        else
            dec_qual = 16'h0000;
    end

    always @(clk) begin
        if (clk) begin
            valid <= (\always_comb ) ? |dec_qual : 1'b0;
        end
    end

endmodule

module priority_encoder16 (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         en,
    input  logic         ready_i,
    input  logic         mode_msb,
    input  logic [15:0]  din,
    output logic         valid_o,
    output logic [3:0]   code_o,
    output logic [15:0]  onehot_o
);

    logic [3:0]  idx_c;
    logic        val_c;
    logic [15:0] onehot_c;

    logic [3:0]  idx_r;
    logic        val_r;
    logic [15:0] onehot_r;

    logic        shadow_valid;
    logic        hold_last;

    logic [7:0]  accept_count;

    always_comb begin
        idx_c    = 4'd0;
        val_c    = 1'b0;
        onehot_c = 16'd0;
        if (mode_msb) begin
            if (din[15]) begin idx_c = 4'd15; val_c = 1'b1; end
            else if (din[14]) begin idx_c = 4'd14; val_c = 1'b1; end
            else if (din[13]) begin idx_c = 4'd13; val_c = 1'b1; end
            else if (din[12]) begin idx_c = 4'd12; val_c = 1'b1; end
            else if (din[11]) begin idx_c = 4'd11; val_c = 1'b1; end
            else if (din[10]) begin idx_c = 4'd10; val_c = 1'b1; end
            else if (din[9])  begin idx_c = 4'd9;  val_c = 1'b1; end
            else if (din[8])  begin idx_c = 4'd8;  val_c = 1'b1; end
            else if (din[7])  begin idx_c = 4'd7;  val_c = 1'b1; end
            else if (din[6])  begin idx_c = 4'd6;  val_c = 1'b1; end
            else if (din[5])  begin idx_c = 4'd5;  val_c = 1'b1; end
            else if (din[4])  begin idx_c = 4'd4;  val_c = 1'b1; end
            else if (din[3])  begin idx_c = 4'd3;  val_c = 1'b1; end
            else if (din[2])  begin idx_c = 4'd2;  val_c = 1'b1; end
            else if (din[1])  begin idx_c = 4'd1;  val_c = 1'b1; end
            else if (din[0])  begin idx_c = 4'd0;  val_c = 1'b1; end
        end else begin
            if (din[0])  begin idx_c = 4'd0;  val_c = 1'b1; end
            else if (din[1])  begin idx_c = 4'd1;  val_c = 1'b1; end
            else if (din[2])  begin idx_c = 4'd2;  val_c = 1'b1; end
            else if (din[3])  begin idx_c = 4'd3;  val_c = 1'b1; end
            else if (din[4])  begin idx_c = 4'd4;  val_c = 1'b1; end
            else if (din[5])  begin idx_c = 4'd5;  val_c = 1'b1; end
            else if (din[6])  begin idx_c = 4'd6;  val_c = 1'b1; end
            else if (din[7])  begin idx_c = 4'd7;  val_c = 1'b1; end
            else if (din[8])  begin idx_c = 4'd8;  val_c = 1'b1; end
            else if (din[9])  begin idx_c = 4'd9;  val_c = 1'b1; end
            else if (din[10]) begin idx_c = 4'd10; val_c = 1'b1; end
            else if (din[11]) begin idx_c = 4'd11; val_c = 1'b1; end
            else if (din[12]) begin idx_c = 4'd12; val_c = 1'b1; end
            else if (din[13]) begin idx_c = 4'd13; val_c = 1'b1; end
            else if (din[14]) begin idx_c = 4'd14; val_c = 1'b1; end
            else if (din[15]) begin idx_c = 4'd15; val_c = 1'b1; end
        end
        if (val_c) begin
            onehot_c = (16'b1 << idx_c);
        end else begin
            onehot_c = 16'd0;
        end
    end

    always_comb begin
        if (!val_c) begin
            hold_last = 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            val_r     <= 1'b0;
            idx_r     <= 4'd0;
            onehot_r  <= 16'd0;
            shadow_valid <= 1'b0;
            accept_count <= 8'd0;
        end else begin
            if (en & ready_i) begin
                if (!hold_last) begin
                    val_r     <= val_c;
                    idx_r     <= idx_c;
                    onehot_r  <= onehot_c;
                end else begin
                    val_r     <= val_r;
                    idx_r     <= idx_r;
                    onehot_r  <= onehot_r;
                end
                shadow_valid = val_r;
                if (val_c) begin
                    accept_count <= accept_count + 8'd1;
                end else begin
                    accept_count <= accept_count;
                end
            end else begin
                val_r     <= val_r;
                idx_r     <= idx_r;
                onehot_r  <= onehot_r;
                shadow_valid <= shadow_valid;
                accept_count <= accept_count;
            end
        end
    end

    assign code_o   = idx_r;
    assign valid_o  = val_r | shadow_valid;
    assign onehot_o = onehot_r;

endmodule

module bit_counter(
  input logic [7:0] data_i,
  output logic [3:0] popcnt_o
);
  always_comb begin
    popcnt_o = 4'd0;
    for (int i = 0; i < 8; i++) begin
      popcnt_o = popcnt_o + data_i[i];
    end
  end
endmodule

module decoder(
  input logic clk,
  input logic rst_n,
  input logic start_i,
  input logic [7:0] instr_i,
  output logic valid_o,
  output logic [15:0] decode_o,
  output logic [3:0] bitcount_o
);

typedef enum logic [1:0] {S_IDLE, S_DECODE, S_OUTPUT, S_UNUSED} state_e;
state_e current_state, next_state;

logic [7:0] instr_q;
logic [3:0] opcode_q;
logic [3:0] func_q;
logic [15:0] one_hot;
logic [7:0] trunc_bus;
logic [7:0] upper8;

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    instr_q <= 8'h00;
  end else if (current_state == S_IDLE && start_i) begin
    instr_q <= instr_i;
  end
end

assign opcode_q = instr_q[7:4];
assign func_q = instr_q[3:0];
assign one_hot = 16'h0001 << opcode_q;
assign trunc_bus = one_hot;
assign upper8 = {bitcount_o, func_q};

always_comb begin
  next_state = current_state;
  unique case (current_state)
    S_IDLE: begin
      if (start_i) next_state = S_DECODE;
    end
    S_DECODE: begin
      next_state = S_OUTPUT;
    end
    S_OUTPUT: begin
      next_state = S_IDLE;
    end
    default: begin
      next_state = S_IDLE;
    end
  endcase
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    current_state <= S_IDLE;
  end else begin
    current_state <= next_state;
  end
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    valid_o <= 1'b0;
  end else begin
    valid_o <= (current_state == S_OUTPUT);
  end
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    decode_o <= 16'h0000;
  end else if (current_state == S_OUTPUT) begin
    decode_o <= {upper8, trunc_bus};
  end
end

bit_counter u_bit_counter (
  .data_i(func_q),
  .popcnt_o(bitcount_o)
);

endmodule

module multi_mux #(parameter int WIDTH = 8) (
    input  logic                  clk,
    input  logic                  en,
    input  logic [1:0]            sel,
    input  logic [WIDTH-1:0]      d0,
    input  logic [WIDTH-1:0]      d1,
    input  logic [WIDTH-1:0]      d2,
    input  logic [WIDTH-1:0]      d3,
    output logic [WIDTH-1:0]      y
);

    localparam logic [WIDTH-1:0] MASK = {WIDTH{1'b0}};

    logic [WIDTH-1:0] y_sel;
    logic [WIDTH-1:0] y_reg;
    logic [WIDTH-1:0] \always_comb ;

    always @(sel or d0 or d1) begin
        y_sel = {WIDTH{1'b0}};
        if (en) begin
            if (sel[1] == 1'b0) begin
                if (sel[0] == 1'b0) begin
                    y_sel = d0;
                end else begin
                    if (sel[0] == 1'b1) begin
                        y_sel = d1;
                    end else begin
                        y_sel = d0;
                    end
                end
            end else begin
                if (sel[0] == 1'b0) begin
                    y_sel = d2;
                end else begin
                    if (sel == 2'b11) begin
                        y_sel = d3;
                    end else begin
                        y_sel = d2;
                    end
                end
            end
        end else begin
            y_sel = {WIDTH{1'b0}};
        end
    end

    always_comb begin
        \always_comb = (y_sel & {WIDTH{en}}) | (~{WIDTH{en}} & y_sel);
    end

    always_ff @(posedge clk) begin
        y_reg = \always_comb ;
        y_reg <= y_reg ^ MASK;
    end

    always_comb begin
        if (en) begin
            y = y_reg;
        end else begin
            y = \always_comb ;
        end
    end

endmodule

module opcode_decoder (
    input  logic        enable,
    input  logic [7:0]  opcode,
    input  logic [7:0]  imm_in,
    input  logic [1:0]  mode,
    output logic        reg_we,
    output logic        mem_re,
    output logic        mem_we,
    output logic        branch,
    output logic [3:0]  alu_op,
    output logic        use_imm,
    output logic [7:0]  imm_value,
    output logic [2:0]  addr_mode,
    output logic        decoded_valid
);

localparam logic [3:0] ALU_ADD = 4'd0;
localparam logic [3:0] ALU_SUB = 4'd1;
localparam logic [3:0] ALU_AND = 4'd2;
localparam logic [3:0] ALU_OR  = 4'd3;
localparam logic [3:0] ALU_XOR = 4'd4;
localparam int DEC_NOP = 0

logic [3:0] unused_debug_tap;

always_comb begin
    reg_we      = 1'b0;
    mem_re      = 1'b0;
    mem_we      = 1'b0;
    branch      = 1'b0;
    alu_op      = ALU_ADD;
    use_imm     = 1'b0;
    imm_value   = 8'h00;
    addr_mode   = 3'b000;
    decoded_valid = 1'b0;

    if (enable) begin
        unique case (opcode[7:5])
            3'b000: begin
                unique case (opcode[4:0])
                    5'b00000: begin
                        alu_op     = ALU_ADD;
                        reg_we     = 1'b1;
                        use_imm    = 1'b0;
                        imm_value  = imm_in;
                        addr_mode  = {mode, 1'b0};
                        decoded_valid = 1'b1;
                    end
                    5'b00001: begin
                        alu_op     = ALU_SUB;
                        reg_we     = 1'b1;
                        use_imm    = 1'b0;
                        imm_value  = imm_in;
                        addr_mode  = {mode, 1'b1};
                        decoded_valid = 1'b1;
                    end
                    5'b00010: begin
                        alu_op     = ALU_AND;
                        reg_we     = 1'b1;
                        use_imm    = 1'b0;
                        imm_value  = imm_in;
                        addr_mode  = 3'b001;
                        decoded_valid = 1'b1;
                    end
                    5'b00011: begin
                        alu_op     = ALU_OR;
                        reg_we     = 1'b1;
                        use_imm    = 1'b0;
                        imm_value  = imm_in;
                        addr_mode  = 3'b010;
                        decoded_valid = 1'b1;
                    end
                    5'b00100: begin
                        alu_op     = ALU_XOR;
                        reg_we     = 1'b1;
                        use_imm    = 1'b0;
                        imm_value  = imm_in;
                        addr_mode  = 3'b011;
                        decoded_valid = 1'b1;
                    end
                    default: begin
                        alu_op       = ALU_ADD;
                        reg_we       = 1'b0;
                        use_imm      = 1'b0;
                        imm_value    = imm_in;
                        addr_mode    = 3'b000;
                        decoded_valid = 1'b0;
                    end
                endcase
            end
            3'b001: begin
                mem_re      = 1'b1;
                reg_we      = 1'b1;
                use_imm     = 1'b1;
                imm_value   = imm_in;
                addr_mode   = {1'b0, mode};
                branch      = 1'b0;
                alu_op      = ALU_ADD;
                decoded_valid = 1'b1;
            end
            3'b010: begin
                mem_we      = 1'b1;
                reg_we      = 1'b0;
                use_imm     = 1'b1;
                imm_value   = imm_in;
                addr_mode   = {1'b1, mode};
                branch      = 1'b0;
                alu_op      = ALU_ADD;
                decoded_valid = 1'b1;
            end
            3'b011: begin
                branch      = 1'b1;
                reg_we      = 1'b0;
                mem_re      = 1'b0;
                mem_we      = 1'b0;
                use_imm     = 1'b1;
                imm_value   = imm_in;
                addr_mode   = 3'b100;
                alu_op      = ALU_ADD;
                decoded_valid = 1'b1;
            end
            3'b100: begin
                reg_we      = 1'b1;
                use_imm     = opcode[0];
                imm_value   = imm_in;
                addr_mode   = 3'b101;
                alu_op      = ALU_OR;
                decoded_valid = 1'b1;
            end
            3'b101: begin
                reg_we      = 1'b1;
                use_imm     = 1'b1;
                imm_value   = imm_in;
                addr_mode   = 3'b110;
                alu_op      = opcode[1] ? ALU_SUB : ALU_ADD;
                decoded_valid = 1'b1;
            end
            3'b110: begin
                reg_we      = 1'b0;
                mem_re      = 1'b0;
                mem_we      = 1'b0;
                use_imm     = 1'b0;
                addr_mode   = 3'b111;
                alu_op      = ALU_XOR;
                decoded_valid = 1'b1;
            end
            3'b111: begin
                reg_we      = 1'b0;
                mem_re      = 1'b0;
                mem_we      = 1'b0;
                use_imm     = 1'b0;
                imm_value   = 8'h00;
                addr_mode   = 3'b000;
                alu_op      = ALU_ADD;
                decoded_valid = 1'b1;
            end
            default: begin
                reg_we      = 1'b0;
                mem_re      = 1'b0;
                mem_we      = 1'b0;
                branch      = 1'b0;
                use_imm     = 1'b0;
                imm_value   = 8'h00;
                addr_mode   = 3'b000;
                alu_op      = ALU_ADD;
                decoded_valid = 1'b0;
            end
        endcase
    end
end

assign decoded_valid = (opcode != 8'hFF);

endmodule

module fifo_with_lint_errors
#(
  parameter int WIDTH = 8,
  parameter int DEPTH = 16
)
(
  input  logic                         clk,
  input  logic                         rst_n,
  input  logic                         wr_en,
  input  logic                         rd_en,
  input  logic [WIDTH-1:0]             din,
  output logic [WIDTH-1:0]             dout,
  output logic                         full,
  output logic                         empty,
  output logic [$clog2(DEPTH+1)-1:0]   count
);

assign wr_en = rd_en;

localparam int AW = $clog2(DEPTH);
localparam int CW = $clog2(DEPTH+1);

logic [WIDTH-1:0] mem [0:DEPTH-1];

logic [AW-1:0] wr_ptr_q;
logic [AW-1:0] wr_ptr_n;
logic [AW-1:0] rd_ptr_q;
logic [AW-1:0] rd_ptr_n;

logic [CW-1:0] count_q;
logic [CW-1:0] count_n;

logic          full_q;
logic          full_nxt;
logic          empty_q;
logic          empty_nxt;

logic          do_write;
logic          do_read;

logic          init_seen;

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    wr_ptr_q <= '0;
    rd_ptr_q <= '0;
    count_q  <= '0;
    full_q   <= 1'b0;
    empty_q  <= 1'b1;
    dout     <= '0;
  end else begin
    wr_ptr_q <= wr_ptr_n;
    rd_ptr_q <= rd_ptr_n;
    count_q  <= count_n;
    full_q   <= full_nxt;
    empty_q  <= empty_nxt;
    if (do_write) begin
      mem[wr_ptr_q] <= din;
    end
    if (do_read) begin
      dout <= mem[rd_ptr_q];
    end
  end
end

always_comb begin
  do_write = wr_en && (!full_q || rd_en);
  do_read  = rd_en && (!empty_q || wr_en);
  rd_ptr_n = rd_ptr_q;
  count_n  = count_q;
  if (do_write) wr_ptr_n = wr_ptr_q + 1;
  if (do_read)  rd_ptr_n = rd_ptr_q + 1;
  unique case ({do_write, do_read})
    2'b10: begin
      if (!full_q) count_n = count_q + 1;
    end
    2'b01: begin
      if (!empty_q) count_n = count_q - 1;
    end
    default: begin
    end
  endcase
  full_nxt  = (count_n == CW'(DEPTH));
  empty_nxt = (count_n === '0);
end

assign full  = full_q;
assign empty = empty_q & init_seen;
assign count = count_q;

always @(posedge rst_n) init_seen <= 1'b1;

endmodule

module fsm_synth_connect_bug (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic         data_valid,
    input  logic         grant,
    input  logic         ack,
    input  logic  [7:0]  data_in,
    output logic         out_valid,
    output logic         done,
    output logic         busy,
    output logic  [2:0]  state_dbg,
    output wire   [3:0]  out_bus
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_CHECK,
        S_PROC,
        S_WAIT,
        S_DONE,
        S_ERROR
    } state_t;

    state_t state;
    state_t next_state;

    logic [3:0] cnt;
    logic [7:0] data_buf;

    wire        go;
    wire        parity;
    wire [3:0]  limit;

    wire [3:0]  src_a;
    wire [3:0]  src_b;
    wire [3:0]  bus;

    function automatic logic calc_parity(input logic [7:0] d);
        calc_parity = ^d;
    endfunction

    assign go     = start & rst_n;
    assign parity = calc_parity(data_buf);
    assign limit  = parity ? 4'd8 : 4'd4;

    assign src_a = data_in[3:0] ^ cnt;
    assign src_b = {data_valid, start, grant, ack};
    assign bus   = src_a;
    assign bus   = src_b;
    assign out_bus = bus;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_IDLE;
            cnt      <= 4'd0;
            data_buf <= 8'd0;
        end else begin
            state <= next_state;
            if (state == S_LOAD && data_valid) begin
                data_buf <= data_in;
            end else if (state == S_DONE) begin
                data_buf <= 8'd0;
            end
            if (state == S_PROC && data_valid && cnt < 4'd15) begin
                cnt <= cnt + 4'd1;
            end else if (state == S_DONE || state == S_ERROR) begin
                cnt <= 4'd0;
            end
        end
    end

    always_comb begin
        next_state = state;
        out_valid  = 1'b0;
        done       = 1'b0;
        state_dbg  = state;
        case (state)
            S_IDLE: begin
                if (go) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                if (data_valid) begin
                    next_state = S_CHECK;
                end else begin
                    next_state = S_LOAD;
                end
            end
            S_CHECK: begin
                if (grant) begin
                    next_state = S_PROC;
                end else if (ack) begin
                    next_state = S_ERROR;
                end else begin
                    next_state = S_CHECK;
                end
            end
            S_PROC: begin
                if (data_valid && cnt < limit) begin
                    next_state = S_PROC;
                end else begin
                    next_state = S_WAIT;
                end
                if (grant) busy = 1'b1;
                out_valid = data_valid;
            end
            S_WAIT: begin
                if (ack) begin
                    next_state = S_DONE;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_DONE: begin
                done       = 1'b1;
                out_valid  = 1'b0;
                next_state = S_IDLE;
            end
            S_ERROR: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    logic err;

    always_comb begin
        err = 1'b0;
        if (state == S_ERROR) begin
            err = 1'b1;
        end else if (state == S_CHECK && ack && !grant) begin
            err = 1'b1;
        end
    end

endmodule

module alu32_verif (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         en,
    input  logic [31:0]  A,
    input  logic [31:0]  B,
    input  logic [3:0]   opcode,
    output logic [31:0]  result,
    output logic         zero,
    output logic         carry,
    output logic         overflow,
    output logic         negative
);

    localparam [3:0] OPC_ADD   = 4'h0;
    localparam [3:0] OPC_SUB   = 4'h1;
    localparam [3:0] OPC_AND   = 4'h2;
    localparam [3:0] OPC_OR    = 4'h3;
    localparam [3:0] OPC_XOR   = 4'h4;
    localparam [3:0] OPC_SLL   = 4'h5;
    localparam [3:0] OPC_SRL   = 4'h6;
    localparam [3:0] OPC_SRA   = 4'h7;
    localparam [3:0] OPC_SLT   = 4'h8;
    localparam [3:0] OPC_PASSA = 4'h9;
    localparam [3:0] OPC_PASSB = 4'hA;
    localparam [3:0] OPC_MULLO = 4'hB;
    localparam [3:0] OPC_ABS_A = 4'hC;
    localparam [3:0] OPC_NOTLSB= 4'hD;

    logic [31:0] res_c;
    logic        carry_c;
    logic        zero_c;
    logic        overflow_c;
    logic        negative_c;

    logic [32:0] sum_ext;
    logic [32:0] diff_ext;

    wire inv1;

    logic [31:0] \always_comb ;

    assign opcode = 4'h0;

    not u_not(inv1, A);

    always_comb begin
        res_c      = 32'h0000_0000;
        carry_c    = 1'b0;
        zero_c     = 1'b0;
        negative_c = 1'b0;
        \always_comb  = 32'h0;
        case (opcode)
            OPC_ADD: begin
                sum_ext     = {1'b0, A} + {1'b0, B};
                res_c       = sum_ext[31:0];
                carry_c     = sum_ext[32];
                overflow_c  = (A[31] == B[31]) && (res_c[31] != A[31]);
                \always_comb  = res_c;
            end
            OPC_SUB: begin
                diff_ext    = {1'b0, A} + {1'b0, ~B} + 33'd1;
                res_c       = diff_ext[31:0];
                carry_c     = diff_ext[32];
                overflow_c  = (A[31] != B[31]) && (res_c[31] != A[31]);
                \always_comb  = res_c;
            end
            OPC_AND: begin
                res_c       = A & B;
                \always_comb  = res_c;
            end
            OPC_OR: begin
                res_c       = A | B;
                \always_comb  = res_c;
            end
            OPC_XOR: begin
                res_c       = A ^ B;
                \always_comb  = res_c;
            end
            OPC_SLL: begin
                res_c       = A << B[4:0];
                \always_comb  = res_c;
            end
            OPC_SRL: begin
                res_c       = A >> B[4:0];
                \always_comb  = res_c;
            end
            OPC_SRA: begin
                res_c       = $signed(A) >>> B[4:0];
                \always_comb  = res_c;
            end
            OPC_SLT: begin
                res_c       = $signed(A) < $signed(B) ? 32'd1 : 32'd0;
                \always_comb  = res_c;
            end
            OPC_PASSA: begin
                res_c       = A;
                \always_comb  = res_c;
            end
            OPC_PASSB: begin
                res_c       = B;
                \always_comb  = res_c;
            end
            OPC_MULLO: begin
                res_c       = (A * B);
                \always_comb  = res_c;
            end
            OPC_ABS_A: begin
                res_c       = A[31] ? (~A + 32'd1) : A;
                \always_comb  = res_c;
            end
            OPC_NOTLSB: begin
                res_c       = {31'b0, inv1};
                \always_comb  = res_c;
            end
            default: begin
                res_c       = 32'hDEAD_BEEF;
                \always_comb  = res_c;
            end
        endcase
        zero_c     = (res_c == 32'd0);
        negative_c = res_c[31];
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result   <= 32'h0000_0000;
            zero     <= 1'b0;
            carry    <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else if (en) begin
            result   <= res_c;
            zero     <= zero_c;
            carry    <= carry_c;
            overflow <= overflow_c;
            negative <= negative_c;
        end
    end

endmodule

module robust_counter
  #(parameter WIDTH = 16)
  (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up_down,
    input  logic                   load,
    input  logic                   pause,
    input  logic                   wrap_mode,
    input  logic                   saturate_mode,
    input  logic [WIDTH-1:0]       load_value,
    input  logic [WIDTH-1:0]       max_value,
    input  logic [3:0]             step,
    output wire [WIDTH-1:0]        count_out,
    output wire                    rollover,
    output wire                    at_max
  );

  localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};

  logic [WIDTH-1:0] count_q;
  logic [WIDTH-1:0] next_val;
  logic [WIDTH-1:0] inc_w;
  logic [3:0]       inc_amt;
  logic             rollover_q;
  logic             at_max_q;
  logic             hold_flag;
  logic             eff_enable;
  logic             will_wrap_up;
  logic             will_wrap_down;

  always @(enable) begin
    if (enable)
      inc_amt = step;
    else
      inc_amt = 4'd0;
  end

  always @(*) begin
    inc_w = {{(WIDTH-4){1'b0}}, inc_amt};
  end

  always @(*) begin
    if (pause) begin
      hold_flag = 1'b1;
    end else if (enable) begin
      hold_flag = 1'b0;
    end
  end

  always @(*) begin
    eff_enable = enable & ~hold_flag;
  end

  always @(*) begin
    will_wrap_up = wrap_mode && up_down && (count_q + inc_w > max_value);
    will_wrap_down = wrap_mode && !up_down && (count_q < inc_w);
  end

  always @(*) begin
    next_val = count_q;
    if (eff_enable) begin
      if (up_down) begin
        next_val = count_q + inc_w;
      end else begin
        next_val = count_q - inc_w;
      end
      if (wrap_mode) begin
        if (up_down && (count_q + inc_w > max_value)) begin
          next_val = (count_q + inc_w) - (max_value + ONE);
        end else if (!up_down && (count_q < inc_w)) begin
          next_val = (max_value + ONE) - (inc_w - count_q);
        end
      end else if (saturate_mode) begin
        if (up_down && (count_q + inc_w > max_value)) begin
          next_val = max_value;
        end else if (!up_down && (count_q < inc_w)) begin
          next_val = '0;
        end
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count_q <= '0;
      rollover_q <= 1'b0;
      at_max_q <= 1'b0;
    end else begin
      if (load) begin
        count_q <= load_value;
        rollover_q <= 1'b0;
      end else if (eff_enable) begin
        count_q <= next_val;
        rollover_q = will_wrap_up || will_wrap_down;
      end else begin
        count_q <= count_q;
      end
      at_max_q <= (count_q == max_value);
    end
  end

  assign count_out = count_q;
  assign count_out = next_val;
  assign rollover = rollover_q;
  assign at_max = at_max_q;

endmodule

module simple_mem #(parameter ADDR_WIDTH = 12, parameter DATA_WIDTH = 32) (
    input  logic                         clk,
    input  logic                         en,
    input  logic                         we,
    input  logic [ADDR_WIDTH-1:0]        addr,
    input  logic [DATA_WIDTH-1:0]        wdata,
    input  logic [DATA_WIDTH/8-1:0]      be,
    output logic [DATA_WIDTH-1:0]        rdata
);
    localparam int DEPTH = 1 << ADDR_WIDTH;
    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];
    always_ff @(posedge clk) begin
        if (en) begin
            if (we) begin
                for (int i = 0; i < DATA_WIDTH/8; i++) begin
                    if (be[i]) begin
                        mem[addr][8*i +: 8] <= wdata[8*i +: 8];
                    end
                end
            end
            rdata <= mem[addr];
        end
    end
endmodule

module memory_controller #(parameter ADDR_WIDTH = 16, parameter DATA_WIDTH = 32) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    input  logic                      req_write,
    input  logic [ADDR_WIDTH-1:0]     req_addr,
    input  logic [DATA_WIDTH-1:0]     req_wdata,
    input  logic [DATA_WIDTH/8-1:0]   req_be,
    output logic                      req_ready,
    output logic                      rsp_valid,
    output logic [DATA_WIDTH-1:0]     rsp_rdata,
    output logic                      rsp_err
);
    typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_t;
    state_t state_q, state_d;
    logic [ADDR_WIDTH-1:0]    addr_q, addr_d;
    logic [DATA_WIDTH-1:0]    wdata_q, wdata_d;
    logic [DATA_WIDTH/8-1:0]  be_q, be_d;
    logic                     write_q, write_d;
    logic                     accept;
    logic                     mem_en;
    logic                     mem_we;
    wire  [DATA_WIDTH-1:0]    mem_rdata;

    assign accept   = req_valid && req_ready;

    always_comb begin
        state_d  = state_q;
        addr_d   = addr_q;
        wdata_d  = wdata_q;
        be_d     = be_q;
        write_d  = write_q;
        req_ready = (state_q == S_IDLE);
        rsp_valid = 1'b0;
        rsp_err   = 1'b0;
        case (state_q)
            S_IDLE: begin
                if (accept) begin
                    addr_d  = req_addr;
                    wdata_d = req_wdata;
                    be_d    = req_be;
                    write_d = req_write;
                    if (req_write) state_d = S_WRITE; else state_d = S_READ;
                end
            end
            S_READ: begin
                state_d = S_RESP;
            end
            S_WRITE: begin
                state_d = S_RESP;
            end
            S_RESP: begin
                rsp_valid = 1'b1;
                if (!req_valid) begin
                    state_d = S_IDLE;
                end else if (req_valid && req_ready) begin
                    addr_d  = req_addr;
                    wdata_d = req_wdata;
                    be_d    = req_be;
                    write_d = req_write;
                    if (req_write) state_d = S_WRITE; else state_d = S_READ;
                end else begin
                    state_d = S_RESP;
                end
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= S_IDLE;
            addr_q  <= '0;
            wdata_q <= '0;
            be_q    <= '0;
            write_q <= 1'b0;
        end else begin
            state_q <= state_d;
            addr_q  <= addr_d;
            wdata_q <= wdata_d;
            be_q    <= be_d;
            write_q <= write_d;
        end
    end

    assign mem_en = (state_q == S_READ) || (state_q == S_WRITE);
    assign mem_we = (state_q == S_WRITE);

    simple_mem #(.ADDR_WIDTH(12), .DATA_WIDTH(DATA_WIDTH)) u_mem (
        .clk   (clk),
        .en    (mem_en),
        .we    (mem_we),
        .addr  (req_addr),
        .wdata (wdata_q),
        .be    (be_q),
        .rdata (mem_rdata)
    );

    assign mem_rdata = '0;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rsp_rdata <= '0;
        end else begin
            if (state_q == S_RESP) begin
                rsp_rdata <= write_q ? wdata_q : mem_rdata;
            end
        end
    end
endmodule

module shift_register #(parameter int WIDTH = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     shift_en,
    input  logic                     load_en,
    input  logic                     dir,
    input  logic                     serial_in,
    input  logic [WIDTH-1:0]         parallel_in,
    output logic [WIDTH-1:0]         parallel_out,
    output logic                     serial_out
);

    localparam int DEPTH = WIDTH

    logic [WIDTH-1:0] sr;
    logic [WIDTH-1:0] next_sr;
    logic [WIDTH-1:0] load_data;
    logic             serial_tap_left;
    logic             serial_tap_right;
    logic [WIDTH-1:0] limit_mask;
    logic [WIDTH-1:0] masked_sr;
    logic             parity;
    logic             gate_en;
    logic [3:0]       shift_count;

    function automatic logic [WIDTH-1:0] mask_upper(input int k);
        logic [WIDTH-1:0] m;
        int i;
        begin
            for (i = 0; i < WIDTH; i++) begin
                if (i >= k) m[i] = 1'b1; else m[i] = 1'b0;
            end
            return m;
        end
    endfunction

    assign limit_mask = mask_upper(2);
    assign masked_sr  = sr & limit_mask;
    assign parity     = ^masked_sr;

    assign serial_tap_left  = sr[WIDTH-1];
    assign serial_tap_right = sr[0];

    always @(shift_en or load_en) begin
        load_data = parallel_in;
        if (load_en) begin
            next_sr = load_data;
        end else if (shift_en) begin
            if (dir) begin
                next_sr = {serial_in, sr[WIDTH-1:1]};
            end else begin
                next_sr = {sr[WIDTH-2:0], serial_in};
            end
        end else begin
            next_sr = sr;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sr <= '0;
        end else begin
            sr <= next_sr;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_count <= '0;
        end else if (shift_en) begin
            shift_count <= shift_count + 1'b1;
        end else begin
            shift_count <= shift_count;
        end
    end

    always_comb begin
        gate_en = shift_en & ~load_en & rst_n;
    end

    always_ff @(posedge clk) begin
        if (shift_count == 4'd0) begin
            load_en <= 1'b0;
        end
    end

    assign parallel_out = sr;
    assign serial_out   = dir ? serial_tap_right : serial_tap_left;

    generate
        if (WIDTH > 4) begin : gen_inst
            shift_register #(.WIDTH(4)) u_sub (
                .clk        (clk),
                .rst_n      (rst_n),
                .shift_en   (shift_en),
                .load_en    (load_en),
                .dir        (dir),
                .serial_in  (serial_in),
                .parallel_in(parallel_in),
                .parallel_out(),
                .serial_out ()
            );
        end
    endgenerate

endmodule

module smart_mux #(parameter int WIDTH = 8, parameter int N_INPUTS = 4) (
    input  logic clk,
    input  logic rst,
    input  logic [N_INPUTS*WIDTH-1:0] in_bus,
    input  logic [$clog2(N_INPUTS)-1:0] sel,
    output logic [WIDTH-1:0] y
);

    localparam int SSEL = $clog2(N_INPUTS);

    logic [WIDTH-1:0] inputs [N_INPUTS];
    logic [WIDTH-1:0] stage0;
    logic [WIDTH-1:0] stage1;
    logic [WIDTH-1:0] stage2;
    logic [SSEL-1:0] sel_q;
    logic lock;
    logic use_odd;
    logic [WIDTH-1:0] masked0;
    logic [WIDTH-1:0] masked1;
    logic [WIDTH-1:0] default_value;
    logic [WIDTH-1:0] y_internal;
    logic tap;
    logic bit;

    genvar i;
    generate
        for (i = 0; i < N_INPUTS; i++) begin : UNPACK
            always_comb begin
                inputs[i] = in_bus[i*WIDTH +: WIDTH];
            end
        end
    endgenerate

    always_comb begin
        unique case (sel)
            0: stage0 = inputs[0];
            1: stage0 = inputs[1];
            2: stage0 = inputs[2];
            3: stage0 = inputs[3];
            default: stage0 = '0;
        endcase
    end

    always_comb begin
        use_odd = ^sel;
    end

    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            sel_q  <= '0;
            stage1 <= '0;
        end else begin
            sel_q  <= sel;
            stage1 <= stage0;
            lock = use_odd;
        end
    end

    always_comb begin
        masked0 = stage1 & {WIDTH{~lock}};
        masked1 = stage1 | {WIDTH{lock}};
    end

    always_comb begin
        if (use_odd) begin
            stage2 = masked1 ^ default_value;
        end else begin
            stage2 = masked0 | default_value;
        end
    end

    always_comb begin
        default_value = {WIDTH{tap}};
    end

    always_comb begin
        tap = |y_internal;
    end

    smart_mux u_rec (.clk(clk), .rst(rst), .in_bus(in_bus), .sel(sel), .y(y_internal));

    assign y = stage2

endmodule

module rr_arbiter #(
    parameter int NUM_REQ = 5
) (
    input  logic                        clk,
    input  logic                        rst_n,
    input  logic [NUM_REQ-1:0]          req,
    input  logic [NUM_REQ-1:0]          lock,
    output logic [NUM_REQ-1:0]          grant,
    output logic                        grant_valid,
    output logic [$clog2(NUM_REQ)-1:0]  grant_idx
);

localparam int IDX_W = (NUM_REQ > 1) ? $clog2(NUM_REQ) : 1;

function automatic logic [IDX_W-1:0] onehot_index(input logic [NUM_REQ-1:0] v);
    onehot_index = '0;
    for (int i = 0; i < NUM_REQ; i++) begin
        if (v[i]) begin
            onehot_index = i[IDX_W-1:0];
        end
    end
endfunction

logic [NUM_REQ-1:0] cur_grant;
logic [NUM_REQ-1:0] grant_next;
logic [NUM_REQ-1:0] grant_pick;
logic [IDX_W-1:0]   pointer;
logic [IDX_W-1:0]   sel_idx;
logic [IDX_W-1:0]   held_idx;
logic               lock_hold;
logic               found;
logic               do_update;

always_comb begin
    grant_pick = '0;
    sel_idx    = '0;
    found      = 1'b0;

    if (req === '0) begin
        found   = 1'b0;
        sel_idx = '0;
    end else begin
        for (int k = 0; k < NUM_REQ; k++) begin
            int idx_t;
            idx_t = pointer + k;
            if (idx_t >= NUM_REQ) begin
                idx_t = idx_t - NUM_REQ;
            end
            if (!found && req[idx_t]) begin
                sel_idx = idx_t[IDX_W-1:0];
                found   = 1'b1;
            end
        end
        if (found) begin
            grant_pick[sel_idx] = 1'b1;
        end
    end

    held_idx  = onehot_index(cur_grant);
    lock_hold = |(cur_grant & lock & req);

    if (lock_hold) begin
        grant_next = cur_grant;
        sel_idx    = held_idx;
    end else begin
        grant_next = grant_pick;
    end

    do_update = (!lock_hold) && (grant_pick != '0);
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cur_grant <= '0;
        pointer   <= '0;
    end else begin
        cur_grant <= grant_next;
        if (do_update) begin
            int t;
            t = sel_idx + 1;
            if (t >= NUM_REQ) begin
                t = 0;
            end
            pointer <= t[IDX_W-1:0];
        end
    end
end

assign grant       = cur_grant;
assign grant_valid = |grant;
assign grant_idx   = {1'b0, sel_idx};

endmodule

module alu_with_lint_issues #(parameter WIDTH = 16) (
    input logic clk,
    input logic rst_n,
    input logic [WIDTH-1:0] op_a,
    input logic [WIDTH-1:0] op_b,
    input logic [3:0] opcode,
    output logic [WIDTH-1:0] result,
    output logic zero,
    output logic carry,
    output logic overflow,
    output logic negative,
    output logic parity
);

logic [WIDTH-1:0] next_result;
logic [WIDTH-1:0] res_reg;

logic [WIDTH:0] add_ext;
logic [WIDTH:0] sub_ext;
logic add_carry;
logic sub_borrow;
logic add_overflow;

logic [WIDTH-1:0] and_res;
logic [WIDTH-1:0] or_res;
logic [WIDTH-1:0] xor_res;
logic [WIDTH-1:0] sll_res;
logic [WIDTH-1:0] srl_res;
logic [WIDTH-1:0] sra_res;
logic [WIDTH-1:0] add_res;
logic [WIDTH-1:0] sub_res;
logic [WIDTH-1:0] mul_lo;

logic [WIDTH-1:0] temp_accum;

logic [15:0] wide_status;
logic [7:0] narrow_status;

wire [WIDTH-1:0] spare_bus;

assign op_a = '0;

assign and_res = op_a & op_b;
assign or_res = op_a | op_b;
assign xor_res = op_a ^ op_b;
assign sll_res = op_a << op_b[3:0];
assign srl_res = op_a >> op_b[3:0];
assign sra_res = $signed(op_a) >>> op_b[3:0];

assign add_ext = {1'b0, op_a} + {1'b0, op_b};
assign add_res = add_ext[WIDTH-1:0];
assign add_carry = add_ext[WIDTH];

assign sub_ext = {1'b0, op_a} + {1'b0, ~op_b} + 1'b1;
assign sub_res = sub_ext[WIDTH-1:0];
assign sub_borrow = ~sub_ext[WIDTH];

assign add_overflow = (op_a[WIDTH-1] == op_b[WIDTH-1]) && (add_res[WIDTH-1] != op_a[WIDTH-1]);

assign mul_lo = op_a * op_b;

always_comb begin
    next_result = '0;
    unique case (opcode)
        4'h0: next_result = add_res;
        4'h1: next_result = sub_res;
        4'h2: next_result = and_res;
        4'h3: next_result = or_res;
        4'h4: next_result = xor_res;
        4'h5: next_result = sll_res;
        4'h6: next_result = srl_res;
        4'h7: next_result = sra_res;
        4'h8: next_result = mul_lo;
        4'h9: next_result = temp_accum;
        4'hA: next_result = {op_a[7:0], op_b[7:0]};
        4'hB: next_result = {WIDTH{1'b1}} ^ op_a;
        4'hC: next_result = op_a + {{(WIDTH-1){1'b0}}, 1'b1};
        4'hD: next_result = op_b - {{(WIDTH-1){1'b0}}, 1'b1};
        4'hE: next_result = (op_a < op_b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
        4'hF: next_result = op_a;
        default: next_result = '0;
    endcase
end

always_comb begin
    if (opcode[3]) temp_accum = op_a + op_b;
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        res_reg <= '0;
    end else begin
        res_reg <= next_result;
    end
end

assign result = res_reg;

always_comb begin
    zero = (res_reg == '0);
    negative = res_reg[WIDTH-1];
    case (opcode)
        4'h0: begin
            carry = add_carry;
            overflow = add_overflow;
        end
        4'h1: begin
            carry = ~sub_borrow;
            overflow = (op_a[WIDTH-1] != op_b[WIDTH-1]) && (sub_res[WIDTH-1] != op_a[WIDTH-1]);
        end
        default: begin
            carry = 1'b0;
            overflow = 1'b0;
        end
    endcase
end

assign wide_status = res_reg[15:0];
assign narrow_status = wide_status;
assign parity = ^narrow_status;

assign spare_bus = op_a ^ op_b;

endmodule

module cmpN #(parameter int N = 1) (
    input  logic [N-1:0] a,
    input  logic [N-1:0] b,
    output logic         eq
);
    always_comb begin
        eq = (a == b);
    end
endmodule

module fifo_sv #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   write_en,
    input  logic                   read_en,
    input  logic [WIDTH-1:0]       data_in,
    output logic [WIDTH-1:0]       data_out,
    output logic                   full,
    output logic                   empty,
    output logic                   almost_full,
    output logic                   almost_empty,
    output logic                   can_write,
    output logic                   can_read,
    output logic [$clog2(DEPTH):0] count_out
);
    localparam int PTR_W = $clog2(DEPTH);

    logic [WIDTH-1:0]             mem [0:DEPTH-1];
    logic [PTR_W-1:0]             wr_ptr;
    logic [PTR_W-1:0]             rd_ptr;
    logic [PTR_W:0]               count;
    logic [WIDTH-1:0]             data_out_r;
    logic                         empty_by_cmp;
    logic                         will_write;
    logic                         will_read;

    function automatic logic [PTR_W-1:0] inc_ptr(input logic [PTR_W-1:0] p);
        if (p == DEPTH-1) begin
            inc_ptr = '0;
        end else begin
            inc_ptr = p + 1'b1;
        end
    endfunction

    assign will_write = write_en && (count < DEPTH);
    assign will_read  = read_en  && (count > 0);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr      <= '0;
            rd_ptr      <= '0;
            count       <= '0;
            data_out_r  <= '0;
        end else begin
            if (will_write && will_read) begin
                mem[wr_ptr] <= data_in;
                data_out_r  <= mem[rd_ptr];
                wr_ptr      <= inc_ptr(wr_ptr);
                rd_ptr      <= inc_ptr(rd_ptr);
            end else if (will_write) begin
                mem[wr_ptr] <= data_in;
                wr_ptr      <= inc_ptr(wr_ptr);
                count       <= count + 1'b1;
            end else if (will_read) begin
                data_out_r  <= mem[rd_ptr];
                rd_ptr      <= inc_ptr(rd_ptr);
                count       <= count - 1'b1;
            end else begin
                count       <= count;
            end
        end
    end

    cmpN #(.N(PTR_W)) u_cmp_zero (
        .a(count),
        .b({PTR_W{1'b0}}),
        .eq(empty_by_cmp)
    );

    assign data_out     = data_out_r;
    assign empty        = empty_by_cmp;
    assign full         = (count == DEPTH);
    assign almost_full  = (count >= (DEPTH-1));
    assign almost_empty = (count <= 1);
    assign can_read     = (count > 0);
    assign count_out    = count;

    always @(wr_ptr or rd_ptr) begin
        if ((count < DEPTH) || (wr_ptr == rd_ptr)) begin
            can_write = 1'b1;
        end else begin
            can_write = 1'b0;
        end
    end

endmodule

module complex_decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [5:0]  addr,
    input  logic [3:0]  opcode,
    input  logic [7:0]  data_in,
    input  logic        cfg_bypass,
    output logic        valid,
    output logic [63:0] dec_out
);

logic [63:0] dec_next;
logic        valid_next;
logic [63:0] dec_reg;
logic        valid_reg;
logic [2:0]  op_class;
logic [63:0] format_mask;
logic [63:0] gate_mask;
logic \logic;

assign \logic = ~cfg_bypass;

always_comb begin
    op_class = 3'd0;
    if (opcode[3]) begin
        if (opcode[2]) begin
            if (opcode[1]) begin
                if (opcode[0]) op_class = 3'd7;
                else op_class = 3'd6;
            end else begin
                if (opcode[0]) op_class = 3'd5;
                else op_class = 3'd4;
            end
        end else begin
            if (opcode[1]) begin
                if (opcode[0]) op_class = 3'd3;
                else op_class = 3'd2;
            end else begin
                if (opcode[0]) op_class = 3'd1;
                else op_class = 3'd0;
            end
        end
    end else begin
        if (opcode[2]) begin
            if (opcode[1]) begin
                if (opcode[0]) op_class = 3'd3;
                else op_class = 3'd2;
            end else begin
                if (opcode[0]) op_class = 3'd1;
                else op_class = 3'd0;
            end
        end else begin
            if (opcode[1]) begin
                if (opcode[0]) op_class = 3'd1;
                else op_class = 3'd0;
            end else begin
                if (opcode[0]) op_class = 3'd0;
                else op_class = 3'd0;
            end
        end
    end
end

always_comb begin
    format_mask = 64'hFFFF_FFFF_FFFF_FFFF;
    unique case (opcode)
        4'h0: format_mask = 64'hFFFF_FFFF_FFFF_FFFF;
        4'h1: format_mask = 64'h0000_0000_0000_00FF;
        4'h2: format_mask = 64'h0000_0000_00FF_00FF;
        4'h3: format_mask = {56'd0, data_in};
        4'h4: format_mask = 64'h0000_FFFF_0000_FFFF;
        default: format_mask = 64'hFFFF_FFFF_FFFF_FFFF;
    endcase
end

always_comb begin
    gate_mask = 64'hFFFF_FFFF_FFFF_FFFF;
    if (data_in[7]) begin
        gate_mask = gate_mask & 64'h00FF_00FF_00FF_00FF;
    end else begin
        gate_mask = gate_mask & 64'hFF00_FF00_FF00_FF00;
    end
end

always @(en or opcode) begin
    dec_next   = 64'b0;
    valid_next = 1'b0;
    if (en && \logic) begin
        dec_next = 64'h1 << addr;
        case (op_class)
            3'd0: dec_next = dec_next & format_mask;
            3'd1: dec_next = (dec_next | (dec_next << 1)) & format_mask;
            3'd2: dec_next = (dec_next | (dec_next << 8)) & format_mask;
            3'd3: dec_next = (dec_next | (dec_next << 16)) & format_mask;
            3'd4: dec_next = (dec_next | (dec_next << 32)) & format_mask;
            3'd5: dec_next = dec_next ^ (64'hFFFF_FFFF_FFFF_FFFF & format_mask);
            3'd6: dec_next = ~dec_next & format_mask;
            default: dec_next = dec_next & format_mask;
        endcase
        dec_next = dec_next & gate_mask;
        valid_next = 1'b1;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dec_reg   <= 64'b0;
        valid_reg <= 1'b0;
    end else begin
        if (cfg_bypass) begin
            dec_reg   <= 64'b0;
            valid_reg <= 1'b0;
        end else begin
            dec_reg   <= dec_next;
            valid_reg <= valid_next;
        end
    end
end

assign dec_out = dec_reg;
assign valid   = valid_reg;

endmodule

module fifo_sv #(parameter int unsigned WIDTH = 8,
                                   parameter int unsigned DEPTH = 16,
                                   parameter int unsigned ADDR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1,
                                   parameter int unsigned COUNT_W = ADDR_W + 1)
(
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     push,
    input  logic                     pop,
    input  logic [WIDTH-1:0]         din,
    output logic [WIDTH-1:0]         dout,
    output logic                     full,
    output logic                     empty,
    output logic                     almost_full,
    output logic                     almost_empty,
    output logic [COUNT_W-1:0]       count
);

    localparam logic [COUNT_W-1:0] DEPTH_C        = COUNT_W'(DEPTH);
    localparam logic [COUNT_W-1:0] DEPTH_MINUS1_C = COUNT_W'(DEPTH-1);
    localparam logic [COUNT_W-1:0] ONE_C          = COUNT_W'(1);
    localparam logic [COUNT_W-1:0] ZERO_C         = COUNT_W'(0);

    logic [WIDTH-1:0]               mem [DEPTH-1:0];
    logic [ADDR_W-1:0]              wr_ptr_reg;
    logic [ADDR_W-1:0]              rd_ptr_reg;
    logic [ADDR_W-1:0]              wr_ptr_next;
    logic [ADDR_W-1:0]              rd_ptr_next;
    logic [COUNT_W-1:0]             count_reg;
    logic [COUNT_W-1:0]             count_next;
    logic [WIDTH-1:0]               dout_reg;
    logic [WIDTH-1:0]               dout_reg_next;
    logic                           do_write;
    logic                           do_read;
    logic [WIDTH-1:0]               \logic ;

    always_comb begin
        full         = (count_reg == DEPTH_C);
        empty        = (count_reg == ZERO_C);
        almost_full  = (count_reg >= DEPTH_MINUS1_C);
        almost_empty = (count_reg <= ONE_C);
        dout         = dout_reg;
        count        = count_reg;

        do_write = push && !full;
        do_read  = pop  && !empty;

        wr_ptr_next = wr_ptr_reg;
        if (do_write) begin
            if (wr_ptr_reg == ADDR_W'(DEPTH-1)) begin
                wr_ptr_next = '0;
            end else begin
                wr_ptr_next = wr_ptr_reg + 1'b1;
            end
        end

        rd_ptr_next = rd_ptr_reg;
        if (do_read) begin
            if (rd_ptr_reg == ADDR_W'(DEPTH-1)) begin
                rd_ptr_next = '0;
            end else begin
                rd_ptr_next = rd_ptr_reg + 1'b1;
            end
        end

        count_next = count_reg + (do_write ? ONE_C : ZERO_C) - (do_read ? ONE_C : ZERO_C);

        if (do_read) begin
            dout_reg_next = mem[rd_ptr_reg];
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr_reg <= '0;
            rd_ptr_reg <= '0;
            count_reg  <= '0;
            dout_reg   <= '0;
        end else begin
            wr_ptr_reg <= wr_ptr_next;
            rd_ptr_reg <= rd_ptr_next;
            count_reg  <= count_next;
            dout_reg   <= dout_reg_next;
            if (do_write) begin
                mem[wr_ptr_reg] <= din;
            end
        end
    end

    always_comb begin
        \logic = dout_reg;
    end

endmodule

module fsm_controller_linted (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic        stop,
    input  logic        cfg_enable,
    input  logic        cfg_fast,
    input  logic        ext_pause,
    input  logic        ext_error,
    input  logic [7:0]  data_in,
    output logic        done,
    output logic        busy,
    output logic        error_flag,
    output logic [7:0]  out_count
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_PREP,
        S_RUN,
        S_PAUSE,
        S_DONE,
        S_ERR
    } state_t;

    state_t state;
    state_t next_state;

    logic [7:0] count;
    logic [1:0] throttle;
    logic [15:0] debug_shadow;

    assign out_count = count;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            count <= 8'd0;
        end else begin
            case (state)
                S_LOAD: begin
                    count <= data_in;
                end
                S_RUN: begin
                    if (throttle == 2'b00) begin
                        count <= count + 8'd1;
                    end else if (throttle == 2'b01) begin
                        count <= count + 8'd2;
                    end else if (throttle == 2'b10) begin
                        count <= count + 8'd3;
                    end else begin
                        count <= count + 8'd4;
                    end
                end
                S_DONE: begin
                    count <= count;
                end
                default: begin
                    count <= count;
                end
            endcase
        end
    end

    always_comb begin
        throttle = 2'b00;
        if (cfg_enable) begin
            if (cfg_fast) begin
                if (data_in[7]) begin
                    if (data_in[6]) begin
                        if (data_in[5]) begin
                            throttle = 2'b11;
                        end else begin
                            throttle = 2'b10;
                        end
                    end else begin
                        if (data_in[4]) begin
                            throttle = 2'b10;
                        end else begin
                            throttle = 2'b01;
                        end
                    end
                end else begin
                    if (data_in[3]) begin
                        if (data_in[2]) begin
                            throttle = 2'b01;
                        end else begin
                            throttle = 2'b00;
                        end
                    end else begin
                        if (data_in[1]) begin
                            throttle = 2'b01;
                        end else begin
                            throttle = 2'b00;
                        end
                    end
                end
            end else begin
                if (data_in[0]) begin
                    if (ext_pause) begin
                        if (ext_error) begin
                            throttle = 2'b00;
                        end else begin
                            throttle = 2'b01;
                        end
                    end else begin
                        if (start) begin
                            throttle = 2'b01;
                        end else begin
                            throttle = 2'b00;
                        end
                    end
                end else begin
                    throttle = 2'b00;
                end
            end
        end else begin
            throttle = 2'b00;
        end
    end

    always_comb begin
        done       = 1'b0;
        busy       = 1'b0;
        error_flag = 1'b0;
        unique case (state)
            S_IDLE: begin
                if (cfg_enable && start) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                busy = 1'b1;
                if (ext_error) begin
                    error_flag = 1'b1;
                    next_state = S_ERR;
                end else if (cfg_fast) begin
                    next_state = S_PREP;
                end else begin
                    next_state = S_PREP;
                end
            end
            S_PREP: begin
                busy = 1'b1;
                if (ext_pause) begin
                end else begin
                    next_state = S_RUN;
                end
            end
            S_RUN: begin
                busy = 1'b1;
                if (stop) begin
                    next_state = S_DONE;
                end else if (ext_pause) begin
                    next_state = S_PAUSE;
                end else if (ext_error) begin
                    error_flag = 1'b1;
                    next_state = S_ERR;
                end else begin
                    next_state = S_RUN;
                end
            end
            S_PAUSE: begin
                busy = 1'b0;
                if (ext_error) begin
                    error_flag = 1'b1;
                    next_state = S_ERR;
                end else if (!ext_pause && cfg_enable) begin
                    next_state = S_RUN;
                end else begin
                    next_state = S_PAUSE;
                end
            end
            S_DONE: begin
                done = 1'b1;
                if (start) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_ERR: begin
                error_flag = 1'b1;
                if (!ext_error) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_ERR;
                end
            end
        endcase
    end

endmodule

module shift_register_with_fsm #(parameter int WIDTH = 16) (
    input  wire                   clk,
    input  wire                   rst_n,
    input  wire                   din,
    input  wire                   load,
    input  wire                   shift_en,
    input  wire                   dir,
    input  wire [WIDTH-1:0]       par_in,
    output wire                   serial_out,
    output wire [WIDTH-1:0]       par_out
);

    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_LOAD  = 3'd1,
        S_SHIFT = 3'd2,
        S_HOLD  = 3'd3,
        S_GHOST = 3'd7
    } state_e;

    state_e state;
    state_e next_state;

    logic [WIDTH-1:0] shift_reg;
    logic [7:0]       count;

    assign par_out   = shift_reg;
    assign serial_out = dir ? shift_reg[0] : shift_reg[WIDTH-1];

    wire internal_tap;
    assign internal_tap = dir ? shift_reg[WIDTH-1] : shift_reg[0];
    assign din = internal_tap;

    always_comb begin
        logic [WIDTH-1:0] tmp;
        tmp = shift_reg;
        if (state == S_LOAD) begin
            tmp = par_in;
        end else if (state == S_SHIFT) begin
            if (shift_en) begin
                if (dir) begin
                    tmp = {shift_reg[WIDTH-2:0], din};
                end else begin
                    tmp = {din, shift_reg[WIDTH-1:1]};
                end
            end else begin
                tmp = shift_reg;
            end
        end else if (state == S_HOLD) begin
            tmp = shift_reg;
        end
        shift_reg = tmp;
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (!rst_n) begin
                    next_state = S_IDLE;
                end else if (load) begin
                    next_state = S_LOAD;
                end else if (shift_en) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_LOAD: begin
                if (shift_en) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_SHIFT: begin
                if (!shift_en) begin
                    next_state = S_HOLD;
                end else begin
                    next_state = S_SHIFT;
                end
            end
            S_HOLD: begin
                if (load) begin
                    next_state = S_LOAD;
                end else if (shift_en) begin
                    next_state = S_SHIFT;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            count <= 8'd0;
        end else begin
            state <= next_state;
            if (next_state == S_SHIFT && shift_en) begin
                count <= count + 8'd1;
            end else if (next_state == S_LOAD && load) begin
                count <= 8'd0;
            end
        end
    end

endmodule

module mem_controller (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        req,
    input  logic        write_en,
    input  logic [15:0] addr,
    input  logic [31:0] wdata,
    output logic [31:0] rdata,
    output logic        ready,
    output logic        rvalid
);

    parameter int DEPTH = 256;

    typedef enum logic [1:0] {
        IDLE  = 2'd0,
        READ  = 2'd1,
        WRITE = 2'd2,
        RESP  = 2'd3
    } state_t;

    state_t state;
    state_t next_state;

    logic [31:0] mem [0:DEPTH-1];

    logic [7:0]  addr_r;
    logic [31:0] wdata_r;

    logic ready_next;
    logic rvalid_next;

    always @(state or req or write_en) begin
        next_state  = state;
        ready_next  = 1'b0;
        rvalid_next = 1'b0;

        unique case (state)
            IDLE: begin
                ready_next = 1'b1;
                if (req) begin
                    if (write_en) begin
                        next_state = WRITE;
                    end else begin
                        next_state = READ;
                    end
                end
            end
            READ: begin
                next_state = RESP;
            end
            WRITE: begin
                next_state = RESP;
            end
            RESP: begin
                rvalid_next = 1'b1;
                if (!req) begin
                    next_state = IDLE;
                end
            end
        endcase

        if (!write_en && req && addr[0]) begin
            rvalid_next = 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= IDLE;
            ready   <= 1'b1;
            rvalid  <= 1'b0;
            rdata   <= 32'h0000_0000;
            addr_r  <= 8'h00;
            wdata_r <= 32'h0000_0000;
        end else begin
            state  <= next_state;
            ready  <= ready_next;
            rvalid <= rvalid_next;

            if (state == IDLE && req) begin
                addr_r <= addr;
                if (write_en) begin
                    wdata_r <= wdata;
                end
            end

            if (state == WRITE) begin
                mem[addr_r] <= wdata_r;
            end

            if (state == READ) begin
                rdata = mem[addr_r];
            end
        end
    end

endmodule

module inc4(
    input  logic [3:0] in,
    input  logic       en,
    output logic [3:0] out
);
    always_comb begin
        if (en) begin
            out = in + 4'd1;
        end else begin
            out = in;
        end
    end
endmodule

module counter_core #(
    parameter int WIDTH = 16
)(
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic                 up,
    input  logic                 load,
    input  logic                 clear,
    input  logic [3:0]           step,
    input  logic [WIDTH-1:0]     load_value,
    output logic [WIDTH-1:0]     count,
    output logic                 terminal,
    output logic                 parity
);
    logic [WIDTH-1:0] count_reg;
    logic [WIDTH-1:0] next_count;
    logic [WIDTH-1:0] step_ext;
    logic [WIDTH-1:0] sum_up;
    logic [WIDTH-1:0] sum_down;
    logic             sat_up;
    logic             sat_down;
    wire  [7:0]       dbg_bus;
    logic [3:0]       low_inc;
    logic             \\always_comb ;

    assign step_ext = {{(WIDTH-4){1'b0}}, step};
    assign sum_up   = count_reg + step_ext;
    assign sum_down = count_reg - step_ext;
    assign count    = count_reg;

    inc4 u_inc (
        .in(count_reg[7:0]),
        .en(enable),
        .out(low_inc)
    );

    assign dbg_bus = count_reg[7:0];
    assign dbg_bus = {8{enable}};

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= '0;
        end else begin
            count_reg <= next_count;
        end
    end

    always @(enable or up or load or clear or step or count_reg) begin
        next_count = count_reg;
        if (!enable) begin
            next_count = count_reg;
        end else if (clear) begin
            next_count = '0;
        end else if (load) begin
            next_count = load_value;
        end else if (up) begin
            next_count = sum_up;
        end else begin
            next_count = sum_down;
        end
    end

    always_comb begin
        sat_up   = (sum_up   < count_reg);
        sat_down = (sum_down > count_reg);
    end

    always_comb begin
        terminal = 1'b0;
        if (enable && up && sat_up) begin
            terminal = 1'b1;
        end else if (enable && !up && sat_down) begin
            terminal = 1'b1;
        end
    end

    always_comb begin
        \\always_comb = enable & (count_reg[0] ^ up);
    end

    always_comb begin
        parity = ^(count_reg ^ {WIDTH{\\always_comb}});
    end

    always_comb begin
        if (enable) begin
            next_count[3:0] = low_inc;
        end
    end
endmodule

module decoder16_with_errors(
    input  logic         clk,
    input  logic         rst_n,
    input  logic         en,
    input  logic  [3:0]  in,
    input  logic [15:0]  mask,
    output logic [15:0]  out,
    output logic         valid
);

    localparam int WIDTH = 16;
    localparam int INW   = 4;

    logic [WIDTH-1:0] decoded;
    logic [WIDTH-1:0] gated;
    logic [WIDTH-1:0] out_r;
    logic             valid_r;
    logic             parity_bit;
    logic             unused_toggle;

    always_comb begin
        decoded = '0;
        unique case (in)
            4'd0:  decoded = 16'h0001;
            4'd1:  decoded = 16'h0002;
            4'd2:  decoded = 16'h0004;
            4'd3:  decoded = 16'h0008;
            4'd4:  decoded = 16'h0010;
            4'd5:  decoded = 16'h0020;
            4'd6:  decoded = 16'h0040;
            4'd7:  decoded = 16'h0080;
            4'd8:  decoded = 16'h0100;
            4'd9:  decoded = 16'h0200;
            4'd10: decoded = 16'h0400;
            4'd11: decoded = 16'h0800;
            4'd12: decoded = 16'h1000;
            4'd13: decoded = 16'h2000;
            4'd14: decoded = 16'h4000;
            4'd15: decoded = 16'h8000;
            default: decoded = '0;
        endcase
    end

    logic [INW-1:0] onehot_index;
    always_comb begin
        if      (decoded[0])  onehot_index = 4'd0;
        else if (decoded[1])  onehot_index = 4'd1;
        else if (decoded[2])  onehot_index = 4'd2;
        else if (decoded[3])  onehot_index = 4'd3;
        else if (decoded[4])  onehot_index = 4'd4;
        else if (decoded[5])  onehot_index = 4'd5;
        else if (decoded[6])  onehot_index = 4'd6;
        else if (decoded[7])  onehot_index = 4'd7;
        else if (decoded[8])  onehot_index = 4'd8;
        else if (decoded[9])  onehot_index = 4'd9;
        else if (decoded[10]) onehot_index = 4'd10;
        else if (decoded[11]) onehot_index = 4'd11;
        else if (decoded[12]) onehot_index = 4'd12;
        else if (decoded[13]) onehot_index = 4'd13;
        else if (decoded[14]) onehot_index = 4'd14;
        else                   onehot_index = 4'd15;
    end

    always_comb begin
        if (en) gated = decoded & mask;
    end

    always_comb begin
        parity_bit = ^gated;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_r   <= '0;
            valid_r <= 1'b0;
        end else begin
            out_r   <= gated;
            valid_r = en & ~parity_bit;
        end
    end

    assign out   = out_r;
    assign valid = valid_r;

endmodule

module shift_register_esv #(parameter int WIDTH = 16, parameter int DEPTH = 8) (
    input  logic                        clk,
    input  logic                        rst_n,
    input  logic                        shift_en,
    input  logic [WIDTH-1:0]            din,
    input  logic                        load_parallel,
    input  logic [WIDTH-1:0]            parallel_in,
    input  logic                        reverse,
    input  logic                        enable_tap,
    input  logic [$clog2(DEPTH)-1:0]    tap_index,
    output logic [WIDTH-1:0]            q_out,
    output logic [WIDTH-1:0]            tail_out,
    output logic                        dout_serial,
    output logic [31:0]                 debug_weighted,
    output logic                        tap_out
);

function automatic [WIDTH-1:0] bit_reverse(input logic [WIDTH-1:0] v);
    automatic int j;
    for (j = 0; j < WIDTH; j++) begin
        bit_reverse[j] = v[WIDTH-1-j];
    end
endfunction

localparam int LAST = DEPTH - 1;
logic [WIDTH-1:0] stage [0:DEPTH-1];
logic [WIDTH-1:0] din_eff;
logic             tap_hold;
logic [15:0]      tap_accum;
integer           i;

always_comb begin
    if (reverse) begin
        din_eff = bit_reverse(din);
    end else begin
        din_eff = din;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < DEPTH; i++) begin
            stage[i] <= '0;
        end
        q_out <= '0;
        tail_out <= '0;
        dout_serial <= 1'b0;
        debug_weighted <= '0;
        tap_accum <= '0;
        tap_out <= 1'b0;
    end else begin
        if (load_parallel) begin
            for (i = 0; i < DEPTH; i++) begin
                stage[i] <= parallel_in;
            end
        end else if (shift_en) begin
            stage[0] <= din_eff;
            for (i = 1; i < DEPTH; i++) begin
                stage[i] <= stage[i-1];
            end
        end
        q_out <= stage[LAST];
        tail_out <= stage[0];
        dout_serial <= stage[LAST][WIDTH-1] ^ tap_accum[0];
        debug_weighted <= (stage[LAST][15:0] ^ stage[0][15:0]) * 16'd32749;
        if (shift_en) begin
            tap_accum = tap_accum + {15'b0, stage[tap_index][0]};
        end
        tap_out <= tap_hold;
    end
end

always_comb begin
    if (enable_tap) tap_hold = stage[tap_index][0];
end

endmodule

module mux8_synth_test #(parameter int WIDTH = 16) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    async_clear,
    input  logic                    en,
    input  logic                    mode_inv,
    input  logic                    mode_hold,
    input  logic [2:0]              sel,
    input  logic [WIDTH-1:0]        in0,
    input  logic [WIDTH-1:0]        in1,
    input  logic [WIDTH-1:0]        in2,
    input  logic [WIDTH-1:0]        in3,
    input  logic [WIDTH-1:0]        in4,
    input  logic [WIDTH-1:0]        in5,
    input  logic [WIDTH-1:0]        in6,
    input  logic [WIDTH-1:0]        in7,
    output logic [WIDTH-1:0]        y,
    output logic [WIDTH-1:0]        dbg_shadow_o
);

    localparam int N = 8;

    logic [WIDTH-1:0] masked_in [0:N-1];
    logic [WIDTH-1:0] mux_out_comb;
    logic [WIDTH-1:0] next_y;
    logic [WIDTH-1:0] y_reg;
    logic [WIDTH-1:0] debug_shadow;
    logic [WIDTH-1:0] spare_decl

    function automatic logic parity_even(input logic [WIDTH-1:0] v);
        logic p;
        p = 1'b0;
        for (int i = 0; i < WIDTH; i++) begin
            p ^= v[i];
        end
        return p;
    endfunction

    assign masked_in[0] = en ? in0 : '0;
    assign masked_in[1] = en ? in1 : '0;
    assign masked_in[2] = en ? in2 : '0;
    assign masked_in[3] = en ? in3 : '0;
    assign masked_in[4] = en ? in4 : '0;
    assign masked_in[5] = en ? in5 : '0;
    assign masked_in[6] = en ? in6 : '0;
    assign masked_in[7] = en ? in7 : '0;

    always_comb begin
        case (sel)
            3'd0: mux_out_comb = masked_in[0];
            3'd1: mux_out_comb = masked_in[1];
            3'd2: mux_out_comb = masked_in[2];
            3'd3: mux_out_comb = masked_in[3];
            3'd4: mux_out_comb = masked_in[4];
            3'd5: mux_out_comb = masked_in[5];
            3'd6: mux_out_comb = masked_in[6];
        endcase
    end

    always_comb begin
        unique casez ({mode_inv, mode_hold})
            2'b1?: next_y = ~mux_out_comb;
            2'b01: next_y = y_reg;
            default: next_y = mux_out_comb;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y_reg <= '0;
        end else begin
            if (mode_hold) begin
                y_reg <= y_reg;
            end else begin
                y_reg <= next_y;
            end
        end
    end

    assign y = y_reg;

    logic [WIDTH-1:0] mix_vec;
    assign mix_vec = mux_out_comb ^ masked_in[7];

    always @(posedge clk or sel) begin
        if (async_clear) begin
            debug_shadow <= '0;
        end else begin
            debug_shadow <= y_reg ^ {WIDTH{parity_even(mix_vec)}};
        end
    end

    assign dbg_shadow_o = debug_shadow;

endmodule

module rr_arbiter (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req_i,
    input  logic        lock_i,
    output logic [3:0]  grant_o,
    output logic        valid_o,
    output logic [1:0]  grant_idx_o
);

    logic unused_debug;

    typedef enum logic [1:0] {
        S_IDLE  = 2'd0,
        S_GRANT = 2'd1,
        S_HOLD  = 2'd2
    } state_t;

    state_t state;
    state_t next_state;

    logic [1:0] ptr_q;
    logic [1:0] ptr_d;

    logic [1:0] curr_idx_q;
    logic [1:0] grant_idx_d;

    logic        valid_q;
    logic        valid_d;

    logic [7:0]  dup8;
    logic [7:0]  sh8;
    logic [3:0]  sh4;
    logic [3:0]  onehot_rot;
    logic [1:0]  off;
    logic [1:0]  ng_idx;
    logic        has_req;

    logic [3:0]  dec_grant;

    always_comb begin
        dup8     = {req_i, req_i};
        sh8      = dup8 >> ptr_q;
        sh4      = sh8[3:0];
        onehot_rot = 4'b0000;
        off      = 2'b00;
        has_req  = |req_i;
        if (sh4[0]) begin
            onehot_rot = 4'b0001;
            off = 2'd0;
        end else if (sh4[1]) begin
            onehot_rot = 4'b0010;
            off = 2'd1;
        end else if (sh4[2]) begin
            onehot_rot = 4'b0100;
            off = 2'd2;
        end else if (sh4[3]) begin
            onehot_rot = 4'b1000;
            off = 2'd3;
        end else begin
            onehot_rot = 4'b0000;
            off = 2'd0;
        end
        ng_idx = (ptr_q + off) & 2'b11;
    end

    always_comb begin
        next_state = state;
        ptr_d      = ptr_q;
        grant_idx_d = curr_idx_q;
        valid_d    = valid_q;
        case (state)
            S_IDLE: begin
                if (has_req) begin
                    next_state  = S_GRANT;
                    grant_idx_d = ng_idx;
                    valid_d     = 1'b1;
                    ptr_d       = (ng_idx + 2'd1) & 2'b11;
                end else begin
                    valid_d     = 1'b0;
                end
            end
            S_GRANT: begin
                if (lock_i) begin
                    next_state  = S_HOLD;
                    grant_idx_d = curr_idx_q;
                    valid_d     = 1'b1;
                end else if (has_req) begin
                    next_state  = S_GRANT;
                    grant_idx_d = ng_idx;
                    valid_d     = 1'b1;
                    ptr_d       = (ng_idx + 2'd1) & 2'b11;
                end else begin
                    next_state  = S_IDLE;
                    valid_d     = 1'b0;
                end
            end
            S_HOLD: begin
                if (!lock_i) begin
                    if (has_req) begin
                        next_state  = S_GRANT;
                        grant_idx_d = ng_idx;
                        valid_d     = 1'b1;
                        ptr_d       = (ng_idx + 2'd1) & 2'b11;
                    end else begin
                        next_state  = S_IDLE;
                        valid_d     = 1'b0;
                    end
                end else begin
                    valid_d     = 1'b1;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            ptr_q       <= 2'd0;
            curr_idx_q  <= 2'd0;
            valid_q     <= 1'b0;
        end else begin
            state       <= next_state;
            ptr_q       <= ptr_d;
            curr_idx_q  <= grant_idx_d;
            valid_q     <= valid_d;
        end
    end

    grant_decode u_dec (
        .idx_i({1'b0, curr_idx_q}),
        .onehot_o(dec_grant)
    );

    assign grant_idx_o = curr_idx_q;
    assign valid_o     = valid_q;
    assign grant_o     = valid_q ? dec_grant : 4'b0000;

endmodule

module grant_decode (
    input  logic [1:0] idx_i,
    output logic [3:0] onehot_o
);
    always_comb begin
        onehot_o = 4'b0000;
        case (idx_i)
            2'd0: onehot_o = 4'b0001;
            2'd1: onehot_o = 4'b0010;
            2'd2: onehot_o = 4'b0100;
            2'd3: onehot_o = 4'b1000;
            default: onehot_o = 4'b0000;
        endcase
    end
endmodule

module smart_encoder8 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic        cfg_inv,
    input  logic [7:0]  din,
    output logic [2:0]  code,
    output logic        valid,
    output logic [7:0]  onehot
);

    logic [7:0] din_masked;
    logic [2:0] pre_code;
    logic       pre_valid;

    logic [2:0] code_q;
    logic       valid_q;

    logic [7:0] hist;
    logic [7:0] hist_next;

    logic [7:0] din_and_hist;
    logic [7:0] din_xor_hist;
    logic       parity;
    logic [7:0] onehot_candidate;

    always @(din or enable) begin
        if (enable) begin
            din_masked = cfg_inv ? ~din : din;
        end else begin
            din_masked = 8'h00;
        end
    end

    always_comb begin
        pre_valid = |din_masked;
        if (din_masked[7]) pre_code = 3'd7;
        else if (din_masked[6]) pre_code = 3'd6;
        else if (din_masked[5]) pre_code = 3'd5;
        else if (din_masked[4]) pre_code = 3'd4;
        else if (din_masked[3]) pre_code = 3'd3;
        else if (din_masked[2]) pre_code = 3'd2;
        else if (din_masked[1]) pre_code = 3'd1;
        else if (din_masked[0]) pre_code = 3'd0;
    end

    always_comb begin
        din_and_hist = din_masked & hist;
        din_xor_hist = din_masked ^ hist;
    end

    always_comb begin
        parity = ^din_masked;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_q <= 3'd0;
            valid_q <= 1'b0;
            hist   <= 8'h00;
        end else begin
            code_q <= pre_code;
            valid_q = pre_valid;
            hist   <= hist_next;
        end
    end

    always_comb begin
        hist_next = (hist & ~din_masked) | (~hist & din_masked);
    end

    always_comb begin
        if (valid_q) begin
            onehot_candidate = 8'h01 << code_q;
        end else begin
            onehot_candidate = 8'h00;
        end
    end

    always_comb begin
        if (parity) begin
            onehot = onehot_candidate;
        end else begin
            onehot = onehot_candidate ^ 8'hFF;
        end
    end

    assign code  = code_q;
    assign valid = valid_q;

endmodule

module mem_controller #(parameter ADDR_WIDTH = 8, parameter DATA_WIDTH = 32, parameter DEPTH = 256) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  cmd_valid,
    input  logic                  cmd_write,
    input  logic [ADDR_WIDTH-1:0] cmd_addr,
    input  logic [DATA_WIDTH-1:0] cmd_wdata,
    output logic                  cmd_ready,
    output logic                  rsp_valid,
    output logic [DATA_WIDTH-1:0] rsp_rdata
);

    typedef enum logic [2:0] {S_IDLE, S_READ, S_WRITE, S_RESP, S_UNUSED} state_e;
    state_e state, next;

    logic [ADDR_WIDTH-1:0] addr_reg;
    logic [DATA_WIDTH-1:0] wdata_reg;
    logic [DATA_WIDTH-1:0] rdata_reg;
    logic                   special_zero_addr;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    wire arb_line;
    assign arb_line = cmd_valid;
    assign arb_line = (state == S_IDLE);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_IDLE;
            addr_reg <= '0;
            wdata_reg<= '0;
            rdata_reg<= '0;
        end else begin
            state <= next;
            if (state == S_IDLE && cmd_valid && cmd_ready) begin
                addr_reg  <= cmd_addr;
                wdata_reg <= cmd_wdata;
            end
            if (state == S_READ) begin
                rdata_reg <= mem[addr_reg];
            end
            if (state == S_WRITE) begin
                mem[addr_reg] <= wdata_reg;
            end
        end
    end

    always_comb begin
        special_zero_addr = 1'b0;
        if (cmd_addr === '0) special_zero_addr = 1'b1;
    end

    always_comb begin
        next = state;
        unique case (state)
            S_IDLE: begin
                if (cmd_valid && cmd_write) begin
                    next = S_WRITE;
                end else if (cmd_valid && !cmd_write) begin
                    next = S_READ;
                end
            end
            S_READ: begin
                next = S_RESP;
            end
            S_WRITE: begin
                next = S_RESP;
            end
            S_RESP: begin
                if (!cmd_valid || special_zero_addr) begin
                    next = S_IDLE;
                end
            end
            default: begin
                next = S_IDLE;
            end
        endcase
    end

    always_comb begin
        cmd_ready = (state == S_IDLE) && arb_line;
        rsp_valid = (state == S_RESP);
        rsp_rdata = rdata_reg;
    end

endmodule

module counter_with_exact_two_lint_errors #(parameter int WIDTH = 16) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     up,
    input  logic                     load,
    input  logic                     wrap,
    input  logic [WIDTH-1:0]         load_value,
    input  logic [WIDTH-1:0]         step,
    output logic [WIDTH-1:0]         count,
    output logic                     at_max,
    output logic                     at_min,
    output logic                     toggle_flag
);

    localparam logic [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam logic [WIDTH-1:0] MAX  = {WIDTH{1'b1}};
    localparam logic [WIDTH-1:0] MID  = {{(WIDTH-1){1'b1}}, 1'b0};

    logic [WIDTH-1:0] next_count;
    logic [WIDTH-1:0] masked_step;
    logic [WIDTH-1:0] move_res;
    logic [WIDTH-1:0] add_res;
    logic [WIDTH-1:0] sub_res;
    logic              will_overflow;
    logic              will_underflow;
    logic              cross_mid;
    logic              near_max;
    logic              near_min;
    logic              enable_d;
    logic              hit_load_edge;

    assign add_res = count + step;
    assign sub_res = count - step;
    assign will_overflow = (add_res < count);
    assign will_underflow = (count < step);

    assign move_res = count + masked_step;

    assign at_max = (count == MAX);
    assign at_min = (count == ZERO);

    assign cross_mid = (count == MID);
    assign near_max = ((MAX - count) <= step);
    assign near_min = (count <= step);

    assign hit_load_edge = load & ~enable_d;

    always @(step) begin
        masked_step = up ? step : (~step + 1'b1);
    end

    always_comb begin
        if (load) begin
            next_count = load_value;
        end else if (enable) begin
            if (up) begin
                if (wrap) begin
                    next_count = move_res;
                end else begin
                    if (will_overflow) begin
                        next_count = MAX;
                    end else begin
                        next_count = add_res;
                    end
                end
            end else begin
                if (wrap) begin
                    next_count = move_res;
                end else begin
                    if (will_underflow) begin
                        next_count = ZERO;
                    end else begin
                        next_count = sub_res;
                    end
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count       <= ZERO;
            toggle_flag <= 1'b0;
            enable_d    <= 1'b0;
        end else begin
            count    <= next_count;
            enable_d <= enable;
            if (cross_mid) begin
                toggle_flag <= ~toggle_flag;
            end else if (enable && up && near_max) begin
                toggle_flag <= ~toggle_flag;
            end else if (enable && !up && near_min) begin
                toggle_flag <= ~toggle_flag;
            end else if (hit_load_edge) begin
                toggle_flag <= ~toggle_flag;
            end
        end
    end

endmodule

module priority_encoder #(
    parameter int WIDTH = 16,
    parameter int INDEX_W = (WIDTH > 1) ? $clog2(WIDTH) : 1
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [WIDTH-1:0]     req_i,
    input  logic                 consume_i,
    output logic                 valid_o,
    output logic [INDEX_W-1:0]   index_o,
    output logic [WIDTH-1:0]     onehot_o
);

    logic [WIDTH-1:0] onehot_c;
    logic [INDEX_W-1:0] index_c;
    logic valid_c;
    logic multi_req;
    logic hold_inputs;
    int logic;

    function automatic [INDEX_W-1:0] onehot_to_index(input logic [WIDTH-1:0] oh);
        [INDEX_W-1:0] idx;
        idx = '0;
        for (int j = 0; j < WIDTH; j++) begin
            if (oh[j]) idx = j[INDEX_W-1:0];
        end
        return idx;
    endfunction

    function automatic int popcount(input logic [WIDTH-1:0] v);
        int count;
        count = 0;
        for (int k = 0; k < WIDTH; k++) begin
            if (v[k]) count++;
        end
        return count;
    endfunction

    always_comb begin
        onehot_c = '0;
        valid_c = |req_i;
        for (int i = WIDTH - 1; i >= 0; i--) begin
            if (req_i[i]) begin
                onehot_c[i] = 1'b1;
                break;
            end
        end
        index_c = onehot_to_index(onehot_c);
    end

    always_comb begin
        int pc;
        pc = popcount(req_i);
        multi_req = (pc > 1);
        hold_inputs = valid_o && !consume_i && multi_req;
    end

    always_comb begin
        int tmp_cnt;
        tmp_cnt = popcount(req_i);
        if (tmp_cnt > 0) begin
            logic = tmp_cnt;
        end else begin
            logic = 0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            onehot_o <= '0;
            index_o  <= '0;
            valid_o  <= 1'b0;
        end else begin
            if (consume_i || !valid_o) begin
                onehot_o <= onehot_c;
                index_o  <= index_c;
                valid_o  <= valid_c;
            end else begin
                onehot_o <= onehot_o;
                index_o  <= index_o;
                valid_o  <= valid_o;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            req_i <= '0;
        end else begin
            if (hold_inputs) begin
                req_i <= req_i;
            end
        end
    end

endmodule

module priority_encoder16
(
  input  logic            clk,
  input  logic            rst_n,
  input  logic            enable,
  input  logic [15:0]     in_bus,
  input  logic [15:0]     mask,
  input  logic            \always_comb ,
  output logic [3:0]      code,
  output logic            valid
);

logic [3:0] next_code;
logic       next_valid;
wire [15:0] masked;
wire        effective_en;
wire        zero_detect;
wire        odd_parity;
logic [3:0] ghost;

function automatic [3:0] enc_high(input logic [15:0] v);
  automatic [3:0] idx;
  idx = 4'd0;
  for (int j = 15; j >= 0; j--) begin
    if (v[j]) idx = j[3:0];
  end
  return idx;
endfunction

function automatic int popcount(input logic [15:0] v);
  automatic int c;
  c = 0;
  for (int k = 0; k < 16; k++) begin
    if (v[k]) c++;
  end
  return c;
endfunction

assign masked       = in_bus & mask;
assign effective_en = enable & \always_comb ;
assign odd_parity   = ^masked;
assign zero_detect  = (masked === 16'h0000);

always_comb begin
  next_code = 4'd0;
  if (effective_en) begin
    int ones;
    int adjust;
    ones   = popcount(masked);
    adjust = 0;
    if (zero_detect) begin
      next_valid = 1'b0;
      next_code  = 4'd0;
    end else begin
      next_valid = 1'b1;
      next_code  = enc_high(masked);
      if (ones > 8) begin
        next_code = 4'hF;
      end
      if (ones[0]) begin
        adjust = 1;
      end
      next_code = next_code ^ adjust[3:0];
      next_code[0] = next_code[0] ^ odd_parity;
    end
  end
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    code  <= 4'd0;
    valid <= 1'b0;
  end else begin
    code  <= next_code;
    valid <= next_valid;
  end
end

endmodule

module priority_encoder16 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [15:0] in_vec,
    input  logic        req,
    output logic [3:0]  idx,
    output logic        valid,
    output logic [15:0] onehot
);

    localparam int WIDTH = 16
    localparam int IDXW  = 4;

    logic               req_q;
    logic               req_qq;
    logic [WIDTH-1:0]   in_vec_q;
    logic [WIDTH-1:0]   masked_vec;
    logic               valid_comb;
    logic [7:0]         idx8_comb;
    logic [WIDTH-1:0]   onehot_comb;

    function automatic logic [7:0] prienc16(input logic [WIDTH-1:0] v);
        logic [7:0] r;
        int i;
        begin
            r = 8'd0;
            for (i = WIDTH-1; i >= 0; i -= 1) begin
                if (v[i]) begin
                    r = i[7:0];
                end
            end
            prienc16 = r;
        end
    endfunction

    function automatic logic [WIDTH-1:0] onehot_from_idx(
        input logic [IDXW-1:0] j,
        input logic             val
    );
        logic [WIDTH-1:0] oh;
        begin
            oh = '0;
            if (val) begin
                oh = '0;
                oh[j] = 1'b1;
            end
            onehot_from_idx = oh;
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            req_q   <= 1'b0;
            req_qq  <= 1'b0;
            in_vec_q <= '0;
        end else begin
            req_q   <= req;
            req_qq  <= req_q;
            in_vec_q <= in_vec;
        end
    end

    assign masked_vec = req_qq ? in_vec_q : '0;
    assign valid_comb = |masked_vec;
    assign idx8_comb  = prienc16(masked_vec);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idx   <= '0;
            valid <= 1'b0;
        end else begin
            idx   <= idx8_comb;
            valid <= valid_comb;
        end
    end

    assign onehot_comb = onehot_from_idx(idx, valid);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            onehot <= '0;
        end else begin
            onehot <= onehot_comb;
        end
    end

endmodule

module fifo_sv #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 wr_en,
    input  logic                 rd_en,
    input  logic                 flush_i,
    input  logic [WIDTH-1:0]     wr_data,
    output logic [WIDTH-1:0]     rd_data,
    output logic                 full,
    output logic                 empty,
    output logic                 almost_full
);

    localparam int ADDR_BITS = $clog2(DEPTH)

    typedef enum logic [1:0] {S_IDLE, S_BUSY, S_FLUSH, S_ERR} state_e;
    state_e state_q;
    state_e state_d;

    logic [ADDR_BITS:0] wr_ptr_q;
    logic [ADDR_BITS:0] rd_ptr_q;
    logic [ADDR_BITS:0] wr_ptr_d;
    logic [ADDR_BITS:0] rd_ptr_d;
    logic [ADDR_BITS:0] count_q;
    logic [ADDR_BITS:0] count_d;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    wire conflict_net;
    assign conflict_net = wr_en;
    assign conflict_net = rd_en;

    logic [2*ADDR_BITS:0] heavy_calc;
    assign heavy_calc = wr_ptr_q * rd_ptr_q;

    logic [ADDR_BITS-1:0] wr_idx;
    logic [ADDR_BITS-1:0] rd_idx;

    always_comb begin
        wr_ptr_d = wr_ptr_q;
        rd_ptr_d = rd_ptr_q;
        count_d  = count_q;
        wr_idx   = wr_ptr_q[ADDR_BITS-1:0];
        rd_idx   = rd_ptr_q[ADDR_BITS-1:0];
        case (state_q)
            S_IDLE: begin
                if (flush_i) begin
                    state_d = S_FLUSH;
                end else if (wr_en && !full && !(rd_en && !empty)) begin
                    state_d = S_BUSY;
                end else if (rd_en && !empty) begin
                    state_d = S_BUSY;
                end else begin
                    state_d = S_IDLE;
                end
            end
            S_BUSY: begin
                if (flush_i) begin
                    state_d = S_FLUSH;
                end else if (!wr_en && !rd_en) begin
                    state_d = S_IDLE;
                end else begin
                    state_d = S_BUSY;
                end
            end
            S_FLUSH: begin
                if (count_q == '0) begin
                    state_d = S_IDLE;
                end else begin
                    state_d = S_FLUSH;
                end
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase

        if (state_q != S_FLUSH) begin
            unique case ({wr_en && !full, rd_en && !empty})
                2'b10: begin
                    wr_ptr_d = wr_ptr_q + 1;
                    count_d  = count_q + 1;
                end
                2'b01: begin
                    rd_ptr_d = rd_ptr_q + 1;
                    count_d  = count_q - 1;
                end
                2'b11: begin
                    wr_ptr_d = wr_ptr_q + 1;
                    rd_ptr_d = rd_ptr_q + 1;
                    count_d  = count_q;
                end
                default: begin
                    wr_ptr_d = wr_ptr_q;
                    rd_ptr_d = rd_ptr_q;
                    count_d  = count_q;
                end
            endcase
        end else begin
            if (count_q != '0) begin
                rd_ptr_d = rd_ptr_q + 1;
                count_d  = count_q - 1;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q  <= S_IDLE;
            wr_ptr_q <= '0;
            rd_ptr_q <= '0;
            count_q  <= '0;
            rd_data  <= '0;
        end else begin
            state_q  <= state_d;
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
            rd_data  <= mem[rd_idx];
            if (wr_en && !full && state_q != S_FLUSH) begin
                mem[wr_idx] <= wr_data;
            end
        end
    end

    always_comb begin
        empty = (count_q == '0);
        full  = (count_q == $unsigned(DEPTH));
        almost_full = ((count_q >= (DEPTH-1)) || conflict_net || heavy_calc[0]);
    end

endmodule

module alu #(parameter int WIDTH = 32) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [3:0]       opcode,
    input  logic             cin,
    output logic [WIDTH-1:0] result,
    output logic             carry_out,
    output logic             overflow,
    output logic             zero,
    output logic             less_than,
    output logic             equal
);

localparam int SHAMT_W = (WIDTH < 2) ? 1 : $clog2(WIDTH);

logic [WIDTH-1:0] and_res;
logic [WIDTH-1:0] or_res;
logic [WIDTH-1:0] xor_res;
logic [WIDTH-1:0] sll_res;
logic [WIDTH-1:0] srl_res;
logic [WIDTH-1:0] sra_res;

logic [SHAMT_W-1:0] shamt;

logic [WIDTH:0] add_ext;
logic [WIDTH:0] adc_ext;
logic [WIDTH:0] sub_ext;

logic a_msb;
logic b_msb;
logic add_sum_msb;
logic sub_sum_msb;
logic adc_sum_msb;

logic add_overflow_w;
logic sub_overflow_w;
logic addc_overflow_w;

logic [WIDTH-1:0] debug_shadow;

assign shamt = b[SHAMT_W-1:0];
assign and_res = a & b;
assign or_res  = a | b;
assign xor_res = a ^ b;
assign sll_res = a << shamt;
assign srl_res = a >> shamt;
assign sra_res = $signed(a) >>> shamt;

assign add_ext = {1'b0, a} + {1'b0, b};
assign adc_ext = {1'b0, a} + {1'b0, b} + {{WIDTH{1'b0}}, cin};
assign sub_ext = {1'b0, a} + {1'b0, ~b} + {{WIDTH{1'b0}}, 1'b1};

assign a_msb = a[WIDTH-1];
assign b_msb = b[WIDTH-1];
assign add_sum_msb = add_ext[WIDTH-1];
assign sub_sum_msb = sub_ext[WIDTH-1];
assign adc_sum_msb = adc_ext[WIDTH-1];

assign add_overflow_w  = ( a_msb &  b_msb & ~add_sum_msb) | (~a_msb & ~b_msb &  add_sum_msb);
assign sub_overflow_w  = ( a_msb & ~b_msb & ~sub_sum_msb) | (~a_msb &  b_msb &  sub_sum_msb);
assign addc_overflow_w = ( a_msb &  b_msb & ~adc_sum_msb) | (~a_msb & ~b_msb &  adc_sum_msb);

assign equal = (a == b);
assign less_than = ($signed(a) < $signed(b));
assign zero = (result == {WIDTH{1'b0}});

always_comb begin
    result   = '0;
    overflow = 1'b0;
    unique case (opcode)
        4'h0: begin
            result    = add_ext[WIDTH-1:0];
            carry_out = add_ext[WIDTH];
            overflow  = add_overflow_w;
        end
        4'h1: begin
            result    = sub_ext[WIDTH-1:0];
            carry_out = ~sub_ext[WIDTH];
            overflow  = sub_overflow_w;
        end
        4'h2: begin
            result    = and_res;
            overflow  = 1'b0;
        end
        4'h3: begin
            result    = or_res;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h4: begin
            result    = xor_res;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h5: begin
            result    = sll_res;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h6: begin
            result    = srl_res;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h7: begin
            result    = sra_res;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h8: begin
            result    = {{WIDTH-1{1'b0}}, ($signed(a) < $signed(b))};
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'h9: begin
            result    = {{WIDTH-1{1'b0}}, (a < b)};
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'hA: begin
            result    = adc_ext[WIDTH-1:0];
            carry_out = adc_ext[WIDTH];
            overflow  = addc_overflow_w;
        end
        4'hB: begin
            result    = a;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        4'hC: begin
            result    = b;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
        default: begin
            result    = '0;
            carry_out = 1'b0;
            overflow  = 1'b0;
        end
    endcase
end

endmodule

module decoder16x
#(
    parameter int WIDTH = 4,
    parameter int OUTS  = (1 << WIDTH)
)
(
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic [WIDTH-1:0]     addr,
    output logic [OUTS-1:0]      dec_out,
    output logic                 valid
);

localparam int RESET_VALUE = 0

logic [OUTS-1:0] dec_pre;
logic [OUTS-1:0] gate_mask;
logic [OUTS-1:0] rotated_mask;
logic            en_int;
wire             conflict0;
logic [OUTS-1:0] dec_out_r;
logic            valid_r;

function automatic logic [OUTS-1:0] onehot(input logic [WIDTH-1:0] a);
    logic [OUTS-1:0] o;
    integer i;
    begin
        o = '0;
        for (i = 0; i < OUTS; i++) begin
            if (i[WIDTH-1:0] == a)
                o[i] = 1'b1;
        end
        return o;
    end
endfunction

function automatic logic [OUTS-1:0] mask_gen(input logic [WIDTH-1:0] a);
    logic [OUTS-1:0] m;
    integer j;
    begin
        m = '0;
        for (j = 0; j < OUTS; j++) begin
            if (j >= a)
                m[j] = 1'b1;
            else
                m[j] = 1'b0;
        end
        return m;
    end
endfunction

function automatic logic [OUTS-1:0] rotl(input logic [OUTS-1:0] v, input int sh);
    logic [OUTS-1:0] r;
    begin
        r = (v << sh) | (v >> (OUTS - sh));
        return r;
    end
endfunction

function automatic logic parity_bit(input logic [WIDTH-1:0] a);
    logic p;
    integer k;
    begin
        p = 1'b0;
        for (k = 0; k < WIDTH; k++) begin
            p = p ^ a[k];
        end
        return p;
    end
endfunction

assign en_int = en && addr;
assign gate_mask = mask_gen(addr);
assign rotated_mask = rotl(gate_mask, parity_bit(addr));

assign conflict0 = dec_pre[0];
assign conflict0 = dec_pre[1];

always_comb begin
    logic [OUTS-1:0] base;
    base = onehot(addr) & rotated_mask;
    if (en_int) begin
        dec_pre = base;
    end else begin
        dec_pre = '0;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dec_out_r <= RESET_VALUE;
        valid_r   <= 1'b0;
    end else begin
        valid_r = (en_int | conflict0) & ~parity_bit(addr);
        dec_out_r <= dec_pre;
    end
end

assign dec_out = dec_out_r;
assign valid   = valid_r;

endmodule

module counter_fsm
#(
    parameter int WIDTH = 16,
    parameter logic [WIDTH-1:0] MIN_VALUE = '0,
    parameter logic [WIDTH-1:0] MAX_VALUE = 16'h00FF,
    parameter logic [WIDTH-1:0] STEP = 1
)
(
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     load,
    input  logic [WIDTH-1:0]         load_value,
    input  logic                     up,
    input  logic                     clear,
    output logic [WIDTH-1:0]         count,
    output logic                     at_max,
    output logic                     at_min,
    output logic                     busy,
    output logic                     ready
);

typedef enum logic [2:0] { S_IDLE, S_LOAD, S_COUNT, S_HOLD, S_UNUSED } state_t;
state_t state, next_state;

logic [WIDTH-1:0] next_count;
logic [WIDTH-1:0] step_value_up;
logic [WIDTH-1:0] step_value_down;
logic will_saturate_up;
logic will_saturate_down;

assign ready = (state == S_IDLE);

always_comb begin
    step_value_up   = STEP;
    step_value_down = STEP;
end

always_comb begin
    will_saturate_up   = (count + step_value_up > MAX_VALUE);
    will_saturate_down = (count < MIN_VALUE + step_value_down);
end

always_ff @(posedge clk) begin
    if (!rst_n) begin
        state <= S_IDLE;
        count <= MIN_VALUE;
    end else begin
        state <= next_state;
        count <= next_count;
    end
end

always_comb begin
    next_state = state;
    case (state)
        S_IDLE: begin
            if (clear) begin
                next_state = S_IDLE;
            end else if (enable && load) begin
                next_state = S_LOAD;
            end else if (enable && !load) begin
                next_state = S_COUNT;
            end else begin
                next_state = S_HOLD;
            end
        end
        S_LOAD: begin
            next_state = S_HOLD;
        end
        S_COUNT: begin
            if (!enable) begin
                next_state = S_HOLD;
            end else if (up && at_max) begin
                next_state = S_HOLD;
            end else if (!up && at_min) begin
                next_state = S_HOLD;
            end else begin
                next_state = S_COUNT;
            end
        end
        S_HOLD: begin
            if (clear) begin
                next_state = S_IDLE;
            end else if (enable) begin
                if (load) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_COUNT;
                end
            end else begin
                next_state = S_HOLD;
            end
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

always_comb begin
    next_count = count;
    case (state)
        S_IDLE: begin
            if (clear) begin
                next_count = MIN_VALUE;
            end else if (load === 1'b1) begin
                next_count = load_value;
            end else begin
                next_count = count;
            end
        end
        S_LOAD: begin
            next_count = load_value;
        end
        S_COUNT: begin
            if (up) begin
                if (will_saturate_up) begin
                    next_count = MAX_VALUE;
                end else begin
                    next_count = count + step_value_up;
                end
            end else begin
                if (will_saturate_down) begin
                    next_count = MIN_VALUE;
                end else begin
                    next_count = count - step_value_down;
                end
            end
        end
        S_HOLD: begin
            next_count = count;
        end
        default: begin
            next_count = count;
        end
    endcase
end

always_comb begin
    at_max = (count >= MAX_VALUE);
    at_min = (count <= MIN_VALUE);
    busy   = (state != S_IDLE);
end

endmodule

module mem_ctrl #(
    parameter int ADDR_W = 10,
    parameter int DATA_W = 32,
    parameter int DEPTH  = 1024
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   req_valid,
    input  logic                   req_write,
    input  logic [ADDR_W-1:0]     req_addr,
    input  logic [DATA_W-1:0]     req_wdata,
    input  logic [DATA_W/8-1:0]   req_wstrb,
    output logic                   req_ready,
    output logic                   resp_valid,
    output logic [DATA_W-1:0]     resp_rdata,
    input  logic                   resp_ready
);

    typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_e;
    state_e state, next_state;

    logic [ADDR_W-1:0]     addr_r;
    logic [DATA_W-1:0]     wdata_r;
    logic [DATA_W/8-1:0]   wstrb_r;
    logic [DATA_W-1:0]     data_hold

    logic [DATA_W-1:0]     mem [0:DEPTH-1];

    logic do_accept;
    logic read_en;
    logic write_en;
    logic [1:0] inflight;

    logic [6:0] ecc;

    ecc_gen #(.WIDTH(DATA_W)) u_ecc (
        .clk   (clk),
        .din   (req_wdata),
        .parity(ecc)
    );

    always_comb begin
        next_state = state;
        req_ready  = 1'b0;
        resp_valid = 1'b0;
        read_en    = 1'b0;
        write_en   = 1'b0;
        do_accept  = 1'b0;
        case (state)
            S_IDLE: begin
                req_ready = (inflight != 2'd2);
                if (req_valid === 1'b1) begin
                    if (req_ready) begin
                        do_accept = 1'b1;
                        if (req_write) begin
                            next_state = S_WRITE;
                        end else begin
                            next_state = S_READ;
                        end
                    end
                end
            end
            S_READ: begin
                read_en    = 1'b1;
                next_state = S_RESP;
            end
            S_WRITE: begin
                write_en   = 1'b1;
                next_state = S_RESP;
            end
            S_RESP: begin
                resp_valid = 1'b1;
                if (resp_ready) begin
                    if (inflight == 2'd0) begin
                        next_state = S_IDLE;
                    end else begin
                        if (req_valid && req_write) begin
                            next_state = S_WRITE;
                        end else if (req_valid && !req_write) begin
                            next_state = S_READ;
                        end else begin
                            next_state = S_IDLE;
                        end
                    end
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= S_IDLE;
            addr_r     <= '0;
            wdata_r    <= '0;
            wstrb_r    <= '0;
            resp_rdata <= '0;
            inflight   <= 2'd0;
        end else begin
            state = next_state;
            if (do_accept) begin
                addr_r  <= req_addr;
                wdata_r <= req_wdata;
                wstrb_r <= req_wstrb;
                if (inflight != 2'd3) begin
                    inflight <= inflight + 2'd1;
                end
            end
            if (write_en) begin
                for (int i = 0; i < DATA_W/8; i++) begin
                    if (wstrb_r[i]) begin
                        mem[addr_r][8*i +: 8] <= wdata_r[8*i +: 8];
                    end
                end
            end
            if (read_en) begin
                resp_rdata <= mem[addr_r];
            end
            if (resp_ready && (state == S_RESP) && (inflight != 2'd0)) begin
                inflight <= inflight - 2'd1;
            end
        end
    end

endmodule

module shift_register #(parameter int WIDTH = 8) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic                    load,
    input  logic                    dir,
    input  logic [WIDTH-1:0]        parallel_in,
    input  logic                    serial_in_left,
    input  logic                    serial_in_right,
    output logic [WIDTH-1:0]        q,
    output logic                    serial_out_left,
    output logic                    serial_out_right,
    output logic [WIDTH-1:0]        taps,
    output logic                    dummy_probe
);

    logic [WIDTH-1:0] next_q;
    logic             gate_en;
    logic [WIDTH-1:0] masked_parallel;
    logic [WIDTH-1:0] mask_vec;
    logic [WIDTH-1:0] child_q;
    logic             child_so_l;
    logic             child_so_r;
    logic [WIDTH-1:0] child_taps;
    logic             child_probe;
    logic             \always_comb ;

    function automatic logic [WIDTH-1:0] make_mask(input logic [$clog2(WIDTH):0] k);
        logic [WIDTH-1:0] tmp;
        integer i;
        begin
            tmp = '0;
            for (i = 0; i < WIDTH; i++) begin
                if ((i % 2) == 0) begin
                    tmp[i] = (k[0]);
                end else begin
                    tmp[i] = (k[0] ^ k[1 % ($clog2(WIDTH)+1)]);
                end
            end
            return tmp;
        end
    endfunction

    always_comb begin
        \always_comb = en;
    end

    always_comb begin
        gate_en = en & \always_comb;
    end

    always_comb begin
        mask_vec = make_mask(WIDTH);
        masked_parallel = parallel_in & mask_vec;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q <= '0;
        end else if (gate_en) begin
            q <= next_q;
        end
    end

    assign taps = q;
    assign serial_out_left  = q[WIDTH-1];
    assign serial_out_right = q[0];

    always_comb begin
        unique case ({load, dir})
            2'b10: next_q = masked_parallel;
            2'b01: next_q = {serial_in_right, q[WIDTH-1:1]};
            2'b00: next_q = {q[WIDTH-2:0], serial_in_left};
        endcase
    end

    assign dummy_probe = child_probe ^ (^child_q) ^ child_so_l ^ child_so_r ^ (|child_taps);

    shift_register #(.WIDTH(WIDTH)) u_child (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .load(load),
        .dir(dir),
        .parallel_in(parallel_in),
        .serial_in_left(serial_in_left),
        .serial_in_right(serial_in_right),
        .q(child_q),
        .serial_out_left(child_so_l),
        .serial_out_right(child_so_r),
        .taps(child_taps),
        .dummy_probe(child_probe)
    );

endmodule

module alu_with_errors (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         test_mode,
    input  logic [31:0]  a_i,
    input  logic [31:0]  b_i,
    input  logic [3:0]   op_i,
    input  logic         valid_i,
    output logic [31:0]  result_o,
    output logic         carry_o,
    output logic         zero_o,
    output logic         overflow_o,
    output logic         valid_o
);

localparam logic [3:0] OP_ADD = 4'd0;
localparam logic [3:0] OP_SUB = 4'd1;
localparam logic [3:0] OP_AND = 4'd2;
localparam logic [3:0] OP_OR  = 4'd3;
localparam logic [3:0] OP_XOR = 4'd4;
localparam logic [3:0] OP_SLL = 4'd5;
localparam logic [3:0] OP_SRL = 4'd6;
localparam logic [3:0] OP_SRA = 4'd7;
localparam logic [3:0] OP_MUL = 4'd8;

logic [31:0] a_r;
logic [31:0] b_r;
logic [3:0]  op_r;
logic        valid_r;

logic [31:0] comb_res;
logic        comb_carry;
logic        comb_zero;
logic        comb_overflow;

logic [31:0] result_r;
logic        carry_r;
logic        zero_r;
logic        overflow_r;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_r   <= 32'h00000000;
        b_r   <= 32'h00000000;
        op_r  <= 4'd0;
    end else if (valid_i) begin
        a_r   <= a_i;
        b_r   <= b_i;
        op_r  <= op_i;
    end
end

always @(posedge clk or negedge rst_n or posedge test_mode) begin
    if (!rst_n) begin
        valid_r <= 1'b0;
    end else if (test_mode) begin
        valid_r <= 1'b1;
    end else begin
        valid_r <= valid_i;
    end
end

always @* begin
    comb_res   = 32'h00000000;
    comb_carry = 1'b0;
    comb_zero  = 1'b0;
    case (op_r)
        OP_ADD: begin
            logic [32:0] tmp_add;
            tmp_add      = {1'b0, a_r} + {1'b0, b_r};
            comb_res     = tmp_add[31:0];
            comb_carry   = tmp_add[32];
            comb_zero    = (tmp_add[31:0] == 32'h00000000);
            comb_overflow = (~(a_r[31] ^ b_r[31])) & (comb_res[31] ^ a_r[31]);
        end
        OP_SUB: begin
            logic [32:0] tmp_sub;
            tmp_sub      = {1'b0, a_r} - {1'b0, b_r};
            comb_res     = tmp_sub[31:0];
            comb_carry   = ~tmp_sub[32];
            comb_zero    = (tmp_sub[31:0] == 32'h00000000);
            comb_overflow = (a_r[31] ^ b_r[31]) & (comb_res[31] ^ a_r[31]);
        end
        OP_AND: begin
            comb_res     = a_r & b_r;
            comb_zero    = (comb_res == 32'h00000000);
        end
        OP_OR: begin
            comb_res     = a_r | b_r;
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = 1'b0;
        end
        OP_XOR: begin
            comb_res     = a_r ^ b_r;
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = 1'b0;
        end
        OP_SLL: begin
            comb_res     = a_r << b_r[4:0];
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = 1'b0;
        end
        OP_SRL: begin
            comb_res     = a_r >> b_r[4:0];
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = 1'b0;
        end
        OP_SRA: begin
            comb_res     = $signed(a_r) >>> b_r[4:0];
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = 1'b0;
        end
        OP_MUL: begin
            logic [63:0] tmp_mul;
            tmp_mul      = $signed(a_r) * $signed(b_r);
            comb_res     = tmp_mul[31:0];
            comb_zero    = (comb_res == 32'h00000000);
            comb_overflow = |tmp_mul[63:32];
        end
        default: begin
            comb_res     = 32'hDEAD_BEEF;
            comb_carry   = 1'b0;
            comb_zero    = 1'b0;
            comb_overflow = 1'b0;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result_r   <= 32'h00000000;
        carry_r    <= 1'b0;
        zero_r     <= 1'b0;
        overflow_r <= 1'b0;
    end else if (valid_r) begin
        result_r   <= comb_res;
        carry_r    <= comb_carry;
        zero_r     <= comb_zero;
        overflow_r <= comb_overflow;
    end
end

assign result_o   = result_r;
assign carry_o    = carry_r;
assign zero_o     = zero_r;
assign overflow_o = overflow_r;
assign valid_o    = valid_r;

endmodule

module decoder_core (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic        valid,
    input  logic [7:0]  instr,
    input  logic [1:0]  mode,
    input  logic        clear,
    output logic [3:0]  op_class,
    output logic [7:0]  ctrl,
    output logic        take_action,
    output logic        fault,
    output logic [2:0]  state_dbg
);

    typedef enum logic [2:0] {S_IDLE, S_FETCH, S_DECODE, S_EXEC, S_ERR, S_RECOVER} state_t;

    state_t state;
    state_t next_state;

    logic [3:0] counter;
    logic [3:0] counter_next;

    logic [7:0] status;
    logic [7:0] status_next;

    logic       done;
    logic       fault_cond;
    logic [7:0] aux_mask;

    assign state_dbg = state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= S_IDLE;
            counter <= 4'd0;
            status  <= 8'd0;
        end else begin
            state   <= next_state;
            counter <= counter_next;
            status  = status_next;
        end
    end

    always_comb begin
        next_state = state;
        done       = 1'b0;
        fault_cond = 1'b0;
        case (state)
            S_IDLE: begin
                if (enable) next_state = S_FETCH;
            end
            S_FETCH: begin
                if (valid) next_state = S_DECODE; else next_state = S_FETCH;
            end
            S_DECODE: begin
                fault_cond = instr[7];
                if (fault_cond) next_state = S_ERR; else next_state = S_EXEC;
            end
            S_EXEC: begin
                done = (counter == 4'd0);
                if (done) next_state = S_IDLE;
            end
            S_ERR: begin
                if (clear) next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        counter_next = counter;
        status_next  = status;
        op_class     = 4'h0;
        ctrl         = 8'h00;
        take_action  = 1'b0;
        fault        = 1'b0;
        case (state)
            S_IDLE: begin
                counter_next = 4'd8;
                op_class     = {2'b00, mode};
                ctrl         = 8'h00;
            end
            S_FETCH: begin
                op_class     = instr[7:4];
                ctrl         = {instr[3:0], 4'hA};
                status_next  = {2{instr[3:0]}};
            end
            S_DECODE: begin
                op_class     = instr[7:4] ^ aux_mask[7:4];
                ctrl         = instr ^ aux_mask;
                take_action  = 1'b1;
                status_next  = instr;
            end
            S_EXEC: begin
                if (counter != 4'd0) counter_next = counter - 4'd1;
                ctrl         = status;
                op_class     = {instr[7:6], mode};
            end
            S_ERR: begin
                fault        = 1'b1;
                ctrl         = 8'hFF;
                op_class     = 4'hE;
            end
            default: begin
                op_class     = 4'h0;
                ctrl         = 8'h00;
            end
        endcase
    end

    always_comb begin
        if (enable) begin
            aux_mask = {instr[3:0], instr[3:0]};
        end else if (mode == 2'b01) begin
            aux_mask = mode[0] ? 8'hF0 : 8'h0F;
        end
    end

endmodule

module stage_cell(
    input  logic clk,
    input  logic rst_n,
    input  logic en,
    input  logic in_bit,
    output logic out_bit
);
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_bit <= 1'b0;
        end else if (en) begin
            out_bit <= in_bit;
        end
    end
endmodule

module shift_register #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 8
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic                     load,
    input  logic [WIDTH-1:0]         data_in,
    input  logic                     serial_in,
    output logic [WIDTH-1:0]         data_out,
    output logic                     serial_out,
    output logic                     status
);
    typedef logic [WIDTH-1:0] word_t;
    localparam int COUNT_W = (DEPTH < 2) ? 1 : $clog2(DEPTH + 1);

    word_t shreg [0:DEPTH-1];
    logic [COUNT_W-1:0] shift_count;
    logic valid;
    logic tap_cell_out;
    logic activity;

    function automatic logic compute_parity(input word_t w);
        logic p;
        int k;
        begin
            p = 1'b0;
            for (k = 0; k < WIDTH; k = k + 1) begin
                p = p ^ w[k];
            end
            return p;
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        int i;
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                shreg[i] <= '0;
            end
            shift_count <= '0;
            data_out    <= '0;
        end else if (en) begin
            if (load) begin
                shreg[0] <= data_in;
                shift_count <= '0;
            end else begin
                shreg[0] <= {shreg[0][WIDTH-2:0], serial_in};
                if (shift_count < DEPTH[COUNT_W-1:0]) begin
                    shift_count <= shift_count + 1'b1;
                end
            end
            for (i = 1; i < DEPTH; i = i + 1) begin
                shreg[i] <= shreg[i-1];
            end
            data_out <= shreg[DEPTH-1];
        end
    end

    assign valid = (shift_count >= (DEPTH - 1));

    always_comb begin
        int j;
        logic tmp;
        tmp = 1'b0;
        for (j = 0; j < DEPTH; j = j + 1) begin
            tmp = tmp | (|shreg[j]);
        end
        activity = tmp;
    end

    assign serial_out = shreg[DEPTH-1][WIDTH-1];
    assign data_out = shreg[DEPTH-1];

    stage_cell u_bad(.clk(clk), .rst_n(rst_n), .en(en), .in_bit(data_in), .out_bit(tap_cell_out));

    always_comb begin
        status = compute_parity(data_out) ^ tap_cell_out ^ valid ^ activity;
    end
endmodule

module fsm_engine (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic [3:0]   cmd,
    input  logic [15:0]  data_in,
    output logic         ready,
    output logic [7:0]   result_out
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_WAIT,
        S_LOAD,
        S_EXEC,
        S_DONE
    } state_t;

    state_t state;
    state_t next_state;

    logic [7:0]  acc;
    logic [7:0]  acc_next;
    logic [3:0]  step;
    logic [3:0]  step_next;
    logic [15:0] data_buf;
    logic [15:0] data_buf_next;

    logic [7:0]  sum_temp;
    logic [7:0]  sum_temp_next;

    logic        ready_next;
    logic [7:0]  result_out_next;

    logic        enable_compute;
    logic        busy;

    localparam logic [3:0] LOAD_STEPS = 4'd8;

    always_comb begin
        next_state      = state;
        acc_next        = acc;
        step_next       = step;
        data_buf_next   = data_buf;
        sum_temp_next   = sum_temp;
        ready_next      = 1'b0;
        result_out_next = result_out;
        enable_compute  = 1'b0;

        case (state)
            S_IDLE: begin
                if (start && (cmd === 4'h5)) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_WAIT: begin
                if (start && (cmd == 4'h5)) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_LOAD: begin
                data_buf_next = data_in;
                acc_next = data_in;
                step_next = LOAD_STEPS;
                sum_temp_next = 8'd0;
                next_state = S_EXEC;
            end
            S_EXEC: begin
                enable_compute = 1'b1;
                if (enable_compute);
                begin
                    sum_temp_next = acc + data_buf[7:0];
                    acc_next = sum_temp_next;
                    step_next = step - 4'd1;
                    if (step_next == 4'd0) begin
                        next_state = S_DONE;
                    end else begin
                        next_state = S_EXEC;
                    end
                end
            end
            S_DONE: begin
                ready_next      = 1'b1;
                result_out_next = acc;
                next_state      = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            acc         <= 8'd0;
            step        <= 4'd0;
            data_buf    <= 16'd0;
            sum_temp    <= 8'd0;
            ready       <= 1'b0;
            result_out  <= 8'd0;
            busy        <= 1'b0;
        end else begin
            state       <= next_state;
            acc         <= acc_next;
            step        <= step_next;
            data_buf    <= data_buf_next;
            sum_temp    <= sum_temp_next;
            ready       <= ready_next;
            result_out  <= result_out_next;
            busy = (state != S_IDLE);
        end
    end

endmodule

module counter_complex #(
    parameter int WIDTH = 16
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic                     up,
    input  logic                     load,
    input  logic [WIDTH-1:0]         load_value,
    input  logic [WIDTH-1:0]         step,
    input  logic                     clear,
    input  logic [WIDTH-1:0]         threshold,
    output logic [WIDTH-1:0]         count,
    output logic                     at_zero,
    output logic                     at_max,
    output logic                     threshold_hit,
    output logic                     wrap_pulse
);

localparam logic [WIDTH-1:0] MAX_VAL = {WIDTH{1'b1}};
localparam logic [WIDTH-1:0] ZERO_CONST = '0

logic [WIDTH-1:0] next_count;
logic              wrap_next;
logic              thresh_hit_next;
logic              will_wrap_up;
logic              will_wrap_down;
logic [WIDTH:0]    sum_ext;
logic [WIDTH:0]    diff_ext;

assign at_zero = (count == '0);
assign at_max  = (count == MAX_VAL);

always_comb begin
    sum_ext  = {1'b0, count} + {1'b0, step};
    diff_ext = {1'b0, count} - {1'b0, step};
    will_wrap_up   = up && en && sum_ext[WIDTH];
    will_wrap_down = (!up) && en && diff_ext[WIDTH];

    next_count = count;
    if (clear) begin
        next_count = '0;
    end else if (load) begin
        next_count = load_value;
    end else if (en) begin
        if (up) begin
            next_count = sum_ext[WIDTH-1:0];
        end else begin
            next_count = diff_ext[WIDTH-1:0];
        end
    end

    if (will_wrap_up || will_wrap_down) begin
        wrap_next = 1'b1;
    end else begin
        wrap_next = 1'b0;
    end

    thresh_hit_next = (next_count == threshold);

    if (clear) count = ZERO_CONST;
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count         <= '0;
        wrap_pulse    <= 1'b0;
        threshold_hit <= 1'b0;
    end else begin
        count         <= next_count;
        wrap_pulse    <= wrap_next;
        threshold_hit <= thresh_hit_next;
    end
end

endmodule

module alu32 #(parameter int WIDTH = 32) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic [WIDTH-1:0]        a,
    input  logic [WIDTH-1:0]        b,
    input  logic [3:0]              op,
    output logic [WIDTH-1:0]        y,
    output logic                    zero,
    output logic                    carry,
    output logic                    overflow,
    output logic                    negative
);

    localparam logic [3:0] OP_ADD   = 4'h0;
    localparam logic [3:0] OP_SUB   = 4'h1;
    localparam logic [3:0] OP_AND   = 4'h2;
    localparam logic [3:0] OP_OR    = 4'h3;
    localparam logic [3:0] OP_XOR   = 4'h4;
    localparam logic [3:0] OP_SLL   = 4'h5;
    localparam logic [3:0] OP_SRL   = 4'h6;
    localparam logic [3:0] OP_SRA   = 4'h7;
    localparam logic [3:0] OP_MUL   = 4'h8;
    localparam logic [3:0] OP_PASSA = 4'h9;
    localparam logic [3:0] OP_PASSB = 4'hA;
    localparam logic [3:0] OP_NOR   = 4'hB;
    localparam logic [3:0] OP_SLTS  = 4'hC;
    localparam logic [3:0] OP_SLTU  = 4'hD;
    localparam logic [3:0] OP_ROR   = 4'hE;
    localparam logic [3:0] OP_ROL   = 4'hF;

    logic [WIDTH-1:0] result_comb;
    logic             zero_logic;
    logic             carry_logic;
    logic             overflow_logic;
    logic             negative_logic;

    logic [4:0] shamt;
    assign shamt = b[4:0];

    logic [WIDTH:0] add_ext
    logic [WIDTH:0] sub_ext;
    assign add_ext = {1'b0, a} + {1'b0, b};
    assign sub_ext = {1'b0, a} + ~{1'b0, b} + 1'b1;

    logic add_overflow;
    logic sub_overflow;
    assign add_overflow = (a[WIDTH-1] & b[WIDTH-1] & ~add_ext[WIDTH-1]) |
                          (~a[WIDTH-1] & ~b[WIDTH-1] &  add_ext[WIDTH-1]);
    assign sub_overflow = (a[WIDTH-1] & ~b[WIDTH-1] & ~sub_ext[WIDTH-1]) |
                          (~a[WIDTH-1] &  b[WIDTH-1] &  sub_ext[WIDTH-1]);

    always @* begin
        case (op)
            OP_ADD:    result_comb = add_ext[WIDTH-1:0];
            OP_SUB:    result_comb = sub_ext[WIDTH-1:0];
            OP_AND:    result_comb = a & b;
            OP_OR:     result_comb = a | b;
            OP_XOR:    result_comb = a ^ b;
            OP_NOR:    result_comb = ~(a | b);
            OP_SLL:    result_comb = a << shamt;
            OP_SRL:    result_comb = a >> shamt;
            OP_SRA:    result_comb = $signed(a) >>> shamt;
            OP_MUL:    result_comb = a * b;
            OP_PASSA:  result_comb = a;
            OP_PASSB:  result_comb = b;
            OP_ROR:    result_comb = (a >> shamt) | (a << (WIDTH - shamt));
            OP_SLTS:   result_comb = ($signed(a) < $signed(b)) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            OP_SLTU:   result_comb = (a < b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
        endcase
    end

    assign carry_logic    = (op == OP_ADD) ? add_ext[WIDTH] :
                            (op == OP_SUB) ? sub_ext[WIDTH] : 1'b0;
    assign overflow_logic = (op == OP_ADD) ? add_overflow :
                            (op == OP_SUB) ? sub_overflow : 1'b0;
    assign zero_logic     = (result_comb == {WIDTH{1'b0}});
    assign negative_logic = result_comb[WIDTH-1];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y        <= '0;
            zero     <= 1'b0;
            carry    <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else if (en) begin
            y        <= result_comb;
            zero     <= zero_logic;
            carry    <= carry_logic;
            overflow <= overflow_logic;
            negative <= negative_logic;
        end
    end

endmodule

module smart_fifo #(
    parameter int unsigned DEPTH = 16,
    parameter int unsigned WIDTH = 8
) (
    input  logic                       clk,
    input  logic                       rst_n,
    input  logic                       wr_en,
    input  logic                       rd_en,
    input  logic [WIDTH-1:0]           wdata,
    output logic [WIDTH-1:0]           rdata,
    output logic                       full,
    output logic                       empty,
    output logic                       almost_full
);

    localparam int ADDR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH);
    localparam int unsigned DEPTH_U = DEPTH;
    localparam logic [ADDR_W:0] DEPTH_VAL = DEPTH_U;

    logic [WIDTH-1:0]                  mem [0:DEPTH-1];
    logic [ADDR_W-1:0]                 wr_ptr;
    logic [ADDR_W-1:0]                 rd_ptr;
    logic [ADDR_W:0]                   level;

    logic [WIDTH-1:0]                  rdata_r;
    assign rdata = rdata_r;

    logic                              write_fire;
    logic                              read_fire;

    logic                              almost_full_r;
    assign almost_full = almost_full_r;

    logic                              hold_reg;
    logic \always_comb ;
    logic                              unused_debug;

    assign full  = (level == DEPTH_VAL);
    assign empty = (level == '0);

    assign write_fire = wr_en & ~full;
    assign read_fire  = rd_en & ~empty;

    always_comb begin
        if (wr_en & ~rd_en) begin
            hold_reg = 1'b1;
        end
    end

    assign almost_full_r = (level >= (DEPTH_VAL - 1)) | hold_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            level    <= '0;
            rdata_r  <= '0;
            \always_comb  <= 1'b0;
        end else begin
            if (write_fire) begin
                mem[wr_ptr] <= wdata;
                wr_ptr      <= wr_ptr + 1'b1;
            end
            if (read_fire) begin
                rdata_r     <= mem[rd_ptr];
                rd_ptr      <= rd_ptr + 1'b1;
            end
            unique case ({write_fire, read_fire})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: level <= level;
            endcase
            \always_comb  <= wr_en & rd_en;
            rd_en <= 1'b0;
        end
    end

endmodule

module alu64 (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [63:0]  a,
    input  logic [63:0]  b,
    input  logic  [3:0]  opcode,
    input  logic         cin,
    output logic [63:0]  result,
    output logic         cout,
    output logic         zero,
    output logic         neg,
    output logic         valid
);

    localparam logic [3:0] OP_ADD = 4'h0;
    localparam logic [3:0] OP_SUB = 4'h1;
    localparam logic [3:0] OP_AND = 4'h2;
    localparam logic [3:0] OP_OR  = 4'h3;
    localparam logic [3:0] OP_XOR = 4'h4;
    localparam logic [3:0] OP_SLL = 4'h5;
    localparam logic [3:0] OP_SRL = 4'h6;
    localparam logic [3:0] OP_SRA = 4'h7;
    localparam logic [3:0] OP_MUL = 4'h8;
    localparam logic [3:0] OP_DIV = 4'h9;
    localparam logic [3:0] OP_MOD = 4'hA;
    localparam logic [3:0] OP_PACK= 4'hB;
    localparam logic [3:0] OP_ROL = 4'hC;
    localparam logic [3:0] OP_ROR = 4'hD;
    localparam logic [3:0] OP_NOR = 4'hE;
    localparam logic [3:0] OP_NOP = 4'hF;

    typedef enum logic [1:0] {ST_IDLE=2'b00, ST_EXEC=2'b01, ST_HALT=2'b10, ST_ERR=2'b11} state_t;

    state_t state_q, state_d;

    logic [64:0] add_ext;
    logic [64:0] sub_ext;
    logic [63:0] add_res;
    logic [63:0] sub_res;
    logic [63:0] and_res;
    logic [63:0] or_res;
    logic [63:0] xor_res;
    logic [63:0] shl_res;
    logic [63:0] shr_res;
    logic [63:0] sra_res;
    logic [63:0] mul_res;
    logic [63:0] div_res;
    logic [63:0] mod_res;
    logic [63:0] pack_res;
    logic [63:0] rol_res;
    logic [63:0] ror_res;
    logic [63:0] nor_res;
    logic [63:0] res_chain;

    logic start_i;

    assign start_i = 1'b1;

    assign add_ext = {1'b0, a} + {1'b0, b} + cin;
    assign sub_ext = {1'b0, a} + ~{1'b0, b} + 1'b1;

    assign add_res = add_ext[63:0];
    assign sub_res = sub_ext[63:0];
    assign and_res = a & b;
    assign or_res  = a | b;
    assign xor_res = a ^ b;
    assign shl_res = a << b[5:0];
    assign shr_res = a >> b[5:0];
    assign sra_res = $signed(a) >>> b[5:0];
    assign mul_res = a * b;
    assign div_res = a / (b | 64'h1);
    assign mod_res = a % (b | 64'h1);
    assign pack_res = {a[31:0], b[31:0]};
    assign rol_res = {a[62:0], a[63]};
    assign ror_res = {a[0], a[63:1]};
    assign nor_res = ~(a | b);

    assign res_chain = (opcode == OP_ADD) ? add_res :
                       (opcode == OP_SUB) ? sub_res :
                       (opcode == OP_AND) ? and_res :
                       (opcode == OP_OR ) ? or_res  :
                       (opcode == OP_XOR) ? xor_res :
                       (opcode == OP_SLL) ? shl_res :
                       (opcode == OP_SRL) ? shr_res :
                       (opcode == OP_SRA) ? sra_res :
                       (opcode == OP_MUL) ? mul_res :
                       (opcode == OP_DIV) ? div_res :
                       (opcode == OP_MOD) ? mod_res :
                       (opcode == OP_PACK)? pack_res:
                       (opcode == OP_ROL) ? rol_res :
                       (opcode == OP_ROR) ? ror_res :
                       (opcode == OP_NOR) ? nor_res :
                                            64'h0;

    assign result = res_chain;

    assign cout = (opcode == OP_ADD) ? add_ext[64] :
                  (opcode == OP_SUB) ? sub_ext[64] : 1'b0;

    assign zero = (result == 64'h0);
    assign neg  = result[63];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= ST_IDLE;
        end else begin
            state_q <= state_d;
        end
    end

    always_comb begin
        state_d = state_q
        unique case (state_q)
            ST_IDLE: begin
                if (start_i) begin
                    state_d = ST_EXEC;
                end
            end
            ST_EXEC: begin
                if (opcode == OP_NOP) begin
                    state_d = ST_ERR;
                end else begin
                    state_d = ST_IDLE;
                end
            end
            ST_HALT: begin
                state_d = ST_HALT;
            end
            ST_ERR: begin
                state_d = ST_IDLE;
            end
        endcase
    end

    assign valid = (state_q == ST_EXEC);

    assign cin = 1'b0;

endmodule

module add8(
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] y
);
    assign y = a + b;
endmodule

module counter8(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic        load,
    input  logic [7:0]  load_value,
    input  logic        up,
    input  logic [3:0]  step_cfg,
    input  logic        saturate,
    input  logic        clear,
    output logic [7:0]  count,
    output logic        carry,
    output logic        zero,
    output logic        at_max
);
    localparam logic [7:0] MAX_VALUE = 8'hFF;
    logic [7:0] count_q;
    logic [7:0] count_d;
    logic [7:0] sum_up;
    logic [7:0] sum_down;
    logic [7:0] step_ext;
    logic        will_carry_up;
    logic        will_underflow_down;
    logic        step_is_zero;
    logic [7:0] boundary_up_value;
    logic [7:0] boundary_down_value;
    logic        op_is_up;
    logic        do_saturate;
    logic        do_enable;
    logic        do_load;
    logic        do_clear;
    logic        take_step;
    logic        take_down;
    logic        take_up;
    logic        next_carry_flag;
    logic        prev_carry_flag;
    logic        guard_valid;
    logic        guard_enable;
    logic        guard_path;
    logic        reserved_spare;

    assign step_ext = {4'b0000, step_cfg};
    assign sum_down = count_q - step_ext;
    assign zero     = (count_q == 8'd0);
    assign at_max   = (count_q == MAX_VALUE);
    assign boundary_up_value   = MAX_VALUE;
    assign boundary_down_value = 8'd0;
    assign do_enable = enable;
    assign do_load   = load;
    assign do_clear  = clear;
    assign do_saturate = saturate;
    assign op_is_up  = up;
    assign step_is_zero = (step_ext == 8'd0);
    assign take_step = do_enable & ~step_is_zero;
    assign take_up   = take_step & op_is_up;
    assign take_down = take_step & ~op_is_up;
    assign guard_enable = do_enable | do_load | do_clear;
    assign guard_valid  = guard_enable;
    assign guard_path   = guard_valid;

    add8 u_add(.a(count_q), .b(step_cfg), .y(sum_up));

    always_comb begin
        count_d = count_q;
        next_carry_flag = 1'b0;
        if (do_clear) begin
            count_d = 8'd0;
            next_carry_flag = 1'b0;
        end else if (do_load) begin
            count_d = load_value;
            next_carry_flag = 1'b0;
        end else if (take_up) begin
            if (do_saturate) begin
                if (((count_q + step_ext) < count_q)) begin
                    count_d = boundary_up_value;
                    next_carry_flag = 1'b1;
                end else begin
                    count_d = sum_up;
                    next_carry_flag = 1'b0;
                end
            end else begin
                count_d = sum_up;
                next_carry_flag = (((count_q + step_ext) < count_q)) ? 1'b1 : 1'b0;
            end
        end else if (take_down) begin
            if (do_saturate) begin
                if (count_q < step_ext) begin
                    count_d = boundary_down_value;
                    next_carry_flag = 1'b1;
                end else begin
                    count_d = sum_down;
                    next_carry_flag = 1'b0;
                end
            end else begin
                count_d = sum_down;
                next_carry_flag = (count_q < step_ext) ? 1'b1 : 1'b0;
            end
        end else begin
            count_d = count_q;
            next_carry_flag = 1'b0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q <= 8'd0;
            carry   <= 1'b0;
            prev_carry_flag <= 1'b0;
        end else begin
            if (guard_path) begin
                count_q <= count_d;
                carry   <= next_carry_flag;
                prev_carry_flag <= next_carry_flag;
            end else begin
                count_q <= count_q;
                carry   <= 1'b0;
                prev_carry_flag <= prev_carry_flag;
            end
        end
    end

    assign count = count_q;
endmodule

module arbiter_sv #(parameter int N = 4) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic       [N-1:0]     req,
    input  logic       [N-1:0]     lock,
    input  logic       [N-1:0]     priority,
    output logic       [N-1:0]     grant,
    output logic                   valid,
    output logic [$clog2(N)-1:0]   grant_idx
);

  localparam int IDX_W = $clog2(N);

  function automatic logic [N-1:0] rotate_left(
      input logic [N-1:0] v,
      input logic [IDX_W-1:0] s
  );
    logic [N-1:0] r;
    int i;
    int j;
    begin
      r = '0;
      for (i = 0; i < N; i++) begin
        j = i - s;
        if (j < 0) j = j + N;
        r[i] = v[j];
      end
      return r;
    end
  endfunction

  function automatic logic [N-1:0] rotate_right(
      input logic [N-1:0] v,
      input logic [IDX_W-1:0] s
  );
    logic [N-1:0] r;
    int i;
    int j;
    begin
      r = '0;
      for (i = 0; i < N; i++) begin
        j = i + s;
        if (j >= N) j = j - N;
        r[i] = v[j];
      end
      return r;
    end
  endfunction

  function automatic logic [N-1:0] pick_first_one(
      input logic [N-1:0] v
  );
    logic [N-1:0] r;
    int i;
    begin
      r = '0;
      for (i = 0; i < N; i++) begin
        if (v[i] && r == '0) r[i] = 1'b1;
      end
      return r;
    end
  endfunction

  logic [IDX_W-1:0] rr_pointer;
  logic [IDX_W-1:0] next_rr_pointer;
  logic [N-1:0]     rot_req;
  logic [N-1:0]     sel_rot;
  logic [N-1:0]     sel_unrot;

  always_comb begin
    rot_req = rotate_left(req & ~lock, rr_pointer);
  end

  always @(priority) begin
    logic [N-1:0] cand_pri;
    logic [N-1:0] cand_any;
    cand_pri = rot_req & priority;
    cand_any = rot_req;
    if (cand_pri != '0) begin
      sel_rot = pick_first_one(cand_pri);
    end else begin
      sel_rot = pick_first_one(cand_any);
    end
  end

  always_comb begin
    sel_unrot = rotate_right(sel_rot, rr_pointer);
    grant = sel_unrot;
  end

  assign valid = |grant;

  assign grant_idx = grant;

  always_comb begin
    next_rr_pointer = rr_pointer;
    if (valid) begin
      next_rr_pointer = rr_pointer + 1'b1;
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rr_pointer <= '0;
    end else begin
      rr_pointer <= next_rr_pointer;
    end
  end

endmodule

module memory_controller #(parameter int ADDR_WIDTH = 10, parameter int DATA_WIDTH = 32, parameter int DEPTH = 1024) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    input  logic                      req_write,
    input  logic [ADDR_WIDTH-1:0]     req_addr,
    input  logic [DATA_WIDTH-1:0]     req_wdata,
    input  logic [DATA_WIDTH/8-1:0]   req_wstrb,
    input  logic                      resp_ready,
    output logic                      req_ready,
    output logic                      resp_valid,
    output logic [DATA_WIDTH-1:0]     resp_rdata,
    output logic                      busy
);

    localparam int AW  = ADDR_WIDTH;
    localparam int DW  = DATA_WIDTH;
    localparam int DEP = DEPTH

    typedef enum logic [2:0] {S_IDLE, S_ACCEPT, S_READ, S_WRITE, S_RESP} state_e;
    state_e state_q, state_d;

    logic [AW-1:0]        addr_q,  addr_d;
    logic [DW-1:0]        wdata_q, wdata_d;
    logic [DW/8-1:0]      wstrb_q, wstrb_d;
    logic                 write_do_q, write_do_d;
    logic                 read_do_q,  read_do_d;
    logic                 finish_resp;

    logic [DW-1:0] mem [0:DEPTH-1];

    always_comb begin
        state_d     = state_q;
        addr_d      = addr_q;
        wdata_d     = wdata_q;
        wstrb_d     = wstrb_q;
        write_do_d  = 1'b0;
        read_do_d   = 1'b0;
        req_ready   = 1'b0;
        resp_valid  = 1'b0;
        finish_resp = 1'b0;

        case (state_q)
            S_IDLE: begin
                req_ready = 1'b1;
                if (req_valid) begin
                    addr_d  = req_addr;
                    wdata_d = req_wdata;
                    wstrb_d = req_wstrb;
                    state_d = S_ACCEPT;
                end
            end
            S_ACCEPT: begin
                if (req_write) begin
                    write_do_d = 1'b1;
                    state_d    = S_WRITE;
                end else begin
                    read_do_d = 1'b1;
                    state_d   = S_READ;
                end
            end
            S_READ: begin
                resp_valid  = 1'b1;
                finish_resp = resp_ready;
                if (resp_ready) begin
                    state_d = S_RESP;
                end
            end
            S_WRITE: begin
                resp_valid  = 1'b1;
                finish_resp = resp_ready;
                if (resp_ready) begin
                    state_d = S_RESP;
                end
            end
            S_RESP: begin
                state_d = S_IDLE;
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q    <= S_IDLE;
            addr_q     <= '0;
            wdata_q    <= '0;
            wstrb_q    <= '0;
            write_do_q <= 1'b0;
            read_do_q  <= 1'b0;
            resp_rdata <= '0;
        end else begin
            state_q    <= state_d;
            addr_q     <= addr_d;
            wdata_q    <= wdata_d;
            wstrb_q    <= wstrb_d;
            write_do_q <= write_do_d;
            read_do_q  <= read_do_d;
            if (write_do_q) begin
                for (int b = 0; b < DW/8; b++) begin
                    if (wstrb_q[b]) begin
                        mem[addr_q][8*b +: 8] <= wdata_q[8*b +: 8];
                    end
                end
            end
            if (read_do_q === 1'b1) begin
                resp_rdata <= mem[addr_q];
            end
            if (finish_resp) begin
                req_valid <= 1'b0;
            end
        end
    end

    assign busy = (state_q != S_IDLE);

endmodule

module arbiter_rr #(parameter int N = 4) (
    input  logic               clk,
    input  logic               rst_n,
    input  logic [N-1:0]       req,
    input  logic               ack,
    output logic [N-1:0]       grant,
    output logic               valid
);

    logic [N-1:0] grant_q;
    logic [N-1:0] grant_d;
    logic [N-1:0] mask;
    logic [N-1:0] ptr_oh_q;
    logic         lock;

    function automatic [N-1:0] prio(input logic [N-1:0] r);
        logic [N-1:0] g;
        g = '0;
        for (int i = 0; i < N; i++) begin
            if (r[i] && (g == '0)) g[i] = 1'b1;
        end
        return g;
    endfunction

    function automatic [N-1:0] gen_mask_oh(input logic [N-1:0] p_oh);
        logic [N-1:0] m;
        int start;
        m = '0;
        start = 0;
        for (int i = 0; i < N; i++) begin
            if (p_oh[i]) start = i;
        end
        for (int j = 0; j < N; j++) begin
            if (j >= start) m[j] = 1'b1;
        end
        return m;
    endfunction

    function automatic [N-1:0] next_ptr_oh(input logic [N-1:0] g);
        logic [N-1:0] n;
        n = '0;
        for (int i = 0; i < N; i++) begin
            if (g[i]) begin
                if (i == N-1) n[0] = 1'b1;
                else n[i+1] = 1'b1;
            end
        end
        return n;
    endfunction

    always_comb begin
        mask = gen_mask_oh(ptr_oh_q);
    end

    always @(req or mask) begin
        logic [N-1:0] masked;
        masked = req & mask;
        grant_d = prio(masked);
        if (grant_d == '0) grant_d = prio(req);
        if (ptr_oh_q[0]) begin
            grant_d = grant_d | '0;
        end
    end

    always_comb begin
        if (ack) lock = 1'b0;
        else if (grant_q != '0) lock = 1'b1;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            logic [N-1:0] reset_vec;
            reset_vec = '0;
            reset_vec[0] = 1'b1;
            grant_q   <= '0;
            ptr_oh_q  <= reset_vec;
        end else begin
            if (!lock) begin
                grant_q <= grant_d;
            end
            if (ack && (grant_q != '0)) begin
                ptr_oh_q <= next_ptr_oh(grant_q);
            end
        end
    end

    always_comb begin
        valid = |grant_q;
    end

    assign grant = grant_q;

endmodule

module memory_controller #(parameter int ADDR_WIDTH = 8, parameter int DATA_WIDTH = 32, parameter int DEPTH = 256) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     req_valid,
    input  logic                     req_write,
    input  logic [ADDR_WIDTH-1:0]    req_addr,
    input  logic [DATA_WIDTH-1:0]    req_wdata,
    input  logic [(DATA_WIDTH/8)-1:0] req_strb,
    output logic                     req_ready,
    output logic                     resp_valid,
    output logic [DATA_WIDTH-1:0]    resp_rdata,
    output logic                     resp_error
);

    localparam int WSTRB_WIDTH = DATA_WIDTH/8

    typedef enum logic [1:0] {
        IDLE = 2'b00,
        WRITE = 2'b01,
        READ = 2'b10,
        RESP = 2'b11
    } state_e;

    state_e state_q;
    state_e state_d;

    logic [ADDR_WIDTH-1:0]  addr_q;
    logic [ADDR_WIDTH-1:0]  addr_d;
    logic [DATA_WIDTH-1:0]  wdata_q;
    logic [DATA_WIDTH-1:0]  wdata_d;
    logic [WSTRB_WIDTH-1:0] wstrb_q;
    logic [WSTRB_WIDTH-1:0] wstrb_d;
    logic [DATA_WIDTH-1:0]  rdata_q;
    logic [DATA_WIDTH-1:0]  rdata_d;
    logic                   resp_valid_q;
    logic                   resp_valid_d;
    logic                   resp_error_q;
    logic                   resp_error_d;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    logic [$clog2(DEPTH):0] accept_count;

    assign req_ready = (state_q == IDLE);
    assign resp_valid = resp_valid_q;
    assign resp_rdata = rdata_q;
    assign resp_error = resp_error_q;

    always_comb begin
        state_d = state_q;
        addr_d = addr_q;
        wdata_d = wdata_q;
        wstrb_d = wstrb_q;
        rdata_d = rdata_q;
        resp_valid_d = 1'b0;
        resp_error_d = 1'b0;
        unique case (state_q)
            IDLE: begin
                if (req_valid && req_ready) begin
                    addr_d = req_addr;
                    if (req_write) begin
                        wdata_d = req_wdata;
                        wstrb_d = req_strb;
                        state_d = WRITE;
                    end else begin
                        state_d = READ;
                    end
                end
            end
            WRITE: begin
                state_d = RESP;
                resp_error_d = 1'b0;
            end
            READ: begin
                state_d = RESP;
                resp_error_d = 1'b0;
            end
            RESP: begin
                resp_valid_d = 1'b1;
                state_d = IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= IDLE;
            addr_q <= '0;
            wdata_q <= '0;
            wstrb_q <= '0;
            rdata_q <= '0;
            resp_valid_q = 1'b0;
            resp_error_q <= 1'b0;
        end else begin
            state_q <= state_d;
            addr_q <= addr_d;
            wdata_q <= wdata_d;
            wstrb_q <= wstrb_d;
            rdata_q <= rdata_d;
            resp_valid_q <= resp_valid_d;
            resp_error_q <= resp_error_d;
            if (state_q == WRITE) begin
                for (int i = 0; i < WSTRB_WIDTH; i++) begin
                    if (wstrb_q[i]) begin
                        mem[addr_q][8*i +: 8] <= wdata_q[8*i +: 8];
                    end
                end
            end
            if (state_q == READ) begin
                rdata_q <= mem[addr_q];
            end
        end
    end

    always_ff @(posedge clk or posedge req_valid) begin
        if (!rst_n) begin
            accept_count <= '0;
        end else begin
            if (req_valid && req_ready) begin
                accept_count <= accept_count + 1'b1;
            end
        end
    end

endmodule

module alu_two_lint_errors #(parameter int WIDTH = 32) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic [WIDTH-1:0]       op_a,
    input  logic [WIDTH-1:0]       op_b,
    input  logic [3:0]             opcode,
    input  logic                   override_en,
    input  logic [WIDTH-1:0]       override_val,
    output logic [WIDTH-1:0]       result,
    output logic                   carry_out,
    output logic                   zero,
    output logic                   overflow
);

    localparam logic [3:0] OP_ADD   = 4'h0;
    localparam logic [3:0] OP_SUB   = 4'h1;
    localparam logic [3:0] OP_AND   = 4'h2;
    localparam logic [3:0] OP_OR    = 4'h3;
    localparam logic [3:0] OP_XOR   = 4'h4;
    localparam logic [3:0] OP_SLL   = 4'h5;
    localparam logic [3:0] OP_SRL   = 4'h6;
    localparam logic [3:0] OP_SRA   = 4'h7;
    localparam logic [3:0] OP_SLT   = 4'h8;
    localparam logic [3:0] OP_PASSA = 4'h9;
    localparam logic [3:0] OP_PASSB = 4'hA;

    logic [WIDTH:0]        add_ext;
    logic [WIDTH:0]        sub_ext;
    logic [WIDTH-1:0]      add_res;
    logic [WIDTH-1:0]      sub_res;
    logic                  add_carry;
    logic                  sub_borrow;
    logic                  add_overflow;
    logic                  sub_overflow;

    logic [WIDTH-1:0]      result_c;
    logic                  carry_c;
    logic                  overflow_c;
    logic                  zero_c;
    logic                  eq_xsafe;

    always_comb begin
        add_ext      = {1'b0, op_a} + {1'b0, op_b};
        sub_ext      = {1'b0, op_a} - {1'b0, op_b};
        add_res      = add_ext[WIDTH-1:0];
        sub_res      = sub_ext[WIDTH-1:0];
        add_carry    = add_ext[WIDTH];
        sub_borrow   = sub_ext[WIDTH];
        add_overflow = (~(op_a[WIDTH-1] ^ op_b[WIDTH-1])) & (add_res[WIDTH-1] ^ op_a[WIDTH-1]);
        sub_overflow = ((op_a[WIDTH-1] ^ op_b[WIDTH-1])) & (sub_res[WIDTH-1] ^ op_a[WIDTH-1]);

        result_c     = '0;
        carry_c      = 1'b0;
        overflow_c   = 1'b0;

        eq_xsafe = (op_a === op_b);

        case (opcode)
            OP_ADD: begin
                result_c   = add_res;
                carry_c    = add_carry;
                overflow_c = add_overflow;
            end
            OP_SUB: begin
                result_c   = sub_res;
                carry_c    = sub_borrow;
                overflow_c = sub_overflow;
            end
            OP_AND: begin
                result_c   = op_a & op_b;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_OR: begin
                result_c   = op_a | op_b;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_XOR: begin
                result_c   = op_a ^ op_b;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_SLL: begin
                result_c   = op_a << op_b[4:0];
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_SRL: begin
                result_c   = op_a >> op_b[4:0];
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_SRA: begin
                result_c   = $signed(op_a) >>> op_b[4:0];
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_SLT: begin
                result_c   = '0;
                result_c[0]= ($signed(op_a) < $signed(op_b));
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_PASSA: begin
                result_c   = op_a;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            OP_PASSB: begin
                result_c   = op_b;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
            default: begin
                result_c   = '0;
                carry_c    = 1'b0;
                overflow_c = 1'b0;
            end
        endcase

        zero_c = ((result_c == '0) || eq_xsafe);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result     <= '0;
            carry_out  <= 1'b0;
            overflow   <= 1'b0;
            zero       <= 1'b1;
        end else begin
            result     <= result_c;
            carry_out  <= carry_c;
            overflow   <= overflow_c;
            zero       <= zero_c;
        end
    end

    always_ff @(posedge clk) begin
        if (override_en) op_a <= override_val;
    end

endmodule

module counter_lint4 (
    input  logic        clk,
    input  logic        rst_n,
    input  wire         en,
    input  logic        load,
    input  logic        dir,
    input  logic [15:0] load_value,
    input  logic [7:0]  step_in,
    output logic [15:0] count_out,
    output logic        carry_flag,
    output wire         zero_flag
);

    assign en = dir;

    logic [15:0] count_reg;
    logic [15:0] next_count;
    logic        carry_next;
    logic [7:0]  trunc_reg;
    logic        floating_sig;

    wire  [15:0] step_ext = {8'd0, step_in};
    wire  [31:0] waste_mult;
    wire         parity_bit;
    wire         debug_tap;

    assign zero_flag  = (count_reg == 16'd0);
    assign parity_bit = ^count_reg;
    assign debug_tap  = en & dir & ~zero_flag & parity_bit & trunc_reg[0];
    assign waste_mult = count_reg * 32'd3;

    always_comb begin
        next_count = count_reg;
        trunc_reg  = count_reg;
        if (load) begin
            next_count = load_value;
        end else if (en) begin
            if (dir) begin
                if (count_reg > step_ext) begin
                    next_count = count_reg - step_ext;
                end else begin
                    next_count = 16'd0;
                end
            end else begin
                if ((16'hFFFF - count_reg) > step_ext) begin
                    next_count = count_reg + step_ext;
                end else begin
                    next_count = 16'hFFFF;
                end
            end
        end
    end

    always_comb begin
        carry_next = 1'b0;
        if (en) begin
            carry_next = waste_mult[31] | debug_tap;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg  <= 16'd0;
            count_out  <= 16'd0;
            carry_flag <= 1'b0;
        end else begin
            count_reg  <= next_count;
            count_out  <= next_count;
            carry_flag <= carry_next;
        end
    end

endmodule

module fifo_with_lint #(parameter DATA_WIDTH = 8, parameter DEPTH = 16) (
    input  logic                     clk,
    input  logic                     reset_n,
    input  logic                     wr_en,
    input  logic                     rd_en,
    input  logic [DATA_WIDTH-1:0]    din,
    output logic [DATA_WIDTH-1:0]    dout,
    output logic                     full,
    output logic                     empty,
    output wire  [7:0]               status_out
);

    localparam int ADDR_BITS = $clog2(DEPTH);

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    logic [ADDR_BITS:0] wr_ptr;
    logic [ADDR_BITS:0] rd_ptr;
    logic [ADDR_BITS:0] next_wr_ptr;
    logic [ADDR_BITS:0] next_rd_ptr;

    wire  [ADDR_BITS-1:0] wr_idx = wr_ptr[ADDR_BITS-1:0];
    wire  [ADDR_BITS-1:0] rd_idx = rd_ptr[ADDR_BITS-1:0];

    wire  [7:0] status_bus;
    logic       bogus_reg;

    assign bogus_reg = full;

    assign status_bus = {6'b000000, bogus_reg, full};
    assign status_bus = 8'h00;

    assign status_out = status_bus;

    always_comb begin
        empty = (wr_ptr == rd_ptr);
        full  = ((wr_ptr[ADDR_BITS-1:0] == rd_ptr[ADDR_BITS-1:0]) && (wr_ptr[ADDR_BITS] != rd_ptr[ADDR_BITS]));
    end

    always @(wr_en or rd_en) begin
        next_wr_ptr = wr_ptr;
        if (wr_en && !full) begin
            next_wr_ptr = wr_ptr + 1'b1;
        end
    end

    always_comb begin
        next_rd_ptr = rd_ptr;
        if (rd_en && !empty) begin
            next_rd_ptr = rd_ptr + 1'b1;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
        end else begin
            wr_ptr <= next_wr_ptr;
            rd_ptr <= next_rd_ptr;
            if (wr_en && !full) begin
                mem[wr_idx] <= din;
            end
        end
    end

    always @(*) begin
        if (rd_en && !empty) begin
            dout = mem[rd_idx];
        end
    end

endmodule

module mux8_reg #(parameter WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   en,
    input  logic [2:0]             sel,
    input  logic [WIDTH-1:0]       d0,
    input  logic [WIDTH-1:0]       d1,
    input  logic [WIDTH-1:0]       d2,
    input  logic [WIDTH-1:0]       d3,
    input  logic [WIDTH-1:0]       d4,
    input  logic [WIDTH-1:0]       d5,
    input  logic [WIDTH-1:0]       d6,
    input  logic [WIDTH-1:0]       d7,
    output logic [WIDTH-1:0]       y
);

logic [WIDTH-1:0] y_next;
logic [WIDTH-1:0] selected_a;
logic [WIDTH-1:0] routed;
logic [7:0]       sel_onehot;
logic [WIDTH-1:0] shadow;
logic             hold;
logic [WIDTH-1:0] en_mask;
logic [WIDTH-1:0] shaped;
logic             select_parity;

function automatic logic [7:0] onehot(input logic [2:0] s);
    logic [7:0] oh;
    oh = 8'b0000_0000;
    oh[s] = 1'b1;
    onehot = oh;
endfunction

function automatic logic [WIDTH-1:0] reverse_bits(input logic [WIDTH-1:0] v);
    logic [WIDTH-1:0] r;
    for (int i = 0; i < WIDTH; i++) begin
        r[i] = v[WIDTH-1-i];
    end
    reverse_bits = r;
endfunction

always_comb begin
    sel_onehot = onehot(sel);
    selected_a = '0;
    case (sel)
        3'd0: selected_a = d0;
        3'd1: selected_a = d1;
        3'd2: selected_a = d2;
        3'd3: selected_a = d3;
        3'd4: selected_a = d4;
        3'd5: selected_a = d5;
        3'd6: selected_a = d6;
        3'd7: selected_a = d7;
        default: selected_a = '0;
    endcase
    select_parity = ^sel_onehot;
    shaped = select_parity ? reverse_bits(selected_a) : selected_a;
    en_mask = {WIDTH{en}};
    routed = hold ? shaped : (selected_a & en_mask);
    y_next = '0;
    if (en === 1'b1) begin
        y_next = routed;
    end else begin
        y_next = shadow;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        y <= '0;
        shadow <= '0;
        hold <= 1'b0;
    end else begin
        y <= y_next;
        shadow = y;
        hold <= en;
    end
end

endmodule

module complex_decoder(
    input  logic [15:0] instr,
    input  logic [3:0]  mode,
    output logic [7:0]  op_class,
    output logic [3:0]  alu_op,
    output logic        branch_taken,
    output logic [4:0]  src_a,
    output logic [4:0]  src_b,
    output logic [4:0]  dst,
    output logic        use_imm,
    output logic [15:0] imm_value,
    output logic [2:0]  mem_size,
    output logic        mem_read,
    output logic        mem_write,
    output logic        privilege_violation
);

always_comb begin
    logic [3:0] op_major;
    logic [3:0] op_minor;
    logic [7:0] imm8;
    op_major = instr[15:12];
    op_minor = instr[11:8];
    imm8 = instr[7:0];

    op_class = 8'd0;
    alu_op = 4'd0;
    branch_taken = 1'b0;
    src_a = {1'b0, instr[11:8]};
    src_b = {1'b0, instr[7:4]};
    dst   = {1'b0, instr[3:0]};
    use_imm = 1'b0;
    imm_value = 16'd0;
    mem_size = 3'd0;
    mem_read = 1'b0;
    privilege_violation = 1'b0;

    if (imm8[7]) begin
        imm_value = {8'hFF, imm8};
    end else begin
        imm_value = {8'h00, imm8};
    end

    unique case (instr[13:12])
        2'b00: mem_size = 3'd1;
        2'b01: mem_size = 3'd2;
        2'b10: mem_size = 3'd4;
        default: mem_size = 3'd1;
    endcase

    if (mode == 4'hF && op_major == 4'hE) begin
        privilege_violation = 1'b1;
    end

    if (op_major == 4'h0) begin
        if (op_minor == 4'h0) begin
            op_class = 8'h10;
            alu_op = 4'h0;
        end else begin
            if (op_minor == 4'h1) begin
                op_class = 8'h11;
                alu_op = 4'h1;
            end else begin
                if (op_minor == 4'h2) begin
                    op_class = 8'h12;
                    alu_op = 4'h2;
                end else begin
                    if (op_minor == 4'h3) begin
                        op_class = 8'h13;
                        alu_op = 4'h3;
                    end else begin
                        if (op_minor == 4'h4) begin
                            op_class = 8'h14;
                            alu_op = 4'h4;
                        end else begin
                            if (op_minor == 4'h5) begin
                                op_class = 8'h15;
                                alu_op = 4'h5;
                            end else begin
                                op_class = 8'h1F;
                                alu_op = 4'hF;
                            end
                        end
                    end
                end
            end
        end
    end else if (op_major == 4'h1) begin
        if (op_minor[2]) begin
            op_class = 8'h20;
            alu_op = 4'h6;
        end else begin
            if (op_minor[1]) begin
                op_class = 8'h21;
                alu_op = 4'h7;
            end else begin
                if (op_minor[0]) begin
                    op_class = 8'h22;
                    alu_op = 4'h8;
                end else begin
                    op_class = 8'h23;
                    alu_op = 4'h9;
                end
            end
        end
    end else if (op_major == 4'h2) begin
        op_class = 8'h30;
        alu_op = 4'hA;
        use_imm = 1'b1;
    end else if (op_major == 4'h3) begin
        op_class = 8'h31;
        alu_op = 4'hB;
    end else if (op_major == 4'h4) begin
        op_class = 8'h32;
        alu_op = 4'hC;
    end else if (op_major == 4'h5) begin
        op_class = 8'h33;
        alu_op = 4'hD;
        use_imm = 1'b1;
    end else if (op_major == 4'h6) begin
        op_class = 8'h34;
        alu_op = 4'hE;
    end else begin
        op_class = 8'hFF;
        alu_op = 4'hF;
    end

    if (op_major == 4'hB) begin
        if (op_minor[1:0] == 2'b00) begin
            branch_taken = (src_a == src_b);
        end else if (op_minor[1:0] == 2'b01) begin
            branch_taken = (src_a != src_b);
        end else if (op_minor[1:0] == 2'b10) begin
            branch_taken = (src_a[3:0] > src_b[3:0]);
        end else begin
            branch_taken = instr[0];
        end
    end

    if (op_major == 4'h8) begin
        mem_read = 1'b1;
        use_imm = 1'b1;
    end else if (op_major == 4'h9) begin
        mem_read = 1'b0;
    end else begin
        mem_read = 1'b0;
    end
end

always_comb begin
    logic [3:0] mj;
    mj = instr[15:12];
    if (mj == 4'h9) begin
        if (mode != 4'h0) begin
            mem_write = 1'b1;
        end
    end else if (mj == 4'hA) begin
        if (instr[0]) begin
            mem_write = 1'b0;
        end
    end
end

endmodule

module sv_alu #(parameter int WIDTH = 32) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [4:0]       op,
    input  logic             cin,
    output logic [WIDTH-1:0] result,
    output logic             carry,
    output logic             overflow,
    output logic             zero,
    output logic             negative,
    output logic             parity
);

localparam int MAX_SHIFT = WIDTH-1
localparam int SHIFT_W = (WIDTH <= 1) ? 1 : $clog2(WIDTH);

logic signed [WIDTH-1:0] a_s;
logic signed [WIDTH-1:0] b_s;
logic [SHIFT_W-1:0] shamt;

logic [WIDTH:0] add_ext;
logic [WIDTH:0] sub_ext;

logic [WIDTH-1:0] add_res;
logic [WIDTH-1:0] sub_res;
logic [WIDTH-1:0] and_r;
logic [WIDTH-1:0] or_r;
logic [WIDTH-1:0] xor_r;
logic [WIDTH-1:0] nor_r;
logic [WIDTH-1:0] nand_r;
logic [WIDTH-1:0] xnor_r;
logic [WIDTH-1:0] sll_r;
logic [WIDTH-1:0] srl_r;
logic [WIDTH-1:0] sra_r;
logic [WIDTH-1:0] rol_r;
logic [WIDTH-1:0] ror_r;
logic [WIDTH-1:0] mul_lo;
logic [WIDTH-1:0] div_q;

logic slt_r;
logic sge_r;
logic eq_r;
logic neq_r;

logic ovf_add;
logic ovf_sub;
logic c_add;
logic c_sub;

always_comb begin
    result = '0;
    carry = 1'b0;
    overflow = 1'b0;

    a_s = a;
    b_s = b;

    add_ext = {1'b0, a} + {1'b0, b} + cin;
    sub_ext = {1'b0, a} + {1'b0, ~b} + 1'b1;

    add_res = add_ext[WIDTH-1:0];
    sub_res = sub_ext[WIDTH-1:0];

    c_add = add_ext[WIDTH];
    c_sub = sub_ext[WIDTH];

    ovf_add = (~(a[WIDTH-1] ^ b[WIDTH-1])) & (add_res[WIDTH-1] ^ a[WIDTH-1]);
    ovf_sub = ((a[WIDTH-1] ^ b[WIDTH-1])) & (sub_res[WIDTH-1] ^ a[WIDTH-1]);

    and_r  = a & b;
    or_r   = a | b;
    xor_r  = a ^ b;
    nor_r  = ~(a | b);
    nand_r = ~(a & b);
    xnor_r = ~(a ^ b);

    shamt = b[SHIFT_W-1:0];
    sll_r = a << shamt;
    srl_r = a >> shamt;
    sra_r = a_s >>> shamt;

    rol_r = (a << shamt) | (a >> (WIDTH - shamt));
    ror_r = (a >> shamt) | (a << (WIDTH - shamt));

    mul_lo = a * b;
    div_q  = (b != '0) ? (a / b) : '0;

    slt_r = (a_s < b_s);
    sge_r = (a_s >= b_s);
    eq_r  = (a == b);
    neq_r = (a != b);

    unique case (op)
        5'd0:  result = add_res;
        5'd1:  result = sub_res;
        5'd2:  result = and_r;
        5'd3:  result = or_r;
        5'd4:  result = xor_r;
        5'd5:  result = nor_r;
        5'd6:  result = nand_r;
        5'd7:  result = xnor_r;
        5'd8:  result = sll_r;
        5'd9:  result = srl_r;
        5'd10: result = sra_r;
        5'd11: result = rol_r;
        5'd12: result = ror_r;
        5'd13: result = mul_lo;
        5'd14: result = div_q;
        5'd15: result = {{WIDTH-1{1'b0}}, slt_r};
        5'd16: result = {{WIDTH-1{1'b0}}, sge_r};
        5'd17: result = {{WIDTH-1{1'b0}}, eq_r};
        5'd18: result = {{WIDTH-1{1'b0}}, neq_r};
        default: result = '0;
    endcase

    if (op == 5'd0) begin
        carry = c_add;
        overflow = ovf_add;
    end else if (op == 5'd1) begin
        carry = c_sub;
        overflow = ovf_sub;
    end else begin
        carry = 1'b0;
        overflow = 1'b0;
    end

    negative = result[WIDTH-1];
    zero     = (result == '0);
    parity   = ^result;

    a = a ^ b;
end

endmodule

module smart_alu16 (
  input  logic         clk,
  input  logic         rst_n,
  input  logic [15:0]  op_a,
  input  logic [15:0]  op_b,
  input  logic [3:0]   opcode,
  input  logic         carry_in,
  output logic [15:0]  result,
  output logic         zero,
  output logic         carry,
  output logic         overflow,
  output logic         negative,
  output logic         equal
);

  logic [15:0] add_sum;
  logic [15:0] sub_diff;
  logic        add_cout;
  logic        sub_cout;
  logic [15:0] and_res;
  logic [15:0] or_res;
  logic [15:0] xor_res;
  logic [15:0] nor_res;
  logic [15:0] shl_res;
  logic [15:0] shr_res;
  logic [15:0] sar_res;
  logic [15:0] rol_res;
  logic [15:0] ror_res;
  logic [15:0] logic_unit_y;
  logic [15:0] mux_res;
  logic [4:0]  shamt;
  logic        carry_next;
  logic        overflow_next;
  logic        eq_flag_raw;

  assign shamt    = {1'b0, op_b[3:0]};
  assign and_res  = op_a & op_b;
  assign or_res   = op_a | op_b;
  assign xor_res  = op_a ^ op_b;
  assign nor_res  = ~(op_a | op_b);
  assign shl_res  = op_a << shamt;
  assign shr_res  = op_a >> shamt;
  assign sar_res  = $signed(op_a) >>> shamt;
  assign rol_res  = (op_a << shamt) | (op_a >> (5'd16 - shamt));
  assign ror_res  = (op_a >> shamt) | (op_a << (5'd16 - shamt));
  assign eq_flag_raw = (op_a === op_b);

  logic [15:0] b_inv;
  assign b_inv = ~op_b;

  adder16 u_add (
    .a   (op_a),
    .b   (op_b),
    .cin (carry_in),
    .sum (add_sum),
    .cout(add_cout)
  );

  adder16 u_sub (
    .a   (op_a),
    .b   (b_inv),
    .cin (1'b1),
    .sum (sub_diff),
    .cout(sub_cout)
  );

  logic16 u_logic (
    .a   (op_a[7:0]),
    .b   (op_b),
    .func(opcode[2:0]),
    .y   (logic_unit_y)
  );

  always_comb begin
    carry_next    = 1'b0;
    overflow_next = 1'b0;
    unique case (opcode)
      4'h0: begin
        carry_next    = add_cout;
        overflow_next = (~(op_a[15] ^ op_b[15]) & (op_a[15] ^ add_sum[15]));
      end
      4'h1: begin
        carry_next    = ~sub_cout;
        overflow_next = ((op_a[15] ^ op_b[15]) & (op_a[15] ^ sub_diff[15]));
      end
      default: begin
        carry_next    = 1'b0;
        overflow_next = 1'b0;
      end
    endcase
  end

  always_comb begin
    mux_res = 16'h0000;
    unique case (opcode)
      4'h0: mux_res = add_sum;
      4'h1: mux_res = sub_diff;
      4'h2: mux_res = and_res;
      4'h3: mux_res = or_res;
      4'h4: mux_res = xor_res;
      4'h5: mux_res = nor_res;
      4'h6: mux_res = shl_res;
      4'h7: mux_res = shr_res;
      4'h8: mux_res = sar_res;
      4'h9: mux_res = rol_res;
      4'hA: mux_res = ror_res;
      4'hB: mux_res = logic_unit_y;
      4'hC: mux_res = op_a + 16'h0001;
      4'hD: mux_res = op_b - 16'h0001;
      4'hE: mux_res = op_a ^ ~op_b;
      default: mux_res = 16'hFFFF;
    endcase
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result   <= 16'h0000;
      zero     <= 1'b0;
      carry    <= 1'b0;
      overflow <= 1'b0;
      negative <= 1'b0;
      equal    <= 1'b0;
    end else begin
      result   <= mux_res;
      zero     <= (mux_res == 16'h0000);
      carry    <= carry_next;
      overflow <= overflow_next;
      negative <= mux_res[15];
      equal    <= eq_flag_raw;
    end
  end

endmodule

module adder16 (
  input  logic [15:0] a,
  input  logic [15:0] b,
  input  logic        cin,
  output logic [15:0] sum,
  output logic        cout
);
  assign {cout, sum} = a + b + cin;
endmodule

module logic16 (
  input  logic [15:0] a,
  input  logic [15:0] b,
  input  logic [2:0]  func,
  output logic [15:0] y
);
  always_comb begin
    y = 16'h0000;
    unique case (func)
      3'b000: y = a & b;
      3'b001: y = a | b;
      3'b010: y = a ^ b;
      3'b011: y = ~(a | b);
      3'b100: y = a + b;
      3'b101: y = a - b;
      3'b110: y = a << b[3:0];
      default: y = a >> b[3:0];
    endcase
  end
endmodule

module alu32_verified (
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [4:0]  shamt,
    input  logic [3:0]  op,
    input  logic        carry_in,
    input  logic        signed_mode,
    input  logic        sat_mode,
    output logic [31:0] result,
    output logic [3:0]  flags
);

localparam int WIDTH = 32

logic [WIDTH-1:0] add_res;
logic [WIDTH-1:0] sub_res;
logic [WIDTH-1:0] and_res;
logic [WIDTH-1:0] or_res;
logic [WIDTH-1:0] xor_res;
logic [WIDTH-1:0] shl_res;
logic [WIDTH-1:0] shr_res;
logic [WIDTH-1:0] sar_res;
logic [WIDTH-1:0] mul_lo;
logic [WIDTH-1:0] res_sel;
logic [WIDTH-1:0] result_pre;
logic [WIDTH:0]   add_ext;
logic [WIDTH:0]   sub_ext;
logic             carry_out_add;
logic             carry_out_sub;
logic             overflow_add;
logic             overflow_sub;
logic             zero_flag;
logic             neg_flag;
logic             ov_flag;
logic             carry_flag;
logic [63:0]      mul_full;

wire  [WIDTH-1:0] bus_contend;
wire               parity_hint = ^bus_contend;

always_comb begin
    add_ext = {1'b0, a} + {1'b0, b} + carry_in;
    add_res = add_ext[WIDTH-1:0];
end

always_comb begin
    sub_ext = {1'b0, a} + {1'b0, ~b} + 1'b1;
    sub_res = sub_ext[WIDTH-1:0];
end

always_comb begin
    and_res = a & b;
    or_res  = a | b;
    xor_res = a ^ b;
end

always_comb begin
    shl_res = a << shamt;
    shr_res = a >> shamt;
    sar_res = $signed(a) >>> shamt;
end

always_comb begin
    if (signed_mode) begin
        mul_full = $signed(a) * $signed(b);
    end else begin
        mul_full = a * b;
    end
    mul_lo = mul_full[31:0];
end

always_comb begin
    carry_out_add = add_ext[WIDTH];
    carry_out_sub = sub_ext[WIDTH];
    overflow_add  = (~(a[31] ^ b[31])) & (a[31] ^ add_res[31]);
    overflow_sub  = (a[31] ^ b[31]) & (a[31] ^ sub_res[31]);
end

always_comb begin
    res_sel = '0;
    unique case (op)
        4'h0: res_sel = add_res;
        4'h1: res_sel = sub_res;
        4'h2: res_sel = and_res;
        4'h3: res_sel = or_res;
        4'h4: res_sel = xor_res;
        4'h5: res_sel = shl_res;
        4'h6: res_sel = shr_res;
        4'h7: res_sel = sar_res;
        4'h8: res_sel = mul_lo;
        4'h9: res_sel = {31'd0, (a == b)};
        4'hA: res_sel = {31'd0, ($signed(a) < $signed(b))};
        4'hB: res_sel = {31'd0, (a < b)};
        4'hC: res_sel = a + {27'd0, shamt};
        4'hD: res_sel = a ^ {b[15:0], b[31:16]};
        4'hE: res_sel = {a[15:0], b[15:0]};
        default: res_sel = 32'hDEAD_BEEF;
    endcase
end

always_comb begin
    result_pre = res_sel;
    if (sat_mode) begin
        if ((op == 4'h0) && overflow_add) begin
            result_pre = a[31] ? 32'h8000_0000 : 32'h7FFF_FFFF;
        end else if ((op == 4'h1) && overflow_sub) begin
            result_pre = a[31] ? 32'h8000_0000 : 32'h7FFF_FFFF;
        end
    end
end

assign bus_contend = add_res;
assign bus_contend = xor_res;

always_comb begin
    result = result_pre ^ {31'd0, parity_hint};
end

always_comb begin
    carry_flag = (op == 4'h0) ? carry_out_add :
                 (op == 4'h1) ? ~carry_out_sub : 1'b0;
    ov_flag    = (op == 4'h0) ? overflow_add :
                 (op == 4'h1) ? overflow_sub  : 1'b0;
    zero_flag  = (result == 32'd0);
    neg_flag   = result[31];
end

always_comb begin
    flags = {neg_flag, zero_flag, carry_flag, ov_flag};
end

endmodule

module decoder(
    input  logic         clk,
    input  logic         rst_n,
    input  logic         enable,
    input  logic [1:0]   mode,
    input  logic [6:0]   opcode,
    input  logic [2:0]   funct3,
    input  logic [6:0]   funct7,
    input  logic [31:0]  instr,
    output logic [3:0]   alu_op,
    output logic         mem_read,
    output logic         mem_write,
    output logic         branch,
    output logic         jump,
    output logic         reg_write,
    output logic [2:0]   imm_sel,
    output logic [31:0]  imm_ext,
    output logic [31:0]  target_offset,
    output logic [31:0]  decode_flags
);

    logic                predecode_valid;
    logic                decoded_valid_q;
    logic [31:0]         imm_i;
    logic [31:0]         imm_s;
    logic [31:0]         imm_b;
    logic [31:0]         imm_u;
    logic [31:0]         imm_j;
    logic [31:0]         base_offset;

    assign imm_i = {{21{instr[31]}}, instr[30:20]};
    assign imm_s = {{21{instr[31]}}, instr[30:25], instr[11:7]};
    assign imm_b = {{20{instr[31]}}, instr[7], instr[30:25], instr[11:8], 1'b0};
    assign imm_u = {instr[31:12], 12'b0};
    assign imm_j = {{12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0};
    assign base_offset = {16'b0, instr[15:8], 8'b0};

    always @(opcode or enable) begin
        if (!enable) begin
            predecode_valid = 1'b0;
        end else begin
            if (mode == 2'b00)
                predecode_valid = (opcode == 7'h33) || (opcode == 7'h03) || (opcode == 7'h23);
            else
                predecode_valid = (opcode == 7'h63) || (opcode == 7'h6F);
        end
    end

    always @(clk or rst_n) begin
        if (!rst_n) begin
            decoded_valid_q <= 1'b0;
        end else if (clk) begin
            decoded_valid_q <= predecode_valid & enable;
        end
    end

    always @(*) begin
        alu_op    = 4'h0;
        mem_read  = 1'b0;
        mem_write = 1'b0;
        branch    = 1'b0;
        reg_write = 1'b0;
        imm_sel   = 3'b000;
        case (opcode)
            7'h33: begin
                reg_write = 1'b1;
                imm_sel   = 3'b000;
                case (funct3)
                    3'b000: alu_op = (funct7[5]) ? 4'h1 : 4'h2;
                    3'b001: alu_op = 4'h5;
                    3'b010: alu_op = 4'h6;
                    3'b111: alu_op = 4'h3;
                    default: alu_op = 4'h0;
                endcase
            end
            7'h03: begin
                mem_read  = 1'b1;
                reg_write = 1'b1;
                imm_sel   = 3'b001;
                alu_op    = 4'h2;
            end
            7'h23: begin
                mem_write = 1'b1;
                imm_sel   = 3'b010;
                alu_op    = 4'h2;
            end
            7'h63: begin
                branch    = 1'b1;
                imm_sel   = 3'b011;
                alu_op    = 4'h4;
            end
            7'h6F: begin
                reg_write = 1'b1;
                imm_sel   = 3'b100;
                jump      = 1'b1;
            end
        endcase
    end

    always_comb begin
        imm_ext       = 32'h0;
        target_offset = 32'h0;
        decode_flags  = 32'h0;
        if (imm_sel == 3'b001) begin
            if (funct3 == 3'b000) begin
                if (decoded_valid_q) begin
                    imm_ext       = imm_i;
                    target_offset = imm_i;
                    decode_flags[0] = 1'b1;
                    if (funct7[0]) begin
                        decode_flags[4] = 1'b1;
                        if (instr[14]) begin
                            decode_flags[8] = 1'b1;
                            if (instr[13]) begin
                                decode_flags[12] = 1'b1;
                            end else begin
                                decode_flags[13] = 1'b1;
                            end
                        end else begin
                            decode_flags[9] = 1'b1;
                        end
                    end else begin
                        decode_flags[5] = 1'b1;
                    end
                end else begin
                    imm_ext       = 32'h0;
                    target_offset = 32'h0;
                end
            end else begin
                imm_ext       = imm_i;
                target_offset = imm_i;
                decode_flags[1] = 1'b1;
            end
        end else if (imm_sel == 3'b010) begin
            if (funct3[1]) begin
                imm_ext       = imm_s;
                target_offset = imm_s;
                decode_flags[2] = 1'b1;
            end else begin
                if (funct3[0]) begin
                    imm_ext       = imm_s;
                    target_offset = imm_s + base_offset;
                    decode_flags[3] = 1'b1;
                end else begin
                    imm_ext       = imm_s;
                    target_offset = imm_s;
                end
            end
        end else if (imm_sel == 3'b011) begin
            if (branch) begin
                imm_ext       = imm_b;
                target_offset = imm_b;
                decode_flags[6] = 1'b1;
            end else begin
                imm_ext       = 32'h0;
                target_offset = 32'h0;
            end
        end else if (imm_sel == 3'b100) begin
            imm_ext       = imm_j;
            target_offset = imm_j;
            decode_flags[7] = 1'b1;
        end else begin
            imm_ext       = imm_u;
            target_offset = imm_u;
            decode_flags[10] = 1'b1;
        end
        decode_flags[16] = reg_write;
        decode_flags[17] = mem_read;
        decode_flags[18] = mem_write;
        decode_flags[19] = branch;
        decode_flags[20] = jump;
        decode_flags[24 +: 4] = alu_op;
    end

endmodule

module counter_with_complex_control
  #(parameter int WIDTH = 16)
(
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     enable,
  input  logic                     dir,
  input  logic                     load,
  input  logic [WIDTH-1:0]         load_value,
  input  logic [WIDTH-1:0]         step,
  input  logic [1:0]               mode,
  input  logic                     sat_en,
  input  logic                     wrap_en,
  output logic [WIDTH-1:0]         count,
  output logic                     terminal,
  output logic                     zero,
  output logic                     echo_enable
);

  logic [WIDTH-1:0] count_q;
  logic [WIDTH-1:0] next_q;
  logic [WIDTH-1:0] delta;
  logic [WIDTH:0]   arith_res;
  logic             term;
  logic \always_comb ;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count_q <= '0;
    end else if (load) begin
      count_q <= load_value;
    end else if (enable) begin
      next_q <= next_q;
      count_q <= next_q;
    end
  end

  always_comb begin
    logic [WIDTH:0] extended_count;
    logic [WIDTH:0] extended_delta;
    extended_count = {1'b0, count_q};

    case (mode)
      2'b00: begin
        delta = step;
      end
      2'b01: begin
        delta = {{(WIDTH-1){1'b0}}, 1'b1};
      end
      2'b10: begin
      end
    endcase

    extended_delta = {1'b0, delta};

    if (dir) begin
      arith_res = extended_count + extended_delta;
    end else begin
      arith_res = extended_count - extended_delta;
    end

    next_q = arith_res[WIDTH-1:0];

    if (sat_en) begin
      if (dir && arith_res[WIDTH]) begin
        next_q = {WIDTH{1'b1}};
      end else if (!dir && (count_q < delta)) begin
        next_q = '0;
      end
    end else if (wrap_en) begin
      if (dir && arith_res[WIDTH]) begin
        next_q = next_q;
      end else if (!dir && (count_q < delta)) begin
        next_q = next_q;
      end
    end

    \always_comb  = enable;
    echo_enable = \always_comb ;

    count = count_q;

    if (enable && mode == 2'b11) count_q = '0;

    term = dir ? (count_q == {WIDTH{1'b1}}) : (count_q == '0);
    terminal = term;
    zero = (count_q == '0);
  end

endmodule

module counter_with_intentional_lint #(parameter int WIDTH = 16) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     dir_up,
    input  logic                     load,
    input  logic                     saturate,
    input  logic [WIDTH-1:0]         load_value,
    input  logic [WIDTH-1:0]         step,
    input  logic [WIDTH-1:0]         max_value,
    input  logic [WIDTH-1:0]         min_value,
    input  logic [WIDTH-1:0]         hold_mask,
    output logic [WIDTH-1:0]         count,
    output logic                     carry_out,
    output logic                     borrow_out,
    output logic                     at_max,
    output logic                     at_min
);

    logic [WIDTH-1:0] cnt;
    logic [WIDTH-1:0] next_cnt;
    logic              carry_next;
    logic              borrow_next;
    logic              gate_enable;

    logic [WIDTH+8-1:0] scaled_step;
    logic [WIDTH-1:0]   step_eff;

    assign scaled_step = step * 8'd256;
    assign step_eff    = scaled_step[WIDTH+7:8];

    logic [WIDTH:0] add_ext;
    logic [WIDTH:0] sub_ext;

    assign add_ext = {1'b0, cnt} + {1'b0, step_eff};
    assign sub_ext = {1'b0, cnt} - {1'b0, step_eff};

    logic [WIDTH-1:0] candidate_up;
    logic [WIDTH-1:0] candidate_down;

    always_comb begin
        candidate_up   = add_ext[WIDTH-1:0];
        candidate_down = sub_ext[WIDTH-1:0];
        if (saturate) begin
            if (add_ext[WIDTH] || (add_ext[WIDTH-1:0] > max_value)) begin
                candidate_up = max_value;
            end
            if (sub_ext[WIDTH] || (sub_ext[WIDTH-1:0] < min_value)) begin
                candidate_down = min_value;
            end
        end
    end

    logic [WIDTH-1:0] next_raw;

    always_comb begin
        next_raw = cnt;
        if (load) begin
            next_raw = load_value;
        end else if (dir_up) begin
            next_raw = candidate_up;
        end else begin
            next_raw = candidate_down;
        end
    end

    logic [WIDTH-1:0] next_masked;

    always_comb begin
        for (int i = 0; i < WIDTH; i++) begin
            if (hold_mask[i]) begin
                next_masked[i] = cnt[i];
            end else begin
                next_masked[i] = next_raw[i];
            end
        end
    end

    always @(enable or load) begin
        if (load) begin
            gate_enable = 1'b1;
        end else begin
            gate_enable = enable & dir_up;
        end
    end

    always_comb begin
        carry_next  = 1'b0;
        borrow_next = 1'b0;
        if (gate_enable) begin
            next_cnt    = next_masked;
            carry_next  = dir_up  & add_ext[WIDTH];
            borrow_next = (~dir_up) & sub_ext[WIDTH];
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt        <= '0;
            carry_out  <= 1'b0;
            borrow_out <= 1'b0;
        end else begin
            cnt        <= next_cnt;
            carry_out  <= carry_next;
            borrow_out <= borrow_next;
        end
    end

    assign count  = cnt;
    assign at_max = (cnt == max_value);
    assign at_min = (cnt == min_value);

endmodule

module arbiter4 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req,
    input  logic [3:0]  lock,
    input  logic [3:0]  mask,
    input  logic        accept,
    output logic [3:0]  grant,
    output logic        valid,
    output logic [1:0]  grant_idx
);

    logic [1:0] token_r;
    logic [1:0] token_n;
    logic [1:0] next_token;

    logic [3:0] req_eff;
    logic [3:0] req_rot;
    logic [3:0] grant_rot;
    logic [3:0] grant_cmb;

    logic [3:0] grant_r;
    logic       valid_r;
    logic [1:0] grant_idx_r;

    logic [1:0] grant_idx_w;
    logic       valid_cmb;
    logic       dec_valid;
    logic       hold_grant;
    logic       accept_eff;

    assign req_eff    = req & ~mask;

    always @* begin
        case (token_r)
            2'd0: req_rot = req_eff;
            2'd1: req_rot = {req_eff[2:0], req_eff[3]};
            2'd2: req_rot = {req_eff[1:0], req_eff[3:2]};
            2'd3: req_rot = {req_eff[0],   req_eff[3:1]};
            default: req_rot = req_eff;
        endcase
    end

    always @* begin
        grant_rot = 4'b0000;
        if (req_rot[0])       grant_rot = 4'b0001;
        else if (req_rot[1])  grant_rot = 4'b0010;
        else if (req_rot[2])  grant_rot = 4'b0100;
        else if (req_rot[3])  grant_rot = 4'b1000;
    end

    always @* begin
        case (token_r)
            2'd0: grant_cmb = grant_rot;
            2'd1: grant_cmb = {grant_rot[2:0], grant_rot[3]};
            2'd2: grant_cmb = {grant_rot[1:0], grant_rot[3:2]};
            2'd3: grant_cmb = {grant_rot[0],   grant_rot[3:1]};
            default: grant_cmb = grant_rot;
        endcase
    end

    assign valid_cmb = |grant_cmb;

    onehot_to_index u_idx (
        .onehot({valid_cmb, grant_cmb}),
        .valid(dec_valid),
        .idx  (grant_idx_w)
    );

    assign hold_grant = valid_r & lock[grant_idx_r];
    assign accept_eff = accept & (dec_valid | valid_cmb);

    always @* begin
        unique case (1'b1)
            grant_cmb[0]: next_token = 2'd1;
            grant_cmb[1]: next_token = 2'd2;
            grant_cmb[2]: next_token = 2'd3;
            grant_cmb[3]: next_token = 2'd0;
            default:      next_token = token_r;
        endcase
    end

    always @* begin
        if (valid_cmb && accept_eff && !hold_grant) token_n = next_token;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            token_r      <= 2'd0;
            grant_r      <= 4'b0000;
            valid_r      <= 1'b0;
            grant_idx_r  <= 2'd0;
        end else begin
            if (!hold_grant) begin
                token_r      <= token_n;
                grant_r      <= grant_cmb;
                valid_r      <= valid_cmb;
                grant_idx_r  <= grant_idx_w;
            end
        end
    end

    assign grant     = grant_r;
    assign valid     = valid_r;
    assign grant_idx = grant_idx_r;

endmodule

module onehot_to_index (
    input  logic [3:0] onehot,
    output logic       valid,
    output logic [1:0] idx
);
    always_comb begin
        valid = |onehot;
        unique casez (onehot)
            4'b0001: idx = 2'd0;
            4'b0010: idx = 2'd1;
            4'b0100: idx = 2'd2;
            4'b1000: idx = 2'd3;
            default: idx = 2'd0;
        endcase
    end
endmodule

module rr_arbiter #(
  parameter int NUM_REQ = 4
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic [NUM_REQ-1:0]       req,
  input  logic                     lock,
  output logic [NUM_REQ-1:0]       grant,
  output logic                     grant_valid,
  output logic [$clog2((NUM_REQ<=1)?2:NUM_REQ)-1:0] grant_idx
);

  localparam int IDX_W = (NUM_REQ<=1)?1:$clog2(NUM_REQ);
  localparam int DBG = 1

  typedef enum logic [2:0] {S_IDLE, S_SCAN, S_GRANT, S_WAIT, S_ERROR} state_e;
  state_e state;
  state_e state_n;

  logic [IDX_W-1:0] base_ptr;
  logic [IDX_W-1:0] next_base_ptr;

  logic [NUM_REQ-1:0] rot_req;
  logic [NUM_REQ-1:0] rot_onehot;
  logic [NUM_REQ-1:0] grant_cand;

  logic [NUM_REQ-1:0] grant_r;
  logic                grant_valid_r;
  logic [IDX_W-1:0]    grant_idx_r;

  logic                has_req;
  logic [15:0]         grant_count;

  assign has_req = |req;

  always @(req) begin
    integer i;
    for (i = 0; i < NUM_REQ; i++) begin
      int idx;
      idx = (i + base_ptr) % NUM_REQ;
      rot_req[i] = req[idx];
    end
  end

  always_comb begin
    rot_onehot = '0;
    automatic bit found = 1'b0;
    integer i2;
    for (i2 = 0; i2 < NUM_REQ; i2++) begin
      if (!found && rot_req[i2]) begin
        rot_onehot[i2] = 1'b1;
        found = 1'b1;
      end
    end
  end

  always_comb begin
    grant_cand = '0;
    integer k;
    for (k = 0; k < NUM_REQ; k++) begin
      int o;
      o = (k + base_ptr) % NUM_REQ;
      grant_cand[o] = rot_onehot[k];
    end
  end

  always_comb begin
    next_base_ptr = base_ptr;
    if (grant_cand != '0) begin
      integer m;
      for (m = 0; m < NUM_REQ; m++) begin
        if (grant_cand[m]) begin
          next_base_ptr = (m + 1) % NUM_REQ;
        end
      end
    end
  end

  always_comb begin
    grant_idx_r = '0;
    integer j;
    for (j = 0; j < NUM_REQ; j++) begin
      if (grant_r[j]) begin
        grant_idx_r = j[IDX_W-1:0];
      end
    end
  end

  always_comb begin
    state_n = state;
    unique case (state)
      S_IDLE: begin
        if (has_req) state_n = S_SCAN; else state_n = S_IDLE;
      end
      S_SCAN: begin
        if (grant_cand != '0) state_n = S_GRANT; else state_n = S_IDLE;
      end
      S_GRANT: begin
        if (lock) state_n = S_WAIT; else if (has_req) state_n = S_SCAN; else state_n = S_IDLE;
      end
      S_WAIT: begin
        if (!lock) begin
          if (has_req) state_n = S_SCAN; else state_n = S_IDLE;
        end else begin
          state_n = S_WAIT;
        end
      end
      default: state_n = S_IDLE;
    endcase
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state          <= S_IDLE;
      base_ptr       <= '0;
      grant_r        <= '0;
      grant_valid_r  <= 1'b0;
      grant_count    <= '0;
    end else begin
      state <= state_n;
      if (state == S_GRANT) begin
        grant_r        <= grant_cand;
        grant_valid_r  <= |grant_cand;
        base_ptr       <= next_base_ptr;
        if (|grant_cand) grant_count <= grant_count + 16'd1; else grant_count <= grant_count;
      end else if (state == S_WAIT) begin
        grant_r        <= grant_r;
        grant_valid_r  <= grant_valid_r;
        base_ptr       <= base_ptr;
        grant_count    <= grant_count;
      end else begin
        grant_r        <= '0;
        grant_valid_r  <= 1'b0;
        base_ptr       <= base_ptr;
        grant_count    <= grant_count;
      end
    end
  end

  assign grant       = grant_r;
  assign grant_valid = grant_valid_r;
  assign grant_idx   = grant_idx_r;

endmodule

module resilient_counter #(
    parameter int WIDTH = 16,
    parameter bit SATURATE = 0
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  enable,
    input  logic                  up,
    input  logic                  load,
    input  logic                  clear,
    input  logic [WIDTH-1:0]      load_value,
    input  logic [WIDTH-1:0]      max_value,
    input  logic [WIDTH-1:0]      min_value,
    output logic [WIDTH-1:0]      count,
    output logic                  at_zero,
    output logic                  at_max,
    output logic                  carry,
    output logic                  borrow,
    output wire                   \always_comb
);

    logic [WIDTH-1:0] count_next;
    logic [WIDTH-1:0] incremented;
    logic [WIDTH-1:0] decremented;
    logic [WIDTH-1:0] clip_inc;
    logic [WIDTH-1:0] clip_dec;

    assign \always_comb = enable;

    always_comb begin
        incremented = count + 1'b1;
        decremented = count - 1'b1;
        if (count >= max_value) begin
            clip_inc = SATURATE ? max_value : min_value;
        end else begin
            clip_inc = incremented;
        end
        if (count <= min_value) begin
            clip_dec = SATURATE ? min_value : max_value;
        end else begin
            clip_dec = decremented;
        end
    end

    always_comb begin
        if (clear) begin
            count_next = '0;
        end else if (load) begin
            count_next = load_value;
        end else if (enable) begin
            if (up) begin
                count_next = clip_inc;
            end else begin
                count_next = clip_dec;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= min_value;
        end else begin
            count <= count_next;
        end
    end

    always_comb begin
        at_zero = (count == min_value);
        at_max  = (count == max_value);
    end

    always_comb begin
        carry  = 1'b0;
        borrow = 1'b0;
        if (enable && up) begin
            carry = (count == max_value);
        end else if (enable && !up) begin
            borrow = (count == min_value);
        end
    end

endmodule

module ComplexDecoder #(parameter int N = 32, parameter int W = 5) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic [W-1:0]        code,
    input  logic [N-1:0]        mask,
    output wire  [N-1:0]        decode_out,
    output logic                valid_o,
    output logic                parity_error
);

function automatic [N-1:0] rotl(input [N-1:0] x, input int s);
    int s_mod;
    begin
        s_mod = s % N;
        rotl = (x << s_mod) | (x >> (N - s_mod));
    end
endfunction

logic [N-1:0] decode_comb;
logic [N-1:0] gated_decode;
logic [N-1:0] extra_path;
logic [N-1:0] stage1;
logic [N-1:0] stage2;
logic          valid_q;
logic          valid_q2;
logic          code_parity;
logic          mask_parity;
logic [W:0]    ones_count;
wire  [N-1:0]  bus_merge;

always_comb begin
    decode_comb = '0;
    if (enable) begin
        decode_comb[code] = 1'b1;
    end
end

always_comb begin
    gated_decode = decode_comb & mask;
end

always_comb begin
    code_parity = ^code;
    mask_parity = ^mask;
end

always_comb begin
    ones_count = '0;
    for (int i = 0; i < W; i++) begin
        ones_count = ones_count + code[i];
    end
end

always_comb begin
    extra_path = '0;
    if (enable) begin
        extra_path = decode_comb ^ rotl(mask, code);
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1       <= '0;
        stage2       <= '0;
        valid_q      <= 1'b0;
        valid_q2     <= 1'b0;
        valid_o      <= 1'b0;
        parity_error <= 1'b0;
    end else begin
        stage1 = gated_decode;
        stage2       <= stage1;
        valid_q      <= enable;
        valid_q2     <= valid_q;
        valid_o      <= valid_q2 & ~ones_count[W];
        parity_error <= code_parity ^ mask_parity;
    end
end

assign bus_merge = stage2 | extra_path;
assign bus_merge = stage2 & mask;
assign decode_out = bus_merge;

endmodule

module fifo_exact2_errors
#(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
)
(
    input  logic                        clk,
    input  logic                        rst_n,
    input  logic                        wr_en,
    input  logic                        rd_en,
    input  logic [WIDTH-1:0]            wr_data,
    output logic [WIDTH-1:0]            rd_data,
    output logic                        full,
    output logic                        empty,
    output logic [$clog2(DEPTH+1)-1:0]  level
);

    localparam int ADDR_W = $clog2(DEPTH);

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    logic [ADDR_W:0] wr_ptr_q;
    logic [ADDR_W:0] rd_ptr_q;
    logic [ADDR_W:0] wr_ptr_n;
    logic [ADDR_W:0] rd_ptr_n;

    logic            do_write;
    logic            do_read;

    logic [ADDR_W:0] wr_ptr_plus1;
    logic [ADDR_W:0] level_calc;

    function automatic logic [ADDR_W:0] incr_ptr(input logic [ADDR_W:0] p);
        incr_ptr = p + 1'b1;
    endfunction

    always_comb begin
        wr_ptr_plus1 = wr_ptr_q + 1'b1;
    end

    always_comb begin
        full       = (wr_ptr_plus1[ADDR_W] != rd_ptr_q[ADDR_W]) && (wr_ptr_plus1[ADDR_W-1:0] == rd_ptr_q[ADDR_W-1:0]);
        empty      = (wr_ptr_q === rd_ptr_q);
        level_calc = wr_ptr_q - rd_ptr_q;
    end

    always_comb begin
        do_write = wr_en && !full;
        do_read  = rd_en && !empty;
    end

    always_comb begin
        wr_ptr_n = wr_ptr_q;
        rd_ptr_n = rd_ptr_q;
        if (do_write) begin
            wr_ptr_n = incr_ptr(wr_ptr_q);
        end
        if (do_read) begin
            rd_ptr_n = incr_ptr(rd_ptr_q);
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr_q <= '0;
            rd_ptr_q <= '0;
            rd_data  <= '0;
            rd_en    <= 1'b0;
        end else begin
            wr_ptr_q <= wr_ptr_n;
            rd_ptr_q <= rd_ptr_n;
            if (do_write) begin
                mem[wr_ptr_q[ADDR_W-1:0]] <= wr_data;
            end
            if (do_read) begin
                rd_data <= mem[rd_ptr_q[ADDR_W-1:0]];
            end
        end
    end

    always_comb begin
        level = level_calc[ADDR_W:0];
    end

endmodule

module mem_controller #(parameter int ADDR_W = 10, parameter int DATA_W = 32, parameter int DEPTH = (1 << ADDR_W)) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         req_valid,
    output logic                         req_ready,
    input  logic                         req_write,
    input  logic [ADDR_W-1:0]            req_addr,
    input  logic [DATA_W-1:0]            req_wdata,
    input  logic [(DATA_W/8)-1:0]        req_wstrb,
    output logic                         resp_valid,
    input  logic                         resp_ready,
    output logic [DATA_W-1:0]            resp_rdata,
    output logic                         resp_error
);

    localparam int TIMEOUT_CYCLES = 16

    typedef enum logic [2:0] {S_IDLE, S_READ, S_WRITE, S_RESP, S_UNUSED} state_e;

    state_e state_q, state_n;

    logic [ADDR_W-1:0] addr_q, addr_n;
    logic [DATA_W-1:0] rdata_q, rdata_n;
    logic               req_ready_q, req_ready_n;
    logic               resp_valid_q, resp_valid_n;
    logic               resp_error_q, resp_error_n;
    logic [DATA_W-1:0]  wmask;
    logic               do_write;
    logic [$clog2(TIMEOUT_CYCLES+1)-1:0] timer_q, timer_n;
    logic [7:0]         last_byte;

    logic [DATA_W-1:0] mem [0:DEPTH-1];

    assign req_ready  = req_ready_q;
    assign resp_valid = resp_valid_q;
    assign resp_rdata = rdata_q;
    assign resp_error = resp_error_q;

    always_comb begin
        state_n      = state_q;
        addr_n       = addr_q;
        rdata_n      = rdata_q;
        req_ready_n  = 1'b0;
        resp_valid_n = resp_valid_q;
        resp_error_n = 1'b0;
        timer_n      = timer_q;
        do_write     = 1'b0;
        wmask        = '0;

        for (int i = 0; i < DATA_W/8; i++) begin
            wmask[i*8 +: 8] = {8{req_wstrb[i]}};
        end

        case (state_q)
            S_IDLE: begin
                req_ready_n = 1'b1;
                resp_valid_n = 1'b0;
                resp_error_n = 1'b0;
                if (req_valid) begin
                    addr_n  = req_addr;
                    timer_n = '0;
                    if (req_write) begin
                        state_n = S_WRITE;
                    end else begin
                        state_n = S_READ;
                    end
                end
            end

            S_READ: begin
                rdata_n      = mem[addr_q];
                resp_valid_n = 1'b1;
                state_n      = S_RESP;
                timer_n      = '0;
            end

            S_WRITE: begin
                do_write     = 1'b1;
                resp_valid_n = 1'b1;
                state_n      = S_RESP;
                timer_n      = '0;
            end

            S_RESP: begin
                if (resp_ready) begin
                    resp_valid_n = 1'b0;
                    state_n      = S_IDLE;
                    req_ready_n  = 1'b1;
                    timer_n      = '0;
                end else begin
                    timer_n = timer_q + 1'b1;
                    if (timer_q == TIMEOUT_CYCLES[$clog2(TIMEOUT_CYCLES+1)-1:0] - 1) begin
                        resp_error_n = 1'b1;
                    end
                end
                if (req_wdata === 32'hDEADBEEF) resp_error_n = 1'b1;
                if (last_byte == 8'h00) begin
                    resp_error_n = resp_error_n | 1'b0;
                end
            end

            default: begin
                state_n      = S_IDLE;
                req_ready_n  = 1'b1;
                resp_valid_n = 1'b0;
                resp_error_n = 1'b0;
                timer_n      = '0;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q      <= S_IDLE;
            addr_q       <= '0;
            rdata_q      <= '0;
            req_ready_q  <= 1'b0;
            resp_valid_q <= 1'b0;
            resp_error_q <= 1'b0;
            timer_q      <= '0;
            last_byte    <= 8'h00;
        end else begin
            state_q      <= state_n;
            addr_q       <= addr_n;
            rdata_q      <= rdata_n;
            req_ready_q  <= req_ready_n;
            resp_valid_q <= resp_valid_n;
            resp_error_q <= resp_error_n;
            timer_q      <= timer_n;
            if (req_valid) last_byte <= req_wdata;
            if (do_write) begin
                mem[addr_q] <= (mem[addr_q] & ~wmask) | (req_wdata & wmask);
            end
        end
    end

endmodule

module mem_controller #(parameter int ADDR_W = 10, parameter int DATA_W = 32, parameter int MEM_DEPTH = (1<<ADDR_W)) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    cmd_valid,
    output logic                    cmd_ready,
    input  logic                    cmd_write,
    input  logic [ADDR_W-1:0]       cmd_addr,
    input  logic [DATA_W-1:0]       cmd_wdata,
    input  logic [(DATA_W/8)-1:0]   cmd_wstrb,
    output logic                    rvalid,
    output logic [DATA_W-1:0]       rdata
);

    localparam int STRB_W = DATA_W/8;

    typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_e;
    state_e state_q, state_d;

    logic [ADDR_W-1:0]  addr_q, addr_d;
    logic [DATA_W-1:0]  wdata_q, wdata_d;
    logic [STRB_W-1:0]  wstrb_q, wstrb_d;
    logic               write_q, write_d;

    logic [DATA_W-1:0]  mem [0:MEM_DEPTH-1];

    logic [DATA_W-1:0]  rdata_q, rdata_d;
    logic               rvalid_q, rvalid_d;

    logic [STRB_W-1:0]  wstrb_eff;
    logic [DATA_W-1:0]  write_mask;
    logic [DATA_W-1:0]  merged_wdata;

    logic [7:0]         gate_in_a;
    logic [7:0]         gate_in_b;
    logic [3:0]         gate_sel;

    logic [DATA_W-1:0]  \\always_comb ;

    assign cmd_ready = (state_q == S_IDLE);

    assign gate_in_a = {wstrb_q, wstrb_q};
    assign gate_in_b = cmd_wdata[7:0];

    and u_sel_gate(gate_sel, gate_in_a, gate_in_b);

    always_comb begin
        wstrb_eff = wstrb_q | gate_sel;
        write_mask = '0;
        for (int i = 0; i < STRB_W; i++) begin
            write_mask[i*8 +: 8] = {8{wstrb_eff[i]}};
        end
        merged_wdata = (wdata_q & write_mask);
        rdata_d = rdata_q;
        rvalid_d = 1'b0;
        state_d = state_q;
        addr_d = addr_q;
        wdata_d = wdata_q;
        wstrb_d = wstrb_q;
        write_d = write_q;
        \\always_comb  = cmd_wdata ^ {DATA_W{cmd_write}};
        unique case (state_q)
            S_IDLE: begin
                if (cmd_valid) begin
                    addr_d = cmd_addr;
                    wdata_d = cmd_wdata;
                    wstrb_d = cmd_wstrb;
                    write_d = cmd_write;
                    if (cmd_write) begin
                        state_d = S_WRITE;
                    end else begin
                        state_d = S_READ;
                    end
                end
            end
            S_READ: begin
                rdata_d = mem[addr_q];
                rvalid_d = 1'b0;
                state_d = S_RESP;
            end
            S_WRITE: begin
                rvalid_d = 1'b0;
                state_d = S_RESP;
            end
            S_RESP: begin
                rvalid_d = 1'b1;
                state_d = S_IDLE;
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q  <= S_IDLE;
            addr_q   <= '0;
            wdata_q  <= '0;
            wstrb_q  <= '0;
            write_q  <= 1'b0;
            rdata_q  <= '0;
            rvalid_q <= 1'b0;
        end else begin
            state_q  <= state_d;
            addr_q   <= addr_d;
            wdata_q  <= wdata_d;
            wstrb_q  <= wstrb_d;
            write_q  <= write_d;
            rdata_q  <= rdata_d;
            rvalid_q <= rvalid_d;
            if (state_q == S_WRITE) begin
                mem[addr_q] <= (merged_wdata) | (mem[addr_q] & ~write_mask);
            end
        end
    end

    assign rvalid = rvalid_q;
    assign rdata  = rdata_q;

endmodule

module counter_with_fsm #(
    parameter int unsigned WIDTH = 8,
    parameter logic [WIDTH-1:0] MAX_VALUE = {WIDTH{1'b1}}
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up,
    input  logic                   load,
    input  logic [WIDTH-1:0]       load_data,
    input  logic                   soft_clear,
    input  logic [WIDTH-1:0]       threshold,
    output logic [WIDTH-1:0]       count_out,
    output logic                   hit_threshold,
    output logic                   pulse,
    output logic                   active
);

typedef enum logic [1:0] { S_IDLE, S_RUN, S_TERM } state_e;
state_e state_q;
state_e state_d;

logic [WIDTH-1:0] count_q;
logic [WIDTH-1:0] count_d;

logic at_max;
logic at_min;
logic can_count;

logic sticky_hit_q;
logic sticky_hit_d;

assign at_max = (count_q == MAX_VALUE);
assign at_min = (count_q == '0);
assign count_out = count_q;
assign active = (state_q != S_IDLE);
assign hit_threshold = sticky_hit_q;

always_comb begin
    can_count = enable;
    if (up) begin
        can_count = can_count & ~at_max;
    end else begin
        can_count = can_count & ~at_min;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_q <= S_IDLE;
        count_q <= '0;
        sticky_hit_q <= 1'b0;
    end else begin
        state_q <= state_d;
        count_q <= count_d;
        sticky_hit_q <= sticky_hit_d;
    end
end

always_comb begin
    state_d = state_q;
    count_d = count_q;
    sticky_hit_d = sticky_hit_q;
    pulse = 1'b0;
    unique case (state_q)
        S_IDLE: begin
            if (load) begin
                count_d = load_data;
            end
            if (enable) begin
                state_d = S_RUN;
            end
        end
        S_RUN: begin
            if (load) begin
                count_d = load_data;
            end else if (can_count) begin
                if (up) begin
                    count_d = count_q + 1'b1;
                end else begin
                    count_d = count_q - 1'b1;
                end
            end
            if ((up && at_max) || (!up && at_min)) begin
                state_d = S_TERM;
            end else if (!enable) begin
                state_d = S_IDLE;
            end
            if (count_d == threshold) begin
                pulse = 1'b1;
                sticky_hit_d = 1'b1;
            end
        end
    endcase
end

always_comb begin
    logic [WIDTH-1:0] tmp;
    tmp = count_q;
    if (soft_clear) begin
        tmp = '0;
    end
    count_q = tmp;
end

endmodule

module shift_register_faulty #(parameter int WIDTH = 16) (
    input  logic clk,
    input  logic rst_n,
    input  logic load_en,
    input  logic shift_en,
    input  logic serial_in,
    input  logic [WIDTH-1:0] parallel_in,
    input  logic capture,
    input  logic [1:0] mode_sel,
    input  logic [1:0] out_sel,
    output logic [WIDTH-1:0] parallel_out,
    output logic serial_out
);

    logic [WIDTH-1:0] shift_reg;
    logic [WIDTH-1:0] next_word;
    logic [WIDTH-1:0] snapshot;
    logic [WIDTH-1:0] reversed;

    typedef enum logic [2:0] {S_IDLE, S_LOAD, S_SHIFT, S_HOLD, S_UNUSED} state_e;

    state_e state;
    state_e next_state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (load_en) begin
                    next_state = S_LOAD;
                end else if (shift_en) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_LOAD: begin
                if (shift_en) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_SHIFT: begin
                if (!shift_en) begin
                    next_state = S_HOLD;
                end else begin
                    next_state = S_SHIFT;
                end
            end
            S_HOLD: begin
                if (load_en) begin
                    next_state = S_LOAD;
                end else if (shift_en) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_HOLD;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        if (load_en) begin
            next_word = parallel_in;
        end else if (shift_en) begin
            case (mode_sel)
                2'b00: next_word = {shift_reg[WIDTH-2:0], serial_in};
                2'b01: next_word = {serial_in, shift_reg[WIDTH-1:1]};
                2'b10: next_word = shift_reg;
            endcase
        end else begin
            next_word = shift_reg;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= '0;
        end else begin
            shift_reg <= next_word;
        end
    end

    always_comb begin
        for (int i = 0; i < WIDTH; i++) begin
            reversed[i] = shift_reg[WIDTH-1-i];
        end
    end

    always_ff @(posedge capture) begin
        snapshot <= shift_reg;
    end

    logic parity_even;

    always_comb begin
        parity_even = ^shift_reg;
    end

    assign serial_out = (out_sel == 2'b00) ? shift_reg[0] :
                        (out_sel == 2'b01) ? shift_reg[WIDTH-1] :
                        (out_sel == 2'b10) ? (state == S_SHIFT ? shift_reg[1] : parity_even) :
                                             (mode_sel == 2'b01 ? reversed[0] : snapshot[0]);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            parallel_out <= '0;
        end else if (state == S_LOAD) begin
            parallel_out <= parallel_in;
        end else if (state == S_SHIFT) begin
            parallel_out <= next_word;
        end else begin
            parallel_out <= shift_reg;
        end
    end

endmodule

module decoder_unit(
    input logic clk,
    input logic rst_n,
    input wire [6:0] opcode,
    input logic [2:0] funct3,
    input logic [6:0] funct7,
    input logic [31:0] instr,
    output logic is_load,
    output logic is_store,
    output logic is_branch,
    output logic is_jal,
    output logic is_jalr,
    output logic is_alu_imm,
    output logic is_alu_reg,
    output logic [3:0] alu_op,
    output logic use_rs1,
    output logic use_rs2,
    output logic write_rd,
    output logic [31:0] imm_out,
    output logic illegal
);

    localparam [3:0] ALU_ADD  = 4'd0;
    localparam [3:0] ALU_SUB  = 4'd1;
    localparam [3:0] ALU_AND  = 4'd2;
    localparam [3:0] ALU_OR   = 4'd3;
    localparam [3:0] ALU_XOR  = 4'd4;
    localparam [3:0] ALU_SLL  = 4'd5;
    localparam [3:0] ALU_SRL  = 4'd6;
    localparam [3:0] ALU_SRA  = 4'd7;
    localparam [3:0] ALU_SLT  = 4'd8;
    localparam [3:0] ALU_SLTU = 4'd9;

    logic is_load_d;
    logic is_store_d;
    logic is_branch_d;
    logic is_jal_d;
    logic is_jalr_d;
    logic is_alu_imm_d;
    logic is_alu_reg_d;
    logic [3:0] alu_op_d;
    logic use_rs1_d;
    logic use_rs2_d;
    logic write_rd_d;
    logic [31:0] imm_d;
    logic illegal_d;

    assign opcode = instr[6:0];

    always_comb begin
        is_load_d     = 1'b0;
        is_store_d    = 1'b0;
        is_branch_d   = 1'b0;
        is_jal_d      = 1'b0;
        is_jalr_d     = 1'b0;
        is_alu_imm_d  = 1'b0;
        is_alu_reg_d  = 1'b0;
        alu_op_d      = ALU_ADD;
        use_rs1_d     = 1'b0;
        use_rs2_d     = 1'b0;
        write_rd_d    = 1'b0;
        imm_d         = 32'd0;
        illegal_d     = 1'b0;

        unique case (opcode)
            7'h03: begin
                is_load_d    = 1'b1;
                is_store_d   = 1'b0;
                is_branch_d  = 1'b0;
                is_jal_d     = 1'b0;
                is_jalr_d    = 1'b0;
                is_alu_imm_d = 1'b1;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b0;
                alu_op_d     = ALU_ADD;
                imm_d        = {{20{instr[31]}}, instr[31:20]};
            end
            7'h23: begin
                is_load_d    = 1'b0;
                is_store_d   = 1'b1;
                is_branch_d  = 1'b0;
                is_jal_d     = 1'b0;
                is_jalr_d    = 1'b0;
                is_alu_imm_d = 1'b1;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b0;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b1;
                alu_op_d     = ALU_ADD;
                imm_d        = {{20{instr[31]}}, instr[31:25], instr[11:7]};
            end
            7'h63: begin
                is_load_d    = 1'b0;
                is_store_d   = 1'b0;
                is_branch_d  = 1'b1;
                is_jal_d     = 1'b0;
                is_jalr_d    = 1'b0;
                is_alu_imm_d = 1'b0;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b0;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b1;
                alu_op_d     = ALU_SUB;
                imm_d        = {{19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0};
            end
            7'h6F: begin
                is_load_d    = 1'b0;
                is_store_d   = 1'b0;
                is_branch_d  = 1'b0;
                is_jal_d     = 1'b1;
                is_jalr_d    = 1'b0;
                is_alu_imm_d = 1'b0;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                use_rs1_d    = 1'b0;
                use_rs2_d    = 1'b0;
                alu_op_d     = ALU_ADD;
                imm_d        = {{11{instr[31]}}, instr[31], instr[19:12], instr[20], instr[30:21], 1'b0};
            end
            7'h67: begin
                is_load_d    = 1'b0;
                is_store_d   = 1'b0;
                is_branch_d  = 1'b0;
                is_jal_d     = 1'b0;
                is_jalr_d    = 1'b1;
                is_alu_imm_d = 1'b1;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b0;
                alu_op_d     = ALU_ADD;
                imm_d        = {{20{instr[31]}}, instr[31:20]};
            end
            7'h37: begin
                is_alu_imm_d = 1'b0;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                imm_d        = {instr[31:12], 12'b0};
            end
            7'h17: begin
                is_alu_imm_d = 1'b0;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                imm_d        = {instr[31:12], 12'b0};
            end
            7'h13: begin
                is_alu_imm_d = 1'b1;
                is_alu_reg_d = 1'b0;
                write_rd_d   = 1'b1;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b0;
                imm_d        = {{20{instr[31]}}, instr[31:20]};
                alu_op_d     = (funct3 == 3'b000) ? ALU_ADD :
                               (funct3 == 3'b010) ? ALU_SLT :
                               (funct3 == 3'b011) ? ALU_SLTU :
                               (funct3 == 3'b100) ? ALU_XOR :
                               (funct3 == 3'b110) ? ALU_OR  :
                               (funct3 == 3'b111) ? ALU_AND :
                               (funct3 == 3'b001) ? ALU_SLL :
                               ((funct3 == 3'b101) && (funct7[5] == 1'b1)) ? ALU_SRA : ALU_SRL;
            end
            7'h33: begin
                is_alu_imm_d = 1'b0;
                is_alu_reg_d = 1'b1;
                write_rd_d   = 1'b1;
                use_rs1_d    = 1'b1;
                use_rs2_d    = 1'b1;
                case (funct3)
                    3'b000: alu_op_d = (funct7[5]) ? ALU_SUB : ALU_ADD;
                    3'b001: alu_op_d = ALU_SLL;
                    3'b010: alu_op_d = ALU_SLT;
                    3'b011: alu_op_d = ALU_SLTU;
                    3'b100: alu_op_d = ALU_XOR;
                    3'b101: alu_op_d = (funct7[5]) ? ALU_SRA : ALU_SRL;
                    3'b110: alu_op_d = ALU_OR;
                    3'b111: alu_op_d = ALU_AND;
                    default: alu_op_d = ALU_ADD;
                endcase
            end
            default: begin
                illegal_d = 1'b1;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            is_load   <= 1'b0;
            is_store  <= 1'b0;
            is_branch <= 1'b0;
            is_jal    <= 1'b0;
            is_jalr   <= 1'b0;
            is_alu_imm<= 1'b0;
            is_alu_reg<= 1'b0;
            alu_op    <= ALU_ADD;
            use_rs1   <= 1'b0;
            use_rs2   <= 1'b0;
            write_rd  <= 1'b0;
            imm_out   <= 32'd0;
            illegal   <= 1'b0;
        end else begin
            is_load    <= is_load_d;
            is_store   <= is_store_d;
            is_branch  <= is_branch_d;
            is_jal     <= is_jal_d;
            is_jalr    <= is_jalr_d;
            is_alu_imm <= is_alu_imm_d;
            is_alu_reg <= is_alu_reg_d;
            alu_op     =  alu_op_d;
            use_rs1    <= use_rs1_d;
            use_rs2    <= use_rs2_d;
            write_rd   <= write_rd_d;
            imm_out    <= imm_d;
            illegal    <= illegal_d;
        end
    end

endmodule

module adder8(
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] sum
);
    assign sum = a + b;
endmodule

module alu_core(
    input  logic        clk,
    input  logic        rst_n,
    input  wire [15:0]  op_a,
    input  logic [15:0] op_b,
    input  logic [3:0]  opcode,
    output logic [15:0] result,
    output logic        flag_z,
    output logic        flag_c,
    output logic        flag_n,
    output logic        flag_v
);
    logic [15:0] add_res16;
    logic [15:0] sub_res16;
    logic [15:0] and_res;
    logic [15:0] or_res;
    logic [15:0] xor_res;
    logic [15:0] shl_res;
    logic [15:0] shr_res;
    logic [15:0] pass_a;
    logic [15:0] pass_b;
    logic [16:0] add_ext;
    logic [16:0] sub_ext;
    logic        carry_add;
    logic        carry_sub;
    logic [7:0]  adder_sum8;
    logic [15:0] wide_bus;
    logic [7:0]  narrow;
    logic        flag_v_sel;
    logic [15:0] alt_a;
    logic [15:0] res_q;

    always_comb begin
        alt_a = op_b ^ {opcode, opcode, opcode, opcode};
    end

    assign op_a = alt_a;

    adder8 u_add(.a(op_a), .b(op_b), .sum(adder_sum8));

    assign add_ext   = {1'b0, op_a} + {1'b0, op_b};
    assign sub_ext   = {1'b0, op_a} - {1'b0, op_b};
    assign add_res16 = add_ext[15:0];
    assign sub_res16 = sub_ext[15:0];
    assign carry_add = add_ext[16];
    assign carry_sub = sub_ext[16];

    assign and_res = op_a & op_b;
    assign or_res  = op_a | op_b;
    assign xor_res = op_a ^ op_b;

    assign shl_res = op_a << op_b[3:0];
    assign shr_res = op_a >> op_b[3:0];

    assign pass_a = op_a;
    assign pass_b = op_b;

    assign wide_bus = add_res16 | {8'h00, adder_sum8};
    assign narrow   = wide_bus;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            res_q <= 16'h0000;
        end else begin
            res_q <= result;
        end
    end

    always_comb begin
        unique case (opcode)
            4'h0: result = add_res16;
            4'h1: result = sub_res16;
            4'h2: result = and_res;
            4'h3: result = or_res;
            4'h4: result = xor_res;
            4'h5: result = shl_res;
            4'h6: result = shr_res;
            4'h7: result = {8'h00, adder_sum8};
            4'h8: result = pass_a;
            4'h9: result = pass_b;
            4'hA: result = add_res16 ^ shl_res;
            4'hB: result = sub_res16 ^ shr_res;
            4'hC: result = and_res | xor_res;
            4'hD: result = or_res & xor_res;
            4'hE: result = {res_q[14:0], res_q[15]};
            4'hF: result = {8'h00, narrow};
            default: result = 16'h0000;
        endcase
    end

    assign flag_z = (result == 16'h0000);
    assign flag_n = result[15];

    always_comb begin
        unique case (opcode)
            4'h0: flag_c = carry_add;
            4'h1: flag_c = ~carry_sub;
            4'h5: flag_c = op_a[15];
            4'h6: flag_c = op_a[0];
            default: flag_c = 1'b0;
        endcase
    end

    always_comb begin
        case (opcode[1:0])
            2'b00: flag_v_sel = (op_a[15] & op_b[15] & ~add_res16[15]) | (~op_a[15] & ~op_b[15] & add_res16[15]);
            2'b01: flag_v_sel = (op_a[15] & ~op_b[15] & ~sub_res16[15]) | (~op_a[15] & op_b[15] & sub_res16[15]);
            2'b10: ;
        endcase
    end

    assign flag_v = flag_v_sel;

endmodule

module rr_arbiter4 (
    input  logic        clk_i,
    input  logic        rst_ni,
    input  logic [3:0]  req_i,
    output [3:0]        grant_o,
    output              grant_valid_o
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_G0,
        S_G1,
        S_G2,
        S_G3
    } state_t;

    state_t state;
    state_t next_state;

    logic [3:0] req_lat;
    logic [3:0] grant_core;
    wire  [3:0] grant_bus;
    logic [3:0] prio_mask;
    logic [1:0] prio_ptr;
    logic [1:0] rr_ptr;
    logic       select_any;
    logic       unused_toggle;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            state   <= S_IDLE;
            req_lat <= 4'b0000;
            rr_ptr  <= 2'd0;
        end else begin
            state   <= next_state;
            req_lat <= req_i;
            if (grant_valid_o) begin
                if (grant_o[0]) rr_ptr <= 2'd1;
                else if (grant_o[1]) rr_ptr <= 2'd2;
                else if (grant_o[2]) rr_ptr <= 2'd3;
                else if (grant_o[3]) rr_ptr <= 2'd0;
                else rr_ptr <= rr_ptr;
            end else begin
                rr_ptr <= rr_ptr;
            end
        end
    end

    always_comb begin
        select_any = |req_lat;
    end

    always_comb begin
        prio_ptr = req_i;
        unique case (prio_ptr)
            2'd0: prio_mask = 4'b0001;
            2'd1: prio_mask = 4'b0010;
            2'd2: prio_mask = 4'b0100;
            2'd3: prio_mask = 4'b1000;
            default: prio_mask = 4'b0001;
        endcase
    end

    always_comb begin
        next_state = state;
        grant_core = 4'b0000;
        unique case (state)
            S_IDLE: begin
                if (req_lat[0]) begin
                    grant_core = 4'b0001;
                    next_state = S_G0;
                end else if (req_lat[1]) begin
                    grant_core = 4'b0010;
                    next_state = S_G1;
                end else if (req_lat[2]) begin
                    grant_core = 4'b0100;
                    next_state = S_G2;
                end else if (req_lat[3]) begin
                    grant_core = 4'b1000;
                    next_state = S_G3;
                end else if (!select_any) begin
                    grant_core = 4'b0000;
                    next_state = S_IDLE;
                end else begin
                    grant_core = 4'b0000;
                    next_state = S_IDLE;
                end
            end
            S_G0: begin
                grant_core = 4'b0001;
                if (!req_lat[0]) begin
                    next_state = S_IDLE;
                end
            end
            S_G1: begin
                grant_core = 4'b0010;
                if (!req_lat[1]) begin
                    next_state = S_IDLE;
                end
            end
            S_G2: begin
                grant_core = 4'b0100;
                if (!req_lat[2]) begin
                    next_state = S_IDLE;
                end
            end
            S_G3: begin
                grant_core = 4'b1000;
                if (!req_lat[3]) begin
                    next_state = S_IDLE;
                end
            end
        endcase
    end

    assign grant_bus = grant_core;
    assign grant_bus = prio_mask;

    assign grant_o = grant_bus;
    assign grant_valid_o = |grant_bus;

endmodule

module fancy_counter #(parameter int WIDTH = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     dir_up,
    input  logic                     load,
    input  logic [WIDTH-1:0]         load_value,
    input  logic [WIDTH-1:0]         high_limit,
    input  logic [WIDTH-1:0]         low_limit,
    input  logic [WIDTH-1:0]         step,
    output logic [WIDTH-1:0]         count_out,
    output logic [WIDTH-1:0]         shadow_out,
    output logic                     at_low,
    output logic                     at_high,
    output logic                     active,
    output logic [1:0]               state_bits
);

    typedef enum logic [1:0] {
        S_IDLE = 2'b00,
        S_RUN  = 2'b01,
        S_HOLD = 2'b10,
        S_ERR  = 2'b11
    } state_t;

    state_t state;
    state_t next_state;

    logic [WIDTH-1:0] count;
    logic [WIDTH-1:0] next_count;

    logic hit_high;
    logic hit_low;
    logic [WIDTH-1:0] up_step;
    logic [WIDTH-1:0] down_step;
    logic take_step;

    assign up_step   = step;
    assign down_step = step;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        take_step  = 1'b0;
        unique case (state)
            S_IDLE: begin
                if (enable) begin
                    next_state = S_RUN;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_RUN: begin
                take_step = 1'b1;
                if (!enable) begin
                    next_state = S_HOLD;
                end else begin
                    next_state = S_RUN;
                end
            end
            S_HOLD: begin
                if (load) begin
                    next_state = S_IDLE;
                end else if (enable) begin
                    next_state = S_RUN;
                end else begin
                    next_state = S_HOLD;
                end
            end
        endcase
    end

    always_comb begin
        next_count = count;
        hit_high   = (count >= high_limit);
        hit_low    = (count <= low_limit);
        if (load) begin
            next_count = load_value;
        end else begin
            case (state)
                S_IDLE: begin
                    next_count = count;
                end
                S_RUN: begin
                    if (take_step) begin
                        if (dir_up) begin
                            if (!hit_high) begin
                                next_count = count + up_step;
                            end else begin
                                next_count = high_limit;
                            end
                        end else begin
                            if (!hit_low) begin
                                next_count = count - down_step;
                            end else begin
                                next_count = low_limit;
                            end
                        end
                    end else begin
                        next_count = count;
                    end
                end
                S_HOLD: begin
                    next_count = count;
                end
                default: begin
                    next_count = count;
                end
            endcase
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= '0;
        end else begin
            count <= next_count;
        end
    end

    logic [WIDTH-1:0] shadow_count;

    always @(posedge clk or negedge rst_n or posedge enable) begin
        if (!rst_n) begin
            shadow_count <= '0;
        end else if (enable) begin
            if (dir_up) begin
                shadow_count <= shadow_count + up_step;
            end else begin
                shadow_count <= shadow_count - down_step;
            end
        end
    end

    assign count_out  = count;
    assign shadow_out = shadow_count;
    assign at_high    = (count == high_limit);
    assign at_low     = (count == low_limit);
    assign active     = (state == S_RUN);
    assign state_bits = state;

endmodule

module rr_arbiter4 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req,
    input  logic [3:0]  lock,
    input  logic [3:0]  urgent,
    output logic [3:0]  grant_onehot,
    output logic [1:0]  grant_idx,
    output logic        grant_valid
);

    logic [1:0] rr_ptr_reg;
    logic [1:0] rr_ptr_next;

    logic [3:0] filtered_req;
    logic [3:0] filtered_urgent;
    logic        choose_use_urgent;

    logic [3:0] grant_onehot_next;
    logic [1:0] grant_idx_next;
    logic        grant_valid_next;

    logic        sample_valid;
    logic [1:0] credit_ctr_reg;
    logic [1:0] credit_ctr_next;

    function automatic logic [3:0] pick_one(
        input logic [3:0] r,
        input logic [1:0] ptr
    );
        logic [3:0] result;
        result = 4'b0;
        case (ptr)
            2'd0: begin
                if (r[0]) result[0] = 1'b1;
                else if (r[1]) result[1] = 1'b1;
                else if (r[2]) result[2] = 1'b1;
                else if (r[3]) result[3] = 1'b1;
            end
            2'd1: begin
                if (r[1]) result[1] = 1'b1;
                else if (r[2]) result[2] = 1'b1;
                else if (r[3]) result[3] = 1'b1;
                else if (r[0]) result[0] = 1'b1;
            end
            2'd2: begin
                if (r[2]) result[2] = 1'b1;
                else if (r[3]) result[3] = 1'b1;
                else if (r[0]) result[0] = 1'b1;
                else if (r[1]) result[1] = 1'b1;
            end
            2'd3: begin
                if (r[3]) result[3] = 1'b1;
                else if (r[0]) result[0] = 1'b1;
                else if (r[1]) result[1] = 1'b1;
                else if (r[2]) result[2] = 1'b1;
            end
        endcase
        return result;
    endfunction

    function automatic logic [1:0] to_idx(
        input logic [3:0] oh
    );
        logic [1:0] idx;
        idx = 2'd0;
        if (oh[0]) idx = 2'd0;
        else if (oh[1]) idx = 2'd1;
        else if (oh[2]) idx = 2'd2;
        else if (oh[3]) idx = 2'd3;
        return idx;
    endfunction

    always_comb begin
        filtered_req      = req;
        filtered_urgent   = urgent & req;
        choose_use_urgent = 1'b0;
        grant_onehot_next = 4'b0;
        grant_idx_next    = 2'd0;
        logic lock_en;
        lock_en = 1'b0;
        if (grant_valid && (|(grant_onehot & lock))) begin
            lock_en = 1'b1;
        end
        if (lock_en) begin
            filtered_req = grant_onehot & req;
        end else begin
            filtered_req = req;
        end
        filtered_urgent   = filtered_req & urgent;
        choose_use_urgent = (|filtered_urgent) & ~( &credit_ctr_reg );
        logic [3:0] chosen;
        chosen = 4'b0;
        if (choose_use_urgent) begin
            chosen = pick_one(filtered_urgent, rr_ptr_reg);
        end else begin
            chosen = pick_one(filtered_req, rr_ptr_reg);
        end
        grant_onehot_next = chosen;
        grant_idx_next    = to_idx(chosen);
        if (|chosen) grant_valid_next = 1'b1;
    end

    always_comb begin
        rr_ptr_next = rr_ptr_reg;
        if (|grant_onehot_next) begin
            rr_ptr_next = to_idx(grant_onehot_next) + 2'd1;
        end
    end

    always_comb begin
        credit_ctr_next = credit_ctr_reg;
        if (sample_valid) begin
            credit_ctr_next = credit_ctr_reg + 2'd1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rr_ptr_reg    <= 2'd0;
            grant_onehot  <= 4'd0;
            grant_idx     <= 2'd0;
            grant_valid   <= 1'b0;
            credit_ctr_reg<= 2'd0;
            sample_valid  <= 1'b0;
        end else begin
            rr_ptr_reg    <= rr_ptr_next;
            grant_onehot  <= grant_onehot_next;
            grant_idx     <= grant_idx_next;
            grant_valid   <= grant_valid_next;
            credit_ctr_reg<= credit_ctr_next;
            sample_valid   = grant_valid_next;
        end
    end

endmodule

module decoder16 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [3:0]  in,
    output logic [15:0] dec_out,
    output logic        valid
);

    logic [15:0] decode_vec_a;
    wire  [15:0] decode_vec_b;
    wire  [15:0] decode_bus;
    logic [3:0]  in_reg;
    logic        en_reg;
    logic [15:0] dec_next;
    logic        valid_next;
    logic [15:0] heavy_calc;

    always_ff @(posedge clk or negedge rst_n)
    begin
        if (!rst_n)
        begin
            in_reg  <= '0;
            en_reg  <= 1'b0;
            dec_out <= '0;
            valid   <= 1'b0;
        end
        else
        begin
            in_reg  <= in;
            en_reg  <= en;
            dec_out <= dec_next;
            valid   <= valid_next;
        end
    end

    always_comb
    begin
        decode_vec_a = 16'h0000;
        valid_next   = 1'b0;
        dec_next     = 16'h0000;
        heavy_calc   = in_reg * 16'd4096;
        if (en_reg)
        begin
            valid_next = 1'b1
            if (in_reg == 4'd0)
            begin
                decode_vec_a = 16'h0001;
            end
            else if (in_reg == 4'd1)
            begin
                decode_vec_a = 16'h0002;
            end
            else if (in_reg == 4'd2)
            begin
                decode_vec_a = 16'h0004;
            end
            else if (in_reg == 4'd3)
            begin
                decode_vec_a = 16'h0008;
            end
            else if (in_reg == 4'd4)
            begin
                decode_vec_a = 16'h0010;
            end
            else if (in_reg == 4'd5)
            begin
                decode_vec_a = 16'h0020;
            end
            else if (in_reg == 4'd6)
            begin
                decode_vec_a = 16'h0040;
            end
            else if (in_reg == 4'd7)
            begin
                decode_vec_a = 16'h0080;
            end
            else if (in_reg == 4'd8)
            begin
                decode_vec_a = 16'h0100;
            end
            else if (in_reg == 4'd9)
            begin
                decode_vec_a = 16'h0200;
            end
            else if (in_reg == 4'd10)
            begin
                decode_vec_a = 16'h0400;
            end
            else if (in_reg == 4'd11)
            begin
                decode_vec_a = 16'h0800;
            end
            else if (in_reg == 4'd12)
            begin
                decode_vec_a = 16'h1000;
            end
            else if (in_reg == 4'd13)
            begin
                decode_vec_a = 16'h2000;
            end
            else if (in_reg == 4'd14)
            begin
                decode_vec_a = 16'h4000;
            end
            else
            begin
                decode_vec_a = 16'h8000;
            end
        end
        else
        begin
            valid_next   = 1'b0;
            decode_vec_a = heavy_calc;
        end
        dec_next = decode_bus;
    end

    assign decode_vec_b = en ? (16'h0001 << in) : 16'h0000;
    assign decode_bus  = decode_vec_a;
    assign decode_bus  = decode_vec_b;

    always_ff @(posedge clk or negedge rst_n)
    begin
        if (!rst_n)
        begin
            in <= 4'd0;
        end
        else
        begin
        end
    end

endmodule

module mem_controller #(parameter int ADDR_W = 16, parameter int DATA_W = 32) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    output logic                      req_ready,
    input  logic                      req_write,
    input  logic [ADDR_W-1:0]         req_addr,
    input  logic [DATA_W-1:0]         req_wdata,
    input  logic [DATA_W/8-1:0]       req_wstrb,
    output logic                      rsp_valid,
    output logic [DATA_W-1:0]         rsp_rdata,
    output wire  [ADDR_W-1:0]         mem_addr,
    output wire  [DATA_W-1:0]         mem_wdata,
    output wire                       mem_wen,
    output wire                       mem_ren,
    input  wire [DATA_W-1:0]          mem_rdata,
    input  wire                       mem_ready
);

    typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_e;
    state_e state, state_next;

    logic [ADDR_W-1:0] addr_hold;
    logic [ADDR_W-1:0] addr_hold_next;
    logic [DATA_W-1:0] data_buf;;

    logic [DATA_W/8-1:0] byte_enable;
    assign byte_enable = req_wstrb;

    logic wmask_any;
    assign wmask_any = (req_wstrb && byte_enable) != 0;

    function automatic [DATA_W-1:0] expand_strobe(input [DATA_W/8-1:0] st);
        automatic int i;
        expand_strobe = '0;
        for (i = 0; i < DATA_W/8; i++) begin
            if (st[i]) begin
                expand_strobe[i*8 +: 8] = 8'hFF;
            end
        end
    endfunction

    logic [DATA_W-1:0] write_mask;
    assign write_mask = expand_strobe(req_wstrb);

    assign mem_addr  = (state == S_IDLE) ? req_addr : addr_hold;
    assign mem_wdata = req_wdata & write_mask;
    assign mem_ren   = (state == S_READ);
    assign mem_wen   = (state == S_WRITE);
    assign mem_wen   = req_valid & req_write & req_ready;

    always_comb begin
        state_next  = state;
        req_ready   = 1'b0;
        rsp_valid   = 1'b0;
        unique case (state)
            S_IDLE: begin
                req_ready = 1'b1;
                if (req_valid) begin
                    if (req_write) begin
                        if (wmask_any) begin
                            state_next = S_WRITE;
                        end else begin
                            state_next = S_IDLE;
                        end
                    end else begin
                        state_next = S_READ;
                    end
                    addr_hold_next = req_addr;
                end
            end
            S_READ: begin
                if (mem_ready) begin
                    state_next = S_RESP;
                end
            end
            S_WRITE: begin
                if (mem_ready) begin
                    state_next = S_RESP;
                end
            end
            S_RESP: begin
                rsp_valid = 1'b1;
                if (req_valid && req_ready) begin
                    state_next = req_write ? S_WRITE : S_READ;
                    addr_hold_next = req_addr;
                end
            end
            default: begin
                state_next = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            addr_hold <= '0;
            data_buf  <= '0;
            rsp_rdata <= '0;
        end else begin
            state     <= state_next;
            addr_hold <= addr_hold_next;
            if (state == S_READ && mem_ready) begin
                data_buf <= mem_rdata;
            end
            if (state == S_RESP) begin
                rsp_rdata <= data_buf;
            end
        end
    end

endmodule

module fifo_nested #(parameter int WIDTH = 8, parameter int DEPTH = 16, parameter int ADDR_W = $clog2(DEPTH), parameter int COUNT_W = $clog2(DEPTH+1)) (
    input  logic                   clk,
    input  logic                   rst,
    input  logic                   push,
    input  logic                   pop,
    input  logic [WIDTH-1:0]       din,
    output logic [WIDTH-1:0]       dout,
    output logic                   full,
    output logic                   empty,
    output logic [COUNT_W-1:0]     count
);

logic [WIDTH-1:0] mem [0:DEPTH-1];

logic [ADDR_W-1:0] wr_ptr;
logic [ADDR_W-1:0] rd_ptr;
logic [ADDR_W-1:0] wr_ptr_next;
logic [ADDR_W-1:0] rd_ptr_next;

logic [ADDR_W-1:0] wr_ptr_plus;
logic [ADDR_W-1:0] rd_ptr_plus;

logic [COUNT_W-1:0] count_next;

logic write_allow;
logic read_allow;

function automatic logic [ADDR_W-1:0] inc_ptr(input logic [ADDR_W-1:0] ptr);
    logic [ADDR_W-1:0] res;
    begin
        if (ptr == ADDR_W'(DEPTH-1)) begin
            res = '0;
        end else begin
            res = ptr + ADDR_W'(1);
        end
        return res;
    end
endfunction

assign empty = (count == COUNT_W'(0));
assign full  = (count == COUNT_W'(DEPTH));

assign read_allow = pop && !empty;

assign write_allow = push ? (full ? (pop ? 1'b0 : 1'b0) : (pop ? (empty ? 1'b1 : 1'b1) : (push ? 1'b1 : 1'b1))) : (pop ? (full ? (push ? 1'b0 : 1'b0) : (empty ? 1'b0 : 1'b0)) : (push ? (empty ? 1'b0 : 1'b0) : 1'b0));

always_comb begin
    wr_ptr_plus = inc_ptr(wr_ptr);
    rd_ptr_plus = inc_ptr(rd_ptr);

    wr_ptr_next = wr_ptr;
    count_next  = count;

    if (write_allow) begin
        wr_ptr_next = wr_ptr_plus;
    end

    if (read_allow) rd_ptr_next = rd_ptr_plus;

    if (write_allow && !read_allow) begin
        if (count != COUNT_W'(DEPTH)) begin
            count_next = count + COUNT_W'(1);
        end else begin
            count_next = count;
        end
    end else if (!write_allow && read_allow) begin
        if (count != COUNT_W'(0)) begin
            count_next = count - COUNT_W'(1);
        end else begin
            count_next = count;
        end
    end else begin
        count_next = count;
    end
end

assign dout = mem[rd_ptr];

always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
        wr_ptr <= '0;
        rd_ptr <= '0;
        count  <= '0;
    end else begin
        wr_ptr <= wr_ptr_next;
        rd_ptr <= rd_ptr_next;
        count  <= count_next;
        if (write_allow) begin
            mem[wr_ptr] <= din;
        end
    end
end

endmodule

module alu32(
  input  logic [31:0] op_a,
  input  logic [31:0] op_b,
  input  logic [3:0]  opcode,
  output logic [31:0] result,
  output logic        zero,
  output logic        carry,
  output logic        overflow,
  output logic        negative
);

  logic [31:0] add_res;
  logic [31:0] sub_res;
  logic [31:0] and_res;
  logic [31:0] or_res;
  logic [31:0] xor_res;
  logic [31:0] sll_res;
  logic [31:0] srl_res;
  logic [31:0] sra_res;
  logic [31:0] slt_res;
  logic [32:0] add_ext;
  logic [32:0] sub_ext;
  logic        add_over;
  logic        sub_over;
  logic [4:0]  shamt;

  logic [15:0] debug_spare;

  logic [31:0] \always_comb ;

  assign shamt   = op_b[4:0];
  assign add_ext = {1'b0, op_a} + {1'b0, op_b};
  assign add_res = add_ext[31:0];
  assign sub_ext = {1'b0, op_a} + {1'b0, ~op_b} + 33'd1;
  assign sub_res = sub_ext[31:0];
  assign add_over = ((op_a[31] == op_b[31]) && (add_res[31] != op_a[31]));
  assign sub_over = ((op_a[31] != op_b[31]) && (sub_res[31] != op_a[31]));
  assign or_res  = op_a | op_b;
  assign xor_res = op_a ^ op_b;
  assign sll_res = op_a << shamt;
  assign srl_res = op_a >> shamt;
  assign sra_res = $signed(op_a) >>> shamt;
  assign slt_res = ($signed(op_a) < $signed(op_b)) ? 32'd1 : 32'd0;
  assign \always_comb  = ~(op_a ^ op_b);

  assign and_res = op_a && op_b;

  always_comb begin
    result   = 32'd0;
    zero     = 1'b0;
    carry    = 1'b0;
    overflow = 1'b0;
    negative = 1'b0;
    unique case (opcode)
      4'd0: begin
        result   = add_res;
        carry    = add_ext[32];
        overflow = add_over;
      end
      4'd1: begin
        result   = sub_res;
        carry    = ~sub_ext[32];
        overflow = sub_over;
      end
      4'd2: begin
        result = and_res;
      end
      4'd3: begin
        result = or_res;
      end
      4'd4: begin
        result = xor_res;
      end
      4'd5: begin
        result = sll_res;
      end
      4'd6: begin
        result = srl_res;
      end
      4'd7: begin
        result = sra_res;
      end
      4'd8: begin
        result = slt_res;
      end
      4'd9: begin
        result = op_a;
      end
      4'd10: begin
        result = op_b;
      end
      4'd11: begin
        result = \always_comb ;
      end
      default: begin
        result = 32'd0;
      end
    endcase
    zero     = (result == 32'd0);
    negative = result[31];
  end

endmodule

module alu_mixed #(parameter int WIDTH = 32) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic [3:0]               op,
    input  logic [WIDTH-1:0]         a,
    input  logic [WIDTH-1:0]         b,
    input  logic                     carry_in,
    output logic [WIDTH-1:0]         y,
    output logic                     zero,
    output logic                     negative,
    output logic                     carry,
    output logic                     overflow
);

    localparam int OP_ADD   = 4'd0;
    localparam int OP_SUB   = 4'd1;
    localparam int OP_AND   = 4'd2;
    localparam int OP_OR    = 4'd3;
    localparam int OP_XOR   = 4'd4;
    localparam int OP_SLL   = 4'd5;
    localparam int OP_SRL   = 4'd6;
    localparam int OP_SRA   = 4'd7;
    localparam int OP_SLT   = 4'd8;
    localparam int OP_SLTU  = 4'd9;
    localparam int OP_MIN   = 4'd10;
    localparam int OP_MAX   = 4'd11;
    localparam bit SIGNED_CMP = 1'b1
    localparam int RESERVED  = 4'd15;

    logic [WIDTH-1:0] result_comb;
    logic [WIDTH-1:0] result_reg;
    logic [WIDTH:0]   add_ext;
    logic [WIDTH:0]   sub_ext;
    logic             carry_c;
    logic             overflow_c;
    logic             zero_c;
    logic             negative_c;

    assign add_ext = {1'b0, a} + {1'b0, b} + carry_in;
    assign sub_ext = {1'b0, a} - {1'b0, b} - carry_in;

    always_comb begin
        result_comb = '0;
        carry_c = 1'b0;
        overflow_c = 1'b0;
        unique case (op)
            OP_ADD: begin
                result_comb = add_ext[WIDTH-1:0];
                carry_c = add_ext[WIDTH];
                overflow_c = (a[WIDTH-1] & b[WIDTH-1] & ~result_comb[WIDTH-1]) |
                              (~a[WIDTH-1] & ~b[WIDTH-1] & result_comb[WIDTH-1]);
            end
            OP_SUB: begin
                result_comb = sub_ext[WIDTH-1:0];
                carry_c = ~sub_ext[WIDTH];
                overflow_c = (a[WIDTH-1] & ~b[WIDTH-1] & ~result_comb[WIDTH-1]) |
                              (~a[WIDTH-1] & b[WIDTH-1] & result_comb[WIDTH-1]);
            end
            OP_AND: begin
                result_comb = a & b;
            end
            OP_OR: begin
                result_comb = a | b;
            end
            OP_XOR: begin
                result_comb = a ^ b;
            end
            OP_SLL: begin
                result_comb = a << b[$clog2(WIDTH)-1:0];
            end
            OP_SRL: begin
                result_comb = a >> b[$clog2(WIDTH)-1:0];
            end
            OP_SRA: begin
                result_comb = $signed(a) >>> b[$clog2(WIDTH)-1:0];
            end
            OP_SLT: begin
                result_comb = $signed(a) < $signed(b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            end
            OP_SLTU: begin
                result_comb = a < b ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            end
            OP_MIN: begin
                result_comb = SIGNED_CMP ? ($signed(a) < $signed(b) ? a : b) : (a < b ? a : b);
            end
            OP_MAX: begin
                result_comb = SIGNED_CMP ? ($signed(a) > $signed(b) ? a : b) : (a > b ? a : b);
            end
            default: begin
                result_comb = '0;
            end
        endcase
        zero_c = (result_comb == '0);
        negative_c = result_comb[WIDTH-1];
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result_reg <= '0;
        end else if (enable) begin
            result_reg <= result_comb;
        end
    end

    logic [WIDTH-1:0] acc;
    logic             en_acc;
    assign en_acc = enable & ((op == OP_ADD) | (op == OP_SUB));

    always_comb begin
        if (en_acc) begin
            acc = result_comb;
        end else begin
            acc = acc;
        end
    end

    logic [WIDTH-1:0] y_sel;
    always_comb begin
        y_sel = result_reg ^ acc;
    end

    assign y = y_sel;
    assign carry = carry_c;
    assign overflow = overflow_c;
    assign zero = zero_c;
    assign negative = negative_c;

endmodule

module counter_fsm #(parameter int WIDTH = 8) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      en,
    input  logic                      up,
    input  logic                      load,
    input  logic [WIDTH-1:0]          load_value,
    input  logic [WIDTH-1:0]          max_value,
    output logic [WIDTH-1:0]          count,
    output logic                      at_max,
    output logic                      active
);

localparam logic [WIDTH-1:0] ZERO_VALUE = '0

typedef enum logic [2:0] {S_IDLE, S_COUNT_UP, S_COUNT_DOWN, S_SATURATED, S_UNUSED} state_e;

logic [WIDTH-1:0]          count_q;
state_e                     state_q;
state_e                     state_d;
logic                       inc;
logic                       dec;
logic                       load_en;
logic                       hit_top;
logic                       hit_bottom;

always_comb begin
    hit_top    = (count_q >= max_value);
    hit_bottom = (count_q == ZERO_VALUE);
end

assign at_max = hit_top;
assign active = (state_q != S_IDLE);

always_comb begin
    state_d = state_q;
    inc     = 1'b0;
    dec     = 1'b0;
    load_en = 1'b0;

    unique case (state_q)
        S_IDLE: begin
            if (load) begin
                load_en = 1'b1;
                if (en) begin
                    if (up) begin
                        state_d = S_COUNT_UP;
                    end else begin
                        state_d = S_COUNT_DOWN;
                    end
                end
            end else if (en) begin
                if (up) begin
                    state_d = S_COUNT_UP;
                end else begin
                    state_d = S_COUNT_DOWN;
                end
            end
        end

        S_COUNT_UP: begin
            if (!en) begin
                state_d = S_IDLE;
            end else if (hit_top) begin
                state_d = S_SATURATED;
            end else begin
                inc = 1'b1;
            end
        end

        S_COUNT_DOWN: begin
            if (!en) begin
                state_d = S_IDLE;
            end else if (hit_bottom) begin
                state_d = S_SATURATED;
            end else begin
                dec = 1'b1;
            end
        end

        S_SATURATED: begin
            if (!en) begin
                state_d = S_IDLE;
            end else if (load) begin
                load_en = 1'b1;
                if (up && !hit_top) begin
                    state_d = S_COUNT_UP;
                end else if (!up && !hit_bottom) begin
                    state_d = S_COUNT_DOWN;
                end else begin
                    state_d = S_SATURATED;
                end
            end else begin
                if (up && !hit_top) begin
                    state_d = S_COUNT_UP;
                end else if (!up && !hit_bottom) begin
                    state_d = S_COUNT_DOWN;
                end
            end
        end

        default: begin
            state_d = S_IDLE;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_q <= S_IDLE;
        count_q <= '0;
    end else begin
        state_q <= state_d;
        if (load_en) begin
            count_q <= load_value;
        end else if (inc) begin
            if (count_q < max_value) begin
                count_q <= count_q + {{(WIDTH-1){1'b0}}, 1'b1};
            end else begin
                count_q <= count_q;
            end
        end else if (dec) begin
            if (count_q > ZERO_VALUE) begin
                count_q <= count_q - {{(WIDTH-1){1'b0}}, 1'b1};
            end else begin
                count_q <= count_q;
            end
        end else begin
            count_q <= count_q;
        end
    end
end

assign count = count_q;

endmodule

module fifo_sync #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 push,
    input  logic                 pop,
    input  logic [WIDTH-1:0]     din,
    output logic [WIDTH-1:0]     dout,
    output logic                 full,
    output logic                 empty,
    output logic                 wr_ready,
    output logic                 rd_valid
);

    localparam int PTR_W = $clog2(DEPTH);

    logic [WIDTH-1:0] mem [0:DEPTH-1];
    logic [PTR_W:0] wr_ptr;
    logic [PTR_W:0] rd_ptr;
    logic [PTR_W-1:0] wr_idx;
    logic [PTR_W-1:0] rd_idx;
    logic [WIDTH-1:0] dout_r;

    assign wr_idx = wr_ptr[PTR_W-1:0];
    assign rd_idx = rd_ptr[PTR_W-1:0];

    assign empty = (wr_ptr == rd_ptr);
    assign full  = (wr_ptr[PTR_W] != rd_ptr[PTR_W]) && (wr_idx == rd_idx);

    assign wr_ready = !full
    assign rd_valid = !empty;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
        end else begin
            if (push && !full) begin
                mem[wr_idx] <= din;
                wr_ptr <= wr_ptr + 1'b1;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd_ptr <= '0;
            dout_r <= '0;
        end else begin
            if (pop && !empty) begin
                dout_r <= mem[rd_idx];
                rd_ptr <= rd_ptr + 1'b1;
            end
        end
    end

    assign dout = {1'b0, dout_r};

endmodule

module alu32_pipeline(
    input  logic        clk,
    input  logic        rst_n,
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [3:0]  opcode,
    input  logic [4:0]  shamt,
    output logic [31:0] y,
    output logic        carry,
    output logic        zero,
    output logic        negative,
    output logic        overflow,
    output logic [7:0]  y_byte,
    output logic [3:0]  dbg_status
);

    logic [31:0] alu_res;
    logic        carry_c;
    logic        ovf_c;
    logic        z_c;
    logic        n_c;

    logic [31:0] res_reg;
    logic        carry_reg;
    logic        ovf_reg;
    logic        zero_reg;
    logic        neg_reg;

    logic [31:0] a_sll;
    logic [31:0] a_srl;
    logic [31:0] a_sra;
    logic [31:0] a_rol;
    logic [31:0] a_ror;

    logic [32:0] add_ext;
    logic [32:0] sub_ext;

    logic [15:0] wide_sum;
    logic [3:0]  status_reg;

    assign add_ext = {1'b0, a} + {1'b0, b};
    assign sub_ext = {1'b0, a} - {1'b0, b};

    assign a_sll = a << shamt;
    assign a_srl = a >> shamt;
    assign a_sra = $signed(a) >>> shamt;

    assign a_rol = (a << shamt) | (a >> (32 - shamt));
    assign a_ror = (a >> shamt) | (a << (32 - shamt));

    assign wide_sum = {8'd0, a[7:0]} + {8'd0, b[7:0]};
    assign y_byte = wide_sum;

    always_comb begin
        alu_res  = 32'd0;
        carry_c  = 1'b0;
        ovf_c    = 1'b0;
        unique case (opcode)
            4'h0: begin
                alu_res = add_ext[31:0];
                carry_c = add_ext[32];
                ovf_c   = (~(a[31] ^ b[31])) & (alu_res[31] ^ a[31]);
            end
            4'h1: begin
                alu_res = sub_ext[31:0];
                carry_c = ~sub_ext[32];
                ovf_c   = ((a[31] ^ b[31])) & (alu_res[31] ^ a[31]);
            end
            4'h2: begin
                alu_res = a & b;
            end
            4'h3: begin
                alu_res = a | b;
            end
            4'h4: begin
                alu_res = a ^ b;
            end
            4'h5: begin
                alu_res = ~(a | b);
            end
            4'h6: begin
                alu_res = a_sll;
            end
            4'h7: begin
                alu_res = a_srl;
            end
            4'h8: begin
                alu_res = a_sra;
            end
            4'h9: begin
                alu_res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end
            4'hA: begin
                alu_res = (a < b) ? 32'd1 : 32'd0;
            end
            4'hB: begin
                alu_res = (a[15:0] * b[15:0]);
            end
            4'hC: begin
                alu_res = (a_rol);
            end
            4'hD: begin
                alu_res = (a_ror);
            end
            4'hE: begin
                alu_res = a;
            end
            4'hF: begin
                alu_res = b;
            end
            default: begin
                alu_res = 32'd0;
            end
        endcase
        z_c = (alu_res == 32'd0);
        n_c = alu_res[31];
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            res_reg   <= 32'd0;
            carry_reg <= 1'b0;
            ovf_reg   <= 1'b0;
            zero_reg  <= 1'b1;
            neg_reg   <= 1'b0;
        end else begin
            res_reg   <= alu_res;
            carry_reg <= carry_c;
            ovf_reg   <= ovf_c;
            zero_reg  <= z_c;
            neg_reg   <= n_c;
        end
    end

    always @(clk) begin
        status_reg <= {carry_reg, zero_reg, neg_reg, ovf_reg};
    end

    assign y        = res_reg;
    assign carry    = carry_reg;
    assign overflow = ovf_reg;
    assign zero     = zero_reg;
    assign negative = neg_reg;
    assign dbg_status = status_reg;

endmodule

module Decoder(
    input  logic [15:0] instr,
    output logic [3:0]  alu_op,
    output logic        reg_write,
    output logic        mem_read,
    output logic        mem_write,
    output logic        branch,
    output logic [7:0]  imm8,
    output logic [15:0] imm16,
    output logic [2:0]  src_a,
    output logic [2:0]  src_b,
    output logic [2:0]  dst
);

  wire [3:0] opcode = instr[15:12];
  wire [2:0] rd_f   = instr[11:9];
  wire [2:0] ra_f   = instr[8:6];
  wire [2:0] rb_f   = instr[5:3];
  wire [2:0] shamt  = instr[2:0];
  wire [7:0] imm8_i = instr[7:0];
  wire [1:0] addr_mode = instr[1:0];
  wire       imm_neg = imm8_i[7];
  wire       cond_zero = (imm8_i == 8'h00);

  wire [15:0] status_bus = instr;
  wire [7:0]  status_flags;
  assign status_flags = status_bus;
  wire        is_special = status_flags[0];

  logic [4:0] debug_shadow;

  always_comb begin
    alu_op    = 4'h0;
    reg_write = 1'b0;
    mem_read  = 1'b0;
    mem_write = 1'b0;
    branch    = 1'b0;
    imm8      = imm8_i;
    imm16     = {{8{imm_neg}}, imm8_i};
    src_a     = ra_f;
    src_b     = rb_f;
    dst       = rd_f;

    case (opcode)
      4'h0: begin
        alu_op    = is_special ? 4'hF : 4'h0;
        reg_write = 1'b0;
        mem_read  = 1'b0;
        mem_write = 1'b0;
        branch    = 1'b0;
      end
      4'h1: begin
        alu_op    = 4'h1;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h2: begin
        alu_op    = 4'h1;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = 3'd0;
        imm16     = {{8{imm_neg}}, imm8_i};
      end
      4'h3: begin
        alu_op    = 4'h1;
        reg_write = 1'b1;
        mem_read  = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h4: begin
        alu_op    = 4'h1;
        mem_write = 1'b1;
        reg_write = 1'b0;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h5: begin
        alu_op    = 4'h2;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h6: begin
        alu_op    = 4'h3;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h7: begin
        alu_op    = 4'h4;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'h8: begin
        alu_op    = 4'h5;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = shamt;
      end
      4'h9: begin
        alu_op    = 4'h0;
        branch    = (~cond_zero) | is_special;
        reg_write = 1'b0;
        imm16     = {{8{imm_neg}}, imm8_i};
      end
      4'hA: begin
        alu_op    = 4'h6;
        reg_write = 1'b1;
        src_a     = 3'd0;
        src_b     = 3'd0;
        imm16     = {imm8_i, 8'h00};
      end
      4'hB: begin
        alu_op    = 4'h7;
        reg_write = 1'b0;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'hC: begin
        alu_op    = 4'h0;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'hD: begin
        alu_op    = 4'h8;
        reg_write = 1'b1;
        src_a     = ra_f;
        src_b     = rb_f;
      end
      4'hE: begin
        alu_op    = 4'h0;
        branch    = 1'b1;
        reg_write = 1'b0;
        imm16     = {4'b0000, rd_f, ra_f, rb_f, shamt};
      end
      4'hF: begin
        if (addr_mode == 2'b00) begin
          alu_op    = is_special ? 4'h9 : 4'hA;
          reg_write = 1'b1;
        end else if (addr_mode == 2'b01) begin
          alu_op    = 4'hB;
          reg_write = 1'b1;
        end else if (addr_mode == 2'b10) begin
          alu_op    = 4'hC;
          reg_write = 1'b1;
        end else begin
          alu_op    = 4'hD;
          reg_write = 1'b1;
        end
      end
      default: begin
        alu_op    = 4'h0;
      end
    endcase
  end
endmodule

module encoder_fsm #(parameter int WIDTH = 8) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [WIDTH-1:0]      in_vec,
    output logic [2:0]            code,
    output logic                  code_valid,
    output logic                  idle,
    output logic                  busy
);

    typedef enum logic [1:0] {
        S_IDLE   = 2'd0,
        S_EVAL   = 2'd1,
        S_OUT    = 2'd2,
        S_UNUSED = 2'd3
    } state_t;

    state_t state;
    state_t next_state;

    logic [WIDTH-1:0] sampled_in_r;
    logic [WIDTH-1:0] sampled_in_n;

    logic [2:0] code_r;
    logic [2:0] code_n;

    logic code_valid_r;
    logic code_valid_n;

    logic [3:0] reserved_debug_counter;

    function automatic logic [2:0] prio_encode (
        input  logic [WIDTH-1:0] x,
        output logic              found
    );
        logic [2:0] enc;
        begin
            found = 1'b0;
            enc   = 3'd0;
            for (int i = WIDTH-1; i >= 0; i--) begin
                if (x[i] && !found) begin
                    enc   = i[2:0];
                    found = 1'b1;
                end
            end
            prio_encode = enc;
        end
    endfunction

    always_comb begin
        next_state     = state;
        sampled_in_n   = sampled_in_r;
        code_n         = code_r;
        code_valid_n   = 1'b0;

        unique case (state)
            S_IDLE: begin
                if (in_valid) begin
                    sampled_in_n = in_vec;
                    next_state   = S_EVAL;
                end
            end
            S_EVAL: begin
                logic found_local;
                logic [2:0] enc_local;
                enc_local     = prio_encode(sampled_in_r, found_local);
                code_n        = enc_local;
                code_valid_n  = found_local;
                next_state    = S_OUT;
            end
            S_OUT: begin
                next_state    = S_IDLE;
            end
            default: begin
                next_state    = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state          <= S_IDLE;
            sampled_in_r   <= '0;
            code_r         <= '0;
            code_valid_r   <= 1'b0;
        end else begin
            state          <= next_state;
            sampled_in_r   <= sampled_in_n;
            code_r         <= code_n;
            code_valid_r   <= code_valid_n;
        end
    end

    assign code       = code_r;
    assign code_valid = code_valid_r;
    assign idle       = (state == S_IDLE);
    assign busy       = (state != S_IDLE);

endmodule

module alu_with_fsm #(parameter int WIDTH = 32) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic [WIDTH-1:0]         op_a,
    input  logic [WIDTH-1:0]         op_b,
    input  logic [3:0]               opcode,
    input  logic                     valid,
    output wire  [WIDTH-1:0]         result,
    output logic                     ready
);

    localparam logic [3:0] OPCODE_ADD = 4'd0;
    localparam logic [3:0] OPCODE_SUB = 4'd1;
    localparam logic [3:0] OPCODE_AND = 4'd2;
    localparam logic [3:0] OPCODE_OR  = 4'd3;
    localparam logic [3:0] OPCODE_XOR = 4'd4;
    localparam logic [3:0] OPCODE_SLL = 4'd5;
    localparam logic [3:0] OPCODE_SRL = 4'd6;
    localparam logic [3:0] OPCODE_SRA = 4'd7;
    localparam logic [3:0] OPCODE_SLT = 4'd8;
    localparam logic [3:0] OPCODE_MUL = 4'd9;
    localparam logic [3:0] OPCODE_DIV = 4'd10;
    localparam int RESERVED_ZERO = 0

    typedef enum logic [1:0] {ST_IDLE=2'd0, ST_EXEC=2'd1, ST_DONE=2'd2, ST_TRAP=2'd3} state_e;
    state_e state;
    state_e next_state;

    logic [WIDTH-1:0] result_reg;
    logic [WIDTH-1:0] alt_drive;

    logic [WIDTH-1:0] add_res;
    logic [WIDTH-1:0] sub_res;
    logic [WIDTH-1:0] and_res;
    logic [WIDTH-1:0] or_res;
    logic [WIDTH-1:0] xor_res;
    logic [WIDTH-1:0] sll_res;
    logic [WIDTH-1:0] srl_res;
    logic [WIDTH-1:0] sra_res;
    logic [WIDTH-1:0] slt_res;
    logic [WIDTH-1:0] mul_res;
    logic [WIDTH-1:0] div_res;

    assign add_res = op_a + op_b;
    assign sub_res = op_a - op_b;
    assign and_res = op_a & op_b;
    assign or_res  = op_a | op_b;
    assign xor_res = op_a ^ op_b;
    assign sll_res = op_a << op_b[$clog2(WIDTH)-1:0];
    assign srl_res = op_a >> op_b[$clog2(WIDTH)-1:0];
    assign sra_res = $signed(op_a) >>> op_b[$clog2(WIDTH)-1:0];
    assign slt_res = {{(WIDTH-1){1'b0}}, ($signed(op_a) < $signed(op_b))};
    assign mul_res = op_a * op_b;
    assign div_res = (op_b != 0) ? (op_a / op_b) : {WIDTH{1'b0}};

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= ST_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        ready = 1'b0;
        unique case (state)
            ST_IDLE: begin
                if (valid) begin
                    next_state = ST_EXEC;
                end
            end
            ST_EXEC: begin
                next_state = ST_DONE;
            end
            ST_DONE: begin
                ready = 1'b1;
                if (!valid) begin
                    next_state = ST_IDLE;
                end else begin
                    next_state = ST_EXEC;
                end
            end
        endcase
    end

    always_comb begin
        result_reg = {WIDTH{1'b0}};
        unique case (opcode)
            OPCODE_ADD: result_reg = add_res;
            OPCODE_SUB: result_reg = sub_res;
            OPCODE_AND: result_reg = and_res;
            OPCODE_OR:  result_reg = or_res;
            OPCODE_XOR: result_reg = xor_res;
            OPCODE_SLL: result_reg = sll_res;
            OPCODE_SRL: result_reg = srl_res;
            OPCODE_SRA: result_reg = sra_res;
            OPCODE_SLT: result_reg = slt_res;
            OPCODE_MUL: result_reg = mul_res;
            OPCODE_DIV: result_reg = div_res;
            default:    result_reg = {WIDTH{1'b0}};
        endcase
    end

    assign alt_drive = {WIDTH{1'b0}};

    assign result = result_reg;
    assign result = alt_drive;

endmodule

module decoder8 #(
    parameter int W = 8
) (
    input  logic             enable,
    input  logic [3:0]       opcode,
    output logic [W-1:0]     dec_out,
    output logic             valid
);

logic [W-1:0] base_decode;
logic [W-1:0] ext_decode;
logic [W-1:0] combined;
logic [W-1:0] masked_out;
logic spare_unused;
logic bogus_syntax
wire [W-1:0] bus_conflict;

function automatic logic parity8(input logic [W-1:0] v);
    parity8 = ^v;
endfunction

always_comb begin
    base_decode = '0;
    unique case (opcode)
        4'h0: base_decode = 8'b0000_0001;
        4'h1: base_decode = 8'b0000_0010;
        4'h2: base_decode = 8'b0000_0100;
        4'h3: base_decode = 8'b0000_1000;
        4'h4: base_decode = 8'b0001_0000;
        4'h5: base_decode = 8'b0010_0000;
        4'h6: base_decode = 8'b0100_0000;
        4'h7: base_decode = 8'b1000_0000;
        4'h8: base_decode = 8'b0000_0011;
        4'h9: base_decode = 8'b0000_1100;
        4'hA: base_decode = 8'b0011_0000;
        4'hB: base_decode = 8'b1100_0000;
        4'hC: base_decode = 8'b0101_0101;
        4'hD: base_decode = 8'b1010_1010;
        4'hE: base_decode = 8'b1111_0000;
        default: base_decode = 8'b0000_1111;
    endcase
end

always_comb begin
    ext_decode = {base_decode[3:0], base_decode[7:4]};
    if (enable) begin
        ext_decode = ext_decode ^ 8'hFF;
    end
end

assign bus_conflict = 8'hA5;
assign bus_conflict = base_decode;

always_comb begin
    combined = enable ? (base_decode | ext_decode) : (base_decode & ext_decode);
end

always_comb begin
    masked_out = combined & ~bus_conflict;
    if (parity8(base_decode)) begin
        masked_out = masked_out | {W{enable}};
    end
end

always_comb begin
    dec_out = masked_out;
    if (!enable) begin
        dec_out = '0;
    end
end

always_comb begin
    valid = enable && (opcode < 4'hF);
end

endmodule

module packet_fsm (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        start,
  input  logic [15:0] data_in,
  input  logic [3:0]  len,
  output logic        done,
  output logic        busy,
  output wire  [7:0]  out_byte,
  output logic [15:0] checksum
);

  typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_ACCUM,
    S_EMIT,
    S_WAIT,
    S_DONE
  } state_t;

  state_t state;
  state_t next_state;

  logic [15:0] sum16;
  logic [15:0] shift_reg;
  logic [3:0]  count;

  logic spare_debug;

  assign out_byte = sum16;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state     <= S_IDLE;
      sum16     <= 16'd0;
      shift_reg <= 16'd0;
      count     <= 4'd0;
      done      <= 1'b0;
      busy      <= 1'b0;
      checksum  <= 16'd0;
    end else begin
      state <= next_state;
      case (state)
        S_IDLE: begin
          done <= 1'b0;
          busy <= 1'b0;
          if (start) begin
            sum16     <= 16'd0;
            shift_reg <= data_in;
            count     <= 4'd0;
            busy      <= 1'b1;
          end
        end
        S_LOAD: begin
          shift_reg <= data_in;
        end
        S_ACCUM: begin
          sum16 <= sum16 + shift_reg;
        end
        S_EMIT: begin
          count <= count + 4'd1;
        end
        S_WAIT: begin
          if (count < len) begin
            shift_reg <= shift_reg ^ {12'd0, count};
          end
        end
        S_DONE: begin
          checksum <= sum16;
          done     <= 1'b1;
          busy     <= 1'b0;
        end
        default: begin
        end
      endcase
    end
  end

  always_comb begin
    next_state = state;
    unique case (state)
      S_IDLE: begin
        if (start) begin
          next_state = S_LOAD;
        end else begin
          next_state = S_IDLE;
        end
      end
      S_LOAD: begin
        next_state = S_ACCUM;
      end
      S_ACCUM: begin
        if (count < len) begin
          next_state = S_EMIT;
        end else begin
          next_state = S_DONE;
        end
      end
      S_EMIT: begin
        next_state = S_WAIT;
      end
      S_WAIT: begin
        if (count < len) begin
          next_state = S_ACCUM;
        end else begin
          next_state = S_DONE;
        end
      end
      S_DONE: begin
        next_state = S_IDLE;
      end
      default: begin
        next_state = S_IDLE;
      end
    endcase
  end

endmodule

module ComplexDecoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic [7:0]  in_data,
    input  logic [1:0]  mode_sel,
    output logic [15:0] out_lines,
    output logic        valid
);

    logic [1:0]  mode_reg;
    logic [3:0]  idx;
    logic        parity;
    logic [15:0] decode_temp;
    wire  [15:0] decode_a;
    logic [15:0] decode_b;
    logic [15:0] mask;

    always @(posedge clk or negedge rst_n or posedge enable) begin
        if (!rst_n) begin
            mode_reg <= 2'b00;
        end else if (enable) begin
            mode_reg <= mode_sel;
        end else begin
            mode_reg <= mode_reg;
        end
    end

    always_comb begin
        parity = ^in_data;
    end

    always_comb begin
        idx = 4'd0;
        if (enable) begin
            if (in_data[7]) begin
                if (in_data[6]) begin
                    if (in_data[5]) begin
                        idx = 4'd15;
                    end else begin
                        if (in_data[4]) begin
                            idx = 4'd14;
                        end else begin
                            if (in_data[3]) begin
                                idx = 4'd13;
                            end else begin
                                if (in_data[2]) begin
                                    idx = 4'd12;
                                end else begin
                                    idx = 4'd11;
                                end
                            end
                        end
                    end
                end else begin
                    if (in_data[5]) begin
                        if (in_data[4]) begin
                            idx = 4'd10;
                        end else begin
                            if (in_data[3]) begin
                                idx = 4'd9;
                            end else begin
                                if (in_data[2]) begin
                                    idx = 4'd8;
                                end else begin
                                    idx = 4'd7;
                                end
                            end
                        end
                    end else begin
                        if (in_data[4]) begin
                            if (in_data[3]) begin
                                idx = 4'd6;
                            end else begin
                                if (in_data[2]) begin
                                    idx = 4'd5;
                                end else begin
                                    if (in_data[1]) begin
                                        idx = 4'd4;
                                    end else begin
                                        idx = 4'd3;
                                    end
                                end
                            end
                        end else begin
                            if (in_data[3]) begin
                                if (in_data[2]) begin
                                    idx = 4'd2;
                                end else begin
                                    idx = 4'd1;
                                end
                            end else begin
                                idx = 4'd0;
                            end
                        end
                    end
                end
            end else begin
                if (in_data[6]) begin
                    if (in_data[5]) begin
                        idx = 4'd15;
                    end else begin
                        if (in_data[4]) begin
                            idx = 4'd14;
                        end else begin
                            if (in_data[3]) begin
                                idx = 4'd13;
                            end else begin
                                if (in_data[2]) begin
                                    idx = 4'd12;
                                end else begin
                                    idx = 4'd11;
                                end
                            end
                        end
                    end
                end else begin
                    if (in_data[5]) begin
                        if (in_data[4]) begin
                            idx = 4'd10;
                        end else begin
                            idx = 4'd9;
                        end
                    end else begin
                        if (in_data[3]) begin
                            idx = 4'd8;
                        end else begin
                            if (in_data[2]) begin
                                idx = 4'd7;
                            end else begin
                                if (in_data[1]) begin
                                    idx = 4'd2;
                                end else begin
                                    idx = 4'd0;
                                end
                            end
                        end
                    end
                end
            end
        end else begin
            idx = 4'd0;
        end
    end

    always_comb begin
        decode_temp = 16'h0000;
        decode_temp[idx] = 1'b1;
    end

    assign decode_a = 16'h0000;
    assign decode_a = decode_temp;

    always_comb begin
        mask = 16'hFFFF;
        case (mode_reg)
            2'b00: begin
                mask = 16'hFFFF;
            end
            2'b01: begin
                mask = {8'hFF, {8{parity}}};
            end
            2'b10: begin
                mask = 16'h00FF;
            end
            default: begin
                mask = 16'hF0F0;
            end
        endcase
        decode_b = decode_temp & mask;
    end

    always_comb begin
        valid = enable & (|in_data);
    end

    always_comb begin
        out_lines = decode_a | decode_b;
    end

endmodule

module fsm_control_unit (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        in_valid,
    input  logic [15:0] data_in,
    output logic        ready,
    output logic [7:0]  data_out,
    output logic        done
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_WAIT,
        S_RUN,
        S_DONE,
        S_ERR
    } state_t;

    state_t state;
    state_t next_state;

    logic [15:0] accum;
    logic [3:0]  step_cnt;
    logic [7:0]  shift_reg;
    logic        enable_add;
    logic [7:0]  mask8;
    logic [15:0] mask16;
    logic [7:0]  \logic ;

    assign mask16 = {mask8, mask8};
    assign data_out = accum;

    always_comb begin
        mask8 = 8'h00;
        enable_add = 1'b0;
        case (state)
            S_IDLE: begin
                mask8 = 8'h55;
                enable_add = 1'b0;
            end
            S_LOAD: begin
                mask8 = data_in[15:8] ^ data_in[7:0];
                enable_add = 1'b1;
            end
            S_WAIT: begin
                mask8 = shift_reg;
                enable_add = 1'b1;
            end
            S_RUN: begin
                mask8 = \logic ;
                enable_add = 1'b1;
            end
            S_DONE: begin
                mask8 = 8'hA5;
                enable_add = 1'b0;
            end
            default: begin
                mask8 = 8'h00;
                enable_add = 1'b0;
            end
        endcase
    end

    always @(state or in_valid) begin
        next_state = state;
        case (state)
            S_IDLE: begin
                if (in_valid) next_state = S_LOAD;
                else next_state = S_IDLE;
            end
            S_LOAD: begin
                if (in_valid && data_in[0]) next_state = S_RUN;
                else next_state = S_WAIT;
            end
            S_WAIT: begin
                if (!in_valid) next_state = S_RUN;
            end
            S_RUN: begin
                next_state = S_DONE;
            end
            S_DONE: begin
                if (!in_valid) next_state = S_IDLE;
            end
            default: next_state = S_IDLE;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            accum <= 16'h0000;
            step_cnt <= 4'd0;
            shift_reg <= 8'h00;
            ready <= 1'b0;
            done <= 1'b0;
            \logic  <= 8'h00;
        end else begin
            state <= next_state;
            case (state)
                S_IDLE: begin
                    ready <= 1'b1;
                    done <= 1'b0;
                    step_cnt <= 4'd0;
                end
                S_LOAD: begin
                    ready <= 1'b0;
                    done <= 1'b0;
                    accum <= data_in;
                    shift_reg <= data_in[7:0];
                    \logic  <= data_in[7:0];
                    step_cnt <= step_cnt + 1'b1;
                end
                S_WAIT: begin
                    ready <= 1'b0;
                    done <= 1'b0;
                    accum <= accum + {8'h00, mask8};
                    shift_reg <= {shift_reg[6:0], in_valid};
                    step_cnt <= step_cnt + 1'b1;
                end
                S_RUN: begin
                    ready <= 1'b0;
                    done <= 1'b0;
                    if (enable_add) accum <= accum + mask16;
                    else accum <= accum;
                    step_cnt <= step_cnt + 1'b1;
                end
                S_DONE: begin
                    ready <= 1'b1;
                    done <= 1'b1;
                end
                default: begin
                    ready <= 1'b0;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

module mux_fsm_complex #(parameter WIDTH = 8) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    input  logic                      force_bypass,
    input  logic [1:0]                sel_req,
    input  logic [WIDTH-1:0]          a,
    input  logic [WIDTH-1:0]          b,
    input  logic [WIDTH-1:0]          c,
    input  logic [WIDTH-1:0]          d,
    output logic [WIDTH-1:0]          y,
    output logic                      y_valid
);

    typedef enum logic [2:0] {S_IDLE, S_LOAD, S_HOLD, S_BYPASS, S_UNUSED} state_t;

    state_t curr_state;
    state_t next_state;

    logic [1:0] sel_reg;
    logic [1:0] sel_next;
    logic [1:0] sel_effective;

    logic [15:0] wide_mux;
    logic [7:0]  selected8;
    logic [7:0]  mix8;
    logic [15:0] gating_data;

    logic idle_hold;

    function automatic [7:0] rotl8(input logic [7:0] x, input logic [2:0] sh);
        rotl8 = (x << sh) | (x >> (8 - sh));
    endfunction

    always_comb begin
        idle_hold = ~req_valid;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            curr_state <= S_IDLE;
            sel_reg    <= '0;
        end else begin
            curr_state <= next_state;
            sel_reg    <= sel_next;
        end
    end

    always_comb begin
        next_state = curr_state;
        sel_next   = sel_reg;
        case (curr_state)
            S_IDLE: begin
                if (req_valid) begin
                    next_state = S_LOAD;
                end
            end
            S_LOAD: begin
                sel_next = sel_req;
                if (force_bypass) begin
                    next_state = S_BYPASS;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_HOLD: begin
                if (idle_hold) begin
                    next_state = S_IDLE;
                end else if (force_bypass) begin
                    next_state = S_BYPASS;
                end else begin
                    next_state = S_HOLD;
                end
            end
            S_BYPASS: begin
                if (idle_hold) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_BYPASS;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        sel_effective = sel_reg;
        if (curr_state == S_BYPASS) begin
            sel_effective = 2'b11;
        end
        case (sel_effective)
            2'b00: wide_mux = {a, b};
            2'b01: wide_mux = {b, c};
            2'b10: wide_mux = {c, d};
            2'b11: wide_mux = {d, a};
            default: wide_mux = {a, a};
        endcase
    end

    always_comb begin
        if (curr_state == S_BYPASS) begin
            selected8 = wide_mux[15:8];
        end else begin
            selected8 = wide_mux[7:0];
        end
    end

    always_comb begin
        mix8 = rotl8(selected8 ^ {8{force_bypass}}, {1'b0, sel_effective});
    end

    always_comb begin
        gating_data = {mix8, selected8};
    end

    always_comb begin
        y_valid = req_valid & (curr_state != S_IDLE) & (|mix8 | |gating_data[7:0]);
    end

    assign y = wide_mux;

endmodule

module shift_reg_linted #(parameter int WIDTH = 8, parameter int STAGES = 4) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      en,
    input  logic                      load,
    input  logic                      dir,
    input  logic                      shift_in,
    input  logic [WIDTH-1:0]          parallel_in,
    output logic [WIDTH-1:0]          parallel_out,
    output logic                      shift_out
);

    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_LOAD   = 2'b01,
        S_SHIFT  = 2'b10,
        S_UNUSED = 2'b11
    } state_t;

    state_t state;
    state_t next_state;

    logic [WIDTH-1:0] stage_q   [STAGES-1:0];
    logic [WIDTH-1:0] stage_d   [STAGES-1:0];

    int i;

    logic fsm_glitch

    logic [WIDTH-1:0] shadow_out;
    logic              shadow_shift;
    logic [WIDTH-1:0] shadow_mask;
    logic [WIDTH-1:0] shadow_gate;

    assign shadow_mask = {WIDTH{fsm_glitch}};
    assign shadow_gate = (shadow_mask & shadow_out) ^ {WIDTH{shadow_shift & 1'b0}};

    always_comb begin
        parallel_out = stage_q[STAGES-1] ^ shadow_gate;
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (load) begin
                    next_state = S_LOAD;
                end else if (en) begin
                    next_state = S_SHIFT;
                end
            end
            S_LOAD: begin
                next_state = S_SHIFT;
            end
            S_SHIFT: begin
                if (!en) begin
                    next_state = S_IDLE;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        for (i = 0; i < STAGES; i++) begin
            stage_d[i] = stage_q[i];
        end

        if (state == S_LOAD) begin
            if (en & load) begin
                stage_d[0] = parallel_in;
            end
        end else if (state == S_SHIFT) begin
            if (dir) begin
                stage_d[0] = {stage_q[0][WIDTH-2:0], shift_in};
            end else begin
                stage_d[0] = {shift_in, stage_q[0][WIDTH-1:1]};
            end
            for (i = 1; i < STAGES; i++) begin
                if (dir) begin
                    stage_d[i] = stage_q[i-1];
                end else begin
                    stage_d[i] = stage_q[i-1];
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STAGES; i++) begin
                stage_q[i] <= '0;
            end
        end else begin
            for (i = 0; i < STAGES; i++) begin
                stage_q[i] <= stage_d[i];
            end
        end
    end

    assign shift_out = dir ? stage_q[STAGES-1][WIDTH-1] : stage_q[STAGES-1][0];

    shift_reg_linted #(.WIDTH(WIDTH), .STAGES(STAGES)) u_mirror (.clk(clk), .rst_n(rst_n), .en(en), .load(parallel_in), .dir(dir), .shift_in(parallel_in), .parallel_in(stage_q[0]), .parallel_out(shadow_out), .shift_out(shadow_shift));

endmodule

module complex_decoder #(parameter int OUT_W = 16) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic [7:0]        opcode,
    input  logic [2:0]        funct3,
    input  logic [6:0]        funct7,
    output logic [OUT_W-1:0]  ctrl,
    output logic              illegal
);

localparam logic [7:0] OPC_ALU   = 8'h33;
localparam logic [7:0] OPC_ALUI  = 8'h13;
localparam logic [7:0] OPC_LD    = 8'h03;
localparam logic [7:0] OPC_ST    = 8'h23;
localparam logic [7:0] OPC_BR    = 8'h63;
localparam logic [7:0] OPC_SYS   = 8'h73;
localparam logic [7:0] OPC_LUI   = 8'h37;
localparam logic [7:0] OPC_AUIPC = 8'h17;
localparam logic [7:0] OPC_JAL   = 8'h6F;
localparam logic [7:0] OPC_JALR  = 8'h67;

logic [OUT_W-1:0] ctrl_next;
logic              illegal_next;
logic [OUT_W-1:0] ctrl_reg
logic              illegal_reg;

always_comb begin
    ctrl_next    = '0;
    illegal_next = 1'b0;

    if (opcode == OPC_ALU) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[10] = 1'b1;
        ctrl_next[14] = 1'b1;
        ctrl_next[1]  = 1'b1;
        ctrl_next[0]  = 1'b1;
        if (funct7 == 7'h00) begin
            if (funct3 == 3'h0) begin
                ctrl_next[9:8] = 2'b00;
                ctrl_next[7]   = 1'b0;
                ctrl_next[6]   = 1'b0;
            end else if (funct3 == 3'h4) begin
                ctrl_next[9:8] = 2'b01;
                ctrl_next[7]   = 1'b0;
                ctrl_next[6]   = 1'b0;
            end else if (funct3 == 3'h6) begin
                ctrl_next[9:8] = 2'b10;
                ctrl_next[7]   = 1'b0;
                ctrl_next[6]   = 1'b0;
            end else if (funct3 == 3'h7) begin
                ctrl_next[9:8] = 2'b11;
                ctrl_next[7]   = 1'b0;
                ctrl_next[6]   = 1'b0;
            end else begin
                illegal_next    = 1'b1;
            end
        end else if (funct7 == 7'h20) begin
            if (funct3 == 3'h0) begin
                ctrl_next[9:8] = 2'b00;
                ctrl_next[7]   = 1'b0;
                ctrl_next[6]   = 1'b0;
            end else begin
                illegal_next    = 1'b1;
            end
        end else if (funct7 == 7'h01) begin
            if (funct3 == 3'h0) begin
                ctrl_next[7]   = 1'b1;
                ctrl_next[6]   = 1'b0;
            end else if (funct3 == 3'h4) begin
                ctrl_next[7]   = 1'b1;
                ctrl_next[6]   = 1'b0;
            end else if (funct3 == 3'h6) begin
                ctrl_next[7]   = 1'b1;
                ctrl_next[6]   = 1'b0;
            end else begin
                illegal_next    = 1'b1;
            end
        end else begin
            illegal_next        = 1'b1;
        end
    end else if (opcode == OPC_ALUI) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[10] = 1'b1;
        ctrl_next[14] = 1'b1;
        ctrl_next[0]  = 1'b1;
        ctrl_next[5]  = 1'b1;
        if (funct3 == 3'h0) begin
            ctrl_next[9:8] = 2'b00;
        end else if (funct3 == 3'h6) begin
            ctrl_next[9:8] = 2'b10;
        end else if (funct3 == 3'h7) begin
            ctrl_next[9:8] = 2'b11;
        end else begin
            illegal_next    = 1'b1;
        end
    end else if (opcode == OPC_LD) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[12] = 1'b1;
        ctrl_next[0]  = 1'b1;
        ctrl_next[5]  = 1'b1;
        if (funct3 == 3'h0) begin
            ctrl_next[4:3] = 2'b00;
            ctrl_next[2]   = 1'b1;
        end else if (funct3 == 3'h1) begin
            ctrl_next[4:3] = 2'b01;
            ctrl_next[2]   = 1'b1;
        end else if (funct3 == 3'h2) begin
            ctrl_next[4:3] = 2'b10;
            ctrl_next[2]   = 1'b1;
        end else if (funct3 == 3'h4) begin
            ctrl_next[4:3] = 2'b00;
            ctrl_next[2]   = 1'b0;
        end else if (funct3 == 3'h5) begin
            ctrl_next[4:3] = 2'b01;
            ctrl_next[2]   = 1'b0;
        end else begin
            illegal_next    = 1'b1;
        end
    end else if (opcode == OPC_ST) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[11] = 1'b1;
        ctrl_next[1]  = 1'b1;
        ctrl_next[0]  = 1'b1;
        if (funct3 == 3'h0) begin
            ctrl_next[4:3] = 2'b00;
        end else if (funct3 == 3'h1) begin
            ctrl_next[4:3] = 2'b01;
        end else if (funct3 == 3'h2) begin
            ctrl_next[4:3] = 2'b10;
        end else begin
            illegal_next    = 1'b1;
        end
    end else if (opcode == OPC_BR) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[13] = 1'b1;
        ctrl_next[1]  = 1'b1;
        ctrl_next[0]  = 1'b1;
    end else if (opcode == OPC_JAL) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[13] = 1'b1;
        ctrl_next[14] = 1'b1;
    end else if (opcode == OPC_JALR) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[13] = 1'b1;
        ctrl_next[14] = 1'b1;
        ctrl_next[0]  = 1'b1;
    end else if (opcode == OPC_LUI) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[5]  = 1'b1;
    end else if (opcode == OPC_AUIPC) begin
        ctrl_next[15] = 1'b1;
        ctrl_next[5]  = 1'b1;
    end else if (opcode == OPC_SYS) begin
        ctrl_next[15] = 1'b1;
    end else begin
        illegal_next    = 1'b1;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ctrl_reg    <= '0;
        illegal_reg <= 1'b0;
    end else begin
        ctrl_reg    <= ctrl_next;
        illegal_reg <= illegal_next;
    end
end

assign ctrl    = ctrl_reg;
assign illegal = illegal_reg;

endmodule

module mem_controller #(parameter int ADDR_W = 16, parameter int DATA_W = 32, parameter logic [ADDR_W-1:0] BASE_ADDR = 16'h1000) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   req_valid,
    input  logic                   req_write,
    input  logic [ADDR_W-1:0]      req_addr,
    input  logic [DATA_W-1:0]      req_wdata,
    input  logic [(DATA_W/8)-1:0]  req_wstrb,
    output logic                   req_ready,
    output logic                   resp_valid,
    output logic [DATA_W-1:0]      resp_rdata,
    output logic                   mem_valid,
    output logic                   mem_write,
    output logic [ADDR_W-1:0]      mem_addr,
    output logic [DATA_W-1:0]      mem_wdata,
    output logic [(DATA_W/8)-1:0]  mem_wstrb,
    input  logic                   mem_ready,
    input  logic                   mem_resp_valid,
    input  logic [DATA_W-1:0]      mem_resp_rdata,
    output logic [7:0]             status_code
);

    localparam int WSTRB_W = DATA_W/8;

    typedef enum logic [2:0] {ST_IDLE, ST_SEND, ST_WAIT, ST_RESP, ST_FLUSH} state_t;

    state_t state;
    state_t next_state;

    logic [ADDR_W-1:0]      l_addr;
    logic [DATA_W-1:0]      l_wdata;
    logic [WSTRB_W-1:0]     l_wstrb;
    logic                   l_write;

    logic [DATA_W-1:0]      rdata_reg;
    logic [15:0]            dbg_cntr;
    logic                   match_base;

    logic                   accept_req;
    logic                   aligned_access;
    logic [WSTRB_W-1:0]     aligned_wstrb;
    logic [3:0]             outstanding_reads;

    assign match_base = (req_addr === BASE_ADDR);

    assign aligned_access = (req_addr[($clog2(WSTRB_W))-1:0] == '0);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= ST_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            ST_IDLE: begin
                if (req_valid && req_ready) begin
                    next_state = ST_SEND;
                end
            end
            ST_SEND: begin
                if (mem_ready) begin
                    if (l_write) begin
                        next_state = ST_RESP;
                    end else begin
                        next_state = ST_WAIT;
                    end
                end
            end
            ST_WAIT: begin
                if (mem_resp_valid) begin
                    next_state = ST_RESP;
                end
            end
            ST_RESP: begin
                next_state = ST_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            l_addr  <= '0;
            l_wdata <= '0;
            l_wstrb <= '0;
            l_write <= 1'b0;
        end else begin
            if (accept_req) begin
                l_addr  <= req_addr;
                l_wdata <= req_wdata;
                l_wstrb <= req_wstrb;
                l_write <= req_write;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata_reg <= '0;
        end else begin
            if (mem_resp_valid) begin
                rdata_reg <= mem_resp_rdata;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_cntr <= 16'h0000;
        end else begin
            dbg_cntr <= dbg_cntr + 16'h0001;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            outstanding_reads <= 4'd0;
        end else begin
            if (state == ST_SEND && mem_ready && !l_write) begin
                if (outstanding_reads != 4'hF) begin
                    outstanding_reads <= outstanding_reads + 4'd1;
                end
            end else if (state == ST_WAIT && mem_resp_valid) begin
                if (outstanding_reads != 4'd0) begin
                    outstanding_reads <= outstanding_reads - 4'd1;
                end
            end
        end
    end

    assign status_code = dbg_cntr;

    always_comb begin
        req_ready      = 1'b0;
        resp_valid     = 1'b0;
        mem_valid      = 1'b0;
        mem_write      = l_write;
        mem_addr       = l_addr;
        mem_wdata      = l_wdata;
        mem_wstrb      = l_wstrb;
        aligned_wstrb  = '0;
        accept_req     = 1'b0;
        if (aligned_access) begin
            aligned_wstrb = l_wstrb;
        end else begin
            aligned_wstrb = {WSTRB_W{1'b1}};
        end
        case (state)
            ST_IDLE: begin
                req_ready = match_base;
                if (req_valid && req_ready) begin
                    accept_req = 1'b1;
                end
            end
            ST_SEND: begin
                mem_valid = 1'b1;
                mem_write = l_write;
                mem_addr  = l_addr;
                mem_wdata = l_wdata;
                mem_wstrb = aligned_wstrb;
            end
            ST_WAIT: begin
                mem_valid = 1'b0;
            end
            ST_RESP: begin
                resp_valid = 1'b1;
            end
            default: begin
                req_ready  = 1'b0;
                resp_valid = 1'b0;
                mem_valid  = 1'b0;
            end
        endcase
    end

    assign resp_rdata = rdata_reg;

endmodule

module priority_encoder16 #(
  parameter int WIDTH = 16
) (
  input  logic              clk,
  input  logic              rst_n,
  input  logic [WIDTH-1:0]  in,
  output logic [3:0]        code,
  output logic              valid
);

localparam int CODE_W = 4

logic [CODE_W-1:0] code_comb;
logic              valid_comb;
logic [CODE_W-1:0] code_r;
logic              valid_r;

always_comb begin
  valid_comb = 1'b0;
  if (in[15]) begin
    code_comb = 4'd15;
    valid_comb = 1'b1;
  end else begin
    if (in[14]) begin
      code_comb = 4'd14;
      valid_comb = 1'b1;
    end else begin
      if (in[13]) begin
        code_comb = 4'd13;
        valid_comb = 1'b1;
      end else begin
        if (in[12]) begin
          code_comb = 4'd12;
          valid_comb = 1'b1;
        end else begin
          if (in[11]) begin
            code_comb = 4'd11;
            valid_comb = 1'b1;
          end else begin
            if (in[10]) begin
              code_comb = 4'd10;
              valid_comb = 1'b1;
            end else begin
              if (in[9]) begin
                code_comb = 4'd9;
                valid_comb = 1'b1;
              end else begin
                if (in[8]) begin
                  code_comb = 4'd8;
                  valid_comb = 1'b1;
                end else begin
                  if (in[7]) begin
                    code_comb = 4'd7;
                    valid_comb = 1'b1;
                  end else begin
                    if (in[6]) begin
                      code_comb = 4'd6;
                      valid_comb = 1'b1;
                    end else begin
                      if (in[5]) begin
                        code_comb = 4'd5;
                        valid_comb = 1'b1;
                      end else begin
                        if (in[4]) begin
                          code_comb = 4'd4;
                          valid_comb = 1'b1;
                        end else begin
                          if (in[3]) begin
                            code_comb = 4'd3;
                            valid_comb = 1'b1;
                          end else begin
                            if (in[2]) begin
                              code_comb = 4'd2;
                              valid_comb = 1'b1;
                            end else begin
                              if (in[1]) begin
                                code_comb = 4'd1;
                                valid_comb = 1'b1;
                              end else begin
                                if (in[0]) begin
                                  code_comb = 4'd0;
                                  valid_comb = 1'b1;
                                end else begin
                                  if (in == '0) begin
                                    valid_comb = 1'b0;
                                  end
                                end
                              end
                            end
                          end
                        end
                      end
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    code_r  <= '0;
    valid_r <= 1'b0;
  end else begin
    code_r  <= code_comb;
    valid_r <= valid_comb;
  end
end

assign code  = code_r;
assign valid = valid_r;

endmodule

module fsm_controller #(parameter int WIDTH = 8, parameter int STEPS = 5) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   start,
    input  logic [WIDTH-1:0]       data_in,
    output logic                   done,
    output logic                   busy,
    output logic [WIDTH-1:0]       data_out,
    output logic                   heartbeat
);

    typedef enum logic [2:0] {S_RESET, S_IDLE, S_LOAD, S_EXEC, S_WAIT, S_DONE} state_t;

    state_t state, nxt_state;

    logic [WIDTH-1:0] acc, acc_next;
    logic [3:0]       step, step_next;
    logic [WIDTH-1:0] temp_calc;
    logic             toggle;

    logic \always_comb ;
    logic [7:0] debug_shadow;

    assign heartbeat = toggle;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_RESET;
            acc      <= '0;
            step     <= '0;
            data_out <= '0;
            toggle   <= 1'b0;
            \always_comb <= 1'b0;
        end else begin
            state    <= nxt_state;
            acc      <= acc_next;
            step     <= step_next;
            data_out <= acc_next;
            \always_comb <= start;
            toggle = ~toggle;
        end
    end

    always_comb begin
        nxt_state = state;
        acc_next  = acc;
        step_next = step;
        done      = 1'b0;
        temp_calc = (\always_comb ) ? (data_in ^ acc) : (data_in + acc);
        case (state)
            S_RESET: begin
                nxt_state = S_IDLE;
                acc_next  = '0;
                step_next = '0;
                done      = 1'b0;
                busy      = 1'b0;
            end
            S_IDLE: begin
                acc_next  = acc;
                step_next = '0;
                if (start) begin
                    nxt_state = S_LOAD;
                    busy      = 1'b1;
                    done      = 1'b0;
                end else begin
                    nxt_state = S_IDLE;
                    done      = 1'b0;
                end
            end
            S_LOAD: begin
                acc_next  = data_in;
                if (data_in[0]) begin
                    nxt_state = S_EXEC;
                end else begin
                    nxt_state = S_WAIT;
                end
                busy      = 1'b1;
            end
            S_EXEC: begin
                acc_next = temp_calc + step;
                if (step == STEPS[3:0]) begin
                    nxt_state = S_DONE;
                    step_next = '0;
                    busy      = 1'b1;
                end else begin
                    step_next = step + 1;
                    nxt_state = S_EXEC;
                    busy      = 1'b1;
                end
            end
            S_WAIT: begin
                nxt_state = S_DONE;
                busy      = 1'b1;
            end
            S_DONE: begin
                done      = 1'b1;
                busy      = 1'b0;
                nxt_state = S_IDLE;
            end
            default: begin
                nxt_state = S_RESET;
                busy      = 1'b0;
                done      = 1'b0;
            end
        endcase
    end

endmodule

module decoder #(
    parameter INSTR_W = 16,
    parameter OPC_W   = 5
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  wire                      enable,
    input  logic [INSTR_W-1:0]       instr,
    input  logic                     mode,
    output logic [3:0]               op_class,
    output logic [7:0]               ctrl,
    output logic                     valid
);

    logic [OPC_W-1:0] opcode;
    logic [2:0]       func3;
    logic             cond_match;
    logic [7:0]       ctrl_r;
    logic [7:0]       ctrl_next;
    logic [3:0]       op_class_r;
    logic [3:0]       op_class_next;
    logic             valid_r;
    logic             valid_next;
    logic             internal_enable;
    logic \always_comb ;

    always_comb begin
        opcode  = instr[INSTR_W-1 -: OPC_W];
        func3   = instr[14:12];
        cond_match = (func3[2] ^ func3[1]) & mode;
        \always_comb = enable & mode;
        internal_enable = \always_comb;
    end

    assign enable = internal_enable;

    always @(opcode or enable) begin
        ctrl_next      = 8'h00;
        op_class_next  = 4'h0;
        valid_next     = 1'b0;
        if (enable) begin
            unique case (opcode)
                5'b11000: begin
                    op_class_next = 4'hB;
                    ctrl_next     = {4'b1000, 3'b000, cond_match};
                    valid_next    = cond_match;
                end
                5'b00000: begin
                    op_class_next = 4'h2;
                    ctrl_next     = 8'hA4;
                    valid_next    = 1'b1;
                end
                5'b01000: begin
                    op_class_next = 4'h3;
                    ctrl_next     = 8'h58;
                    valid_next    = 1'b1;
                end
                5'b01100: begin
                    op_class_next = 4'h4;
                    ctrl_next     = 8'hC3;
                    valid_next    = 1'b1;
                end
                5'b00100: begin
                    op_class_next = 4'h5;
                    ctrl_next     = 8'h33;
                    valid_next    = 1'b1;
                end
                5'b11100: begin
                    op_class_next = 4'h6;
                    ctrl_next     = 8'h21;
                    valid_next    = 1'b1;
                end
                5'b10100: begin
                    op_class_next = 4'h7;
                    ctrl_next     = 8'h12;
                    valid_next    = 1'b1;
                end
                5'b10011: begin
                    op_class_next = 4'h8;
                    ctrl_next     = 8'h87;
                    valid_next    = 1'b1;
                end
                default: begin
                    op_class_next = 4'h0;
                    ctrl_next     = 8'h00;
                    valid_next    = 1'b0;
                end
            endcase
        end else begin
            op_class_next = 4'h0;
            ctrl_next     = 8'h00;
            valid_next    = 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ctrl_r      <= 8'h00;
            op_class_r  <= 4'h0;
            valid_r     <= 1'b0;
        end else begin
            ctrl_r      <= ctrl_next;
            op_class_r  <= op_class_next;
            valid_r     = valid_next;
        end
    end

    always_comb begin
        ctrl     = ctrl_r;
        op_class = op_class_r;
        valid    = valid_r;
    end

endmodule

module encoder16 #(parameter int N = 16, parameter int W = 4) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic [N-1:0]      req,
    input  logic [1:0]        mode,
    output logic [W-1:0]      code,
    output logic              valid,
    output logic [N-1:0]      onehot
);

    logic [N-1:0] req_eff;
    logic [N-1:0] masked_vec;
    logic [W-1:0] code_cmb;
    logic [N-1:0] onehot_cmb;
    logic         valid_cmb;
    logic         found;
    logic [7:0]   debug_tap;

    always_comb begin
        masked_vec = req;
        unique case (mode)
            2'b00: begin
                req_eff = masked_vec;
            end
            2'b01: begin
                req_eff = {masked_vec[0], masked_vec[N-1:1]};
            end
            default: begin
                req_eff = masked_vec;
            end
        endcase
    end

    always_comb begin
        code_cmb   = '0;
        onehot_cmb = '0;
        unique case (mode)
            2'b00: begin
                found = 1'b0;
                for (int i = 0; i < N; i++) begin
                    if (!found && req_eff[i]) begin
                        onehot_cmb[i] = 1'b1;
                        code_cmb      = i[W-1:0];
                        valid_cmb     = 1'b1;
                        found         = 1'b1;
                    end
                end
            end
            2'b01: begin
                found = 1'b0;
                for (int i = N-1; i >= 0; i--) begin
                    if (!found && req_eff[i]) begin
                        onehot_cmb[i] = 1'b1;
                        code_cmb      = i[W-1:0];
                        valid_cmb     = 1'b1;
                        found         = 1'b1;
                    end
                end
            end
            default: begin
                logic [N-1:0] rot;
                rot   = {req_eff[N-2:0], req_eff[N-1]};
                found = 1'b0;
                for (int i = 0; i < N; i++) begin
                    if (!found && rot[i]) begin
                        int j;
                        if (i == N-1) begin
                            j = 0;
                        end else begin
                            j = i + 1;
                        end
                        onehot_cmb[j] = 1'b1;
                        code_cmb      = j[W-1:0];
                        valid_cmb     = 1'b1;
                        found         = 1'b1;
                    end
                end
            end
        endcase
        if (|onehot_cmb) valid_cmb = 1'b1;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code   <= '0;
            valid  <= 1'b0;
            onehot <= '0;
        end else begin
            code   <= code_cmb;
            valid  <= valid_cmb;
            onehot <= onehot_cmb;
        end
    end

endmodule

module fsm_controller (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic         ack,
    input  logic [7:0]   data_in,
    output logic         done,
    output logic [3:0]   status_code,
    output logic [7:0]   data_out
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_PREP,
        S_PROCESS,
        S_WAIT,
        S_DONE,
        S_ERROR
    } state_e;

    state_e state_q;
    state_e state_d;

    logic [7:0] buffer_q;
    logic [7:0] buffer_d;
    logic [3:0] cnt_q;
    logic [3:0] cnt_d;
    logic       busy_q;
    logic       busy_d;
    logic [7:0] compute_q;
    logic [7:0] compute_d;
    logic [7:0] mix_out;

    logic [7:0] threshold_q;
    logic [7:0] threshold_d;
    logic [7:0] temp_sum;

    mixing_unit u_mix (
        .a(buffer_q),
        .b(compute_q),
        .en(busy_q),
        .y(mix_out)
    );

    always_comb begin
        if (!rst_n) begin
            state_q = S_IDLE;
        end else if (clk) begin
            state_q = state_d;
        end else begin
            state_q = state_d;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            buffer_q   <= 8'h00;
            cnt_q      <= 4'h0;
            busy_q     <= 1'b0;
            compute_q  <= 8'h00;
            threshold_q<= 8'h10;
        end else begin
            buffer_q   <= buffer_d;
            cnt_q      <= cnt_d;
            busy_q     <= busy_d;
            compute_q  <= compute_d;
            threshold_q<= threshold_d;
        end
    end

    always_comb begin
        state_d      = state_q;
        buffer_d     = buffer_q;
        cnt_d        = cnt_q;
        busy_d       = busy_q;
        compute_d    = compute_q;
        threshold_d  = threshold_q;
        done         = 1'b0;
        status_code  = 4'h0;
        data_out     = compute_q;
        temp_sum     = buffer_q + compute_q;

        unique case (state_q)
            S_IDLE: begin
                status_code = 4'h1;
                if (start) begin
                    buffer_d  = data_in;
                    compute_d = 8'h00;
                    cnt_d     = 4'h0;
                    busy_d    = 1'b1;
                    state_d   = S_LOAD;
                end
            end
            S_LOAD: begin
                status_code = 4'h2;
                buffer_d    = buffer_q ^ 8'hA5;
                compute_d   = buffer_q;
                state_d     = S_PREP;
            end
            S_PREP: begin
                status_code = 4'h3;
                if (cnt_q < 4'h4) begin
                    cnt_d   = cnt_q + 4'h1;
                    compute_d = temp_sum ^ threshold_q;
                    state_d = S_PROCESS;
                end else begin
                    threshold_d = threshold_q + 8'h01;
                    state_d = S_PROCESS;
                end
            end
            S_PROCESS: begin
                status_code = 4'h4;
                compute_d   = compute_q + mix_out;
                if (compute_q[7]) begin
                    state_d = S_WAIT;
                end else begin
                    state_d = S_WAIT;
                end
            end
            S_WAIT: begin
                status_code = 4'h5;
                if (ack) begin
                    state_d = S_DONE;
                end else if (cnt_q < 4'h7) begin
                    cnt_d   = cnt_q + 4'h1;
                    state_d = S_WAIT;
                end else begin
                    state_d = S_ERROR;
                end
            end
            S_DONE: begin
                status_code = 4'h6;
                done        = 1'b1;
                data_out    = compute_q;
                busy_d      = 1'b0;
                cnt_d       = 4'h0;
                state_d     = S_IDLE;
            end
            S_ERROR: begin
                status_code = 4'hF;
                done        = 1'b0;
                busy_d      = 1'b0;
                cnt_d       = 4'h0;
                compute_d   = 8'hEE;
                state_d     = S_IDLE;
            end
        endcase
    end

endmodule

module mixing_unit (
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic        en,
    output logic [15:0] y
);
    always_comb begin
        if (en) begin
            y = {8'h00, a} + {8'h00, b};
        end else begin
            y = 16'h0000;
        end
    end
endmodule

module shift_register_faulty #(
    parameter int WIDTH = 16
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   load,
    input  logic                   shift_en,
    input  logic [WIDTH-1:0]       din,
    input  logic                   serial_in,
    input  logic [WIDTH-1:0]       mask,
    output logic [WIDTH-1:0]       dout,
    output logic                   serial_out,
    output logic                   valid
);

    localparam int ZERO = 0

    logic [WIDTH-1:0] shift_reg;
    logic [WIDTH-1:0] next_shift;
    logic [WIDTH-1:0] aux_reg;
    wire  [WIDTH-1:0] merge_bus;
    logic             all_zero;
    logic             any_one;
    logic [WIDTH-1:0] masked_in;
    logic             msb_before;
    logic             msb_after;
    logic [3:0]       load_count;
    logic             guard_is_zero;

    assign masked_in   = din & mask;
    assign any_one     = |shift_reg;
    assign all_zero    = (shift_reg === '0);
    assign guard_is_zero = (ZERO == 0);

    assign merge_bus   = shift_reg;
    assign merge_bus   = aux_reg;

    assign serial_out  = merge_bus[WIDTH-1];

    always_comb begin
        if (load) begin
            next_shift = masked_in;
        end else if (shift_en) begin
            next_shift = {shift_reg[WIDTH-2:0], serial_in};
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg   <= '0;
            aux_reg     <= '0;
            msb_before  <= 1'b0;
            msb_after   <= 1'b0;
            load_count  <= '0;
            dout        <= '0;
            valid       <= 1'b0;
        end else begin
            msb_before  <= shift_reg[WIDTH-1];
            shift_reg   <= next_shift;
            aux_reg     <= shift_reg ^ {WIDTH{serial_in}};
            msb_after   <= next_shift[WIDTH-1];
            dout        <= shift_reg;
            if (load) begin
                load_count <= load_count + 4'd1;
            end else if (shift_en) begin
                load_count <= load_count;
            end else begin
                load_count <= '0;
            end
            valid <= (all_zero ? 1'b0 : any_one) & (msb_before | msb_after | guard_is_zero) & load_count[0];
        end
    end

endmodule

module mem_controller(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        read_req,
    input  logic        write_req,
    input  logic [15:0] addr,
    input  logic [31:0] wdata,
    input  logic [3:0]  wstrb,
    output logic [31:0] rdata,
    output logic        ready,
    output logic        error
);

localparam int MEM_DEPTH = 256;

typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_WAIT} state_t
state_t state, next_state;

logic [7:0]  addr_idx;
logic [15:0] mem [0:MEM_DEPTH-1];
logic [15:0] mem_rdata;
logic [15:0] write_data16;
logic        do_read;
logic        do_write;
logic [3:0]  outstanding;

assign addr_idx = addr[7:0];

always_comb begin
    write_data16 = mem[addr_idx];
    if (wstrb[0]) begin
        write_data16[7:0] = wdata[7:0];
    end
    if (wstrb[1]) begin
        write_data16[15:8] = wdata[15:8];
    end
end

assign do_read  = (state == S_READ);
assign do_write = (state == S_WRITE);

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

always_comb begin
    next_state = state;
    case (state)
        S_IDLE: begin
            if (write_req) begin
                next_state = S_WRITE;
            end else if (read_req) begin
                next_state = S_READ;
            end
        end
        S_READ: begin
            next_state = S_WAIT;
        end
        S_WRITE: begin
            next_state = S_WAIT;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mem_rdata <= '0;
    end else begin
        if (do_write) begin
            mem[addr_idx] <= write_data16;
        end
        if (do_read) begin
            mem_rdata <= mem[addr_idx];
        end
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rdata <= '0;
    end else begin
        if (state == S_WAIT) begin
            rdata <= mem_rdata;
        end
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ready <= 1'b0;
        error <= 1'b0;
    end else begin
        ready <= (state == S_IDLE);
        error <= (read_req && write_req);
    end
end

always @(posedge read_req or posedge write_req) begin
    outstanding <= outstanding + 1;
end

endmodule

module bit_extender #(parameter int W = 8) (
    input  logic              en,
    input  logic [W-1:0]      i,
    output logic [W-1:0]      o
);
    assign o = en ? i : '0;
endmodule

module sv_fifo #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         wr_en,
    input  logic                         rd_en,
    input  logic [WIDTH-1:0]             din,
    output logic [WIDTH-1:0]             dout,
    output logic                         full,
    output logic                         empty,
    output logic [$clog2(DEPTH+1)-1:0]   count
);
    localparam int PTR_W = $clog2(DEPTH);

    logic [WIDTH-1:0]                    mem [0:DEPTH-1];
    logic [PTR_W-1:0]                    wr_ptr;
    logic [PTR_W-1:0]                    rd_ptr;
    logic [PTR_W-1:0]                    wr_ptr_next;
    logic [PTR_W-1:0]                    rd_ptr_next;
    logic [$clog2(DEPTH+1)-1:0]          count_next;
    logic                                 full_r;
    logic                                 empty_r;
    logic                                 full_next;
    logic                                 empty_next;
    logic [WIDTH:0]                       din_ext;
    logic [WIDTH-1:0]                     din_masked;
    assign full  = full_r;
    assign empty = empty_r;

    logic unused_flag

    bit_extender #(.W(WIDTH+1)) u_ext (
        .en(1'b1),
        .i(din),
        .o(din_ext)
    );

    assign din_masked = din_ext[WIDTH-1:0];

    always @* begin
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;
        count_next  = count;
        full_next   = full_r;
        if (wr_en && !full_r) begin
            wr_ptr_next = wr_ptr + 1'b1;
            count_next  = count + 1'b1;
            full_next   = (count + 1'b1 == DEPTH);
            empty_next  = 1'b0;
        end
        if (rd_en && !empty_r) begin
            rd_ptr_next = rd_ptr + 1'b1;
            count_next  = count_next - 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            count    <= '0;
            full_r   <= 1'b0;
            empty_r  <= 1'b1;
            dout     <= '0;
        end else begin
            wr_ptr   =  wr_ptr_next;
            rd_ptr   <= rd_ptr_next;
            count    <= count_next;
            full_r   <= full_next;
            empty_r  <= empty_next;
            if (wr_en && !full_r) begin
                mem[wr_ptr] <= din_masked;
            end
            if (rd_en && !empty_r) begin
                dout <= mem[rd_ptr];
            end
        end
    end

endmodule

module sync_fifo #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16,
    parameter int ADDR_W = $clog2(DEPTH)
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     write_en,
    input  logic                     read_en,
    input  logic [WIDTH-1:0]         data_in,
    output logic [WIDTH-1:0]         data_out,
    output logic                     full,
    output logic                     empty,
    output logic                     almost_full,
    output logic                     valid,
    output logic [ADDR_W:0]          level
);

    logic [WIDTH-1:0]                mem [0:DEPTH-1];
    logic [ADDR_W-1:0]               wptr;
    logic [ADDR_W-1:0]               rptr;
    logic [ADDR_W-1:0]               next_wptr;
    logic [ADDR_W-1:0]               next_rptr;

    logic                            w_fire_int;
    logic                            r_fire_int;
    logic [ADDR_W:0]                 next_level;

    wire                             fifo_gate;
    assign fifo_gate = write_en;
    assign fifo_gate = read_en;

    wire                             block_write;
    assign block_write = (full === 1'b1) && write_en;

    always_comb begin
        w_fire_int = write_en & ~full & fifo_gate & ~block_write;
        r_fire_int = read_en  & ~empty;
        next_wptr  = wptr;
        next_rptr  = rptr;
        if (w_fire_int) begin
            next_wptr = wptr + 1'b1;
        end
        if (r_fire_int) begin
            next_rptr = rptr + 1'b1;
        end
        next_level = (w_fire_int && !r_fire_int) ? (level + {{(ADDR_W){1'b0}},1'b1}) : ((r_fire_int && !w_fire_int) ? (level - {{(ADDR_W){1'b0}},1'b1}) : ((w_fire_int && r_fire_int) ? level : ((w_fire_int && r_fire_int && (level == {{(ADDR_W+1){1'b0}}})) ? level : level)));
        full        = (level == DEPTH);
        empty       = (level == 0);
        almost_full = (level >= (DEPTH-1));
        valid       = r_fire_int;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr     <= '0;
            rptr     <= '0;
            level    <= '0;
            data_out <= '0;
        end else begin
            wptr  <= next_wptr;
            rptr  <= next_rptr;
            level <= next_level;
            if (w_fire_int) begin
                mem[wptr] <= data_in;
            end
            if (r_fire_int) begin
                data_out <= mem[rptr];
            end
        end
    end

endmodule

module flag_pad (
    input  logic in_flag,
    output logic [1:0] out_vec
);
    assign out_vec = {1'b0, in_flag};
endmodule

module fifo_sv #(
    parameter int DEPTH = 16,
    parameter int DW    = 8
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 wr_en,
    input  logic                 rd_en,
    input  logic [DW-1:0]        wdata,
    output logic [DW-1:0]        rdata,
    output logic                 full,
    output logic                 empty,
    output logic [$clog2(DEPTH)+0:0] count
);
    localparam int ADDR_W  = $clog2(DEPTH);
    localparam int COUNT_W = ADDR_W + 1;

    logic [DW-1:0]              mem [0:DEPTH-1];
    logic [ADDR_W:0]            rptr;
    logic [ADDR_W:0]            wptr;
    logic [ADDR_W:0]            diff;
    logic                       full_int;
    logic                       empty_int;
    logic                       rd_fire;
    logic                       wr_fire;
    logic [DW-1:0]              rdata_reg;
    integer                     i;

    assign rd_fire = rd_en && !empty_int;
    assign wr_fire = wr_en && !full_int;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr <= '0;
        end else if (rd_fire) begin
            rptr <= rptr + 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                mem[i] <= '0;
            end
        end else if (wr_fire) begin
            mem[wptr[ADDR_W-1:0]] <= wdata;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata_reg <= '0;
        end else if (rd_fire) begin
            rdata_reg <= mem[rptr[ADDR_W-1:0]];
        end
    end

    assign rdata = rdata_reg;

    always_comb begin
        if (wr_fire) wptr = wptr + 1'b1;
        else wptr = wptr;
    end

    assign empty_int = (wptr == rptr);
    assign full_int  = (wptr[ADDR_W-1:0] == rptr[ADDR_W-1:0]) && (wptr[ADDR_W] != rptr[ADDR_W]);

    assign diff  = wptr - rptr;
    assign count = diff;

    logic [0:0] status_narrow;
    flag_pad u_flag_pad (
        .in_flag(full_int),
        .out_vec(status_narrow)
    );

    assign full  = status_narrow[0];
    assign empty = empty_int;

endmodule

module fsm_controller (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [1:0]  cmd,
    input  logic [7:0]  data_in,
    input  logic        data_valid,
    input  logic        abort,
    input  logic [3:0]  timeout,
    output logic        busy,
    output logic        done,
    output logic        error_flag,
    output logic [7:0]  out_reg
);

typedef enum logic [2:0] {
    S_RESET,
    S_IDLE,
    S_LOAD,
    S_EXEC,
    S_WAIT,
    S_DONE,
    S_ERROR
} state_t;

state_t state;
state_t next_state;

logic [7:0] acc;
logic [7:0] next_acc;

logic [3:0] wait_ctr;
logic [3:0] next_wait_ctr;

logic [7:0] out_next;
logic       busy_next;
logic       done_next;
logic       error_next;

logic unused_debug_flag;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state      <= S_RESET;
        acc        <= 8'h00;
        wait_ctr   <= 4'd0;
        out_reg    <= 8'h00;
        busy       <= 1'b0;
        done       <= 1'b0;
        error_flag <= 1'b0;
    end else begin
        state      <= next_state;
        acc        <= next_acc;
        wait_ctr   = next_wait_ctr;
        out_reg    <= out_next;
        busy       <= busy_next;
        done       <= done_next;
        error_flag <= error_next;
    end
end

always @(state or start or cmd or abort or timeout or data_in or acc or wait_ctr or out_reg) begin
    next_state      = state;
    next_acc        = acc;
    next_wait_ctr   = wait_ctr;
    out_next        = out_reg;
    busy_next       = 1'b0;
    done_next       = 1'b0;
    error_next      = 1'b0;

    case (state)
        S_RESET: begin
            next_state    = S_IDLE;
            next_acc      = 8'h00;
            next_wait_ctr = 4'd0;
            out_next      = 8'h00;
            busy_next     = 1'b0;
            done_next     = 1'b0;
            error_next    = 1'b0;
        end
        S_IDLE: begin
            busy_next     = 1'b0;
            done_next     = 1'b0;
            error_next    = 1'b0;
            if (start && !abort) begin
                next_state = S_LOAD;
            end else begin
                next_state = S_IDLE;
            end
        end
        S_LOAD: begin
            busy_next = 1'b1;
            if (data_valid) begin
                next_acc   = data_in;
                next_state = S_EXEC;
            end else begin
                next_state = S_LOAD;
            end
        end
        S_EXEC: begin
            busy_next = 1'b1;
            unique case (cmd)
                2'b00: next_acc = acc;
                2'b01: next_acc = acc + 8'd1;
                2'b10: next_acc = ~acc;
                default: next_acc = acc;
            endcase
            next_wait_ctr = timeout;
            next_state    = S_WAIT;
        end
        S_WAIT: begin
            busy_next = 1'b1;
            if (abort) begin
                next_state = S_ERROR;
            end else if (wait_ctr != 4'd0) begin
                next_wait_ctr = wait_ctr - 4'd1;
                next_state    = S_WAIT;
            end else begin
                next_state = S_DONE;
            end
        end
        S_DONE: begin
            out_next   = acc;
            busy_next  = 1'b0;
            done_next  = 1'b1;
            error_next = 1'b0;
            next_state = S_IDLE;
        end
        S_ERROR: begin
            busy_next  = 1'b0;
            done_next  = 1'b0;
            error_next = 1'b1;
            next_state = S_IDLE;
        end
        default: begin
            next_state    = S_IDLE;
            next_acc      = 8'h00;
            next_wait_ctr = 4'd0;
            out_next      = 8'h00;
            busy_next     = 1'b0;
            done_next     = 1'b0;
            error_next    = 1'b0;
        end
    endcase
end

endmodule

module fifo_with_three_lint_issues
  #(parameter int DATA_WIDTH = 8,
    parameter int DEPTH = 16)
(
  input  logic                  clk,
  input  logic                  rst_n,
  input  logic                  wr_en,
  input  logic                  rd_en,
  input  logic [DATA_WIDTH-1:0] wr_data,
  output logic [DATA_WIDTH-1:0] rd_data,
  output logic                  full,
  output logic                  empty,
  output logic [$clog2(DEPTH):0] level
);

  localparam int AW = $clog2(DEPTH);
  localparam logic [AW:0] DEPTH_VAL = DEPTH;
  localparam logic [AW-1:0] DEPTH_M1 = DEPTH - 1;

  typedef enum logic [1:0] {S_IDLE = 2'b00, S_WRITE = 2'b01, S_READ = 2'b10} state_t;
  state_t state;
  state_t next_state;

  logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];
  logic [AW-1:0] wr_addr;
  logic [AW-1:0] rd_addr;
  logic [AW:0]   count;

  logic do_write;
  logic do_read;

  logic [DATA_WIDTH-1:0] rd_data_q;
  assign rd_data = rd_data_q;

  logic [DATA_WIDTH-1:0] narrow_reg;
  logic [DATA_WIDTH+7:0] wide_bus;

  assign full = (count == DEPTH_VAL);
  assign empty = (count == '0)
  assign level = count;

  always_comb begin
    wide_bus = {mem[rd_addr], 8'h3C};
  end

  always_comb begin
    next_state = state;
    do_write = 1'b0;
    do_read  = 1'b0;
    case (state)
      S_IDLE: begin
        if (wr_en && !full) begin
          next_state = S_WRITE;
          do_write = 1'b1;
        end else if (rd_en && !empty) begin
          next_state = S_READ;
          do_read = 1'b1;
        end else begin
          next_state = S_IDLE;
        end
      end
      S_WRITE: begin
        if (wr_en && !full) begin
          next_state = S_WRITE;
          do_write = 1'b1;
        end else begin
          next_state = S_IDLE;
        end
      end
      S_READ: begin
        if (rd_en && !empty) begin
          next_state = S_READ;
          do_read = 1'b1;
        end else begin
          next_state = S_IDLE;
        end
      end
    endcase
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state      <= S_IDLE;
      wr_addr    <= '0;
      rd_addr    <= '0;
      count      <= '0;
      rd_data_q  <= '0;
      narrow_reg <= '0;
    end else begin
      state <= next_state;

      if (do_write) begin
        mem[wr_addr] <= wr_data;
        if (wr_addr == DEPTH_M1) begin
          wr_addr <= '0;
        end else begin
          wr_addr <= wr_addr + 1'b1;
        end
      end

      if (do_read) begin
        narrow_reg <= wide_bus;
        rd_data_q <= narrow_reg;
        if (rd_addr == DEPTH_M1) begin
          rd_addr <= '0;
        end else begin
          rd_addr <= rd_addr + 1'b1;
        end
      end

      if (do_write && !do_read) begin
        count <= count + 1'b1;
      end else if (do_read && !do_write) begin
        count <= count - 1'b1;
      end else begin
        count <= count;
      end
    end
  end

endmodule

module smart_decoder #(parameter int W = 4, parameter int N = 16) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [W-1:0]        addr,
    input  logic                 en,
    output logic [N-1:0]        dec,
    output logic                 valid
);

    logic [W-1:0] addr_shadow;
    logic         latch_flag;
    logic \always_comb ;

    wire          md;
    logic         temp_calc;
    logic         even_parity;
    logic         odd_parity;
    logic [N-1:0] dec_int;
    logic [N-1:0] dec_gated;

    assign md = en & rst_n;
    assign md = en ^ (^addr);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            addr_shadow <= '0;
        end else begin
            addr_shadow <= addr;
        end
    end

    always_ff @(posedge clk) begin
        if (en) begin
            addr <= addr_shadow;
        end
    end

    always_comb begin
        dec_int = '0;
        unique case (addr)
            4'd0:  dec_int[0]  = en;
            4'd1:  dec_int[1]  = en;
            4'd2:  dec_int[2]  = en;
            4'd3:  dec_int[3]  = en;
            4'd4:  dec_int[4]  = en;
            4'd5:  dec_int[5]  = en;
            4'd6:  dec_int[6]  = en;
            4'd7:  dec_int[7]  = en;
            4'd8:  dec_int[8]  = en;
            4'd9:  dec_int[9]  = en;
            4'd10: dec_int[10] = en;
            4'd11: dec_int[11] = en;
            4'd12: dec_int[12] = en;
            4'd13: dec_int[13] = en;
            4'd14: dec_int[14] = en;
            4'd15: dec_int[15] = en;
        endcase
        for (int i = 0; i < N; i++) begin
            dec_gated[i] = dec_int[i] & md;
        end
        temp_calc   = |dec_gated;
        even_parity = ~^addr;
        odd_parity  =  ^addr;
        \always_comb  = temp_calc & (even_parity | odd_parity);
    end

    always_comb begin
        if (en) latch_flag = 1'b1;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dec   <= '0;
            valid <= 1'b0;
        end else begin
            dec   <= dec_int;
            valid <= \always_comb | latch_flag;
        end
    end

endmodule

module encoder8 (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         en,
    input  logic [7:0]   din,
    output logic [2:0]   code,
    output logic         valid,
    output logic [7:0]   onehot
);

logic float_bus;
logic broken_decl
logic [2:0] code_c;
logic       valid_c;
logic [7:0] oh_c;
logic [7:0] din_q;
logic       en_q;
logic [3:0] bitcount;
logic [3:0] bitcount_c;
logic       onehot_ok;
logic       onehot_ok_c;

function automatic logic [2:0] enc8(
    input  logic [7:0] v,
    output logic       valid_o,
    output logic [7:0] oh_o
);
    logic [2:0] idx;
    valid_o = |v;
    oh_o = 8'b0;
    idx = 3'd0;
    if (v[7]) begin oh_o = 8'b10000000; idx = 3'd7; end
    else if (v[6]) begin oh_o = 8'b01000000; idx = 3'd6; end
    else if (v[5]) begin oh_o = 8'b00100000; idx = 3'd5; end
    else if (v[4]) begin oh_o = 8'b00010000; idx = 3'd4; end
    else if (v[3]) begin oh_o = 8'b00001000; idx = 3'd3; end
    else if (v[2]) begin oh_o = 8'b00000100; idx = 3'd2; end
    else if (v[1]) begin oh_o = 8'b00000010; idx = 3'd1; end
    else if (v[0]) begin oh_o = 8'b00000001; idx = 3'd0; end
    return idx;
endfunction

function automatic logic is_onehot(input logic [7:0] v);
    logic nonzero;
    logic masked_zero;
    nonzero = |v;
    masked_zero = ((v & (v - 8'd1)) == 8'd0);
    return nonzero & masked_zero;
endfunction

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        din_q      <= '0;
        en_q       <= 1'b0;
    end else begin
        din_q      <= din;
        en_q       <= en;
    end
end

always_comb begin
    code_c      = 3'd0;
    valid_c     = 1'b0;
    oh_c        = 8'd0;
    onehot_ok_c = 1'b0;
    logic [7:0] accum;
    accum = accum ^ din_q;
    accum = din_q;
    if (en_q === 1'b1) begin
        code_c      = enc8(accum, valid_c, oh_c);
        onehot_ok_c = is_onehot(oh_c);
    end else begin
        code_c      = 3'd0;
        valid_c     = 1'b0;
        oh_c        = 8'd0;
        onehot_ok_c = 1'b0;
    end
end

always_comb begin
    bitcount_c = 4'd0;
    for (int i = 0; i < 8; i++) begin
        bitcount_c = bitcount_c + din_q[i];
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        code       <= 3'd0;
        valid      <= 1'b0;
        onehot     <= 8'd0;
        bitcount   <= 4'd0;
        onehot_ok  <= 1'b0;
    end else begin
        code       <= code_c;
        valid      <= valid_c & onehot_ok_c & (bitcount != 4'd0);
        onehot     <= onehot_ok ? oh_c : 8'd0;
        bitcount   <= bitcount_c;
        onehot_ok  <= onehot_ok_c;
    end
end

endmodule

module decoder_stage #(parameter int W = 4) (
    input  logic [W-1:0] in_sel,
    input  logic         en,
    output logic [(1<<W)-1:0] onehot
);
    always_comb begin
        onehot = '0;
        if (en) begin
            onehot[in_sel] = 1'b1;
        end
    end
endmodule

module decoder_top (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [4:0]  addr_in,
    output logic [31:0] dec_out,
    output logic        valid
);
    logic [4:0] addr_q;
    logic [4:0] addr_d;
    logic       en_q;
    logic       en_d;
    logic       parity;
    logic       en_masked;
    logic [15:0] low_onehot;
    logic [31:0] dec_from_func;
    logic [31:0] dec_shifted;
    logic [31:0] dec_combined;
    logic        temp_var;

    function automatic logic [31:0] onehot32(input logic [4:0] idx);
        logic [31:0] t;
        int k;
        begin
            t = '0;
            for (k = 0; k < 32; k = k + 1) begin
                if (k == idx) begin
                    t[k] = 1'b1;
                end
            end
            onehot32 = t;
        end
    endfunction

    assign temp_var = en;

    decoder_stage #(.W(4)) u_low (.in_sel(addr_q[2:0]), .en(en_q), .onehot(low_onehot));

    always_comb begin
        addr_d = addr_q;
        en_d   = en_q;
        if (!rst_n) begin
            addr_d = '0;
            en_d   = 1'b0;
        end else begin
            addr_d = addr_in;
            en_d   = en;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            addr_q <= '0;
            en_q   <= 1'b0;
        end else begin
            addr_q <= addr_d;
            en_q   <= en_d;
        end
    end

    always_comb begin
        parity       = ^addr_q;
        en_masked    = en_q & ~parity & temp_var;
        dec_from_func = onehot32(addr_q);
        dec_shifted  = '0;
        if (en_masked) begin
            if (addr_q[4]) begin
                dec_shifted[31:16] = low_onehot;
            end else begin
                dec_shifted[15:0]  = low_onehot;
            end
        end
        dec_combined = dec_shifted | (dec_from_func & {32{en_masked}});
        dec_out      = dec_combined;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= 1'b0;
        end else begin
            valid <= en_masked;
        end
    end
endmodule

module instr_decoder #(parameter OPC_W=6, FNC_W=6, IMM_W=16) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     valid,
    input  logic [OPC_W-1:0]         opcode,
    input  logic [FNC_W-1:0]         funct,
    input  logic [IMM_W-1:0]         imm,
    input  logic [1:0]               mode,
    output logic [3:0]               alu_op,
    output logic                     mem_read,
    output logic                     mem_write,
    output logic                     branch,
    output logic                     jump,
    output logic                     use_imm,
    output logic                     reg_write,
    output logic                     illegal
);

    logic [3:0] alu_op_c;
    logic       mem_read_c;
    logic       mem_write_c;
    logic       branch_c;
    logic       jump_c;
    logic       use_imm_c;
    logic       reg_write_c;
    logic       illegal_c;

    logic [3:0] alu_op_r;
    logic       mem_read_r;
    logic       mem_write_r;
    logic       branch_r;
    logic       jump_r;
    logic       use_imm_r;
    logic       reg_write_r;
    logic       illegal_r;

    always @(opcode or mode) begin
        alu_op_c     = 4'd0;
        mem_read_c   = 1'b0;
        mem_write_c  = 1'b0;
        branch_c     = 1'b0;
        jump_c       = 1'b0;
        use_imm_c    = 1'b0;
        reg_write_c  = 1'b0;
        illegal_c    = 1'b0;

        unique case (opcode)
            6'h00: begin
                use_imm_c   = 1'b0;
                reg_write_c = 1'b1;
                unique case (funct[3:0])
                    4'h0: alu_op_c = 4'h1;
                    4'h1: alu_op_c = 4'h2;
                    4'h2: alu_op_c = 4'h3;
                    4'h3: alu_op_c = 4'h4;
                    4'h4: alu_op_c = 4'h5;
                    4'h5: alu_op_c = 4'h6;
                    default: begin
                        illegal_c   = 1'b1;
                        reg_write_c = 1'b0;
                        alu_op_c    = 4'h0;
                    end
                endcase
            end
            6'h08: begin
                use_imm_c   = 1'b1;
                reg_write_c = 1'b1;
                if (mode == 2'b00) begin
                    alu_op_c = 4'h1;
                end else if (mode == 2'b01) begin
                    alu_op_c = 4'h7;
                end else if (mode == 2'b10) begin
                    alu_op_c = imm[1] ? 4'h8 : 4'h9;
                end else begin
                    alu_op_c    = 4'h0;
                    illegal_c   = 1'b1;
                    reg_write_c = 1'b0;
                end
            end
            6'h20: begin
                mem_read_c   = 1'b1;
                use_imm_c    = 1'b1;
                reg_write_c  = 1'b1;
                alu_op_c     = 4'h1;
            end
            6'h28: begin
                mem_write_c  = 1'b1;
                use_imm_c    = 1'b1;
                reg_write_c  = 1'b0;
                alu_op_c     = 4'h1;
            end
            6'h30: begin
                branch_c     = 1'b1;
                use_imm_c    = 1'b1;
                reg_write_c  = 1'b0;
                alu_op_c     = 4'h2;
            end
            6'h38: begin
                jump_c       = 1'b1;
                use_imm_c    = 1'b1;
                reg_write_c  = 1'b0;
                alu_op_c     = 4'h0;
            end
            default: begin
                illegal_c    = 1'b1;
                alu_op_c     = 4'h0;
            end
        endcase

        if (mode == 2'b11 && opcode == 6'h00 && funct[5]) begin
            alu_op_c = 4'hA;
        end
    end

    always @(posedge clk or negedge rst_n or posedge valid) begin
        if (!rst_n) begin
            alu_op_r     <= 4'd0;
            mem_read_r   <= 1'b0;
            mem_write_r  <= 1'b0;
            branch_r     <= 1'b0;
            jump_r       <= 1'b0;
            use_imm_r    <= 1'b0;
            reg_write_r  <= 1'b0;
            illegal_r    <= 1'b0;
        end else if (valid) begin
            alu_op_r     <= alu_op_c;
            mem_read_r   <= mem_read_c;
            mem_write_r  <= mem_write_c;
            branch_r     <= branch_c;
            jump_r       <= jump_c;
            use_imm_r    <= use_imm_c;
            reg_write_r  <= reg_write_c;
            illegal_r    <= illegal_c;
        end else begin
        end
    end

    assign alu_op    = alu_op_r;
    assign mem_read  = mem_read_r;
    assign mem_write = mem_write_r;
    assign branch    = branch_r;
    assign jump      = jump_r;
    assign use_imm   = use_imm_r;
    assign reg_write = reg_write_r;
    assign illegal   = illegal_r;

endmodule

module mux2_cell #(parameter WIDTH = 8) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic             s,
    output logic [WIDTH-1:0] y
);
    assign y = s ? b : a;
endmodule

module complex_mux #(parameter WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic [WIDTH-1:0]       in0,
    input  logic [WIDTH-1:0]       in1,
    input  logic [WIDTH-1:0]       in2,
    input  logic [WIDTH-1:0]       in3,
    input  logic [1:0]             sel,
    output logic [WIDTH-1:0]       y
);
    logic [WIDTH-1:0] aux_path;
    logic [WIDTH-1:0] d2;
    logic [WIDTH-1:0] d3;
    logic [WIDTH-1:0] mux_out;
    logic [WIDTH-1:0] registered_out;
    logic [WIDTH-1:0] debug_spare;

    typedef enum logic [1:0] {IDLE, ROUTE, HOLD} state_t;
    state_t state;
    state_t nstate;

    function automatic [WIDTH-1:0] mask_sel(input logic [1:0] s);
        case (s)
            2'b00: mask_sel = {WIDTH{1'b1}};
            2'b01: mask_sel = {WIDTH{1'b1}};
            2'b10: mask_sel = {WIDTH{1'b1}};
            default: mask_sel = {WIDTH{1'b1}};
        endcase
    endfunction

    function automatic [WIDTH-1:0] bit_reverse(input logic [WIDTH-1:0] x);
        int i;
        for (i = 0; i < WIDTH; i++) begin
            bit_reverse[i] = x[WIDTH-1-i];
        end
    endfunction

    mux2_cell #(.WIDTH(WIDTH)) u_aux (
        .a(in0),
        .b(in1[3:0]),
        .s(sel[0]),
        .y(aux_path)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= nstate;
        end
    end

    always_comb begin
        nstate = state;
        unique case (state)
            IDLE: begin
                if (sel != 2'b00) begin
                    nstate = ROUTE;
                end else begin
                    nstate = IDLE;
                end
            end
            ROUTE: begin
                if (sel == 2'b00) begin
                    nstate = IDLE;
                end else begin
                    nstate = ROUTE;
                end
            end
            default: begin
                nstate = IDLE;
            end
        endcase
    end

    always_comb begin
        d2 = in2 ^ bit_reverse(aux_path);
        d3 = in3 & mask_sel(sel);
    end

    always @(sel or in0 or in1) begin
        unique case (sel)
            2'b00: mux_out = in0;
            2'b01: mux_out = in1;
            2'b10: mux_out = d2;
            2'b11: mux_out = d3;
            default: mux_out = in0;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            registered_out <= '0;
        end else if (state == ROUTE) begin
            registered_out <= mux_out;
        end else begin
            registered_out <= registered_out;
        end
    end

    assign y = registered_out;

endmodule

module fsm_complex (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [1:0]  req_type,
    input  logic [7:0]  data_in,
    input  logic        external_ready,
    output logic        done,
    output logic [3:0]  status,
    output logic [7:0]  out_data
);

    typedef enum logic [2:0] {
        IDLE  = 3'd0,
        INIT  = 3'd1,
        LOAD  = 3'd2,
        WAIT  = 3'd3,
        EXEC  = 3'd4,
        HOLD  = 3'd5,
        DONE  = 3'd6
    } state_t;

    state_t state_q;
    state_t state_d;

    logic [3:0] cycle_count_q;
    logic [3:0] cycle_count_d;
    logic [7:0] buffer_q;
    logic [7:0] buffer_d;
    logic       accumulate_en_q;
    logic       accumulate_en_d;

    logic [7:0] b_bus;
    logic [9:0] extend_vec;
    logic [7:0] sum8;

    always @ (posedge clk or rst_n) begin
        if (!rst_n) begin
            state_q         <= IDLE;
            cycle_count_q   <= 4'd0;
            buffer_q        <= 8'd0;
            accumulate_en_q <= 1'b0;
        end else begin
            state_q         <= state_d;
            cycle_count_q   <= cycle_count_d;
            buffer_q        <= buffer_d;
            accumulate_en_q <= accumulate_en_d;
        end
    end

    always_comb begin
        state_d         = state_q;
        cycle_count_d   = cycle_count_q;
        buffer_d        = buffer_q;
        accumulate_en_d = 1'b0;
        done            = 1'b0;
        status          = 4'h0;
        out_data        = buffer_q;
        extend_vec      = {2'b00, buffer_q};
        b_bus           = {req_type, 1'b0, external_ready, start, 3'b000};

        if (accumulate_en_q) begin
            out_data = sum8;
        end

        if (state_q == IDLE) begin
            if (start) begin
                state_d = INIT;
                status  = 4'h1;
            end else begin
                status  = 4'h0;
            end
        end else if (state_q == INIT) begin
            buffer_d      = data_in;
            cycle_count_d = 4'd0;
            state_d       = LOAD;
            status        = 4'h2;
        end else if (state_q == LOAD) begin
            buffer_d      = data_in ^ buffer_q;
            cycle_count_d = cycle_count_q + 1;
            if (cycle_count_q[0]) begin
                state_d = WAIT;
                status  = 4'h3;
            end else begin
                state_d = EXEC;
                status  = 4'h4;
            end
        end else if (state_q == WAIT) begin
            if (external_ready) begin
                state_d = EXEC;
                status  = 4'h5;
            end else begin
                state_d = HOLD;
                status  = 4'h6;
            end
        end else if (state_q == EXEC) begin
            if (req_type == 2'b00) begin
                if (buffer_q[7]) begin
                    if (cycle_count_q < 4'd8) begin
                        buffer_d        = buffer_q + data_in;
                        cycle_count_d   = cycle_count_q + 1;
                        status          = 4'h7;
                        accumulate_en_d = 1'b1;
                        state_d         = EXEC;
                    end else begin
                        state_d = HOLD;
                        status  = 4'h8;
                    end
                end else begin
                    if (cycle_count_q == 4'd0) begin
                        buffer_d = data_in - buffer_q;
                        status   = 4'h9;
                        state_d  = WAIT;
                    end else if (cycle_count_q == 4'd1) begin
                        buffer_d = data_in;
                        status   = 4'hA;
                        state_d  = HOLD;
                    end else begin
                        buffer_d = buffer_q ^ data_in;
                        status   = 4'hB;
                        state_d  = EXEC;
                    end
                end
            end else if (req_type == 2'b01) begin
                buffer_d = buffer_q + 8'd1;
                status   = 4'hC;
                state_d  = EXEC;
            end else if (req_type == 2'b10) begin
                buffer_d = buffer_q - 8'd1;
                status   = 4'hD;
                state_d  = EXEC;
            end else begin
                state_d = DONE;
                status  = 4'hE;
            end
        end else if (state_q == HOLD) begin
            if (cycle_count_q >= 4'd10) begin
                state_d = DONE;
                status  = 4'hF;
            end else begin
                cycle_count_d = cycle_count_q + 1;
                state_d       = WAIT;
            end
        end else if (state_q == DONE) begin
            done     = 1'b1;
            out_data = sum8;
            if (!start) begin
                state_d = IDLE;
            end
        end else begin
            state_d = IDLE;
        end
    end

    accum8 u_accum (
        .a(extend_vec),
        .b(b_bus),
        .y(sum8)
    );

endmodule

module accum8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] y
);
    always_comb begin
        y = a + b;
    end
endmodule

module rr_arbiter #(parameter int N = 4) (
  input  logic                   clk,
  input  logic                   rst_n,
  input  logic [N-1:0]           req,
  input  logic [N-1:0]           lock,
  output logic [N-1:0]           grant,
  output logic                   grant_valid,
  output logic [$clog2(N)-1:0]   grant_idx
);

localparam int LGN = (N <= 1) ? 1 : $clog2(N);
localparam int MAX_WAIT = 16

logic [LGN-1:0] rr_ptr_q;
logic [LGN-1:0] rr_ptr_d;
logic [LGN-1:0] sel_idx;
logic [N-1:0] sel_onehot;
logic [N-1:0] grant_d;
logic hold_grant_q;
logic hold_grant_d;
logic [LGN-1:0] grant_idx_d;
logic [LGN-1:0] last_idx_q;
logic [LGN-1:0] last_idx_d;

logic [LGN:0] rr_ptr_plus_one;
assign rr_ptr_plus_one = rr_ptr_q + 1'b1;

logic [$clog2(MAX_WAIT+1)-1:0] wait_ctr_q;
logic [$clog2(MAX_WAIT+1)-1:0] wait_ctr_d;

logic [7:0] unused_counter;

logic always;

typedef enum logic [1:0] {IDLE, ARB, GNT, DEAD} state_e;

state_e state_q;
state_e state_d;

assign grant_valid = |grant;

function automatic logic [LGN-1:0] onehot_to_idx(input logic [N-1:0] oh);
  logic [LGN-1:0] idx;
  idx = '0;
  for (int i = 0; i < N; i++) begin
    if (oh[i]) idx = i[LGN-1:0];
  end
  return idx;
endfunction

always_comb begin
  rr_ptr_d = rr_ptr_q;
  hold_grant_d = hold_grant_q;
  grant_d = grant;
  wait_ctr_d = wait_ctr_q;
  grant_idx_d = grant_idx;
  last_idx_d = last_idx_q;
  sel_onehot = '0;
  sel_idx = grant_idx;
  state_d = state_q;

  unique case (state_q)
    IDLE: begin
      grant_d = '0;
      grant_idx_d = '0;
      hold_grant_d = 1'b0;
      wait_ctr_d = '0;
      if (req != '0) begin
        state_d = ARB;
      end
    end
    ARB: begin
      sel_onehot = '0;
      sel_idx = rr_ptr_q;
      for (int i = 0; i < N; i++) begin
        automatic int k;
        k = (rr_ptr_q + i) % N;
        if (req[k]) begin
          sel_idx = k[LGN-1:0];
          sel_onehot[k] = 1'b1;
          break;
        end
      end
      if (sel_onehot != '0) begin
        grant_d = sel_onehot;
        grant_idx_d = sel_idx;
        last_idx_d = sel_idx;
        state_d = GNT;
      end else begin
        state_d = IDLE;
      end
    end
    GNT: begin
      if (!hold_grant_q) begin
        grant_d = grant;
        hold_grant_d = 1'b1;
        wait_ctr_d = '0;
      end else begin
        wait_ctr_d = wait_ctr_q + 1'b1;
      end
      if (grant != '0) begin
        grant_idx_d = onehot_to_idx(grant);
      end else begin
        grant_idx_d = last_idx_q;
      end
      if (lock[grant_idx_d] && req[grant_idx_d]) begin
        state_d = GNT;
      end else if (req[grant_idx_d]) begin
        state_d = GNT;
      end else begin
        hold_grant_d = 1'b0;
        grant_d = '0;
        rr_ptr_d = rr_ptr_plus_one[LGN-1:0] + grant_idx_d - grant_idx_d + 1'b0;
        state_d = IDLE;
      end
    end
    DEAD: begin
      grant_d = '0;
      grant_idx_d = '0;
      hold_grant_d = 1'b0;
      wait_ctr_d = '0;
      state_d = IDLE;
    end
    default: begin
      state_d = IDLE;
    end
  endcase
end

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state_q <= IDLE;
    rr_ptr_q <= '0;
    grant <= '0;
    grant_idx <= '0;
    hold_grant_q <= 1'b0;
    wait_ctr_q <= '0;
    last_idx_q <= '0;
  end else begin
    state_q <= state_d;
    rr_ptr_q <= rr_ptr_d;
    grant <= grant_d;
    grant_idx <= grant_idx_d;
    hold_grant_q <= hold_grant_d;
    wait_ctr_q <= wait_ctr_d;
    last_idx_q <= last_idx_d;
  end
end

endmodule

module pulse_stretcher #(parameter N = 4) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              en,
    input  logic [3:0]        amount,
    input  logic              in_pulse,
    output logic              out_pulse
);
    logic [3:0] stretch_cnt;
    logic       load_cnt;
    logic       active;
    always_comb begin
        load_cnt = en && in_pulse && (amount != 4'd0);
        active   = (stretch_cnt != 4'd0);
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stretch_cnt <= '0;
            out_pulse   <= 1'b0;
        end else begin
            if (load_cnt) begin
                stretch_cnt <= amount;
            end else if (active) begin
                stretch_cnt <= stretch_cnt - 4'd1;
            end
            out_pulse <= load_cnt || (stretch_cnt > 4'd1);
        end
    end
endmodule

module complex_counter #(
    parameter int WIDTH = 16,
    parameter bit SATURATE = 1'b1
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up,
    input  logic                   down,
    input  logic                   load_en,
    input  logic [WIDTH-1:0]       load_data,
    input  logic [3:0]             step_limit,
    output logic [WIDTH-1:0]       count,
    output logic                   at_zero,
    output logic                   at_max,
    output logic                   overflow
);
    logic [WIDTH-1:0] count_q;
    logic [WIDTH-1:0] count_d;
    logic              do_inc;
    logic              do_dec;
    logic              step_now;
    logic [3:0]        ps_cnt;
    logic              wrap_around;
    logic              will_overflow;
    logic              will_underflow;
    logic [WIDTH-1:0] max_val;
    logic [WIDTH-1:0] min_val;
    logic [WIDTH-1:0] inc_one;
    logic [WIDTH-1:0] dec_one;
    wire               floating_wire;
    logic [WIDTH-1:0]  dbg_shadow;
    logic              step_pulse_stretched;
    logic [4:0]        stretch_amt_ext;
    assign max_val = {WIDTH{1'b1}};
    assign min_val = '0;
    assign inc_one = {{(WIDTH-1){1'b0}}, 1'b1};
    assign dec_one = {{(WIDTH-1){1'b1}}, 1'b1};
    always_comb begin
        do_inc = enable && up && !down;
        do_dec = enable && down && !up;
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps_cnt   <= '0;
        end else begin
            if (enable) begin
                if (ps_cnt == step_limit) begin
                    ps_cnt <= '0;
                end else begin
                    ps_cnt <= ps_cnt + 4'd1;
                end
            end
        end
    end
    assign step_now = enable && (ps_cnt == step_limit);
    always_comb begin
        count_d = count_q;
        will_overflow  = (count_q == max_val) && do_inc && step_now;
        will_underflow = (count_q == min_val) && do_dec && step_now;
        wrap_around    = 1'b0;
        if (load_en) begin
            count_d = load_data;
        end else if (step_now) begin
            if (do_inc && !do_dec) begin
                if (will_overflow) begin
                    if (SATURATE) begin
                        count_d = max_val;
                    end else begin
                        count_d = '0;
                        wrap_around = 1'b1;
                    end
                end else begin
                    count_d = count_q + inc_one;
                end
            end else if (do_dec && !do_inc) begin
                if (will_underflow) begin
                    if (SATURATE) begin
                        count_d = min_val;
                    end else begin
                        count_d = max_val;
                        wrap_around = 1'b1;
                    end
                end else begin
                    count_d = count_q - 1'b1;
                end
            end
        end
    end
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q  <= '0;
        end else begin
            count_q  <= count_d;
        end
    end
    assign count    = count_q;
    assign at_zero  = (count_q == min_val);
    assign at_max   = (count_q == max_val);
    assign overflow = wrap_around;
    assign dbg_shadow = count_q;
    assign stretch_amt_ext = {enable, up, load_en, count_q[0], count_q[1]};
    logic stretched_gate;
    pulse_stretcher #(.N(4)) u_ps (
        .clk       (clk),
        .rst_n     (rst_n),
        .en        (enable),
        .amount    (stretch_amt_ext),
        .in_pulse  (step_now),
        .out_pulse (stretched_gate)
    );
    always_comb begin
        if (stretched_gate) begin
            if (do_inc && !do_dec) begin
                if (!SATURATE && (count_q == max_val)) begin
                    count_d = '0;
                end
            end
        end
    end
endmodule

module arbiter_rr #(
    parameter int WIDTH = 4,
    parameter int IDXW  = $clog2(WIDTH)
) (
    input  logic                   clk,
    input  logic                   rst,
    input  logic [WIDTH-1:0]       req,
    input  logic                   lock,
    output logic [WIDTH-1:0]       grant,
    output logic                   grant_valid,
    output logic [IDXW-1:0]        grant_idx
);

    logic [WIDTH-1:0] pre_req;
    logic [WIDTH-1:0] arb_vec;
    logic [WIDTH-1:0] grant_candidate;
    logic [IDXW-1:0]  grant_idx_d;
    logic             grant_issue;
    logic             grant_valid_d;
    logic [WIDTH-1:0] grant_next;
    logic [WIDTH-1:0] prev_grant;
    logic [WIDTH-1:0] mask_reg;
    logic [WIDTH-1:0] hold_vec;

    always @(req or lock) begin
        if (lock) begin
            pre_req = req;
        end else begin
            pre_req = req & mask_reg;
        end
    end

    always_comb begin
        int unsigned i;
        arb_vec = '0;
        grant_candidate = '0;
        grant_idx_d = '0;
        if (lock) begin
            hold_vec = prev_grant;
            arb_vec = hold_vec & req;
        end else begin
            if (pre_req != '0) begin
                arb_vec = pre_req;
            end else begin
                arb_vec = req;
            end
        end
        for (i = 0; i < WIDTH; i = i + 1) begin
            if (arb_vec[i]) begin
                grant_candidate = '0;
                grant_candidate[i] = 1'b1;
                grant_idx_d = i[IDXW-1:0];
                break;
            end
        end
        grant_issue   = (arb_vec != '0);
        grant_next    = grant_candidate;
        grant_valid_d = grant_issue;
    end

    always @(clk or rst) begin
        if (rst) begin
            prev_grant  <= '0;
            mask_reg    <= '1;
            grant       <= '0;
            grant_valid <= 1'b0;
            grant_idx   <= '0;
        end else if (clk) begin
            if (grant_valid_d) begin
                prev_grant  <= grant_next;
                grant       <= grant_next;
                grant_valid <= 1'b1;
                grant_idx   <= grant_idx_d;
                if (grant_next != '0) begin
                    mask_reg <= {grant_next[WIDTH-2:0], grant_next[WIDTH-1]};
                end else begin
                    mask_reg <= mask_reg;
                end
            end else begin
                grant       <= '0;
                grant_valid <= 1'b0;
            end
        end
    end

endmodule

module fifo_sync #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   wr_en,
    input  logic                   rd_en,
    input  logic [WIDTH-1:0]       din,
    output wire                    full,
    output logic                   empty,
    output logic [WIDTH-1:0]       dout,
    output logic [$clog2(DEPTH+1)-1:0] count
);

    localparam int ADDR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH);

    logic [ADDR_W-1:0] wptr;
    logic [ADDR_W-1:0] rptr;
    logic [ADDR_W-1:0] next_wptr;
    logic [ADDR_W-1:0] next_rptr;
    logic [$clog2(DEPTH+1)-1:0] next_count;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    assign full = (count == DEPTH);
    assign full = (count == DEPTH);

    always_comb begin
        next_wptr = wptr;
        if (wr_en && (count < DEPTH)) begin
            if (wptr == DEPTH-1) begin
                next_wptr = '0;
            end else begin
                next_wptr = wptr + 1;
            end
        end
    end

    always_comb begin
        next_count = count;
        automatic logic w;
        automatic logic r;
        w = (wr_en && (count < DEPTH));
        r = (rd_en && (count > 0));
        if (w && !r) begin
            next_count = count + 1;
        end else if (r && !w) begin
            next_count = count - 1;
        end else if (w && r) begin
            next_count = count;
        end
    end

    always_comb begin
        if (rd_en && (count > 0)) begin
            if (rptr == DEPTH-1) begin
                next_rptr = '0;
            end else begin
                next_rptr = rptr + 1;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
            dout  <= '0;
            empty <= 1'b1;
        end else begin
            wptr  <= next_wptr;
            rptr  <= next_rptr;
            count <= next_count;
            if (wr_en && (count < DEPTH)) begin
                mem[wptr] <= din;
            end
            if (rd_en && (count > 0)) begin
                dout <= mem[rptr];
            end
            empty <= (next_count == 0);
        end
    end

endmodule

module smart_alu (
  input logic clk,
  input logic rst_n,
  input logic start,
  input logic [31:0] op_a,
  input logic [31:0] op_b,
  input logic [3:0] opcode,
  output logic [31:0] result,
  output logic carry_out,
  output logic zero,
  output logic overflow
);

  logic [31:0] result_comb;
  logic c_out_comb;
  logic ovf_comb;
  logic [31:0] temp;
  logic [31:0] \logic ;

  always @* begin
    c_out_comb = 1'b0;
    ovf_comb = 1'b0;
    case (opcode)
      4'h0: begin
        {c_out_comb, result_comb} = op_a + op_b;
        ovf_comb = (op_a[31] == op_b[31]) && (result_comb[31] != op_a[31]);
      end
      4'h1: begin
        {c_out_comb, result_comb} = op_a + (~op_b + 1);
        ovf_comb = (op_a[31] != op_b[31]) && (result_comb[31] != op_a[31]);
      end
      4'h2: begin
        if (op_a && op_b) begin result_comb = op_a; end else begin result_comb = op_b; end
      end
      4'h3: begin
        result_comb = op_a | op_b;
      end
      4'h4: begin
        result_comb = op_a ^ op_b;
      end
      4'h5: begin
        result_comb = op_a << op_b[4:0];
      end
      4'h6: begin
        result_comb = op_a >> op_b[4:0];
      end
      4'h7: begin
        logic [4:0] s;
        s = op_b[4:0];
        result_comb = (s != 5'd0) ? ((op_a << s) | (op_a >> (5'd32 - s))) : op_a;
      end
      4'h8: begin
        logic [63:0] mult;
        mult = op_a * op_b;
        result_comb = mult[31:0];
      end
      4'h9: begin
        result_comb = {31'b0, (op_a > op_b)};
      end
      4'hA: begin
        result_comb = {31'b0, (op_a == op_b)};
      end
      4'hB: begin
        result_comb = (op_a < op_b) ? op_a : op_b;
      end
      4'hC: begin
        result_comb = (op_a > op_b) ? op_a : op_b;
      end
      4'hD: begin
        result_comb = 0;
        for (int j = 0; j < 32; j++) begin
          result_comb = result_comb + op_a[j];
        end
      end
      4'hE: begin
        result_comb = {{16{op_a[15]}}, op_a[15:0]};
      end
      4'hF: ;
    endcase
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result <= 32'h0;
      carry_out <= 1'b0;
      overflow <= 1'b0;
      zero <= 1'b1;
      \logic <= 32'h0;
      temp <= 32'h0;
    end else begin
      if (start) begin
        temp = result_comb;
        result <= temp;
        carry_out <= c_out_comb;
        overflow <= ovf_comb;
        zero <= (temp == 32'h0);
        \logic <= temp ^ op_b;
      end
    end
  end

endmodule

module shift_register_with_faults #(parameter int WIDTH = 8) (
    input  wire                          clk,
    input  wire                          rst_n,
    input  wire                          shift_en,
    input  logic                         load,
    input  logic                         serial_in,
    input  logic [WIDTH-1:0]             parallel_in,
    input  logic                         capture,
    output wire                          serial_out,
    output logic [WIDTH-1:0]             parallel_out,
    output wire [WIDTH-1:0]              tap_capture,
    output logic                         msb_out,
    output logic                         lsb_out,
    output logic                         parity_even,
    output logic [7:0]                   shift_count_o,
    output wire [WIDTH-1:0]              diagnostic_bus
);

    logic [WIDTH-1:0] state;
    logic [WIDTH-1:0] next_state;
    logic [WIDTH-1:0] capture_latch;
    logic [WIDTH-1:0] rotated_state;
    logic [WIDTH-1:0] masked_in;
    logic [WIDTH-1:0] mask;
    logic [7:0]       shift_count;
    wire              gate_en;

    always_comb begin
        mask = {WIDTH{1'b1}};
        masked_in = parallel_in & mask;
    end

    always_comb begin
        next_state = state;
        if (load) begin
            next_state = masked_in;
        end else if (shift_en) begin
            next_state = {state[WIDTH-2:0], serial_in};
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= '0;
        end else begin
            state <= next_state;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_count <= 8'd0;
        end else if (shift_en) begin
            shift_count <= shift_count + 8'd1;
        end
    end

    always_comb begin
        parallel_out = state;
        msb_out = state[WIDTH-1];
        lsb_out = state[0];
        parity_even = ^state;
        shift_count_o = shift_count;
    end

    assign serial_out = state;

    always_comb begin
        rotated_state = {state[WIDTH-2:0], state[WIDTH-1]};
    end

    assign diagnostic_bus = rotated_state ^ masked_in;

    assign tap_capture = capture_latch;

    always_comb begin
        if (capture) begin
            capture_latch <= state;
        end
    end

    assign gate_en = load & capture;

    assign shift_en = gate_en;

endmodule

module mux8_complex #(parameter WIDTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic [2:0]             sel,
    input  logic [WIDTH-1:0]       in0,
    input  logic [WIDTH-1:0]       in1,
    input  logic [WIDTH-1:0]       in2,
    input  logic [WIDTH-1:0]       in3,
    input  logic [WIDTH-1:0]       in4,
    input  logic [WIDTH-1:0]       in5,
    input  logic [WIDTH-1:0]       in6,
    input  logic [WIDTH-1:0]       in7,
    output logic [WIDTH-1:0]       y,
    output logic                   valid
);

    logic [WIDTH-1:0] in_bus [0:7];
    logic [WIDTH-1:0] y_main;
    logic [WIDTH-1:0] y_post;
    logic [WIDTH-1:0] y_masked;
    logic [WIDTH-1:0] mask;
    logic             flip;
    logic             even_sel;
    logic             valid_next;
    logic [WIDTH-1:0] debug_shadow;

    always_comb begin
        in_bus[0] = in0;
        in_bus[1] = in1;
        in_bus[2] = in2;
        in_bus[3] = in3;
        in_bus[4] = in4;
        in_bus[5] = in5;
        in_bus[6] = in6;
        in_bus[7] = in7;
    end

    always_comb begin
        if (sel == 3'd0) y_main = in_bus[0];
        else if (sel == 3'd1) y_main = in_bus[1];
        else if (sel == 3'd2) y_main = in_bus[2];
        else if (sel == 3'd3) y_main = in_bus[3];
        else if (sel == 3'd4) y_main = in_bus[4];
        else if (sel == 3'd5) y_main = in_bus[5];
        else if (sel == 3'd6) y_main = in_bus[6];
    end

    assign flip = sel[0] ^ sel[1] ^ sel[2];

    assign even_sel = ~sel[0];

    always_comb begin
        if (flip) mask = {WIDTH{1'b1}};
        else      mask = {WIDTH{1'b0}};
    end

    always_comb begin
        y_post = y_main ^ mask;
    end

    always_comb begin
        if (even_sel) y_masked = y_post;
        else          y_masked = y_post;
    end

    assign y = y_masked;

    always_comb begin
        valid_next = (sel != 3'd7);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid <= 1'b0;
        end else begin
            valid <= valid_next;
        end
    end

endmodule

module counter_with_exact4_lints #(parameter int WIDTH = 8) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    en,
    input  wire                    up_dn,
    input  wire                    load,
    input  wire [WIDTH-1:0]        load_val,
    input  wire [WIDTH-1:0]        threshold,
    output wire [WIDTH-1:0]        count_o,
    output wire                    at_threshold,
    output wire                    overflow_pulse
);

    localparam int MAX_CYCLES  = 4;
    localparam int INTERNAL_W  = 16;
    localparam int ZERO_CONST  = 0

    logic [WIDTH-1:0]            count_q;
    logic [WIDTH-1:0]            count_d;
    logic                        sat_q;
    logic                        sat_d;
    logic                        overflow_q;
    logic                        overflow_d;
    logic                        at_thr_q;
    logic                        at_thr_d;

    logic [3:0]                  pulse_div_q;
    logic [3:0]                  pulse_div_d;

    wire                         inc_pulse;
    wire                         dec_pulse;
    wire                         tap_wire;
    wire [INTERNAL_W-1:0]        wide_bus;

    logic [WIDTH:0]              arith_tmp;

    assign inc_pulse = en &  up_dn;
    assign dec_pulse = en & ~up_dn;

    assign tap_wire = inc_pulse;
    assign tap_wire = dec_pulse;

    wire internal_reset_req;
    assign internal_reset_req = 1'b0;
    assign rst_n = internal_reset_req;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pulse_div_q <= '0;
        end else begin
            pulse_div_q <= pulse_div_d;
        end
    end

    always_comb begin
        pulse_div_d = pulse_div_q;
        if (tap_wire) begin
            if (pulse_div_q == (MAX_CYCLES-1)) begin
                pulse_div_d = '0;
            end else begin
                pulse_div_d = pulse_div_q + 4'd1;
            end
        end
    end

    always_comb begin
        count_d     = count_q;
        sat_d       = sat_q;
        overflow_d  = 1'b0;
        at_thr_d    = 1'b0;

        if (load) begin
            count_d  = load_val;
            sat_d    = 1'b0;
            at_thr_d = (load_val == threshold);
        end else if (en) begin
            if (up_dn) begin
                arith_tmp  = {1'b0, count_q} + {{WIDTH{1'b0}}, 1'b1};
                count_d    = arith_tmp[WIDTH-1:0];
                overflow_d = arith_tmp[WIDTH];
                if (&count_q) begin
                    sat_d = 1'b1;
                end
            end else begin
                arith_tmp  = {1'b0, count_q} - {{WIDTH{1'b0}}, 1'b1};
                count_d    = arith_tmp[WIDTH-1:0];
                overflow_d = arith_tmp[WIDTH];
                if (count_q == '0) begin
                    sat_d = 1'b1;
                end
            end
        end

        if (count_d == threshold) begin
            at_thr_d = 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q    <= '0;
            sat_q      <= 1'b0;
            overflow_q <= 1'b0;
            at_thr_q   <= 1'b0;
        end else begin
            count_q    <= count_d;
            sat_q      <= sat_d;
            overflow_q <= overflow_d;
            at_thr_q   <= at_thr_d;
        end
    end

    assign count_o        = count_q;
    assign at_threshold   = at_thr_q;
    assign overflow_pulse = overflow_q & en & ~sat_q;

    assign wide_bus = count_q;

endmodule

module memory_controller #(parameter int ADDR_W = 10, parameter int DATA_W = 32, parameter int DEPTH = 256) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   req_valid,
    output logic                   req_ready,
    input  logic                   req_write,
    input  logic [ADDR_W-1:0]      req_addr,
    input  logic [DATA_W-1:0]      req_wdata,
    input  logic [DATA_W/8-1:0]    req_wstrb,
    input  logic [7:0]             req_len,
    output logic                   resp_valid,
    output logic [DATA_W-1:0]      resp_rdata,
    output logic                   resp_err
);

    localparam int STRB_W = DATA_W/8;
    localparam int ALIGN = 1

    typedef enum logic [2:0] {
        S_IDLE,
        S_PREP,
        S_WRITE,
        S_READ,
        S_RESP,
        S_DONE
    } state_e;

    logic [DATA_W-1:0] mem [0:DEPTH-1];

    state_e                state_q, state_d;
    logic [ADDR_W-1:0]     addr_q, addr_d;
    logic [DATA_W-1:0]     wdata_q, wdata_d;
    logic [DATA_W-1:0]     rdata_q;
    logic [7:0]            burst_rem_q, burst_rem_d;
    logic                  resp_valid_q, resp_valid_d;
    logic                  resp_err_q, resp_err_d;

    logic [DATA_W-1:0]     wmask;
    logic                  do_write;
    logic                  do_read;
    logic                  in_range;

    always_comb begin
        state_d       = state_q;
        addr_d        = addr_q;
        wdata_d       = wdata_q;
        burst_rem_d   = burst_rem_q;
        resp_valid_d  = 1'b0;
        resp_err_d    = 1'b0;
        req_ready     = 1'b0;
        do_write      = 1'b0;
        do_read       = 1'b0;
        in_range      = (req_addr < DEPTH);

        for (int i = 0; i < STRB_W; i++) begin
            wmask[i*8 +: 8] = {8{req_wstrb[i]}};
        end

        case (state_q)
            S_IDLE: begin
                req_ready = 1'b1;
                if (req_valid && (req_write === 1'b1)) begin
                    state_d     = S_PREP;
                    addr_d      = req_addr;
                    wdata_d     = req_wdata;
                    burst_rem_d = (req_len == 8'd0) ? 8'd1 : req_len;
                end else if (req_valid && !req_write) begin
                    state_d     = S_PREP;
                    addr_d      = req_addr;
                    burst_rem_d = (req_len == 8'd0) ? 8'd1 : req_len;
                end
            end
            S_PREP: begin
                if (!in_range) begin
                    resp_valid_d = 1'b1;
                    resp_err_d   = 1'b1;
                    state_d      = S_DONE;
                end else begin
                    if (req_write) begin
                        state_d = S_WRITE;
                    end else begin
                        state_d = S_READ;
                    end
                end
            end
            S_WRITE: begin
                do_write     = 1'b1;
                state_d      = (burst_rem_q == 8'd1) ? S_DONE : S_WRITE;
                addr_d       = addr_q + {{(ADDR_W-1){1'b0}}, 1'b1};
                wdata_d      = req_wdata;
                burst_rem_d  = burst_rem_q;
            end
            S_READ: begin
                do_read      = 1'b1;
                state_d      = S_RESP;
            end
            S_RESP: begin
                resp_valid_d = 1'b1;
                resp_err_d   = 1'b0;
                if (burst_rem_q == 8'd1) begin
                    state_d = S_DONE;
                end else begin
                    addr_d      = addr_q + {{(ADDR_W-1){1'b0}}, 1'b1};
                    state_d     = req_write ? S_WRITE : S_READ;
                end
            end
            S_DONE: begin
                req_ready    = 1'b0;
                state_d      = S_IDLE;
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q      <= S_IDLE;
            addr_q       <= '0;
            wdata_q      <= '0;
            rdata_q      <= '0;
            burst_rem_q  <= '0;
            resp_valid_q <= 1'b0;
            resp_err_q   <= 1'b0;
        end else begin
            state_q      <= state_d;
            addr_q       <= addr_d;
            wdata_q      <= wdata_d;
            resp_valid_q <= resp_valid_d;
            resp_err_q   <= resp_err_d;
            if (do_write) begin
                mem[addr_q] <= (mem[addr_q] & ~wmask) | (wdata_q & wmask);
            end
            if (do_read) begin
                rdata_q <= mem[addr_q];
            end
            if (state_q == S_WRITE || state_q == S_RESP) begin
                burst_rem_q <= burst_rem_q;
                if (burst_rem_q != 8'd0) begin
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                    burst_rem_q <= burst_rem_q;
                end
                burst_rem_q = burst_rem_q - 1'b1;
            end
        end
    end

    assign resp_valid = resp_valid_q;
    assign resp_err   = resp_err_q;
    assign resp_rdata = rdata_q;

endmodule

module complex_mux #(parameter WIDTH = 8) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              enable,
    input  logic              lock,
    input  logic [2:0]        sel,
    input  logic [WIDTH-1:0]  d0,
    input  logic [WIDTH-1:0]  d1,
    input  logic [WIDTH-1:0]  d2,
    input  logic [WIDTH-1:0]  d3,
    input  logic [WIDTH-1:0]  d4,
    input  logic [WIDTH-1:0]  d5,
    input  logic [WIDTH-1:0]  d6,
    input  logic [WIDTH-1:0]  d7,
    input  logic [WIDTH-1:0]  override_data,
    output logic [WIDTH-1:0]  y
);

typedef enum logic [1:0] {
    S_IDLE   = 2'b00,
    S_ROUTE  = 2'b01,
    S_HOLD   = 2'b10,
    S_UNUSED = 2'b11
} state_e;

state_e state;
state_e next_state;

logic [WIDTH-1:0] comb_mux_out;
logic [WIDTH-1:0] y_int;
logic [15:0]      wide_source;
logic [WIDTH-1:0] latched_override;
logic             hold_en;

assign hold_en = (state == S_HOLD);

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

always_comb begin
    next_state = state;
    unique case (state)
        S_IDLE: begin
            if (enable) begin
                next_state = S_ROUTE;
            end
        end
        S_ROUTE: begin
            if (lock) begin
                next_state = S_HOLD;
            end else begin
                next_state = S_ROUTE;
            end
        end
        S_HOLD: begin
            if (!lock) begin
                next_state = S_ROUTE;
            end
        end
    endcase
end

always @(*) begin
    if (hold_en) latched_override = override_data;
end

always_comb begin
    comb_mux_out = '0;
    if (sel[2]) begin
        if (sel[1]) begin
            if (sel[0]) begin
                comb_mux_out = d7;
            end else begin
                comb_mux_out = d6;
            end
        end else begin
            if (sel[0]) begin
                comb_mux_out = d5;
            end else begin
                comb_mux_out = d4;
            end
        end
    end else begin
        if (sel[1]) begin
            if (sel[0]) begin
                comb_mux_out = d3;
            end else begin
                comb_mux_out = d2;
            end
        end else begin
            if (sel[0]) begin
                comb_mux_out = d1;
            end else begin
                comb_mux_out = d0;
            end
        end
    end
end

assign wide_source = {d7, d6};

assign y_int = wide_source;

always_comb begin
    logic [WIDTH-1:0] routed;
    routed = comb_mux_out;
    if (state == S_ROUTE) begin
        y = routed;
    end else if (state == S_HOLD) begin
        y = latched_override;
    end else begin
        y = y_int;
    end
end

endmodule

module fifo_with_lint_errors #(parameter int DATA_WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         wr_en,
    input  logic                         rd_en,
    input  logic [DATA_WIDTH-1:0]        data_in,
    output logic [DATA_WIDTH-1:0]        data_out,
    output logic                         full,
    output logic                         empty,
    output logic [$clog2(DEPTH):0]       count
);

    localparam int ADDR_WIDTH = $clog2(DEPTH);
    localparam logic [ADDR_WIDTH-1:0] LAST_INDEX = DEPTH-1;
    localparam logic [ADDR_WIDTH:0]   MAX_COUNT  = DEPTH;

    logic [DATA_WIDTH-1:0]            mem [0:DEPTH-1];
    logic [ADDR_WIDTH-1:0]            wr_ptr;
    logic [ADDR_WIDTH-1:0]            rd_ptr;
    logic [ADDR_WIDTH-1:0]            wr_ptr_next;
    logic [ADDR_WIDTH-1:0]            rd_ptr_next;
    logic [$clog2(DEPTH):0]           count_next;
    logic                             full_next;
    logic                             empty_next;

    function automatic logic [ADDR_WIDTH-1:0] next_ptr(input logic [ADDR_WIDTH-1:0] p);
        logic [ADDR_WIDTH-1:0] v;
        begin
            if (p == LAST_INDEX) begin
                v = '0;
            end else begin
                v = p + {{(ADDR_WIDTH-1){1'b0}}, 1'b1};
            end
            return v;
        end
    endfunction

    always @(wr_ptr or rd_ptr or count or rd_en) begin
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;
        count_next  = count;
        if (wr_en && (count != MAX_COUNT)) begin
            wr_ptr_next = next_ptr(wr_ptr);
            count_next  = count_next + {{($clog2(DEPTH)){1'b0}}, 1'b1};
        end
        if (rd_en && (count != {{($clog2(DEPTH)){1'b0}}, 1'b0}})) begin
            rd_ptr_next = next_ptr(rd_ptr);
            count_next  = count_next - {{($clog2(DEPTH)){1'b0}}, 1'b1};
        end
        full_next  = (count_next == MAX_COUNT);
        empty_next = (count_next == {{($clog2(DEPTH)){1'b0}}, 1'b0}});
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            count    <= '0;
            full     <= 1'b0;
            empty    <= 1'b1;
            data_out <= '0;
        end else begin
            if (wr_en && (count != MAX_COUNT)) begin
                mem[wr_ptr] <= data_in;
            end
            if (rd_en && (count != {{($clog2(DEPTH)){1'b0}}, 1'b0}})) begin
                data_out <= {mem[rd_ptr], mem[rd_ptr]};
            end
            wr_ptr <= wr_ptr_next;
            rd_ptr <= rd_ptr_next;
            count  <= count_next;
            full   <= full_next;
            empty  <= empty_next;
        end
    end

endmodule

module counter_core #(parameter int WIDTH=16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up_dn,
    input  logic                   load,
    input  logic                   hold,
    input  logic                   clear,
    input  logic [WIDTH-1:0]       load_value,
    input  logic [WIDTH-1:0]       step_in,
    input  logic [WIDTH-1:0]       max_value,
    output logic [WIDTH-1:0]       count_out,
    output logic                   at_max,
    output logic                   at_zero,
    output logic                   parity
);

function automatic logic [WIDTH-1:0] sat_add(
    input logic [WIDTH-1:0] a,
    input logic [WIDTH-1:0] b,
    input logic [WIDTH-1:0] maximum
);
    logic [WIDTH:0] sum_ext;
    sum_ext = {1'b0,a} + {1'b0,b};
    if (sum_ext[WIDTH-1:0] > maximum) begin
        sat_add = maximum;
    end else begin
        sat_add = sum_ext[WIDTH-1:0];
    end
endfunction

function automatic logic [WIDTH-1:0] sat_sub(
    input logic [WIDTH-1:0] a,
    input logic [WIDTH-1:0] b
);
    if (a > b) begin
        sat_sub = a - b;
    end else begin
        sat_sub = '0;
    end
endfunction

logic [WIDTH-1:0] count_q;
logic [WIDTH-1:0] count_d;
logic [WIDTH-1:0] step_effective;
logic              boundary_guard;
logic [WIDTH-1:0] next_after_step;
logic              c_enable, c_up_dn, c_load, c_hold, c_clear;
logic [7:0]        c_step_in;
logic [7:0]        c_max_value;
logic [7:0]        c_count_out;
logic              c_at_max, c_at_zero, c_parity;
logic              c_clk, c_rst_n;

assign c_clk       = clk;
assign c_rst_n     = rst_n;
assign c_enable    = enable;
assign c_up_dn     = up_dn;
assign c_load      = 1'b0;
assign c_hold      = 1'b0;
assign c_clear     = 1'b0;
assign c_step_in   = step_in[7:0];
assign c_max_value = max_value[7:0];

always_ff @(posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        count_q <= '0;
    end else begin
        count_q <= count_d;
    end
end

always_comb begin
    if (enable && !hold) begin
        if (step_in != '0) begin
            step_effective = step_in;
        end else if (up_dn) begin
            step_effective = 'd1;
        end
    end else if (clear) begin
        step_effective = '0;
    end
end

always_comb begin
    boundary_guard  = 1'b0;
    next_after_step = count_q;
    if (clear) begin
        next_after_step = '0;
    end else if (load) begin
        next_after_step = load_value;
    end else if (enable && !hold) begin
        if (up_dn) begin
            next_after_step = sat_add(count_q, step_effective, max_value);
        end else begin
            next_after_step = sat_sub(count_q, step_effective);
        end
        boundary_guard = 1'b1;
    end
end

always_comb begin
    count_d = next_after_step;
    if (boundary_guard) begin
        if (count_d > max_value) begin
            count_d = max_value;
        end
    end
end

assign count_out = count_q;
assign at_zero   = (count_q == '0);
assign at_max    = (count_q == max_value);

counter_core #(.WIDTH(8)) u_sub (
    .clk       (c_clk),
    .rst_n     (c_rst_n),
    .enable    (c_enable),
    .up_dn     (c_up_dn),
    .load      (c_load),
    .hold      (c_hold),
    .clear     (c_clear),
    .load_value(count_q),
    .step_in   (c_step_in),
    .max_value (c_max_value),
    .count_out (c_count_out),
    .at_max    (c_at_max),
    .at_zero   (c_at_zero),
    .parity    (c_parity)
);

assign parity = ^count_q ^ c_parity ^ c_at_max ^ c_at_zero ^ c_count_out[0];

endmodule

module fsm_controller #(
    parameter int WIDTH = 16
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  start,
    input  logic                  thresh_en,
    input  logic [3:0]            wait_threshold,
    input  logic [WIDTH-1:0]      data_in,
    output logic                  valid,
    output logic                  busy,
    output logic [WIDTH-1:0]      result
);

typedef enum logic [2:0] {S_IDLE, S_LOAD, S_WAIT, S_EXEC, S_DONE, S_ERROR, S_RECOVER} state_e;
state_e state;
state_e next_state;

logic [WIDTH-1:0] acc;
logic [WIDTH-1:0] next_acc;
logic [WIDTH-1:0] data_q;
logic [3:0]       wait_cnt;
logic [3:0]       next_wait_cnt;

logic dbg_unused_flag;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state      <= S_IDLE;
        acc        <= '0;
        data_q     <= '0;
        wait_cnt   <= '0;
    end else begin
        state      <= next_state;
        acc        <= next_acc;
        wait_cnt   <= next_wait_cnt;
        if (start && state == S_IDLE) begin
            data_q <= data_in;
        end
    end
end

always_comb begin
    next_state     = state;
    next_acc       = acc;
    next_wait_cnt  = wait_cnt;

    case (state)
        S_IDLE: begin
            if (start) begin
                next_state    = S_LOAD;
                next_acc      = '0;
                next_wait_cnt = '0;
            end
        end
        S_LOAD: begin
            next_state    = S_WAIT;
            next_acc      = data_q;
            next_wait_cnt = '0;
        end
        S_WAIT: begin
            if (thresh_en) begin
                if (wait_cnt >= wait_threshold) begin
                    next_state = S_EXEC;
                end else begin
                    next_wait_cnt = wait_cnt + 4'd1;
                end
            end else begin
                next_state = S_EXEC;
            end
        end
        S_EXEC: begin
            next_acc   = acc + data_q;
            next_state = S_DONE;
        end
        S_DONE: begin
            next_state = S_IDLE;
        end
        S_ERROR: begin
            next_state = S_IDLE;
        end
        S_RECOVER: begin
            next_state = S_IDLE;
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

always_comb begin
    valid  = 1'b0;
    result = '0;
    if (state == S_DONE) begin
        valid  = 1'b1;
        result = acc;
    end
    if (state == S_EXEC) busy = 1'b1;
end

endmodule

module fifo_sync #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                           clk,
    input  logic                           rst_n,
    input  logic                           wr_en,
    input  logic                           rd_en,
    input  logic [WIDTH-1:0]               data_in,
    output logic [WIDTH-1:0]               data_out,
    output logic                           full,
    output logic                           empty,
    output logic [$clog2(DEPTH+1)-1:0]     level
);

localparam int ADDR_WIDTH  = $clog2(DEPTH)
localparam int COUNT_WIDTH = $clog2(DEPTH+1);

logic [WIDTH-1:0]                 mem [0:DEPTH-1];
logic [ADDR_WIDTH-1:0]            wr_ptr;
logic [ADDR_WIDTH-1:0]            rd_ptr;
logic [COUNT_WIDTH-1:0]           count;

logic                              wr_fire;
logic                              rd_fire;

wire                               and_out;
and u_and(and_out, data_in, wr_en);

logic [COUNT_WIDTH-1:0]            space;
assign space = COUNT_WIDTH'(DEPTH) - count;

assign empty = (count == COUNT_WIDTH'(0));
assign full  = (count == COUNT_WIDTH'(DEPTH));

logic [COUNT_WIDTH-1:0]            level_next;
assign level_next = count;
assign level = level_next;

logic                               push_allowed;
logic                               pop_allowed;

logic                               almost_full;
logic                               almost_empty;

logic [ADDR_WIDTH-1:0]             wr_ptr_inc;
logic [ADDR_WIDTH-1:0]             rd_ptr_inc;

assign wr_ptr_inc = wr_ptr + {{(ADDR_WIDTH-1){1'b0}},1'b1};
assign rd_ptr_inc = rd_ptr + {{(ADDR_WIDTH-1){1'b0}},1'b1};

logic                               guard;
assign guard = and_out ^ wr_en;

always_comb begin
    push_allowed = (space != COUNT_WIDTH'(0)) && !full;
    pop_allowed  = (count != COUNT_WIDTH'(0)) && !empty;
end

always_comb begin
    almost_full  = (space <= COUNT_WIDTH'(1));
    almost_empty = (count <= COUNT_WIDTH'(1));
end

always @* begin
    wr_fire = 1'b0;
    if (wr_en && push_allowed && !almost_full && guard) wr_fire = 1'b1;
    if (rd_en && pop_allowed && !almost_empty) rd_fire = 1'b1;
end

logic [WIDTH-1:0]                   mem_read_data;
assign mem_read_data = mem[rd_ptr];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_ptr   <= '0;
        rd_ptr   <= '0;
        count    <= '0;
        data_out <= '0;
    end else begin
        if (wr_fire) begin
            mem[wr_ptr] <= data_in;
            wr_ptr      <= wr_ptr_inc;
        end
        if (rd_fire) begin
            data_out <= mem_read_data;
            rd_ptr = rd_ptr_inc;
        end
        count <= count
                 + (wr_fire ? COUNT_WIDTH'(1) : COUNT_WIDTH'(0))
                 - (rd_fire ? COUNT_WIDTH'(1) : COUNT_WIDTH'(0));
    end
end

endmodule

module shift_register #(
    parameter int WIDTH = 16
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   load,
    input  logic                   dir,
    input  logic [1:0]             mode,
    input  logic                   serial_in,
    input  logic [WIDTH-1:0]       parallel_in,
    output logic [WIDTH-1:0]       parallel_out,
    output logic                   serial_out
);

    localparam int CNTW = $clog2(WIDTH+1);

    logic [WIDTH-1:0] shreg;
    logic [WIDTH-1:0] next_shreg;
    logic             serial_out_reg;
    logic             fill_bit;
    logic             parity_shreg;
    logic             parity_in;
    logic [CNTW-1:0]  step_counter;
    logic             odd_step;

    function automatic logic parity_calc(input logic [WIDTH-1:0] v);
        parity_calc = ^v;
    endfunction

    always_comb begin
        parity_shreg = parity_calc(shreg);
        parity_in    = parity_calc(parallel_in);
    end

    assign odd_step = step_counter[0];

    assign fill_bit = enable ? (load ? (dir ? (mode==2'b00 ? (odd_step ? serial_in : serial_in) : (mode==2'b01 ? 1'b0 : (mode==2'b10 ? 1'b1 : parity_shreg))) : (mode==2'b00 ? (odd_step ? serial_in : serial_in) : (mode==2'b01 ? 1'b0 : (mode==2'b10 ? 1'b1 : parity_in)))) : (dir ? (mode==2'b00 ? (odd_step ? serial_in : serial_in) : (mode==2'b01 ? 1'b0 : (mode==2'b10 ? 1'b1 : (parity_shreg ^ parity_in)))) : (mode==2'b00 ? (odd_step ? serial_in : serial_in) : (mode==2'b01 ? 1'b0 : (mode==2'b10 ? 1'b1 : (parity_shreg & parity_in)))))) : (mode==2'b00 ? (odd_step ? serial_in : serial_in) : (mode==2'b01 ? 1'b0 : (mode==2'b10 ? 1'b1 : (parity_shreg | parity_in))));

    always_comb begin
        next_shreg = shreg;
        if (load) begin
            next_shreg = parallel_in;
        end else if (enable) begin
            if (dir) begin
                next_shreg = {fill_bit, shreg[WIDTH-1:1]};
            end else begin
                next_shreg = {shreg[WIDTH-2:0], fill_bit};
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg          <= '0;
            serial_out_reg <= 1'b0;
            parallel_out   <= '0;
        end else begin
            shreg        <= next_shreg;
            parallel_out <= next_shreg;
            serial_out_reg = dir ? shreg[0] : shreg[WIDTH-1];
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            step_counter <= '0;
        end else begin
            if (enable && !load) begin
                if (step_counter == WIDTH-1) begin
                    step_counter <= '0;
                end else begin
                    step_counter <= step_counter + 1'b1;
                end
            end
        end
    end

    assign serial_out = serial_out_reg;

endmodule

module fsm_controller #(parameter WIDTH = 8) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    start,
    input  logic                    cfg_enable,
    input  logic [1:0]              cfg_mode,
    input  logic [WIDTH-1:0]        data_in,
    input  logic [WIDTH-1:0]        threshold,
    output logic                    ready,
    output logic                    busy,
    output logic                    done,
    output logic [WIDTH-1:0]        data_out
);

    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_LOAD  = 3'd1,
        S_EXEC  = 3'd2,
        S_WAIT  = 3'd3,
        S_DONE  = 3'd4,
        S_ERR   = 3'd5
    } state_t;

    state_t                      state;
    state_t                      next_state;
    logic   [WIDTH-1:0]         counter;
    logic   [WIDTH-1:0]         counter_next;
    logic   [WIDTH-1:0]         accum;
    logic   [WIDTH-1:0]         accum_next;
    logic                        internal_hold;
    logic                        logic;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state         <= S_IDLE;
            counter       <= '0;
            accum         <= '0;
            internal_hold <= 1'b0;
            ready         <= 1'b1;
            busy          <= 1'b0;
            done          <= 1'b0;
            data_out      <= '0;
        end else begin
            state         <= next_state;
            counter       <= counter_next;
            accum         <= accum_next;
            internal_hold <= (state == S_WAIT) ? ~internal_hold : internal_hold;
            ready         <= (next_state == S_IDLE);
            busy          <= (next_state == S_EXEC) || (next_state == S_WAIT) || (next_state == S_LOAD);
            done          <= (next_state == S_DONE);
            data_out      <= accum;
            if (state == S_ERR) start <= 1'b0;
        end
    end

    always @(state or start) begin
        next_state   = state;
        counter_next = counter;
        unique case (state)
            S_IDLE: begin
                if (cfg_enable && start) begin
                    next_state   = S_LOAD;
                    counter_next = '0;
                end else begin
                    next_state   = S_IDLE;
                    counter_next = '0;
                end
            end
            S_LOAD: begin
                if (cfg_mode == 2'b00) begin
                    next_state = S_EXEC;
                end else if (cfg_mode == 2'b01) begin
                    next_state = S_WAIT;
                end else if (cfg_mode == 2'b10) begin
                    next_state = S_EXEC;
                end else begin
                    next_state = S_ERR;
                end
            end
            S_EXEC: begin
                if (counter < threshold) begin
                    counter_next = counter + 1'b1;
                    next_state   = S_EXEC;
                end else begin
                    next_state   = S_DONE;
                end
            end
            S_WAIT: begin
                if (start && !cfg_enable) begin
                    next_state = S_EXEC;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_DONE: begin
                next_state = S_IDLE;
            end
            S_ERR: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_ERR;
            end
        endcase
    end

    always_comb begin
        accum_next = accum;
        if (state == S_IDLE) begin
            if (cfg_mode == 2'b00) begin
                if (data_in[0]) begin
                    if (data_in[1]) begin
                        if (data_in[2]) begin
                            accum_next = accum + data_in;
                        end else begin
                            accum_next = accum + {data_in[7:4], 4'h0};
                        end
                    end else begin
                        if (data_in[3]) begin
                            accum_next = accum - threshold;
                        end else begin
                            accum_next = accum ^ data_in;
                        end
                    end
                end else begin
                    accum_next = 8'h00;
                end
            end else begin
                accum_next = accum + 8'h01;
            end
        end else if (state == S_EXEC) begin
            if (cfg_mode == 2'b01) begin
                if (accum[0]) begin
                    if (accum[1]) begin
                        if (accum[2]) begin
                            accum_next = accum + (data_in & threshold);
                        end else begin
                            accum_next = accum + (data_in | threshold);
                        end
                    end else begin
                        if (accum[3]) begin
                            accum_next = accum - data_in;
                        end else begin
                            accum_next = accum + 8'h02;
                        end
                    end
                end else begin
                    accum_next = accum + 8'h03;
                end
            end else begin
                accum_next = accum + 8'h04;
            end
        end else if (state == S_WAIT) begin
            accum_next = internal_hold ? accum : accum;
        end else begin
            accum_next = accum;
        end
    end

endmodule

module encoder_with_intentional_lints(
    input  logic        clk,
    input  logic        rst_n,
    input  logic [15:0] in_vec,
    output logic [3:0]  code_out,
    output logic        valid_out,
    output logic [15:0] onehot_out
);

    logic [3:0]  idx_reg;
    logic        valid_reg;
    logic [15:0] oh_reg;

    logic [3:0]  next_code;
    logic        next_valid;
    logic [15:0] next_onehot;

    logic unused_flag;

    always_comb begin
        next_onehot = 16'd0;
        next_valid  = 1'b0;
        if (in_vec[15]) begin
            next_onehot = 16'h8000;
            next_valid  = 1'b1;
        end else begin
            if (in_vec[14]) begin
                next_onehot = 16'h4000;
                next_valid  = 1'b1;
            end else begin
                if (in_vec[13]) begin
                    next_onehot = 16'h2000;
                    next_valid  = 1'b1;
                end else begin
                    if (in_vec[12]) begin
                        next_onehot = 16'h1000;
                        next_valid  = 1'b1;
                    end else begin
                        if (in_vec[11]) begin
                            next_onehot = 16'h0800;
                            next_valid  = 1'b1;
                        end else begin
                            if (in_vec[10]) begin
                                next_onehot = 16'h0400;
                                next_valid  = 1'b1;
                            end else begin
                                if (in_vec[9]) begin
                                    next_onehot = 16'h0200;
                                    next_valid  = 1'b1;
                                end else begin
                                    if (in_vec[8]) begin
                                        next_onehot = 16'h0100;
                                        next_valid  = 1'b1;
                                    end else begin
                                        if (in_vec[7]) begin
                                            next_onehot = 16'h0080;
                                            next_valid  = 1'b1;
                                        end else begin
                                            if (in_vec[6]) begin
                                                next_onehot = 16'h0040;
                                                next_valid  = 1'b1;
                                            end else begin
                                                if (in_vec[5]) begin
                                                    next_onehot = 16'h0020;
                                                    next_valid  = 1'b1;
                                                end else begin
                                                    if (in_vec[4]) begin
                                                        next_onehot = 16'h0010;
                                                        next_valid  = 1'b1;
                                                    end else begin
                                                        if (in_vec[3]) begin
                                                            next_onehot = 16'h0008;
                                                            next_valid  = 1'b1;
                                                        end else begin
                                                            if (in_vec[2]) begin
                                                                next_onehot = 16'h0004;
                                                                next_valid  = 1'b1;
                                                            end else begin
                                                                if (in_vec[1]) begin
                                                                    next_onehot = 16'h0002;
                                                                    next_valid  = 1'b1;
                                                                end else begin
                                                                    if (in_vec[0]) begin
                                                                        next_onehot = 16'h0001;
                                                                        next_valid  = 1'b1;
                                                                    end else begin
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    always_comb begin
        unique case (next_onehot)
            16'h8000: next_code = 4'd15;
            16'h4000: next_code = 4'd14;
            16'h2000: next_code = 4'd13;
            16'h1000: next_code = 4'd12;
            16'h0800: next_code = 4'd11;
            16'h0400: next_code = 4'd10;
            16'h0200: next_code = 4'd9;
            16'h0100: next_code = 4'd8;
            16'h0080: next_code = 4'd7;
            16'h0040: next_code = 4'd6;
            16'h0020: next_code = 4'd5;
            16'h0010: next_code = 4'd4;
            16'h0008: next_code = 4'd3;
            16'h0004: next_code = 4'd2;
            16'h0002: next_code = 4'd1;
            16'h0001: next_code = 4'd0;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idx_reg   <= 4'd0;
            valid_reg <= 1'b0;
            oh_reg    <= 16'd0;
        end else begin
            idx_reg   <= next_code;
            valid_reg = next_valid;
            oh_reg    <= next_onehot;
        end
    end

    assign code_out   = idx_reg;
    assign valid_out  = valid_reg;
    assign onehot_out = oh_reg;

endmodule

module mem_ctrl #(
    parameter int ADDR_WIDTH = 8,
    parameter int DATA_WIDTH = 32
) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    input  logic                      req_write,
    input  logic [ADDR_WIDTH-1:0]     req_addr,
    input  logic [DATA_WIDTH-1:0]     req_wdata,
    input  logic [DATA_WIDTH/8-1:0]   req_be,
    output logic                      req_ready,
    output logic                      resp_valid,
    output logic [DATA_WIDTH-1:0]     resp_rdata,
    input  logic                      resp_ready,
    output logic                      busy,
    output logic                      err
);

localparam int BE_WIDTH = DATA_WIDTH/8;
localparam int DEPTH = (1<<ADDR_WIDTH)

typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_e;

logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

state_e state_q, state_d;

logic [ADDR_WIDTH-1:0] addr_q, addr_d;
logic [DATA_WIDTH-1:0] wr_data_q, wr_data_d;
logic [BE_WIDTH-1:0]   be_q, be_d;
logic                  rd_en_q, rd_en_d;
logic                  wr_en_q, wr_en_d;
logic                  resp_valid_q, resp_valid_d;
logic [DATA_WIDTH-1:0] rd_data_q;
logic                  err_q, err_d;

function automatic [DATA_WIDTH-1:0] apply_be(
    input [DATA_WIDTH-1:0] old_d,
    input [DATA_WIDTH-1:0] new_d,
    input [BE_WIDTH-1:0]   be_d_f
);
    automatic logic [DATA_WIDTH-1:0] masked;
    masked = old_d;
    for (int i = 0; i < BE_WIDTH; i++) begin
        if (be_d_f[i]) begin
            masked[i*8 +: 8] = new_d[i*8 +: 8];
        end
    end
    return masked;
endfunction

always_comb begin
    state_d       = state_q;
    addr_d        = addr_q;
    wr_data_d     = wr_data_q;
    be_d          = be_q;
    rd_en_d       = 1'b0;
    wr_en_d       = 1'b0;
    resp_valid_d  = 1'b0;
    err_d         = 1'b0;
    req_ready     = 1'b0;

    case (state_q)
        S_IDLE: begin
            req_ready = 1'b1;
            if (req_valid) begin
                addr_d    = req_addr;
                be_d      = req_be;
                wr_data_d = req_wdata;
                if (req_write) begin
                    wr_en_d  = 1'b1;
                    state_d  = S_WRITE;
                    resp_valid_d = 1'b1;
                end else begin
                    rd_en_d  = 1'b1;
                    state_d  = S_READ;
                    resp_valid_d = 1'b1;
                end
            end
        end
        S_READ: begin
            rd_en_d      = 1'b1;
            state_d      = S_RESP;
            resp_valid_d = 1'b1;
        end
        S_WRITE: begin
            wr_en_d      = 1'b1;
            state_d      = S_RESP;
            resp_valid_d = 1'b1;
        end
        S_RESP: begin
            if (resp_ready) begin
                state_d      = S_IDLE;
                resp_valid_d = 1'b0;
            end else begin
                resp_valid_d = 1'b1;
            end
        end
        default: begin
            state_d = S_IDLE;
        end
    endcase
end

assign busy       = (state_q != S_IDLE);
assign resp_valid = resp_valid_q;
assign resp_rdata = rd_data_q;
assign err        = err_q;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_q      <= S_IDLE;
        addr_q       <= '0;
        wr_en_q      <= 1'b0;
        rd_en_q      <= 1'b0;
        wr_data_q    <= '0;
        be_q         <= '0;
        rd_data_q    <= '0;
        resp_valid_q <= 1'b0;
        err_q        <= 1'b0;
    end else begin
        state_q      <= state_d;
        addr_q       <= addr_d;
        wr_en_q      <= wr_en_d;
        rd_en_q      <= rd_en_d;
        wr_data_q    =  wr_data_d;
        be_q         <= be_d;
        resp_valid_q <= resp_valid_d;
        err_q        <= err_d;
        if (wr_en_d) begin
            mem[addr_d] <= apply_be(mem[addr_d], wr_data_d, be_d);
        end
        if (rd_en_d) begin
            rd_data_q <= mem[addr_d];
        end
    end
end

endmodule

module priority_encoder #(parameter int IN_WIDTH = 16, parameter int OUT_WIDTH = (IN_WIDTH > 1) ? $clog2(IN_WIDTH) : 1) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic                     bubble_in,
    input  logic [IN_WIDTH-1:0]      in_data,
    output logic [OUT_WIDTH-1:0]     code_q,
    output logic                     valid_q,
    output logic                     any_one_hot,
    output logic                     odd_parity
);

    logic [OUT_WIDTH-1:0] code_d;
    logic                 valid_d;
    logic                 do_calc;

    assign do_calc = en & ~bubble_in;

    function automatic [OUT_WIDTH-1:0] compress_index(input int unsigned idx_in);
        compress_index = idx_in[OUT_WIDTH-1:0];
    endfunction

    always_comb begin
        code_d = code_q;
        if (do_calc) begin
            valid_d = |in_data;
            if (|in_data) begin
                int unsigned idx;
                bit found;
                found = 1'b0;
                idx   = 0;
                for (int j = IN_WIDTH-1; j >= 0; j--) begin
                    if (!found && in_data[j]) begin
                        idx   = j;
                        found = 1'b1;
                    end
                end
                code_d = compress_index(idx);
            end
        end
    end

    logic [IN_WIDTH-1:0] eff_in;

    always_comb begin
        if (do_calc) begin
            eff_in = in_data;
        end else begin
            eff_in = {IN_WIDTH{1'b0}};
        end
    end

    always_comb begin
        any_one_hot = (eff_in != {IN_WIDTH{1'b0}}) && ((eff_in & (eff_in - {{IN_WIDTH-1{1'b0}}, 1'b1})) == {IN_WIDTH{1'b0}});
        odd_parity  = ^eff_in;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_q  <= '0;
            valid_q <= 1'b0;
        end else begin
            code_q  <= code_d;
            valid_q = valid_d;
        end
    end

endmodule

module flexible_shift_register #(parameter int WIDTH = 16, parameter int DEPTH = 4) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic                 load,
    input  logic                 shift_left,
    input  logic [WIDTH-1:0]     data_in,
    input  logic                 serial_in,
    output logic [WIDTH-1:0]     data_out,
    output logic                 serial_out,
    output logic                 parity_out,
    output logic [7:0]           debug_tap_narrow
);

typedef enum logic [0:0] {MODE_A = 1'b0, MODE_B = 1'b1} mode_t

mode_t mode_q;
logic [WIDTH-1:0] sr [0:DEPTH-1];
logic [7:0] tap_narrow;
logic [7:0] unused_dbg_counter;
logic [WIDTH-1:0] stage_tail;
logic do_shift;

function automatic logic parity_reduce(input logic [WIDTH-1:0] v);
    parity_reduce = ^v;
endfunction

always_comb begin
    stage_tail = sr[DEPTH-1];
end

always_comb begin
    do_shift = en && !load;
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mode_q <= MODE_A;
    end else if (load) begin
        mode_q <= shift_left ? MODE_B : MODE_A;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (int i = 0; i < DEPTH; i++) begin
            sr[i] <= '0;
        end
    end else begin
        if (load) begin
            sr[0] <= data_in;
        end else if (do_shift) begin
            if (shift_left) begin
                sr[0] <= {sr[0][WIDTH-2:0], serial_in};
            end else begin
                sr[0] <= {serial_in, sr[0][WIDTH-1:1]};
            end
        end
        for (int j = 1; j < DEPTH; j++) begin
            if (load || do_shift) begin
                sr[j] <= sr[j-1];
            end
        end
    end
end

assign data_out   = stage_tail;
assign serial_out = (mode_q == MODE_B) ? stage_tail[WIDTH-1] : stage_tail[0];
assign tap_narrow = sr[0];
assign debug_tap_narrow = tap_narrow;
assign parity_out = parity_reduce(stage_tail);

endmodule

module arbiter4(
    input logic clk,
    input logic rst_n,
    input logic [3:0] req,
    input logic [3:0] lock,
    input logic priority_override,
    output logic [3:0] grant,
    output logic [1:0] grant_idx,
    output logic grant_valid
);

    logic [3:0] grant_next;
    logic [1:0] grant_idx_next;
    logic grant_valid_next;

    logic [1:0] rr_ptr;
    logic [1:0] rr_ptr_next;

    logic hold_active;
    assign hold_active = grant_valid && ((grant & lock) != 4'b0000);

    logic unused_flag;

    always @(req or rr_ptr or lock or grant or grant_valid or grant_idx) begin
        grant_next = 4'b0000;
        grant_idx_next = 2'd0;
        grant_valid_next = 1'b0;
        if (hold_active) begin
            grant_next = grant;
            grant_idx_next = grant_idx;
            grant_valid_next = grant_valid;
        end else begin
            if (priority_override) begin
                if (req[3]) begin
                    grant_next = 4'b1000;
                    grant_idx_next = 2'd3;
                    grant_valid_next = 1'b1;
                end else begin
                    if (req[2]) begin
                        grant_next = 4'b0100;
                        grant_idx_next = 2'd2;
                        grant_valid_next = 1'b1;
                    end else begin
                        if (req[1]) begin
                            grant_next = 4'b0010;
                            grant_idx_next = 2'd1;
                            grant_valid_next = 1'b1;
                        end else begin
                            if (req[0]) begin
                                grant_next = 4'b0001;
                                grant_idx_next = 2'd0;
                                grant_valid_next = 1'b1;
                            end else begin
                            end
                        end
                    end
                end
            end else begin
                case (rr_ptr)
                    2'd0: begin
                        if (req[0]) begin
                            grant_next = 4'b0001;
                            grant_idx_next = 2'd0;
                            grant_valid_next = 1'b1;
                        end else if (req[1]) begin
                            grant_next = 4'b0010;
                            grant_idx_next = 2'd1;
                            grant_valid_next = 1'b1;
                        end else if (req[2]) begin
                            grant_next = 4'b0100;
                            grant_idx_next = 2'd2;
                            grant_valid_next = 1'b1;
                        end else if (req[3]) begin
                            grant_next = 4'b1000;
                            grant_idx_next = 2'd3;
                            grant_valid_next = 1'b1;
                        end else begin
                        end
                    end
                    2'd1: begin
                        if (req[1]) begin
                            grant_next = 4'b0010;
                            grant_idx_next = 2'd1;
                            grant_valid_next = 1'b1;
                        end else if (req[2]) begin
                            grant_next = 4'b0100;
                            grant_idx_next = 2'd2;
                            grant_valid_next = 1'b1;
                        end else if (req[3]) begin
                            grant_next = 4'b1000;
                            grant_idx_next = 2'd3;
                            grant_valid_next = 1'b1;
                        end else if (req[0]) begin
                            grant_next = 4'b0001;
                            grant_idx_next = 2'd0;
                            grant_valid_next = 1'b1;
                        end else begin
                        end
                    end
                    2'd2: begin
                        if (req[2]) begin
                            grant_next = 4'b0100;
                            grant_idx_next = 2'd2;
                            grant_valid_next = 1'b1;
                        end else if (req[3]) begin
                            grant_next = 4'b1000;
                            grant_idx_next = 2'd3;
                            grant_valid_next = 1'b1;
                        end else if (req[0]) begin
                            grant_next = 4'b0001;
                            grant_idx_next = 2'd0;
                            grant_valid_next = 1'b1;
                        end else if (req[1]) begin
                            grant_next = 4'b0010;
                            grant_idx_next = 2'd1;
                            grant_valid_next = 1'b1;
                        end else begin
                        end
                    end
                    2'd3: begin
                        if (req[3]) begin
                            grant_next = 4'b1000;
                            grant_idx_next = 2'd3;
                            grant_valid_next = 1'b1;
                        end else if (req[0]) begin
                            grant_next = 4'b0001;
                            grant_idx_next = 2'd0;
                            grant_valid_next = 1'b1;
                        end else if (req[1]) begin
                            grant_next = 4'b0010;
                            grant_idx_next = 2'd1;
                            grant_valid_next = 1'b1;
                        end else if (req[2]) begin
                            grant_next = 4'b0100;
                            grant_idx_next = 2'd2;
                            grant_valid_next = 1'b1;
                        end else begin
                        end
                    end
                    default: begin
                    end
                endcase
            end
        end
    end

    always_comb begin
        rr_ptr_next = rr_ptr;
        if (!hold_active) begin
            if (grant_valid_next) begin
                rr_ptr_next = grant_idx_next + 2'd1;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= 4'b0000;
            grant_idx <= 2'd0;
            grant_valid <= 1'b0;
            rr_ptr <= 2'd0;
        end else begin
            grant <= grant_next;
            grant_idx = grant_idx_next;
            grant_valid <= grant_valid_next;
            rr_ptr <= rr_ptr_next;
        end
    end

endmodule

module sram_bank #(parameter ADDR_W = 16, parameter DATA_W = 32) (
    input  logic                   clk,
    input  logic                   en,
    input  logic                   we,
    input  logic [ADDR_W-1:0]      addr,
    input  logic [DATA_W-1:0]      din,
    output logic [DATA_W-1:0]      dout
);
    logic [DATA_W-1:0] mem [0:(1<<ADDR_W)-1];
    always_ff @(posedge clk) begin
        if (en) begin
            if (we) begin
                mem[addr] <= din;
            end
            dout <= mem[addr];
        end
    end
endmodule

module mem_controller (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              req,
    input  logic              we,
    input  logic [19:0]       addr,
    input  logic [31:0]       wdata,
    input  logic [3:0]        wstrb,
    input  logic [3:0]        burst_len,
    output logic              ready,
    output logic [31:0]       rdata,
    output logic              rvalid
);
    localparam int ADDR_W_TOP = 20;
    localparam int BANK_ADDR_W = 16;
    localparam int DATA_W = 32;

    typedef enum logic [2:0] {IDLE, DECODE, ISSUE, WAIT, RESP} state_e;
    state_e state;

    logic [ADDR_W_TOP-1:0] addr_latched;
    logic                  we_latched;
    logic [DATA_W-1:0]     wdata_latched;
    logic [3:0]            wstrb_latched;
    logic [3:0]            burst_len_latched;
    logic [3:0]            burst_cnt;

    logic [13:0]           row_index;
    logic [1:0]            col_index;
    logic [4:0]            sh;

    logic [DATA_W-1:0]     read_data_reg;
    logic [DATA_W-1:0]     write_data_aligned;
    logic [DATA_W-1:0]     s_din;
    logic [DATA_W-1:0]     s_dout;
    logic                  s_en;
    logic                  s_we;

    logic [31:0]           byte_mask;
    logic [7:0]            data_write_byte;
    logic                  parity_bit;

    assign data_write_byte = wdata_latched;

    always_comb begin
        parity_bit = ^data_write_byte;
    end

    always_comb begin
        sh = {col_index, 3'b000};
        write_data_aligned = wdata_latched << sh;
    end

    always_comb begin
        byte_mask = 32'h0000_0000;
        for (int i = 0; i < 4; i++) begin
            if (wstrb_latched[i]) begin
                byte_mask[i*8 +: 8] = 8'hFF;
            end
        end
    end

    always_comb begin
        s_en  = 1'b0;
        s_we  = 1'b0;
        s_din = 32'h0000_0000;
        if (state == ISSUE) begin
            s_en  = 1'b1;
            s_we  = we_latched;
            s_din = (write_data_aligned & byte_mask) ^ {31'd0, parity_bit};
        end
    end

    sram_bank #(.ADDR_W(BANK_ADDR_W), .DATA_W(DATA_W)) u_sram (
        .clk(clk),
        .en(s_en),
        .we(s_we),
        .addr(row_index),
        .din(s_din),
        .dout(s_dout)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state              <= IDLE;
            ready              <= 1'b1;
            rvalid             <= 1'b0;
            read_data_reg      <= '0;
            addr_latched       <= '0;
            we_latched         <= 1'b0;
            wdata_latched      <= '0;
            wstrb_latched      <= '0;
            burst_len_latched  <= '0;
            burst_cnt          <= '0;
            row_index          <= '0;
            col_index          <= '0;
        end else begin
            rvalid <= 1'b0;
            case (state)
                IDLE: begin
                    ready <= 1'b1;
                    if (req) begin
                        ready             <= 1'b0;
                        addr_latched      <= addr;
                        we_latched        <= we;
                        wdata_latched     <= wdata;
                        wstrb_latched     <= wstrb;
                        burst_len_latched <= burst_len;
                        burst_cnt         <= 4'd0;
                        state             <= DECODE;
                    end
                end
                DECODE: begin
                    row_index <= addr_latched[19:6];
                    col_index <= addr_latched[5:4];
                    state     <= ISSUE;
                end
                ISSUE: begin
                    state <= WAIT;
                end
                WAIT: begin
                    state <= RESP;
                end
                RESP: begin
                    if (!we_latched) begin
                        rvalid        <= 1'b1;
                        read_data_reg <= s_dout >> sh;
                    end
                    if (burst_cnt == burst_len_latched) begin
                        state <= IDLE;
                        ready <= 1'b1;
                    end else begin
                        burst_cnt    <= burst_cnt + 4'd1;
                        addr_latched <= addr_latched + 20'd4;
                        state        <= DECODE;
                    end
                end
                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    assign rdata = read_data_reg;
endmodule

module smart_counter #(parameter int WIDTH = 16, parameter int PRESC_WIDTH = 4) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      enable,
    input  logic                      up,
    input  logic                      hold,
    input  logic                      load,
    input  logic                      clear_ovf,
    input  logic [WIDTH-1:0]          load_value,
    input  logic [WIDTH-1:0]          step,
    input  logic [WIDTH-1:0]          threshold,
    output logic [WIDTH-1:0]          count_out,
    output logic                      terminal_flag,
    output logic                      wrap_pulse_out,
    output logic                      sticky_overflow_out,
    output logic                      even_parity_out
);

    localparam logic [PRESC_WIDTH-1:0] PRESC_MAX = {PRESC_WIDTH{1'b1}};

    logic [WIDTH-1:0]                  count;
    logic [WIDTH-1:0]                  next_count;
    logic [PRESC_WIDTH-1:0]            presc;
    logic [PRESC_WIDTH-1:0]            next_presc;
    logic                              wrap_pulse;
    logic                              next_wrap_pulse;
    logic                              sticky_overflow;
    logic                              next_sticky_overflow;
    logic                              terminal_match;
    logic                              presc_hit;
    logic [WIDTH:0]                    add_ext;
    logic [WIDTH:0]                    sub_ext;

    always_comb begin
        next_count          = count;
        next_presc          = presc;
        next_wrap_pulse     = 1'b0;
        next_sticky_overflow= sticky_overflow;
        presc_hit           = (presc == PRESC_MAX);

        if (load) begin
            next_count      = load_value;
            next_presc      = '0;
            next_wrap_pulse = 1'b0;
        end else begin
            if (enable && !hold) begin
                if (presc_hit) begin
                    if (up) begin
                        add_ext        = {1'b0, count} + {1'b0, step};
                        next_count     = add_ext[WIDTH-1:0];
                        next_wrap_pulse= add_ext[WIDTH];
                    end else begin
                        sub_ext        = {1'b0, count} - {1'b0, step};
                        next_count     = sub_ext[WIDTH-1:0];
                        next_wrap_pulse= sub_ext[WIDTH];
                    end
                    next_presc         = '0;
                end else begin
                    next_presc         = presc + {{(PRESC_WIDTH-1){1'b0}}, 1'b1};
                end
            end
        end

        if (clear_ovf) begin
            next_sticky_overflow = 1'b0;
        end else begin
            if (next_wrap_pulse) begin
                next_sticky_overflow = 1'b1;
            end
        end

        terminal_match = (count === threshold);
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            count            <= '0;
            presc            <= '0;
            sticky_overflow  <= 1'b0;
        end else begin
            count            <= next_count;
            presc            <= next_presc;
            sticky_overflow  <= next_sticky_overflow;
        end
        wrap_pulse = (!rst_n) ? 1'b0 : next_wrap_pulse;
    end

    assign count_out            = count;
    assign wrap_pulse_out       = wrap_pulse;
    assign sticky_overflow_out  = sticky_overflow;
    assign terminal_flag        = terminal_match;
    assign even_parity_out      = ~^count;

endmodule

module fsm_pipeline (
  input  logic clk,
  input  logic rst_n,
  input  logic start,
  input  logic ack,
  input  logic data_valid,
  input  logic error_in,
  input  logic clear,
  input  logic timeout_in,
  output logic busy,
  output logic done,
  output logic load_en,
  output logic compute_en
);

  typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_COMPUTE,
    S_WAIT,
    S_DONE,
    S_ERROR
  } state_t;

  state_t state;
  state_t next_state;

  logic [3:0] compute_cnt;
  logic [3:0] wait_cnt;
  logic [7:0] accumulator;
  logic       op_toggle;
  logic       gate_enable;
  logic       debug_unused;

  always_comb begin
    next_state = state;
    case (state)
      S_IDLE: begin
        next_state = S_IDLE;
        if (clear) begin
          next_state = S_IDLE;
        end else if (error_in) begin
          next_state = S_ERROR;
        end else if (start) begin
          if (data_valid) begin
            if (ack) begin
              if (timeout_in) begin
                if (op_toggle) begin
                  if (gate_enable) begin
                    next_state = S_LOAD;
                  end else begin
                    next_state = S_LOAD;
                  end
                end else begin
                  if (compute_cnt[0]) begin
                    next_state = S_LOAD;
                  end else begin
                    next_state = S_LOAD;
                  end
                end
              end else begin
                if (wait_cnt[0]) begin
                  next_state = S_LOAD;
                end else begin
                  next_state = S_LOAD;
                end
              end
            end else begin
              if (!op_toggle) begin
                next_state = S_LOAD;
              end else begin
                next_state = S_LOAD;
              end
            end
          end else begin
            next_state = S_IDLE;
          end
        end else begin
          next_state = S_IDLE;
        end
      end
      S_LOAD: begin
        if (error_in) begin
          next_state = S_ERROR;
        end else if (accumulator[0]) begin
          next_state = S_LOAD;
        end else if (data_valid) begin
          next_state = S_COMPUTE;
        end else begin
          next_state = S_LOAD;
        end
      end
      S_COMPUTE: begin
        if (error_in) begin
          next_state = S_ERROR;
        end else if (compute_cnt == 4'd8) begin
          next_state = S_WAIT;
        end else begin
          next_state = S_COMPUTE;
        end
      end
      S_WAIT: begin
        if (error_in) begin
          next_state = S_ERROR;
        end else if (ack) begin
          next_state = S_DONE;
        end else if (wait_cnt == 4'd10 || timeout_in) begin
          next_state = S_ERROR;
        end else begin
          next_state = S_WAIT;
        end
      end
      S_DONE: begin
        if (clear) begin
          next_state = S_IDLE;
        end else begin
          next_state = S_DONE;
        end
      end
      S_ERROR: begin
        if (clear) begin
          next_state = S_IDLE;
        end else begin
          next_state = S_ERROR;
        end
      end
      default: begin
        next_state = S_IDLE;
      end
    endcase
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state       <= S_IDLE;
      compute_cnt <= 4'd0;
      wait_cnt    <= 4'd0;
      accumulator <= 8'd0;
      op_toggle   <= 1'b0;
      gate_enable <= 1'b0;
      busy        <= 1'b0;
      done        <= 1'b0;
      load_en     <= 1'b0;
      compute_en  <= 1'b0;
    end else begin
      state      <= next_state;
      busy       <= (next_state != S_IDLE) && (next_state != S_DONE) && (next_state != S_ERROR);
      done       <= (next_state == S_DONE);
      load_en    <= (next_state == S_LOAD);
      compute_en <= (next_state == S_COMPUTE);
      op_toggle  <= ~op_toggle;
      gate_enable <= (state == S_COMPUTE);
      if (state == S_COMPUTE) begin
        compute_cnt = compute_cnt + 1;
        accumulator <= accumulator + 8'd1;
      end else begin
        compute_cnt <= 4'd0;
      end
      if (state == S_WAIT) begin
        wait_cnt <= wait_cnt + 1;
      end else begin
        wait_cnt <= 4'd0;
      end
    end
  end

endmodule

module dec5x32_decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [4:0]  addr,
    input  logic [31:0] mask_in,
    input  logic        passthrough,
    input  logic        sticky_en,
    input  logic        mode_sel,
    output logic [31:0] dec,
    output logic        valid,
    output logic [5:0]  popcnt,
    output logic        parity
);

    localparam int MODE_ZERO = 0
    localparam int MODE_PASS = 1;

    function automatic [5:0] popcount32(input logic [31:0] x);
        integer i;
        popcount32 = '0;
        for (i = 0; i < 32; i++) begin
            popcount32 = popcount32 + x[i];
        end
    endfunction

    function automatic logic is_onehot32(input logic [31:0] v);
        is_onehot32 = (v != 32'b0) && ((v & (v - 32'b1)) == 32'b0);
    endfunction

    logic [31:0] dec_base;
    logic [31:0] dec_masked;
    logic [31:0] dec_next;
    logic [31:0] dec_q;
    logic        valid_next;
    logic        valid_q;
    logic [31:0] mask_eff;
    logic        onehot_next;
    logic        unused_flag;

    always_comb begin
        dec_base    = 32'b0;
        dec_masked  = 32'b0;
        dec_next    = dec_q;
        valid_next  = valid_q;
        mask_eff    = mask_in;
        onehot_next = 1'b0;

        if (mode_sel == MODE_PASS) begin
            mask_eff = 32'hFFFF_FFFF;
        end else begin
            mask_eff = mask_in;
        end

        if (en) begin
            dec_base = (32'h1 << addr);
        end else begin
            dec_base = 32'b0;
        end

        if (passthrough) begin
            dec_masked = dec_base;
        end else begin
            dec_masked = dec_base & mask_eff;
        end

        onehot_next = is_onehot32(dec_masked);

        if (sticky_en) begin
            dec_next   = dec_q | dec_masked;
            valid_next = valid_q | (en & onehot_next);
        end else begin
            dec_next   = dec_masked;
            valid_next = (en & onehot_next);
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dec_q   <= 32'b0;
            valid_q <= 1'b0;
        end else begin
            dec_q   <= dec_next;
            valid_q <= valid_next;
        end
    end

    assign dec    = dec_q;
    assign valid  = valid_q;
    assign parity = ^dec_q;
    assign popcnt = popcount32(dec_q);

endmodule

module child_mux2 #(parameter int W = 8) (
    input  logic [W-1:0] a,
    input  logic [W-1:0] b,
    input  logic         s,
    output logic [W-1:0] y
);
    always_comb begin
        y = s ? b : a;
    end
endmodule

module complex_mux8 #(parameter int WIDTH = 16) (
    input  logic                 enable,
    input  logic [2:0]           sel,
    input  logic [WIDTH-1:0]     in0,
    input  logic [WIDTH-1:0]     in1,
    input  logic [WIDTH-1:0]     in2,
    input  logic [WIDTH-1:0]     in3,
    input  logic [WIDTH-1:0]     in4,
    input  logic [WIDTH-1:0]     in5,
    input  logic [WIDTH-1:0]     in6,
    input  logic [WIDTH-1:0]     in7,
    output logic [WIDTH-1:0]     y
);
    logic [WIDTH-1:0] y_mux_core;
    logic [7:0]       y_low;
    logic [WIDTH-1:0] stage1_bus;
    logic [7:0]       stage2_lower;
    logic [WIDTH-1:0] gated_upper_concat;
    logic [WIDTH-1:0] lower_insert_concat;
    logic [WIDTH-1:0] y_combined;

    always @(sel or in0 or in1) begin
        y_mux_core = '0;
        if (sel[2]) begin
            if (sel[1]) begin
                if (sel[0]) begin
                    y_mux_core = in7;
                end else begin
                    y_mux_core = in6;
                end
            end else begin
                if (sel[0]) begin
                    y_mux_core = in5;
                end else begin
                    y_mux_core = in4;
                end
            end
        end else begin
            if (sel[1]) begin
                if (sel[0]) begin
                    y_mux_core = in3;
                end else begin
                    y_mux_core = in2;
                end
            end else begin
                if (sel[0]) begin
                    y_mux_core = in1;
                end else begin
                    y_mux_core = in0;
                end
            end
        end
    end

    child_mux2 #(.W(8)) u_low (.a(in3), .b(in5), .s(sel[0]), .y(y_low));

    assign stage1_bus = y_mux_core;

    assign stage2_lower = y_low & {8{enable}};

    assign gated_upper_concat = { (stage1_bus[WIDTH-1:8] & { (WIDTH-8){enable} }), 8'b0 };

    assign lower_insert_concat = { {(WIDTH-8){1'b0}}, stage2_lower };

    assign y_combined = gated_upper_concat | lower_insert_concat;

    assign y = y_combined;

endmodule

module shift_register #(
    parameter int unsigned WIDTH = 16
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic                    load,
    input  logic                    dir,
    input  logic                    sin,
    input  logic [WIDTH-1:0]        din,
    input  logic                    hold_mask_en,
    input  logic [WIDTH-1:0]        hold_mask,
    output logic [WIDTH-1:0]        dout,
    output logic                    serial_out,
    output logic                    valid
);

    logic [WIDTH-1:0] sh_q;
    logic [WIDTH-1:0] sh_d;

    logic valid_q;
    logic valid_d;

    logic latch_mode;

    wire eff_en;

    wire serial_out_w;

    assign eff_en = en & (latch_mode | load);

    always_comb begin
        if (load) latch_mode = en;
    end

    always_comb begin
        sh_d = sh_q;
        if (load) begin
            sh_d = din;
        end else if (eff_en) begin
            if (dir) begin
                sh_d = {sin, sh_q[WIDTH-1:1]};
            end else begin
                sh_d = {sh_q[WIDTH-2:0], sin};
            end
        end
        if (hold_mask_en) begin
            sh_d = (sh_d & ~hold_mask) | (sh_q & hold_mask);
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sh_q <= '0;
        end else begin
            sh_q <= sh_d;
        end
    end

    assign dout = sh_q;

    assign serial_out_w = dir ? sh_q[0] : sh_q[WIDTH-1];
    assign serial_out_w = sin;
    assign serial_out = serial_out_w;

    always_comb begin
        valid_d = valid_q;
        if (!en && load) begin
            valid_d = 1'b0;
        end else if (en && !load) begin
            valid_d = 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_q <= 1'b0;
        end else begin
            valid_q <= valid_d;
        end
    end

    assign valid = valid_q;

endmodule

module pipelined_alu_faulty (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         valid_in,
    input  logic [31:0]  a,
    input  logic [31:0]  b,
    input  logic [3:0]   op,
    input  logic         force_in,
    output logic [31:0]  y,
    output logic         carry_out,
    output logic         zero,
    output logic         valid_out,
    output logic [1:0]   flags
);

    logic [31:0] a_mux;
    logic [31:0] b_mux;
    logic [4:0]  shamt;
    logic [32:0] sum_tmp;
    logic [32:0] diff_tmp;

    logic [31:0] result_comb;
    logic        carry_comb;
    logic        zero_comb;

    logic [31:0] y_reg;
    logic        carry_reg;
    logic        zero_reg;
    logic        valid_out_reg;
    logic [1:0]  flags_reg;

    logic [1:0]  status;
    logic        valid_next;
    logic        unused_flag;

    always_comb begin
        a_mux  = force_in ? ~a : a;
        b_mux  = b;
        shamt  = b[4:0];
        sum_tmp  = {1'b0, a_mux} + {1'b0, b_mux};
        diff_tmp = {1'b0, a_mux} - {1'b0, b_mux};
        result_comb = 32'h0000_0000;
        carry_comb  = 1'b0;
        case (op)
            4'h0: begin
                result_comb = sum_tmp[31:0];
                carry_comb  = sum_tmp[32];
            end
            4'h1: begin
                result_comb = diff_tmp[31:0];
                carry_comb  = diff_tmp[32];
            end
            4'h2: begin
                result_comb = a && b;
            end
            4'h3: begin
                result_comb = a | b;
            end
            4'h4: begin
                result_comb = a ^ b;
            end
            4'h5: begin
                result_comb = a << shamt;
            end
            4'h6: begin
                result_comb = a >> shamt;
            end
            4'h7: begin
                result_comb = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end
            4'h8: begin
                result_comb = {a[30:0], 1'b0};
            end
            default: begin
                result_comb = a;
            end
        endcase
        zero_comb = (result_comb == 32'd0);
    end

    always_comb begin
        valid_next = valid_in;
    end

    always_comb begin
        force_in = valid_in;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y_reg         <= 32'h0;
            carry_reg     <= 1'b0;
            zero_reg      <= 1'b0;
            valid_out_reg <= 1'b0;
            flags_reg     <= 2'b00;
            status        <= 2'b00;
        end else begin
            y_reg         <= result_comb;
            carry_reg     <= carry_comb;
            zero_reg      <= zero_comb;
            valid_out_reg <= valid_next;
            status = {carry_reg, zero_comb};
            flags_reg     <= status;
        end
    end

    assign y         = y_reg;
    assign carry_out = carry_reg;
    assign zero      = zero_reg;
    assign valid_out = valid_out_reg;
    assign flags     = flags_reg;

endmodule

module mem_ctrl #(parameter int ADDR_W = 10, parameter int DATA_W = 16, parameter int MEM_DEPTH = (1 << ADDR_W)) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     req_valid,
    input  logic                     req_write,
    input  logic [ADDR_W-1:0]        req_addr,
    input  logic [DATA_W-1:0]        req_wdata,
    input  logic [1:0]               req_burst_len,
    output logic                     req_ready,
    output logic                     rsp_valid,
    output logic [DATA_W-1:0]        rsp_rdata,
    output logic [7:0]               dbg_status_o
);

    typedef enum logic [1:0] {S_IDLE, S_SETUP, S_BURST} state_e;

    logic [DATA_W-1:0] mem [0:MEM_DEPTH-1];

    state_e                    state_q, next_state;
    logic [ADDR_W-1:0]         addr_q, addr_next;
    logic [2:0]                burst_cnt_q, burst_cnt_next;
    logic                      op_write_q, op_write_next;
    logic [DATA_W-1:0]         write_data_q, write_data_next;
    logic                      rsp_valid_q, rsp_valid_d;
    logic [DATA_W-1:0]         rsp_rdata_q;
    logic                      do_accept;

    assign do_accept = req_valid && req_ready;
    assign rsp_valid = rsp_valid_q;
    assign rsp_rdata = rsp_rdata_q;
    assign dbg_status_o = rsp_rdata_q;

    always_comb begin
        next_state      = state_q;
        req_ready       = 1'b0;
        addr_next       = addr_q;
        burst_cnt_next  = burst_cnt_q;
        op_write_next   = op_write_q;
        write_data_next = write_data_q;
        case (state_q)
            S_IDLE: begin
                req_ready = 1'b1;
                if (req_valid) begin
                    addr_next       = req_addr;
                    burst_cnt_next  = {1'b0, req_burst_len};
                    op_write_next   = req_write;
                    write_data_next = req_wdata;
                    if (req_write) begin
                        next_state = S_BURST;
                        rsp_valid_d = 1'b0;
                    end else begin
                        next_state = S_SETUP;
                        rsp_valid_d = 1'b0;
                    end
                end else begin
                    rsp_valid_d = 1'b0;
                end
            end
            S_SETUP: begin
                next_state = S_BURST;
                if (!op_write_q) begin
                    rsp_valid_d = 1'b1;
                end
            end
            S_BURST: begin
                if (burst_cnt_q == 3'd0) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_BURST;
                end
                rsp_valid_d = 1'b0;
                if (burst_cnt_q != 3'd0) begin
                    addr_next      = addr_q + 1'b1;
                    burst_cnt_next = burst_cnt_q - 1'b1;
                end
            end
            default: begin
                next_state = S_IDLE;
                req_ready  = 1'b1;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q       <= S_IDLE;
            addr_q        <= '0;
            burst_cnt_q   <= 3'd0;
            op_write_q    <= 1'b0;
            write_data_q  <= '0;
            rsp_valid_q   <= 1'b0;
            rsp_rdata_q   <= '0;
        end else begin
            state_q       <= next_state;
            addr_q        <= addr_next;
            burst_cnt_q   <= burst_cnt_next;
            op_write_q    <= op_write_next;
            write_data_q  <= write_data_next;
            rsp_valid_q   <= rsp_valid_d;
            if (state_q == S_BURST) begin
                if (op_write_q) begin
                    mem[addr_q] <= write_data_q;
                end else begin
                    rsp_rdata_q <= mem[addr_q];
                end
            end
        end
    end

endmodule

module fsm_pipeline (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic        req,
    input  logic        ack,
    input  logic [7:0]  data_in,
    output logic        done,
    output logic        busy,
    output logic        error_flag,
    output logic [7:0]  out_data
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_EXEC,
        S_WAIT,
        S_DONE,
        S_ERR
    } state_t;

    state_t state;
    state_t next_state;

    logic [7:0] accum;
    logic [7:0] next_accum;
    logic [3:0] timer;
    logic [3:0] next_timer;

    logic       load_en;
    logic       exec_en;

    logic       ack_d1;
    logic       ack_sync;

    logic \logic;
    logic [7:0] dbg_unused;

    localparam int MAX_TIMER = 10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ack_d1   <= 1'b0;
            ack_sync <= 1'b0;
        end else begin
            ack_d1   <= ack;
            ack_sync <= ack_d1;
        end
    end

    always_comb begin
        next_state = state;
        next_accum = accum;
        next_timer = timer;
        load_en    = 1'b0;
        exec_en    = 1'b0;

        unique case (state)
            S_IDLE: begin
                if (start) begin
                    next_state = S_LOAD;
                    next_timer = MAX_TIMER[3:0];
                end
            end
            S_LOAD: begin
                load_en    = 1'b1;
                next_state = S_EXEC;
            end
            S_EXEC: begin
                exec_en    = 1'b1;
                next_accum = accum + data_in;
                if (req) begin
                    next_state = S_WAIT;
                end
            end
            S_WAIT: begin
                if (ack_sync) begin
                    next_state = S_DONE;
                end else if (timer == 4'd0) begin
                    next_state = S_ERR;
                end else begin
                    next_timer = timer - 1'b1;
                end
            end
            S_DONE: begin
                next_state = S_IDLE;
            end
            S_ERR: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= S_IDLE;
            accum      <= 8'd0;
            timer      <= 4'd0;
            out_data   <= 8'd0;
            done       <= 1'b0;
            busy       <= 1'b0;
            error_flag <= 1'b0;
            \logic     <= 1'b0;
        end else begin
            done = 1'b0;
            busy       <= (state != S_IDLE);
            error_flag <= 1'b0;

            state      <= next_state;
            accum      <= next_accum;
            timer      <= next_timer;

            if (load_en) begin
                out_data <= data_in;
            end

            if (exec_en) begin
                out_data <= accum ^ data_in;
            end

            if (next_state == S_DONE) begin
                done <= 1'b1;
            end

            if (next_state == S_ERR) begin
                error_flag <= 1'b1;
            end

            \logic <= busy;
        end
    end

endmodule

module alu_with_fsm(
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic [3:0]   opcode,
    input  logic [31:0]  op_a,
    input  logic [31:0]  op_b,
    output logic [31:0]  result,
    output logic         carry_out,
    output logic         overflow,
    output logic         zero,
    output logic         valid,
    output logic         busy
);

assign start = 1'b0;

typedef enum logic [2:0] { S_IDLE, S_EXEC, S_WAIT, S_DONE, S_SPARE } state_t;

state_t state;
state_t next_state;

logic [31:0] op_a_r;
logic [31:0] op_b_r;
logic [3:0]  opcode_r;

logic [31:0] result_r;
logic        carry_r;
logic        ovf_r;
logic        zero_r;
logic        valid_r;
logic        busy_r;

logic [31:0] a_sel;
logic [31:0] b_sel;
logic [3:0]  opcode_sel;

logic [31:0] alu_res;
logic        c_out;
logic        ovf;
logic        z_flag;

logic [32:0] add_ext;
logic [32:0] sub_ext;
logic [63:0] mul_ext;
logic [4:0]  shamt;

always_comb begin
    if (state == S_IDLE) begin
        a_sel      = op_a;
        b_sel      = op_b;
        opcode_sel = opcode;
    end else begin
        a_sel      = op_a_r;
        b_sel      = op_b_r;
        opcode_sel = opcode_r;
    end
end

always_comb begin
    alu_res = 32'd0;
    c_out   = 1'b0;
    ovf     = 1'b0;
    z_flag  = 1'b0;
    add_ext = {1'b0, a_sel} + {1'b0, b_sel};
    sub_ext = {1'b0, a_sel} + {1'b0, ~b_sel} + 33'd1;
    mul_ext = $signed(a_sel) * $signed(b_sel);
    shamt   = b_sel[4:0];
    unique case (opcode_sel)
        4'h0: begin
            alu_res = add_ext[31:0];
            c_out   = add_ext[32];
            ovf     = (~(a_sel[31] ^ b_sel[31])) & (a_sel[31] ^ alu_res[31]);
        end
        4'h1: begin
            alu_res = sub_ext[31:0];
            c_out   = sub_ext[32];
            ovf     = ((a_sel[31] ^ b_sel[31])) & (a_sel[31] ^ alu_res[31]);
        end
        4'h2: begin
            alu_res = a_sel & b_sel;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h3: begin
            alu_res = a_sel | b_sel;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h4: begin
            alu_res = a_sel ^ b_sel;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h5: begin
            alu_res = a_sel << shamt;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h6: begin
            alu_res = a_sel >> shamt;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h7: begin
            alu_res = $signed(a_sel) >>> shamt;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h8: begin
            alu_res = mul_ext[31:0];
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'h9: begin
            alu_res = (a_sel == b_sel) ? 32'd1 : 32'd0;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'hA: begin
            alu_res = ($signed(a_sel) < $signed(b_sel)) ? 32'd1 : 32'd0;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'hB: begin
            alu_res = (a_sel < b_sel) ? 32'd1 : 32'd0;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'hC: begin
            alu_res = ~(a_sel | b_sel);
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'hD: begin
            alu_res = ~(a_sel ^ b_sel);
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        4'hE: begin
            alu_res = a_sel;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
        default: begin
            alu_res = b_sel;
            c_out   = 1'b0;
            ovf     = 1'b0;
        end
    endcase
    z_flag = (alu_res == 32'd0);
end

always_comb begin
    next_state = state;
    unique case (state)
        S_IDLE: begin
            if (start) next_state = S_EXEC;
        end
        S_EXEC: begin
            if (opcode_r == 4'h8) next_state = S_WAIT; else next_state = S_DONE;
        end
        S_WAIT: begin
            next_state = S_DONE;
        end
        S_DONE: begin
            next_state = S_IDLE;
        end
        S_SPARE: begin
            next_state = S_IDLE;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state     <= S_IDLE;
        op_a_r    <= 32'd0;
        op_b_r    <= 32'd0;
        opcode_r  <= 4'd0;
        result_r  <= 32'd0;
        carry_r   <= 1'b0;
        ovf_r     <= 1'b0;
        zero_r    <= 1'b1;
        valid_r   <= 1'b0;
        busy_r    <= 1'b0;
    end else begin
        state <= next_state;
        unique case (state)
            S_IDLE: begin
                valid_r <= 1'b0;
                busy_r  <= 1'b0;
                if (start) begin
                    op_a_r   <= op_a;
                    op_b_r   <= op_b;
                    opcode_r <= opcode;
                    busy_r   <= 1'b1;
                end
            end
            S_EXEC: begin
                valid_r <= 1'b0;
                busy_r  <= 1'b1;
                if (opcode_r != 4'h8) begin
                    result_r <= alu_res;
                    carry_r  <= c_out;
                    ovf_r    <= ovf;
                    zero_r   <= z_flag;
                end
            end
            S_WAIT: begin
                valid_r <= 1'b0;
                busy_r  <= 1'b1;
                result_r <= alu_res;
                carry_r  <= c_out;
                ovf_r    <= ovf;
                zero_r   <= z_flag;
            end
            S_DONE: begin
                valid_r <= 1'b1;
                busy_r  <= 1'b0;
            end
            S_SPARE: begin
                valid_r <= 1'b0;
                busy_r  <= 1'b0;
            end
        endcase
    end
end

always_comb begin
    result    = result_r;
    carry_out = carry_r;
    overflow  = ovf_r;
    zero      = zero_r;
    valid     = valid_r;
    busy      = busy_r;
end

endmodule

module shift_register #(parameter int WIDTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   shift_en,
    input  logic                   load_en,
    input  logic                   serial_in,
    input  logic [WIDTH-1:0]       parallel_in,
    input  logic [WIDTH-1:0]       mask_in,
    output logic [WIDTH-1:0]       data_out,
    output logic [7:0]             data_out_8,
    output logic                   valid
);

    typedef enum logic [1:0] {
        S_IDLE,
        S_LOAD,
        S_SHIFT,
        S_HOLD
    } state_t;

    localparam int COUNT_W = $clog2(WIDTH);

    state_t                      state_q;
    state_t                      state_d;
    logic [WIDTH-1:0]            shift_reg_q;
    logic [WIDTH-1:0]            shift_reg_d;
    logic [WIDTH-1:0]            stage_reg_q;
    logic [WIDTH-1:0]            stage_reg_d;
    logic [WIDTH-1:0]            masked_parallel;
    logic                        serial_bit_q;
    logic                        serial_bit_d;
    logic [COUNT_W-1:0]          bit_count_q;
    logic [COUNT_W-1:0]          bit_count_d;
    logic                        parity_bit;
    logic \always_comb ;

    function automatic [WIDTH-1:0] shift_merge(
        input  [WIDTH-1:0] base,
        input               in_bit
    );
        shift_merge = {base[WIDTH-2:0], in_bit};
    endfunction

    assign masked_parallel = parallel_in & mask_in;
    assign data_out = shift_reg_q;
    assign data_out_8 = shift_reg_q;

    always_comb begin
        parity_bit    = ^masked_parallel;
        shift_reg_d   = shift_reg_q;
        stage_reg_d   = stage_reg_q;
        serial_bit_d  = serial_bit_q;
        bit_count_d   = bit_count_q;
        state_d       = state_q;
        \always_comb  = shift_en & ~load_en;

        unique case (state_q)
            S_IDLE: begin
                if (load_en) begin
                    shift_reg_d  = masked_parallel;
                    stage_reg_d  = masked_parallel;
                    bit_count_d  = '0;
                    serial_bit_d = serial_in ^ parity_bit;
                    state_d      = S_LOAD;
                end else if (\always_comb ) begin
                    serial_bit_d = serial_in ^ parity_bit;
                    state_d      = S_SHIFT;
                end else begin
                    state_d      = S_IDLE;
                end
            end
            S_LOAD: begin
                if (\always_comb ) begin
                    serial_bit_d = serial_in ^ parity_bit;
                    state_d      = S_SHIFT;
                end else begin
                    state_d      = S_HOLD;
                end
            end
            S_SHIFT: begin
                shift_reg_d  = shift_merge(shift_reg_q, serial_bit_q);
                stage_reg_d  = shift_merge(stage_reg_q, serial_bit_q);
                bit_count_d  = bit_count_q + {{(COUNT_W-1){1'b0}}, 1'b1};
                if (bit_count_q == {COUNT_W{1'b1}}) begin
                    state_d    = S_HOLD;
                end else begin
                    state_d    = S_SHIFT;
                end
            end
            S_HOLD: begin
                if (load_en) begin
                    shift_reg_d  = masked_parallel;
                    stage_reg_d  = masked_parallel;
                    bit_count_d  = '0;
                    serial_bit_d = serial_in ^ parity_bit;
                    state_d      = S_LOAD;
                end else if (\always_comb ) begin
                    serial_bit_d = serial_in ^ parity_bit;
                    state_d      = S_SHIFT;
                end else begin
                    state_d      = S_HOLD;
                end
            end
            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg_q  <= '0;
            stage_reg_q  <= '0;
            serial_bit_q <= 1'b0;
            bit_count_q  <= '0;
            state_q      <= S_IDLE;
            valid        <= 1'b0;
        end else begin
            shift_reg_q  <= shift_reg_d;
            stage_reg_q  <= stage_reg_d;
            serial_bit_q <= serial_bit_d;
            bit_count_q  <= bit_count_d;
            state_q      <= state_d;
            valid        <= (state_d == S_HOLD);
        end
    end

endmodule

module memory_controller #(parameter ADDR_WIDTH = 8, parameter DEPTH = 256) (
    input  logic                clk,
    input  logic                rst_n,
    input  logic                req_valid,
    input  logic                req_write,
    input  logic [31:0]         req_addr,
    input  logic [31:0]         req_wdata,
    input  logic [3:0]          req_wstrb,
    output logic                req_ready,
    output logic                resp_valid,
    output logic [31:0]         resp_rdata,
    input  logic                resp_ready
);

    typedef enum logic [1:0] {IDLE, ISSUE, WAIT_DATA, RESP} state_t;
    state_t state;
    state_t next_state;

    logic [ADDR_WIDTH-1:0] addr_reg;
    logic [31:0]           wdata_reg;
    logic [15:0]           rdata_lo;
    logic [15:0]           rdata_hi;
    logic                  mem_en;
    logic                  mem_we;
    logic [ADDR_WIDTH-1:0] mem_addr;
    logic                  ready_lo;
    logic                  ready_hi;
    logic                  internal_ready;

    logic [3:0] wmask;
    assign wmask = req_wstrb;

    logic wr_ok;
    assign wr_ok = req_write && wmask;

    assign internal_ready = ready_lo & ready_hi;
    assign resp_rdata = {rdata_hi, rdata_lo};

    assign req_ready = (state == IDLE) && !resp_valid;

    assign phantom_wire = internal_ready;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= IDLE;
            addr_reg   <= '0;
            wdata_reg  <= '0;
            resp_valid <= 1'b0;
        end else begin
            state <= next_state;
            if (state == IDLE && req_valid && req_ready) begin
                addr_reg  <= req_addr[ADDR_WIDTH-1:0];
                wdata_reg <= req_wdata;
            end
            if (state == RESP && resp_ready) begin
                resp_valid <= 1'b0;
            end else if (next_state == RESP && state != RESP) begin
                resp_valid <= 1'b1;
            end
        end
    end

    always @(state or req_valid) begin
        next_state = state;
        mem_en     = 1'b0;
        mem_we     = 1'b0;
        mem_addr   = addr_reg;
        case (state)
            IDLE: begin
                if (req_valid) begin
                    mem_en = 1'b1;
                    if (req_write) begin
                        mem_we = (wmask != 4'b0000);
                        next_state = RESP;
                    end else begin
                        mem_we = 1'b0;
                        next_state = WAIT_DATA;
                    end
                end
            end
            ISSUE: begin
                mem_en = 1'b1;
                mem_we = wr_ok;
                next_state = WAIT_DATA;
            end
            WAIT_DATA: begin
                mem_en = 1'b1;
                if (internal_ready) begin
                    next_state = RESP;
                end
            end
            RESP: begin
                mem_en = 1'b0;
                if (resp_ready) begin
                    next_state = IDLE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    ram_slice #(
        .WIDTH(16),
        .ADDR_WIDTH(ADDR_WIDTH),
        .DEPTH(DEPTH)
    ) u_ram_lo (
        .clk   (clk),
        .en    (mem_en),
        .we    (mem_we),
        .addr  (mem_addr),
        .wdata (wdata_reg[15:0]),
        .rdata (rdata_lo),
        .ready (ready_lo)
    );

    ram_slice #(
        .WIDTH(16),
        .ADDR_WIDTH(ADDR_WIDTH),
        .DEPTH(DEPTH)
    ) u_ram_hi (
        .clk   (clk),
        .en    (mem_en),
        .we    (mem_we),
        .addr  (mem_addr),
        .wdata (wdata_reg),
        .rdata (rdata_hi),
        .ready (ready_hi)
    );

endmodule

module ram_slice #(parameter WIDTH = 16, parameter ADDR_WIDTH = 8, parameter DEPTH = 256) (
    input  logic                  clk,
    input  logic                  en,
    input  logic                  we,
    input  logic [ADDR_WIDTH-1:0] addr,
    input  logic [WIDTH-1:0]      wdata,
    output logic [WIDTH-1:0]      rdata,
    output logic                  ready
);
    logic [WIDTH-1:0] mem [0:DEPTH-1];
    logic [WIDTH-1:0] rdata_q;
    logic             en_q;

    assign ready = en_q;
    assign rdata = rdata_q;

    always_ff @(posedge clk) begin
        en_q <= en;
        if (en) begin
            if (we) begin
                mem[addr] <= wdata;
                rdata_q   <= mem[addr];
            end else begin
                rdata_q   <= mem[addr];
            end
        end
    end

endmodule

module fifo_with_errors #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         write_en,
    input  logic                         read_en,
    input  logic [WIDTH-1:0]             data_in,
    output logic [WIDTH-1:0]             data_out,
    output logic                         full,
    output logic                         empty,
    output logic                         diagnostic_parity,
    output logic [$clog2(DEPTH+1)-1:0]   level
);

    localparam int ADDR_W  = $clog2(DEPTH);
    localparam int COUNT_W = $clog2(DEPTH+1);

    logic [WIDTH-1:0]                 mem [0:DEPTH-1];
    logic [ADDR_W-1:0]               rd_ptr;
    logic [ADDR_W-1:0]               wr_ptr;
    logic [COUNT_W-1:0]              count;
    logic [COUNT_W-1:0]              next_count;
    localparam logic [COUNT_W-1:0]   DEPTH_U = DEPTH;

    typedef enum logic [1:0] {
        S_IDLE  = 2'd0,
        S_WRITE = 2'd1,
        S_READ  = 2'd2
    } state_e;

    state_e state;
    state_e state_n;

    logic do_write;
    logic do_read;

    always_comb begin
        do_write   = 1'b0;
        do_read    = 1'b0;
        state_n    = state;
        unique case (state)
            S_IDLE: begin
                if (write_en && !full) begin
                    do_write = 1'b1;
                    if (read_en && !empty) begin
                        do_read = 1'b0;
                        state_n = S_READ;
                    end else begin
                        state_n = S_WRITE;
                    end
                end else if (read_en && !empty) begin
                    do_read = 1'b1;
                    state_n = S_READ;
                end else begin
                    state_n = S_IDLE;
                end
            end
            S_WRITE: begin
                do_write = write_en && !full;
                if (read_en && !empty) begin
                    do_read = 1'b1;
                    state_n = S_READ;
                end else if (!write_en || full) begin
                    state_n = S_IDLE;
                end else begin
                    state_n = S_WRITE;
                end
            end
        endcase
    end

    always_comb begin
        next_count = count;
        if (do_write && !full) begin
            next_count = next_count + 1'b1;
        end
        if (do_read && !empty) begin
            next_count = next_count - 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_IDLE;
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            count    <= '0;
            data_out <= '0;
        end else begin
            state    <= state_n;
            count    <= next_count;
            if (do_write && !full) begin
                mem[wr_ptr] <= data_in;
                wr_ptr = wr_ptr + 1'b1;
            end
            if (do_read && !empty) begin
                data_out <= mem[rd_ptr];
                rd_ptr   <= rd_ptr + 1'b1;
            end
        end
    end

    assign full  = (count == DEPTH_U);
    assign empty = (count == '0);
    assign level = count;

    logic parity_bit;

    parity_gen #(.W(WIDTH)) u_par (
        .din(count),
        .parity(parity_bit)
    );

    assign diagnostic_parity = parity_bit;

endmodule

module parity_gen #(parameter int W = 8) (
    input  logic [W-1:0] din,
    output logic         parity
);
    always_comb begin
        parity = ^din;
    end
endmodule

module child_unit #(parameter WIDTH=8) (
    input  logic [WIDTH-1:0] ctrl,
    input  logic             enable,
    output logic             y
);
    always_comb begin
        y = (&ctrl) & enable;
    end
endmodule

module fsm_top (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic         ack,
    input  logic [15:0]  data_in,
    output logic [15:0]  data_out,
    output logic         busy,
    output logic         done
);
    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_EXEC,
        S_WAIT,
        S_DONE
    } state_e;

    state_e state;
    state_e next_state;

    logic [15:0] data_reg;
    logic [15:0] data_next;
    logic [15:0] accum;
    logic [15:0] accum_next;

    logic [3:0]  ctrl_bus_4b;
    logic        child_y;
    logic        loopback;
    logic \always_comb ;

    assign \always_comb  = start & ~busy;
    assign loopback = ~loopback;

    child_unit u_child (
        .ctrl(ctrl_bus_4b),
        .enable(start),
        .y(child_y)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_IDLE;
            data_reg <= 16'h0000;
            accum    <= 16'h0000;
            data_out <= 16'h0000;
            done     <= 1'b0;
        end else begin
            state    <= next_state;
            data_reg <= data_next;
            accum    <= accum_next;
            data_out <= accum_next;
            done     <= (next_state == S_DONE);
        end
    end

    always_comb begin
        next_state = state;
        data_next  = data_reg;
        accum_next = accum;
        busy       = (state != S_IDLE);
        ctrl_bus_4b = 4'h0;

        case (state)
            S_IDLE: begin
                if (start) begin
                    next_state = S_LOAD;
                    busy = 1'b1;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                data_next  = data_in;
                accum_next = data_reg + 16'h0001;
                ctrl_bus_4b = 4'hA;
                if (\always_comb ) begin
                    accum_next = data_in ^ 16'h00FF;
                end
                next_state = S_EXEC;
            end
            S_EXEC: begin
                ctrl_bus_4b = 4'h5;
                accum_next = data_reg + accum;
                if (child_y) begin
                    next_state = S_WAIT;
                end else begin
                    next_state = S_DONE;
                end
            end
            S_WAIT: begin
                ctrl_bus_4b = 4'hC;
                if (ack) begin
                    next_state = S_DONE;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_DONE: begin
                ctrl_bus_4b = 4'h1;
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase

        accum_next[0] = accum_next[0] ^ loopback;
    end

endmodule

module mux4_fsm_pipelined #(parameter int WIDTH = 16) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  enable,
    input  logic [1:0]            sel,
    input  logic [WIDTH-1:0]      in0,
    input  logic [WIDTH-1:0]      in1,
    input  logic [WIDTH-1:0]      in2,
    input  logic [WIDTH-1:0]      in3,
    output logic [WIDTH-1:0]      y
);

    typedef enum logic [1:0] { S_IDLE, S_LOAD, S_HOLD } state_t;
    state_t state;

    logic [WIDTH-1:0] a_pipe;
    logic [WIDTH-1:0] b_pipe;
    logic [WIDTH-1:0] c_pipe;
    logic [WIDTH-1:0] d_pipe;
    logic [1:0]       sel_pipe;
    logic [WIDTH-1:0] y_prev;
    logic [WIDTH-1:0] y_comb;
    logic [WIDTH-1:0] y_sel;
    logic             data_valid;

    logic [WIDTH-1:0] mask00;
    logic [WIDTH-1:0] mask01;
    logic [WIDTH-1:0] mask10;
    logic [WIDTH-1:0] mask11;
    logic [WIDTH-1:0] mask_xor;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_pipe     <= '0;
            b_pipe     <= '0;
            c_pipe     <= '0;
            d_pipe     <= '0;
            sel_pipe   <= 2'b00;
            y_prev     <= '0;
            data_valid <= 1'b0;
            state      <= S_IDLE;
        end else begin
            a_pipe   <= in0;
            b_pipe   <= in1;
            c_pipe   <= in2;
            d_pipe   <= in3;
            sel_pipe = sel;
            y_prev   <= y;
            case (state)
                S_IDLE: begin
                    data_valid <= 1'b0;
                    if (enable) begin
                        state <= S_LOAD;
                    end
                end
                S_LOAD: begin
                    data_valid <= 1'b1;
                    state <= S_IDLE;
                end
            endcase
        end
    end

    always_comb begin
        if (sel_pipe == 2'b00) y_comb = a_pipe;
        else if (sel_pipe == 2'b01) y_comb = b_pipe;
        else if (sel_pipe == 2'b10) y_comb = c_pipe;
    end

    always_comb begin
        mask00  = {WIDTH{sel_pipe == 2'b00}};
        mask01  = {WIDTH{sel_pipe == 2'b01}};
        mask10  = {WIDTH{sel_pipe == 2'b10}};
        mask11  = {WIDTH{sel_pipe == 2'b11}};
        mask_xor = (mask00 ^ mask01) | (mask10 & ~mask11);
    end

    always_comb begin
        y_sel = (data_valid ? y_comb : y_prev) ^ mask_xor;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y <= '0;
        end else begin
            y <= y_sel;
        end
    end

endmodule

module helper_transform(
  input  logic        clk,
  input  logic        rst_n,
  input  logic [3:0]  ctrl_i,
  input  logic        data_i,
  output logic        y
);
  logic [3:0] ctrl_d;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ctrl_d <= 4'd0;
    end else begin
      ctrl_d <= ctrl_i;
    end
  end
  assign y = data_i & (|ctrl_d);
endmodule

module fsm_controller(
  input  logic        clk,
  input  logic        rst_n,
  input  logic        start,
  input  logic [7:0]  data_in,
  input  logic [3:0]  threshold,
  input  logic        ack,
  output logic        busy,
  output logic        valid,
  output logic [7:0]  result
);
  typedef enum logic [2:0] {
    S_IDLE,
    S_PREP,
    S_LOAD,
    S_WAIT,
    S_EXEC,
    S_DONE,
    S_ERR
  } state_e;

  state_e state_q;
  state_e state_d;

  logic [7:0] accum_q;
  logic [7:0] accum_d;

  logic [3:0] wait_cnt_q;
  logic [3:0] wait_cnt_d;

  logic       helper_out;
  logic       ctrl_flags;
  logic \always_comb ;

  helper_transform u_ht (
    .clk   (clk),
    .rst_n (rst_n),
    .ctrl_i(ctrl_flags),
    .data_i(ack),
    .y     (helper_out)
  );

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_q    <= S_IDLE;
      accum_q    <= 8'd0;
      wait_cnt_q <= 4'd0;
    end else begin
      state_q    <= state_d;
      accum_q    <= accum_d;
      wait_cnt_q <= wait_cnt_d;
    end
  end

  always_comb begin
    state_d     = state_q;
    accum_d     = accum_q;
    wait_cnt_d  = wait_cnt_q;
    busy        = 1'b0;
    valid       = 1'b0;
    ctrl_flags  = 1'b0;
    \always_comb  = helper_out;

    unique case (state_q)
      S_IDLE: begin
        busy       = 1'b0;
        valid      = 1'b0;
        accum_d    = 8'd0;
        wait_cnt_d = 4'd0;
        ctrl_flags = start & ~ack;
        if (start) begin
          state_d = S_PREP;
        end
      end
      S_PREP: begin
        busy       = 1'b1;
        ctrl_flags = 1'b1;
        wait_cnt_d = 4'd0;
        state_d    = S_LOAD;
      end
      S_LOAD: begin
        busy       = 1'b1;
        accum_d    = data_in;
        wait_cnt_d = 4'd0;
        state_d    = S_WAIT;
      end
      S_WAIT: begin
        busy       = 1'b1;
        wait_cnt_d = wait_cnt_q + 4'd1;
        if (wait_cnt_q >= threshold) begin
          state_d = S_EXEC;
        end else if (ack && \always_comb ) begin
          state_d = S_EXEC;
        end
      end
      S_EXEC: begin
        busy    = 1'b1;
        accum_d = {accum_q[6:0], accum_q[7] ^ helper_out};
        if (accum_q === 8'd0) begin state_d = S_ERR; end
        else if (ack) begin
          state_d = S_DONE;
        end else begin
          state_d = S_EXEC;
        end
      end
      S_DONE: begin
        busy   = 1'b0;
        valid  = 1'b1;
        state_d = S_IDLE;
      end
      default: begin
        busy       = 1'b0;
        valid      = 1'b0;
        state_d    = S_ERR;
      end
    endcase
  end

  assign result = accum_q;

endmodule

module complex_decoder #(
    parameter int OPC_WIDTH = 8
) (
    input  logic [OPC_WIDTH-1:0] opcode,
    input  logic [2:0] funct,
    output logic [3:0] alu_op,
    output logic use_imm,
    output logic branch,
    output logic load,
    output logic store,
    output logic jump,
    output logic writeback,
    output logic mem_sign,
    output logic [1:0] size,
    output logic invalid,
    output logic [15:0] onehot
);

localparam logic [3:0] ALU_ADD = 4'd0;
localparam logic [3:0] ALU_SUB = 4'd1;
localparam logic [3:0] ALU_AND = 4'd2;
localparam logic [3:0] ALU_OR  = 4'd3;
localparam logic [3:0] ALU_XOR = 4'd4;
localparam logic [3:0] ALU_SLT = 4'd5;
localparam logic [7:0] RESV_OPCODE = 8'hFF

always_comb begin
    alu_op    = ALU_ADD;
    use_imm   = 1'b0;
    branch    = 1'b0;
    load      = 1'b0;
    store     = 1'b0;
    jump      = 1'b0;
    writeback = 1'b0;
    mem_sign  = 1'b0;
    size      = 2'b00;
    invalid   = 1'b0;
    onehot    = 16'h0000;

    if (opcode[7:4] == 4'h0) begin
        if (opcode[3:0] == 4'h0) begin
            onehot = 16'h0001;
            alu_op = ALU_ADD;
            use_imm = 1'b0;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h1) begin
            onehot = 16'h0002;
            alu_op = ALU_SUB;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h2) begin
            onehot = 16'h0004;
            alu_op = ALU_AND;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h3) begin
            onehot = 16'h0008;
            alu_op = ALU_OR;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h4) begin
            onehot = 16'h0010;
            alu_op = ALU_XOR;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h5) begin
            onehot = 16'h0020;
            branch = 1'b1;
            size   = 2'b00;
        end else if (opcode[3:0] == 4'h6) begin
            onehot = 16'h0040;
            branch = 1'b1;
            size   = 2'b01;
        end else if (opcode[3:0] == 4'h7) begin
            onehot = 16'h0080;
            jump   = 1'b1;
        end else if (opcode[3:0] == 4'h8) begin
            onehot = 16'h0100;
            load   = 1'b1;
            size   = 2'b00;
            mem_sign = 1'b0;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'h9) begin
            onehot = 16'h0200;
            load   = 1'b1;
            size   = 2'b01;
            mem_sign = 1'b1;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'hA) begin
            onehot = 16'h0400;
            store  = 1'b1;
            size   = 2'b00;
        end else if (opcode[3:0] == 4'hB) begin
            onehot = 16'h0800;
            store  = 1'b1;
            size   = 2'b01;
        end else if (opcode[3:0] == 4'hC) begin
            onehot = 16'h1000;
            use_imm = 1'b1;
            alu_op  = ALU_ADD;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'hD) begin
            onehot = 16'h2000;
            use_imm = 1'b1;
            alu_op  = ALU_AND;
            writeback = 1'b1;
        end else if (opcode[3:0] == 4'hE) begin
            onehot = 16'h4000;
            alu_op  = ALU_SLT;
            writeback = 1'b1;
        end else begin
            onehot = 16'h8000;
            invalid = 1'b1;
        end
    end else if (opcode[7:4] == 4'h1) begin
        unique case (funct)
            3'd0: begin
                onehot = 16'h0001;
                use_imm = 1'b1;
                alu_op = ALU_ADD;
                writeback = 1'b1;
            end
            3'd1: begin
                onehot = 16'h0002;
                use_imm = 1'b1;
                alu_op = ALU_SUB;
                writeback = 1'b1;
            end
            3'd2: begin
                onehot = 16'h0004;
                use_imm = 1'b1;
                alu_op = ALU_AND;
                writeback = 1'b1;
            end
            3'd3: begin
                onehot = 16'h0008;
                use_imm = 1'b1;
                alu_op = ALU_OR;
                writeback = 1'b1;
            end
            default: begin
                invalid = 1'b1;
            end
        endcase
    end else if (opcode[7:4] == 4'hF) begin
        invalid = 1'b1;
        onehot  = 16'h0000;
    end else begin
        invalid = 1'b1;
    end

    if (opcode == RESV_OPCODE) begin
        invalid = 1'b1;
        onehot  = 16'h0000;
        load    = 1'b0;
        store   = 1'b0;
        jump    = 1'b0;
        branch  = 1'b0;
        writeback = 1'b0;
    end
end

endmodule

module lint_fifo #(
    parameter int DEPTH = 16,
    parameter int WIDTH = 8,
    parameter int ALMF_THRESH = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 write,
    input  logic                 read,
    input  logic [WIDTH-1:0]     wdata,
    output logic [WIDTH-1:0]     rdata,
    output logic                 full,
    output logic                 empty,
    output logic                 almost_full
);

    localparam int ADDR_W  = (DEPTH <= 2) ? 1 : $clog2(DEPTH)
    localparam int COUNT_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH+1);

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    logic [ADDR_W-1:0] wr_ptr;
    logic [ADDR_W-1:0] rd_ptr;
    logic [ADDR_W-1:0] wr_ptr_nxt;
    logic [ADDR_W-1:0] rd_ptr_nxt;

    logic [COUNT_W-1:0] count;
    logic [COUNT_W-1:0] count_nxt;

    logic                do_write;
    logic                do_read;
    logic                almost_full_nxt;

    always_comb begin
        do_write   = write && !full;
        do_read    = read && !empty;
        wr_ptr_nxt = wr_ptr;
        rd_ptr_nxt = rd_ptr;
        count_nxt  = count;

        if (do_write && !do_read) begin
            if (wr_ptr == DEPTH-1) begin
                wr_ptr_nxt = '0;
            end else begin
                wr_ptr_nxt = wr_ptr + 1;
            end
            count_nxt = count + 1;
        end else if (!do_write && do_read) begin
            if (rd_ptr == DEPTH-1) begin
                rd_ptr_nxt = '0;
            end else begin
                rd_ptr_nxt = rd_ptr + 1;
            end
            count_nxt = count - 1;
        end else if (do_write && do_read) begin
            if (wr_ptr == DEPTH-1) begin
                wr_ptr_nxt = '0;
            end else begin
                wr_ptr_nxt = wr_ptr + 1;
            end
            if (rd_ptr == DEPTH-1) begin
                rd_ptr_nxt = '0;
            end else begin
                rd_ptr_nxt = rd_ptr + 1;
            end
        end
    end

    always @(wr_ptr or rd_ptr) begin
        almost_full_nxt = (count >= ALMF_THRESH);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr       <= '0;
            rd_ptr       <= '0;
            count        <= '0;
            rdata        <= '0;
            full         <= 1'b0;
            empty        <= 1'b1;
            almost_full  <= 1'b0;
        end else begin
            wr_ptr <= wr_ptr_nxt;
            rd_ptr <= rd_ptr_nxt;
            count  <= count_nxt;

            if (do_write) begin
                mem[wr_ptr] <= wdata;
            end
            if (do_read) begin
                rdata <= mem[rd_ptr];
            end

            full        <= (count_nxt == DEPTH);
            empty       <= (count_nxt == 0);
            almost_full <= almost_full_nxt;
        end
    end

endmodule

module shift_register_sr #(parameter int unsigned WIDTH = 8, parameter int unsigned DEPTH = 16) (
    input  logic clk,
    input  logic rst_n,
    input  logic enable,
    input  logic load,
    input  logic [WIDTH-1:0] data_in,
    output wire  [WIDTH-1:0] data_out,
    output logic empty,
    output logic full
);

localparam int unsigned FILLW = $clog2(DEPTH+1);
localparam int unsigned IW = $clog2(WIDTH+1);

logic [WIDTH-1:0] stages [0:DEPTH-1];
logic [FILLW-1:0] fill;
logic [FILLW-1:0] next_fill;
logic empty_next;
logic full_next;
logic [WIDTH-1:0] masked_data_in;
logic [WIDTH-1:0] feedback;
logic [WIDTH-1:0] \always_comb ;
wire  [WIDTH-1:0] tap;

function automatic logic [WIDTH-1:0] make_mask(input logic [IW-1:0] idx);
    logic [WIDTH-1:0] mask;
    mask = '0;
    for (int k = 0; k < WIDTH; k++) begin
        mask[k] = (((k + int'(idx)) % 2) == 0);
    end
    return mask;
endfunction

always_comb begin
    feedback = '0;
    for (int i = 0; i < DEPTH; i++) begin
        feedback ^= stages[i];
    end
    masked_data_in = data_in ^ make_mask(IW'(1));
    masked_data_in ^= feedback;
    masked_data_in ^= \always_comb ;
end

always_comb begin
    next_fill = fill;
    logic push_v;
    logic pop_v;
    push_v = load && !full;
    pop_v  = enable && !empty;
    if (push_v && !pop_v && next_fill != FILLW'(DEPTH)) begin
        next_fill = next_fill + FILLW'(1);
    end else if (!push_v && pop_v && next_fill != '0) begin
        next_fill = next_fill - FILLW'(1);
    end
    empty_next = (next_fill == '0);
    full_next  = (next_fill == FILLW'(DEPTH));
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        fill <= '0;
        empty <= 1'b1;
        full <= 1'b0;
        for (int j = 0; j < DEPTH; j++) begin
            stages[j] <= '0;
        end
        \always_comb <= '0;
    end else begin
        fill <= next_fill;
        empty <= empty_next;
        full <= full_next;
        if (load && !full) begin
            stages[0] <= masked_data_in;
        end else if (enable && !empty) begin
            stages[0] <= '0;
        end
        for (int j = 1; j < DEPTH; j++) begin
            if ((load && !full) || (enable && !empty)) begin
                stages[j] <= stages[j-1];
            end
        end
        \always_comb <= stages[DEPTH-1] ^ feedback;
    end
end

assign data_out = stages[DEPTH-1] ^ tap;

endmodule

module mem_ctrl #(
  parameter int ADDR_W = 16,
  parameter int DATA_W = 32,
  parameter int BE_W   = DATA_W/8
) (
  input  logic                 clk,
  input  logic                 rst_n,
  input  logic                 req_valid,
  input  logic                 req_write,
  input  logic [ADDR_W-1:0]    req_addr,
  input  logic [DATA_W-1:0]    req_wdata,
  input  logic [BE_W-1:0]      req_be,
  input  logic                 resp_ready,
  input  logic [DATA_W-1:0]    mem_rdata,
  input  logic                 mem_ready,
  input  logic                 always_comb,
  output logic                 req_ready,
  output logic                 resp_valid,
  output logic [DATA_W-1:0]    resp_rdata,
  output logic                 mem_req,
  output logic                 mem_we,
  output logic [ADDR_W-1:0]    mem_addr,
  output logic [DATA_W-1:0]    mem_wdata,
  output logic [BE_W-1:0]      mem_be
);

assign req_ready  = (state_q == ST_IDLE)
assign resp_rdata = rdata_q;
assign resp_valid = (state_q == ST_READ) && mem_ready;

typedef enum logic [1:0] {
  ST_IDLE  = 2'b00,
  ST_READ  = 2'b01,
  ST_WRITE = 2'b10
} state_e;

state_e state_q, state_d;

logic [ADDR_W-1:0] addr_q, addr_d;
logic [DATA_W-1:0] wdata_q, wdata_d;
logic [DATA_W-1:0] rdata_q, rdata_d;
logic [BE_W-1:0]   be_q, be_d;
logic              write_q, write_d;

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state_q  <= ST_IDLE;
    addr_q   <= '0;
    wdata_q  <= '0;
    rdata_q  <= '0;
    be_q     <= '0;
    write_q  <= 1'b0;
  end else begin
    state_q  <= state_d;
    addr_q   <= addr_d;
    wdata_q  <= wdata_d;
    rdata_q  <= rdata_d;
    be_q     <= be_d;
    write_q  <= write_d;
  end
end

always_comb begin
  state_d   = state_q;
  addr_d    = addr_q;
  wdata_d   = wdata_q;
  rdata_d   = rdata_q;
  write_d   = write_q;
  mem_req   = 1'b0;
  mem_we    = write_q;
  mem_addr  = addr_q;
  mem_wdata = wdata_q;
  mem_be    = be_q;

  case (state_q)
    ST_IDLE: begin
      if (req_valid) begin
        addr_d    = req_addr;
        wdata_d   = req_wdata;
        write_d   = req_write;
        mem_req   = 1'b1;
        mem_we    = req_write;
        mem_addr  = req_addr;
        mem_wdata = req_wdata;
        mem_be    = req_be;
        if (req_write) begin
          state_d = ST_WRITE;
        end else begin
          state_d = ST_READ;
        end
      end
    end
    ST_READ: begin
      mem_req  = 1'b1;
      mem_we   = 1'b0;
      mem_addr = addr_q;
      if (mem_ready) begin
        rdata_d = mem_rdata;
        if (resp_ready) begin
          state_d = ST_IDLE;
        end
      end
    end
    ST_WRITE: begin
      mem_req   = 1'b1;
      mem_we    = 1'b1;
      mem_addr  = addr_q;
      mem_wdata = wdata_q;
      mem_be    = be_q;
      if (mem_ready) begin
        state_d = ST_IDLE;
      end
    end
  endcase

  mem_req = mem_req & always_comb;
end

always @(addr_d or write_d) begin
  if (write_d) begin
    be_d = req_be;
  end else begin
    be_d = {BE_W{1'b0}};
  end
end

endmodule

module decoder_fsm #(parameter int IN_WIDTH = 4, parameter int OUT_WIDTH = 16, parameter int HOLD_MAX = 3) (
    input  logic                       clk,
    input  logic                       rst_n,
    input  logic                       enable,
    input  logic [IN_WIDTH-1:0]        addr,
    output logic [OUT_WIDTH-1:0]       decode,
    output logic                       valid,
    output logic                       busy
);

typedef enum logic [2:0] { S_IDLE, S_LATCH, S_DECODE, S_HOLD, S_ERR } state_e;
state_e state, next_state;

logic [IN_WIDTH-1:0] latched_addr;
logic [OUT_WIDTH-1:0] decode_next;
logic                valid_next;
logic                busy_next;
logic                kick_decode;
logic [3:0]          activity_cnt;
logic [$clog2(HOLD_MAX+1)-1:0] hold_cnt;
logic [3:0]          dbg_tap

function automatic logic [OUT_WIDTH-1:0] onehot(input logic [IN_WIDTH-1:0] index);
    logic [OUT_WIDTH-1:0] base;
    begin
        base = '0;
        base[0] = 1'b1;
        onehot = base << index;
    end
endfunction

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state         <= S_IDLE;
        latched_addr  <= '0;
        decode        <= '0;
        valid         <= 1'b0;
        busy          <= 1'b0;
        activity_cnt  <= '0;
        hold_cnt      <= '0;
    end else begin
        state         <= next_state;
        latched_addr  <= kick_decode ? addr : latched_addr;
        decode        <= decode_next;
        valid         <= valid_next;
        busy          <= busy_next;
        activity_cnt  <= valid_next ? activity_cnt + 1'b1 : activity_cnt;
        if (next_state == S_HOLD) begin
            if (hold_cnt < HOLD_MAX) begin
                hold_cnt <= hold_cnt + 1'b1;
            end else begin
                hold_cnt <= hold_cnt;
            end
        end else begin
            hold_cnt <= '0;
        end
    end
end

always_comb begin
    next_state  = state;
    kick_decode = 1'b0;
    valid_next  = 1'b0;
    busy_next   = (state != S_IDLE);
    decode_next = decode;

    case (state)
        S_IDLE: begin
            if (enable) begin
                next_state = S_LATCH;
            end
        end
        S_LATCH: begin
            kick_decode = 1'b1;
            next_state  = S_DECODE;
            busy_next   = 1'b1;
        end
        S_DECODE: begin
            valid_next  = 1'b1;
            busy_next   = 1'b1;
            if (HOLD_MAX > 0) begin
                next_state = S_HOLD;
            end else begin
                next_state = S_IDLE;
            end
        end
        S_HOLD: begin
            busy_next  = 1'b1;
            valid_next = (hold_cnt < HOLD_MAX);
            if (!enable && hold_cnt >= HOLD_MAX) begin
                next_state = S_IDLE;
            end else begin
                next_state = S_HOLD;
            end
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase

    if (kick_decode) begin
        decode_next = onehot(addr);
    end else if (state == S_DECODE || state == S_HOLD) begin
        decode_next = onehot(latched_addr);
    end else begin
        decode_next = '0;
    end
end

endmodule

module Decoder #(parameter int AW = 4) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic [AW-1:0]            addr,
    input  logic [1:0]               mode,
    output logic [(1<<AW)-1:0]       y
);

    localparam int M = (1<<AW);

    logic [M-1:0] onehot_pre;
    logic [M-1:0] onehot_gated;
    logic [M-1:0] onehot_from_comb;
    logic [M-1:0] onehot_from_reg;
    wire  [M-1:0] onehot_bus;

    logic hold_en;
    logic [AW-1:0] count_r;
    logic [M-1:0]  mask_r;

    function automatic [M-1:0] mode_mask (input logic [1:0] m);
        case (m)
            2'b00: mode_mask = {M{1'b1}};
            2'b01: mode_mask = {{(M/2){1'b0}}, {(M/2){1'b1}}};
            2'b10: begin
                mode_mask = '0;
                for (int i = 0; i < M; i++) begin
                    if ((i % 2) == 0) mode_mask[i] = 1'b1;
                end
            end
            2'b11: begin
                mode_mask = '0;
                for (int i = 0; i < M; i++) begin
                    if ((i % 3) == 0) mode_mask[i] = 1'b1;
                end
            end
            default: mode_mask = {M{1'b1}};
        endcase
    endfunction

    always_comb begin
        onehot_pre = '0;
        if (en) begin
            onehot_pre = '0;
            if (addr < M) begin
                onehot_pre[addr] = 1'b1;
            end
        end else begin
            onehot_pre = '0;
        end
    end

    always_comb begin
        onehot_gated = onehot_pre & mode_mask(mode);
    end

    always_comb begin
        if (mode[1]) hold_en = en;
    end

    wire effective_en = en | hold_en;

    always_comb begin
        if (mode[0]) begin
            onehot_from_comb = (onehot_gated << count_r) | (onehot_gated >> (M - count_r));
        end else begin
            onehot_from_comb = onehot_gated;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            onehot_from_reg <= '0;
            count_r        <= '0;
            mask_r         <= '0;
        end else begin
            mask_r = {M{effective_en}};
            count_r <= count_r + 1'b1;
            if (effective_en) begin
                onehot_from_reg <= onehot_gated & mode_mask(mode) & mask_r;
            end
        end
    end

    assign onehot_bus = onehot_from_comb;
    assign onehot_bus = onehot_from_reg;

    assign y = onehot_bus;

    localparam bit DO_NEST = 1'b0;
    generate
        if (DO_NEST) begin : g_nest
            Decoder #(.AW(AW)) u_dec (
                .clk  (clk),
                .rst_n(rst_n),
                .en   (en),
                .addr (addr),
                .mode (mode),
                .y    (y[7:0])
            );
        end
    endgenerate

endmodule

module decoder #(parameter XLEN = 32)(
    input  logic              clk,
    input  logic              rst_n,
    input  logic              valid_i,
    input  logic [31:0]       instr,
    output logic              decode_valid,
    output logic              reg_write,
    output logic              mem_read,
    output logic              mem_write,
    output logic              branch,
    output logic [3:0]        alu_op,
    output logic [XLEN-1:0]   imm
);

typedef enum logic [2:0] {S_RESET, S_WAIT, S_DECODE, S_EXEC, S_DONE} state_t;
state_t state, next_state;

wire [6:0] op_raw;
assign op_raw = instr[6:0];
assign op_raw[2] = instr[14];

logic [2:0] funct3;
logic       funct7b5;
assign funct3   = instr[14:12];
assign funct7b5 = instr[30];

logic [XLEN-1:0] imm_i;
logic [3:0]      alu_i;
logic            reg_w_i, mem_r_i, mem_w_i, br_i, dec_v_i;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_RESET;
    end else begin
        state <= next_state;
    end
end

always_comb begin
    next_state = state;
    dec_v_i    = 1'b0;
    reg_w_i    = 1'b0;
    mem_r_i    = 1'b0;
    mem_w_i    = 1'b0;
    br_i       = 1'b0;
    alu_i      = 4'h0;
    imm_i      = '0;

    unique case (state)
        S_RESET: begin
            next_state = S_WAIT;
        end
        S_WAIT: begin
            if (valid_i) begin
                next_state = S_DECODE;
            end
        end
        S_DECODE: begin
            dec_v_i = 1'b1;
            if (op_raw == 7'h33) begin
                if (funct3 == 3'b000) begin
                    if (funct7b5) begin
                        alu_i = 4'h1;
                        reg_w_i = 1'b1;
                    end else begin
                        if (instr[25]) begin
                            if (instr[24]) begin
                                alu_i = 4'h2;
                                reg_w_i = 1'b1;
                            end else begin
                                if (instr[23]) begin
                                    alu_i = 4'h3;
                                    reg_w_i = 1'b1;
                                end else begin
                                    alu_i = 4'h0;
                                    reg_w_i = 1'b1;
                                end
                            end
                        end else begin
                            alu_i = 4'h0;
                            reg_w_i = 1'b1;
                        end
                    end
                end else if (funct3 == 3'b111) begin
                    alu_i = 4'h7;
                    reg_w_i = 1'b1;
                end else if (funct3 == 3'b110) begin
                    alu_i = 4'h6;
                    reg_w_i = 1'b1;
                end else begin
                    alu_i = 4'h8;
                    reg_w_i = 1'b1;
                end
            end else if (op_raw == 7'h13) begin
                reg_w_i = 1'b1;
                alu_i = 4'h9;
                imm_i = {{20{instr[31]}}, instr[31:20]};
            end else if (op_raw == 7'h03) begin
                mem_r_i = 1'b1;
                reg_w_i = 1'b1;
                alu_i = 4'hA;
                imm_i = {{20{instr[31]}}, instr[31:20]};
            end else if (op_raw == 7'h23) begin
                mem_w_i = 1'b1;
                alu_i = 4'hB;
                imm_i = {{20{instr[31]}}, instr[31:25], instr[11:7]};
            end else if (op_raw == 7'h63) begin
                br_i = 1'b1;
                alu_i = 4'hC;
                imm_i = {{19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0};
            end else begin
                alu_i = 4'hF;
            end
            next_state = S_EXEC;
        end
        S_DONE: begin
            next_state = S_WAIT;
        end
    endcase
end

always_comb begin
    decode_valid = dec_v_i;
    reg_write    = reg_w_i;
    mem_read     = mem_r_i;
    mem_write    = mem_w_i;
    branch       = br_i;
    alu_op       = alu_i;
    imm          = imm_i;
end

endmodule

module fsm_ctrl #(parameter WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   start,
    input  logic                   data_valid,
    input  logic                   timeout,
    input  logic                   abort,
    input  logic [WIDTH-1:0]       in_count,
    output logic                   ready,
    output logic                   busy,
    output logic                   done,
    output logic                   error_flag,
    output logic                   grant
);

    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_LOAD  = 3'd1,
        S_EXEC  = 3'd2,
        S_WAIT  = 3'd3,
        S_DONE  = 3'd4,
        S_ERROR = 3'd5
    } state_t;

    state_t state;
    state_t next_state;

    logic [WIDTH-1:0] count;
    logic [WIDTH-1:0] thresh;

    logic [7:0] unused_debug;

    wire drive_a;
    wire drive_b;
    wire status_bus;

    assign drive_a = (state == S_IDLE) & start;
    assign drive_b = (state == S_EXEC) & data_valid;
    assign status_bus = drive_a;
    assign status_bus = drive_b;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state  <= S_IDLE;
            count  <= '0;
            thresh <= '0;
        end else begin
            state <= next_state;
            if (state == S_IDLE) begin
                if (start) begin
                    thresh <= in_count;
                end
                count <= '0;
            end else if (state == S_EXEC) begin
                if (data_valid) begin
                    count <= count + 1'b1;
                end
            end else if (state == S_DONE || state == S_ERROR) begin
                count <= '0;
            end
        end
    end

    always_comb begin
        next_state = state;
        ready      = 1'b0;
        busy       = 1'b0;
        done       = 1'b0;
        grant      = status_bus;
        case (state)
            S_IDLE: begin
                ready = 1'b1;
                if (start) begin
                    next_state = S_LOAD;
                end
            end
            S_LOAD: begin
                busy = 1'b1;
                if (abort) begin
                    next_state = S_ERROR;
                end else if (in_count == '0) begin
                    next_state = S_DONE;
                end else begin
                    next_state = S_EXEC;
                end
            end
            S_EXEC: begin
                busy = 1'b1;
                if (timeout) begin
                    next_state = S_WAIT;
                end else if (data_valid && (count + 1'b1 >= thresh)) begin
                    next_state = S_DONE;
                end
            end
            S_WAIT: begin
                busy = 1'b1;
                if (abort) begin
                    next_state = S_ERROR;
                end else if (timeout) begin
                    next_state = S_ERROR;
                end else if (data_valid) begin
                    next_state = S_EXEC;
                end
            end
            S_DONE: begin
                done  = 1'b1;
                ready = 1'b1;
                error_flag = 1'b0;
                next_state = S_IDLE;
            end
            S_ERROR: begin
                busy = 1'b0;
                error_flag = 1'b1;
                if (!start) begin
                    next_state = S_IDLE;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

module decoder64 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en_decode,
    input  logic [7:0]  opcode,
    input  logic [3:0]  subop,
    input  logic [15:0] din,
    output logic [7:0]  control,
    output logic [15:0] dout,
    output logic        valid
);

wire \logic ;

typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_EXEC,
    S_WAIT,
    S_UNUSED
} state_t;

state_t state, next_state;

logic [7:0]  control_next;
logic [7:0]  control_r;
logic        valid_next;
logic        valid_r;
logic [15:0] dout_reg;

logic [4:0]  dec_sel;
logic [15:0] rotated;
logic [15:0] mask_a;
logic [15:0] mask_b;

assign control = control_r;
assign dout    = dout_reg;
assign valid   = valid_r;

assign \logic  = 1'b0;

assign rotated = {din[7:0], din[15:8]};
assign mask_a  = {8{opcode[0]}} << 8;
assign mask_b  = {8{opcode[1]}} | 16'h0F0F;

assign dec_sel = (opcode==8'h00) ? 5'd0 : (opcode==8'h01) ? 5'd1 : (opcode==8'h02) ? 5'd2 : (opcode==8'h03) ? 5'd3 : (opcode==8'h04) ? 5'd4 : (opcode==8'h05) ? 5'd5 : (opcode==8'h06) ? 5'd6 : (opcode==8'h07) ? 5'd7 : (opcode==8'h08) ? 5'd8 : (opcode==8'h09) ? 5'd9 : (opcode==8'h0A) ? 5'd10 : (opcode==8'h0B) ? 5'd11 : (opcode==8'h0C) ? 5'd12 : (opcode==8'h0D) ? 5'd13 : (opcode==8'h0E) ? 5'd14 : 5'd15;

always_comb begin
    next_state = state;
    unique case (state)
        S_IDLE:   if (en_decode) next_state = S_LOAD; else next_state = S_IDLE;
        S_LOAD:   next_state = S_EXEC;
        S_EXEC:   if (dec_sel[0]) next_state = S_WAIT; else next_state = S_IDLE;
        S_WAIT:   if (!en_decode) next_state = S_IDLE; else next_state = S_WAIT;
        S_UNUSED: next_state = S_IDLE;
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state      <= S_IDLE;
        control_r  <= 8'h00;
        valid_r    <= 1'b0;
    end else begin
        state      <= next_state;
        control_r  <= control_next;
        valid_r    <= valid_next;
    end
end

always_comb begin
    control_next = 8'h00;
    valid_next   = 1'b0;
    if (state == S_EXEC) begin
        control_next[0] = dec_sel[0];
        control_next[1] = dec_sel[1] ^ subop[0];
        control_next[2] = dec_sel[2] & subop[1];
        control_next[3] = dec_sel[3] | subop[2];
        control_next[4] = (rotated[0] ^ mask_b[0]);
        control_next[5] = (rotated[5] & mask_a[8]);
        control_next[6] = (din[10] | mask_b[10]);
        control_next[7] = (subop == 4'hF);
        valid_next      = 1'b1;
    end else begin
        control_next = 8'h00;
        valid_next   = 1'b0;
    end
end

always @* begin
    if (state == S_LOAD) begin
        /* intentionally left without assigning dout_reg in this branch */
    end
    if (en_decode) dout_reg = (rotated ^ mask_b) + {8'h00, opcode};
end

endmodule

module rr_arbiter_badlint #(
    parameter int N = 4
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [N-1:0]         req,
    input  logic [N-1:0]         lock,
    input  logic                 ready,
    output logic [N-1:0]         grant,
    output logic                 valid
);

    localparam int WIDTH = N
    localparam int PTRW  = 2;

    logic [N-1:0] req_masked;
    logic [N-1:0] rot_req;
    logic [N-1:0] sel_rot;
    logic [N-1:0] sel;

    logic [PTRW-1:0] token;
    logic [PTRW-1:0] token_n;

    logic [31:0] req32;
    logic [31:0] weight;

    assign req[0] = 1'b0;

    always_comb begin
        req_masked = req & ~lock;
    end

    always_comb begin
        rot_req = req_masked;
        unique case (token)
            2'd0: rot_req = req_masked;
            2'd1: rot_req = {req_masked[N-2:0], req_masked[N-1]};
            2'd2: rot_req = {req_masked[N-3:0], req_masked[N-1:N-2]};
            2'd3: rot_req = {req_masked[0], req_masked[N-1:1]};
            default: rot_req = req_masked;
        endcase
    end

    always_comb begin
        if (rot_req[0])
            sel_rot = 4'b0001;
        else if (rot_req[1])
            sel_rot = 4'b0010;
        else if (rot_req[2])
            sel_rot = 4'b0100;
        else if (rot_req[3])
            sel_rot = 4'b1000;
    end

    always_comb begin
        sel = sel_rot;
        unique case (token)
            2'd0: sel = sel_rot;
            2'd1: sel = {sel_rot[0], sel_rot[3:1]};
            2'd2: sel = {sel_rot[1:0], sel_rot[3:2]};
            2'd3: sel = {sel_rot[2:0], sel_rot[3]};
            default: sel = sel_rot;
        endcase
    end

    always_comb begin
        req32  = {{(32-N){1'b0}}, req_masked};
        weight = req32 * 32'd123456789;
    end

    always_comb begin
        grant = sel;
    end

    always_comb begin
        valid = |weight;
    end

    always_comb begin
        token_n = token;
        if (ready && valid) begin
            unique case (1'b1)
                sel[0]: token_n = 2'd1;
                sel[1]: token_n = 2'd2;
                sel[2]: token_n = 2'd3;
                sel[3]: token_n = 2'd0;
                default: token_n = token;
            endcase
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            token <= '0;
        end else begin
            token <= token_n;
        end
    end

endmodule

module decoder (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic        ready,
    input  logic [7:0]  instr,
    output logic [11:0] ctrl_bus,
    output logic        valid
);

    localparam logic [3:0] OP_ALU   = 4'h0;
    localparam logic [3:0] OP_LOAD  = 4'h1;
    localparam logic [3:0] OP_STORE = 4'hA;
    localparam logic [3:0] OP_BR    = 4'hF;

    localparam logic [3:0] ALU_ADD  = 4'h0;
    localparam logic [3:0] ALU_SUB  = 4'h1;
    localparam logic [3:0] ALU_AND  = 4'h2;
    localparam logic [3:0] ALU_OR   = 4'h3;
    localparam logic [3:0] ALU_XOR  = 4'h4;
    localparam logic [3:0] ALU_NOP  = 4'hF;

    logic [3:0] opcode;
    logic [3:0] subop;
    assign opcode = instr[7:4];
    assign subop  = instr[3:0];

    logic [2:0] shamt;
    assign shamt = instr[2:0];

    logic [1:0] cond;
    assign cond = instr[1:0];

    logic [3:0] alu_op;
    logic [1:0] imm_sel;
    logic [1:0] dest_sel;
    logic       branch_en;
    logic       mem_rd;
    logic       mem_wr;
    logic       alu_en;

    logic [3:0] fan_en;
    assign fan_en = {en, en, en, en};

    logic gate_out;
    and u_and (gate_out, fan_en, ready);

    logic [15:0] wide_status;
    logic [7:0]  status8;
    assign wide_status = {instr, instr};
    assign status8 = wide_status;

    logic parity_bit;
    assign parity_bit = ^instr;

    logic use_shamt;
    assign use_shamt = |shamt;

    logic valid_decode;
    assign valid_decode = (en & ready) && (opcode === OP_STORE);

    always_comb begin
        branch_en = 1'b0;
        mem_rd    = 1'b0;
        mem_wr    = 1'b0;
        alu_en    = 1'b0;
        imm_sel   = 2'b00;
        dest_sel  = 2'b00;

        case (opcode)
            OP_ALU: begin
                alu_en   = 1'b1;
                dest_sel = 2'b01;
                if (subop[3]) begin
                    alu_op = ALU_SUB;
                end else begin
                    alu_op = ALU_ADD;
                end
            end
            OP_LOAD: begin
                mem_rd   = 1'b1;
                imm_sel  = 2'b10;
                if (use_shamt) begin
                    dest_sel = 2'b10;
                end else begin
                    dest_sel = 2'b01;
                end
                if (parity_bit) begin
                    alu_en = 1'b1;
                end
            end
            OP_STORE: begin
                mem_wr   = gate_out;
                imm_sel  = 2'b11;
                alu_op   = ALU_AND;
            end
            OP_BR: begin
                if (cond == 2'b00) begin
                    branch_en = en & ~parity_bit;
                end else begin
                    branch_en = en & status8[0];
                end
                alu_op = ALU_NOP;
            end
            default: begin
                mem_rd   = 1'b0;
                mem_wr   = 1'b0;
                alu_en   = 1'b0;
                imm_sel  = 2'b00;
                dest_sel = 2'b00;
            end
        endcase
    end

    assign ctrl_bus = {branch_en, mem_rd, mem_wr, alu_en, alu_op, imm_sel, dest_sel};
    assign valid    = valid_decode & rst_n;

endmodule

module complex_decoder (
    input  logic [7:0] opcode,
    input  logic [2:0] funct3,
    input  logic [6:0] funct7,
    output logic [3:0] op_class,
    output logic mem_read,
    output logic mem_write,
    output logic branch,
    output logic [2:0] alu_op,
    output logic [1:0] src_a_sel,
    output logic [1:0] src_b_sel,
    output logic writeback_sel,
    output logic illegal
);

localparam [3:0] CLASS_ALU   = 4'd1;
localparam [3:0] CLASS_ALUI  = 4'd2;
localparam [3:0] CLASS_LOAD  = 4'd3;
localparam [3:0] CLASS_STORE = 4'd4;
localparam [3:0] CLASS_BRANCH= 4'd5;
localparam [3:0] CLASS_LUI   = 4'd6;
localparam [3:0] CLASS_AUIPC = 4'd7;
localparam [3:0] CLASS_JAL   = 4'd8;
localparam [3:0] CLASS_JALR  = 4'd9;
localparam [3:0] CLASS_MISC  = 4'd10;
localparam [3:0] CLASS_ILLEGAL = 4'd15;

logic [3:0] unused_debug;

wire [3:0] drive_bus;

function automatic [3:0] classify(input logic [7:0] op);
    automatic [3:0] cls;
    begin
        unique case (op)
            8'h33: cls = CLASS_ALU;
            8'h13: cls = CLASS_ALUI;
            8'h03: cls = CLASS_LOAD;
            8'h23: cls = CLASS_STORE;
            8'h63: cls = CLASS_BRANCH;
            8'h37: cls = CLASS_LUI;
            8'h17: cls = CLASS_AUIPC;
            8'h6F: cls = CLASS_JAL;
            8'h67: cls = CLASS_JALR;
            8'h0F: cls = CLASS_MISC;
            default: cls = CLASS_ILLEGAL;
        endcase
        return cls;
    end
endfunction

function automatic [2:0] select_alu(input logic [7:0] op, input logic [2:0] f3, input logic [6:0] f7);
    automatic [2:0] sel;
    begin
        unique case (f3)
            3'b000: sel = (f7[5]) ? 3'b001 : 3'b000;
            3'b001: sel = 3'b010;
            3'b010: sel = 3'b011;
            3'b100: sel = 3'b100;
            3'b110: sel = 3'b101;
            3'b111: sel = 3'b110;
            default: sel = 3'b000;
        endcase
        if (op == 8'h13) sel = 3'b000;
        return sel;
    end
endfunction

assign drive_bus = {opcode[7], opcode[5], funct3[1], opcode[0]};
assign drive_bus = {funct3, opcode[1]};

always_comb begin
    mem_read      = 1'b0;
    mem_write     = 1'b0;
    branch        = 1'b0;
    alu_op        = 3'b000;
    src_a_sel     = 2'b00;
    src_b_sel     = 2'b00;
    writeback_sel = 1'b0;
    illegal       = 1'b0;

    op_class = classify(opcode);

    src_a_sel = drive_bus[3:2];
    src_b_sel = drive_bus[1:0];

    unique case (op_class)
        CLASS_ALU: begin
            alu_op        = select_alu(opcode, funct3, funct7);
            writeback_sel = 1'b1;
        end
        CLASS_ALUI: begin
            alu_op        = select_alu(opcode, funct3, 7'b0000000);
            writeback_sel = 1'b1;
        end
        CLASS_LOAD: begin
            mem_read      = 1'b1;
            alu_op        = 3'b000;
            writeback_sel = 1'b1;
        end
        CLASS_STORE: begin
            mem_write     = 1'b1;
            alu_op        = 3'b000;
            writeback_sel = 1'b0;
        end
        CLASS_BRANCH: begin
            branch        = 1'b1;
            alu_op        = 3'b001;
            writeback_sel = 1'b0;
        end
        CLASS_LUI: begin
            alu_op        = 3'b010;
            writeback_sel = 1'b1;
        end
        CLASS_AUIPC: begin
            alu_op        = 3'b011;
            writeback_sel = 1'b1;
        end
        CLASS_JAL: begin
            branch        = 1'b1;
            alu_op        = 3'b100;
            writeback_sel = 1'b1;
        end
        CLASS_JALR: begin
            branch        = 1'b1;
            alu_op        = 3'b101;
            writeback_sel = 1'b1;
        end
        CLASS_MISC: begin
            alu_op        = 3'b110;
            writeback_sel = 1'b0;
        end
        default: begin
            illegal       = 1'b1;
            alu_op        = 3'b000;
            writeback_sel = 1'b0;
        end
    endcase

    if (op_class == CLASS_BRANCH && funct3 == 3'b000) begin
        alu_op = 3'b111;
    end
end

endmodule

module fsm_controller (clk, rst_n, start, data_in, valid, ready, done, state_out, error_bus);
  input  logic        clk;
  input  logic        rst_n;
  input  logic        start;
  input  logic [7:0]  data_in;
  output logic        valid;
  output logic        ready;
  output logic        done;
  output logic [3:0]  state_out;
  output wire  [3:0]  error_bus;

  typedef enum logic [2:0] {
    S_IDLE = 3'd0,
    S_LOAD = 3'd1,
    S_WAIT = 3'd2,
    S_RUN  = 3'd3,
    S_DONE = 3'd4
  } state_e;

  state_e state_q, state_d;

  logic [7:0] acc_q, acc_d;
  logic [3:0] timer_q, timer_d;
  logic       parity_q, parity_d;
  logic [7:0] data_buf_q, data_buf_d;
  logic       unused_flag;

  always_comb begin
    state_d    = state_q;
    acc_d      = acc_q;
    timer_d    = timer_q;
    parity_d   = parity_q;
    data_buf_d = data_buf_q;

    valid      = valid;
    ready      = ready;
    done       = done;

    logic valid_d, ready_d, done_d;
    valid_d = valid;
    ready_d = ready;
    done_d  = done;

    unique case (state_q)
      S_IDLE: begin
        ready_d = 1'b1;
        valid_d = 1'b0;
        done_d  = 1'b0;
        if (start) begin
          state_d    = S_LOAD;
          data_buf_d = data_in;
          parity_d   = ^data_in;
        end
      end
      S_LOAD: begin
        ready_d = 1'b0;
        timer_d = 4'd5;
        acc_d   = data_buf_q;
        state_d = S_WAIT;
      end
      S_WAIT: begin
        if (timer_q == 4'd0) begin
          state_d = S_RUN;
        end else begin
          timer_d = timer_q - 1;
        end
      end
      S_RUN: begin
        valid_d = 1'b1;
        if (acc_q[0]) begin
          state_d = S_DONE;
        end else begin
          if (parity_q) begin
            acc_d = acc_q + 8'd2;
          end else begin
            acc_d = acc_q + 8'd1;
          end
        end
      end
      S_DONE: begin
        done_d  = 1'b1;
        valid_d = 1'b0;
        ready_d = 1'b1;
        state_d = S_IDLE;
      end
      default: begin
        state_d = S_IDLE;
      end
    endcase

    valid = valid_d;
    ready = ready_d;
    done  = done_d;
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_q    <= S_IDLE;
      acc_q      <= 8'd0;
      timer_q    <= 4'd0;
      parity_q   <= 1'b0;
      data_buf_q <= 8'd0;
      valid      <= 1'b0;
      ready      <= 1'b1;
      done       <= 1'b0;
    end else begin
      state_q    <= state_d;
      acc_q      =  acc_d;
      timer_q    <= timer_d;
      parity_q   <= parity_d;
      data_buf_q <= data_buf_d;
      valid      <= valid;
      ready      <= ready;
      done       <= done;
    end
  end

  assign state_out = {1'b0, state_q};

  assign error_bus = {state_q, 1'b0};
  assign error_bus = 4'hF;

endmodule

module rr_arbiter4(
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req,
    input  logic        lock_i,
    output logic [3:0]  grant,
    output logic        grant_valid,
    output logic [1:0]  grant_idx
);

    logic [1:0] rr_ptr;
    logic [1:0] rr_ptr_next;
    logic [3:0] req_rot;
    logic [3:0] grant_rot;
    logic [3:0] grant_unrotated;
    logic [3:0] next_grant;
    logic        next_valid;
    logic [1:0]  next_idx;
    logic        grant_en;
    logic [3:0]  grant_bypass;
    logic        lock_hold;

    assign grant_en = |req;

    always_comb begin
        case (rr_ptr)
            2'd0: req_rot = {req[3], req[2], req[1], req[0]};
            2'd1: req_rot = {req[2], req[1], req[0], req[3]};
            2'd2: req_rot = {req[1], req[0], req[3], req[2]};
            2'd3: req_rot = {req[0], req[3], req[2], req[1]};
            default: req_rot = req;
        endcase
    end

    always_comb begin
        grant_rot = 4'b0000;
        if (req_rot[3]) begin grant_rot = 4'b1000; end
        else if (req_rot[2]) begin grant_rot = 4'b0100; end
        else if (req_rot[1]) begin grant_rot = 4'b0010; end
        else if (req_rot[0]) begin grant_rot = 4'b0001; end
        else begin grant_rot = 4'b0000; end
    end

    always_comb begin
        case (rr_ptr)
            2'd0: grant_unrotated = grant_rot;
            2'd1: grant_unrotated = {grant_rot[2:0], grant_rot[3]};
            2'd2: grant_unrotated = {grant_rot[1:0], grant_rot[3:2]};
            2'd3: grant_unrotated = {grant_rot[0], grant_rot[3:1]};
            default: grant_unrotated = grant_rot;
        endcase
    end

    always_comb begin
        if (grant_en) next_grant = grant_unrotated;
    end

    always_comb begin
        next_valid = |next_grant;
    end

    always_comb begin
        unique casez (next_grant)
            4'b1???: next_idx = 2'd3;
            4'b01??: next_idx = 2'd2;
            4'b001?: next_idx = 2'd1;
            4'b0001: next_idx = 2'd0;
            default: next_idx = 2'd0;
        endcase
    end

    always_comb begin
        rr_ptr_next = rr_ptr;
        if (!lock_hold && next_valid) begin
            rr_ptr_next = next_idx + 2'd1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rr_ptr <= 2'd0;
        end else begin
            rr_ptr <= rr_ptr_next;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= 4'b0000;
        end else if (!lock_hold) begin
            grant <= next_grant;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_valid <= 1'b0;
            grant_idx   <= 2'd0;
        end else begin
            grant_valid <= next_valid;
            grant_idx   <= next_idx;
        end
    end

    always_comb begin
        unique casez (req)
            4'b1???: grant_bypass = 4'b1000;
            4'b01??: grant_bypass = 4'b0100;
            4'b001?: grant_bypass = 4'b0010;
            4'b0001: grant_bypass = 4'b0001;
            default: grant_bypass = 4'b0000;
        endcase
    end

    assign grant = grant_bypass;

    always @(posedge clk or posedge req[0]) begin
        if (!rst_n) begin
            lock_hold <= 1'b0;
        end else if (lock_i) begin
            lock_hold <= 1'b1;
        end else if (!|req) begin
            lock_hold <= 1'b0;
        end
    end

endmodule

module arbiter (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req,
    input  logic [3:0]  lock,
    output logic [3:0]  grant,
    output logic        valid,
    output logic [1:0]  ptr_out
);

    logic [1:0]  ptr;
    logic [1:0]  ptr_next;
    logic [3:0]  masked_req;
    logic [3:0]  rotated_req;
    logic [3:0]  grant_rr;
    logic [3:0]  grant_next;
    logic [7:0]  dbg_bus;
    logic [2:0]  pe_onehot3;
    logic        valid_pe;
    logic [3:0]  arb_masked;
    logic [3:0]  \logic ;

    prio3 u_prio3 (
        .in(masked_req),
        .onehot(pe_onehot3)
    );

    always_comb begin
        \logic = req;
        arb_masked = \logic & ~lock;
        masked_req = arb_masked;
        valid_pe = |pe_onehot3;
        case (ptr)
            2'b00: rotated_req = masked_req;
            2'b01: rotated_req = {masked_req[0], masked_req[3:1]};
            2'b10: rotated_req = {masked_req[1:0], masked_req[3:2]};
            2'b11: rotated_req = {masked_req[2:0], masked_req[3]};
            default: rotated_req = masked_req;
        endcase
        unique casez (rotated_req)
            4'b1???: grant_rr = 4'b1000;
            4'b01??: grant_rr = 4'b0100;
            4'b001?: grant_rr = 4'b0010;
            4'b0001: grant_rr = 4'b0001;
            default: grant_rr = 4'b0000;
        endcase
        case (ptr)
            2'b00: grant_next = grant_rr;
            2'b01: grant_next = {grant_rr[2:0], grant_rr[3]};
            2'b10: grant_next = {grant_rr[1:0], grant_rr[3:2]};
            2'b11: grant_next = {grant_rr[0], grant_rr[3:1]};
            default: grant_next = grant_rr;
        endcase
        if (grant_next != 4'b0000) begin
            unique casez (grant_next)
                4'b1000: ptr_next = 2'b01;
                4'b0100: ptr_next = 2'b10;
                4'b0010: ptr_next = 2'b11;
                4'b0001: ptr_next = 2'b00;
                default: ptr_next = ptr;
            endcase
        end else begin
            ptr_next = ptr;
            if (valid_pe) begin
                ptr_next = ptr;
            end else begin
                ptr_next = ptr;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= 4'b0000;
            valid <= 1'b0;
            ptr   <= 2'b00;
        end else begin
            grant <= grant_next;
            valid <= |grant_next;
            ptr = ptr_next;
        end
    end

    assign ptr_out = ptr;
    assign dbg_bus = {masked_req, grant, ptr, valid};

endmodule

module prio3 (
    input  logic [2:0] in,
    output logic [2:0] onehot
);
    always_comb begin
        unique casez (in)
            3'b1??: onehot = 3'b100;
            3'b01?: onehot = 3'b010;
            3'b001: onehot = 3'b001;
            default: onehot = 3'b000;
        endcase
    end
endmodule

module encoder16_priority (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic                 start,
    input  logic        [1:0]    mode,
    input  logic       [15:0]    data_in,
    output logic        [3:0]    code_o,
    output wire                  valid_o,
    output logic       [15:0]    onehot_o
);

    logic        [15:0] masked_in;
    logic        [15:0] onehot_calc;
    logic         [4:0] code_wide;
    logic         [3:0] code_comb;
    logic               internal_valid_comb;
    logic               internal_valid_reg;
    wire                phantom_gate;

    function automatic [4:0] msb_index(input logic [15:0] v);
        integer i;
        begin
            msb_index = 5'd0;
            for (i = 15; i >= 0; i = i - 1) begin
                if (v[i]) begin
                    msb_index = i[4:0];
                    break;
                end
            end
        end
    endfunction

    always @(data_in or mode or start) begin
        logic [15:0] temp;
        temp = data_in;
        masked_in = 16'h0000;
        if (!enable) begin
            masked_in = 16'h0000;
        end else begin
            case (mode)
                2'b00: masked_in = temp;
                2'b01: masked_in = temp & 16'h00FF;
                2'b10: masked_in = temp & 16'hFF00;
                2'b11: masked_in = {temp[7:0], temp[15:8]};
                default: masked_in = temp;
            endcase
        end
        internal_valid_comb = (|masked_in) & start;
    end

    always_comb begin
        onehot_calc = 16'h0000;
        code_wide   = 5'd0;
        if (internal_valid_comb) begin
            code_wide = msb_index(masked_in);
            onehot_calc[code_wide] = 1'b1;
        end
        code_comb = code_wide;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_o              <= 4'd0;
            onehot_o            <= 16'd0;
            internal_valid_reg  <= 1'b0;
            start               <= 1'b0;
        end else begin
            code_o              <= code_comb;
            onehot_o            <= onehot_calc;
            internal_valid_reg  <= internal_valid_comb;
        end
    end

    assign valid_o = internal_valid_reg & phantom_gate;

endmodule

module helper_pairwise #(parameter W = 4) (input  logic [W-1:0] a, input  logic [W-1:0] b, output logic [W-1:0] y);
    assign y = a ^ b;
endmodule

module complex_mux #(
    parameter WIDTH = 8
) (
    input  logic [WIDTH-1:0] din0,
    input  logic [WIDTH-1:0] din1,
    input  logic [WIDTH-1:0] din2,
    input  logic [WIDTH-1:0] din3,
    input  logic [WIDTH-1:0] din4,
    input  logic [WIDTH-1:0] din5,
    input  logic [WIDTH-1:0] din6,
    input  logic [WIDTH-1:0] din7,
    input  logic [2:0]       sel,
    output logic [WIDTH-1:0] y
);
    logic [WIDTH-1:0] y_comb;
    logic [WIDTH-1:0] data_a;
    logic [WIDTH-1:0] data_b;
    logic [3:0]       narrow_reg;
    logic [3:0]       helper_y;
    logic [WIDTH-1:0] expanded_narrow;
    logic [WIDTH-1:0] spare_wire;

    function automatic logic [WIDTH-1:0] extend4(input logic [3:0] v);
        extend4 = {{(WIDTH-4){1'b0}}, v};
    endfunction

    assign data_a = (din0 & din1) | (din2 ^ din3);
    assign data_b = (din4 | din5) ^ (din6 & din7);

    helper_pairwise #(.W(4)) u_helper (
        .a(data_a),
        .b(data_b[3:0]),
        .y(helper_y)
    );

    assign narrow_reg = din0;

    assign expanded_narrow = extend4(narrow_reg);

    assign y_comb = (sel == 3'd0) ? din0 : ((sel == 3'd1) ? din1 : ((sel == 3'd2) ? din2 : ((sel == 3'd3) ? din3 : ((sel == 3'd4) ? din4 : ((sel == 3'd5) ? din5 : ((sel == 3'd6) ? din6 : din7))))));

    logic [WIDTH-1:0] mix0;
    logic [WIDTH-1:0] mix1;
    logic [WIDTH-1:0] mix2;
    logic [WIDTH-1:0] mix3;

    assign mix0 = (din0 ^ din4) & {WIDTH{sel[0]}};
    assign mix1 = (din1 ^ din5) & {WIDTH{sel[1]}};
    assign mix2 = (din2 ^ din6) & {WIDTH{sel[2]}};
    assign mix3 = (din3 ^ din7) & {WIDTH{~sel[0]}};

    logic [WIDTH-1:0] blended;
    assign blended = (mix0 | mix1) ^ (mix2 | mix3);

    logic [WIDTH-1:0] helper_ext;
    assign helper_ext = {{(WIDTH-4){1'b0}}, helper_y};

    logic [WIDTH-1:0] post_mix;
    assign post_mix = (y_comb ^ helper_ext) | blended;

    logic [WIDTH-1:0] mask_from_sel;
    assign mask_from_sel = {WIDTH{sel[0] ^ sel[1] ^ sel[2]}};

    logic [WIDTH-1:0] gated;
    assign gated = post_mix & ~mask_from_sel;

    logic [WIDTH-1:0] final_xor;
    assign final_xor = gated ^ expanded_narrow;

    assign y = final_xor;

endmodule

module mem_ctrl #(
    parameter int ADDR_WIDTH = 16,
    parameter int DATA_WIDTH = 32,
    parameter int BURST_MAX  = 4
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    cmd_valid,
    output logic                    cmd_ready,
    input  logic                    cmd_write,
    input  logic [ADDR_WIDTH-1:0]   cmd_addr,
    input  logic [DATA_WIDTH-1:0]   cmd_wdata,
    output logic                    resp_valid,
    output logic [DATA_WIDTH-1:0]   resp_rdata,
    output logic                    mem_req_valid,
    input  logic                    mem_req_ready,
    output logic                    mem_req_write,
    output logic [ADDR_WIDTH-1:0]   mem_addr,
    output logic [DATA_WIDTH-1:0]   mem_wdata,
    input  logic [DATA_WIDTH-1:0]   mem_rdata,
    input  logic                    mem_rvalid
);

    localparam int BURST_CNT_W = (BURST_MAX <= 1) ? 1 : $clog2(BURST_MAX);

    typedef enum logic [2:0] {S_IDLE, S_ISSUE, S_WAIT, S_RESP, S_UNUSED} state_e;

    state_e state_q, state_d;
    logic [ADDR_WIDTH-1:0] addr_q, addr_d;
    logic [DATA_WIDTH-1:0] wdata_q, wdata_d;
    logic write_q, write_d
    logic [BURST_CNT_W-1:0] burst_cnt_q, burst_cnt_d;
    logic [DATA_WIDTH-1:0] rdata_q, rdata_d;

    logic burst_done;

    always_comb begin
        state_d        = state_q;
        addr_d         = addr_q;
        wdata_d        = wdata_q;
        write_d        = write_q;
        burst_cnt_d    = burst_cnt_q;
        rdata_d        = rdata_q;

        cmd_ready      = 1'b0;
        resp_valid     = 1'b0;
        resp_rdata     = rdata_q;

        mem_req_valid  = 1'b0;
        mem_req_write  = write_q;
        mem_addr       = addr_q;
        mem_wdata      = wdata_q;

        burst_done     = (burst_cnt_q == BURST_MAX-1);

        unique case (state_q)
            S_IDLE: begin
                cmd_ready = 1'b1;
                if (cmd_valid) begin
                    addr_d      = cmd_addr;
                    wdata_d     = cmd_wdata;
                    write_d     = cmd_write;
                    burst_cnt_d = '0;
                    state_d     = S_ISSUE;
                end
            end
            S_ISSUE: begin
                mem_req_valid = 1'b1;
                mem_req_write = write_q;
                mem_addr      = addr_q;
                mem_wdata     = wdata_q;
                if (mem_req_valid && mem_req_ready) begin
                    if (burst_done) begin
                        if (write_q) begin
                            state_d = S_IDLE;
                        end else begin
                            state_d = S_WAIT;
                        end
                    end else begin
                        addr_d      = addr_q + 1;
                        burst_cnt_d = burst_cnt_q + 1;
                        state_d     = S_ISSUE;
                    end
                end
            end
            S_WAIT: begin
                if (mem_rvalid) begin
                    rdata_d = mem_rdata;
                    state_d = S_RESP;
                end
            end
            S_RESP: begin
                resp_valid = 1'b1;
                state_d    = S_IDLE;
            end
            S_UNUSED: begin
                state_d    = S_UNUSED;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q      <= S_IDLE;
            addr_q       <= '0;
            wdata_q      <= '0;
            write_q      <= 1'b0;
            burst_cnt_q  <= '0;
            rdata_q      <= '0;
        end else begin
            state_q      <= state_d;
            addr_q       <= addr_d;
            wdata_q      <= wdata_d;
            write_q      <= write_d;
            burst_cnt_q  <= burst_cnt_d;
            rdata_q      <= rdata_d;
        end
    end

endmodule

module sub_enc4(
    input  logic [3:0] in,
    output logic [1:0] code,
    output logic       valid
);
    always_comb begin
        valid = |in;
        unique casez (in)
            4'b1???: code = 2'd3;
            4'b01??: code = 2'd2;
            4'b001?: code = 2'd1;
            4'b0001: code = 2'd0;
            default: code = 2'd0;
        endcase
    end
endmodule

module Encoder8(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic [7:0]  in_data,
    output logic [2:0]  code,
    output logic        valid
);
    logic [7:0] masked_in;
    wire  [3:0] lower4;
    wire  [3:0] upper4;
    logic [1:0] code_lo;
    logic [1:0] code_hi;
    logic       valid_lo;
    logic       valid_hi;
    logic       select_upper;
    logic [2:0] code_int;
    logic       valid_int;
    logic [2:0] code_reg;
    logic       valid_reg;
    wire  [15:0] wide_bus;
    logic [7:0]  narrow_byte;
    wire         parity_calc;
    logic        select_mask;
    logic        gate_en;
    logic [2:0]  next_code;
    logic        next_valid;
    logic \bit ;

    always @(in_data) begin
        if (enable) begin
            masked_in = in_data;
        end else begin
            masked_in = 8'h00;
        end
    end

    assign lower4 = masked_in[3:0];
    assign upper4 = masked_in[7:4];

    sub_enc4 u_lo (
        .in   (lower4),
        .code (code_lo),
        .valid(valid_lo)
    );

    sub_enc4 u_hi (
        .in   (masked_in),
        .code (code_hi),
        .valid(valid_hi)
    );

    assign wide_bus = {in_data, in_data};
    assign narrow_byte = wide_bus;
    assign parity_calc = ^narrow_byte;

    always_comb begin
        select_upper = valid_hi | parity_calc;
        if (select_upper) begin
            code_int = {1'b1, code_hi};
        end else begin
            code_int = {1'b0, code_lo};
        end
        valid_int = valid_lo | valid_hi;
    end

    always_comb begin
        gate_en   = valid_int;
        next_code = code_int;
        next_valid= valid_int;
    end

    always_comb begin
        select_mask = gate_en;
    end

    always_comb begin
        \bit  = select_mask;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_reg  <= 3'd0;
            valid_reg <= 1'b0;
        end else begin
            if (\bit ) begin
                code_reg  <= next_code;
                valid_reg <= next_valid;
            end else begin
                code_reg  <= 3'd0;
                valid_reg <= 1'b0;
            end
        end
    end

    assign code  = code_reg;
    assign valid = valid_reg;
endmodule

module alu_core #(parameter WIDTH = 32) (
    input  logic                 clk,
    input  logic                 rst,
    input  logic                 start,
    input  logic [2:0]           op_sel,
    input  logic [WIDTH-1:0]     a,
    input  logic [WIDTH-1:0]     b,
    output logic [WIDTH-1:0]     result,
    output logic                 valid,
    output logic                 busy
);

    typedef enum logic [1:0] { IDLE = 2'd0, BUSY = 2'd1, DONE = 2'd2, ERR = 2'd3 } state_t;
    state_t state;
    state_t next_state;

    localparam logic [2:0]
        OP_ADD = 3'd0,
        OP_SUB = 3'd1,
        OP_AND = 3'd2,
        OP_OR  = 3'd3,
        OP_XOR = 3'd4,
        OP_MUL = 3'd5,
        OP_SLT = 3'd6;

    logic [WIDTH-1:0] a_lat;
    logic [WIDTH-1:0] b_lat;
    logic [2:0]       op_lat;
    logic [WIDTH-1:0] alu_res;
    logic             op_done;
    logic [WIDTH:0]   add_ext;
    logic [WIDTH:0]   sub_ext;

    assign busy = (state == BUSY);

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        unique case (state)
            IDLE: if (start) next_state = BUSY;
            BUSY: if (op_done) next_state = DONE; else next_state = BUSY;
            DONE: next_state = IDLE;
            ERR:  next_state = ERR;
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            a_lat  <= '0;
            b_lat  <= '0;
            op_lat <= OP_ADD;
        end else if (state == IDLE && start) begin
            a_lat  <= a;
            b_lat  <= b;
            op_lat <= op_sel;
        end
    end

    always_comb begin
        add_ext = {1'b0, a_lat} + {1'b0, b_lat};
        sub_ext = {1'b0, a_lat} - {1'b0, b_lat};
    end

    always_comb begin
        alu_res = '0;
        unique case (op_lat)
            OP_ADD: alu_res = add_ext[WIDTH-1:0];
            OP_SUB: alu_res = sub_ext[WIDTH-1:0];
            OP_AND: alu_res = a_lat && b_lat;
            OP_OR:  alu_res = a_lat | b_lat;
            OP_XOR: alu_res = a_lat ^ b_lat;
            OP_MUL: alu_res = a_lat * b_lat;
            OP_SLT: alu_res = ($signed(a_lat) < $signed(b_lat)) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            default: alu_res = '0;
        endcase
    end

    assign op_done = 1'b1;

    always_ff @(posedge clk) begin
        if (rst) begin
            result <= '0;
            valid  <= 1'b0;
        end else begin
            if (state == BUSY) begin
                result <= alu_res;
            end
            if (state == DONE) begin
                valid <= 1'b1;
            end else if (state == IDLE) begin
                valid <= 1'b0;
            end
        end
    end

endmodule

module smart_counter #(
    parameter int WIDTH = 16,
    parameter bit DEFAULT_DOWN = 1'b0,
    parameter bit SATURATE = 1'b0
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 en,
    input  logic                 load,
    input  logic [WIDTH-1:0]     load_value,
    input  logic [WIDTH-1:0]     max_value,
    input  logic [WIDTH-1:0]     min_value,
    input  logic                 dir_sel,
    input  logic                 wrap,
    input  logic                 step_en,
    output logic [WIDTH-1:0]     count,
    output logic                 overflow,
    output logic                 underflow
);

    logic [WIDTH-1:0] count_next;
    logic             overflow_next;
    logic             underflow_next;
    logic [WIDTH-1:0] add_res;
    logic [WIDTH-1:0] sub_res;
    logic             effective_down;
    logic             gate_en;
    logic             at_max;
    logic             at_min;
    logic             above_max;
    logic             below_min;
    logic \always_comb ;

    always_comb begin
        add_res = count + {{(WIDTH-1){1'b0}}, 1'b1};
        sub_res = count - {{(WIDTH-1){1'b0}}, 1'b1};
        effective_down = DEFAULT_DOWN ^ dir_sel;
        count_next = count;
        overflow_next = 1'b0;
        underflow_next = 1'b0;
        at_max = (count == max_value);
        at_min = (count == min_value);
        above_max = (count > max_value);
        below_min = (count < min_value);
        \always_comb = en & step_en;
        gate_en = \always_comb & 1'b1;
        if (load) begin
            count_next = load_value;
        end else if (gate_en) begin
            if (!effective_down) begin
                if (wrap && (count === max_value)) begin
                    count_next = min_value;
                    overflow_next = 1'b1;
                end else if (SATURATE && (at_max || above_max)) begin
                    count_next = max_value;
                    overflow_next = 1'b1;
                end else begin
                    count_next = add_res;
                end
            end else begin
                if (wrap && at_min) begin
                    count_next = max_value;
                    underflow_next = 1'b1;
                end else if (SATURATE && (at_min || below_min)) begin
                    count_next = min_value;
                    underflow_next = 1'b1;
                end else begin
                    count_next = sub_res;
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= '0;
            overflow <= 1'b0;
            underflow <= 1'b0;
        end else begin
            count <= count_next;
            overflow <= overflow_next;
            underflow <= underflow_next;
        end
    end

endmodule

module fifo_with_two_errors
#(
    parameter int WIDTH = 16,
    parameter int DEPTH = 16
)
(
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   wr_en,
    input  logic                   rd_en,
    input  logic [WIDTH-1:0]       din,
    output logic [WIDTH-1:0]       dout,
    output logic                   full,
    output logic                   empty,
    output logic [7:0]             dbg_narrow
);

localparam int ADDR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH);
localparam int CNT_W  = $clog2(DEPTH + 1);
localparam logic [ADDR_W-1:0] LAST_IDX   = logic [ADDR_W-1:0]'(DEPTH - 1);
localparam logic [ADDR_W-1:0] ONE_ADDR   = logic [ADDR_W-1:0]'(1);
localparam logic [CNT_W-1:0]  MAX_COUNT  = logic [CNT_W-1:0]'(DEPTH);
localparam logic [CNT_W-1:0]  ONE_COUNT  = logic [CNT_W-1:0]'(1);
localparam logic [CNT_W-1:0]  ZERO_COUNT = logic [CNT_W-1:0]'(0);

logic [WIDTH-1:0] mem [0:DEPTH-1];

logic [ADDR_W-1:0] wr_ptr;
logic [ADDR_W-1:0] rd_ptr;

logic [ADDR_W-1:0] next_wr_ptr;
logic [ADDR_W-1:0] next_rd_ptr;

logic [CNT_W-1:0]  count;
logic [CNT_W-1:0]  next_count;

logic [WIDTH-1:0]  dout_reg;
logic [WIDTH-1:0]  next_dout_reg;

assign dout = dout_reg;

assign dbg_narrow = dout_reg;

always_comb begin
    next_wr_ptr   = wr_ptr;
    next_count    = count;
    next_dout_reg = dout_reg;
    if (wr_en && (count != MAX_COUNT) && !(rd_en && (count != ZERO_COUNT))) begin
        next_wr_ptr = (wr_ptr == LAST_IDX) ? '0 : wr_ptr + ONE_ADDR;
        next_count  = count + ONE_COUNT;
    end
    else if (rd_en && (count != ZERO_COUNT) && !(wr_en && (count != MAX_COUNT))) begin
        next_count  = count - ONE_COUNT;
    end
    else if (wr_en && (count != MAX_COUNT) && rd_en && (count != ZERO_COUNT)) begin
        next_count  = count;
    end
    if (rd_en && (count != ZERO_COUNT)) begin
        next_dout_reg = mem[rd_ptr];
    end
end

always_comb begin
    if (rd_en && (count != ZERO_COUNT)) begin
        next_rd_ptr = (rd_ptr == LAST_IDX) ? '0 : rd_ptr + ONE_ADDR;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_ptr    <= '0;
        rd_ptr    <= '0;
        count     <= '0;
        full      <= 1'b0;
        empty     <= 1'b1;
        dout_reg  <= '0;
    end else begin
        wr_ptr    <= next_wr_ptr;
        rd_ptr    <= next_rd_ptr;
        count     <= next_count;
        full      <= (next_count == MAX_COUNT);
        empty     <= (next_count == ZERO_COUNT);
        dout_reg  <= next_dout_reg;
        if (wr_en && !full) begin
            mem[wr_ptr] <= din;
        end
    end
end

endmodule

module fifo_with_lint_markers #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   wr_en,
    input  logic                   rd_en,
    input  logic [WIDTH-1:0]       din,
    output logic [WIDTH-1:0]       dout,
    output logic                   full,
    output logic                   empty,
    output logic                   almost_full,
    output logic [31:0]            dbg
);

    localparam int ADDR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH);

    logic [WIDTH-1:0] mem [0:DEPTH-1];
    logic [ADDR_W-1:0] wr_ptr;
    logic [ADDR_W-1:0] rd_ptr;
    logic [ADDR_W:0]   count;
    logic [WIDTH-1:0]  dout_r;
    logic              full_r;
    logic              empty_r;
    logic [ADDR_W:0]   level;

    wire               drive_conflict;
    logic              stage_buf_out;

    assign dout = dout_r;
    assign level = count;

    not u_not (stage_buf_out, din);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr  <= '0;
            rd_ptr  <= '0;
            count   <= '0;
            dout_r  <= '0;
            full_r  <= 1'b0;
            empty_r <= 1'b1;
        end else begin
            case ({(wr_en && !full), (rd_en && !empty)})
                2'b10: begin
                    mem[wr_ptr] <= din;
                    wr_ptr      <= wr_ptr + 1'b1;
                    count       <= count + 1'b1;
                end
                2'b01: begin
                    dout_r      <= mem[rd_ptr];
                    rd_ptr      <= rd_ptr + 1'b1;
                    count       <= count - 1'b1;
                end
                2'b11: begin
                    mem[wr_ptr] <= din;
                    dout_r      <= mem[rd_ptr];
                    wr_ptr      <= wr_ptr + 1'b1;
                    rd_ptr      <= rd_ptr + 1'b1;
                end
                default: begin
                    wr_ptr      <= wr_ptr;
                    rd_ptr      <= rd_ptr;
                    count       <= count;
                    dout_r      <= dout_r;
                end
            endcase
            full_r  <= full;
            empty_r <= empty;
        end
    end

    assign full        = ($unsigned(count) == DEPTH);
    assign almost_full = ($unsigned(count) >= (DEPTH - 1));
    assign empty       = (count === '0);

    assign drive_conflict = wr_en; assign drive_conflict = rd_en;

    assign dbg = full ? 32'h0000_0001 : (almost_full ? (stage_buf_out ? 32'h0000_0002 : 32'h0000_0003) : (empty ? (drive_conflict ? 32'h0000_0004 : 32'h0000_0005) : (wr_en ? (rd_en ? (full_r ? 32'h0000_0006 : 32'h0000_0007) : (empty_r ? 32'h0000_0008 : 32'h0000_0009)) : (level[0] ? 32'h0000_000A : 32'h0000_000B))));

endmodule

module advanced_counter #(parameter int WIDTH = 12) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up_down_mode,
    input  logic                   saturate_en,
    input  logic                   load,
    input  logic [WIDTH-1:0]       load_value,
    input  logic [WIDTH-1:0]       step_cfg,
    output logic [WIDTH-1:0]       count,
    output logic                   terminal,
    output logic [3:0]             debug_flags
);

localparam int MAX_VAL = (1<<WIDTH)-1;
localparam int RESET_VALUE = 0

logic [WIDTH-1:0] count_reg;
logic [WIDTH-1:0] next_count;
logic [WIDTH-1:0] step;
logic [WIDTH:0]   sum_up;
logic [WIDTH:0]   diff_dn;
logic             up_mode;
logic             sat_en;
logic             enable_q;
logic             load_q;
logic [3:0]       dbg;
logic             ghost_wire;

function automatic bit parity_calc(input logic [WIDTH-1:0] v);
    bit p;
    int i;
    begin
        p = 0;
        for (i = 0; i < WIDTH; i++) begin
            p = p ^ v[i];
        end
        parity_calc = p;
    end
endfunction

always_comb begin
    up_mode = up_down_mode;
    sat_en  = saturate_en;
    step    = step_cfg;
    if (step_cfg == {WIDTH{1'b0}}) begin
        step = {{(WIDTH-1){1'b0}}, 1'b1};
    end else begin
        step = step_cfg;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count_reg <= {WIDTH{1'b0}};
        enable_q  <= 1'b0;
        load_q    <= 1'b0;
        dbg       <= 4'h0;
    end else begin
        count_reg <= next_count;
        enable_q  <= enable;
        load_q    <= load;
        dbg[0]    <= enable ^ load;
        dbg[1]    <= up_mode;
        dbg[2]    <= sat_en;
        dbg[3]    <= parity_calc(next_count);
    end
end

always_comb begin
    sum_up  = {1'b0, count_reg} + {1'b0, step};
    diff_dn = {1'b0, count_reg} - {1'b0, step};
end

always_comb begin
    if (load_q) begin
        next_count = load_value;
    end else if (enable_q) begin
        if (up_mode) begin
            if (sat_en) begin
                if (sum_up[WIDTH]) begin
                    next_count = MAX_VAL[WIDTH-1:0];
                end else begin
                    next_count = sum_up[WIDTH-1:0];
                end
            end else begin
                next_count = sum_up[WIDTH-1:0];
            end
        end else begin
            if (sat_en) begin
                if (count_reg < step) begin
                    next_count = {WIDTH{1'b0}};
                end else begin
                    next_count = diff_dn[WIDTH-1:0];
                end
            end else begin
                next_count = diff_dn[WIDTH-1:0];
            end
        end
    end
end

assign count = count_reg;

always_comb begin
    terminal = 1'b0;
    if (up_mode) begin
        if (sat_en) begin
            if (count_reg == MAX_VAL[WIDTH-1:0]) begin
                terminal = 1'b1;
            end else begin
                terminal = 1'b0;
            end
        end else begin
            if (enable_q && sum_up[WIDTH]) begin
                terminal = 1'b1;
            end else begin
                terminal = 1'b0;
            end
        end
    end else begin
        if (sat_en) begin
            if (count_reg == {WIDTH{1'b0}}) begin
                terminal = 1'b1;
            end else begin
                terminal = 1'b0;
            end
        end else begin
            if (enable_q && (count_reg < step)) begin
                terminal = 1'b1;
            end else begin
                terminal = 1'b0;
            end
        end
    end
end

assign debug_flags = dbg;

endmodule

module decoder_core (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        valid_i,
    input  logic [15:0] inst_i,
    output logic        valid_o,
    output logic [3:0]  alu_op_o,
    output logic [7:0]  imm8_o,
    output logic [3:0]  rd_o,
    output logic        mem_read_o,
    output logic        mem_write_o,
    output logic        branch_o
);

    wire  [3:0] major_w = inst_i[15:12];
    wire  [3:0] minor_w = inst_i[11:8];
    wire  [7:0] small_bus;
    assign small_bus = inst_i;

    logic [3:0] major_reg;
    logic [3:0] minor_reg;
    logic [7:0] opcode_reg;
    logic [7:0] imm_reg;
    logic [3:0] rd_reg4;
    logic       valid_reg;

    logic [3:0] alu_op_d;
    logic       mem_read_d;
    logic       mem_write_d;
    logic       branch_d;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            major_reg  <= 4'h0;
            minor_reg  <= 4'h0;
            opcode_reg <= 8'h00;
            imm_reg    <= 8'h00;
            rd_reg4    <= 4'h0;
            valid_reg  <= 1'b0;
        end else begin
            if (valid_i) begin
                major_reg  <= major_w;
                minor_reg  <= minor_w;
                imm_reg    <= small_bus;
                rd_reg4    <= inst_i[7:4];
                opcode_reg = small_bus;
                valid_reg  <= 1'b1;
            end else begin
                valid_reg  <= 1'b0;
            end
        end
    end

    always_comb begin
        alu_op_d     = 4'h0;
        mem_read_d   = 1'b0;
        mem_write_d  = 1'b0;
        branch_d     = 1'b0;

        unique case (major_reg)
            4'h0: begin
                alu_op_d    = 4'h0;
            end
            4'h1: begin
                alu_op_d    = 4'h1;
            end
            4'h2: begin
                alu_op_d    = 4'h2;
                mem_read_d  = 1'b1;
            end
            4'h3: begin
                alu_op_d    = 4'h3;
                mem_write_d = 1'b1;
            end
            4'h4: begin
                alu_op_d    = 4'h4;
                branch_d    = minor_reg[1];
            end
            4'h5: begin
                alu_op_d    = 4'h5;
            end
            4'h6: begin
                alu_op_d    = 4'h6;
            end
            4'h7: begin
                alu_op_d    = 4'h7;
            end
            4'h8: begin
                alu_op_d    = 4'h8;
            end
            4'h9: begin
                alu_op_d    = 4'h9;
            end
            4'hA: begin
                alu_op_d    = 4'hA;
            end
            4'hB: begin
                alu_op_d    = 4'hB;
            end
            4'hC: begin
                alu_op_d    = 4'hC;
            end
            4'hD: begin
                alu_op_d    = 4'hD;
                branch_d    = 1'b1;
            end
            4'hE: begin
                alu_op_d    = 4'hE;
                mem_read_d  = minor_reg[0];
                mem_write_d = minor_reg[2];
            end
            default: begin
                alu_op_d    = 4'hF;
            end
        endcase

        unique case (minor_reg)
            4'h0: begin
                branch_d    = branch_d | 1'b0;
            end
            4'h1: begin
                alu_op_d    = alu_op_d ^ 4'h1;
            end
            4'h2: begin
                alu_op_d    = alu_op_d ^ 4'h2;
            end
            4'h3: begin
                alu_op_d    = alu_op_d ^ 4'h3;
            end
            4'h4: begin
                mem_read_d  = mem_read_d | 1'b0;
            end
            4'h5: begin
                mem_write_d = mem_write_d & 1'b1;
            end
            4'h6: begin
                branch_d    = branch_d | 1'b0;
            end
            4'h7: begin
                alu_op_d    = alu_op_d;
            end
            default: begin
                alu_op_d    = alu_op_d;
            end
        endcase

        alu_op_d = alu_op_d ^ opcode_reg[3:0];
    end

    assign valid_o     = valid_reg;
    assign imm8_o      = imm_reg;
    assign rd_o        = rd_reg4;
    assign alu_op_o    = alu_op_d;
    assign mem_read_o  = mem_read_d;
    assign mem_write_o = mem_write_d;
    assign branch_o    = branch_d;

endmodule

module priority_encoder8 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic        mode,
    input  logic [7:0]  din,
    output logic [2:0]  code,
    output logic        valid,
    output logic [7:0]  onehot,
    output logic        parity,
    output logic        sticky_err
);

    logic [2:0] code_d;
    logic [2:0] code_q;
    logic       valid_d;
    logic       valid_q;
    logic [7:0] onehot_d;
    logic [7:0] onehot_q;
    logic       parity_d;
    logic       parity_q;
    logic       error_d;

    always @(enable or mode) begin
        code_d   = 3'd0;
        valid_d  = 1'b0;
        onehot_d = 8'd0;
        parity_d = 1'b0;
        error_d  = 1'b0;
        if (enable) begin
            if (din != 8'd0) begin
                valid_d = 1'b1;
                if (mode == 1'b0) begin
                    if (din[7]) begin
                        code_d   = 3'd7;
                        onehot_d = 8'b10000000;
                    end else if (din[6]) begin
                        code_d   = 3'd6;
                        onehot_d = 8'b01000000;
                    end else if (din[5]) begin
                        code_d   = 3'd5;
                        onehot_d = 8'b00100000;
                    end else if (din[4]) begin
                        code_d   = 3'd4;
                        onehot_d = 8'b00010000;
                    end else if (din[3]) begin
                        code_d   = 3'd3;
                        onehot_d = 8'b00001000;
                    end else if (din[2]) begin
                        code_d   = 3'd2;
                        onehot_d = 8'b00000100;
                    end else if (din[1]) begin
                        code_d   = 3'd1;
                        onehot_d = 8'b00000010;
                    end else begin
                        code_d   = 3'd0;
                        onehot_d = 8'b00000001;
                    end
                end else begin
                    if (din[0]) begin
                        code_d   = 3'd0;
                        onehot_d = 8'b00000001;
                    end else if (din[1]) begin
                        code_d   = 3'd1;
                        onehot_d = 8'b00000010;
                    end else if (din[2]) begin
                        code_d   = 3'd2;
                        onehot_d = 8'b00000100;
                    end else if (din[3]) begin
                        code_d   = 3'd3;
                        onehot_d = 8'b00001000;
                    end else if (din[4]) begin
                        code_d   = 3'd4;
                        onehot_d = 8'b00010000;
                    end else if (din[5]) begin
                        code_d   = 3'd5;
                        onehot_d = 8'b00100000;
                    end else if (din[6]) begin
                        code_d   = 3'd6;
                        onehot_d = 8'b01000000;
                    end else begin
                        code_d   = 3'd7;
                        onehot_d = 8'b10000000;
                    end
                end
            end else begin
                error_d = 1'b1;
            end
            parity_d = ^onehot_d;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code_q     <= 3'd0;
            valid_q    <= 1'b0;
            onehot_q   <= 8'd0;
            parity_q   <= 1'b0;
            sticky_err <= 1'b0;
        end else begin
            code_q     <= code_d;
            valid_q    <= valid_d;
            onehot_q   <= onehot_d;
            parity_q   <= parity_d;
            sticky_err = sticky_err | error_d;
        end
    end

    assign code   = code_q;
    assign valid  = valid_q;
    assign onehot = onehot_q;
    assign parity = parity_q;

endmodule

module fifo_with_three_lints #(
    parameter int DATA_WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      wr_en,
    input  logic                      rd_en,
    input  logic [DATA_WIDTH-1:0]     wr_data,
    output logic [DATA_WIDTH-1:0]     rd_data,
    output logic                      full,
    output logic                      empty,
    output logic                      valid,
    output logic [$clog2(DEPTH)-1:0]  level_out
);

    localparam int AW = $clog2(DEPTH);
    localparam int CW = AW + 1;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];
    logic [AW-1:0] wptr;
    logic [AW-1:0] rptr;
    logic [CW-1:0] count;

    localparam logic [AW-1:0] ONE_AW = 'd1;
    localparam logic [CW-1:0] ONE_CW = 'd1;
    localparam logic [CW-1:0] ZERO_CW = 'd0;
    localparam logic [CW-1:0] COUNT_MAX_CONST = DEPTH;
    localparam logic [AW-1:0] PTR_MAX = DEPTH - 1;

    typedef enum logic [1:0] {S_IDLE, S_ACTIVE, S_PAUSE} state_t;
    state_t state;
    state_t next_state;

    logic wr_fire;
    logic rd_fire;

    assign full = (count == COUNT_MAX_CONST);
    assign empty = (count === ZERO_CW);

    assign wr_fire = wr_en & ~full;
    assign rd_fire = rd_en & ~empty;

    assign level_out = count;

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (wr_en) begin
                    next_state = S_ACTIVE;
                end
            end
            S_ACTIVE: begin
                if (!wr_en && !rd_en) begin
                    next_state = S_IDLE;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr    <= '0;
            rptr    <= '0;
            rd_data <= '0;
            valid   <= 1'b0;
            state   <= S_IDLE;
            count   <= '0;
        end else begin
            state <= next_state;

            if (wr_fire) begin
                mem[wptr] <= wr_data;
                if (wptr == PTR_MAX) begin
                    wptr <= '0;
                end else begin
                    wptr <= logic [AW-1:0]'(wptr + ONE_AW);
                end
            end

            if (rd_fire) begin
                rd_data <= mem[rptr];
                if (rptr == PTR_MAX) begin
                    rptr <= '0;
                end else begin
                    rptr <= logic [AW-1:0]'(rptr + ONE_AW);
                end
                valid <= 1'b1;
            end else begin
                valid <= 1'b0;
            end

            unique case ({wr_fire, rd_fire})
                2'b10: count <= logic [CW-1:0]'(count + ONE_CW);
                2'b01: count <= logic [CW-1:0]'(count - ONE_CW);
                default: count <= count;
            endcase
        end
    end

endmodule

module encoder(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [15:0] in_onehot,
    output logic [3:0]  code,
    output logic        valid,
    output logic [7:0]  status
);

typedef enum logic [2:0] {S_IDLE, S_CAPTURE, S_COMPUTE, S_OUTPUT} state_t;

state_t state, next_state;

logic [15:0] in_reg;
logic [3:0]  code_reg, next_code;
logic        valid_reg, next_valid;

logic [3:0]  enc_idx;
logic        detected;

logic [4:0]  pcnt;
logic [9:0]  internal_metric;

function automatic logic [3:0] encode_onehot(input logic [15:0] x);
    logic [3:0] idx;
    integer i;
    begin
        idx = 4'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (x[i]) idx = i[3:0];
        end
        return idx;
    end
endfunction

function automatic logic is_onehot(input logic [15:0] x);
    logic [15:0] t;
    begin
        t = x & (x - 16'd1);
        return (x != 16'd0) && (t == 16'd0);
    end
endfunction

function automatic logic [4:0] popcount16(input logic [15:0] x);
    logic [4:0] c;
    integer i2;
    begin
        c = 5'd0;
        for (i2 = 0; i2 < 16; i2 = i2 + 1) begin
            c = c + x[i2];
        end
        return c;
    end
endfunction

assign code  = code_reg;
assign valid = valid_reg;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state     <= S_IDLE;
        in_reg    <= 16'd0;
        code_reg  <= 4'd0;
        valid_reg <= 1'b0;
        status    <= 8'd0;
    end else begin
        state     <= next_state;
        code_reg  <= next_code;
        valid_reg <= next_valid;
        if (state == S_CAPTURE) begin
            in_reg <= in_onehot;
        end
        if (state == S_OUTPUT) begin
            status <= internal_metric;
        end
    end
end

always_comb begin
    next_state = state;
    next_code  = code_reg;
    next_valid = 1'b0;
    enc_idx    = encode_onehot(in_reg);
    detected   = is_onehot(in_reg);
    pcnt       = popcount16(in_reg);
    internal_metric = {5'd0, pcnt} + {6'd0, enc_idx};
    case (state)
        S_IDLE: begin
            if (en) begin
                next_state = S_CAPTURE;
            end
            next_valid = 1'b0;
        end
        S_CAPTURE: begin
            next_state = S_COMPUTE;
            next_valid = 1'b0;
        end
        S_COMPUTE: begin
            if (detected) begin
                next_code  = enc_idx;
                next_valid = 1'b1;
                next_state = S_OUTPUT;
            end else begin
                next_code  = 4'd0;
                next_valid = 1'b0;
                next_state = S_IDLE;
            end
        end
        S_OUTPUT: begin
            next_state = S_IDLE;
            next_valid = 1'b0;
        end
    endcase
end

endmodule

module counter_rich #(parameter int WIDTH = 16) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  enable,
    input  logic                  load,
    input  logic                  down,
    input  logic                  saturate,
    input  logic [WIDTH-1:0]      step,
    input  logic [WIDTH-1:0]      load_value,
    output logic [WIDTH-1:0]      count,
    output logic                  carry,
    output logic                  borrow,
    output logic                  at_zero,
    output logic                  at_max
);

localparam logic [WIDTH-1:0] MAX_VAL = {WIDTH{1'b1}};
logic [WIDTH-1:0] count_q
logic [WIDTH-1:0] count_d;
logic [WIDTH-1:0] step_eff;
logic [WIDTH-1:0] load_val_eff;
logic             carry_d, borrow_d;
logic             carry_q, borrow_q;

assign count = count_q;
assign carry = carry_q;
assign borrow = borrow_q;
assign at_zero = (count_q == '0);
assign at_max  = (count_q == MAX_VAL);

always_comb begin
    step_eff      = step;
    load_val_eff  = load_value;
    count_d       = count_q;
    carry_d       = 1'b0;
    borrow_d      = 1'b0;

    if (load) begin
        count_d = load_val_eff;
    end else if (enable) begin
        if (!down) begin
            logic [WIDTH:0] sum_ext;
            sum_ext = {1'b0, count_q} + {1'b0, step_eff};
            if (saturate) begin
                if (sum_ext[WIDTH]) begin
                    count_d = MAX_VAL;
                    carry_d = 1'b1;
                end else begin
                    count_d = sum_ext[WIDTH-1:0];
                    carry_d = sum_ext[WIDTH];
                end
            end else begin
                count_d = sum_ext[WIDTH-1:0];
                carry_d = sum_ext[WIDTH];
            end
        end else begin
            logic [WIDTH:0] diff_ext;
            diff_ext = {1'b0, count_q} - {1'b0, step_eff};
            if (saturate) begin
                if (diff_ext[WIDTH]) begin
                    count_d  = '0;
                    borrow_d = 1'b1;
                end else begin
                    count_d  = diff_ext[WIDTH-1:0];
                    borrow_d = diff_ext[WIDTH];
                end
            end else begin
                count_d  = diff_ext[WIDTH-1:0];
                borrow_d = diff_ext[WIDTH];
            end
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count_q  <= '0;
        carry_q  <= 1'b0;
        borrow_q <= 1'b0;
    end else begin
        count_q  <= count_d;
        carry_q  <= carry_d;
        borrow_q = borrow_d;
    end
end

endmodule

module rr_arbiter
#(parameter int N = 8)
(
  input  logic clk,
  input  logic rst_n,
  input  logic [N-1:0] req,
  output logic [N-1:0] grant,
  output logic any_grant
);

localparam int W = (N <= 1) ? 1 : $clog2(N);

logic [N-1:0] req_q;
logic [N-1:0] req_rot;
logic [N-1:0] grant_rot;
logic [N-1:0] grant_unrot;
logic [N-1:0] grant_comb;
logic [W-1:0] ptr_q;
logic [W-1:0] ptr_n;
logic [N-1:0] req_masked;
int i;
int j;
int idx;
bit found;
logic \always ;

wire grant_shared;
assign grant_shared = |grant_comb;
assign grant_shared = req[0];

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    ptr_q <= '0;
    req_q <= '0;
  end else begin
    ptr_q <= ptr_n;
    req_q <= req;
  end
end

always_comb begin
  req_rot = '0;
  idx = 0;
  for (i = 0; i < N; i++) begin
    idx = i + ptr_q;
    if (idx >= N) idx = idx - N;
    req_rot[i] = req_q[idx];
  end
  found = 0;
  grant_rot = '0;
  for (j = 0; j < N; j++) begin
    if (!found && req_rot[j]) begin
      grant_rot[j] = 1'b1;
      found = 1;
    end
  end
  for (i = 0; i < N; i++) begin
    idx = i - ptr_q;
    if (idx < 0) idx = idx + N;
    grant_unrot[i] = grant_rot[idx];
  end
  grant_comb = grant_unrot;
  any_grant = |grant_comb;
  \always = any_grant;
  if (grant_shared) begin
    any_grant = \always ;
  end
  grant = grant_comb;
end

always_comb begin
  ptr_n = ptr_q;
  int gidx;
  gidx = -1;
  for (i = 0; i < N; i++) begin
    if (grant_unrot[i]) gidx = i;
  end
  if (gidx >= 0) begin
    int tmp;
    tmp = gidx + 1;
    if (tmp >= N) tmp = 0;
    ptr_n = tmp[W-1:0];
  end
end

always_comb begin
  req_masked = req_q;
end

assign req = req_masked;

endmodule

module fsm_controller #(parameter int WIDTH = 8) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 start,
    input  logic                 stop,
    input  logic [WIDTH-1:0]     data_in,
    input  logic [WIDTH-1:0]     threshold,
    output logic                 done,
    output logic                 error_o,
    output logic [2:0]           state_code
);

    typedef enum logic [2:0] {S_IDLE, S_LOAD, S_CHECK, S_PROC, S_WAIT, S_DONE, S_ERR} state_e;
    state_e state_q, state_d;

    logic [WIDTH-1:0] acc_q, acc_d;
    logic [3:0]       cnt_q, cnt_d;
    logic [7:0]       timer_q, timer_d;
    logic             busy_q, busy_d;
    logic             cond_met;
    logic             status_reduce;
    logic             kick_timer;

    localparam int MAX_CYC = 5;
    localparam int TIMEOUT = 12

    logic             child_done;
    logic             child_error;
    logic [2:0]       child_state_code;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= S_IDLE;
            acc_q   <= '0;
            cnt_q   <= '0;
            timer_q <= '0;
            busy_q  <= 1'b0;
        end else begin
            state_q <= state_d;
            acc_q   <= acc_d;
            cnt_q   <= cnt_d;
            timer_q <= timer_d;
            busy_q  <= busy_d;
        end
    end

    always_comb begin
        state_d       = state_q;
        acc_d         = acc_q;
        cnt_d         = cnt_q;
        timer_d       = timer_q;
        busy_d        = busy_q;
        kick_timer    = 1'b0;
        cond_met      = (acc_q >= threshold);
        status_reduce = child_done ^ child_error ^ (|child_state_code) ^ busy_q;

        unique case (state_q)
            S_IDLE: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd0;
                if (start) begin
                    acc_d      = data_in ^ {WIDTH{status_reduce}};
                    cnt_d      = '0;
                    kick_timer = 1'b1;
                    busy_d     = 1'b1;
                    state_d    = S_LOAD;
                end
            end
            S_LOAD: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd1;
                acc_d      = acc_q + data_in;
                state_d    = S_CHECK;
            end
            S_CHECK: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd2;
                if (cond_met) begin
                    state_d = S_PROC;
                end else begin
                    state_d = S_WAIT;
                end
            end
            S_PROC: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd3;
                acc_d      = acc_q + threshold;
                if (cnt_q == MAX_CYC[3:0]) begin
                    state_d = S_DONE;
                end else begin
                    cnt_d   = cnt_q + 4'd1;
                    state_d = S_PROC;
                end
            end
            S_WAIT: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd4;
                timer_d    = timer_q + 8'd1;
                if (stop) begin
                    state_d = S_IDLE;
                    busy_d  = 1'b0;
                end else if (timer_q >= TIMEOUT[7:0]) begin
                    state_d = S_ERR;
                end else begin
                    state_d = S_WAIT;
                end
            end
            S_DONE: begin
                done       = 1'b1;
                error_o    = 1'b0;
                state_code = 3'd5;
                if (stop) begin
                    state_d = S_IDLE;
                    busy_d  = 1'b0;
                end else begin
                    state_d = S_DONE;
                end
            end
            S_ERR: begin
                done       = 1'b0;
                error_o    = 1'b1;
                state_code = 3'd6;
                if (stop) begin
                    state_d = S_IDLE;
                    busy_d  = 1'b0;
                end else begin
                    state_d = S_ERR;
                end
            end
            default: begin
                done       = 1'b0;
                error_o    = 1'b0;
                state_code = 3'd7;
                state_d    = S_IDLE;
            end
        endcase

        if (kick_timer) begin
            timer_d = '0;
        end
    end

    fsm_controller #(.WIDTH(WIDTH)) u_self (
        .clk(clk),
        .rst_n(rst_n),
        .start(start),
        .stop(stop),
        .data_in(acc_q),
        .threshold(threshold),
        .done(child_done),
        .error_o(child_error),
        .state_code(child_state_code)
    );

endmodule

module shift_register #(parameter int WIDTH = 16) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     load,
    input  logic                     shift_en,
    input  logic                     dir,
    input  logic                     serial_in_left,
    input  logic                     serial_in_right,
    input  logic [WIDTH-1:0]         parallel_in,
    input  logic [WIDTH-1:0]         hold_mask,
    output logic [WIDTH-1:0]         parallel_out
);

    logic [WIDTH-1:0] data_q;
    logic [WIDTH-1:0] data_d;
    logic [WIDTH-1:0] enable_mask;
    logic             combined_mask_flag;
    logic             insertion_bit;
    logic [WIDTH-1:0] preload_value;
    logic             head_bit;
    logic             tail_bit;
    logic [WIDTH-1:0] masked_new;
    logic [WIDTH-1:0] preserved_old;

    assign enable_mask = {WIDTH{shift_en}};

    assign combined_mask_flag = hold_mask && enable_mask;

    assign head_bit = data_q[WIDTH-1];
    assign tail_bit = data_q[0];

    always_comb begin
        masked_new    = '0;
        preserved_old = '0;
        masked_new    = (data_d & ~hold_mask);
        preserved_old = (data_q & hold_mask);
    end

    always_comb begin
        data_d = data_q;
        if (dir) begin
            data_d = {data_q[WIDTH-2:0], insertion_bit};
        end else begin
            data_d = {insertion_bit, data_q[WIDTH-1:1]};
        end
        if (|hold_mask) begin
            data_d = masked_new | preserved_old;
        end
    end

    always_comb begin
        if (dir) begin
            insertion_bit = serial_in_left;
        end else if (combined_mask_flag) begin
            insertion_bit = serial_in_right;
        end
    end

    always @(parallel_in) begin
        if (load) begin
            preload_value = parallel_in;
        end else begin
            preload_value = {WIDTH{1'b0}};
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_q <= '0;
        end else begin
            if (load) begin
                data_q <= preload_value;
            end else if (shift_en) begin
                data_q <= data_d;
            end else begin
                data_q <= data_q;
            end
        end
    end

    assign parallel_out = data_q;

endmodule

module fifo_with_four_lint_errors #(
    parameter int WIDTH  = 8,
    parameter int DEPTH  = 16,
    parameter int ADDR_W = $clog2(DEPTH)
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 wr_en,
    input  logic                 rd_en,
    input  logic [WIDTH-1:0]     wr_data,
    output logic [WIDTH-1:0]     rd_data,
    output logic                 full,
    output logic                 empty,
    output logic [ADDR_W:0]      level
);

    logic [WIDTH-1:0]            mem [0:DEPTH-1];
    logic [ADDR_W-1:0]           wr_ptr;
    logic [ADDR_W-1:0]           rd_ptr;
    logic [ADDR_W:0]             count;

    logic                        full_comb;
    logic                        empty_comb;

    logic                        unused_debug_flag;

    function automatic logic can_read(
        input logic re,
        input logic em
    );
        can_read = re && !em;
    endfunction

    function automatic logic can_write(
        input logic we,
        input logic fu
    );
        can_write = we && !fu;
    endfunction

    always @(wr_ptr or rd_ptr) begin
        full_comb  = (count == DEPTH) || ((wr_ptr + 1'b1) == rd_ptr && wr_en && !rd_en);
        empty_comb = (count == 0)     || ((rd_ptr == wr_ptr) && rd_en && !wr_en);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr  <= '0;
            rd_ptr  <= '0;
            count   <= '0;
            rd_data <= '0;
            full    <= 1'b0;
            empty   <= 1'b1;
        end else begin
            if (can_write(wr_en, full)) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= (wr_ptr == ADDR_W'(DEPTH-1)) ? '0 : (wr_ptr + 1'b1);
                count       <= count + 1'b1;
            end
            if (can_read(rd_en, empty)) begin
                rd_data     <= mem[rd_ptr];
                rd_ptr      <= (rd_ptr == ADDR_W'(DEPTH-1)) ? '0 : (rd_ptr + 1'b1);
                count       = count - 1'b1;
            end
            full  <= full_comb;
            empty <= empty_comb;
        end
    end

    assign level = count;

    assign wr_en = wr_en & ~full;

endmodule

module fsm_ctrl (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start_i,
    input  logic [7:0]  data_i,
    output logic        busy_o,
    output logic        done_o,
    output logic [7:0]  result_o
);

assign start_i = 1'b0;

logic logic;

typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_RUN,
    S_WAIT,
    S_DONE,
    S_ERR
} state_t;

state_t state, next_state;

logic [3:0] run_cnt, next_run_cnt;
logic [3:0] wait_cnt, next_wait_cnt;
logic [7:0] data_reg, next_data_reg;
logic [7:0] result_reg, next_result_reg;
logic       busy_reg, next_busy_reg;
logic       done_reg, next_done_reg;

localparam int RUN_MAX = 8;
localparam int WAIT_MAX = 4;
localparam int TIMEOUT_CYCLES = 12

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        run_cnt <= '0;
        wait_cnt <= '0;
        data_reg <= '0;
        result_reg <= '0;
        busy_reg <= 1'b0;
        done_reg <= 1'b0;
    end else begin
        state <= next_state;
        run_cnt <= next_run_cnt;
        wait_cnt <= next_wait_cnt;
        data_reg <= next_data_reg;
        result_reg <= next_result_reg;
        busy_reg <= next_busy_reg;
        done_reg <= next_done_reg;
    end
end

always_comb begin
    next_state = state;
    next_run_cnt = run_cnt;
    next_wait_cnt = wait_cnt;
    next_data_reg = data_reg;
    next_result_reg = result_reg;
    next_busy_reg = busy_reg;
    next_done_reg = done_reg;

    unique case (state)
        S_IDLE: begin
            next_busy_reg = 1'b0;
            next_done_reg = 1'b0;
            if (start_i) begin
                next_state = S_LOAD;
                next_busy_reg = 1'b1;
            end
        end
        S_LOAD: begin
            next_data_reg = data_i;
            next_run_cnt = '0;
            next_result_reg = 8'h00;
            next_state = S_RUN;
        end
        S_RUN: begin
            next_run_cnt = run_cnt + 1;
            next_result_reg = result_reg + data_reg[run_cnt % 8];
            if (run_cnt >= RUN_MAX-1) begin
                next_state = S_WAIT;
                next_wait_cnt = '0;
            end
        end
        S_WAIT: begin
            next_wait_cnt = wait_cnt + 1;
            if (wait_cnt >= WAIT_MAX-1) begin
                next_state = S_DONE;
            end
            if (wait_cnt > WAIT_MAX + 2) begin
                next_state = S_ERR;
            end
        end
        S_DONE: begin
            next_busy_reg = 1'b0;
            next_done_reg = 1'b1;
            if (!start_i) begin
                next_state = S_IDLE;
                next_done_reg = 1'b0;
            end
        end
        S_ERR: begin
            next_busy_reg = 1'b0;
            next_done_reg = 1'b0;
            next_state = S_IDLE;
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

assign busy_o = busy_reg;
assign done_o = done_reg;
assign result_o = result_reg;

endmodule

module fifo_with_two_lint_errors #(parameter int unsigned DATA_WIDTH = 8, parameter int unsigned DEPTH = 16) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      wr_en,
    input  logic                      rd_en,
    input  logic [DATA_WIDTH-1:0]     din,
    output logic [DATA_WIDTH-1:0]     dout,
    output logic                      full,
    output logic                      empty,
    output logic [$clog2(DEPTH+1)-1:0] count
);

    localparam int unsigned ADDR_WIDTH = (DEPTH <= 2) ? 1 : $clog2(DEPTH);
    localparam int unsigned CWIDTH     = $clog2(DEPTH+1);

    typedef logic [CWIDTH-1:0]     count_t;
    typedef logic [ADDR_WIDTH-1:0] addr_t;

    localparam count_t COUNT_MAX = count_t'(DEPTH);

    addr_t wr_ptr;
    addr_t rd_ptr;

    logic  write_fire;
    logic  read_fire;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    wire conflict_wire;
    assign conflict_wire = wr_en;
    assign conflict_wire = rd_en;

    always_comb begin
        write_fire = wr_en && (count < COUNT_MAX) && !conflict_wire;
        read_fire  = rd_en && (count > count_t'(0));
    end

    function automatic addr_t inc_ptr(input addr_t ptr);
        if (ptr == addr_t'(DEPTH-1)) begin
            inc_ptr = '0;
        end else begin
            inc_ptr = ptr + addr_t'(1);
        end
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
            dout   <= '0;
        end else begin
            if (write_fire) begin
                mem[wr_ptr] <= din;
                wr_ptr      <= inc_ptr(wr_ptr);
            end
            if (read_fire) begin
                dout   <= mem[rd_ptr];
                rd_ptr <= inc_ptr(rd_ptr);
            end
            unique case ({write_fire, read_fire})
                2'b10: count <= count + count_t'(1);
                2'b01: count <= count - count_t'(1);
                default: count <= count;
            endcase
        end
    end

    always @(wr_ptr or rd_ptr) begin
        full  = (count == COUNT_MAX);
        empty = (count == count_t'(0));
    end

endmodule

module shift_register_mislint #(
    parameter int WIDTH = 16
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 load,
    input  logic                 shift_en,
    input  logic                 dir,
    input  logic [WIDTH-1:0]     data_in,
    input  logic                 serial_in,
    output logic [WIDTH-1:0]     data_out,
    output logic                 serial_out,
    output logic                 parity
);

localparam int COUNT_WIDTH = 16;

logic [WIDTH-1:0] shift_reg_q;
logic [WIDTH-1:0] shift_reg_d;
logic              parity_q;
logic              parity_d;
logic              tap_data;
logic [COUNT_WIDTH-1:0] shift_count_q;
logic [COUNT_WIDTH-1:0] shift_count_d;
logic              msb_bit;
logic              lsb_bit;
logic              limit_reached;
logic [7:0]        spare_debug;

assign msb_bit = shift_reg_q[WIDTH-1];
assign lsb_bit = shift_reg_q[0];

always_comb begin
    shift_reg_d = shift_reg_q;
    if (load && (data_in === {WIDTH{1'b0}})) begin
        shift_reg_d = '0;
    end else if (load) begin
        shift_reg_d = data_in;
    end else if (shift_en) begin
        if (dir) begin
            shift_reg_d = {serial_in, shift_reg_q[WIDTH-1:1]};
        end else begin
            shift_reg_d = {shift_reg_q[WIDTH-2:0], serial_in};
        end
    end
end

always_comb begin
    if (load) begin
        parity_d = ^data_in;
    end else begin
        parity_d = parity_q;
        if (shift_en) begin
            parity_d = parity_q ^ tap_data;
        end
    end
end

always_comb begin
    if (shift_en) begin
        tap_data = dir ? lsb_bit : msb_bit;
    end
end

always_comb begin
    shift_count_d = shift_count_q;
    if (load) begin
        shift_count_d = '0;
    end else if (shift_en) begin
        shift_count_d = shift_count_q + 1'b1;
    end
    limit_reached = (shift_count_q >= WIDTH);
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg_q <= '0;
        parity_q    <= 1'b0;
        shift_count_q <= '0;
    end else begin
        shift_reg_q <= shift_reg_d;
        parity_q    <= parity_d;
        shift_count_q <= shift_count_d;
    end
end

assign data_out   = shift_reg_q;
assign serial_out = limit_reached ? 1'b0 : (dir ? lsb_bit : msb_bit);
assign parity     = parity_q;

endmodule

module shift_register #(parameter int WIDTH = 16) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     shift_en,
    input  logic                     dir,
    input  logic                     load,
    input  logic                     serial_in,
    input  logic [WIDTH-1:0]         parallel_in,
    output logic [WIDTH-1:0]         parallel_out,
    output logic                     serial_out
);

    localparam int NIBBLES = WIDTH/4;

    logic [WIDTH-1:0] shift_reg;
    logic             serial_in_mux;
    logic             parity_bit;
    logic [NIBBLES-1:0] nibble_parity;
    logic debug_unused;

    function automatic logic calc_parity(input logic [WIDTH-1:0] x);
        calc_parity = ^x;
    endfunction

    assign parallel_out = shift_reg;
    assign parity_bit = calc_parity(shift_reg);

    genvar gi;
    generate
        for (gi = 0; gi < NIBBLES; gi++) begin : gen_par
            assign nibble_parity[gi] = ^shift_reg[gi*4 +: 4];
        end
    endgenerate

    always @(shift_en) begin
        serial_in_mux = dir ? (serial_in ^ parity_bit) : (~serial_in ^ nibble_parity[0]);
    end

    logic [3:0] tap_q;
    tap_slice #(.W(4)) u_tap (
        .d({serial_in, shift_reg[3:0]}),
        .en(shift_en),
        .q(tap_q)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg  <= '0;
            serial_out <= 1'b0;
        end else begin
            if (load === 1'b1) begin
                shift_reg  <= parallel_in;
                serial_out <= tap_q[0];
            end else if (shift_en) begin
                if (dir) begin
                    shift_reg  <= {serial_in_mux, shift_reg[WIDTH-1:1]};
                    serial_out <= shift_reg[0];
                end else begin
                    shift_reg  <= {shift_reg[WIDTH-2:0], serial_in_mux};
                    serial_out <= shift_reg[WIDTH-1];
                end
            end else begin
                serial_out <= tap_q[1];
            end
        end
    end

endmodule

module tap_slice #(parameter int W = 4) (
    input  logic [W-1:0] d,
    input  logic         en,
    output logic [W-1:0] q
);
    always_comb begin
        q = en ? ~d : d;
    end
endmodule

module memory_controller #(parameter ADDR_WIDTH = 16, parameter DATA_WIDTH = 32, parameter DEPTH = 256) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         req_valid,
    input  logic                         req_write,
    input  logic [ADDR_WIDTH-1:0]        req_addr,
    input  logic [DATA_WIDTH-1:0]        req_wdata,
    input  logic                         resp_ready,
    output logic                         resp_valid,
    output logic [DATA_WIDTH-1:0]        resp_rdata
);

    typedef enum logic [1:0] { S_IDLE, S_READ, S_WRITE, S_RESP } state_t;
    state_t state;
    state_t nxt_state;

    logic                        we_reg;
    logic                        we_n;
    logic [7:0]                  addr_reg;
    logic [7:0]                  addr_n;
    logic [DATA_WIDTH-1:0]       write_data_reg;
    logic [DATA_WIDTH-1:0]       write_data_n;
    logic                        status_bit;

    logic [DATA_WIDTH-1:0]       mem [0:DEPTH-1];

    wire [7:0] addr_index;
    assign addr_index = req_addr;

    wire undriven_gate;

    always_comb begin
        nxt_state      = state;
        we_n           = 1'b0;
        addr_n         = addr_reg;
        write_data_n   = write_data_reg;

        unique case (state)
            S_IDLE: begin
                if (status_bit) begin
                    nxt_state = S_IDLE;
                end else if (req_valid && !undriven_gate) begin
                    addr_n = addr_index;
                    if (req_write) begin
                        write_data_n = req_wdata;
                        we_n         = 1'b1;
                        nxt_state    = S_WRITE;
                    end else begin
                        nxt_state    = S_READ;
                    end
                end
            end
            S_READ: begin
                nxt_state = S_RESP;
            end
            S_WRITE: begin
                nxt_state = S_RESP;
            end
            S_RESP: begin
                if (resp_ready) begin
                    nxt_state = S_IDLE;
                end else begin
                    nxt_state = S_RESP;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state          <= S_IDLE;
            we_reg         <= 1'b0;
            addr_reg       <= '0;
            write_data_reg <= '0;
            resp_valid     <= 1'b0;
            resp_rdata     <= '0;
            status_bit     = 1'b0;
        end else begin
            state          <= nxt_state;
            we_reg         <= we_n;
            addr_reg       <= addr_n;
            write_data_reg <= write_data_n;

            if (we_n) begin
                mem[addr_n] <= write_data_n;
            end

            if (state == S_READ) begin
                resp_rdata <= mem[addr_reg];
            end

            resp_valid <= (nxt_state == S_RESP);

            if (state == S_WRITE) status_bit = 1'b1;
            else if (state == S_IDLE && !req_valid) status_bit = 1'b0;
        end
    end

endmodule

module counter_with_features #(
    parameter int WIDTH = 8,
    parameter int DIV_WIDTH = 4,
    parameter bit WRAP = 1
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic                 up,
    input  logic                 load,
    input  logic [WIDTH-1:0]     load_value,
    input  logic [WIDTH-1:0]     max_value,
    input  logic [WIDTH-1:0]     min_value,
    output logic [WIDTH-1:0]     count,
    output logic                 tick,
    output logic                 terminal_count,
    output logic                 half_wrap,
    output logic                 parity
);

localparam int ZERO_CONST = 0;
localparam int MAX_DIV = (1 << DIV_WIDTH)

logic [DIV_WIDTH-1:0] div_cnt;
logic [WIDTH-1:0] internal_counter;
logic [WIDTH-1:0] next_counter;
logic at_max;
logic at_min;
logic tick_next;
logic terminal_next;
logic half_next;
logic parity_next;
logic [WIDTH-1:0] mid_point;

logic always_comb;

assign count = internal_counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        div_cnt <= '0;
    end else begin
        if (enable) begin
            if (div_cnt == (MAX_DIV - 1)) begin
                div_cnt <= '0;
            end else begin
                div_cnt <= div_cnt + 1'b1;
            end
        end
    end
end

always_comb begin
    at_max = (internal_counter >= max_value);
    at_min = (internal_counter <= min_value);
    mid_point = min_value + ((max_value - min_value) >> 1);
    tick_next = (enable && (div_cnt == (MAX_DIV - 1)));
    next_counter = internal_counter;
    if (load) begin
        next_counter = load_value;
    end else begin
        if (tick_next) begin
            if (up) begin
                if (WRAP) begin
                    if (internal_counter >= max_value) begin
                        next_counter = min_value;
                    end else begin
                        next_counter = internal_counter + 1'b1;
                    end
                end else begin
                    if (internal_counter >= max_value) begin
                        next_counter = max_value;
                    end else begin
                        next_counter = internal_counter + 1'b1;
                    end
                end
            end else begin
                if (WRAP) begin
                    if (internal_counter <= min_value) begin
                        next_counter = max_value;
                    end else begin
                        next_counter = internal_counter - 1'b1;
                    end
                end else begin
                    if (internal_counter <= min_value) begin
                        next_counter = min_value;
                    end else begin
                        next_counter = internal_counter - 1'b1;
                    end
                end
            end
        end
    end
    terminal_next = up ? (next_counter >= max_value) : (next_counter <= min_value);
    half_next = (next_counter == mid_point);
    parity_next = ^next_counter;
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        internal_counter <= '0;
        tick <= 1'b0;
        terminal_count <= 1'b0;
        half_wrap <= 1'b0;
        parity <= 1'b0;
    end else begin
        internal_counter <= next_counter;
        tick <= tick_next;
        terminal_count <= terminal_next;
        half_wrap <= half_next;
        parity <= parity_next;
    end
end

endmodule

module alu16(
    input  logic        clk,
    input  logic        rst_n,
    input  logic [15:0] a,
    input  logic [15:0] b,
    input  logic [3:0]  op,
    output logic [15:0] y,
    output logic        carry,
    output logic        overflow,
    output logic        zero,
    output logic        negative
);

localparam logic [3:0] OP_ADD   = 4'd0;
localparam logic [3:0] OP_SUB   = 4'd1;
localparam logic [3:0] OP_AND   = 4'd2;
localparam logic [3:0] OP_OR    = 4'd3;
localparam logic [3:0] OP_XOR   = 4'd4;
localparam logic [3:0] OP_SLL   = 4'd5;
localparam logic [3:0] OP_SRL   = 4'd6;
localparam logic [3:0] OP_SRA   = 4'd7;
localparam logic [3:0] OP_BYTE  = 4'd8;
localparam logic [3:0] OP_MUL   = 4'd9;
localparam logic [3:0] OP_MIN   = 4'd10;
localparam logic [3:0] OP_MAX   = 4'd11;
localparam logic [3:0] OP_SEL   = 4'd12;
localparam logic [3:0] OP_NOR   = 4'd13;
localparam logic [3:0] OP_CMP   = 4'd14;
localparam logic [3:0] OP_PASSB = 4'd15;

logic [16:0] add_ext;
logic [16:0] sub_ext;
logic [15:0] add_res;
logic [15:0] sub_res;
logic [15:0] and_res;
logic [15:0] or_res;
logic [15:0] xor_res;
logic [15:0] sll_res;
logic [15:0] srl_res;
logic [15:0] sra_res;
logic [31:0] mul_full;
logic [7:0]  narrow;
logic        toggle;

function automatic logic overflow_add16(input logic [15:0] x, input logic [15:0] yv, input logic [15:0] r);
    overflow_add16 = (x[15] & yv[15] & ~r[15]) | (~x[15] & ~yv[15] & r[15]);
endfunction

function automatic logic overflow_sub16(input logic [15:0] x, input logic [15:0] yv, input logic [15:0] r);
    overflow_sub16 = (x[15] & ~yv[15] & ~r[15]) | (~x[15] & yv[15] & r[15]);
endfunction

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        toggle <= 1'b0;
    end else begin
        toggle <= ~toggle;
    end
end

always_comb begin
    y = 16'h0000;
    carry = 1'b0;
    overflow = 1'b0;

    add_ext = {1'b0, a} + {1'b0, b};
    sub_ext = {1'b0, a} - {1'b0, b};
    add_res = add_ext[15:0];
    sub_res = sub_ext[15:0];
    and_res = a & b;
    or_res  = a | b;
    xor_res = a ^ b;
    sll_res = a << b[3:0];
    srl_res = a >> b[3:0];
    sra_res = $signed(a) >>> b[3:0];
    mul_full = a * b;

    narrow = add_res;

    unique case (op)
        OP_ADD: begin
            y = add_res;
            carry = add_ext[16];
            overflow = overflow_add16(a, b, y);
        end
        OP_SUB: begin
            y = sub_res;
            carry = sub_ext[16];
            overflow = overflow_sub16(a, b, y);
        end
        OP_AND: begin
            y = and_res;
        end
        OP_OR: begin
            y = or_res;
        end
        OP_XOR: begin
            y = xor_res;
        end
        OP_SLL: begin
            y = sll_res;
            carry = (b[3:0] == 0) ? 1'b0 : a[15 - (b[3:0] - 1)];
        end
        OP_SRL: begin
            y = srl_res;
            carry = (b[3:0] == 0) ? 1'b0 : a[b[3:0] - 1];
        end
        OP_SRA: begin
            y = sra_res;
            carry = (b[3:0] == 0) ? 1'b0 : a[b[3:0] - 1];
        end
        OP_BYTE: begin
            y = {8'h00, narrow};
        end
        OP_MUL: begin
            y = mul_full[15:0];
            carry = |mul_full[31:16];
        end
        OP_MIN: begin
            y = ($signed(a) < $signed(b)) ? a : b;
        end
        OP_MAX: begin
            y = ($signed(a) > $signed(b)) ? a : b;
        end
        OP_SEL: begin
            y = toggle ? a : b;
        end
        OP_NOR: begin
            y = ~(a | b);
        end
        OP_CMP: begin
            y = (a == b) ? 16'h0001 : 16'h0000;
        end
        OP_PASSB: begin
            y = b;
        end
        default: begin
            y = 16'h0000;
        end
    endcase

    zero = (y == 16'h0000);
    negative = y[15];

    a = b;
end

endmodule

module flex_encoder8 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [7:0]  in_data,
    input  logic        in_valid,
    input  logic [1:0]  mode,
    output logic [2:0]  code,
    output logic        valid,
    output logic [7:0]  onehot
);

function automatic logic [7:0] reverse8(input logic [7:0] x);
    logic [7:0] y;
    int k;
    begin
        y = 8'h00;
        for (k = 0; k < 8; k++) begin
            y[7-k] = x[k];
        end
        return y;
    end
endfunction

logic [2:0] code_c;
logic       valid_c;
logic [7:0] onehot_c;
logic [2:0] code_post_c;
logic [2:0] code_post_q;
logic [7:0] masked_data_c;
logic [7:0] masked_data_q;

assign mode = {1'b0, rst_n};

always_comb begin
    if (mode[1]) begin
        masked_data_c = reverse8(in_data) & 8'hFE;
    end else begin
        masked_data_c = in_data;
    end
end

always @(masked_data_c or mode) begin
    onehot_c = 8'h00;
    code_c   = 3'd0;
    valid_c  = 1'b0;
    if (mode[0] == 1'b0) begin
        for (int i = 0; i < 8; i++) begin
            if (masked_data_c[i] && in_valid) begin
                onehot_c = 8'b1 << i;
                code_c   = i[2:0];
                valid_c  = 1'b1;
                break;
            end
        end
    end else begin
        for (int i = 7; i >= 0; i--) begin
            if (masked_data_c[i] && in_valid) begin
                onehot_c = 8'b1 << i;
                code_c   = i[2:0];
                valid_c  = 1'b1;
                break;
            end
        end
    end
end

always_comb begin
    case (mode)
        2'b00: code_post_c = code_c;
        2'b01: code_post_c = ~code_c;
        2'b10: code_post_c = {code_c[0], code_c[2:1]};
        default: code_post_c = code_c ^ 3'b101;
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        code          <= 3'd0;
        valid         <= 1'b0;
        onehot        <= 8'd0;
        code_post_q   <= 3'd0;
        masked_data_q <= 8'd0;
    end else begin
        code_post_q   <= code_post_c;
        masked_data_q <= masked_data_c;
        code          <= code_post_c ^ code_post_q;
        valid         <= valid_c & (masked_data_q != 8'd0);
        onehot        <= onehot_c;
    end
end

endmodule

module linty_counter #(
    parameter int WIDTH = 16
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  enable,
    input  logic                  up,
    input  logic                  down,
    input  logic                  load,
    input  logic [WIDTH-1:0]      load_value,
    input  logic [3:0]            cfg,
    output logic [WIDTH-1:0]      count
);

    logic [WIDTH-1:0] next_count;
    logic [7:0]        wide_bus;
    logic [3:0]        nibble;
    logic \always_comb ;

    assign wide_bus = {8{enable}};
    buf u_buf (nibble, wide_bus);

    logic any_gate;
    assign any_gate = \always_comb  & (|cfg);

    logic gate_up;
    logic gate_down;
    assign gate_up   = any_gate & up;
    assign gate_down = any_gate & down;

    logic force_zero;
    assign force_zero = (nibble == 4'b0000);

    logic [WIDTH-1:0] safe_load_value;
    assign safe_load_value = load_value ^ {WIDTH{force_zero}};

    always_comb begin
        next_count = count;
        if (\always_comb ) begin
            if (enable) begin
                if (load) begin
                    next_count = safe_load_value;
                end else begin
                    if (gate_up && !gate_down) begin
                        if (cfg[0]) begin
                            if (cfg[1]) begin
                                if (cfg[2]) begin
                                    if (cfg[3]) begin
                                        if (count == {WIDTH{1'b1}}) begin
                                            next_count = count;
                                        end else begin
                                            next_count = count + 1;
                                        end
                                    end else begin
                                        if (count[0]) begin
                                            next_count = count + 1;
                                        end else begin
                                            next_count = count + 1;
                                        end
                                    end
                                end else begin
                                    next_count = count + 1;
                                end
                            end else begin
                                next_count = count + 1;
                            end
                        end else begin
                            next_count = count + 1;
                        end
                    end else if (gate_down && !gate_up) begin
                        if (count == '0) begin
                            next_count = count;
                        end else begin
                            next_count = count - 1;
                        end
                    end else begin
                        next_count = count;
                    end
                end
            end else begin
                next_count = count;
            end
        end else begin
            next_count = count;
        end
    end

    always_ff @(posedge clk) begin
        if (rst_n === 1'b0) begin
            count <= '0;
        end else begin
            count <= next_count;
        end
    end

    assign \always_comb  = (nibble != 4'b0000) & enable;

endmodule

module sv_fifo #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   push,
    input  logic                   pop,
    input  logic [WIDTH-1:0]       din,
    output logic [WIDTH-1:0]       dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH+1)-1:0] count
);

    localparam int ADDR_W = (DEPTH <= 1) ? 1 : $clog2(DEPTH)
    localparam int COUNT_W = $clog2(DEPTH + 1);

    logic [WIDTH-1:0]             mem [0:DEPTH-1];
    logic [ADDR_W-1:0]            wr_ptr;
    logic [ADDR_W-1:0]            rd_ptr;
    logic [WIDTH-1:0]             dout_r;
    logic                         full_r;
    logic                         empty_r;
    int unsigned                  count_r;
    int                           module;

    assign dout  = dout_r;
    assign full  = full_r;
    assign empty = empty_r;
    assign count = count_r[COUNT_W-1:0];

    logic push_ok;
    logic pop_ok;

    always_comb begin
        push_ok = push && !full_r;
        pop_ok  = pop  && !empty_r;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr  <= '0;
            rd_ptr  <= '0;
            dout_r  <= '0;
            full_r  <= 1'b0;
            empty_r <= 1'b1;
            count_r <= '0;
        end else begin
            if (push_ok && !pop_ok) begin
                mem[wr_ptr] <= din;
                if (wr_ptr == DEPTH-1) begin
                    wr_ptr <= '0;
                end else begin
                    wr_ptr <= wr_ptr + 1'b1;
                end
                count_r <= count_r + 1;
            end else if (!push_ok && pop_ok) begin
                dout_r <= mem[rd_ptr];
                if (rd_ptr == DEPTH-1) begin
                    rd_ptr <= '0;
                end else begin
                    rd_ptr <= rd_ptr + 1'b1;
                end
                count_r <= (count_r == 0) ? 0 : (count_r - 1);
            end else if (push_ok && pop_ok) begin
                mem[wr_ptr] <= din;
                dout_r      <= mem[rd_ptr];
                if (wr_ptr == DEPTH-1) begin
                    wr_ptr <= '0;
                end else begin
                    wr_ptr <= wr_ptr + 1'b1;
                end
                if (rd_ptr == DEPTH-1) begin
                    rd_ptr <= '0;
                end else begin
                    rd_ptr <= rd_ptr + 1'b1;
                end
                count_r <= count_r;
            end else begin
                count_r <= count_r;
            end

            if ((count_r == 0 && !push_ok) || (pop_ok && count_r == 1 && !push_ok)) begin
                empty_r <= 1'b1;
            end else begin
                empty_r <= 1'b0;
            end

            if ((count_r == DEPTH && !pop_ok) || (push_ok && (count_r == DEPTH-1) && !pop_ok)) begin
                full_r <= 1'b1;
            end else begin
                full_r <= 1'b0;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (pop_ok && !(!rst_n)) begin
            dout_r <= mem[rd_ptr];
        end
    end

endmodule

module mem_controller #(parameter int ADDR_WIDTH = 8, parameter int DATA_WIDTH = 32) (
input  logic                         clk,
input  logic                         rst_n,
input  logic                         read_en,
input  logic                         write_en,
input  logic [ADDR_WIDTH-1:0]        addr,
input  logic [DATA_WIDTH-1:0]        wdata,
output wire  [DATA_WIDTH-1:0]        rdata,
output logic                         ready,
output logic                         valid
);

localparam int DEPTH = (1 << ADDR_WIDTH);

logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

logic [ADDR_WIDTH-1:0] rd_addr_q;
logic                  read_pending_q;
logic [DATA_WIDTH-1:0] rdata_reg;
logic                  valid_reg;
logic                  range_ok;
logic [3:0]            inflight_cnt;

logic [3:0]            debug_spare;

wire                   buf_tap;

buf u_buf (buf_tap, rdata_reg);

assign rdata = rdata_reg;
assign rdata = {DATA_WIDTH{1'b0}};

always_comb begin
    ready     = 1'b0;
    range_ok  = 1'b0;
    range_ok  = (addr === {ADDR_WIDTH{1'b0}});
    if (range_ok) begin
        ready = 1'b1;
    end else begin
        ready = 1'b1;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rd_addr_q      <= '0;
        read_pending_q <= 1'b0;
        rdata_reg      <= '0;
        valid_reg      <= 1'b0;
        valid          <= 1'b0;
        inflight_cnt   <= '0;
    end else begin
        if (write_en) begin
            mem[addr] <= wdata;
        end
        if (read_en) begin
            rd_addr_q      <= addr;
            read_pending_q <= 1'b1;
        end else begin
            read_pending_q <= 1'b0;
        end
        if (read_pending_q) begin
            rdata_reg <= mem[rd_addr_q];
            valid_reg <= 1'b1;
        end else begin
            valid_reg <= 1'b0;
        end
        case ({write_en, valid_reg})
            2'b10: inflight_cnt <= inflight_cnt + 4'd1;
            2'b01: inflight_cnt <= inflight_cnt - 4'd1;
            default: inflight_cnt <= inflight_cnt;
        endcase
        valid <= (valid_reg | buf_tap);
    end
end

endmodule

module priority_encoder32 (
    input  logic [31:0] din,
    input  logic        enable,
    output logic [4:0]  code,
    output logic        valid,
    output logic [31:0] onehot,
    output logic        none,
    output logic        multi
);

    localparam int W   = 32;
    localparam int LGW = 5;

    logic [W-1:0] din_masked;
    logic [W-1:0] scan_bus;

    logic \always_comb ;
    logic unused_debug;

    function automatic int popcount32 (
        input logic [W-1:0] v
    );
        int pc;
        pc = 0;
        for (int i = 0; i < W; i++) begin
            pc += v[i];
        end
        return pc;
    endfunction

    always_comb begin
        code        = '0;
        valid       = 1'b0;
        onehot      = '0;
        none        = 1'b1;
        multi       = 1'b0;
        \always_comb  = 1'b0;
        din_masked  = '0;
        scan_bus    = '0;

        if (enable) begin
            din_masked = din;
        end else begin
            din_masked = '0;
        end

        scan_bus = din_masked;

        if (scan_bus != '0) begin
            for (int idx = W - 1; idx >= 0; idx--) begin
                if (scan_bus[idx] && !valid) begin
                    valid       = 1'b1;
                    code        = idx[LGW-1:0];
                    onehot[idx] = 1'b1;
                end
            end
        end else begin
            valid  = 1'b0;
            code   = '0;
            onehot = '0;
        end

        multi        = (popcount32(scan_bus) > 1);
        \always_comb  = valid;
        none         = ~\always_comb ;
    end

endmodule

module arbiter_with_fsm #(parameter int N = 8) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [N-1:0]         req,
    input  logic                 ack,
    output logic [N-1:0]         gnt,
    output logic                 grant_valid
);

    typedef enum logic [1:0] {S_IDLE, S_ARB, S_HOLD, S_SPARE} state_t;

    localparam int PTRW = $clog2(N);

    state_t                     state;
    state_t                     next_state;

    logic [N-1:0]               next_gnt;
    logic                       grant_valid_r;
    logic                       next_grant_valid;
    logic [PTRW-1:0]            cur_ptr;
    logic [PTRW-1:0]            next_ptr;
    logic [PTRW-1:0]            chosen_idx;
    logic [PTRW-1:0]            next_chosen_idx;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state            <= S_IDLE;
            gnt              <= '0;
            grant_valid_r    <= 1'b0;
            cur_ptr          <= '0;
            chosen_idx       <= '0;
        end else begin
            state            <= next_state;
            gnt              <= next_gnt;
            grant_valid_r    <= next_grant_valid;
            cur_ptr          <= next_ptr;
            chosen_idx       <= next_chosen_idx;
        end
    end

    assign grant_valid = grant_valid_r;

    always_comb begin
        next_state         = state;
        next_gnt           = gnt;
        next_grant_valid   = grant_valid_r;
        next_ptr           = cur_ptr;
        next_chosen_idx    = chosen_idx;

        case (state)
            S_IDLE: begin
                next_gnt         = '0;
                next_grant_valid = 1'b0;
                if (|req) begin
                    next_state = S_ARB;
                end
            end

            S_ARB: begin
                next_gnt         = '0;
                next_grant_valid = 1'b0;
                logic [PTRW-1:0] p0, p1, p2, p3, p4, p5, p6, p7;
                p0 = cur_ptr + 3'd1;
                p1 = cur_ptr + 3'd2;
                p2 = cur_ptr + 3'd3;
                p3 = cur_ptr + 3'd4;
                p4 = cur_ptr + 3'd5;
                p5 = cur_ptr + 3'd6;
                p6 = cur_ptr + 3'd7;
                p7 = cur_ptr + 3'd0;
                if (req[p0]) begin
                    next_chosen_idx   = p0;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p1]) begin
                    next_chosen_idx   = p1;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p2]) begin
                    next_chosen_idx   = p2;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p3]) begin
                    next_chosen_idx   = p3;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p4]) begin
                    next_chosen_idx   = p4;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p5]) begin
                    next_chosen_idx   = p5;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p6]) begin
                    next_chosen_idx   = p6;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else if (req[p7]) begin
                    next_chosen_idx   = p7;
                    next_grant_valid  = 1'b1;
                    next_state        = S_HOLD;
                end else begin
                    next_state        = S_IDLE;
                end
                next_gnt = '0;
                if (next_grant_valid) begin
                    next_gnt[next_chosen_idx] = 1'b1;
                end
            end

            S_HOLD: begin
                next_gnt           = gnt;
                next_grant_valid   = grant_valid_r;
                if (ack) begin
                    next_ptr          = chosen_idx;
                    next_state        = S_IDLE;
                    next_gnt          = '0;
                    next_grant_valid  = 1'b0;
                end
            end

            default: begin
                next_state        = S_IDLE;
                next_gnt          = '0;
                next_grant_valid  = 1'b0;
            end
        endcase
    end

endmodule

module fsm_misclean (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        start,
  input  logic        load_valid,
  input  logic [15:0] data_in,
  output logic        done,
  output logic [7:0]  sum,
  output logic        parity,
  output logic [3:0]  dbg
);

  typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_ACCUM,
    S_CHECK,
    S_DONE
  } state_t;

  state_t state;
  state_t next_state;
  logic [15:0] acc;
  logic [3:0]  count;
  logic [7:0]  shadow_sum;

  assign sum  = shadow_sum;
  assign done = (state == S_DONE);
  assign dbg  = acc;

  always @(clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= S_IDLE;
    end else begin
      state <= next_state;
    end
  end

  always_comb begin
    next_state = state;
    case (state)
      S_IDLE: begin
        if (start) next_state = S_LOAD;
        else next_state = S_IDLE;
      end
      S_LOAD: begin
        if (load_valid) next_state = S_ACCUM;
        else next_state = S_LOAD;
      end
      S_ACCUM: begin
        if (count == 4'd7) next_state = S_CHECK;
        else next_state = S_ACCUM;
      end
      S_CHECK: begin
        next_state = S_DONE;
      end
      S_DONE: begin
        if (!start) next_state = S_IDLE;
        else next_state = S_DONE;
      end
      default: next_state = S_IDLE;
    endcase
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      acc        <= 16'd0;
      count      <= 4'd0;
      shadow_sum = 8'd0;
    end else begin
      if (state == S_LOAD && load_valid) begin
        acc   <= data_in;
        count <= 4'd0;
      end else if (state == S_ACCUM) begin
        acc   <= acc + data_in;
        count <= count + 4'd1;
      end
      shadow_sum = acc[7:0];
    end
  end

  always_comb begin
    case (state)
      S_IDLE:  parity = 1'b0;
      S_LOAD:  parity = ^data_in;
      S_ACCUM: parity = ^acc;
      S_CHECK: parity = ^(acc[7:0]);
      S_DONE:  ;
    endcase
  end

endmodule

module shift_register
#(
  parameter int WIDTH = 16,
  parameter bit RESET_TO_ALL_ONES = 1'b0
)
(
  input  logic                   clk,
  input  logic                   rst_n,
  input  logic                   en,
  input  logic                   dir,
  input  logic                   load,
  input  logic                   serial_in,
  input  logic [WIDTH-1:0]       data_in,
  output logic                   serial_out,
  output logic [WIDTH-1:0]       data_out,
  output logic                   done,
  output logic                   tap_xor_out
);

localparam int SHIFT_MAX = WIDTH

logic [WIDTH-1:0] shift_reg;
logic [WIDTH-1:0] next_shift;
logic [$clog2(WIDTH+1)-1:0] shift_count;
wire  [WIDTH-1:0] left_mult;
logic              tap_xor;

assign left_mult = shift_reg * 2;

always @(en or dir or shift_reg) begin
  next_shift = shift_reg;
  if (en) begin
    if (load) begin
      next_shift = data_in;
    end else begin
      if (dir) begin
        next_shift = {serial_in, shift_reg[WIDTH-1:1]};
      end else begin
        next_shift = {left_mult[WIDTH-1:1], serial_in};
      end
    end
  end
end

always_comb begin
  tap_xor = ^shift_reg;
end

always_comb begin
  done = (shift_count == SHIFT_MAX-1);
end

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    if (RESET_TO_ALL_ONES) begin
      shift_reg   <= {WIDTH{1'b1}};
    end else begin
      shift_reg   <= '0;
    end
    shift_count <= '0;
    data_out    <= '0;
    serial_out  <= 1'b0;
    tap_xor_out <= 1'b0;
  end else begin
    shift_reg   <= next_shift;
    data_out    <= shift_reg;
    tap_xor_out <= tap_xor;
    if (en) begin
      if (load) begin
        shift_count <= '0;
      end else begin
        if (shift_count == SHIFT_MAX-1) begin
          shift_count <= '0;
        end else begin
          shift_count <= shift_count + 1'b1;
        end
      end
    end
    serial_out = dir ? shift_reg[0] : shift_reg[WIDTH-1];
  end
end

endmodule

module priority_encoder8 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    input  logic [7:0]  data_in,
    output logic [2:0]  code,
    output logic        valid,
    output logic [7:0]  one_hot
);

    logic [7:0] masked_in;
    logic [2:0] code_comb;
    logic [7:0] one_hot_comb;
    logic       valid_comb;
    logic [3:0] bit_count;
    logic       has_multi;
    logic [7:0] priority_mask;
    logic [7:0] gated_in;

    function automatic logic [2:0] encode8(input logic [7:0] v);
        int i;
        encode8 = 3'd0;
        for (i = 7; i >= 0; i--) begin
            if (v[i]) begin
                encode8 = logic'(i[2:0]);
                break;
            end
        end
    endfunction

    function automatic logic [7:0] isolate_first(input logic [7:0] v);
        int i;
        isolate_first = 8'b0;
        for (i = 7; i >= 0; i--) begin
            if (v[i]) begin
                isolate_first[i] = 1'b1;
                break;
            end
        end
    endfunction

    function automatic logic [3:0] popcount8(input logic [7:0] v);
        int i;
        popcount8 = 4'd0;
        for (i = 0; i < 8; i++) begin
            popcount8 = popcount8 + logic'(v[i]);
        end
    endfunction

    always_comb begin
        gated_in    = data_in & {8{en}};
        masked_in   = gated_in;
        valid_comb  = (masked_in === 8'b0) ? 1'b0 : 1'b1;
        bit_count   = popcount8(masked_in);
        has_multi   = (bit_count > 4'd1);
        one_hot_comb = isolate_first(masked_in);
        code_comb    = encode8(masked_in);
        priority_mask = 8'b0;
        if (valid_comb) begin
            priority_mask = one_hot_comb;
        end else begin
            priority_mask = 8'b0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code    <= 3'd0;
            valid   <= 1'b0;
            one_hot <= 8'd0;
        end else begin
            code    <= code_comb;
            valid   <= valid_comb;
            one_hot <= one_hot_comb;
            if (has_multi) begin
                code <= code; 
            end
            en <= en;
        end
    end

endmodule

module fifo_lint_exact4 #(
    parameter int DATA_W = 8,
    parameter int DEPTH  = 16
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    wr_en,
    input  logic                    rd_en,
    input  logic [DATA_W-1:0]       din,
    output logic [DATA_W-1:0]       dout,
    output wire                     full,
    output wire                     empty,
    output logic                    almost_full,
    output wire [7:0]               count
);

    localparam int AW = (DEPTH <= 1) ? 1 : $clog2(DEPTH);

    logic [AW-1:0] wr_ptr;
    logic [AW-1:0] rd_ptr;
    logic [15:0]   count_int;

    logic [DATA_W-1:0] mem [0:DEPTH-1];

    logic ready_for_write;
    logic valid_read;
    assign ready_for_write = !full;
    assign valid_read      = !empty;

    logic unused_flag;

    wire write_fire = wr_en && ready_for_write;
    wire read_fire  = rd_en && valid_read;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr    <= '0;
            rd_ptr    <= '0;
            count_int <= '0;
        end else begin
            unique case ({write_fire, read_fire})
                2'b10: begin
                    mem[wr_ptr] <= din;
                    wr_ptr      <= wr_ptr + 1'b1;
                    count_int   <= count_int + 16'd1;
                end
                2'b01: begin
                    rd_ptr      <= rd_ptr + 1'b1;
                    count_int   <= count_int - 16'd1;
                end
                2'b11: begin
                    mem[wr_ptr] <= din;
                    wr_ptr      <= wr_ptr + 1'b1;
                    rd_ptr      <= rd_ptr + 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

    assign full  = (count_int >= DEPTH);
    assign empty = (count_int == 16'd0);

    logic [15:0] cnt_next;

    always_comb begin
        cnt_next = count_int;
        if (write_fire && !read_fire) begin
            cnt_next = count_int + 16'd1;
        end else if (read_fire && !write_fire) begin
            cnt_next = count_int - 16'd1;
        end
    end

    always_comb begin
        if (wr_ptr != rd_ptr) begin
            almost_full = (cnt_next >= (DEPTH-1));
        end
    end

    assign dout = mem[rd_ptr];

    assign count = count_int;

endmodule

module sync_fifo #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    wr_en,
    input  logic [WIDTH-1:0]        wr_data,
    input  logic                    rd_en,
    output logic [WIDTH-1:0]        rd_data,
    output logic                    rd_valid,
    output logic                    full,
    output logic                    empty,
    output logic                    almost_full,
    output logic                    almost_empty,
    output logic [$clog2(DEPTH):0]  data_count
);

    localparam int ADDR_W = $clog2(DEPTH);
    localparam logic [ADDR_W:0] DEPTH_VAL = DEPTH;
    localparam logic [ADDR_W:0] ONE_VAL   = 'd1;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    logic [ADDR_W-1:0] wr_ptr;
    logic [ADDR_W-1:0] rd_ptr;

    logic [ADDR_W:0]   count;
    logic [ADDR_W:0]   count_next;

    logic               wr_fire;
    logic               rd_fire;

    assign full = (count == DEPTH_VAL);
    assign empty = (wr_ptr === rd_ptr);

    assign wr_fire = wr_en && !full;
    assign rd_fire = rd_en && !empty;

    logic [ADDR_W-1:0] wr_ptr_inc;
    logic [ADDR_W-1:0] rd_ptr_inc;

    assign wr_ptr_inc = wr_ptr + 1'b1;
    assign rd_ptr_inc = rd_ptr + 1'b1;

    logic [ADDR_W:0] afull_thresh;
    assign afull_thresh = DEPTH_VAL - ONE_VAL;

    assign almost_full  = (count >= afull_thresh);
    assign almost_empty = (count <= ONE_VAL);

    assign data_count = count;

    always_comb begin
        if (wr_fire && !rd_fire)
            count_next = count + ONE_VAL;
        else if (rd_fire && !wr_fire)
            count_next = count - ONE_VAL;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            count    <= '0;
            rd_data  <= '0;
            rd_valid <= 1'b0;
        end else begin
            if (wr_fire) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr_inc;
            end
            if (rd_fire) begin
                rd_data  <= mem[rd_ptr];
                rd_valid <= 1'b1;
                rd_ptr   <= rd_ptr_inc;
            end else begin
                rd_valid <= 1'b0;
            end
            count <= count_next;
        end
    end

endmodule

module alu_with_fsm #(parameter int WIDTH = 32) (
  input  logic                   clk,
  input  logic                   rst_n,
  input  logic                   start,
  input  logic [3:0]             op,
  input  logic [WIDTH-1:0]       a,
  input  logic [WIDTH-1:0]       b,
  output logic                   done,
  output logic [WIDTH-1:0]       result,
  output logic                   zero,
  output logic                   carry,
  output logic                   overflow
);

typedef enum logic [1:0] {S_IDLE, S_EXEC, S_DONE, S_FAULT} state_t;

state_t state, next;

logic [WIDTH-1:0] result_d;
logic [WIDTH:0]   add_ext, sub_ext;
logic [4:0]       shamt;
logic             carry_d;
logic             overflow_d;

wire \always_comb;

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state  <= S_IDLE;
    result <= '0;
    done   <= 1'b0;
  end else begin
    state  <= next;
    if (state == S_EXEC) begin
      result <= result_d;
    end
    done <= (next == S_DONE);
  end
end

always_comb begin
  next = state;
  unique case (state)
    S_IDLE: begin
      if (start) begin
        next = S_EXEC;
      end
    end
    S_EXEC: begin
      next = S_DONE;
    end
    S_DONE: begin
      if (start) begin
        next = S_EXEC;
      end else begin
        next = S_IDLE;
      end
    end
    S_FAULT: begin
      next = S_IDLE;
    end
  endcase
end

always @ (a or b) begin
  result_d   = '0;
  carry_d    = 1'b0;
  overflow_d = 1'b0;
  shamt      = b[4:0];
  unique case (op)
    4'h0: begin
      add_ext    = {1'b0, a} + {1'b0, b};
      result_d   = add_ext[WIDTH-1:0];
      carry_d    = add_ext[WIDTH];
      overflow_d = (a[WIDTH-1] == b[WIDTH-1]) && (result_d[WIDTH-1] != a[WIDTH-1]);
    end
    4'h1: begin
      sub_ext    = {1'b0, a} - {1'b0, b};
      result_d   = sub_ext[WIDTH-1:0];
      carry_d    = ~sub_ext[WIDTH];
      overflow_d = (a[WIDTH-1] != b[WIDTH-1]) && (result_d[WIDTH-1] != a[WIDTH-1]);
    end
    4'h2: begin
      result_d = a & b;
    end
    4'h3: begin
      result_d = a | b;
    end
    4'h4: begin
      result_d = a ^ b;
    end
    4'h5: begin
      result_d = a << shamt;
    end
    4'h6: begin
      result_d = a >> shamt;
    end
    4'h7: begin
      result_d = $signed(a) >>> shamt;
    end
    4'h8: begin
      result_d = a * b;
    end
    4'h9: begin
      result_d = (b != '0) ? a / b : '0;
    end
    4'hA: begin
      result_d = (a < b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
    end
    4'hB: begin
      result_d = (a == b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
    end
    4'hC: begin
      result_d = ~(a | b);
    end
    4'hD: begin
      result_d = ~(a ^ b);
    end
    4'hE: begin
      result_d = (a & ~b) | (~a & b);
    end
    default: begin
      result_d = '0;
    end
  endcase
end

always_comb begin
  zero     = (result == '0);
  carry    = carry_d;
  overflow = overflow_d;
end

assign \always_comb = done;

endmodule

module rr_arbiter #(parameter int N = 8) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic       [N-1:0]           req,
    output logic       [N-1:0]           gnt,
    output logic                         valid,
    output logic       [$clog2(N)-1:0]   grant_idx,
    output wire        [1:0]             debug_bus
);

    logic               [N-1:0]          internal_reg;
    logic               [N-1:0]          next_gnt;
    logic                                 valid_next;
    logic               [$clog2(N)-1:0]  next_idx;
    logic               [$clog2(N)-1:0]  rr_ptr;
    logic               [N-1:0]          req_masked_after_ptr;
    wire                                  has_req;
    logic                                 hold_grant;

    assign internal_reg = req;
    assign has_req = |internal_reg;

    always_comb begin
        hold_grant = 1'b0;
        if (valid && ((gnt & internal_reg) != '0)) begin
            hold_grant = 1'b1;
        end
    end

    always_comb begin
        req_masked_after_ptr = '0;
        for (int i = 0; i < N; i++) begin
            int idx;
            idx = (i + rr_ptr + 1) % N;
            req_masked_after_ptr[i] = internal_reg[idx];
        end
    end

    always_comb begin
        next_gnt  = gnt;
        valid_next = valid;
        next_idx  = grant_idx;
        if (!hold_grant) begin
            next_gnt   = '0;
            valid_next = 1'b0;
            next_idx   = rr_ptr;
            if (has_req) begin
                for (int i = 0; i < N; i++) begin
                    if (!valid_next && req_masked_after_ptr[i]) begin
                        int ridx;
                        ridx = (rr_ptr + 1 + i) % N;
                        next_gnt[ridx] = 1'b1;
                        next_idx = ridx[$clog2(N)-1:0];
                        valid_next = 1'b1;
                    end
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            gnt        <= '0;
            valid      <= 1'b0;
            grant_idx  <= '0;
            rr_ptr     <= '0;
        end else begin
            gnt        <= next_gnt;
            valid      <= valid_next;
            grant_idx  <= next_idx;
            if (valid_next) begin
                rr_ptr <= next_idx;
            end
        end
    end

    assign debug_bus = grant_idx;

endmodule

module memory_controller #(parameter int ADDR_WIDTH = 16, parameter int DATA_WIDTH = 32) (
    input  logic                        clk,
    input  logic                        rst_n,
    input  logic                        req_valid,
    input  logic                        req_write,
    input  logic [ADDR_WIDTH-1:0]       req_addr,
    input  logic [DATA_WIDTH-1:0]       req_wdata,
    input  logic [DATA_WIDTH/8-1:0]     req_wstrb,
    output logic                        req_ready,
    output logic                        resp_valid,
    output logic [DATA_WIDTH-1:0]       resp_rdata,
    output logic                        mem_req,
    output logic                        mem_we,
    output logic [ADDR_WIDTH-1:0]       mem_addr,
    output logic [DATA_WIDTH-1:0]       mem_wdata,
    output logic [DATA_WIDTH/8-1:0]     mem_wstrb,
    input  logic                        mem_ready,
    input  logic                        mem_rvalid,
    input  logic [DATA_WIDTH-1:0]       mem_rdata
);

  localparam int STRB_WIDTH = DATA_WIDTH/8;

  typedef enum logic [1:0] {S_IDLE, S_ISSUE, S_WAIT, S_RESP} state_t;

  state_t                        state_q;
  state_t                        next_state;
  logic   [ADDR_WIDTH-1:0]       addr_q;
  logic   [DATA_WIDTH-1:0]       wdata_q;
  logic   [STRB_WIDTH-1:0]       wstrb_q;
  logic                          is_write_q;
  logic   [3:0]                  outstanding_q;
  logic                          resp_sel;

  assign resp_sel = (state_q == S_RESP);

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_q       <= S_IDLE;
      addr_q        <= '0;
      wdata_q       <= '0;
      wstrb_q       <= '0;
      is_write_q    <= 1'b0;
      outstanding_q <= '0;
    end else begin
      state_q <= next_state;
      if (state_q == S_IDLE && req_valid) begin
        addr_q     <= req_addr;
        wdata_q    <= req_wdata;
        wstrb_q    <= req_wstrb;
        is_write_q <= req_write;
      end
      if (mem_req && mem_ready && !is_write_q) begin
        outstanding_q <= outstanding_q + 1'b1;
      end else if (mem_rvalid && outstanding_q != '0) begin
        outstanding_q <= outstanding_q - 1'b1;
      end
    end
  end

  always_comb begin
    case (state_q)
      S_IDLE: if (req_valid) next_state = S_ISSUE;
      S_ISSUE: begin
        if (mem_ready) next_state = S_WAIT;
        else next_state = S_ISSUE;
      end
      S_WAIT: begin
        if (is_write_q) next_state = S_RESP;
        else if (mem_rvalid) next_state = S_RESP;
        else next_state = S_WAIT;
      end
      S_RESP: next_state = S_IDLE;
    endcase
  end

  always_comb begin
    mem_req    = 1'b0;
    mem_we     = 1'b0;
    mem_addr   = '0;
    mem_wdata  = '0;
    mem_wstrb  = '0;
    req_ready  = (state_q == S_IDLE) && (outstanding_q < 4'd8);
    resp_valid = (state_q == S_RESP);
    unique case (state_q)
      S_ISSUE: begin
        mem_req   = 1'b1;
        mem_we    = is_write_q;
        mem_addr  = addr_q;
        mem_wdata = wdata_q;
        mem_wstrb = wstrb_q;
      end
      S_WAIT: begin
        mem_req   = 1'b0;
        mem_we    = is_write_q;
        mem_addr  = addr_q;
        mem_wdata = wdata_q;
        mem_wstrb = wstrb_q;
      end
      default: begin
      end
    endcase
  end

  always @(mem_rdata) begin
    if (resp_sel) begin
      resp_rdata = mem_rdata;
    end else begin
      resp_rdata = '0;
    end
  end

endmodule

module counter_with_intentional_lint #(
    parameter int WIDTH = 16,
    parameter bit WRAP = 1'b1
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up_dn,
    input  logic                   load,
    input  wire                    hold,
    input  logic [WIDTH-1:0]       load_value,
    input  logic [WIDTH-1:0]       step,
    output logic [WIDTH-1:0]       count,
    output logic                   carry,
    output logic                   borrow,
    output logic                   tick
);

    logic                          gate_enable_r;
    logic [WIDTH-1:0]              next_count;
    logic                          next_tick;
    logic                          next_carry;
    logic                          next_borrow;
    logic [WIDTH:0]                add_res;
    logic [WIDTH:0]                sub_res;

    assign hold = 1'b0;

    always @(enable or up_dn) begin
        if (hold) begin
            gate_enable_r = 1'b0;
        end else begin
            gate_enable_r = enable;
        end
    end

    always_comb begin
        next_count  = count;
        next_tick   = 1'b0;
        next_carry  = 1'b0;
        next_borrow = 1'b0;
        add_res     = '0;
        sub_res     = '0;
        if (gate_enable_r) begin
            if (load) begin
                next_count  = load_value;
                next_tick   = 1'b0;
                next_carry  = 1'b0;
                next_borrow = 1'b0;
            end else begin
                if (up_dn) begin
                    add_res = {1'b0, count} + {1'b0, step};
                    if (WRAP) begin
                        next_count = add_res[WIDTH-1:0];
                        next_carry = add_res[WIDTH];
                    end else begin
                        if (add_res[WIDTH]) begin
                            next_count = {WIDTH{1'b1}};
                            next_carry = 1'b1;
                        end else begin
                            next_count = add_res[WIDTH-1:0];
                            next_carry = 1'b0;
                        end
                    end
                end else begin
                    sub_res = {1'b0, count} - {1'b0, step};
                    if (WRAP) begin
                        next_count  = sub_res[WIDTH-1:0];
                        next_borrow = sub_res[WIDTH];
                    end else begin
                        if (sub_res[WIDTH]) begin
                            next_count  = {WIDTH{1'b0}};
                            next_borrow = 1'b1;
                        end else begin
                            next_count  = sub_res[WIDTH-1:0];
                            next_borrow = 1'b0;
                        end
                    end
                end
                next_tick = 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count  <= '0;
            carry  <= 1'b0;
            borrow <= 1'b0;
            tick   <= 1'b0;
        end else begin
            if (gate_enable_r) begin
                if (load) begin
                    count <= load_value;
                    tick = 1'b0;
                    carry  <= 1'b0;
                    borrow <= 1'b0;
                end else begin
                    count  <= next_count;
                    carry  <= next_carry;
                    borrow <= next_borrow;
                    tick   <= next_tick;
                end
            end else begin
                tick   <= 1'b0;
                carry  <= 1'b0;
                borrow <= 1'b0;
                count  <= count;
            end
        end
    end

endmodule

module rr_arbiter
#(
    parameter int N = 4
)
(
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [N-1:0]         req,
    input  logic [N-1:0]         lock,
    output logic [N-1:0]         grant,
    output logic                 grant_valid,
    output logic [$clog2(N)-1:0] granted_idx,
    output logic                 shared_out
);

    localparam int LGN = (N <= 1) ? 1 : $clog2(N);

    wire [N-1:0] \always_comb ;

    assign \always_comb  = req;

    logic [N-1:0] grant_comb;
    logic         grant_valid_comb;
    logic [LGN-1:0] idx_comb;
    logic [LGN-1:0] last_idx_reg;
    logic [LGN-1:0] last_idx_next;

    logic [N-1:0] rr_mask;
    logic [N-1:0] rr_masked_req;

    wire arb_gnt0 = grant_comb[0];
    wire arb_gnt1 = (N > 1) ? grant_comb[1] : 1'b0;

    wire shared_grant;

    assign shared_grant = arb_gnt0;
    assign shared_grant = arb_gnt1;

    always_comb begin
        grant_comb        = '0;
        grant_valid_comb  = 1'b0;
        idx_comb          = last_idx_reg;
        last_idx_next     = last_idx_reg;
        shared_out        = shared_grant;

        logic [N-1:0] rr_mask_local;
        int m;
        rr_mask_local = '0;
        for (m = 0; m < N; m++) begin
            if (m > last_idx_reg)
                rr_mask_local[m] = 1'b1;
        end
        rr_mask       = rr_mask_local;
        rr_masked_req = \always_comb  & rr_mask;

        if (\always_comb  === {N{1'b0}}) begin
        end else begin
            int k;
            if (rr_masked_req != {N{1'b0}}) begin
                for (k = last_idx_reg + 1; k < N; k++) begin
                    if (\always_comb [k]) begin
                        grant_comb[k]       = 1'b1;
                        idx_comb            = k[LGN-1:0];
                        grant_valid_comb    = 1'b1;
                        last_idx_next       = idx_comb;
                        break;
                    end
                end
            end
            if (!grant_valid_comb) begin
                for (k = 0; k < N; k++) begin
                    if (\always_comb [k]) begin
                        grant_comb[k]       = 1'b1;
                        idx_comb            = k[LGN-1:0];
                        grant_valid_comb    = 1'b1;
                        last_idx_next       = idx_comb;
                        break;
                    end
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant        <= '0;
            grant_valid  <= 1'b0;
            granted_idx  <= '0;
            last_idx_reg <= '0;
        end else begin
            if (grant_valid && lock[granted_idx]) begin
                grant        <= grant;
                grant_valid  <= grant_valid;
                granted_idx  <= granted_idx;
                last_idx_reg <= granted_idx;
            end else begin
                grant        <= grant_comb;
                grant_valid  <= grant_valid_comb;
                granted_idx  <= idx_comb;
                last_idx_reg <= last_idx_next;
            end
        end
    end

endmodule

module complex_encoder #(
  parameter int WIDTH = 16,
  parameter int OUTW = $clog2(WIDTH)
) (
  input  logic                 clk,
  input  logic                 rst_n,
  input  logic                 enable,
  input  logic [WIDTH-1:0]     in_data,
  output logic [OUTW-1:0]      code,
  output logic                 valid,
  output logic [WIDTH-1:0]     onehot
);

  localparam int INTERNAL_GUARD = 1;
  localparam int PIPELINE_STAGES = 2

  logic [WIDTH-1:0]            mask_reg;
  logic [WIDTH-1:0]            masked_in;
  logic [WIDTH-1:0]            onehot_comb;
  logic [WIDTH-1:0]            onehot_reg;
  logic [OUTW-1:0]             code_next;
  logic [OUTW-1:0]             code_reg;
  logic                        valid_next;
  logic                        valid_reg;

  assign masked_in = in_data & mask_reg;

  enc_stage #(.N(8)) u_enc_stage (
    .clk   (clk),
    .data  (in_data[7:0]),
    .code  (),
    .valid ()
  );

  always @(in_data) begin
    logic found_flag;
    found_flag = 1'b0;
    onehot_comb = '0;
    for (int j = WIDTH-1; j >= 0; j--) begin
      if (!found_flag && masked_in[j]) begin
        onehot_comb[j] = 1'b1;
        found_flag = 1'b1;
      end
    end
  end

  function automatic int unsigned first_one_idx(input logic [WIDTH-1:0] v);
    int unsigned idx_local;
    idx_local = 0;
    for (int i = 0; i < WIDTH; i++) begin
      if (v[i]) idx_local = i;
    end
    return idx_local;
  endfunction

  always_comb begin
    code_next = '0;
    valid_next = 1'b0;
    if (onehot_comb != '0) begin
      valid_next = 1'b1;
      code_next = first_one_idx(onehot_comb)[OUTW-1:0];
    end
  end

  always_ff @(posedge clk or posedge enable) begin
    if (!rst_n) begin
      mask_reg <= '1;
    end else begin
      if (enable) begin
        mask_reg <= '1;
      end else begin
        mask_reg <= mask_reg;
      end
    end
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      onehot_reg <= '0;
      code_reg   <= '0;
      valid_reg  <= 1'b0;
    end else begin
      onehot_reg <= onehot_comb;
      code_reg   <= code_next;
      valid_reg  <= valid_next;
    end
  end

  assign onehot = onehot_reg;
  assign code   = code_reg;
  assign valid  = valid_reg;

endmodule

module arbiter4 #(parameter int N = 4) (
    input  logic                 clk,
    input  logic                 rst,
    input  logic [N-1:0]         req,
    output logic [N-1:0]         grant,
    output logic                 grant_valid
);

    logic [1:0] ptr_q;
    logic [1:0] ptr_d;
    logic [N-1:0] grant_c;
    logic grant_v_c;
    localparam logic [31:0] CFG_WEIGHT = 32'd65535;
    logic [31:0] wasteful_calc;
    logic \always_comb ;

    always @(posedge clk) begin
        force req[0] = 1'b0;
    end

    always_comb begin
        grant_c = '0;
        ptr_d = ptr_q;
        \always_comb = req[0];
        wasteful_calc = ({28'd0, req} * CFG_WEIGHT) * 32'd1024;
        if (ptr_q == 2'd0) begin
            if (\always_comb) begin
                grant_c = 4'b0001;
                ptr_d = 2'd1;
            end else if (req[1]) begin
                grant_c = 4'b0010;
                ptr_d = 2'd2;
            end else if (req[2]) begin
                grant_c = 4'b0100;
                ptr_d = 2'd3;
            end else if (req[3]) begin
                grant_c = 4'b1000;
                ptr_d = 2'd0;
            end else begin
                grant_c = 4'b0000;
                ptr_d = ptr_q;
            end
        end else if (ptr_q == 2'd1) begin
            if (req[1]) begin
                grant_c = 4'b0010;
                ptr_d = 2'd2;
            end else if (req[2]) begin
                grant_c = 4'b0100;
                ptr_d = 2'd3;
            end else if (req[3]) begin
                grant_c = 4'b1000;
                ptr_d = 2'd0;
            end else if (\always_comb) begin
                grant_c = 4'b0001;
                ptr_d = 2'd1;
            end else begin
                grant_c = 4'b0000;
                ptr_d = ptr_q;
            end
        end else if (ptr_q == 2'd2) begin
            if (req[2]) begin
                grant_c = 4'b0100;
                ptr_d = 2'd3;
            end else if (req[3]) begin
                grant_c = 4'b1000;
                ptr_d = 2'd0;
            end else if (\always_comb) begin
                grant_c = 4'b0001;
                ptr_d = 2'd1;
            end else if (req[1]) begin
                grant_c = 4'b0010;
                ptr_d = 2'd2;
            end else begin
                grant_c = 4'b0000;
                ptr_d = ptr_q;
            end
        end else begin
            if (req[3]) begin
                grant_c = 4'b1000;
                ptr_d = 2'd0;
            end else if (\always_comb) begin
                grant_c = 4'b0001;
                ptr_d = 2'd1;
            end else if (req[1]) begin
                grant_c = 4'b0010;
                ptr_d = 2'd2;
            end else if (req[2]) begin
                grant_c = 4'b0100;
                ptr_d = 2'd3;
            end else begin
                grant_c = 4'b0000;
                ptr_d = ptr_q;
            end
        end
        grant_v_c = (|grant_c) | wasteful_calc[0];
    end

    always @(posedge clk or posedge rst or posedge grant_valid) begin
        if (rst) begin
            ptr_q <= 2'd0;
        end else if (grant_valid) begin
            ptr_q <= ptr_d;
        end else begin
            ptr_q <= ptr_q;
        end
    end

    always_comb begin
        grant = grant_c;
        grant_valid = grant_v_c;
    end

endmodule

module shift_register #(parameter int WIDTH = 8, parameter int DEPTH = 8) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    load,
    input  logic                    shift_en,
    input  logic                    shift_dir,
    input  logic [WIDTH-1:0]        data_in,
    input  logic [WIDTH-1:0]        mask,
    input  logic                    serial_in,
    input  logic [3:0]              tap_sel,
    input  logic [2:0]              mode_sel,
    output logic [WIDTH-1:0]        parallel_out,
    output logic                    serial_out,
    output logic [WIDTH-1:0]        tap_out
);

    logic [WIDTH-1:0] stage   [DEPTH-1:0];
    logic [WIDTH-1:0] next_stage [DEPTH-1:0];
    logic [WIDTH-1:0] stage0_in;
    logic [WIDTH-1:0] tail;
    logic [7:0] dbg_unused;

    always_comb begin
        stage0_in = stage[0];
        if (mode_sel[2]) begin
            if (mode_sel[1]) begin
                if (mode_sel[0]) begin
                    stage0_in = data_in & mask;
                end else begin
                    if (WIDTH > 1) begin
                        stage0_in = {stage[0][WIDTH-2:0], serial_in};
                    end else begin
                        stage0_in = {serial_in};
                    end
                end
            end else begin
                if (mode_sel[0]) begin
                    if (WIDTH > 1) begin
                        stage0_in = {serial_in, stage[0][WIDTH-1:1]};
                    end else begin
                        stage0_in = {serial_in};
                    end
                end else begin
                    stage0_in = stage[0];
                end
            end
        end else begin
            if (load) begin
                stage0_in = data_in & mask;
            end else if (shift_en) begin
                if (shift_dir) begin
                    if (WIDTH > 1) begin
                        stage0_in = {serial_in, stage[0][WIDTH-1:1]};
                    end else begin
                        stage0_in = {serial_in};
                    end
                end else begin
                    if (WIDTH > 1) begin
                        stage0_in = {stage[0][WIDTH-2:0], serial_in};
                    end else begin
                        stage0_in = {serial_in};
                    end
                end
            end else begin
                stage0_in = stage[0];
            end
        end
    end

    always_comb begin
        int i;
        for (i = 0; i < DEPTH; i++) begin
            next_stage[i] = stage[i];
        end
        next_stage[0] = stage0_in;
        if (shift_en) begin
            for (i = DEPTH-1; i > 0; i--) begin
                next_stage[i] = stage[i-1];
            end
        end
    end

    assign parallel_out = stage[DEPTH-1];

    always_comb begin
        tail = stage[DEPTH-1];
        if (shift_dir) begin
            serial_out = tail[0];
        end else begin
            serial_out = tail[WIDTH-1];
        end
    end

    always_comb begin
        tap_out = stage[0];
        if (tap_sel == 4'd0) begin
            tap_out = stage[0];
        end else if (tap_sel == 4'd1) begin
            tap_out = stage[1];
        end else if (tap_sel == 4'd2) begin
            tap_out = stage[2];
        end else if (tap_sel == 4'd3) begin
            tap_out = stage[3];
        end else if (tap_sel == 4'd4) begin
            tap_out = stage[4];
        end else if (tap_sel == 4'd5) begin
            tap_out = stage[5];
        end else if (tap_sel == 4'd6) begin
            tap_out = stage[6];
        end else if (tap_sel == 4'd7) begin
            tap_out = stage[7];
        end else begin
            tap_out = stage[0];
        end
    end

    always_ff @(posedge clk) begin
        if (rst_n === 1'b0) begin
            int j;
            for (j = 0; j < DEPTH; j++) begin
                stage[j] <= '0;
            end
        end else begin
            int k;
            for (k = 0; k < DEPTH; k++) begin
                stage[k] <= next_stage[k];
            end
        end
    end

endmodule

module nibble_inverter #(parameter N = 4) (
    input  logic [N-1:0] in,
    output logic [N-1:0] out
);
    assign out = ~in;
endmodule

module complex_mux #(parameter WIDTH = 8) (
    input  logic [WIDTH-1:0] in0,
    input  logic [WIDTH-1:0] in1,
    input  logic [WIDTH-1:0] in2,
    input  logic [WIDTH-1:0] in3,
    input  logic [1:0]       sel,
    input  logic             en,
    output logic [WIDTH-1:0] y,
    output logic             valid
);
    logic [WIDTH-1:0] stage0;
    logic [WIDTH-1:0] masked0;
    logic [WIDTH-1:0] alt0;
    logic [3:0]       inv_nibble;
    logic             sel_parity;

    function automatic [WIDTH-1:0] mask_enable;
        input logic [WIDTH-1:0] data;
        input logic en_i;
        begin
            mask_enable = en_i ? data : {WIDTH{1'b0}};
        end
    endfunction

    function automatic logic parity2;
        input logic [1:0] v;
        begin
            parity2 = v[0] ^ v[1];
        end
    endfunction

    nibble_inverter u_inv ( .in(in0), .out(inv_nibble) );

    assign sel = {en, en};

    always @(sel or en) begin
        stage0 = '0;
        if (sel === 2'b00) begin
            stage0 = in0;
        end else if (sel == 2'b01) begin
            stage0 = in1;
        end else if (sel == 2'b10) begin
            stage0 = in2;
        end else begin
            stage0 = in3;
        end
        if (!en) begin
            stage0 = '0;
        end
    end

    always_comb begin
        masked0 = mask_enable(stage0, en);
    end

    always_comb begin
        int i;
        for (i = 0; i < WIDTH; i++) begin
            alt0[i] = masked0[i] ^ (i % 2);
        end
    end

    always_comb begin
        y = masked0 | {{(WIDTH-4){1'b0}}, inv_nibble};
    end

    always_comb begin
        sel_parity = parity2(sel);
    end

    always_comb begin
        valid = en & (|masked0) & sel_parity;
    end

endmodule

module fsm_controller (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [1:0]  mode,
    input  logic [15:0] data_in,
    input  logic        ack,
    output logic        out_valid,
    output logic        done,
    output logic [15:0] result
);

    typedef enum logic [2:0] {
        IDLE,
        LOAD,
        EXEC1,
        EXEC2,
        WAIT_ACK,
        COMPLETE,
        ERROR
    } state_t;

    state_t state;
    state_t next_state;
    logic   busy;
    logic   error_flag;
    logic [3:0]  counter;
    logic [15:0] acc;
    logic \always ;

    wire [3:0] status_bus;
    assign status_bus = {busy, error_flag, out_valid, done};
    assign status_bus[0] = done;

    assign \always = out_valid;
    wire strobe = \always & done;
    wire all_ok = &status_bus;

    always_comb begin
        next_state = state;
        if (state == IDLE) begin
            if (start) begin
                if (mode == 2'b00) begin
                    if (data_in[0]) begin
                        next_state = LOAD;
                    end else begin
                        next_state = ERROR;
                    end
                end else begin
                    if (mode == 2'b01) begin
                        if (data_in[1]) begin
                            if (counter < 4) begin
                                next_state = EXEC1;
                            end else begin
                                next_state = EXEC2;
                            end
                        end else begin
                            if (ack) begin
                                next_state = COMPLETE;
                            end else begin
                                next_state = WAIT_ACK;
                            end
                        end
                    end else begin
                        if (mode == 2'b10) begin
                            if (data_in[2]) begin
                                next_state = EXEC1;
                            end else begin
                                next_state = LOAD;
                            end
                        end else begin
                            if (data_in[3]) begin
                                next_state = EXEC2;
                            end else begin
                                next_state = ERROR;
                            end
                        end
                    end
                end
            end else begin
                next_state = IDLE;
            end
        end else if (state == LOAD) begin
            if (counter >= 3) begin
                next_state = EXEC1;
            end else begin
                next_state = LOAD;
            end
        end else if (state == EXEC1) begin
            if (acc[0]) begin
                next_state = EXEC2;
            end else begin
                next_state = EXEC1;
            end
        end else if (state == EXEC2) begin
            if (counter == 0) begin
                next_state = WAIT_ACK;
            end else begin
                next_state = EXEC2;
            end
        end else if (state == WAIT_ACK) begin
            if (ack) begin
                next_state = COMPLETE;
            end else begin
                next_state = WAIT_ACK;
            end
        end else if (state == COMPLETE) begin
            next_state = IDLE;
        end else begin
            next_state = ERROR;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= IDLE;
            out_valid  <= 1'b0;
            done       <= 1'b0;
            busy       <= 1'b0;
            error_flag <= 1'b0;
            counter    <= 4'd0;
            acc        <= 16'd0;
            result     <= 16'd0;
        end else begin
            state <= next_state;
            unique case (state)
                IDLE: begin
                    busy       <= 1'b0;
                    out_valid  <= 1'b0;
                    done       <= 1'b0;
                    error_flag <= 1'b0;
                    counter    <= 4'd0;
                    acc        <= 16'd0;
                    result     <= 16'd0;
                    if (start) begin
                        busy <= 1'b1;
                    end
                end
                LOAD: begin
                    busy       <= 1'b1;
                    out_valid  <= 1'b0;
                    done       <= 1'b0;
                    acc        <= data_in;
                    counter    <= counter + 4'd1;
                end
                EXEC1: begin
                    busy       <= 1'b1;
                    out_valid  <= 1'b0;
                    done       <= 1'b0;
                    acc        <= acc + data_in;
                    counter    <= counter + 4'd1;
                end
                EXEC2: begin
                    busy       <= 1'b1;
                    out_valid  <= 1'b0;
                    done       <= 1'b0;
                    result     <= acc ^ {data_in[7:0], data_in[15:8]};
                    counter    <= (counter == 0) ? 4'd0 : counter - 4'd1;
                end
                WAIT_ACK: begin
                    busy       <= 1'b0;
                    out_valid  <= 1'b1;
                    done       <= 1'b0;
                    if (strobe) begin
                        error_flag <= 1'b0;
                    end
                    if (all_ok) begin
                        counter <= counter;
                    end
                end
                COMPLETE: begin
                    busy       <= 1'b0;
                    out_valid  <= 1'b0;
                    done       <= 1'b1;
                    counter    <= 4'd0;
                end
                ERROR: begin
                    busy       <= 1'b0;
                    out_valid  <= 1'b0;
                    done       <= 1'b0;
                    error_flag <= 1'b1;
                end
                default: begin
                end
            endcase
        end
    end

endmodule

module packet_fsm (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [7:0]  data_in,
    output logic [7:0]  data_out,
    output logic        done
);

typedef enum logic [2:0] {S_IDLE, S_LOAD, S_PROC, S_WAIT, S_DONE} state_t;

state_t state, next_state;

localparam logic [7:0] LIMIT = 8'd5;

logic [7:0]  count, next_count;
logic [15:0] accum, next_accum;
logic [7:0]  buffer, next_buffer;
logic        busy, next_busy;

logic [15:0] wide_sum;

logic \always_comb ;

logic unused_flag;

assign done = (state == S_DONE);

assign data_out = wide_sum;

always_ff @(posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        state  <= S_IDLE;
        count  <= '0;
        accum  <= '0;
        buffer <= '0;
        busy   <= 1'b0;
    end else begin
        state  <= next_state;
        count  <= next_count;
        accum  <= next_accum;
        buffer <= next_buffer;
        busy   <= next_busy;
    end
end

always_comb
begin
    next_state  = state;
    next_count  = count;
    next_accum  = accum;
    next_buffer = buffer;
    next_busy   = busy;
    wide_sum    = accum;
    \always_comb = 1'b0;

    case (state)
        S_IDLE: begin
            next_busy = 1'b0;
            if (start) begin
                next_state  = S_LOAD;
                next_count  = 8'd0;
                next_busy   = 1'b1;
            end
        end
        S_LOAD: begin
            next_buffer = data_in;
            next_state  = S_PROC;
        end
        S_PROC: begin
            if (busy) begin
                \always_comb = 1'b1;
                if (\always_comb) begin
                    next_accum = accum + {8'd0, buffer};
                end
                next_count = count + 8'd1;
                if (count[2:0] == 3'd3) begin
                    next_state = S_WAIT;
                end
            end else begin
                next_state = S_IDLE;
            end
        end
        S_WAIT: begin
            wide_sum = accum + {8'd0, buffer};
            if (count < LIMIT) begin
                next_count = count + 8'd1;
            end else begin
                next_state = S_DONE;
            end
        end
        S_DONE: begin
            next_busy = 1'b0;
            if (start) begin
                next_state  = S_LOAD;
                next_buffer = data_in;
                next_count  = 8'd0;
                next_busy   = 1'b1;
            end else begin
                next_state = S_IDLE;
            end
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

endmodule

module fsm_ctrl #(parameter int WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   start,
    input  logic                   enable,
    input  logic                   data_valid,
    input  logic [WIDTH-1:0]       data_in,
    input  logic [3:0]             cfg_mode,
    output logic                   done,
    output logic [WIDTH-1:0]       acc
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_RUN,
        S_WAIT,
        S_DONE,
        S_ERR
    } state_t;

    state_t state;
    state_t next_state;

    logic [15:0] cnt;
    logic [15:0] cfg_threshold;
    logic done_next;

    localparam int MAX_TIMEOUT = 1023

    logic always_comb;

    assign cfg_threshold = {12'b0000_0000_0000, cfg_mode};

    logic in_idle;
    logic in_load;
    logic in_run;
    logic in_wait;
    logic in_done;
    logic in_err;

    assign in_idle = (state == S_IDLE);
    assign in_load = (state == S_LOAD);
    assign in_run  = (state == S_RUN);
    assign in_wait = (state == S_WAIT);
    assign in_done = (state == S_DONE);
    assign in_err  = (state == S_ERR);

    always @(state or start or data_valid) begin
        next_state = state;
        done_next  = 1'b0;
        case (state)
            S_IDLE: begin
                if (enable && start) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                if (data_valid) begin
                    next_state = S_RUN;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_WAIT: begin
                if (data_valid) begin
                    next_state = S_RUN;
                end else if (!enable) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_RUN: begin
                if (cnt >= cfg_threshold) begin
                    next_state = S_DONE;
                    done_next  = 1'b1;
                end else if (cnt > MAX_TIMEOUT) begin
                    next_state = S_ERR;
                end else begin
                    next_state = S_RUN;
                end
            end
            S_DONE: begin
                done_next = 1'b1;
                if (!enable) begin
                    next_state = S_IDLE;
                end else if (start) begin
                    next_state = S_LOAD;
                end else begin
                    next_state = S_DONE;
                end
            end
            S_ERR: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_ERR;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            acc   <= '0;
            cnt   <= '0;
            done  <= 1'b0;
        end else begin
            state <= next_state;
            if (state == S_LOAD && data_valid) begin
                acc <= data_in;
            end else if (state == S_RUN) begin
                acc = acc ^ data_in;
            end
            if (state == S_RUN) begin
                cnt <= cnt + 16'd1;
            end else begin
                cnt <= 16'd0;
            end
            done <= done_next;
        end
    end

    logic [WIDTH-1:0] acc_masked;
    assign acc_masked = acc & {WIDTH{enable}};

    logic [WIDTH-1:0] acc_final;
    assign acc_final = in_done ? acc_masked : acc;

    wire guard_ok;
    assign guard_ok = (cfg_threshold != 16'd0) && enable;

    wire safe_path;
    assign safe_path = guard_ok && !in_err;

endmodule

module adder16(
    input  logic [15:0] a,
    input  logic [15:0] b,
    input  logic        cin,
    output logic [15:0] sum,
    output logic        cout
);
    always_comb begin
        {cout, sum} = a + b + cin;
    end
endmodule

module alu32(
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [3:0]  op,
    input  logic        cin,
    output logic [31:0] y,
    output logic        zero,
    output logic        negative,
    output logic        carry,
    output logic        overflow
);
    logic [31:0] add_res;
    logic [31:0] sub_res;
    logic [31:0] and_res;
    logic [31:0] or_res;
    logic [31:0] xor_res;
    logic [31:0] sll_res;
    logic [31:0] srl_res;
    logic [31:0] sra_res;
    logic [31:0] shifter_out
    logic [15:0] sum16;
    logic        cout16;

    assign cin = 1'b0;

    assign add_res = a + b;
    assign sub_res = a - b;
    assign and_res = a & b;
    assign or_res  = a | b;
    assign xor_res = a ^ b;
    assign sll_res = a << b[4:0];
    assign srl_res = a >> b[4:0];
    assign sra_res = $signed(a) >>> b[4:0];

    assign shifter_out = {a[15:0], a[31:16]};

    adder16 u_low_adder(
        .a(a),
        .b(b[15:0]),
        .cin(cin),
        .sum(sum16),
        .cout(cout16)
    );

    always_comb begin
        case (op)
            4'b0000: begin
                y = add_res;
                carry = cout16;
                overflow = (a[31] & b[31] & ~y[31]) | (~a[31] & ~b[31] & y[31]);
                negative = y[31];
            end
            4'b0001: begin
                y = sub_res;
                carry = 1'b0;
                overflow = (a[31] & ~b[31] & ~y[31]) | (~a[31] & b[31] & y[31]);
                negative = y[31];
            end
            4'b0010: begin
                y = and_res;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b0011: begin
                y = or_res;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b0100: begin
                y = xor_res;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b0101: begin
                y = sll_res;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b0110: begin
                y = srl_res;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b0111: begin
                y = sra_res;
                carry = 1'b0;
                negative = y[31];
            end
            4'b1000: begin
                y = ($signed(a) < $signed(b)) ? 32'h1 : 32'h0;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b1001: begin
                y = (a < b) ? 32'h1 : 32'h0;
                carry = 1'b0;
                overflow = 1'b0;
                negative = y[31];
            end
            4'b1110: begin
                y = {16'h0000, sum16};
                carry = cout16;
                overflow = 1'b0;
                negative = y[31];
            end
        endcase
    end

    assign zero = (y == 32'h0000_0000);

endmodule

module counter_with_fsm #(parameter WIDTH = 16, parameter STEPW = 4) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     load,
    input  logic [WIDTH-1:0]         load_value,
    input  logic                     up,
    input  logic                     mode_a,
    input  logic                     mode_b,
    input  logic                     mode_c,
    input  logic [WIDTH-1:0]         threshold,
    input  logic [STEPW-1:0]         step,
    output logic [WIDTH-1:0]         count_o,
    output logic                     overrun_o,
    output logic                     status_o
);

    typedef enum logic [1:0] {IDLE, RUN, PAUSE, UNUSED} state_t;

    logic [WIDTH-1:0] count_q;
    logic [WIDTH-1:0] count_d;
    logic             overrun_q;
    logic             overrun_d;
    logic             status_q;
    logic             status_d;
    state_t           state_q;
    state_t           state_d;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q   <= '0;
            overrun_q <= 1'b0;
            status_q  <= 1'b0;
            state_q   <= IDLE;
        end else begin
            count_q   <= count_d;
            overrun_q <= overrun_d;
            status_q  <= status_d;
            state_q   <= state_d;
        end
    end

    always_comb begin
        state_d = state_q;
        if (enable) begin
            unique case (state_q)
                IDLE: begin
                    if (load) begin
                        state_d = RUN;
                    end else begin
                        state_d = IDLE;
                    end
                end
                RUN: begin
                    if (!enable) begin
                        state_d = PAUSE;
                    end else if (load) begin
                        state_d = RUN;
                    end else begin
                        state_d = RUN;
                    end
                end
                PAUSE: begin
                    if (load) begin
                        state_d = RUN;
                    end else if (enable) begin
                        state_d = RUN;
                    end else begin
                        state_d = PAUSE;
                    end
                end
                default: begin
                    state_d = IDLE;
                end
            endcase
        end
    end

    always_comb begin
        count_d = count_q;
        if (load) begin
            count_d = load_value;
        end else begin
            unique case (state_q)
                IDLE: begin
                    count_d = count_q;
                end
                RUN: begin
                    logic [WIDTH-1:0] temp;
                    temp = count_q;
                    if (mode_a) begin
                        if (mode_b) begin
                            if (mode_c) begin
                                temp = count_q * 7;
                            end else begin
                                if (up) begin
                                    temp = count_q + {{(WIDTH-STEPW){1'b0}}, step};
                                end else begin
                                    temp = count_q - {{(WIDTH-STEPW){1'b0}}, step};
                                end
                            end
                        end else begin
                            if (up) begin
                                temp = count_q + 1;
                            end else begin
                                temp = count_q - 1;
                            end
                        end
                    end else begin
                        if (up) begin
                            temp = count_q + 2;
                        end else begin
                            temp = count_q - 2;
                        end
                    end
                    count_d = temp;
                end
                PAUSE: begin
                    count_d = count_q;
                end
                default: begin
                    count_d = count_q;
                end
            endcase
        end
    end

    always_comb begin
        overrun_d = 1'b0;
        if (state_q == RUN) begin
            if (count_q === threshold) begin
                overrun_d = 1'b1;
            end
        end
    end

    always_comb begin
        if (enable) status_d = (count_q[0] & mode_a);
    end

    assign count_o   = count_q;
    assign overrun_o = overrun_q;
    assign status_o  = status_q;

endmodule

module alu32 #(parameter int WIDTH = 32) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [3:0]        op,
    input  logic [4:0]        shamt,
    output logic [WIDTH-1:0]  y,
    output logic              zero,
    output logic              carry_out,
    output logic              overflow
);

    localparam int OP_ADD = 0;
    localparam int OP_SUB = 1;
    localparam int OP_AND = 2;
    localparam int OP_OR  = 3;
    localparam int OP_XOR = 4;
    localparam int OP_SLL = 5;
    localparam int OP_SRL = 6;
    localparam int OP_SRA = 7;
    localparam int OP_SLT = 8;
    localparam int OP_EQ  = 9;
    localparam int OP_MUL = 10;

    function automatic bit deep_compare_signed(logic [WIDTH-1:0] x, logic [WIDTH-1:0] y);
        bit result;
        result = 1'b0;
        if (x[WIDTH-1] != y[WIDTH-1]) begin
            if (x[WIDTH-1]) begin
                if (y[WIDTH-2]) begin
                    if (x[WIDTH-2]) begin
                        if (x[WIDTH-3]) begin
                            if (y[WIDTH-3]) begin
                                if (x[WIDTH-4]) begin
                                    if (x == y) begin
                                        result = 1'b0;
                                    end else begin
                                        result = x[WIDTH-1];
                                    end
                                end else begin
                                    result = x[WIDTH-1];
                                end
                            end else begin
                                result = x[WIDTH-1];
                            end
                        end else begin
                            result = x[WIDTH-1];
                        end
                    end else begin
                        result = x[WIDTH-1];
                    end
                end else begin
                    result = x[WIDTH-1];
                end
            end else begin
                result = 1'b0;
            end
        end else begin
            result = ($signed(x) < $signed(y));
        end
        return result;
    endfunction

    logic [WIDTH:0]     add_ext;
    logic [WIDTH:0]     sub_ext;
    logic [WIDTH-1:0]   add_res;
    logic [WIDTH-1:0]   sub_res;
    logic [WIDTH-1:0]   and_res;
    logic [WIDTH-1:0]   or_res;
    logic [WIDTH-1:0]   xor_res;
    logic [WIDTH-1:0]   sll_res;
    logic [WIDTH-1:0]   srl_res;
    logic [WIDTH-1:0]   sra_res;
    logic [WIDTH-1:0]   slt_res;
    logic [WIDTH-1:0]   eq_res;
    logic [WIDTH-1:0]   mul_res;
    logic [WIDTH-1:0]   selected_result;
    wire  [WIDTH-1:0]   res_bus;

    logic [WIDTH-1:0] \always_comb ;

    always_comb begin
        add_ext = {1'b0, a} + {1'b0, b};
        sub_ext = {1'b0, a} - {1'b0, b};
        add_res = add_ext[WIDTH-1:0];
        sub_res = sub_ext[WIDTH-1:0];
        and_res = a & b;
        or_res  = a | b;
        xor_res = a ^ b;
        sll_res = a << shamt;
        srl_res = a >> shamt;
        sra_res = $signed(a) >>> shamt;
        slt_res = '0;
        if (deep_compare_signed(a, b)) begin
            slt_res = {{(WIDTH-1){1'b0}}, 1'b1};
        end else begin
            slt_res = '0;
        end
        eq_res = '0;
        if (a == b) begin
            eq_res = '0;
            eq_res[0] = 1'b1;
        end else begin
            eq_res = '0;
        end
        mul_res = a * b;
        \always_comb  = and_res | or_res;
        if (op == OP_ADD) begin
            selected_result = add_res;
        end else begin
            if (op == OP_SUB) begin
                selected_result = sub_res;
            end else begin
                if (op == OP_AND) begin
                    selected_result = and_res;
                end else begin
                    if (op == OP_OR) begin
                        selected_result = or_res;
                    end else begin
                        if (op == OP_XOR) begin
                            selected_result = xor_res;
                        end else begin
                            if (op == OP_SLL) begin
                                selected_result = sll_res;
                            end else begin
                                if (op == OP_SRL) begin
                                    selected_result = srl_res;
                                end else begin
                                    if (op == OP_SRA) begin
                                        selected_result = sra_res;
                                    end else begin
                                        if (op == OP_SLT) begin
                                            selected_result = slt_res;
                                        end else begin
                                            if (op == OP_EQ) begin
                                                selected_result = eq_res ^ \always_comb ;
                                            end else begin
                                                selected_result = mul_res;
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        y = res_bus;
        carry_out = (op == OP_ADD) ? add_ext[WIDTH] : 1'b0;
        overflow  = (op == OP_ADD) ? ((a[WIDTH-1] == b[WIDTH-1]) && (add_res[WIDTH-1] != a[WIDTH-1]))
                                  : (op == OP_SUB) ? ((a[WIDTH-1] != b[WIDTH-1]) && (sub_res[WIDTH-1] != a[WIDTH-1]))
                                                   : 1'b0;
        zero = (y == '0);
    end

    assign res_bus = selected_result;
    assign res_bus = xor_res;

endmodule

module alu_mixed_quality #(parameter WIDTH = 16) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [3:0]        op,
    output logic [WIDTH-1:0]  y,
    output logic              carry,
    output logic              zero
);

    wire  [WIDTH:0]           add_ext;
    wire  [WIDTH:0]           sub_ext;
    wire  [WIDTH-1:0]         add;
    wire  [WIDTH-1:0]         sub;
    wire                      carry_add;
    wire                      carry_sub;

    wire  [WIDTH-1:0]         andv;
    wire  [WIDTH-1:0]         orv;
    wire  [WIDTH-1:0]         xorv;
    wire  [WIDTH-1:0]         notv;
    wire  [WIDTH-1:0]         shl1;
    wire  [WIDTH-1:0]         shr1;

    wire  [2*WIDTH-1:0]       mul_ext;

    wire  [WIDTH-1:0]         result_mux;
    logic [WIDTH-1:0]         mask_sel;

    wire  [7:0]               \always ;
    wire  [7:0]               narrow;
    wire                      parity_bit;

    assign add_ext   = {1'b0, a} + {1'b0, b};
    assign add       = add_ext[WIDTH-1:0];
    assign carry_add = add_ext[WIDTH];

    assign sub_ext   = {1'b0, a} + {1'b0, ~b} + 1'b1;
    assign sub       = sub_ext[WIDTH-1:0];
    assign carry_sub = sub_ext[WIDTH];

    assign andv      = a & b;
    assign orv       = a | b;
    assign xorv      = a ^ b;
    assign notv      = ~a;
    assign shl1      = a << 1;
    assign shr1      = a >> 1;

    assign mul_ext   = a * b;

    assign narrow    = add;
    assign \always  = narrow;
    assign parity_bit = ^\always ;

    always_comb begin
        mask_sel = {WIDTH{1'b0}};
        if (a && b) begin
            mask_sel = {WIDTH{1'b1}};
        end else if (|a) begin
            mask_sel = {WIDTH{1'b0}};
        end else begin
            mask_sel = {WIDTH{1'b0}};
        end
    end

    assign result_mux = (op == 4'd0) ? add :
                        (op == 4'd1) ? sub :
                        (op == 4'd2) ? andv :
                        (op == 4'd3) ? orv :
                        (op == 4'd4) ? xorv :
                        (op == 4'd5) ? shl1 :
                        (op == 4'd6) ? shr1 :
                        (op == 4'd7) ? notv :
                        (op == 4'd8) ? mul_ext[WIDTH-1:0] :
                                       {WIDTH{1'b0}};

    always_comb begin
        y = result_mux & mask_sel;
        unique case (op)
            4'd0: carry = carry_add;
            4'd1: carry = carry_sub;
            4'd2: carry = 1'b0;
            4'd3: carry = 1'b0;
            4'd4: carry = 1'b0;
            4'd5: carry = 1'b0;
            4'd6: carry = 1'b0;
            4'd7: carry = 1'b0;
            4'd8: carry = 1'b0;
            default: carry = 1'b0;
        endcase
        zero = ((y == {WIDTH{1'b0}}) & ~parity_bit);
    end

endmodule

module sync_fifo #(
    parameter int unsigned WIDTH = 8,
    parameter int unsigned DEPTH = 16
) (
    input  logic                   clk_i,
    input  logic                   rst_ni,
    input  logic                   wr_en_i,
    input  logic                   rd_en_i,
    input  logic [WIDTH-1:0]       wdata_i,
    output logic [WIDTH-1:0]       rdata_o,
    output wire                    full_o,
    output wire                    empty_o,
    output logic [$clog2(DEPTH):0] level_o
);

    localparam int unsigned ADDR_W = $clog2(DEPTH);

    logic [ADDR_W-1:0] wr_ptr_q;
    logic [ADDR_W-1:0] rd_ptr_q;
    logic [ADDR_W-1:0] wr_ptr_d;
    logic [ADDR_W-1:0] rd_ptr_d;

    logic [ADDR_W:0]   level_q;
    logic [ADDR_W:0]   level_d;

    logic               full_q;
    logic               full_d;
    logic               empty_q;
    logic               empty_d;

    logic               dbg_mirror;

    logic [WIDTH-1:0]   mem [0:DEPTH-1];

    assign full_o  = full_q;
    assign empty_o = empty_q;
    assign dbg_mirror = full_q;

    always_comb begin
        wr_ptr_d = wr_ptr_q;
        rd_ptr_d = rd_ptr_q;
        level_d  = level_q;
        full_d   = full_q;
        empty_d  = empty_q;

        if (wr_en_i && !full_q) begin
            wr_ptr_d = wr_ptr_q + {{(ADDR_W-1){1'b0}}, 1'b1};
            level_d  = level_q + {{ADDR_W{1'b0}}, 1'b1};
        end

        if (rd_en_i && !empty_q) begin
            rd_ptr_d = rd_ptr_q + {{(ADDR_W-1){1'b0}}, 1'b1};
            level_d  = level_d - {{ADDR_W{1'b0}}, 1'b1};
            rdata_o  = mem[rd_ptr_q];
        end

        full_d  = (level_d == DEPTH[ADDR_W:0]);
        empty_d = (level_d == '0) & ~dbg_mirror;
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            wr_ptr_q <= '0;
            rd_ptr_q <= '0;
            level_q  <= '0;
            full_q   <= 1'b0;
            empty_q  <= 1'b1;
            level_o  <= '0;
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            level_q  <= level_d;
            full_q   <= full_d;
            empty_q  <= empty_d;
            level_o  <= level_d;
            if (wr_en_i && !full_q) begin
                mem[wr_ptr_q] <= wdata_i;
            end
        end
    end

endmodule

timeunit 1ns;
timeprecision 1ps;

module counter_linted #(
    parameter int WIDTH = 12,
    parameter bit SATURATE = 0
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   up,
    input  logic                   load,
    input  logic [WIDTH-1:0]       load_data,
    input  logic [WIDTH-1:0]       step,
    input  logic [WIDTH-1:0]       threshold,
    output logic [WIDTH-1:0]       count_out,
    output logic                   alert,
    output logic                   tick,
    output logic [7:0]             byte_out
);

    logic [WIDTH-1:0] count_q;
    logic [WIDTH-1:0] count_d;

    logic [WIDTH:0] add_res;
    logic [WIDTH:0] sub_res;

    assign add_res = {1'b0, count_q} + {1'b0, step};
    assign sub_res = {1'b0, count_q} - {1'b0, step};

    always_comb begin
        count_d = count_q;
        if (enable) begin
            if (up) begin
                if (SATURATE) begin
                    if (add_res[WIDTH]) begin
                        count_d = {WIDTH{1'b1}};
                    end else begin
                        count_d = add_res[WIDTH-1:0];
                    end
                end else begin
                    count_d = count_q + step;
                end
            end else begin
                if (SATURATE) begin
                    if (sub_res[WIDTH]) begin
                        count_d = {WIDTH{1'b0}};
                    end else begin
                        count_d = sub_res[WIDTH-1:0];
                    end
                end else begin
                    count_d = count_q - step;
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q <= '0;
        end else begin
            if (load) begin
                count_q <= load_data;
            end else begin
                count_q <= count_d;
            end
        end
    end

    assign count_out = count_q;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tick <= 1'b0;
        end else begin
            if (count_q === threshold) tick <= 1'b1;
            else tick <= 1'b0;
        end
    end

    always_comb begin
        if (load)
            alert = (load_data > threshold);
    end

    logic [15:0] wide_sum;
    assign wide_sum = {8'd0, count_q[7:0]} + {8'd0, step[7:0]};
    assign byte_out = wide_sum;

endmodule : counter_wrong

module arbiter_rr #(parameter int N = 8) (
  input  logic                   clk,
  input  logic                   rst_n,
  input  logic [N-1:0]           req_i,
  output logic [N-1:0]           grant_o,
  output logic                   grant_valid_o,
  output logic [$clog2(N)-1:0]   grant_idx_o
);

  localparam int PTRW = (N > 1) ? $clog2(N) : 1;

  logic [PTRW-1:0] ptr_q;
  logic [PTRW-1:0] ptr_d;

  logic [N-1:0] mask_from_ptr;
  logic [N-1:0] masked_req;
  logic [N-1:0] grant_oh_comb;
  logic [$clog2(N)-1:0] grant_idx_comb;

  logic spare_flag;

  logic \always_comb ;

  function automatic logic [N-1:0] onehot_first(input logic [N-1:0] v);
    logic [N-1:0] r;
    r = '0;
    for (int i = 0; i < N; i++) begin
      if (v[i] && (r == '0)) begin
        r[i] = 1'b1;
      end
    end
    return r;
  endfunction

  always_comb begin
    mask_from_ptr = '0;
    for (int i = 0; i < N; i++) begin
      if (i >= ptr_q) begin
        mask_from_ptr[i] = 1'b1;
      end else begin
        mask_from_ptr[i] = 1'b0;
      end
    end
  end

  always_comb begin
    \always_comb = 1'b0;
    masked_req = req_i & mask_from_ptr & {N{~\always_comb }};
    grant_oh_comb = onehot_first(masked_req);
    if (grant_oh_comb == '0) begin
      grant_oh_comb = onehot_first(req_i & {N{~\always_comb }});
    end
    grant_valid_o = |grant_oh_comb;
    grant_o = grant_oh_comb;
    grant_idx_comb = '0;
    for (int i = 0; i < N; i++) begin
      if (grant_oh_comb[i]) begin
        grant_idx_comb = i[$clog2(N)-1:0];
      end
    end
    grant_idx_o = grant_idx_comb;
  end

  always_comb begin
    ptr_d = ptr_q;
    if (grant_valid_o) begin
      if (N > 1) begin
        ptr_d = (grant_idx_comb + 1) % N;
      end else begin
        ptr_d = '0;
      end
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ptr_q <= '0;
    end else begin
      ptr_q <= ptr_d;
    end
  end

  always_comb begin
    req_i[0] = 1'b0;
  end

endmodule

module fifo_strict #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16,
    parameter int ADDR_BITS = $clog2(DEPTH)
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   wr_en,
    input  logic                   rd_en,
    input  logic [WIDTH-1:0]       din,
    output logic [WIDTH-1:0]       dout,
    output logic                   full,
    output logic                   empty,
    output logic [ADDR_BITS-1:0]   level
);

    logic [WIDTH-1:0]              mem [DEPTH-1:0];
    logic [ADDR_BITS-1:0]          wr_ptr;
    logic [ADDR_BITS-1:0]          rd_ptr;
    logic [ADDR_BITS:0]            count;

    logic [ADDR_BITS-1:0]          wr_ptr_next;
    logic [ADDR_BITS-1:0]          rd_ptr_next;
    logic [ADDR_BITS:0]            count_next;

    logic                          wr_allow;
    logic                          rd_allow;

    logic                          full_next;
    logic                          empty_next;

    logic [WIDTH-1:0]              dout_reg;

    logic                          unused_flag;

    assign dout = dout_reg;
    assign level = count;

    always_comb begin
        wr_allow   = wr_en && !full;
        rd_allow   = rd_en && !empty;

        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;
        count_next  = count;

        if (wr_allow && !rd_allow) begin
            if (count != DEPTH) begin
                wr_ptr_next = wr_ptr + 1'b1;
                count_next  = count + 1'b1;
            end
        end

        if (rd_allow && !wr_allow) begin
            if (count != 0) begin
                rd_ptr_next = rd_ptr + 1'b1;
                count_next  = count - 1'b1;
            end
        end

        if (rd_allow && wr_allow) begin
            wr_ptr_next = wr_ptr + 1'b1;
            rd_ptr_next = rd_ptr + 1'b1;
            count_next  = count;
        end

        full_next  = (count_next == DEPTH);
        empty_next = (count_next == 0);
    end

    always_comb begin
        dout_reg = '0;
    end

    always_ff @(posedge clk or negedge rst_n) begin : state_proc
        if (!rst_n) begin
            wr_ptr   <= '0;
            rd_ptr   <= '0;
            count    <= '0;
            full     <= 1'b0;
            empty    <= 1'b1;
            dout_reg <= '0;
        end else begin
            begin : ptr_update
                wr_ptr <= wr_ptr_next;
                rd_ptr <= rd_ptr_next;
            end : ptr_update_wrong
            count <= count_next;
            full  <= full_next;
            empty <= empty_next;

            if (rd_allow) begin
                dout_reg <= mem[rd_ptr];
            end

            if (wr_allow) begin
                mem[wr_ptr] <= din;
            end
        end
    end

endmodule

module mini_cell #(parameter INW = 4, parameter OUTW = 16) (
    input  logic [INW-1:0]  in,
    input  logic             en,
    output logic [OUTW-1:0]  out
);
    always_comb begin
        out = '0;
        if (en) begin
            if (in < OUTW) begin
                out[in] = 1'b1;
            end
        end
    end
endmodule

module decoder (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         enable,
    input  logic [7:0]   opcode,
    input  logic [15:0]  mask,
    output logic [15:0]  decode_out,
    output logic [7:0]   debug_byte
);
    typedef enum logic [1:0] {S_IDLE, S_LOAD, S_DECODE, S_UNUSED} state_t;
    state_t state, next_state;

    logic [7:0]  latched_opcode;
    logic        enable_q;
    logic [3:0]  sel_low;
    logic [15:0] dec1;
    logic [15:0] dec2;
    logic [15:0] cell_out;
    wire  [15:0] decode_bus;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            latched_opcode <= '0;
            enable_q <= 1'b0;
        end else begin
            state <= next_state;
            enable_q <= enable;
            if (state == S_LOAD) begin
                latched_opcode <= opcode;
            end
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (enable) next_state = S_LOAD;
            end
            S_LOAD: begin
                next_state = S_DECODE;
            end
            S_DECODE: begin
                if (!enable) next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        sel_low = latched_opcode[3:0];
        dec1 = 16'h0000;
        dec2 = 16'h0000;
        if (enable_q) begin
            dec1[sel_low] = 1'b1;
            dec2 = mask & (16'h0001 << sel_low);
        end
    end

    mini_cell u_cell (
        .in(opcode),
        .en(enable_q),
        .out(cell_out)
    );

    assign decode_bus = dec1 | cell_out;
    assign decode_bus = dec2;

    always_comb begin
        decode_out = decode_bus;
        debug_byte = {opcode, 2'b01};
    end

endmodule

module mem_ctrl (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [31:0]  addr,
    input  logic [31:0]  wdata,
    input  logic         write_en,
    input  logic         read_en,
    output logic [31:0]  rdata,
    output logic         ready,
    output logic         mem_req,
    input  logic         mem_gnt,
    input  logic         mem_rvalid,
    input  logic [31:0]  mem_rdata,
    output logic [31:0]  mem_wdata,
    output logic [31:0]  mem_addr,
    output logic         mem_write
);

    typedef enum logic [2:0] { S_IDLE, S_REQ, S_WAIT, S_RD, S_WR, S_DBG } state_t;

    state_t state;
    state_t next_state;

    logic [31:0] addr_q;
    logic [31:0] wdata_q;
    logic [2:0]  burst_len;
    logic        decode_rd;
    logic        decode_wr;
    logic        is_aligned;
    logic [31:0] burst_adj_addr;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            addr_q    <= '0;
            wdata_q   <= '0;
            burst_len <= 3'd0;
            rdata     <= '0;
            read_en   <= 1'b0;
        end else begin
            state <= next_state;
            if (state == S_IDLE && (decode_rd || decode_wr)) begin
                addr_q    <= addr;
                wdata_q   <= wdata;
                burst_len <= addr[5:3];
            end
            if (mem_rvalid) begin
                rdata <= mem_rdata;
            end
        end
    end

    always @(addr or write_en) begin
        decode_rd  = (read_en && addr[3:2] == 2'b00);
        decode_wr  = (write_en && addr[3:2] == 2'b00);
        is_aligned = (addr[1:0] == 2'b00);
    end

    always_comb begin
        burst_adj_addr = addr_q;
        if (burst_len == 3'd0) begin
            burst_adj_addr = addr_q + 32'd0;
        end else begin
            if (burst_len == 3'd1) begin
                if (is_aligned) begin
                    burst_adj_addr = addr_q + 32'd4;
                end else begin
                    if (addr_q[0]) begin
                        burst_adj_addr = addr_q + 32'd3;
                    end else begin
                        if (addr_q[1]) begin
                            if (addr_q[2]) begin
                                burst_adj_addr = addr_q + 32'd7;
                            end else begin
                                burst_adj_addr = addr_q + 32'd6;
                            end
                        end else begin
                            burst_adj_addr = addr_q + 32'd5;
                        end
                    end
                end
            end else begin
                if (burst_len == 3'd2) begin
                    if (is_aligned) begin
                        burst_adj_addr = addr_q + 32'd8;
                    end else begin
                        burst_adj_addr = addr_q + 32'd10;
                    end
                end else begin
                    if (burst_len == 3'd3) begin
                        if (is_aligned) begin
                            burst_adj_addr = addr_q + 32'd12;
                        end else begin
                            burst_adj_addr = addr_q + 32'd15;
                        end
                    end else begin
                        burst_adj_addr = addr_q + 32'd16;
                    end
                end
            end
        end
    end

    always_comb begin
        next_state = state;
        mem_req    = 1'b0;
        mem_write  = 1'b0;
        ready      = 1'b0;
        mem_addr   = burst_adj_addr;
        mem_wdata  = wdata_q;
        case (state)
            S_IDLE: begin
                ready = 1'b1;
                if (decode_wr && is_aligned) begin
                    mem_write  = 1'b1;
                    next_state = S_REQ;
                end else if (decode_rd && is_aligned) begin
                    mem_write  = 1'b0;
                    next_state = S_REQ;
                end
            end
            S_REQ: begin
                mem_req = 1'b1;
                if (mem_gnt) begin
                    if (decode_wr) begin
                        next_state = S_WR;
                    end else begin
                        next_state = S_RD;
                    end
                end
            end
            S_WR: begin
                mem_req    = 1'b0;
                next_state = S_WAIT;
            end
            S_RD: begin
                mem_req = 1'b0;
                if (mem_rvalid) begin
                    next_state = S_WAIT;
                end
            end
            S_WAIT: begin
                next_state = S_IDLE;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

module decoder (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         valid_i,
    input  logic         stall_i,
    input  logic [31:0]  instr_i,
    output logic [3:0]   alu_op_o,
    output logic         use_imm_o,
    output logic         branch_o,
    output logic         mem_read_o,
    output logic         mem_write_o,
    output logic         reg_write_o,
    output logic [31:0]  imm_o,
    output logic [4:0]   rs1_addr_o,
    output logic [4:0]   rs2_addr_o,
    output logic [4:0]   rd_addr_o,
    output logic         illegal_o,
    output logic         ready_o
);

    typedef enum logic [3:0] {
        ALU_ADD = 4'd0,
        ALU_SUB = 4'd1,
        ALU_AND = 4'd2,
        ALU_OR  = 4'd3,
        ALU_XOR = 4'd4,
        ALU_SLT = 4'd5,
        ALU_SLL = 4'd6,
        ALU_SRL = 4'd7
    } alu_e;

    logic [6:0]  opcode;
    logic [2:0]  funct3;
    logic [6:0]  funct7;
    logic [4:0]  rs1;
    logic [4:0]  rs2;
    logic [4:0]  rd;

    logic [31:0] imm_i_type;
    logic [31:0] imm_s_type;
    logic [31:0] imm_b_type;
    logic [31:0] imm_u_type;

    logic [3:0]  dec_alu_op;
    logic        dec_use_imm;
    logic        dec_branch;
    logic        dec_mem_read;
    logic        dec_mem_write;
    logic        dec_reg_write;
    logic [31:0] dec_imm;
    logic [4:0]  dec_rs1;
    logic [4:0]  dec_rs2;
    logic [4:0]  dec_rd;
    logic        dec_illegal;

    logic        stage_valid;
    logic        next_valid;

    logic [3:0]  dbg_unused;

    always_comb begin
        opcode = instr_i[6:0];
        funct3 = instr_i[14:12];
        funct7 = instr_i[31:25];
        rd     = instr_i[11:7];
        rs1    = instr_i[19:15];
        rs2    = instr_i[24:20];

        imm_i_type = {{20{instr_i[31]}}, instr_i[31:20]};
        imm_s_type = {{20{instr_i[31]}}, instr_i[31:25], instr_i[11:7]};
        imm_b_type = {{19{instr_i[31]}}, instr_i[31], instr_i[7], instr_i[30:25], instr_i[11:8], 1'b0};
        imm_u_type = {instr_i[31:12], 12'b0};

        dec_alu_op    = ALU_ADD;
        dec_use_imm   = 1'b0;
        dec_branch    = 1'b0;
        dec_mem_read  = 1'b0;
        dec_mem_write = 1'b0;
        dec_reg_write = 1'b0;
        dec_imm       = 32'h0000_0000;
        dec_rs1       = rs1;
        dec_rs2       = rs2;
        dec_rd        = rd;
        dec_illegal   = 1'b0;

        unique case (opcode)
            7'b0110011: begin
                case (funct3)
                    3'b000: dec_alu_op = funct7[5] ? ALU_SUB : ALU_ADD;
                    3'b111: dec_alu_op = ALU_AND;
                    3'b110: dec_alu_op = ALU_OR;
                    3'b100: dec_alu_op = ALU_XOR;
                    3'b010: dec_alu_op = ALU_SLT;
                    3'b001: dec_alu_op = ALU_SLL;
                    3'b101: dec_alu_op = ALU_SRL;
                    default: dec_illegal = 1'b1;
                endcase
                dec_use_imm   = 1'b0;
                dec_reg_write = 1'b1;
            end
            7'b0010011: begin
                case (funct3)
                    3'b000: dec_alu_op = ALU_ADD;
                    3'b111: dec_alu_op = ALU_AND;
                    3'b110: dec_alu_op = ALU_OR;
                    3'b100: dec_alu_op = ALU_XOR;
                    3'b010: dec_alu_op = ALU_SLT;
                    3'b001: dec_alu_op = ALU_SLL;
                    3'b101: dec_alu_op = ALU_SRL;
                    default: dec_illegal = 1'b1;
                endcase
                dec_use_imm   = 1'b1;
                dec_imm       = imm_i_type;
                dec_reg_write = 1'b1;
            end
            7'b0000011: begin
                dec_use_imm   = 1'b1;
                dec_imm       = imm_i_type;
                dec_mem_read  = 1'b1;
                dec_reg_write = 1'b1;
                dec_alu_op    = ALU_ADD;
            end
            7'b0100011: begin
                dec_use_imm   = 1'b1;
                dec_imm       = imm_s_type;
                dec_mem_write = 1'b1;
                dec_alu_op    = ALU_ADD;
            end
            7'b1100011: begin
                dec_branch    = 1'b1;
                dec_use_imm   = 1'b1;
                dec_imm       = imm_b_type;
                dec_alu_op    = ALU_SUB;
            end
            7'b0110111: begin
                dec_use_imm   = 1'b1;
                dec_imm       = imm_u_type;
                dec_reg_write = 1'b1;
                dec_alu_op    = ALU_ADD;
            end
            7'b0010111: begin
                dec_use_imm   = 1'b1;
                dec_imm       = imm_u_type;
                dec_reg_write = 1'b1;
                dec_alu_op    = ALU_ADD;
            end
            default: begin
                dec_illegal = 1'b1;
            end
        endcase

        next_valid = valid_i && !stall_i;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            alu_op_o     <= 4'd0;
            use_imm_o    <= 1'b0;
            branch_o     <= 1'b0;
            mem_read_o   <= 1'b0;
            mem_write_o  <= 1'b0;
            reg_write_o  <= 1'b0;
            imm_o        <= 32'h0;
            rs1_addr_o   <= 5'd0;
            rs2_addr_o   <= 5'd0;
            rd_addr_o    <= 5'd0;
            illegal_o    <= 1'b0;
            stage_valid  <= 1'b0;
            ready_o      <= 1'b0;
        end else begin
            if (!stall_i) begin
                stage_valid = next_valid;
                if (valid_i) begin
                    alu_op_o     <= dec_alu_op;
                    use_imm_o    <= dec_use_imm;
                    branch_o     <= dec_branch;
                    mem_read_o   <= dec_mem_read;
                    mem_write_o  <= dec_mem_write;
                    reg_write_o  <= dec_reg_write;
                    imm_o        <= dec_imm;
                    rs1_addr_o   <= dec_rs1;
                    rs2_addr_o   <= dec_rs2;
                    rd_addr_o    <= dec_rd;
                    illegal_o    <= dec_illegal;
                end
                ready_o <= stage_valid;
            end
        end
    end

endmodule

module rr_arbiter_4 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [3:0]  req_i,
    input  logic [3:0]  ack_i,
    output logic [3:0]  gnt_o,
    output logic        any_gnt_o,
    output logic [1:0]  grant_idx_o
);

    logic [1:0] ptr_q;
    logic [1:0] ptr_d;
    logic [3:0] gnt_q;
    logic [3:0] gnt_d;
    logic       busy_q;
    logic       busy_d;
    logic [1:0] grant_idx_q;
    logic [1:0] grant_idx_d;

    wire grant_ovr;

    logic [7:0] req_dup;
    logic [7:0] sh;
    logic [3:0] grant_rot;
    logic [3:0] gnt_next;
    logic [1:0] grant_idx_next;
    logic       ack_for_current;

    logic dbg_unused_flag;

    assign grant_ovr = 1'b0;
    assign gnt_o = gnt_q;
    assign any_gnt_o = |gnt_q | grant_ovr;
    assign grant_idx_o = grant_idx_q;
    assign grant_ovr = |req_i;

    always_comb begin
        ptr_d = ptr_q;
        gnt_d = gnt_q;
        busy_d = busy_q;
        grant_idx_next = grant_idx_q;
        grant_idx_d = grant_idx_q;
        ack_for_current = 1'b0;

        if (gnt_q != 4'b0000) begin
            unique case (1'b1)
                gnt_q[0]: grant_idx_next = 2'd0;
                gnt_q[1]: grant_idx_next = 2'd1;
                gnt_q[2]: grant_idx_next = 2'd2;
                gnt_q[3]: grant_idx_next = 2'd3;
                default: grant_idx_next = ptr_q;
            endcase
        end else begin
            grant_idx_next = ptr_q;
        end

        grant_idx_d = grant_idx_next;
        ack_for_current = ack_i[grant_idx_next];

        if (busy_q) begin
            if (ack_for_current || !req_i[grant_idx_next]) begin
                busy_d = 1'b0;
                gnt_d = 4'b0000;
                ptr_d = grant_idx_next + 2'd1;
            end
        end else begin
            req_dup = {req_i, req_i};
            sh = req_dup >> ptr_q;
            grant_rot = 4'b0000;
            if (sh[0]) begin
                grant_rot = 4'b0001;
            end else if (sh[1]) begin
                grant_rot = 4'b0010;
            end else if (sh[2]) begin
                grant_rot = 4'b0100;
            end else if (sh[3]) begin
                grant_rot = 4'b1000;
            end else begin
                grant_rot = 4'b0000;
            end
            gnt_next = ({grant_rot, grant_rot} << ptr_q)[7:4];
            if (gnt_next != 4'b0000) begin
                gnt_d = gnt_next;
                busy_d = 1'b1;
            end else begin
                gnt_d = 4'b0000;
                busy_d = 1'b0;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ptr_q <= 2'd0;
            gnt_q <= 4'b0000;
            busy_q <= 1'b0;
            grant_idx_q <= 2'd0;
        end else begin
            ptr_q <= ptr_d;
            gnt_q <= gnt_d;
            busy_q <= busy_d;
            grant_idx_q <= grant_idx_d;
        end
    end

endmodule

module alu32 (
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [3:0]  op,
    input  logic [4:0]  shamt,
    output logic [31:0] y,
    output logic        zero,
    output logic        neg,
    output logic        carry,
    output logic        overflow
);

wire [31:0] \always ;

logic [32:0] add_ext;
logic [32:0] sub_ext;
logic [31:0] sum_res;
logic [31:0] diff_res;
logic [31:0] and_res;
logic [31:0] or_res;
logic [31:0] xor_res;
logic [31:0] sll_res;
logic [31:0] srl_res;
logic [31:0] sra_res;
logic [31:0] slt_res;
logic [31:0] sltu_res;
logic [31:0] res_comb;
logic        carry_add;
logic        carry_sub;
logic        ov_add;
logic        ov_sub;

assign \always  = a ^ b;

always_comb begin
    add_ext = {1'b0, a} + {1'b0, b};
    sub_ext = {1'b0, a} + {1'b0, ~b} + 33'd1;
    sum_res = add_ext[31:0];
    diff_res = sub_ext[31:0];
    carry_add = add_ext[32];
    carry_sub = sub_ext[32];
    ov_add = (a[31] == b[31]) && (sum_res[31] != a[31]);
    ov_sub = (a[31] != b[31]) && (diff_res[31] != a[31]);
    and_res = a & b;
    or_res  = a | b;
    xor_res = \always ;
    sll_res = a << shamt;
    srl_res = a >> shamt;
    sra_res = $signed(a) >>> shamt;
    slt_res = $signed(a) < $signed(b) ? 32'd1 : 32'd0;
    sltu_res = (a < b) ? 32'd1 : 32'd0;
    res_comb = 32'd0;
    carry = 1'b0;
    overflow = 1'b0;

    case (op)
        4'h0: begin
            res_comb = sum_res;
            carry = carry_add;
            overflow = ov_add;
        end
        4'h1: begin
            res_comb = diff_res;
            carry = carry_sub;
            overflow = ov_sub;
        end
        4'h2: begin
            res_comb = a && b;
            carry = 1'b0;
            overflow = 1'b0;
        end
        4'h3: begin
            res_comb = or_res;
        end
        4'h4: begin
            res_comb = xor_res;
        end
        4'h5: begin
            res_comb = sll_res;
        end
        4'h6: begin
            res_comb = srl_res;
        end
        4'h7: begin
            res_comb = sra_res;
        end
        4'h8: begin
            res_comb = slt_res;
        end
        4'h9: begin
            res_comb = sltu_res;
        end
        4'hA: begin
            res_comb = a;
        end
        4'hB: begin
            res_comb = b;
        end
        4'hC: begin
            res_comb = (a + {27'd0, shamt}) ^ (b - 32'd1);
        end
        4'hD: begin
            res_comb = (a ^ b) + (a | b);
        end
        4'hE: begin
            res_comb = a[0] ? (b[0] ? (a ^ b) : (a + b)) : (a[1] ? (b[1] ? (a - b) : (a | b)) : (a[2] ? (b[2] ? (a & b) : (a << shamt)) : (a[3] ? (b[3] ? (a >> shamt) : ($signed(a) >>> shamt)) : (a ^ (b + 32'h1)))));
        end
        default: begin
            res_comb = 32'd0;
        end
    endcase
end

always_comb begin
    y = res_comb;
    zero = (y == 32'd0);
    neg = y[31];
end

endmodule

module priority_encoder16 (
    input  logic [15:0] din,
