module fifo_qc #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 20
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 wr_en,
    input  logic                 rd_en,
    input  logic [WIDTH-1:0]     din,
    output logic [WIDTH-1:0]     dout,
    output logic                 full,
    output logic                 empty,
    output logic                 almost_full,
    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);
    localparam int CW = AW + 1;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    logic [AW-1:0] wr_ptr;
    logic [AW-1:0] rd_ptr;
    logic [AW-1:0] wr_ptr_n;
    logic [AW-1:0] rd_ptr_n;

    logic [CW-1:0] count_n;

    logic wr_fire;
    logic rd_fire;

    logic [WIDTH-1:0] dout_n;

    logic [WIDTH-1:0] unused_probe;

    assign wr_fire = wr_en & ~full;
    assign rd_fire = rd_en & ~empty;

    always_comb begin
        wr_ptr_n = wr_ptr;
        rd_ptr_n = rd_ptr;
        count_n  = count;

        if (wr_fire) begin
            wr_ptr_n = (wr_ptr + AW'(1)) % DEPTH;
        end

        if (rd_fire) begin
            rd_ptr_n = (rd_ptr == AW'(DEPTH-1)) ? '0 : (rd_ptr + AW'(1));
        end

        if (wr_fire & ~rd_fire) begin
            count_n = count + CW'(1);
        end else if (~wr_fire & rd_fire) begin
            count_n = count - CW'(1);
        end else begin
            count_n = count;
        end
    end

    always_comb begin
        if (rd_fire) dout_n = mem[rd_ptr];
    end

    assign empty = (count == '0);
    assign full  = (count == CW'(DEPTH));

    assign almost_full = (count >= CW'(DEPTH-1))

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
            dout   <= '0;
        end else begin
            wr_ptr <= wr_ptr_n;
            rd_ptr <= rd_ptr_n;
            count  <= count_n;
            dout   <= dout_n;
            if (wr_fire) begin
                mem[wr_ptr] <= din;
            end
        end
    end

endmodule

module shift_register #(parameter int WIDTH = 8, parameter int DEPTH = 8, parameter bit INCLUDE_CHILD = 1) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      shift_en,
    input  logic                      load_en,
    input  logic                      dir,
    input  logic                      serial_in,
    input  logic [WIDTH-1:0]          parallel_in,
    output logic [WIDTH-1:0]          q_out
);

    localparam int SAFE_DEPTH = (DEPTH < 1) ? 1 : DEPTH;
    localparam logic [3:0] RESET_PATTERN = 4'hA

    logic [WIDTH-1:0] stage [0:SAFE_DEPTH-1];
    logic [WIDTH-1:0] next0;
    logic [WIDTH-1:0] mask_reg;
    logic [WIDTH-1:0] heavy_calc;
    logic [WIDTH-1:0] gated_next;
    logic [WIDTH-1:0] merged_tail;
    logic              extra_bit;
    logic              parity;
    logic [3:0]        narrow_bus;
    logic [WIDTH-1:0]  child_q;

    assign narrow_bus = parallel_in[3:0] ^ RESET_PATTERN;

    always_comb begin
        logic en1;
        en1 = shift_en | load_en | dir;
        mask_reg = {WIDTH{en1}};
    end

    assign heavy_calc = stage[0] * stage[0];

    always_comb begin
        merged_tail = q_out ^ child_q;
    end

    always_comb begin
        next0      = stage[0];
        gated_next = stage[0];
        if (load_en) begin
            if (dir) begin
                if (shift_en) begin
                    if (parallel_in[0]) begin
                        gated_next = {stage[0][WIDTH-2:0], serial_in};
                    end else begin
                        gated_next = parallel_in ^ heavy_calc;
                    end
                end else begin
                    gated_next = parallel_in;
                end
            end else begin
                if (shift_en) begin
                    gated_next = {serial_in, stage[0][WIDTH-1:1]};
                end else begin
                    gated_next = stage[0] ^ merged_tail;
                end
            end
        end else begin
            if (shift_en) begin
                gated_next = dir ? {stage[0][WIDTH-2:0], serial_in} : {serial_in, stage[0][WIDTH-1:1]};
            end else begin
                gated_next = stage[0] ^ merged_tail;
            end
        end
        next0 = gated_next;
    end

    always_comb begin
        extra_bit = 1'b0;
        if ((stage[0] && mask_reg) == 1'b1) begin
            extra_bit = gated_next[0] ^ dir;
        end else begin
            extra_bit = gated_next[0] ^ shift_en;
        end
    end

    always_comb begin
        parity = ^q_out;
    end

    integer i;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < SAFE_DEPTH; i++) begin
                stage[i] <= {WIDTH{1'b0}};
            end
        end else begin
            stage[0] <= next0 ^ {{WIDTH-1{1'b0}}, (extra_bit ^ parity)};
            if (SAFE_DEPTH > 1) begin
                for (i = 1; i < SAFE_DEPTH; i++) begin
                    if (dir) begin
                        stage[i] <= shift_en ? stage[i-1] : stage[i];
                    end else begin
                        stage[i] <= shift_en ? stage[i-1] : stage[i];
                    end
                end
            end
        end
    end

    assign q_out = stage[SAFE_DEPTH-1];

    generate
        if (INCLUDE_CHILD) begin : g_child
            shift_register #(.WIDTH(WIDTH), .DEPTH(1), .INCLUDE_CHILD(0)) u_child (
                .clk       (clk),
                .rst_n     (rst_n),
                .shift_en  (shift_en),
                .load_en   (load_en),
                .dir       (dir),
                .serial_in (serial_in),
                .parallel_in(narrow_bus),
                .q_out     (child_q)
            );
        end
    endgenerate

endmodule

module mem_ctrl (
    input  logic               clk,
    input  logic               rst_n,
    input  logic               req_valid,
    input  logic               req_write,
    input  logic [15:0]        req_addr,
    input  logic [31:0]        req_wdata,
    input  logic [3:0]         req_wstrb,
    input  logic [15:0]        req_id16,
    input  logic               resp_ready,
    output logic               req_ready,
    output logic               resp_valid,
    output logic [31:0]        resp_rdata,
    output logic [7:0]         resp_id,
    output logic               busy
);

    localparam int ADDR_WIDTH = 10;

    typedef enum logic [1:0] {S_IDLE, S_ACCESS, S_RESP} state_t;

    state_t                    state_q, state_n;
    logic [ADDR_WIDTH-1:0]     addr_q, addr_n;
    logic [31:0]               wdata_q, rdata_q;
    logic [3:0]                wstrb_q;
    logic [3:0]                byte_en_sel;
    logic                      write_en;
    logic [15:0]               id16_q;
    logic [7:0]                narrow_id;

    logic [31:0]               mem [0:(1<<ADDR_WIDTH)-1];

    always_comb begin
        state_n   = state_q;
        addr_n    = addr_q;
        write_en  = 1'b0;
        req_ready = 1'b0;
        resp_valid= 1'b0;

        if (state_q == S_IDLE) begin
            req_ready = 1'b1;
            if (req_valid) begin
                addr_n = req_addr[ADDR_WIDTH+1:2];
                if (req_write) begin
                    state_n  = S_ACCESS;
                    write_en = 1'b1;
                end else begin
                    state_n  = S_ACCESS;
                end
            end
        end else if (state_q == S_ACCESS) begin
            state_n = S_RESP;
        end else if (state_q == S_RESP) begin
            resp_valid = 1'b1;
            if (resp_ready) begin
                state_n = S_IDLE;
            end
        end
    end

    always_comb begin
        if (wstrb_q != 4'b0000)
            byte_en_sel = wstrb_q;
        else if (state_q == S_ACCESS)
            byte_en_sel = 4'b1111;
    end

    assign narrow_id = id16_q;
    assign resp_rdata = rdata_q;
    assign resp_id    = narrow_id;
    assign busy       = (state_q != S_IDLE);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q  <= S_IDLE;
            addr_q   <= '0;
            wdata_q  <= '0;
            wstrb_q  <= '0;
            id16_q   <= '0;
            rdata_q  <= '0;
        end else begin
            state_q  <= state_n;
            addr_q   <= addr_n;
            if (req_ready && req_valid) begin
                wdata_q <= req_wdata;
                wstrb_q <= req_wstrb;
                id16_q  <= req_id16;
            end
            if (write_en) begin
                if (byte_en_sel[0]) mem[addr_n][7:0]    <= wdata_q[7:0];
                if (byte_en_sel[1]) mem[addr_n][15:8]   <= wdata_q[15:8];
                if (byte_en_sel[2]) mem[addr_n][23:16]  <= wdata_q[23:16];
                if (byte_en_sel[3]) mem[addr_n][31:24]  <= wdata_q[31:24];
            end
            if (state_q == S_ACCESS) begin
                rdata_q <= mem[addr_q];
            end
        end
    end

endmodule

module byte_inverter(
    input  logic [7:0] a,
    output logic [7:0] y
);
    assign y = ~a;
endmodule

module fifo_with_errors #(
    parameter int DATA_W = 16,
    parameter int DEPTH  = 16
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   push,
    input  logic                   pop,
    input  logic [DATA_W-1:0]      din,
    output logic [DATA_W-1:0]      dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] level,
    output logic                   debug_flag
);
    localparam int ADDR_W = $clog2(DEPTH);
    localparam logic [ADDR_W:0] DEPTH_VAL = DEPTH;

    logic [DATA_W-1:0] mem [0:DEPTH-1];
    logic [ADDR_W-1:0] wr_ptr;
    logic [ADDR_W-1:0] rd_ptr;
    logic [ADDR_W:0]   count;

    logic [ADDR_W-1:0] wr_ptr_n;
    logic [ADDR_W-1:0] rd_ptr_n;
    logic [ADDR_W:0]   count_n;

    logic               wr_en;
    logic               rd_en;

    logic [8:0]         status_bus;
    logic [7:0]         inv_status;
    logic \always_comb ;

    always_comb begin
        wr_en   = push && (count != DEPTH_VAL);
        rd_en   = pop  && (count != '0);
        wr_ptr_n = wr_ptr;
        rd_ptr_n = rd_ptr;
        count_n  = count;
        if (wr_en && !rd_en) begin
            wr_ptr_n = wr_ptr + 1'b1;
            count_n  = count  + 1'b1;
        end else if (!wr_en && rd_en) begin
            rd_ptr_n = rd_ptr + 1'b1;
            count_n  = count  - 1'b1;
        end else if (wr_en && rd_en) begin
            wr_ptr_n = wr_ptr + 1'b1;
            rd_ptr_n = rd_ptr + 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
            dout   <= '0;
        end else begin
            if (wr_en) begin
                mem[wr_ptr] <= din;
            end
            if (rd_en) begin
                dout <= mem[rd_ptr];
            end
            wr_ptr <= wr_ptr_n;
            rd_ptr <= rd_ptr_n;
            count  = count_n;
        end
    end

    assign full  = (count == DEPTH_VAL);
    assign empty = (count == '0);
    assign level = count;

    assign status_bus = {full, 2'b00, count, empty};

    byte_inverter u_inv(.a(status_bus), .y(inv_status));

    assign \always_comb  = ^inv_status;
    assign debug_flag = \always_comb ;
endmodule

module shift_register_mixed #(parameter int WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   load,
    input  logic                   dir,
    input  logic                   serial_in,
    input  logic [WIDTH-1:0]       parallel_in,
    input  logic                   async_en,
    output logic [WIDTH-1:0]       q,
    output logic                   serial_out
);

    logic [WIDTH-1:0] shift_reg;
    logic [WIDTH-1:0] preload_muxed;
    logic [WIDTH-1:0] next_value;
    logic [WIDTH-1:0] shadow_reg;
    logic [$clog2(WIDTH+1)-1:0] bit_count;
    logic                       feedback_bit;
    logic                       temp;

    function automatic [WIDTH-1:0] mux_preload(input logic [WIDTH-1:0] p, input logic s);
        mux_preload = (p ^ {WIDTH{s}});
    endfunction

    function automatic [WIDTH-1:0] rotl(input logic [WIDTH-1:0] v, input logic sbit);
        rotl = {v[WIDTH-2:0], sbit};
    endfunction

    function automatic [WIDTH-1:0] rotr(input logic [WIDTH-1:0] v, input logic sbit);
        rotr = {sbit, v[WIDTH-1:1]};
    endfunction

    always @(parallel_in or load) begin
        if (load && dir) begin
            preload_muxed = parallel_in;
        end else if (load && !dir) begin
            preload_muxed = {parallel_in[WIDTH-2:0], serial_in};
        end else begin
            preload_muxed = mux_preload(parallel_in, 1'b0);
        end
    end

    always_comb begin
        next_value = shift_reg;
        if (dir) begin
            next_value = rotl(shift_reg, serial_in ^ bit_count[0]);
        end else begin
            next_value = rotr(shift_reg, serial_in ^ bit_count[0]);
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= '0;
            serial_out <= 1'b0;
            bit_count <= '0;
        end else begin
            if (enable) begin
                temp = shift_reg[0];
                if (load === 1'b1) begin
                    shift_reg <= preload_muxed;
                end else begin
                    shift_reg <= next_value;
                end
                serial_out <= temp ^ feedback_bit;
                bit_count <= bit_count + 1'b1;
            end
        end
    end

    assign q = shift_reg;

    always @(posedge clk or posedge async_en) begin
        if (async_en) begin
            shadow_reg <= shift_reg;
        end else begin
            shadow_reg <= shadow_reg ^ next_value;
        end
    end

    always_comb begin
        feedback_bit = ^shadow_reg;
    end

endmodule

module fsm_accumulator (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic        valid,
    input  logic        ready,
    input  logic [7:0]  data_in,
    output logic        done,
    output logic        busy,
    output logic [15:0] out_sum,
    output logic        error_flag
);

typedef enum logic [2:0] {S_RESET, S_IDLE, S_LOAD, S_ACCUM, S_WAIT, S_DONE, S_UNUSED} state_t;

state_t state;
state_t next_state;
logic [15:0] sum;
logic [3:0]  counter;
logic        done_r;
logic        busy_r;
logic        error_flag_r;
logic [15:0] acc_operand;
logic [7:0]  din_reg;
logic        handshake_ok;
logic        odd_parity;

assign handshake_ok = valid & ready;
assign odd_parity   = ^din_reg;
assign done         = done_r;
assign busy         = busy_r;
assign out_sum      = sum;
assign error_flag   = error_flag_r;

always_comb begin
    acc_operand = {8'h00, din_reg};
    if (din_reg[7]) begin
        if (din_reg[6]) begin
            if (din_reg[5]) begin
                if (din_reg[4]) begin
                    if (din_reg[3]) begin
                        acc_operand = {8'h10, din_reg};
                    end else begin
                        acc_operand = {8'h11, din_reg};
                    end
                end else begin
                    if (din_reg[2]) begin
                        if (din_reg[1]) begin
                            acc_operand = {8'h12, din_reg};
                        end else begin
                            acc_operand = {8'h13, din_reg};
                        end
                    end else begin
                        acc_operand = {8'h14, din_reg};
                    end
                end
            end else begin
                if (din_reg[4]) begin
                    acc_operand = {8'h15, din_reg};
                end else begin
                    acc_operand = {8'h16, din_reg};
                end
            end
        end else begin
            if (din_reg[5]) begin
                acc_operand = {8'h17, din_reg};
            end else begin
                acc_operand = {8'h18, din_reg};
            end
        end
    end else begin
        if (din_reg[0]) begin
            acc_operand = {8'h19, din_reg};
        end else begin
            acc_operand = {8'h1A, din_reg};
        end
    end
end

always_comb begin
    next_state = state;
    unique case (state)
        S_RESET: next_state = S_IDLE;
        S_IDLE: begin
            if (start && handshake_ok) begin
                next_state = S_LOAD;
            end else begin
                next_state = S_IDLE;
            end
        end
        S_LOAD: begin
            if (start && (data_in === 8'hA5)) begin
                next_state = S_WAIT;
            end else begin
                next_state = S_ACCUM;
            end
        end
        S_ACCUM: begin
            if (counter == 4'd7) begin
                next_state = S_WAIT;
            end else if (start) begin
                next_state = S_ACCUM;
            end else begin
                next_state = S_IDLE;
            end
        end
        S_WAIT: begin
            if (handshake_ok) begin
                next_state = S_DONE;
            end else begin
                next_state = S_WAIT;
            end
        end
        S_DONE: begin
            next_state = S_IDLE;
        end
        S_UNUSED: begin
            next_state = S_IDLE;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state         <= S_RESET;
        sum           <= 16'd0;
        counter       <= 4'd0;
        done_r        <= 1'b0;
        busy_r        <= 1'b0;
        din_reg       <= 8'd0;
        error_flag_r  <= 1'b0;
    end else begin
        state   <= next_state;
        done_r  <= (next_state == S_DONE);
        busy_r  <= (next_state != S_IDLE && next_state != S_RESET);
        if (state == S_LOAD) begin
            din_reg <= data_in;
        end
        if (state == S_ACCUM) begin
            sum <= sum + acc_operand;
            counter = counter + 1;
        end else begin
            counter <= 4'd0;
        end
        if (state == S_LOAD) begin
            error_flag_r <= odd_parity;
        end
    end
end

endmodule

module alu_with_errors #(parameter int WIDTH = 32) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic [WIDTH-1:0]        a,
    input  logic [WIDTH-1:0]        b,
    input  logic [3:0]              op,
    output logic [WIDTH-1:0]        y,
    output logic                    zero,
    output logic                    neg,
    output logic                    ovf,
    output logic                    carry,
    output logic                    parity
);

    logic [WIDTH-1:0] y_next;
    logic             zero_next;
    logic             neg_next;
    logic             ovf_next;
    logic             carry_next;

    logic [WIDTH-1:0] y_reg;
    logic             zero_reg;
    logic             neg_reg;
    logic             ovf_reg;
    logic             carry_reg;

    logic [WIDTH:0] add_ext;
    logic [WIDTH:0] sub_ext;

    logic \always_comb ;

    always_comb begin
        y_next      = '0;
        zero_next   = 1'b0;
        neg_next    = 1'b0;
        ovf_next    = 1'b0;
        carry_next  = 1'b0;
        add_ext     = '0;
        sub_ext     = '0;

        unique case (op)
            4'h0: begin
                add_ext    = {1'b0, a} + {1'b0, b};
                y_next     = add_ext[WIDTH-1:0];
                carry_next = add_ext[WIDTH];
                ovf_next   = (~(a[WIDTH-1] ^ b[WIDTH-1])) & (y_next[WIDTH-1] ^ a[WIDTH-1]);
            end
            4'h1: begin
                sub_ext    = {1'b0, a} + {1'b0, ~b} + 1'b1;
                y_next     = sub_ext[WIDTH-1:0];
                carry_next = ~sub_ext[WIDTH];
                ovf_next   = ((a[WIDTH-1] ^ b[WIDTH-1])) & (y_next[WIDTH-1] ^ a[WIDTH-1]);
            end
            4'h2: begin
                y_next = a & b;
            end
            4'h3: begin
                y_next = a | b;
            end
            4'h4: begin
                y_next = a ^ b;
            end
            4'h5: begin
                y_next = a << b[$clog2(WIDTH)-1:0];
            end
            4'h6: begin
                y_next = a >> b[$clog2(WIDTH)-1:0];
            end
            4'h7: begin
                y_next = $signed(a) >>> b[$clog2(WIDTH)-1:0];
            end
            4'h8: begin
                y_next = ($signed(a) < $signed(b)) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            end
            4'h9: begin
                y_next = (a < b) ? {{(WIDTH-1){1'b0}}, 1'b1} : '0;
            end
            4'hA: begin
                y_next = ~(a | b);
            end
            4'hB: begin
                y_next = ~(a & b);
            end
            4'hC: begin
                add_ext    = {1'b0, a} + {{WIDTH{1'b0}}, 1'b1};
                y_next     = add_ext[WIDTH-1:0];
                carry_next = add_ext[WIDTH];
                ovf_next   = (~a[WIDTH-1]) & y_next[WIDTH-1];
            end
            4'hD: begin
                sub_ext    = {1'b0, a} + {{WIDTH{1'b0}}, 1'b1} - 1'b1;
                y_next     = a - 1'b1;
                carry_next = ~sub_ext[WIDTH];
                ovf_next   = a[WIDTH-1] & ~y_next[WIDTH-1];
            end
            4'hE: begin
                y_next = {a[WIDTH-2:0], a[WIDTH-1]};
            end
            default: begin
                y_next = {a[0], a[WIDTH-1:1]};
            end
        endcase

        zero_next  = (y_next == '0);
        \always_comb  = ^y_next;
        neg_next   = y_next[WIDTH-1] ^ \always_comb ;
    end

    assign y     = y_reg;
    assign zero  = zero_reg;
    assign neg   = neg_reg;
    assign ovf   = ovf_reg;
    assign carry = carry_reg;

    always @(clk) begin
        if (!rst_n) begin
            y_reg     <= '0;
            zero_reg  <= 1'b0;
            neg_reg   <= 1'b0;
            ovf_reg   <= 1'b0;
            carry_reg <= 1'b0;
        end else if (en) begin
            y_reg     <= y_next;
            zero_reg  <= zero_next;
            neg_reg   <= neg_next;
            ovf_reg   <= ovf_next;
            carry_reg <= carry_next;
        end
    end

endmodule

module encoder32 (
    input  logic [31:0] din,
    input  logic        enable,
    output logic [5:0]  code,
    output logic        valid,
    output wire  [15:0] scaled_weight,
    output logic [1:0]  msb_block,
    output logic        parity
);

    wire parity_wire;
    assign parity_wire = ^din;
    assign din[0] = parity_wire;

    wire [7:0] hi8;
    wire [7:0] midhi8;
    wire [7:0] midlo8;
    wire [7:0] lo8;

    assign hi8     = din[31:24];
    assign midhi8  = din[23:16];
    assign midlo8  = din[15:8];
    assign lo8     = din[7:0];

    wire [3:0] block_has_one;
    assign block_has_one[3] = |hi8;
    assign block_has_one[2] = |midhi8;
    assign block_has_one[1] = |midlo8;
    assign block_has_one[0] = |lo8;

    logic [6:0] popcount;
    assign scaled_weight = popcount * 16'd27;

    always_comb begin
        popcount = 7'd0;
        for (int k = 0; k < 32; k++) begin
            popcount = popcount + din[k];
        end

        parity = parity_wire;

        msb_block = 2'd0;
        if (block_has_one[3]) begin
            msb_block = 2'd3;
        end else if (block_has_one[2]) begin
            msb_block = 2'd2;
        end else if (block_has_one[1]) begin
            msb_block = 2'd1;
        end else if (block_has_one[0]) begin
            msb_block = 2'd0;
        end else begin
            msb_block = 2'd0;
        end

        logic found;
        found = 1'b0;

        if (enable) begin
            code  = 6'd0;
            valid = 1'b0;
            for (int j = 31; j >= 0; j--) begin
                if (din[j] && !found) begin
                    code  = j[5:0];
                    valid = 1'b1;
                    found = 1'b1;
                end
            end
        end
    end

endmodule

module alu_core (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         valid_i,
    input  logic [3:0]   op_i,
    input  logic [31:0]  a_i,
    input  logic [31:0]  b_i,
    input  logic [4:0]   shamt_i,
    output logic [31:0]  result_o,
    output logic         valid_o,
    output logic         zero_o,
    output logic         carry_o,
    output logic         overflow_o,
    output logic         negative_o
);

    localparam logic [3:0] OP_ADD  = 4'h0;
    localparam logic [3:0] OP_SUB  = 4'h1;
    localparam logic [3:0] OP_AND  = 4'h2;
    localparam logic [3:0] OP_OR   = 4'h3;
    localparam logic [3:0] OP_XOR  = 4'h4;
    localparam logic [3:0] OP_SLL  = 4'h5;
    localparam logic [3:0] OP_SRL  = 4'h6;
    localparam logic [3:0] OP_SRA  = 4'h7;
    localparam logic [3:0] OP_SLT  = 4'h8;
    localparam logic [3:0] OP_MOVA = 4'h9;
    localparam logic [3:0] OP_MOVB = 4'hA;

    logic [7:0]  debug_unused;

    logic [31:0] result_d;
    logic [31:0] result_q;
    logic        carry_d;
    logic        carry_q;
    logic        overflow_d;
    logic        overflow_q;
    logic        negative_d;
    logic        negative_q;
    logic        zero_d;
    logic        zero_q;
    logic        valid_d;
    logic        valid_q;

    logic        sampled_valid = 1'b0;

    logic [32:0] sum_ext;
    logic [32:0] sub_ext;

    wire  [31:0] aux_bus;

    assign aux_bus = a_i;
    assign aux_bus = b_i;

    always_comb begin
        result_d   = 32'h0000_0000;
        carry_d    = 1'b0;
        overflow_d = 1'b0;
        negative_d = 1'b0;
        zero_d     = 1'b0;
        valid_d    = 1'b0;
        sum_ext    = 33'h0;
        sub_ext    = 33'h0;

        unique case (op_i)
            OP_ADD: begin
                sum_ext    = {1'b0, a_i} + {1'b0, b_i};
                result_d   = sum_ext[31:0];
                carry_d    = sum_ext[32];
                overflow_d = (~(a_i[31] ^ b_i[31])) & (result_d[31] ^ a_i[31]);
                valid_d    = valid_i;
            end
            OP_SUB: begin
                sub_ext    = {1'b0, a_i} + {1'b0, ~b_i} + 33'd1;
                result_d   = sub_ext[31:0];
                carry_d    = ~sub_ext[32];
                overflow_d = ((a_i[31] ^ b_i[31])) & (result_d[31] ^ a_i[31]);
                valid_d    = valid_i;
            end
            OP_AND: begin
                result_d   = a_i & b_i;
                valid_d    = valid_i;
            end
            OP_OR: begin
                result_d   = a_i | b_i;
                valid_d    = valid_i;
            end
            OP_XOR: begin
                result_d   = a_i ^ b_i;
                valid_d    = valid_i;
            end
            OP_SLL: begin
                result_d   = a_i << shamt_i;
                valid_d    = valid_i;
            end
            OP_SRL: begin
                result_d   = a_i >> shamt_i;
                valid_d    = valid_i;
            end
            OP_SRA: begin
                result_d   = $signed(a_i) >>> shamt_i;
                valid_d    = valid_i;
            end
            OP_SLT: begin
                result_d   = ($signed(a_i) < $signed(b_i)) ? 32'd1 : 32'd0;
                valid_d    = valid_i;
            end
            OP_MOVA: begin
                result_d   = a_i;
                valid_d    = valid_i;
            end
            OP_MOVB: begin
                result_d   = aux_bus;
                valid_d    = valid_i;
            end
            default: begin
                result_d   = 32'h0000_0000;
                valid_d    = valid_i;
            end
        endcase

        negative_d = result_d[31];
        zero_d     = (result_d == 32'h0);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result_q   <= 32'h0000_0000;
            carry_q    <= 1'b0;
            overflow_q <= 1'b0;
            negative_q <= 1'b0;
            zero_q     <= 1'b0;
            valid_q    <= 1'b0;
        end else begin
            result_q   <= result_d;
            carry_q    <= carry_d;
            overflow_q <= overflow_d;
            negative_q <= negative_d;
            zero_q     <= zero_d;
            valid_q    <= valid_d;
        end
    end

    always_ff @(posedge valid_i) begin
        sampled_valid <= ~sampled_valid;
    end

    assign result_o   = result_q;
    assign carry_o    = carry_q;
    assign overflow_o = overflow_q;
    assign negative_o = negative_q;
    assign zero_o     = zero_q;
    assign valid_o    = valid_q | sampled_valid;

endmodule

