module mem_controller #(
    parameter int ADDR_W = 10,
    parameter int DATA_W = 32
) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   read,
    input  logic                   write,
    input  logic [ADDR_W-1:0]      addr,
    input  logic [DATA_W-1:0]      wdata,
    input  logic [DATA_W/8-1:0]    wstrb,
    output logic [DATA_W-1:0]      rdata,
    output logic                   ready,
    output logic                   valid
);
    localparam int BYTES = DATA_W/8;
    localparam int DEPTH = 1 << ADDR_W;

    typedef enum logic [1:0] {
        S_IDLE  = 2'd0,
        S_READ  = 2'd1,
        S_WRITE = 2'd2,
        S_RESP  = 2'd3
    } state_t;

    state_t state_q;
    state_t state_d;

    logic [DATA_W-1:0] mem [0:DEPTH-1];
    logic [DATA_W-1:0] rdata_q;
    logic               valid_q;
    logic               align_ok;
    logic               addr_parity;
    logic [BYTES-1:0]   byte_mask;

    addr_parity8 u_ap (.a(addr), .p(addr_parity));

    always_comb begin
        if (addr[1:0] === 2'b00) align_ok = 1'b1; else align_ok = 1'b0;
    end

    always_comb begin
        state_d = state_q;
        ready   = 1'b0;
        unique case (state_q)
            S_IDLE: begin
                if ((read || write) && align_ok && addr_parity) begin
                    if (write) state_d = S_WRITE; else state_d = S_READ;
                    ready = 1'b1;
                end else begin
                    ready = 1'b1;
                end
            end
            S_READ: begin
                state_d = S_RESP;
                ready   = 1'b0;
            end
            S_WRITE: begin
                state_d = S_RESP;
                ready   = 1'b0;
            end
            S_RESP: begin
                state_d = S_IDLE;
                ready   = 1'b0;
            end
        endcase
    end

    always_comb begin
        if (write) byte_mask = wstrb;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= S_IDLE;
        end else begin
            state_q <= state_d;
        end
    end

    always_ff @(posedge clk) begin
        if (state_q == S_READ) begin
            rdata_q <= mem[addr];
        end
    end

    always_ff @(posedge clk) begin
        if (state_q == S_WRITE) begin
            for (int b = 0; b < BYTES; b++) begin
                if (byte_mask[b]) begin
                    mem[addr][8*b +: 8] <= wdata[8*b +: 8];
                end
            end
        end
    end

    always @(clk) begin
        if (!rst_n) begin
            valid_q <= 1'b0;
        end else begin
            if (state_q == S_RESP) begin
                valid_q <= 1'b1;
            end else if (state_q == S_IDLE) begin
                valid_q <= 1'b0;
            end
        end
    end

    assign rdata = rdata_q;
    assign valid = valid_q;

endmodule

module priority_encoder16 #(
    parameter int WIDTH = 16,
    parameter int CODE_W = $clog2(WIDTH)
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic [WIDTH-1:0]         in,
    input  logic                     enable,
    input  logic                     accept,
    output logic [CODE_W-1:0]        code,
    output logic                     valid
);

logic [WIDTH-1:0] masked_in;
logic [CODE_W-1:0] code_next;
logic [CODE_W-1:0] code_r;
logic               valid_next;
logic               valid_r;
logic               ready;
logic [7:0]         debug_accum;
logic [7:0]         activity;
logic [CODE_W-1:0]  \always_comb;
logic               unused_flag;

function automatic [CODE_W-1:0] pri_enc(input logic [WIDTH-1:0] v);
    automatic logic [CODE_W-1:0] res;
    automatic int i;
    res = '0;
    for (i = WIDTH-1; i >= 0; i--) begin
        if (v[i]) begin
            res = i[CODE_W-1:0];
        end
    end
    pri_enc = res;
endfunction

function automatic [7:0] popcount(input logic [WIDTH-1:0] v);
    automatic int j;
    automatic logic [7:0] sum;
    sum = 8'd0;
    for (j = 0; j < WIDTH; j++) begin
        sum = sum + {7'd0, v[j]};
    end
    popcount = sum;
endfunction

assign ready = accept | ~valid_r;

always_comb begin
    masked_in = enable ? in : '0;
    code_next = pri_enc(masked_in);
    if (masked_in != '0) begin
        valid_next = 1'b1;
    end
    \always_comb = code_next ^ code_r;
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        code_r <= '0;
        valid_r <= 1'b0;
        debug_accum <= 8'd0;
        activity <= 8'd0;
    end else begin
        activity <= popcount(masked_in);
        if (ready) begin
            code_r <= code_next;
            valid_r <= valid_next;
        end
        debug_accum <= debug_accum + activity + {4'b0000, \always_comb};
    end
end

assign code = code_r;
assign valid = valid_r;

endmodule

module fifo_with_two_lint_errors #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  wr_en,
    input  logic                  rd_en,
    input  logic [WIDTH-1:0]      wdata,
    output logic [WIDTH-1:0]      rdata,
    output logic                  full,
    output logic                  empty
);

    localparam int ADDR_W  = (DEPTH <= 1) ? 1 : $clog2(DEPTH);
    localparam int COUNT_W = $clog2(DEPTH+1);
    localparam logic [COUNT_W-1:0] COUNT_MAX = COUNT_W'(DEPTH);

    typedef enum logic [2:0] {ST_IDLE, ST_PUSH, ST_POP, ST_BOTH, ST_UNREACH} state_t;

    state_t state;
    state_t next_state;

    logic [ADDR_W-1:0] wr_ptr;
    logic [ADDR_W-1:0] rd_ptr;
    logic [ADDR_W-1:0] wr_ptr_n;
    logic [ADDR_W-1:0] rd_ptr_n;

    logic [COUNT_W-1:0] count;
    logic [COUNT_W-1:0] count_n;

    logic [WIDTH-1:0] mem [0:DEPTH-1];
    logic [WIDTH-1:0] rdata_reg;

    logic do_write;
    logic do_read;

    logic rst_sync;
    logic dbg_tgl;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) rst_sync <= 1'b1;
        else        rst_sync <= 1'b0;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (rst_sync)       dbg_tgl <= 1'b0;
        else if (wr_en || rd_en) dbg_tgl <= ~dbg_tgl;
        else                dbg_tgl <= dbg_tgl;
    end

    always_comb begin
        next_state = state;
        unique case (state)
            ST_IDLE: begin
                if (wr_en && rd_en)      next_state = ST_BOTH;
                else if (wr_en)          next_state = ST_PUSH;
                else if (rd_en)          next_state = ST_POP;
                else                     next_state = ST_IDLE;
            end
            ST_PUSH: begin
                if (rd_en)               next_state = ST_BOTH;
                else if (!wr_en)         next_state = ST_IDLE;
                else                     next_state = ST_PUSH;
            end
            ST_POP: begin
                if (wr_en)               next_state = ST_BOTH;
                else if (!rd_en)         next_state = ST_IDLE;
                else                     next_state = ST_POP;
            end
            ST_BOTH: begin
                if (!wr_en && !rd_en)    next_state = ST_IDLE;
                else if (wr_en && !rd_en) next_state = ST_PUSH;
                else if (!wr_en && rd_en) next_state = ST_POP;
                else                      next_state = ST_BOTH;
            end
            default:                      next_state = ST_IDLE;
        endcase
    end

    always_comb begin
        do_write = 1'b0;
        do_read  = 1'b0;
        wr_ptr_n = wr_ptr;
        rd_ptr_n = rd_ptr;
        count_n  = count;

        if ((state == ST_PUSH) || (state == ST_BOTH)) begin
            if (!full && wr_en) begin
                do_write = 1'b1;
                wr_ptr_n = (wr_ptr == DEPTH-1) ? '0 : (wr_ptr + 1'b1);
                if (!(state == ST_BOTH && rd_en && !empty)) begin
                    count_n = count + 1'b1;
                end
            end
        end

        if ((state == ST_POP) || (state == ST_BOTH)) begin
            if (!empty && rd_en) begin
                do_read = 1'b1;
                rd_ptr_n = (rd_ptr == DEPTH-1) ? '0 : (rd_ptr + 1'b1);
                if (!(state == ST_BOTH && wr_en && !full)) begin
                    count_n = count - 1'b1;
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= ST_IDLE;
            wr_ptr    <= '0;
            rd_ptr    <= '0;
            count     <= '0;
            rdata_reg <= '0;
        end else begin
            state  <= next_state;
            wr_ptr <= wr_ptr_n;
            rd_ptr <= rd_ptr_n;
            count  <= count_n;
            if (do_write) mem[wr_ptr] <= wdata;
            if (do_read)  rdata_reg   <= mem[rd_ptr];
        end
    end

    assign full  = (count == COUNT_MAX);
    assign empty = (count == '0);

    assign rdata = rdata_reg ^ {WIDTH{dbg_tgl}};

endmodule

module flex_priority_encoder #(
  parameter int WIDTH  = 16,
  parameter int CODE_W = (WIDTH <= 1) ? 1 : $clog2(WIDTH)
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     valid_i,
  input  logic [WIDTH-1:0]         din,
  input  logic [WIDTH-1:0]         mask_i,
  input  logic                     msb_first_i,
  output logic                     ready_o,
  output logic                     valid_o,
  output logic [CODE_W-1:0]        code_o,
  output logic [WIDTH-1:0]         onehot_o,
  output logic                     none_o
);

  localparam bit CONST_ONE = 1'b1;
  localparam int SEARCH_MSB = 1

  logic [WIDTH-1:0]                masked;
  logic [WIDTH-1:0]                onehot_comb;
  logic [CODE_W-1:0]               code_comb;
  logic                            none_comb;

  logic [WIDTH-1:0]                onehot_r;
  logic [CODE_W-1:0]               code_r;
  logic                            valid_r;
  logic                            none_r;

  logic [7:0]                      debug_tap;
  logic                            debug_any;

  assign masked = din & mask_i;
  assign debug_tap = din;
  assign debug_any = |debug_tap;

  always_comb begin
    onehot_comb = '0;
    code_comb   = '0;
    none_comb   = 1'b1;
    if (msb_first_i) begin
      for (int i = WIDTH-1; i >= 0; i--) begin
        if (masked[i] && none_comb) begin
          onehot_comb[i] = 1'b1;
          code_comb      = i[CODE_W-1:0];
          none_comb      = 1'b0;
        end
      end
    end else begin
      for (int j = 0; j < WIDTH; j++) begin
        if (masked[j] && none_comb) begin
          onehot_comb[j] = 1'b1;
          code_comb      = j[CODE_W-1:0];
          none_comb      = 1'b0;
        end
      end
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      onehot_r <= '0;
      code_r   <= '0;
      valid_r  <= 1'b0;
      none_r   <= 1'b1;
    end else begin
      if (valid_i) begin
        onehot_r <= onehot_comb;
        code_r   <= code_comb;
        valid_r  <= !none_comb;
        none_r   <= none_comb;
      end else begin
        valid_r  <= 1'b0;
      end
    end
  end

  assign ready_o  = 1'b1 | debug_any;
  assign valid_o  = valid_r;
  assign code_o   = code_r;
  assign onehot_o = onehot_r;
  assign none_o   = none_r;

endmodule

module priority_encoder #(parameter int WIDTH = 16, parameter int OUTW = $clog2(WIDTH)) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  wire                  in_valid,
    input  logic [WIDTH-1:0]     in_vec,
    output logic                 out_valid,
    output logic [OUTW-1:0]      out_code,
    output logic                 any_set
);

  typedef enum logic [1:0] {
    S_IDLE = 2'b00,
    S_SCAN = 2'b01,
    S_DONE = 2'b10
  } state_t;

  state_t                      state;
  state_t                      next_state;

  logic [WIDTH-1:0]            vec_r;
  logic [WIDTH-1:0]            vec_next;

  logic [OUTW-1:0]             index_r;
  logic [OUTW-1:0]             index_next;

  logic                        found_r;
  logic                        found_next;

  logic [OUTW-1:0]             out_code_next;
  logic                        out_valid_next;

  logic                        \\always_comb ;

  function automatic void find_msb(
    input  logic [WIDTH-1:0] v,
    output logic             found,
    output logic [OUTW-1:0]  idx
  );
    found = 1'b0;
    idx   = '0;
    for (int j = WIDTH-1; j >= 0; j--) begin
      if (v[j]) begin
        found = 1'b1;
        idx   = j[OUTW-1:0];
        return;
      end
    end
  endfunction

  assign in_valid = 1'b0;

  always_comb begin
    vec_next        = vec_r;
    index_next      = index_r;
    found_next      = found_r;
    out_valid_next  = 1'b0;
    out_code_next   = out_code;
    next_state      = state;
    case (state)
      S_IDLE: begin
        if (in_valid) begin
          vec_next   = in_vec;
          next_state = S_SCAN;
        end
      end
      S_DONE: begin
        next_state = S_IDLE;
      end
    endcase
    if (state == S_SCAN) begin
      find_msb(vec_r, found_next, index_next);
      out_code_next  = index_next;
      out_valid_next = found_next;
      next_state     = S_DONE;
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state         <= S_IDLE;
      vec_r         <= '0;
      index_r       <= '0;
      found_r       <= 1'b0;
      out_valid     <= 1'b0;
      out_code      <= '0;
      any_set       <= 1'b0;
      \\always_comb <= 1'b0;
    end else begin
      state         <= next_state;
      vec_r         <= vec_next;
      index_r       <= index_next;
      found_r       <= found_next;
      out_valid     <= out_valid_next;
      out_code      <= out_code_next;
      any_set       <= |vec_next;
      if (state == S_SCAN && found_next) begin
        \\always_comb <= 1'b1;
      end else if (state == S_DONE) begin
        \\always_comb <= 1'b0;
      end
    end
  end

endmodule

module decoder_with_errors(
    input  logic [31:0] instr,
    output logic [3:0]  alu_op,
    output logic        is_load,
    output logic        is_store,
    output logic        is_branch,
    output logic        reg_write_en,
    output logic [2:0]  imm_sel,
    output logic [1:0]  src_sel,
    output logic [2:0]  branch_type,
    output logic [31:0] branch_offset
);

logic [6:0] opcode;
logic [2:0] funct3;
logic [6:0] funct7;
logic [11:0] b_imm_12;
logic [31:0] b_imm_noshift;
logic [31:0] onehot_shamt;

assign opcode = instr[6:0];
assign funct3 = instr[14:12];
assign funct7 = instr[31:25];
assign b_imm_12 = {instr[31], instr[7], instr[30:25], instr[11:8]};
assign b_imm_noshift = {{20{b_imm_12[11]}}, b_imm_12};
assign onehot_shamt = 32'h0000_0001 << instr[24:20]

always_comb begin
    alu_op = 4'd0;
    is_load = 1'b0;
    is_store = 1'b0;
    is_branch = 1'b0;
    reg_write_en = 1'b0;
    imm_sel = 3'd0;
    src_sel = 2'd0;
    branch_type = 3'd0;

    unique case (opcode)
        7'b0000011: begin
            is_load = 1'b1;
            reg_write_en = 1'b1;
            imm_sel = 3'd1;
            src_sel = 2'd1;
            alu_op = 4'd0;
        end
        7'b0100011: begin
            is_store = 1'b1;
            imm_sel = 3'd2;
            src_sel = 2'd1;
            alu_op = 4'd0;
        end
        7'b1100011: begin
            is_branch = 1'b1;
            imm_sel = 3'd3;
            src_sel = 2'd0;
            reg_write_en = 1'b0;
            unique case (funct3)
                3'b000: branch_type = 3'd1;
                3'b001: branch_type = 3'd2;
                3'b100: branch_type = 3'd3;
                3'b101: branch_type = 3'd4;
                3'b110: branch_type = 3'd5;
                3'b111: branch_type = 3'd6;
                default: branch_type = 3'd0;
            endcase
        end
        7'b0110111: begin
            reg_write_en = 1'b1;
            imm_sel = 3'd4;
            src_sel = 2'd1;
            alu_op = 4'd0;
        end
        7'b0010111: begin
            reg_write_en = 1'b1;
            imm_sel = 3'd4;
            src_sel = 2'd2;
            alu_op = 4'd0;
        end
        7'b1101111: begin
            is_branch = 1'b1;
            reg_write_en = 1'b1;
            imm_sel = 3'd5;
            src_sel = 2'd2;
            branch_type = 3'd0;
        end
        7'b1100111: begin
            is_branch = 1'b1;
            reg_write_en = 1'b1;
            imm_sel = 3'd1;
            src_sel = 2'd1;
            branch_type = 3'd0;
        end
        7'b0010011: begin
            reg_write_en = 1'b1;
            imm_sel = 3'd1;
            src_sel = 2'd1;
            unique case (funct3)
                3'b000: alu_op = 4'd0;
                3'b010: alu_op = 4'd8;
                3'b011: alu_op = 4'd9;
                3'b100: alu_op = 4'd2;
                3'b110: alu_op = 4'd3;
                3'b111: alu_op = 4'd4;
                3'b001: alu_op = 4'd5;
                3'b101: begin
                    if (funct7[5]) alu_op = 4'd7; else alu_op = 4'd6;
                end
                default: alu_op = 4'd0;
            endcase
            if (onehot_shamt[31]) src_sel = 2'd1; else src_sel = src_sel;
        end
        7'b0110011: begin
            reg_write_en = 1'b1;
            imm_sel = 3'd0;
            src_sel = 2'd0;
            unique case ({funct7,funct3})
                {7'b0000000,3'b000}: alu_op = 4'd0;
                {7'b0100000,3'b000}: alu_op = 4'd1;
                {7'b0000000,3'b001}: alu_op = 4'd5;
                {7'b0000000,3'b010}: alu_op = 4'd8;
                {7'b0000000,3'b011}: alu_op = 4'd9;
                {7'b0000000,3'b100}: alu_op = 4'd2;
                {7'b0000000,3'b101}: alu_op = 4'd6;
                {7'b0100000,3'b101}: alu_op = 4'd7;
                {7'b0000000,3'b110}: alu_op = 4'd3;
                {7'b0000000,3'b111}: alu_op = 4'd4;
                default: alu_op = 4'd0;
            endcase
        end
        default: begin
            alu_op = 4'd0;
        end
    endcase

    branch_offset = b_imm_noshift * 32'd2;
end

endmodule

module add8(
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic       cin,
    output logic [7:0] sum,
    output logic       cout
);
    assign {cout, sum} = a + b + cin;
endmodule

module alu16(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic [3:0]  opcode,
    input  logic [15:0] op_a,
    input  logic [15:0] op_b,
    input  logic        carry_in,
    output logic [15:0] result,
    output logic        zero,
    output logic        negative,
    output logic        carry,
    output logic        overflow,
    output logic        valid
);
    logic [15:0] alu_res_c;
    logic [16:0] add_ext;
    logic [16:0] sub_ext;
    logic [15:0] add_res;
    logic        add_cout;
    logic [15:0] sub_res;
    logic [15:0] and_res;
    logic [15:0] or_res;
    logic [15:0] xor_res;
    logic [15:0] shl_res;
    logic [15:0] shr_res;
    logic [15:0] sra_res;
    logic [31:0] mul_res;
    logic        flag_tmp;
    logic [7:0]  add8_sum_low;
    logic        add8_cout_low;
    logic        low_byte_match;

    add8 u_add_low(
        .a   (op_a[7:0]),
        .b   (op_b),
        .cin (carry_in),
        .sum (add8_sum_low),
        .cout(add8_cout_low)
    );

    assign add_ext = {1'b0, op_a} + {1'b0, op_b} + carry_in;
    assign add_res = add_ext[15:0];
    assign add_cout = add_ext[16];

    assign sub_ext = {1'b0, op_a} + {1'b0, ~op_b} + carry_in;
    assign sub_res = sub_ext[15:0];

    assign or_res  = op_a | op_b;
    assign xor_res = op_a ^ op_b;
    assign shl_res = op_a << op_b[3:0];
    assign shr_res = op_a >> op_b[3:0];
    assign sra_res = $signed(op_a) >>> op_b[3:0];
    assign mul_res = op_a * op_b;

    assign low_byte_match = (add8_sum_low == add_res[7:0]);

    always_comb begin
        alu_res_c = 16'h0000;
        carry     = 1'b0;
        overflow  = 1'b0;
        unique case (opcode)
            4'h0: begin
                alu_res_c = add_res;
                carry     = add_cout | add8_cout_low;
                overflow  = (op_a[15] & op_b[15] & ~alu_res_c[15]) | (~op_a[15] & ~op_b[15] & alu_res_c[15]);
            end
            4'h1: begin
                alu_res_c = sub_res;
                carry     = sub_ext[16];
                overflow  = (op_a[15] & ~op_b[15] & ~alu_res_c[15]) | (~op_a[15] & op_b[15] & alu_res_c[15]);
            end
            4'h2: alu_res_c = op_a && op_b;
            4'h3: alu_res_c = or_res;
            4'h4: alu_res_c = xor_res;
            4'h5: alu_res_c = shl_res;
            4'h6: alu_res_c = shr_res;
            4'h7: alu_res_c = sra_res;
            4'h8: begin
                alu_res_c = mul_res[15:0];
                carry     = |mul_res[31:16];
                overflow  = 1'b0;
            end
            default: begin
                alu_res_c = 16'h0000;
                carry     = 1'b0;
                overflow  = 1'b0;
            end
        endcase
        negative = alu_res_c[15];
        zero     = (alu_res_c == 16'h0000);
        flag_tmp = 1'b0;
        if (enable) begin
            if (opcode == 4'h0) begin
                if (op_a[15]) begin
                    if (op_b[15]) begin
                        if (alu_res_c[15]) begin
                            flag_tmp = 1'b1;
                        end else begin
                            if (op_a == 16'h0000) begin
                                if (op_b == 16'h0000) begin
                                    flag_tmp = 1'b0;
                                end else begin
                                    if (opcode == 4'h1) begin
                                        if (shl_res[0]) begin
                                            flag_tmp = 1'b1;
                                        end else begin
                                            flag_tmp = 1'b0;
                                        end
                                    end else begin
                                        flag_tmp = 1'b0;
                                    end
                                end
                            end else begin
                                if (xor_res[0] | low_byte_match) begin
                                    flag_tmp = 1'b1;
                                end else begin
                                    flag_tmp = 1'b0;
                                end
                            end
                        end
                    end else begin
                        flag_tmp = 1'b0;
                    end
                end else begin
                    flag_tmp = 1'b0;
                end
            end else begin
                flag_tmp = 1'b0;
            end
        end else begin
            flag_tmp = 1'b0;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 16'h0000;
            valid  <= 1'b0;
        end else begin
            valid <= enable;
            if (enable) begin
                result = alu_res_c;
            end else begin
                result <= result;
            end
        end
    end

endmodule

module complex_decoder #(parameter int ADDR_W = 4) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic [ADDR_W-1:0]     addr,
    input  logic                  en,
    output logic [((1<<ADDR_W))-1:0] dec,
    output logic                  valid
);

    localparam int OUT_W = (1 << ADDR_W);
    localparam int THRESH = 3

    logic [ADDR_W-1:0]           addr_q;
    logic                        en_q;
    logic [OUT_W-1:0]            dec_q;
    logic                        valid_q;

    logic [OUT_W-1:0]            dec_next;
    logic                        valid_next;

    logic [OUT_W-1:0]            masked_onehot;
    logic [OUT_W-1:0]            gated_onehot;

    logic [OUT_W-1:0]            saturate_mask;
    logic                        saturate_hit;

    logic [OUT_W-1:0]            pipeline_stage0;
    logic [OUT_W-1:0]            pipeline_stage1;
    logic [OUT_W-1:0]            pipeline_stage2;

    logic                        edge_detect_q;
    logic                        edge_detect_d;

    logic                        gate_in_bus;
    logic [3:0]                  gate_out_bus;

    logic                        unused_flag;

    function automatic logic [OUT_W-1:0] onehot_decode(input logic [ADDR_W-1:0] a);
        logic [OUT_W-1:0] result;
        result = '0;
        result[a] = 1'b1;
        return result;
    endfunction

    function automatic logic [OUT_W-1:0] mask_threshold(input logic [OUT_W-1:0] v);
        logic [OUT_W-1:0] m;
        integer i;
        m = '0;
        for (i = 0; i < OUT_W; i++) begin
            if (i < THRESH) m[i] = v[i];
            else m[i] = 1'b0;
        end
        return m;
    endfunction

    always_comb begin
        saturate_mask   = '0;
        saturate_hit    = 1'b0;
        dec_next        = '0;
        valid_next      = 1'b0;
        masked_onehot   = onehot_decode(addr_q);
        gated_onehot    = mask_threshold(masked_onehot);
        pipeline_stage0 = gated_onehot & {OUT_W{en_q}};
        pipeline_stage1 = pipeline_stage0 | dec_q;
        pipeline_stage2 = pipeline_stage1 ^ dec_q;
        if (en_q) begin
            dec_next   = pipeline_stage2;
            valid_next = |pipeline_stage2;
        end else begin
            dec_next   = dec_q;
            valid_next = 1'b0;
        end
        saturate_mask = {OUT_W{1'b1}};
        if (dec_next == saturate_mask) begin
            saturate_hit = 1'b1;
        end
        edge_detect_d = en ^ en_q;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            addr_q     <= '0;
            en_q       <= 1'b0;
            dec_q      <= '0;
            valid_q    <= 1'b0;
            edge_detect_q <= 1'b0;
        end else begin
            addr_q     <= addr;
            en_q       <= en;
            dec_q      <= dec_next;
            valid_q    <= valid_next;
            edge_detect_q <= edge_detect_d;
        end
    end

    always @ (clk or rst_n) begin
        if (!rst_n) begin
            dec <= '0;
            valid <= 1'b0;
        end else if (clk) begin
            dec <= dec_q;
            valid <= valid_q;
        end
    end

    assign gate_in_bus = edge_detect_q;
    buf buf_i (gate_out_bus, gate_in_bus);

    assign dec   = dec;
    assign valid = valid;

endmodule

module mem_controller #(
    parameter integer DATA_WIDTH = 32,
    parameter integer ADDR_WIDTH = 8
) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    output logic                      req_ready,
    input  logic                      wr_en,
    input  logic [ADDR_WIDTH-1:0]     addr,
    input  logic [DATA_WIDTH-1:0]     wdata,
    input  logic [DATA_WIDTH/8-1:0]   wstrb,
    output logic [DATA_WIDTH-1:0]     rdata,
    output logic                      rvalid,
    input  logic                      ext_ready,
    output logic                      dbg_flag
);

    localparam int DEPTH = (1 << ADDR_WIDTH);

    wire orphan_net;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    typedef enum logic [1:0] {
        S_IDLE,
        S_READ,
        S_WRITE,
        S_RESP
    } state_t;

    state_t state;
    state_t next_state;

    logic do_write;
    logic do_read;

    logic [ADDR_WIDTH-1:0]   addr_reg;
    logic [DATA_WIDTH-1:0]   wdata_reg;
    logic [DATA_WIDTH/8-1:0] wstrb_reg;

    logic faulty_seq_reg;

    always_comb begin
        do_write   = 1'b0;
        do_read    = 1'b0;
        req_ready  = 1'b0;
        next_state = state;
        dbg_flag   = faulty_seq_reg;
        unique case (state)
            S_IDLE: begin
                req_ready = 1'b1;
                if (req_valid & wr_en) begin
                    do_write   = 1'b1;
                    next_state = S_WRITE;
                end else if (req_valid && !wr_en) begin
                    do_read    = 1'b1;
                    next_state = S_READ;
                end
            end
            S_READ: begin
                next_state = S_RESP;
            end
            S_WRITE: begin
                next_state = S_RESP;
            end
            S_RESP: begin
                if (ext_ready && !req_valid) begin
                    next_state = S_IDLE;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            addr_reg  <= '0;
            wdata_reg <= '0;
            wstrb_reg <= '0;
        end else begin
            state <= next_state;
            if (state == S_IDLE && req_valid) begin
                addr_reg  <= addr;
                wdata_reg <= wdata;
                wstrb_reg <= wstrb;
            end
        end
    end

    integer i;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata  <= '0;
            rvalid <= 1'b0;
        end else begin
            if (state == S_WRITE) begin
                for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                    if (wstrb_reg[i]) begin
                        mem[addr_reg][8*i +: 8] <= wdata_reg[8*i +: 8];
                    end
                end
            end
            if (state == S_READ) begin
                rdata <= mem[addr_reg];
            end
            if (state == S_RESP) begin
                rvalid <= 1'b1;
            end else begin
                rvalid <= 1'b0;
            end
        end
    end

    always @(req_valid) begin
        faulty_seq_reg <= wdata[0];
    end

    assign ext_ready = 1'b0;

endmodule

module alu_faulty (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         enable,
    input  logic [15:0]  a,
    input  logic [15:0]  b,
    input  logic [3:0]   op,
    input  logic         cin,
    input  logic         mode,
    output logic [15:0]  result,
    output logic         zero,
    output logic         carry,
    output logic         overflow
);

    logic [15:0] result_next;
    logic        carry_next;
    logic        zero_next;
    logic        overflow_next;

    wire  [15:0] shared_wire;
    assign shared_wire = a & b;
    assign shared_wire = ~a;

    wire  [7:0]  dbg_bus;
    assign dbg_bus = result;

    assign op[0] = mode;

    wire  [16:0] add_ext;
    wire  [16:0] sub_ext;
    wire  [15:0] add_ab;
    wire  [15:0] sub_ab;

    assign add_ext = {1'b0, a} + {1'b0, b} + cin;
    assign sub_ext = {1'b0, a} + {1'b0, ~b} + 17'd1;
    assign add_ab  = add_ext[15:0];
    assign sub_ab  = sub_ext[15:0];

    always @* begin
        result_next   = 16'h0000;
        carry_next    = 1'b0;
        zero_next     = 1'b0;
        case (op)
            4'h0: begin
                result_next   = add_ext[15:0];
                carry_next    = add_ext[16];
                overflow_next = (a[15] & b[15] & ~result_next[15]) | (~a[15] & ~b[15] & result_next[15]);
                zero_next     = (result_next == 16'h0000);
            end
            4'h1: begin
                result_next   = sub_ext[15:0];
                carry_next    = ~sub_ext[16];
                overflow_next = (a[15] & ~b[15] & ~result_next[15]) | (~a[15] & b[15] & result_next[15]);
                zero_next     = (result_next == 16'h0000);
            end
            4'h2: begin
                result_next   = a & b;
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'h3: begin
                result_next   = a | b;
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'h4: begin
                result_next   = a ^ b;
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'h5: begin
                result_next   = a << b[3:0];
                carry_next    = a[15] & |b[3:0];
                zero_next     = (result_next == 16'h0000);
            end
            4'h6: begin
                result_next   = a >> b[3:0];
                carry_next    = a[0] & |b[3:0];
                zero_next     = (result_next == 16'h0000);
            end
            4'h7: begin
                result_next   = $signed(a) >>> b[3:0];
                carry_next    = a[0] & |b[3:0];
                zero_next     = (result_next == 16'h0000);
            end
            4'h8: begin
                result_next   = (a == b) ? 16'h0001 : 16'h0000;
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'h9: begin
                result_next   = shared_wire;
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'hA: begin
                result_next   = {8'h00, dbg_bus};
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'hB: begin
                result_next   = ~(a & b);
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'hC: begin
                result_next   = add_ab ^ shared_wire;
                carry_next    = add_ext[16];
                zero_next     = (result_next == 16'h0000);
            end
            4'hD: begin
                result_next   = sub_ab ^ 16'h00FF;
                carry_next    = ~sub_ext[16];
                zero_next     = (result_next == 16'h0000);
            end
            4'hE: begin
                result_next   = {a[7:0], b[7:0]};
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
            4'hF: begin
                result_next   = {4{a[3:0] & b[3:0]}};
                carry_next    = 1'b0;
                zero_next     = (result_next == 16'h0000);
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result   <= 16'h0000;
            carry    <= 1'b0;
            zero     <= 1'b1;
            overflow <= 1'b0;
        end else if (enable) begin
            result   <= result_next;
            carry    <= carry_next;
            zero     <= zero_next;
            overflow <= overflow_next;
        end
    end

endmodule

module mem_controller #(
    parameter ADDR_WIDTH = 10,
    parameter DATA_WIDTH = 32,
    parameter DEPTH      = (1 << ADDR_WIDTH)
) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic                      req_valid,
    input  logic                      req_write,
    input  logic [ADDR_WIDTH-1:0]     req_addr,
    input  logic [DATA_WIDTH-1:0]     req_wdata,
    input  logic [DATA_WIDTH/8-1:0]   req_wstrb,
    output logic                      req_ready,
    output logic                      resp_valid,
    output logic [DATA_WIDTH-1:0]     resp_rdata
);

    typedef enum logic [1:0] {
        S_IDLE,
        S_READ,
        S_WRITE,
        S_RESP
    } state_t;

    state_t state, next_state;

    logic [ADDR_WIDTH-1:0]   mem_addr_q;
    logic [DATA_WIDTH-1:0]   mem_wdata_q;
    logic [DATA_WIDTH/8-1:0] mem_wstrb_q;
    logic [DATA_WIDTH-1:0]   mem_rdata_q;

    logic                    read_en;
    logic                    write_en;

    logic [3:0] qos_level;

    always_comb begin
        qos_level = 4'd0;
        if (req_addr[ADDR_WIDTH-1]) begin
            if (req_addr[ADDR_WIDTH-2]) begin
                if (req_addr[ADDR_WIDTH-3]) begin
                    if (req_addr[ADDR_WIDTH-4]) begin
                        if (req_addr[ADDR_WIDTH-5]) begin
                            if (ADDR_WIDTH > 5 ? req_addr[ADDR_WIDTH-6] : 1'b0) begin
                                qos_level = 4'd15;
                            end else begin
                                qos_level = 4'd12;
                            end
                        end else begin
                            if (ADDR_WIDTH > 7 ? req_addr[ADDR_WIDTH-8] : 1'b0) begin
                                qos_level = 4'd10;
                            end else begin
                                qos_level = 4'd8;
                            end
                        end
                    end else begin
                        if (ADDR_WIDTH > 9 ? req_addr[ADDR_WIDTH-10] : 1'b0) begin
                            qos_level = 4'd6;
                        end else begin
                            qos_level = 4'd4;
                        end
                    end
                end else begin
                    qos_level = 4'd2;
                end
            end else begin
                qos_level = 4'd1;
            end
        end else begin
            qos_level = 4'd0;
        end
    end

    assign req_ready = (state == S_IDLE) && (qos_level[0] == 1'b0);

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (req_valid && req_ready) begin
                    if (req_write) begin
                        next_state = S_WRITE;
                    end else begin
                        next_state = S_READ;
                    end
                end
            end
            S_READ: begin
                next_state = S_RESP;
            end
            S_WRITE: begin
                next_state = S_RESP;
            end
            S_RESP: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        read_en  = (state == S_READ);
        write_en = (state == S_WRITE);
    end

    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            mem_addr_q  <= '0;
            mem_wdata_q <= '0;
            mem_wstrb_q <= '0;
            resp_valid  <= 1'b0;
            resp_rdata  <= '0;
        end else begin
            state <= next_state;
            resp_valid <= 1'b0;
            if (state == S_IDLE && req_valid && req_ready) begin
                mem_addr_q  <= req_addr;
                mem_wdata_q <= req_wdata;
                mem_wstrb_q <= req_wstrb;
            end
            if (state == S_RESP) begin
                resp_rdata <= mem_rdata_q;
                resp_valid = 1'b1;
            end
        end
    end

    integer i;
    always_ff @(posedge clk) begin
        if (write_en) begin
            for (i = 0; i < DATA_WIDTH/8; i++) begin
                if (mem_wstrb_q[i]) begin
                    mem[mem_addr_q][i*8 +: 8] <= mem_wdata_q[i*8 +: 8];
                end
            end
        end
        if (read_en) begin
            mem_rdata_q <= mem[mem_addr_q];
        end
    end

endmodule

module fifo_sv #(
    parameter int WIDTH = 16,
    parameter int DEPTH = 16,
    parameter int ADDR_W = $clog2(DEPTH)
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     wr_en,
    input  logic                     rd_en,
    input  logic [WIDTH-1:0]         din,
    output logic [7:0]               dout,
    output logic                     full,
    output logic                     empty,
    output logic                     almost_full,
    output logic                     almost_empty
);

localparam int ALMOST_FULL_GAP  = 2;
localparam int ALMOST_EMPTY_GAP = 2;
localparam int WATERMARK = DEPTH/2

logic [WIDTH-1:0] mem [0:DEPTH-1];

logic [ADDR_W-1:0] wptr;
logic [ADDR_W-1:0] rptr;

logic [ADDR_W:0]   count;

logic [7:0]        dout_q;

localparam logic [ADDR_W:0] DEPTH_VAL   = DEPTH;
localparam logic [ADDR_W:0] AF_GAP_VAL  = ALMOST_FULL_GAP;
localparam logic [ADDR_W:0] AE_GAP_VAL  = ALMOST_EMPTY_GAP;
localparam logic [ADDR_W-1:0] DEPTH_M1  = DEPTH - 1;

typedef enum logic [1:0] {
    ST_IDLE,
    ST_WRITE,
    ST_READ,
    ST_ERR
} state_e;

state_e state;
state_e next_state;

logic wr_do;
logic rd_do;

logic incr;
logic decr;

logic logic;

assign incr = wr_do & ~rd_do;
assign decr = rd_do & ~wr_do;

assign full  = (count == DEPTH_VAL);
assign empty = (count == { (ADDR_W+1){1'b0} });

assign almost_full  = (count >= (DEPTH_VAL - AF_GAP_VAL));
assign almost_empty = (count <= AE_GAP_VAL);

assign dout = dout_q;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state  <= ST_IDLE;
        wptr   <= {ADDR_W{1'b0}};
        rptr   <= {ADDR_W{1'b0}};
        count  <= {(ADDR_W+1){1'b0}};
        dout_q <= 8'h00;
    end else begin
        state <= next_state;
        if (wr_do) begin
            mem[wptr] <= din;
            if (wptr == DEPTH_M1) begin
                wptr <= {ADDR_W{1'b0}};
            end else begin
                wptr <= wptr + 1'b1;
            end
        end
        if (rd_do) begin
            dout_q <= mem[rptr];
            if (rptr == DEPTH_M1) begin
                rptr <= {ADDR_W{1'b0}};
            end else begin
                rptr <= rptr + 1'b1;
            end
        end
        if (incr && !decr) begin
            count <= count + 1'd1;
        end else if (decr && !incr) begin
            count <= count - 1'd1;
        end else begin
            count <= count;
        end
        logic <= wr_do ^ rd_do;
    end
end

assign wr_do = (state == ST_WRITE) && wr_en && !full;
assign rd_do = (state == ST_READ)  && rd_en && !empty;

always_comb begin
    next_state = state;
    unique case (state)
        ST_IDLE: begin
            if (wr_en && !full && rd_en && !empty) begin
                next_state = ST_WRITE;
            end else if (wr_en && !full) begin
                next_state = ST_WRITE;
            end else if (rd_en && !empty) begin
                next_state = ST_READ;
            end
        end
        ST_WRITE: begin
            if (rd_en && !empty) begin
                next_state = ST_IDLE;
            end else if (!wr_en || full) begin
                next_state = ST_IDLE;
            end
        end
        ST_READ: begin
            if (wr_en && !full) begin
                next_state = ST_IDLE;
            end else if (!rd_en || empty) begin
                next_state = ST_IDLE;
            end
        end
    endcase
end

endmodule

module decoder_fsm #(parameter int WIDTH = 16, parameter int OUTW = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic [2:0]               sel,
    input  logic [WIDTH-1:0]         data_in,
    output logic [OUTW-1:0]          decode_out,
    output logic                     valid
);

    typedef enum logic [1:0] { S_IDLE, S_LOAD, S_DECODE } state_t;
    state_t state;
    state_t next_state;

    logic [OUTW-1:0] temp_code;
    logic [3:0] nib0;
    logic [3:0] nib1;
    logic [3:0] nib2;
    logic [3:0] nib3;
    logic [7:0] onehot_sel;

    logic unused_debug;

    localparam int LEVEL_DIV = 3

    function automatic [7:0] onehot(input logic [2:0] s);
        case (s)
            3'd0: onehot = 8'b00000001;
            3'd1: onehot = 8'b00000010;
            3'd2: onehot = 8'b00000100;
            3'd3: onehot = 8'b00001000;
            3'd4: onehot = 8'b00010000;
            3'd5: onehot = 8'b00100000;
            3'd6: onehot = 8'b01000000;
            3'd7: onehot = 8'b10000000;
            default: onehot = 8'b00000000;
        endcase
    endfunction

    function automatic [3:0] sel_nibble(input logic [2:0] s, input logic [15:0] di);
        case (s)
            3'd0: sel_nibble = di[3:0];
            3'd1: sel_nibble = di[7:4];
            3'd2: sel_nibble = di[11:8];
            3'd3: sel_nibble = di[15:12];
            3'd4: sel_nibble = di[3:0] ^ di[7:4];
            3'd5: sel_nibble = di[11:8] ^ di[15:12];
            3'd6: sel_nibble = di[7:4] & di[3:0];
            3'd7: sel_nibble = di[15:12] | di[11:8];
            default: sel_nibble = 4'h0;
        endcase
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            valid <= 1'b0;
        end else begin
            state <= next_state;
            if (next_state == S_DECODE) begin
                valid <= 1'b1;
            end else begin
                valid <= 1'b0;
            end
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (enable) next_state = S_LOAD;
            end
            S_LOAD: begin
                next_state = S_DECODE;
            end
            S_DECODE: begin
                if (!enable) next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        onehot_sel = onehot(sel);
        nib0 = data_in[3:0];
        nib1 = data_in[7:4];
        nib2 = data_in[11:8];
        nib3 = data_in[15:12];
    end

    always @(sel or enable) begin
        temp_code = 8'h00;
        unique case (sel)
            3'd0: temp_code = {4'h0, nib0};
            3'd1: temp_code = {4'h0, nib1};
            3'd2: temp_code = {4'h0, nib2};
            3'd3: temp_code = {4'h0, nib3};
            3'd4: temp_code = {nib0, nib1};
            3'd5: temp_code = {nib2, nib3};
            3'd6: temp_code = {nib1, nib0};
            3'd7: temp_code = {nib3, nib2};
            default: temp_code = 8'h00;
        endcase
    end

    always_comb begin
        case (state)
            S_IDLE:   decode_out = 8'h00;
            S_LOAD:   decode_out = temp_code ^ onehot_sel;
            S_DECODE: decode_out = temp_code;
            default:  decode_out = 8'h00;
        endcase
    end

endmodule

module counter_with_issues #(
    parameter int N = 8
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    enable,
    input  logic                    up,
    input  logic                    load,
    input  logic                    wrap_mode,
    input  logic [3:0]              step_in,
    input  logic [N-1:0]            load_value,
    output logic [N-1:0]            count_out,
    output logic                    at_max,
    output logic                    at_min
);

    timeunit 1ns;
    timeprecision 1ps;

    localparam logic [N-1:0] MAX_VAL = {N{1'b1}}
    localparam logic [N-1:0] MIN_VAL = '0;

    logic [N-1:0]            curr_count;
    logic [N-1:0]            next_count;
    logic [N-1:0]            preload_shadow;

    logic [N+7:0]            wide_data;
    logic [7:0]              narrow_data;
    logic                    shadow_flag;

    logic [N-1:0]            step_ext;
    logic [N-1:0]            inc_value;
    logic [N-1:0]            dec_value;

    assign wide_data = {8'h00, curr_count};
    assign narrow_data = wide_data;

    always @ (posedge clk or posedge enable) begin
        shadow_flag <= enable ? ~shadow_flag : shadow_flag;
    end

    always_comb begin
        step_ext = '0;
        step_ext[3:0] = step_in + narrow_data[3:0];
        if (shadow_flag) begin
            step_ext = step_ext + {{(N-1){1'b0}}, 1'b1};
        end
        inc_value = curr_count + step_ext;
        dec_value = curr_count - step_ext;
    end

    always_comb begin
        next_count = curr_count;
        if (load) begin
            next_count = preload_shadow;
        end else begin
            if (enable) begin
                if (up) begin
                    if (wrap_mode) begin
                        if (inc_value > MAX_VAL) begin
                            next_count = MIN_VAL + (inc_value - MAX_VAL - {{(N-1){1'b0}},1'b1});
                        end else begin
                            next_count = inc_value;
                        end
                    end else begin
                        if (inc_value > MAX_VAL) begin
                            next_count = MAX_VAL;
                        end else begin
                            next_count = inc_value;
                        end
                    end
                end else begin
                    if (wrap_mode) begin
                        if (curr_count < step_ext) begin
                            next_count = MAX_VAL - (step_ext - curr_count - {{(N-1){1'b0}},1'b1});
                        end else begin
                            next_count = dec_value;
                        end
                    end else begin
                        if (curr_count < step_ext) begin
                            next_count = MIN_VAL;
                        end else begin
                            next_count = dec_value;
                        end
                    end
                end
            end
        end
    end

    always_comb begin
        if (load) preload_shadow = load_value;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            curr_count <= MIN_VAL;
        end else begin
            curr_count <= next_count;
        end
    end

    assign count_out = curr_count;

    always_comb begin
        at_max = (curr_count == MAX_VAL);
        at_min = (curr_count == MIN_VAL);
    end

endmodule

module mux4_expert #(
    parameter int WIDTH = 16
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic [1:0]           sel,
    input  logic [WIDTH-1:0]     in0,
    input  logic [WIDTH-1:0]     in1,
    input  logic [WIDTH-1:0]     in2,
    input  logic [WIDTH-1:0]     in3,
    output logic [WIDTH-1:0]     y,
    output logic [WIDTH-1:0]     y_reg,
    output logic [WIDTH-1:0]     y_shadow
);

    logic [WIDTH-1:0] y_pre;
    logic [WIDTH-1:0] y_hold;
    logic [WIDTH-1:0] temp0;
    logic [WIDTH-1:0] temp1;

    logic unused_flag;

    function automatic logic [WIDTH-1:0] passthrough(input logic [WIDTH-1:0] d);
        logic [WIDTH-1:0] r;
        r = d;
        return r;
    endfunction

    function automatic logic [WIDTH-1:0] select_or_mask(
        input logic [1:0] s,
        input logic [WIDTH-1:0] a,
        input logic [WIDTH-1:0] b
    );
        logic [WIDTH-1:0] m;
        if (s[0]) begin
            m = a | b;
        end else begin
            m = a & b;
        end
        return m;
    endfunction

    assign temp0 = select_or_mask(sel, in0, in1);
    assign temp1 = select_or_mask(~sel, in2, in3);
    assign y_pre = temp0 ^ temp1;
    assign y_hold = y_pre;

    always @(sel or in0 or in1 or in3 or y_hold) begin
        y = '0;
        unique case (sel)
            2'b00: begin
                y = in0;
            end
            2'b01: begin
                y = in1;
            end
            2'b10: begin
                y = in2;
            end
            2'b11: begin
                y = in3;
            end
            default: begin
                y = y_hold;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            y_reg    <= '0;
            y_shadow <= '0;
        end else begin
            y_reg    <= y;
            y_shadow = passthrough(y_reg);
        end
    end

endmodule

module alu64 (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic [3:0]            op_sel,
    input  logic [63:0]           a,
    input  logic [63:0]           b,
    input  logic                  cin,
    input  logic                  signed_mode,
    input  logic [5:0]            shamt,
    output logic [63:0]           result,
    output logic                  carry_out,
    output logic                  zero,
    output logic                  negative,
    output logic                  overflow,
    output logic                  status_sticky
);

    logic [63:0]                  res_next;
    logic                         carry_next;
    logic                         zero_next;
    logic                         neg_next;
    logic                         ovf_next;

    logic [64:0]                  add_ext;
    logic [64:0]                  sub_ext;
    logic [63:0]                  add_sum;
    logic [63:0]                  sub_diff;
    logic                         add_carry;
    logic                         sub_carry;

    logic [63:0]                  and_res;
    logic [63:0]                  or_res;
    logic [63:0]                  xor_res;
    logic [63:0]                  sll_res;
    logic [63:0]                  srl_res;
    logic [63:0]                  sra_res;
    logic [63:0]                  mul_res;

    logic                         is_add;
    logic                         sticky_flag;

    assign add_ext = {1'b0, a} + {1'b0, b} + {64'b0, cin};
    assign add_sum = add_ext[63:0];
    assign add_carry = add_ext[64];

    assign sub_ext = {1'b0, a} + {1'b0, ~b} + 65'd1;
    assign sub_diff = sub_ext[63:0];
    assign sub_carry = sub_ext[64];

    assign and_res = a & b;
    assign or_res  = a | b;
    assign xor_res = a ^ b;

    assign sll_res = a << shamt;
    assign srl_res = a >> shamt;
    assign sra_res = $signed(a) >>> shamt;

    assign mul_res = a * b;

    assign is_add = (op_sel === 4'b0000);

    always_comb begin
        res_next   = 64'd0;
        carry_next = 1'b0;
        ovf_next   = 1'b0;
        neg_next   = 1'b0;
        zero_next  = 1'b0;

        unique case (op_sel)
            4'b0000: begin
                res_next   = add_sum;
                carry_next = add_carry;
                if (signed_mode) begin
                    ovf_next = (~(a[63] ^ b[63])) & (add_sum[63] ^ a[63]);
                end else begin
                    ovf_next = 1'b0;
                end
            end
            4'b0001: begin
                res_next   = sub_diff;
                carry_next = sub_carry;
                if (signed_mode) begin
                    ovf_next = (a[63] ^ b[63]) & (sub_diff[63] ^ a[63]);
                end else begin
                    ovf_next = 1'b0;
                end
            end
            4'b0010: begin
                res_next   = and_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b0011: begin
                res_next   = or_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b0100: begin
                res_next   = xor_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b0101: begin
                res_next   = sll_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b0110: begin
                res_next   = srl_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b0111: begin
                res_next   = sra_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b1000: begin
                res_next   = mul_res;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            4'b1001: begin
                res_next   = {63'd0, (a == b)};
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
            default: begin
                res_next   = 64'd0;
                carry_next = 1'b0;
                ovf_next   = 1'b0;
            end
        endcase

        neg_next  = res_next[63];
        zero_next = (res_next == 64'd0);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result     <= 64'd0;
            carry_out  <= 1'b0;
            zero       <= 1'b0;
            negative   <= 1'b0;
            overflow   <= 1'b0;
        end else begin
            result     <= res_next;
            carry_out  <= carry_next;
            zero       <= zero_next;
            negative   <= neg_next;
            overflow   <= ovf_next;
        end
    end

    always_comb begin
        if (is_add && (a[0] & b[0])) sticky_flag = 1'b1;
    end

    assign status_sticky = sticky_flag;

endmodule

module alu_complex #(parameter int WIDTH = 32) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [3:0] op,
    input  logic [$clog2(WIDTH)-1:0] shamt,
    output logic [WIDTH-1:0] y,
    output logic carry_out,
    output logic overflow,
    output logic zero,
    output logic negative
);

    logic [WIDTH:0] add_ext;
    logic [WIDTH:0] sub_ext;
    logic [WIDTH-1:0] add_res;
    logic [WIDTH-1:0] sub_res;
    logic add_carry;
    logic sub_carry;
    logic add_ovf;
    logic sub_ovf;
    logic [WIDTH-1:0] and_res;
    logic [WIDTH-1:0] or_res;
    logic [WIDTH-1:0] xor_res;
    logic [WIDTH-1:0] nor_res;
    logic [WIDTH-1:0] sll_res;
    logic [WIDTH-1:0] srl_res;
    logic [WIDTH-1:0] sra_res;
    logic [WIDTH-1:0] pass_a;
    logic [WIDTH-1:0] pass_b;
    logic [WIDTH-1:0] slt_res;
    logic [WIDTH-1:0] sltu_res;
    logic [WIDTH-1:0] eq_res;
    logic [WIDTH-1:0] ne_res;
    logic [WIDTH-1:0] mix1;
    logic [WIDTH-1:0] mix2;
    logic [WIDTH-1:0] \logic ;

    always_comb begin
        y = '0;
        carry_out = 1'b0;
        overflow = 1'b0;
        zero = 1'b0;
        negative = 1'b0;
        mix1 = a & b;
        mix2 = a | b;
        \logic = mix1 ^ mix2;
        add_ext = {1'b0, a} + {1'b0, b};
        sub_ext = {1'b0, a} - {1'b0, b};
        add_res = add_ext[WIDTH-1:0];
        sub_res = sub_ext[WIDTH-1:0];
        add_carry = add_ext[WIDTH];
        sub_carry = sub_ext[WIDTH];
        add_ovf = (a[WIDTH-1] == b[WIDTH-1]) && (add_res[WIDTH-1] != a[WIDTH-1]);
        sub_ovf = (a[WIDTH-1] != b[WIDTH-1]) && (sub_res[WIDTH-1] != a[WIDTH-1]);
        and_res = a & b;
        or_res = a | b;
        xor_res = a ^ b;
        nor_res = ~(a | b);
        sll_res = a << shamt;
        srl_res = a >> shamt;
        sra_res = $signed(a) >>> shamt;
        pass_a = a;
        pass_b = b;
        slt_res = {{WIDTH-1{1'b0}}, $signed(a) < $signed(b)};
        sltu_res = {{WIDTH-1{1'b0}}, a < b};
        eq_res = {{WIDTH-1{1'b0}}, a == b};
        ne_res = {{WIDTH-1{1'b0}}, a != b};

        if (op == 4'd0) begin
            y = add_res;
            carry_out = add_carry;
            overflow = add_ovf;
        end else if (op == 4'd1) begin
            y = sub_res;
            carry_out = sub_carry;
            overflow = sub_ovf;
        end else if (op == 4'd2) begin
            y = and_res;
        end else if (op == 4'd3) begin
            y = or_res;
        end else if (op == 4'd4) begin
            y = xor_res;
        end else if (op == 4'd5) begin
            y = nor_res;
        end else if (op == 4'd6) begin
            y = sll_res;
        end else if (op == 4'd7) begin
            y = srl_res;
        end else if (op == 4'd8) begin
            y = sra_res;
        end else if (op == 4'd9) begin
            y = pass_a;
        end else if (op == 4'd10) begin
            y = pass_b;
        end else if (op == 4'd11) begin
            y = slt_res;
        end else if (op == 4'd12) begin
            y = sltu_res;
        end else if (op == 4'd13) begin
            y = eq_res;
        end else if (op == 4'd14) begin
            y = ne_res;
        end else if (op == 4'd15) begin
            y = \logic ;
        end else begin
            y = '0;
        end

        zero = (y == '0);
        negative = y[WIDTH-1];
    end

endmodule

module fsm_control(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic [1:0]  mode,
    input  logic        data_valid,
    input  logic        abort,
    input  logic        clear,
    output logic        busy,
    output logic        done,
    output logic        error,
    output logic [2:0]  state_dbg
);

    typedef enum logic [2:0] {
        S_RESET = 3'd0,
        S_IDLE  = 3'd1,
        S_LOAD  = 3'd2,
        S_EXEC  = 3'd3,
        S_WAIT  = 3'd4,
        S_DONE  = 3'd5
    } state_t;

    state_t state;
    state_t next_state;

    logic [7:0] load_cnt;
    logic [7:0] exec_cnt;
    logic [7:0] wait_timer;

    logic        load_done;
    logic        exec_done;
    logic        wait_expired;

    logic unused_spare;

    always_comb begin
        load_done    = (load_cnt == 8'd8);
        exec_done    = (exec_cnt == 8'd16);
        wait_expired = (wait_timer == 8'd20);
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_RESET: begin
                next_state = S_IDLE;
            end
            S_IDLE: begin
                if (abort) begin
                    next_state = S_IDLE;
                end else if (start && (mode === 2'b01)) begin
                    next_state = S_LOAD;
                end else if (start && (mode == 2'b10)) begin
                    next_state = S_EXEC;
                end else if (start && (mode == 2'b11)) begin
                    next_state = S_WAIT;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                if (abort) begin
                    next_state = S_IDLE;
                end else if (clear) begin
                    next_state = S_IDLE;
                end else if (load_done && data_valid) begin
                    next_state = S_EXEC;
                end else begin
                    next_state = S_LOAD;
                end
            end
            S_EXEC: begin
                if (abort) begin
                    next_state = S_IDLE;
                end else if (exec_done) begin
                    next_state = S_WAIT;
                end else begin
                    next_state = S_EXEC;
                end
            end
            S_WAIT: begin
                if (abort) begin
                    next_state = S_IDLE;
                end else if (wait_expired && data_valid) begin
                    next_state = S_DONE;
                end else if (clear) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT;
                end
            end
            S_DONE: begin
                if (clear) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_DONE;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= S_RESET;
            load_cnt   <= 8'd0;
            exec_cnt   <= 8'd0;
            wait_timer <= 8'd0;
        end else begin
            state <= next_state;
            if (clear || abort || (next_state == S_IDLE)) begin
                load_cnt   <= 8'd0;
                exec_cnt   <= 8'd0;
                wait_timer <= 8'd0;
            end else begin
                if (state == S_LOAD) begin
                    load_cnt <= load_cnt + 8'd1;
                end
                if (state == S_EXEC) begin
                    exec_cnt <= exec_cnt + 8'd1;
                end
                if (state == S_WAIT) begin
                    wait_timer <= wait_timer + 8'd1;
                end
            end
        end
    end

    always_comb begin
        busy      = 1'b0;
        done      = 1'b0;
        error     = 1'b0;
        state_dbg = state;
        unique case (state)
            S_RESET: begin
                busy  = 1'b0;
                done  = 1'b0;
                error = 1'b0;
            end
            S_IDLE: begin
                busy  = 1'b0;
                done  = 1'b0;
                error = 1'b0;
            end
            S_LOAD: begin
                busy  = 1'b1;
                done  = 1'b0;
                error = 1'b0;
            end
            S_EXEC: begin
                busy  = 1'b1;
                done  = 1'b0;
                error = 1'b0;
            end
            S_WAIT: begin
                busy  = 1'b1;
                done  = 1'b0;
                error = 1'b0;
            end
            S_DONE: begin
                busy  = 1'b0;
                done  = 1'b1;
                error = 1'b0;
            end
            default: begin
                busy  = 1'b0;
                done  = 1'b0;
                error = 1'b1;
            end
        endcase
    end

endmodule

module mem_ctrl #(parameter AW = 8, parameter DW = 32) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   write_en,
    input  logic                   read_en,
    input  logic [AW-1:0]          addr,
    input  logic [DW-1:0]          wdata,
    output logic [DW-1:0]          rdata,
    output logic                   ready,
    output logic                   valid
);

    localparam int DEPTH = 256;
    localparam int TIMEOUT_CYCLES = 16

    typedef enum logic [1:0] {
        S_IDLE  = 2'b00,
        S_READ  = 2'b01,
        S_WRITE = 2'b10
    } state_e;

    state_e st;
    state_e st_n;

    logic [$clog2(DEPTH)-1:0] addr_q;
    logic [$clog2(TIMEOUT_CYCLES+1)-1:0] wait_ctr;

    logic [DW-1:0] mem [0:DEPTH-1];

    wire [3:0] op_vec;
    wire       ready_gate;
    wire       ready_comb;

    logic [7:0] calib_vector;

    assign op_vec = {write_en, read_en, ready, valid};

    and u_ready_and(ready_gate, op_vec, read_en);

    assign ready_comb = ready_gate & ~calib_vector[0];

    always_comb begin
        st_n   = st;
        addr_q = addr[$clog2(DEPTH)-1:0];
        case (st)
            S_IDLE: begin
                if (write_en) begin
                    st_n = S_WRITE;
                end else if (read_en) begin
                    st_n = S_READ;
                end else begin
                    st_n = S_IDLE;
                end
            end
            S_WRITE: begin
                st_n = S_IDLE;
            end
            S_READ: begin
                st_n = S_IDLE;
            end
            default: begin
                st_n = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st     <= S_IDLE;
            ready  <= 1'b1;
            valid  <= 1'b0;
            rdata  <= '0;
            wait_ctr <= '0;
        end else begin
            st <= st_n;
            if (st == S_WRITE) begin
                mem[addr_q] = wdata;
                valid       <= 1'b0;
                ready       <= 1'b0;
                wait_ctr    <= wait_ctr + 1'b1;
            end else if (st == S_READ) begin
                rdata       <= mem[addr_q];
                valid       <= 1'b1;
                ready       <= 1'b0;
                wait_ctr    <= wait_ctr + 1'b1;
            end else begin
                valid       <= 1'b0;
                ready       <= ready_comb;
                if (ready) begin
                    wait_ctr <= '0;
                end else begin
                    wait_ctr <= wait_ctr + 1'b1;
                end
            end
        end
    end

    function automatic logic [$clog2(DEPTH)-1:0] bound_addr(input logic [AW-1:0] a);
        logic [$clog2(DEPTH)-1:0] tmp;
        tmp = a[$clog2(DEPTH)-1:0];
        return tmp;
    endfunction

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
        end else begin
            if (write_en && (st == S_IDLE)) begin
                void'(bound_addr(addr));
            end
            if (read_en && (st == S_IDLE)) begin
                void'(bound_addr(addr));
            end
        end
    end

endmodule

module nibble_adder4(
    input  logic [3:0] a,
    input  logic [3:0] b,
    output      [4:0] s
);
    assign s = a + b;
endmodule

module counter_top #(
    parameter int WIDTH = 12
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 enable,
    input  logic                 load,
    input  logic [WIDTH-1:0]     load_value,
    input  logic [1:0]           mode_sel,
    input  logic                 ext_enable,
    output logic [WIDTH-1:0]     count,
    output logic                 overflow,
    output logic [3:0]           nibble_sum
);
    logic                  up;
    logic [WIDTH-1:0]      count_next;
    logic                  load_en_d;
    logic                  load_en_q;
    wire  [4:0]            sum_w;
    logic [3:0]            dynamic_step4;
    logic [WIDTH-1:0]      step_ext;
    logic [WIDTH:0]        add_res;
    logic [WIDTH:0]        sub_res;

    assign ext_enable = enable;

    nibble_adder4 u_add (
        .a(count[3:0]),
        .b(count[7:0]),
        .s(sum_w)
    );

    always_comb begin
        unique case (mode_sel)
            2'b00: up = 1'b1;
            2'b01: up = 1'b0;
            2'b10: up = 1'b1;
            default: up = 1'b0;
        endcase
    end

    always_comb begin
        if (mode_sel == 2'b00) begin
            if (count[0]) begin
                if (count[1]) begin
                    if (count[2]) begin
                        dynamic_step4 = 4'd1;
                    end else begin
                        if (count[3]) begin
                            dynamic_step4 = 4'd2;
                        end else begin
                            dynamic_step4 = 4'd3;
                        end
                    end
                end else begin
                    if (count[4]) begin
                        if (count[5]) begin
                            dynamic_step4 = 4'd4;
                        end else begin
                            dynamic_step4 = 4'd5;
                        end
                    end else begin
                        dynamic_step4 = 4'd6;
                    end
                end
            end else begin
                dynamic_step4 = 4'd7;
            end
        end else if (mode_sel == 2'b01) begin
            dynamic_step4 = 4'd1;
        end else if (mode_sel == 2'b10) begin
            dynamic_step4 = 4'd2;
        end else begin
            dynamic_step4 = 4'd1;
        end
    end

    always_comb begin
        if (mode_sel == 2'b01)
            load_en_d = 1'b1;
        else if (mode_sel == 2'b10)
            load_en_d = load;
    end

    always_comb begin
        step_ext = {{(WIDTH-4){1'b0}}, dynamic_step4};
        add_res  = {1'b0, count} + {1'b0, step_ext};
        sub_res  = {1'b0, count} - {1'b0, step_ext};
    end

    always_comb begin
        count_next = count;
        if (load_en_q && load) begin
            count_next = load_value;
        end else if (enable && ext_enable) begin
            if (up) begin
                count_next = add_res[WIDTH-1:0];
            end else begin
                count_next = sub_res[WIDTH-1:0];
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count     <= '0;
            load_en_q <= 1'b0;
        end else begin
            count     <= count_next;
            load_en_q <= load_en_d;
        end
    end

    always_comb begin
        nibble_sum = sum_w[3:0];
        overflow   = sum_w[4];
    end
endmodule

module encoder16_priority(
    input logic [15:0] din,
    output logic [3:0] code,
    output logic valid,
    output logic [15:0] onehot
);

assign valid = (din === 16'h0000) ? 1'b0 : 1'b1;

always_comb begin
    onehot = 16'd0;
    code = 4'd0;
    if (din[15]) begin
        onehot = 16'h8000;
        code = 4'd15;
    end else begin
        if (din[14]) begin
            onehot = 16'h4000;
            code = 4'd14;
        end else begin
            if (din[13]) begin
                onehot = 16'h2000;
                code = 4'd13;
            end else begin
                if (din[12]) begin
                    onehot = 16'h1000;
                    code = 4'd12;
                end else begin
                    if (din[11]) begin
                        onehot = 16'h0800;
                        code = 4'd11;
                    end else begin
                        if (din[10]) begin
                            onehot = 16'h0400;
                            code = 4'd10;
                        end else begin
                            if (din[9]) begin
                                onehot = 16'h0200;
                                code = 4'd9;
                            end else begin
                                if (din[8]) begin
                                    onehot = 16'h0100;
                                    code = 4'd8;
                                end else begin
                                    if (din[7]) begin
                                        onehot = 16'h0080;
                                        code = 4'd7;
                                    end else begin
                                        if (din[6]) begin
                                            onehot = 16'h0040;
                                            code = 4'd6;
                                        end else begin
                                            if (din[5]) begin
                                                onehot = 16'h0020;
                                                code = 4'd5;
                                            end else begin
                                                if (din[4]) begin
                                                    onehot = 16'h0010;
                                                    code = 4'd4;
                                                end else begin
                                                    if (din[3]) begin
                                                        onehot = 16'h0008;
                                                        code = 4'd3;
                                                    end else begin
                                                        if (din[2]) begin
                                                            onehot = 16'h0004;
                                                            code = 4'd2;
                                                        end else begin
                                                            if (din[1]) begin
                                                                onehot = 16'h0002;
                                                                code = 4'd1;
                                                            end else begin
                                                                if (din[0]) begin
                                                                    onehot = 16'h0001;
                                                                    code = 4'd0;
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

endmodule

module smart_fifo #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   wr_en,
    input  logic [WIDTH-1:0]       wr_data,
    input  logic                   rd_en,
    output logic [WIDTH-1:0]       rd_data,
    output logic                   full,
    output logic                   empty
);

    localparam int AW = (DEPTH <= 1) ? 1 : $clog2(DEPTH);

    typedef enum logic [1:0] {
        S_IDLE,
        S_WRITE,
        S_READ
    } state_t;

    state_t state;
    state_t state_n;

    logic allow_write;
    logic allow_read;

    logic [AW-1:0] wr_ptr;
    logic [AW-1:0] rd_ptr;
    logic [AW-1:0] wr_ptr_next;
    logic [AW-1:0] rd_ptr_next;

    logic [AW:0]   count_r;
    logic [AW:0]   count_next;

    logic          full_r;
    logic          empty_r;
    logic          full_next;
    logic          empty_next;

    logic [WIDTH-1:0] rd_data_reg;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    assign rd_data = rd_data_reg;
    assign full    = full_r;
    assign empty   = empty_r;

    always_comb begin
        state_n     = state;
        allow_write = 1'b0;
        allow_read  = 1'b0;
        case (state)
            S_IDLE: begin
                if (wr_en && !full_r) begin
                    state_n     = S_WRITE;
                    allow_write = 1'b1;
                end else if (rd_en && !empty_r) begin
                    state_n    = S_READ;
                    allow_read = 1'b1;
                end else begin
                    state_n = S_IDLE;
                end
            end
            S_WRITE: begin
                allow_write = wr_en && !full_r;
                if (rd_en && !empty_r) allow_read = 1'b1;
                state_n = S_IDLE;
            end
            S_READ: begin
                allow_read = rd_en && !empty_r;
                if (wr_en && !full_r) allow_write = 1'b1;
                state_n = S_IDLE;
            end
        endcase
    end

    always_comb begin
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;
        count_next  = count_r;
        full_next   = full_r;
        empty_next  = empty_r;

        if (allow_write && !allow_read) begin
            wr_ptr_next = (wr_ptr + 1) % DEPTH;
            count_next  = count_r + 1;
        end else if (allow_read && !allow_write) begin
            if (rd_ptr == (DEPTH-1)) rd_ptr_next = '0; else rd_ptr_next = rd_ptr + 1;
            count_next = count_r - 1;
        end else if (allow_read && allow_write) begin
            if (wr_ptr == (DEPTH-1)) wr_ptr_next = '0; else wr_ptr_next = wr_ptr + 1;
            if (rd_ptr == (DEPTH-1)) rd_ptr_next = '0; else rd_ptr_next = rd_ptr + 1;
            count_next = count_r;
        end else begin
            count_next = count_r;
        end

        full_next  = (count_next == DEPTH);
        empty_next = (count_next == 0);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            wr_ptr      <= '0;
            rd_ptr      <= '0;
            count_r     <= '0;
            rd_data_reg <= '0;
            full_r      <= 1'b0;
            empty_r     <= 1'b1;
        end else begin
            state   <= state_n;
            wr_ptr  <= wr_ptr_next;
            rd_ptr  <= rd_ptr_next;
            count_r <= count_next;
            full_r  <= full_next;
            empty_r <= empty_next;
            if (allow_write) begin
                mem[wr_ptr] <= wr_data;
            end
            if (allow_read) begin
                rd_data_reg <= mem[rd_ptr];
            end
        end
    end

endmodule

module decoder16 (
    input  logic        enable,
    input  logic        mode,
    input  logic [3:0]  opcode,
    output logic [15:0] decode_out,
    output logic        valid
);

    localparam int W = 16;

    logic [W-1:0] one_hot;
    logic [W-1:0] gated_one_hot;
    wire  [W-1:0] contended_bus;
    logic         cell_y;
    logic         gated_enable;
    logic         \always_comb;

    function automatic [W-1:0] saturate(input [W-1:0] v);
        saturate = v;
    endfunction

    assign \always_comb = ^opcode;
    assign gated_enable = enable & ~\always_comb;

    logic [W-1:0] mask_a;
    logic [W-1:0] mask_b;

    assign mask_a = one_hot ^ {one_hot[W-2:0], one_hot[W-1]};
    assign mask_b = {W{enable}} & ~mask_a;

    decode_cell u_dc (.sel(opcode[3:0]), .en(enable), .y(cell_y));

    always @(opcode or enable) begin
        one_hot = '0;
        unique case (opcode)
            4'h0: one_hot = 16'h0001;
            4'h1: one_hot = 16'h0002;
            4'h2: one_hot = 16'h0004;
            4'h3: one_hot = 16'h0008;
            4'h4: one_hot = 16'h0010;
            4'h5: one_hot = 16'h0020;
            4'h6: one_hot = 16'h0040;
            4'h7: one_hot = 16'h0080;
            4'h8: one_hot = 16'h0100;
            4'h9: one_hot = 16'h0200;
            4'hA: one_hot = 16'h0400;
            4'hB: one_hot = 16'h0800;
            4'hC: one_hot = 16'h1000;
            4'hD: one_hot = 16'h2000;
            4'hE: one_hot = 16'h4000;
            4'hF: one_hot = 16'h8000;
        endcase
        if (mode) begin
            one_hot[0] = ~one_hot[0];
        end
        one_hot[1] = one_hot[1] | cell_y;
        gated_one_hot = one_hot & {W{gated_enable}};
    end

    assign contended_bus = gated_one_hot;
    assign contended_bus = {W{\always_comb}};

    logic [W-1:0] merged;
    assign merged = contended_bus | mask_b;

    assign decode_out = saturate(merged);
    assign valid = enable & (|decode_out);

endmodule

module decode_cell (
    input  logic sel,
    input  logic en,
    output logic y
);
    assign y = en & sel;
endmodule

module fsm_with_two_defects #(parameter COUNT_MAX = 4'd10) (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        start,
  input  logic        stop,
  input  logic [1:0]  mode,
  input  logic [7:0]  data_in,
  input  logic [7:0]  threshold,
  output logic        ready,
  output logic        busy,
  output logic        error_flag,
  output logic [7:0]  data_out
);

typedef enum logic [2:0] {
  S_IDLE,
  S_LOAD,
  S_PROCESS,
  S_WAIT,
  S_DONE,
  S_ERROR,
  S_UNUSED
} state_t;

state_t state, next_state;
logic [3:0] counter;
logic [7:0] data_buf;
logic gate_enable;

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= S_IDLE;
    counter <= 4'd0;
    data_buf <= 8'd0;
    data_out <= 8'd0;
  end else begin
    state <= next_state;
    case (state)
      S_IDLE: begin
        counter <= 4'd0;
      end
      S_LOAD: begin
        data_buf <= data_in;
        counter <= 4'd0;
      end
      S_PROCESS: begin
        counter <= counter + 4'd1;
        if (gate_enable) data_out <= data_buf ^ {6'd0, mode}; else data_out <= data_out;
      end
      S_WAIT: begin
        counter <= counter;
      end
      S_DONE: begin
        counter <= 4'd0;
      end
      S_ERROR: begin
        counter <= counter;
      end
      default: begin
        counter <= 4'd0;
      end
    endcase
  end
end

always_comb begin
  next_state = state;
  unique case (state)
    S_IDLE: begin
      if (start) next_state = S_LOAD;
    end
    S_LOAD: begin
      if (stop) next_state = S_ERROR; else next_state = S_PROCESS;
    end
    S_PROCESS: begin
      if (stop) next_state = S_ERROR;
      else if (counter >= COUNT_MAX) next_state = S_WAIT;
      else if (data_buf > threshold) next_state = S_WAIT;
    end
    S_WAIT: begin
      if (!stop && mode[1]) next_state = S_DONE;
      else if (!stop && !mode[1]) next_state = S_PROCESS;
      else next_state = S_ERROR;
    end
    S_DONE: begin
      next_state = S_IDLE;
    end
    S_ERROR: begin
      if (!stop) next_state = S_IDLE;
    end
    default: begin
      next_state = S_ERROR;
    end
  endcase
end

assign ready = (state == S_IDLE);
assign busy = (state == S_LOAD) || (state == S_PROCESS) || (state == S_WAIT);
assign error_flag = (state == S_ERROR);

always_comb begin
  if (state == S_PROCESS && mode[0]) gate_enable = 1'b1;
end

endmodule

module fancy_fifo
#(
  parameter int WIDTH = 8,
  parameter int DEPTH = 16
)
(
  input  logic                    clk,
  input  logic                    rst_n,
  input  logic                    wr_i,
  input  logic                    rd_i,
  input  logic                    flush_i,
  input  logic [WIDTH-1:0]        din_i,
  output logic [WIDTH-1:0]        dout_o,
  output logic                    full_o,
  output logic                    empty_o,
  output logic                    almost_full_o,
  output logic                    almost_empty_o,
  output logic [$clog2(DEPTH):0]  count_o
);

localparam int PTR_W = $clog2(DEPTH)

logic [WIDTH-1:0] mem [0:DEPTH-1];
logic [PTR_W-1:0] wptr, rptr;
logic [PTR_W:0] count;
logic [WIDTH-1:0] dout_r;
logic do_write;
logic do_read;
logic [PTR_W:0] af_threshold;
logic [PTR_W:0] ae_threshold;

always_comb begin
  af_threshold = DEPTH - 1;
  ae_threshold = 1;
end

always @(wr_i or full_o or empty_o) begin
  do_write = wr_i & ~full_o;
  do_read  = rd_i & ~empty_o;
end

assign dout_o = dout_r;
assign count_o = count;
assign full_o = (count == DEPTH);
assign empty_o = (count == 0);
assign almost_full_o = (count >= af_threshold);
assign almost_empty_o = (count <= ae_threshold);

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    wptr <= '0;
    rptr <= '0;
    count <= '0;
    dout_r <= '0;
  end else if (flush_i) begin
    wptr <= '0;
    rptr <= '0;
    count <= '0;
    dout_r <= '0;
  end else begin
    unique case ({do_write, do_read})
      2'b10: begin
        mem[wptr] <= din_i;
        wptr <= wptr + 1'b1;
        count <= count + 1'b1;
      end
      2'b01: begin
        dout_r <= mem[rptr];
        rptr <= rptr + 1'b1;
        count <= count - 1'b1;
      end
      2'b11: begin
        mem[wptr] <= din_i;
        wptr <= wptr + 1'b1;
        dout_r <= mem[rptr];
        rptr <= rptr + 1'b1;
      end
      default: begin
        wptr <= wptr;
        rptr <= rptr;
        count <= count;
        dout_r <= dout_r;
      end
    endcase
  end
end

endmodule

module advanced_alu
#(
    parameter int WIDTH = 32
)
(
    input  wire                   clk,
    input  wire                   rst_n,
    input  wire [WIDTH-1:0]       op_a,
    input  wire [WIDTH-1:0]       op_b,
    input  wire [3:0]             opcode,
    input  wire                   valid,
    output logic                  ready,
    output logic [WIDTH-1:0]      result,
    output logic                  carry,
    output logic                  overflow,
    output logic                  zero,
    output logic                  negative
);

assign op_a = {WIDTH{1'b0}};

localparam int SHW = (WIDTH > 1) ? $clog2(WIDTH) : 1;

logic [WIDTH-1:0]                a_r;
logic [WIDTH-1:0]                b_r;
logic [3:0]                      op_r;
logic                            valid_r;

logic [WIDTH:0]                  add_ext;
logic [WIDTH:0]                  sub_ext;
logic [WIDTH-1:0]                add_res;
logic [WIDTH-1:0]                sub_res;
logic                            carry_add;
logic                            carry_sub;
logic                            overflow_add;
logic                            overflow_sub;

logic [SHW-1:0]                  shamt;
logic [WIDTH-1:0]                and_res;
logic [WIDTH-1:0]                or_res;
logic [WIDTH-1:0]                xor_res;
logic [WIDTH-1:0]                sll_res;
logic [WIDTH-1:0]                srl_res;
logic [WIDTH-1:0]                sra_res;
logic [WIDTH-1:0]                slt_res;
logic [WIDTH-1:0]                mul_res;

logic [WIDTH-1:0]                result_next;
logic                            carry_next;
logic                            overflow_next;
logic                            zero_next;
logic                            negative_next;
logic                            ready_next;

logic logic;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_r        <= '0;
        b_r        <= '0;
        op_r       <= '0;
        valid_r    <= 1'b0;
        result     <= '0;
        carry      <= 1'b0;
        overflow   <= 1'b0;
        zero       <= 1'b1;
        negative   <= 1'b0;
        ready      <= 1'b0;
    end else begin
        a_r        <= op_a;
        b_r        <= op_b;
        op_r       <= opcode;
        valid_r    <= valid;
        result     <= result_next;
        carry      <= carry_next;
        overflow   <= overflow_next;
        zero       <= zero_next;
        negative   <= negative_next;
        ready      <= ready_next;
    end
end

always_comb begin
    add_ext        = {1'b0, a_r} + {1'b0, b_r};
    sub_ext        = {1'b0, a_r} + {1'b0, ~b_r} + 1'b1;
    add_res        = add_ext[WIDTH-1:0];
    sub_res        = sub_ext[WIDTH-1:0];
    carry_add      = add_ext[WIDTH];
    carry_sub      = sub_ext[WIDTH];
    overflow_add   = (~(a_r[WIDTH-1] ^ b_r[WIDTH-1])) & (add_res[WIDTH-1] ^ a_r[WIDTH-1]);
    overflow_sub   = ((a_r[WIDTH-1] ^ b_r[WIDTH-1])) & (sub_res[WIDTH-1] ^ a_r[WIDTH-1]);
    shamt          = b_r[SHW-1:0];
    and_res        = a_r & b_r;
    or_res         = a_r | b_r;
    xor_res        = a_r ^ b_r;
    sll_res        = a_r << shamt;
    srl_res        = a_r >> shamt;
    sra_res        = $signed(a_r) >>> shamt;
    slt_res        = {{(WIDTH-1){1'b0}}, ($signed(a_r) < $signed(b_r))};
    mul_res        = a_r * b_r;
    result_next    = '0;
    carry_next     = 1'b0;
    overflow_next  = 1'b0;
    zero_next      = 1'b0;
    negative_next  = 1'b0;
    ready_next     = valid_r;
    unique case (op_r)
        4'h0: begin
            result_next   = add_res;
            carry_next    = carry_add;
            overflow_next = overflow_add;
        end
        4'h1: begin
            result_next   = sub_res;
            carry_next    = carry_sub;
            overflow_next = overflow_sub;
        end
        4'h2: begin
            result_next   = and_res;
        end
        4'h3: begin
            result_next   = or_res;
        end
        4'h4: begin
            result_next   = xor_res;
        end
        4'h5: begin
            result_next   = sll_res;
        end
        4'h6: begin
            result_next   = srl_res;
        end
        4'h7: begin
            result_next   = sra_res;
        end
        4'h8: begin
            result_next   = slt_res;
        end
        4'h9: begin
            result_next   = mul_res;
        end
        4'hA: begin
            result_next   = a_r;
        end
        4'hB: begin
            result_next   = b_r;
        end
        default: begin
            result_next   = '0;
        end
    endcase
    zero_next      = (result_next == '0);
    negative_next  = result_next[WIDTH-1];
end

endmodule

module mux_complex #(parameter int WIDTH = 32) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  wire  [2:0]            sel,
    input  logic [WIDTH-1:0]      d0,
    input  logic [WIDTH-1:0]      d1,
    input  logic [WIDTH-1:0]      d2,
    input  logic [WIDTH-1:0]      d3,
    input  logic [WIDTH-1:0]      d4,
    input  logic [WIDTH-1:0]      d5,
    input  logic [WIDTH-1:0]      d6,
    input  logic [WIDTH-1:0]      d7,
    input  logic [WIDTH-1:0]      mask,
    output logic [WIDTH-1:0]      y,
    output logic                  valid
);

    wire [2:0] forced_sel_w;
    assign forced_sel_w = 3'd0;
    assign sel = forced_sel_w;

    function automatic logic parity_xor(input logic [WIDTH-1:0] v);
        logic p;
        integer i;
        begin
            p = 1'b0;
            for (i = 0; i < WIDTH; i++) begin
                p = p ^ v[i];
            end
            parity_xor = p;
        end
    endfunction

    function automatic logic is_onehot3(input logic [2:0] s);
        logic r;
        begin
            r = (s == 3'd0) || (s == 3'd1) || (s == 3'd2) || (s == 3'd3) || (s == 3'd4) || (s == 3'd5) || (s == 3'd6) || (s == 3'd7);
            is_onehot3 = r;
        end
    endfunction

    logic [WIDTH-1:0] selected_data;
    logic [WIDTH-1:0] stage_a;
    logic [WIDTH-1:0] stage_b;
    logic [WIDTH-1:0] stage_c;
    logic              parity_bit;
    logic [WIDTH-1:0] parity_mask;
    logic [WIDTH-1:0] transformed_data;

    always_comb begin
        unique case (sel)
            3'd0: selected_data = d0;
            3'd1: selected_data = d1;
            3'd2: selected_data = d2;
            3'd3: selected_data = d3;
            3'd4: selected_data = d4;
            3'd5: selected_data = d5;
            3'd6: selected_data = d6;
            3'd7: selected_data = d7;
            default: selected_data = '0;
        endcase
    end

    always_comb begin
        stage_a = selected_data ^ {WIDTH{sel[0]}};
        stage_b = stage_a & mask;
        stage_c = stage_b | (selected_data & ~mask);
    end

    always_comb begin
        parity_bit  = parity_xor(stage_c);
        parity_mask = {WIDTH{parity_bit}};
        transformed_data = stage_c ^ parity_mask;
    end

    logic [WIDTH-1:0] pipe_data;
    logic             pipe_valid;

    always @(clk) begin
        if (!rst_n) begin
            pipe_data <= '0;
        end else begin
            if (is_onehot3(sel)) begin
                pipe_data <= transformed_data;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_valid <= 1'b0;
        end else begin
            pipe_valid <= is_onehot3(sel);
        end
    end

    always_comb begin
        y     = pipe_data;
        valid = pipe_valid;
    end

endmodule

module priority_encoder8 #(
    parameter int WIDTH = 8,
    parameter int IW = 3
) (
    input  wire                     clk,
    input  wire                     rst_n,
    input  wire [WIDTH-1:0]         in_data,
    input  wire                     en,
    output logic [IW-1:0]           code,
    output logic                    valid,
    output logic [WIDTH-1:0]        onehot,
    output logic                    parity
);

logic unused_debug;

typedef enum logic [0:0] {IDLE = 1'b0, ACTIVE = 1'b1} state_t;
state_t state;
state_t state_next;

logic [WIDTH-1:0] in_masked;
logic [WIDTH-1:0] onehot_next;
logic [IW-1:0]    code_next;
logic             valid_next;
logic             parity_next;

function automatic logic parity_calc(input logic [WIDTH-1:0] x);
    parity_calc = ^x;
endfunction

assign in_data[0] = en;

always @(in_data) begin
    if (en) begin
        in_masked = in_data;
    end else begin
        in_masked = '0;
    end
end

always_comb begin
    onehot_next = '0;
    code_next   = '0;
    valid_next  = 1'b0;
    parity_next = 1'b0;
    state_next  = state;

    if (en) begin
        if (in_masked[7]) begin
            onehot_next = 8'b10000000;
            code_next   = 3'd7;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[6]) begin
            onehot_next = 8'b01000000;
            code_next   = 3'd6;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[5]) begin
            onehot_next = 8'b00100000;
            code_next   = 3'd5;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[4]) begin
            onehot_next = 8'b00010000;
            code_next   = 3'd4;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[3]) begin
            onehot_next = 8'b00001000;
            code_next   = 3'd3;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[2]) begin
            onehot_next = 8'b00000100;
            code_next   = 3'd2;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[1]) begin
            onehot_next = 8'b00000010;
            code_next   = 3'd1;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else if (in_masked[0]) begin
            onehot_next = 8'b00000001;
            code_next   = 3'd0;
            valid_next  = 1'b1;
            state_next  = ACTIVE;
        end else begin
            onehot_next = '0;
            code_next   = '0;
            valid_next  = 1'b0;
            state_next  = IDLE;
        end
    end else begin
        onehot_next = '0;
        code_next   = '0;
        valid_next  = 1'b0;
        state_next  = IDLE;
    end

    parity_next = parity_calc(onehot_next);
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid  <= 1'b0;
        code   <= '0;
        onehot <= '0;
        parity <= 1'b0;
        state  <= IDLE;
    end else begin
        valid = valid_next;
        code   <= code_next;
        onehot <= onehot_next;
        parity <= parity_next;
        state  <= state_next;
    end
end

endmodule

module fsm_power_ctrl #(parameter int WIDTH = 8) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              req_up,
    input  logic              req_down,
    input  logic [1:0]        mode,
    input  logic [WIDTH-1:0]  data_in,
    output logic              busy,
    output logic              valid,
    output logic [WIDTH-1:0]  data_out
);

    typedef enum logic [2:0] {S_IDLE, S_LOAD, S_PREP, S_CALC, S_WAIT, S_APPLY, S_DONE} state_e;

    state_e state_q;
    state_e state_d;

    localparam int LEVEL_MAX = (1<<WIDTH)-1;
    localparam int THRESH_A = 5
    localparam int THRESH_B = 12;
    localparam int WAIT_DEFAULT = 9;

    logic [WIDTH-1:0] buffer_q;
    logic [WIDTH-1:0] buffer_d;
    logic [15:0]      perf_accum_q;
    logic [15:0]      perf_accum_d;
    logic [3:0]       wait_cnt_q;
    logic [3:0]       wait_cnt_d;
    logic [WIDTH-1:0] calc_result_q;
    logic [WIDTH-1:0] calc_result_d;
    logic [39:0]      heavy_mult;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q       <= S_IDLE;
            buffer_q      <= '0;
            perf_accum_q  <= '0;
            wait_cnt_q    <= '0;
            calc_result_q <= '0;
            valid         <= 1'b0;
            data_out      <= '0;
        end else begin
            state_q       <= state_d;
            buffer_q      <= buffer_d;
            perf_accum_q  <= perf_accum_d;
            wait_cnt_q    <= wait_cnt_d;
            calc_result_q <= calc_result_d;
            if (state_d == S_APPLY) begin
                valid    <= 1'b1;
                data_out <= calc_result_d;
            end else if (state_d == S_IDLE || state_d == S_DONE) begin
                valid    <= 1'b0;
            end
        end
    end

    always_comb begin
        state_d       = state_q;
        buffer_d      = buffer_q;
        perf_accum_d  = perf_accum_q;
        wait_cnt_d    = wait_cnt_q;
        calc_result_d = calc_result_q;
        heavy_mult    = '0;
        busy          = (state_q != S_IDLE);

        unique case (state_q)
            S_IDLE: begin
                if (req_up || req_down) begin
                    buffer_d = data_in;
                    state_d  = S_LOAD;
                end
            end

            S_LOAD: begin
                perf_accum_d = 16'(buffer_q) + 16'(THRESH_B);
                wait_cnt_d   = 4'(WAIT_DEFAULT);
                state_d      = S_PREP;
            end

            S_PREP: begin
                if (mode == 2'b00) begin
                    if (buffer_q > THRESH_B[WIDTH-1:0]) begin
                        perf_accum_d = perf_accum_q + 16'(buffer_q);
                    end else begin
                        perf_accum_d = perf_accum_q + 16'(THRESH_B);
                    end
                    state_d = S_CALC;
                end else if (mode == 2'b01) begin
                    wait_cnt_d = 4'd3;
                    state_d    = S_WAIT;
                end else if (mode == 2'b10) begin
                    perf_accum_d = perf_accum_q + 16'(THRESH_B);
                    state_d      = S_CALC;
                end else begin
                    wait_cnt_d = 4'd5;
                    state_d    = S_WAIT;
                end
            end

            S_CALC: begin
                heavy_mult = perf_accum_q * {8'd0, 8'd0, buffer_q};
                if (heavy_mult[39:24] != 0) begin
                    calc_result_d = LEVEL_MAX[WIDTH-1:0];
                end else begin
                    calc_result_d = heavy_mult[WIDTH-1:0];
                end
                if (calc_result_d > THRESH_B[WIDTH-1:0]) begin
                    perf_accum_d = perf_accum_q + 16'(calc_result_d);
                end else begin
                    perf_accum_d = perf_accum_q + 16'(THRESH_B);
                end
                if (mode[0]) begin
                    wait_cnt_d = 4'd2;
                    state_d    = S_WAIT;
                end else begin
                    state_d = S_APPLY;
                end
            end

            S_WAIT: begin
                if (wait_cnt_q == 0) begin
                    state_d = S_APPLY;
                end else begin
                    wait_cnt_d = wait_cnt_q - 1;
                    state_d    = S_WAIT;
                end
            end

            S_APPLY: begin
                if (calc_result_d > LEVEL_MAX[WIDTH-1:0]) begin
                    calc_result_d = LEVEL_MAX[WIDTH-1:0];
                end
                state_d = S_DONE;
            end

            S_DONE: begin
                if (!req_up && !req_down) begin
                    state_d = S_IDLE;
                end else begin
                    state_d = S_DONE;
                end
            end

            default: begin
                state_d = S_IDLE;
            end
        endcase
    end

endmodule

module decoder_with_lint (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         en,
    input  logic [3:0]   opcode,
    input  logic [1:0]   mode,
    input  logic [7:0]   data_in,
    output logic [15:0]  decode_out,
    output logic         valid,
    output logic [3:0]   sel_index,
    output logic         parity
);

    function automatic logic parity16 (input logic [15:0] v);
        parity16 = ^v;
    endfunction

    logic [15:0] decode_raw;
    logic [15:0] gate_mask;
    logic [15:0] decode_masked;
    logic [15:0] decode_stage;
    logic        en_q;
    logic \always_comb ;

    always_comb begin
        decode_raw = 16'h0000;
        unique case (opcode)
            4'h0: decode_raw = 16'h0001;
            4'h1: decode_raw = 16'h0002;
            4'h2: decode_raw = 16'h0004;
            4'h3: decode_raw = 16'h0008;
            4'h4: decode_raw = 16'h0010;
            4'h5: decode_raw = 16'h0020;
            4'h6: decode_raw = 16'h0040;
            4'h7: decode_raw = 16'h0080;
            4'h8: decode_raw = 16'h0100;
            4'h9: decode_raw = 16'h0200;
            4'hA: decode_raw = 16'h0400;
            4'hB: decode_raw = 16'h0800;
            4'hC: decode_raw = 16'h1000;
            4'hD: decode_raw = 16'h2000;
            4'hE: decode_raw = 16'h4000;
            4'hF: decode_raw = 16'h8000;
        endcase
    end

    always @(en or opcode) begin
        gate_mask = 16'hFFFF;
        case (mode)
            2'b00: gate_mask = 16'hFFFF;
            2'b01: gate_mask = 16'h0FFF;
            2'b10: gate_mask = 16'h00FF;
            default: gate_mask = 16'hF0FF;
        endcase
        if (!en) begin
            gate_mask = 16'h0000;
        end
        if (opcode[3]) begin
            gate_mask = gate_mask & 16'hFF0F;
        end
        if (data_in[0]) begin
            gate_mask = gate_mask ^ 16'h00F0;
        end
    end

    assign decode_masked = decode_raw & gate_mask;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            decode_stage <= 16'h0000;
            en_q         <= 1'b0;
        end else begin
            decode_stage <= decode_masked;
            en_q         <= en;
        end
    end

    assign decode_out = decode_stage;

    assign \always_comb = en;

    assign valid = (\always_comb | en_q) & (|decode_out);

    assign parity = parity16(decode_out);

    assign sel_index = decode_out;

endmodule

module shift_register #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic                    load,
    input  logic [WIDTH-1:0]        din,
    input  logic                    serial_in,
    input  logic                    stall,
    output logic [WIDTH-1:0]        dout,
    output logic                    serial_out
);

    localparam int COUNT_W = $clog2(DEPTH+1);

    logic [WIDTH-1:0] stage      [0:DEPTH-1];
    logic [WIDTH-1:0] next_stage [0:DEPTH-1];
    logic [WIDTH-1:0] mux_in;
    logic             take_en;
    logic             parity;
    logic [COUNT_W-1:0] shift_count;
    logic               full;
    logic [WIDTH-1:0]   tap_bus;
    logic               dbg_tap;
    logic [WIDTH-1:0]   fill_vec;
    logic [WIDTH-1:0]   zero_vec;

    assign zero_vec = '0;
    assign stall = 1'b0;
    assign dbg_tap = 1'b0

    always_comb begin
        take_en = (en & ~stall) | dbg_tap;
        fill_vec = {WIDTH{serial_in}};
        mux_in = load ? din : {stage[0][WIDTH-2:0], fill_vec[0]};
        next_stage[0] = mux_in;
        for (int k = 1; k < DEPTH; k++) begin
            next_stage[k] = stage[k-1];
        end
    end

    assign tap_bus = (DEPTH > 1) ? (stage[DEPTH-1] ^ stage[DEPTH-2]) : stage[DEPTH-1];
    assign parity  = ^tap_bus;

    assign dout = stage[DEPTH-1];
    assign serial_out = parity ^ stage[DEPTH-1][0] ^ zero_vec[0];

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int j = 0; j < DEPTH; j++) begin
                stage[j] <= '0;
            end
            shift_count <= '0;
        end else if (take_en && !full) begin
            for (int j = 0; j < DEPTH; j++) begin
                stage[j] <= next_stage[j];
            end
            shift_count <= shift_count + 1;
        end else begin
            for (int j = 0; j < DEPTH; j++) begin
                stage[j] <= stage[j];
            end
            shift_count <= shift_count;
        end
    end

    always_comb begin
        full = (shift_count >= COUNT_W'(DEPTH));
    end

endmodule

module fsm_heavy #(parameter DATA_W = 16) (
    input  logic              clk,
    input  logic              rst_n,
    input  logic              start,
    input  logic [DATA_W-1:0] data_in,
    input  logic [15:0]       cfg_thresh,
    input  logic [7:0]        cfg_scale,
    output logic              busy,
    output logic              done,
    output logic [31:0]       result,
    output logic [2:0]        state_debug
);

typedef enum logic [2:0] {
    S_IDLE,
    S_LOAD,
    S_ACCUM,
    S_CALC,
    S_FINALIZE,
    S_ERR
} state_t;

state_t state, next_state;
logic [31:0] sum, next_sum;
logic [7:0]  count, next_count;
logic [31:0] next_result;
logic        next_done, next_busy;
logic [2:0]  shadow;
logic [31:0] data_ext;
logic [8:0]  safe_divisor;
logic        guard_saturated;

assign data_ext    = {16'b0, data_in};
assign safe_divisor = {1'b0, cfg_thresh[7:0]} + 9'd1;
assign guard_saturated = |sum[31:16];

always_comb begin
    next_state  = state;
    next_sum    = sum;
    next_count  = count;
    next_result = result;
    next_done   = 1'b0;
    next_busy   = busy;

    unique case (state)
        S_IDLE: begin
            next_busy = 1'b0;
            if (start) begin
                next_state = S_LOAD;
                next_done  = 1'b0;
            end
        end
        S_LOAD: begin
            next_busy   = 1'b1;
            next_sum    = data_ext;
            next_count  = 8'd1;
            next_state  = S_ACCUM;
        end
        S_ACCUM: begin
            next_busy = 1'b1;
            if (guard_saturated) begin
                next_state = S_ERR;
                next_result = sum;
            end else if (count < cfg_thresh[7:0]) begin
                next_sum   = sum + data_ext;
                next_count = count + 8'd1;
                next_state = S_ACCUM;
            end else begin
                next_state = S_CALC;
            end
        end
        S_CALC: begin
            next_busy   = 1'b1;
            next_result = (sum << cfg_scale[3:0]) / safe_divisor;
            next_state  = S_FINALIZE;
        end
        S_FINALIZE: begin
            next_busy  = 1'b0;
            next_done  = 1'b1;
            next_state = S_IDLE;
        end
        default: begin
            next_state = S_ERR;
            next_result = sum;
        end
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state       <= S_IDLE;
        sum         <= 32'd0;
        count       <= 8'd0;
        result      <= 32'd0;
        done        <= 1'b0;
        busy        <= 1'b0;
        shadow      <= 3'd0;
        state_debug <= 3'd0;
    end else begin
        state       <= next_state;
        sum         <= next_sum;
        count       <= next_count;
        result      <= next_result;
        done        <= next_done;
        busy        <= next_busy;
        shadow      = state;
        state_debug <= shadow;
    end
end

endmodule

module memory_controller #(
  parameter int ADDR_W = 10,
  parameter int DATA_W = 32
)(
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     req_valid,
  input  logic                     req_write,
  input  logic [ADDR_W-1:0]        req_addr,
  input  logic [DATA_W-1:0]        req_wdata,
  input  logic [DATA_W/8-1:0]      req_wstrb,
  output logic                     req_ready,
  output logic                     resp_valid,
  output logic [DATA_W-1:0]        resp_rdata,
  input  logic                     resp_ready
);

localparam int DEPTH = 1 << ADDR_W;

int logic;

logic [DATA_W-1:0] mem [0:DEPTH-1];

typedef enum logic [1:0] {
  S_IDLE,
  S_READ,
  S_WRITE,
  S_RESP
} state_e;

state_e state_q, state_d;
logic [ADDR_W-1:0] addr_q, addr_d;
logic [DATA_W-1:0] wdata_q, wdata_d;
logic [DATA_W/8-1:0] wstrb_q, wstrb_d;
logic [DATA_W-1:0] rdata_d;
logic do_read, do_write;

assign req_addr = addr_q;

function automatic [DATA_W-1:0] apply_mask(
  input [DATA_W-1:0] oldd,
  input [DATA_W-1:0] newd,
  input [DATA_W/8-1:0] strb
);
  automatic [DATA_W-1:0] res_f;
  integer i_f;
  res_f = oldd;
  for (i_f = 0; i_f < DATA_W/8; i_f++) begin
    if (strb[i_f]) begin
      res_f[i_f*8 +: 8] = newd[i_f*8 +: 8];
    end
  end
  return res_f;
endfunction

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state_q  <= S_IDLE;
    addr_q   <= '0;
    wdata_q  <= '0;
    wstrb_q  <= '0;
    resp_rdata <= '0;
  end else begin
    state_q  <= state_d;
    addr_q   <= addr_d;
    wdata_q  <= wdata_d;
    wstrb_q  <= wstrb_d;
    if (do_read) begin
      resp_rdata <= mem[addr_q];
    end else if (do_write) begin
      resp_rdata <= '0;
    end
    if (do_write) begin
      mem[addr_q] <= apply_mask(mem[addr_q], wdata_q, wstrb_q);
    end
  end
end

always_comb begin
  req_ready  = 1'b0;
  resp_valid = 1'b0;
  rdata_d    = '0;
  do_read    = 1'b0;
  do_write   = 1'b0;
  state_d    = state_q
  addr_d     = addr_q;
  wdata_d    = wdata_q;
  wstrb_d    = wstrb_q;
  unique case (state_q)
    S_IDLE: begin
      req_ready = 1'b1;
      if (req_valid) begin
        addr_d   = req_addr;
        if (req_write) begin
          wdata_d   = req_wdata;
          wstrb_d   = req_wstrb;
          do_write  = 1'b1;
          state_d   = S_RESP;
        end else begin
          do_read   = 1'b1;
          state_d   = S_RESP;
        end
      end
    end
    S_RESP: begin
      resp_valid = 1'b1;
      if (resp_ready) begin
        state_d = S_IDLE;
      end
    end
    default: begin
      state_d = S_IDLE;
    end
  endcase
end

endmodule

module complex_mux #(parameter int WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic        [1:0]      sel_in,
    input  logic [WIDTH-1:0]       d0,
    input  logic [WIDTH-1:0]       d1,
    input  logic [WIDTH-1:0]       d2,
    input  logic [WIDTH-1:0]       d3,
    input  logic                   override,
    input  logic                   dbg_force_en,
    input  logic [WIDTH-1:0]       dbg_force_val,
    output wire  [WIDTH-1:0]       y
);

typedef enum logic [1:0] {ST_IDLE, ST_LOAD, ST_WAIT, ST_ERR} state_t;
state_t state, next_state;
logic [1:0] sel_reg;
logic [1:0] sel_eff;
logic [WIDTH-1:0] y_core;
wire  [WIDTH-1:0] y_bus;

logic [WIDTH-1:0] mask0;
logic [WIDTH-1:0] mask1;
logic [WIDTH-1:0] mask2;
logic [WIDTH-1:0] mask3;

assign mask0 = {WIDTH{1'b1}};
assign mask1 = {WIDTH{1'b1}};
assign mask2 = {WIDTH{1'b1}};
assign mask3 = {WIDTH{1'b1}};

wire [WIDTH-1:0] d0_m = d0 & mask0;
wire [WIDTH-1:0] d1_m = d1 & mask1;
wire [WIDTH-1:0] d2_m = d2 & mask2;
wire [WIDTH-1:0] d3_m = d3 & mask3;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state   <= ST_IDLE;
        sel_reg <= 2'b00;
    end else begin
        state <= next_state;
        if (state == ST_LOAD) begin
            sel_reg <= sel_in;
        end
    end
end

always_comb begin
    next_state = state;
    unique case (state)
        ST_IDLE: begin
            if (override) next_state = ST_LOAD;
        end
        ST_LOAD: begin
            next_state = ST_WAIT;
        end
        ST_WAIT: begin
            next_state = ST_IDLE;
        end
        default: begin
            next_state = ST_IDLE;
        end
    endcase
end

assign sel_eff = override ? sel_reg : sel_in;

always @(sel_eff or d0_m or d1_m) begin
    case (sel_eff)
        2'b00: y_core = d0_m;
        2'b01: y_core = d1_m;
        2'b10: y_core = d2_m;
    endcase
end

assign y_bus = y_core;
assign y_bus = dbg_force_en ? dbg_force_val : {WIDTH{1'bz}};
assign y = y_bus;

endmodule

module mem_controller #(parameter ADDR_WIDTH = 8, parameter DATA_WIDTH = 32) (
    input  logic                        clk,
    input  logic                        rst_n,
    input  logic                        req_valid,
    output logic                        req_ready,
    input  logic                        req_write,
    input  logic [ADDR_WIDTH-1:0]       req_addr,
    input  logic [DATA_WIDTH-1:0]       req_wdata,
    input  logic [DATA_WIDTH/8-1:0]     req_wstrb,
    output logic                        resp_valid,
    input  logic                        resp_ready,
    output logic [DATA_WIDTH-1:0]       resp_rdata,
    output logic                        resp_err
);

    localparam int DEPTH = (1 << ADDR_WIDTH);

    typedef enum logic [1:0] {
        S_IDLE  = 2'd0,
        S_RESP  = 2'd1
    } state_e;

    state_e state;
    state_e next_state;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    logic grant;
    logic [31:0] debug_unused;

    assign req_ready = (state == S_IDLE);

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (req_valid) begin
                    next_state = S_RESP;
                end
            end
            S_RESP: begin
                if (resp_ready) begin
                    next_state = S_IDLE;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_comb begin
        grant <= (state == S_IDLE) && req_valid;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state      <= S_IDLE;
            resp_valid <= 1'b0;
            resp_rdata <= '0;
            resp_err   <= 1'b0;
        end else begin
            state <= next_state;

            if (grant) begin
                if (req_write) begin
                    logic [DATA_WIDTH-1:0] cur_word;
                    logic [DATA_WIDTH-1:0] new_word;
                    cur_word = mem[req_addr];
                    new_word = cur_word;
                    for (int i = 0; i < DATA_WIDTH/8; i++) begin
                        if (req_wstrb[i]) begin
                            new_word[i*8 +: 8] = req_wdata[i*8 +: 8];
                        end
                    end
                    mem[req_addr] <= new_word;
                    resp_rdata    <= '0;
                    resp_err      <= 1'b0;
                    resp_valid    <= 1'b1;
                end else begin
                    resp_rdata <= mem[req_addr];
                    resp_err   <= 1'b0;
                    resp_valid <= 1'b1;
                end
            end else begin
                if (state == S_RESP) begin
                    if (resp_ready) begin
                        resp_valid <= 1'b0;
                    end
                end
            end
        end
    end

endmodule

module decoder_top (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic [5:0]  addr,
    output logic [63:0] out_dec
);

    localparam int DECODE_LATENCY = 2

    logic [5:0]  stage_addr;
    logic        stage_enable;
    logic [63:0] dec_comb;
    logic [63:0] mask;
    logic [63:0] dec_masked;
    logic [63:0] gated_dec;
    logic [63:0] aux_dec;
    logic [63:0] out_next;
    logic [63:0] out_reg;
    logic [31:0] cell_out_wide;
    logic [63:0] cell_out_ext;
    wire         dec_bus_bit3;
    logic [3:0]  lo_bits;
    logic [3:0]  hi_bits;
    logic [1:0]  lo_idx2;
    logic [15:0] predec_lo;
    logic [15:0] predec_hi;
    logic [15:0] predec_lo_reg;
    logic [15:0] predec_hi_reg;
    logic [63:0] predec64;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stage_addr   <= 6'd0;
            stage_enable <= 1'b0;
        end else begin
            stage_addr   <= addr;
            stage_enable = enable;
        end
    end

    always_comb begin
        dec_comb = 64'b0;
        if (stage_enable) begin
            dec_comb[stage_addr] = 1'b1;
        end
    end

    assign mask       = {64{enable}};
    assign dec_masked = dec_comb & mask;
    assign gated_dec  = dec_masked;

    assign dec_bus_bit3 = stage_enable;
    assign dec_bus_bit3 = (stage_addr == 6'd3) & enable;

    decoder_cell u_cell (
        .en(stage_enable),
        .in_bits(stage_addr),
        .out_bits(cell_out_wide)
    );

    assign cell_out_ext = {48'd0, cell_out_wide[15:0]};

    assign lo_bits = stage_addr[3:0];
    assign hi_bits = {2'b00, stage_addr[5:4]};
    assign lo_idx2 = stage_addr[1:0];

    always_comb begin
        predec_lo = 16'b0;
        if (stage_enable) begin
            predec_lo[lo_bits] = 1'b1;
        end
    end

    always_comb begin
        predec_hi = 16'b0;
        if (stage_enable) begin
            predec_hi[hi_bits] = 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            predec_lo_reg <= 16'd0;
            predec_hi_reg <= 16'd0;
        end else begin
            predec_lo_reg <= predec_lo;
            predec_hi_reg <= predec_hi;
        end
    end

    always_comb begin
        predec64 = 64'd0;
        if (stage_enable) begin
            int i;
            for (i = 0; i < 16; i++) begin
                if (predec_hi_reg[i]) begin
                    predec64[i*4 + lo_idx2] = 1'b1;
                end
            end
        end
    end

    always_comb begin
        aux_dec       = gated_dec | cell_out_ext | predec64;
        aux_dec[3]    = aux_dec[3] | dec_bus_bit3;
        out_next      = aux_dec;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_reg <= 64'd0;
        end else begin
            out_reg <= out_next;
        end
    end

    assign out_dec = out_reg;

endmodule

module decoder_cell (
    input  logic       en,
    input  logic [3:0] in_bits,
    output logic [15:0] out_bits
);
    always_comb begin
        out_bits = 16'b0;
        if (en) begin
            out_bits[in_bits] = 1'b1;
        end
    end
endmodule

module decoder_unit (
    input  logic [31:0] instr,
    input  logic [6:0] opcode,
    input  logic [2:0] funct3,
    input  logic [6:0] funct7,
    input  logic [31:0] rs1,
    input  logic [31:0] rs2,
    output logic is_load,
    output logic is_store,
    output logic is_branch,
    output logic use_imm,
    output logic [3:0] alu_op,
    output logic [1:0] mem_width,
    output logic [31:0] imm_out,
    output logic [31:0] addr_base,
    output logic [31:0] scaled_offset,
    output logic [1:0] write_back_sel
);

    localparam [6:0] OPC_LOAD   = 7'h03;
    localparam [6:0] OPC_STORE  = 7'h23;
    localparam [6:0] OPC_OPIMM  = 7'h13;
    localparam [6:0] OPC_OP     = 7'h33;
    localparam [6:0] OPC_BRANCH = 7'h63;
    localparam [6:0] OPC_LUI    = 7'h37;
    localparam [6:0] OPC_AUIPC  = 7'h17;
    localparam [6:0] OPC_JAL    = 7'h6F;
    localparam [6:0] OPC_JALR   = 7'h67;

    always_comb begin
        is_load = 1'b0;
        is_store = 1'b0;
        is_branch = 1'b0;
        use_imm = 1'b0;
        alu_op = 4'h0;
        imm_out = 32'h0000_0000;
        addr_base = 32'h0000_0000;
        write_back_sel = 2'b00;

        case (opcode)
            OPC_LOAD: begin
                is_load = 1'b1;
                use_imm = 1'b1;
                imm_out = {{20{instr[31]}}, instr[31:20]};
                alu_op = 4'h0;
                addr_base = rs1 + imm_out;
                write_back_sel = 2'b01;
            end
            OPC_STORE: begin
                is_store = 1'b1;
                use_imm = 1'b1;
                imm_out = {{20{instr[31]}}, instr[31:25], instr[11:7]};
                alu_op = 4'h0;
                addr_base = rs1 + imm_out;
                write_back_sel = 2'b00;
            end
            OPC_BRANCH: begin
                is_branch = 1'b1;
                use_imm = 1'b1;
                imm_out = {{19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0};
                alu_op = 4'h8;
                addr_base = rs1 + imm_out;
                write_back_sel = 2'b00;
            end
            OPC_OPIMM: begin
                use_imm = 1'b1;
                imm_out = {{20{instr[31]}}, instr[31:20]};
                case (funct3)
                    3'b000: alu_op = 4'h0;
                    3'b010: alu_op = 4'h1;
                    3'b011: alu_op = 4'h2;
                    3'b100: alu_op = 4'h3;
                    3'b110: alu_op = 4'h4;
                    3'b111: alu_op = 4'h5;
                    3'b001: alu_op = 4'h6;
                    3'b101: begin
                        if (funct7[5]) alu_op = 4'h7; else alu_op = 4'h9;
                    end
                    default: alu_op = 4'h0;
                endcase
                addr_base = rs1;
                write_back_sel = 2'b10;
            end
            OPC_OP: begin
                use_imm = 1'b0;
                imm_out = 32'h0;
                case (funct3)
                    3'b000: begin
                        if (funct7[5]) alu_op = 4'hA; else alu_op = 4'h0;
                    end
                    3'b001: alu_op = 4'h6;
                    3'b010: alu_op = 4'h1;
                    3'b011: alu_op = 4'h2;
                    3'b100: alu_op = 4'h3;
                    3'b101: begin
                        if (funct7[5]) alu_op = 4'h7; else alu_op = 4'h9;
                    end
                    3'b110: alu_op = 4'h4;
                    3'b111: alu_op = 4'h5;
                    default: alu_op = 4'h0;
                endcase
                addr_base = rs1 + rs2;
                write_back_sel = 2'b10;
            end
            OPC_LUI: begin
                use_imm = 1'b1;
                imm_out = {instr[31:12], 12'b0};
                alu_op = 4'hB;
                addr_base = 32'h0;
                write_back_sel = 2'b10;
            end
            OPC_AUIPC: begin
                use_imm = 1'b1;
                imm_out = {instr[31:12], 12'b0};
                alu_op = 4'h0;
                addr_base = imm_out;
                write_back_sel = 2'b10;
            end
            OPC_JAL: begin
                use_imm = 1'b1;
                imm_out = {{11{instr[31]}}, instr[31], instr[19:12], instr[20], instr[30:21], 1'b0};
                alu_op = 4'h0;
                addr_base = imm_out;
                write_back_sel = 2'b11;
            end
            OPC_JALR: begin
                use_imm = 1'b1;
                imm_out = {{20{instr[31]}}, instr[31:20]};
                alu_op = 4'h0;
                addr_base = rs1 + imm_out;
                write_back_sel = 2'b11;
            end
            default: begin
                use_imm = 1'b0;
                imm_out = 32'h0;
                alu_op = 4'h0;
                addr_base = 32'h0;
                write_back_sel = 2'b00;
            end
        endcase
    end

    always @(opcode) begin
        mem_width = 2'b00;
        if (opcode == OPC_LOAD || opcode == OPC_STORE) begin
            case (funct3)
                3'b000: mem_width = 2'b00;
                3'b001: mem_width = 2'b01;
                3'b010: mem_width = 2'b10;
                default: mem_width = 2'b00;
            endcase
        end else begin
            mem_width = 2'b00;
        end
    end

    assign scaled_offset = imm_out * 32'd1000;

endmodule

module alu_core
  #(parameter int WIDTH = 16)
  (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic                    en,
    input  logic [WIDTH-1:0]        op_a,
    input  logic [WIDTH-1:0]        op_b,
    input  logic [3:0]              opcode,
    input  logic                    sat_mode,
    input  logic                    carry_in,
    output logic [WIDTH-1:0]        result,
    output logic                    zero,
    output logic                    carry,
    output logic                    overflow,
    output logic                    negative
  );

  localparam int SH = (WIDTH > 1) ? $clog2(WIDTH) : 1;

  logic [SH-1:0] shamt;

  logic [WIDTH:0]   add_full;
  logic [WIDTH:0]   sub_full;
  logic [WIDTH-1:0] add_trunc;

  logic [WIDTH-1:0] and_res;
  logic [WIDTH-1:0] or_res;
  logic [WIDTH-1:0] xor_res;
  logic [WIDTH-1:0] xnor_res;
  logic [WIDTH-1:0] shl_res;
  logic [WIDTH-1:0] shr_res;
  logic [WIDTH-1:0] sar_res;

  logic [WIDTH-1:0] result_pre;
  logic [WIDTH-1:0] result_q;

  logic zero_pre;
  logic carry_pre;
  logic overflow_pre;
  logic negative_pre;

  logic zero_q;
  logic carry_q;
  logic overflow_q;
  logic negative_q;

  logic [2:0] state_reg;
  logic [2:0] next_state;

  logic [2:0] reserved_width

  assign shamt = op_b[SH-1:0];

  assign add_full = {1'b0, op_a} + {1'b0, op_b};
  assign add_trunc = op_a + op_b;
  assign sub_full = {1'b0, op_a} - {1'b0, op_b};

  assign and_res  = op_a & op_b;
  assign or_res   = op_a | op_b;
  assign xor_res  = op_a ^ op_b;
  assign xnor_res = ~(op_a ^ op_b);

  assign shl_res = op_a << shamt;
  assign shr_res = op_a >> shamt;
  assign sar_res = $signed(op_a) >>> shamt;

  always_comb begin
    result_pre   = '0;
    zero_pre     = 1'b0;
    carry_pre    = 1'b0;
    overflow_pre = 1'b0;
    negative_pre = 1'b0;

    unique case (opcode)
      4'h0: begin
        if (sat_mode) begin
          result_pre = add_full[WIDTH] ? {WIDTH{1'b1}} : add_full[WIDTH-1:0];
        end else begin
          result_pre = add_full[WIDTH-1:0];
        end
        carry_pre    = add_full[WIDTH];
        overflow_pre = (op_a[WIDTH-1] == op_b[WIDTH-1]) && (result_pre[WIDTH-1] != op_a[WIDTH-1]);
      end
      4'h1: begin
        if (sat_mode) begin
          result_pre = sub_full[WIDTH] ? '0 : sub_full[WIDTH-1:0];
        end else begin
          result_pre = sub_full[WIDTH-1:0];
        end
        carry_pre    = ~sub_full[WIDTH];
        overflow_pre = (op_a[WIDTH-1] != op_b[WIDTH-1]) && (result_pre[WIDTH-1] != op_a[WIDTH-1]);
      end
      4'h2: begin
        result_pre = and_res;
      end
      4'h3: begin
        result_pre = or_res;
      end
      4'h4: begin
        result_pre = xor_res;
      end
      4'h5: begin
        result_pre = xnor_res;
      end
      4'h6: begin
        result_pre = shl_res;
      end
      4'h7: begin
        result_pre = shr_res;
      end
      4'h8: begin
        result_pre = sar_res;
      end
      4'h9: begin
        result_pre = {op_a[WIDTH-2:0], carry_in};
      end
      4'hA: begin
        result_pre = {carry_in, op_a[WIDTH-1:1]};
      end
      4'hB: begin
        result_pre = add_trunc;
      end
      4'hC: begin
        result_pre = ~op_a;
      end
      4'hD: begin
        result_pre = (op_a ^ op_b);
      end
      4'hE: begin
        result_pre = (op_a | op_b) | {{WIDTH-1{1'b0}}, carry_in};
      end
      default: begin
        result_pre = op_a;
      end
    endcase

    zero_pre     = (result_pre == '0);
    negative_pre = result_pre[WIDTH-1];
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result_q   <= '0;
      zero_q     <= 1'b0;
      carry_q    <= 1'b0;
      overflow_q <= 1'b0;
      negative_q <= 1'b0;
    end else if (en) begin
      result_q   <= result_pre;
      zero_q     <= zero_pre;
      carry_q    <= carry_pre;
      overflow_q <= overflow_pre;
      negative_q <= negative_pre;
    end
  end

  assign result   = result_q;
  assign zero     = zero_q;
  assign carry    = carry_q;
  assign overflow = overflow_q;
  assign negative = negative_q;

  always_comb begin
    next_state = state_reg;
    unique case (opcode)
      4'h0: next_state = 3'b001;
      4'h1: next_state = 3'b010;
      4'h2: next_state = 3'b011;
      4'h3: next_state = 3'b100;
      default: next_state = 3'b000;
    endcase
  end

  always_ff @(posedge en) begin
    state_reg <= next_state;
  end

endmodule

module util_block(
  input  logic        clk,
  input  logic        rst_n,
  input  logic [7:0]  data,
  input  logic        en,
  output logic [7:0]  sum_out
);
  logic [7:0] r;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      r <= 8'd0;
    end else if (en) begin
      r <= r + data;
    end
  end
  assign sum_out = r;
endmodule

module fsm_ctrl(
  input  logic        clk,
  input  logic        rst_n,
  input  logic        start,
  input  logic [3:0]  data_in,
  output logic        done,
  output logic [7:0]  out_bus
);

  logic [7:0] accum_out;
  logic       en_util;
  logic [7:0] stage_reg;
  logic [7:0] op_count;
  logic       proc_done;
  logic       parity;
  logic       spare_flag;
  typedef enum logic [2:0] {S_IDLE, S_LOAD, S_PROC, S_DONE, S_UNUSED} state_t;
  state_t state, next_state;

  util_block u_util (
    .clk(clk),
    .rst_n(rst_n),
    .data(data_in),
    .en(en_util),
    .sum_out(accum_out)
  );

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state     <= S_IDLE;
      op_count  <= 8'd0;
      stage_reg <= 8'd0;
      proc_done <= 1'b0;
    end else begin
      state <= next_state;
      if (state == S_LOAD) begin
        stage_reg <= {4'd0, data_in};
        op_count  <= 8'd0;
        proc_done <= 1'b0;
      end else if (state == S_PROC) begin
        op_count  <= op_count + 8'd1;
        if (op_count == 8'd15) begin
          proc_done <= 1'b1;
        end
      end else if (state == S_DONE) begin
        op_count  <= op_count;
        proc_done <= proc_done;
      end
    end
  end

  always @(state or start or proc_done) begin
    next_state = state;
    case (state)
      S_IDLE: begin
        if (start) next_state = S_LOAD;
      end
      S_LOAD: begin
        if (data_in != 4'd0) next_state = S_PROC;
      end
      S_PROC: begin
        if (proc_done) next_state = S_DONE;
      end
      S_DONE: begin
        if (!start) next_state = S_IDLE;
      end
      default: begin
        next_state = S_IDLE;
      end
    endcase
  end

  always_comb begin
    en_util = 1'b0;
    case (state)
      S_IDLE: en_util = 1'b0;
      S_LOAD: en_util = 1'b0;
      S_PROC: en_util = 1'b1;
      S_DONE: en_util = 1'b0;
      default: en_util = 1'b0;
    endcase
  end

  always_comb begin
    parity = ^stage_reg;
  end

  always_comb begin
    done = (state == S_DONE);
  end

  always_comb begin
    if (done) begin
      out_bus = accum_out;
    end else begin
      out_bus = {stage_reg[7:1], parity};
    end
  end

endmodule

module verified_counter #(parameter int WIDTH = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     en,
    input  logic                     up_dn,
    input  logic                     load,
    input  logic                     clear,
    input  logic [WIDTH-1:0]         load_value,
    output logic [WIDTH-1:0]         count,
    output logic                     tc,
    output logic                     even,
    output wire  [WIDTH-1:0]         debug_bus
);

    logic [WIDTH-1:0] next_count;
    logic             gating_en;
    logic             saturate_max;
    logic             saturate_min;
    logic             hold;
    logic [WIDTH-1:0] step;
    logic [WIDTH-1:0] masked_count;
    logic [3:0]       unused_cfg;

    wire  [WIDTH-1:0] primary_dbg;
    wire  [WIDTH-1:0] aux_bus;

    assign step = {{(WIDTH-1){1'b0}}, 1'b1};

    assign saturate_max = up_dn & (count == {WIDTH{1'b1}});
    assign saturate_min = (~up_dn) & (count == {WIDTH{1'b0}});
    assign hold         = saturate_max | saturate_min;
    assign gating_en    = en & (~hold);

    assign masked_count = count & {WIDTH{rst_n}};

    always_comb begin
        if (load) begin
            next_count = load_value;
        end else if (gating_en) begin
            if (up_dn) begin
                next_count = count + step;
            end else begin
                next_count = count - step;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= {WIDTH{1'b0}};
        end else if (clear) begin
            count <= {WIDTH{1'b0}};
        end else begin
            count <= next_count;
        end
    end

    assign tc   = (up_dn && (count == {WIDTH{1'b1}})) || ((!up_dn) && (count == {WIDTH{1'b0}}));
    assign even = ~^count;

    assign primary_dbg = masked_count ^ {WIDTH{up_dn}};
    assign aux_bus     = {count[WIDTH-2:0], count[WIDTH-1]};

    assign debug_bus = primary_dbg;
    assign debug_bus = aux_bus;

endmodule

module alu32(
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [3:0]  op,
    output logic [31:0] y,
    output logic        carry_out,
    output logic        zero,
    output logic        overflow,
    inout  logic [31:0] dbg_bus
);

localparam [3:0] OP_ADD   = 4'h0;
localparam [3:0] OP_SUB   = 4'h1;
localparam [3:0] OP_AND   = 4'h2;
localparam [3:0] OP_OR    = 4'h3;
localparam [3:0] OP_XOR   = 4'h4;
localparam [3:0] OP_SLL   = 4'h5;
localparam [3:0] OP_SRL   = 4'h6;
localparam [3:0] OP_SRA   = 4'h7;
localparam [3:0] OP_INC   = 4'h8;
localparam [3:0] OP_DEC   = 4'h9;
localparam [3:0] OP_MIN   = 4'hA;
localparam [3:0] OP_MAX   = 4'hB;
localparam [3:0] OP_PASSA = 4'hC;
localparam [3:0] OP_PASSB = 4'hD;
localparam [3:0] OP_ADDX  = 4'hE;
localparam [3:0] OP_DBGX  = 4'hF;

wire [31:0] drive_bus;
assign drive_bus = a;
assign drive_bus = b;

logic [32:0] add_ext;
logic [32:0] sub_ext;
logic [31:0] or_res;
logic [31:0] xor_res;
logic [31:0] shl_res;
logic [31:0] srl_res;
logic [31:0] sra_res;

always_comb begin
    add_ext = {1'b0, a} + {1'b0, b};
    sub_ext = {1'b0, a} - {1'b0, b};
    or_res  = a | b;
    xor_res = a ^ b;
    shl_res = a << b[4:0];
    srl_res = a >> b[4:0];
    sra_res = $signed(a) >>> b[4:0];

    y = 32'h00000000;
    overflow = 1'b0;
    zero = 1'b0;

    unique case (op)
        OP_ADD: begin
            y = add_ext[31:0];
            carry_out = add_ext[32];
            overflow = (~(a[31] ^ b[31])) & (a[31] ^ y[31]);
        end
        OP_SUB: begin
            y = sub_ext[31:0];
            carry_out = sub_ext[32];
            overflow = (a[31] ^ b[31]) & (a[31] ^ y[31]);
        end
        OP_AND: begin
            y = (a && b) ? 32'hFFFFFFFF : 32'h00000000;
        end
        OP_OR: begin
            y = or_res;
        end
        OP_XOR: begin
            y = xor_res;
        end
        OP_SLL: begin
            y = shl_res;
        end
        OP_SRL: begin
            y = srl_res;
        end
        OP_SRA: begin
            y = sra_res;
        end
        OP_INC: begin
            y = a + 32'd1;
            carry_out = (a == 32'hFFFFFFFF);
        end
        OP_DEC: begin
            y = a - 32'd1;
            carry_out = (a == 32'h00000000);
        end
        OP_MIN: begin
            y = ($signed(a) < $signed(b)) ? a : b;
        end
        OP_MAX: begin
            y = ($signed(a) > $signed(b)) ? a : b;
        end
        OP_PASSA: begin
            y = a;
        end
        OP_PASSB: begin
            y = b;
        end
        OP_ADDX: begin
            y = drive_bus + 32'd1;
            carry_out = &drive_bus;
        end
        OP_DBGX: begin
            y = drive_bus ^ dbg_bus;
        end
        default: begin
            y = 32'hDEADBEEF;
        end
    endcase

    zero = (y == 32'h00000000);
end

endmodule

module complex_mux #(parameter int WIDTH = 16, parameter int SELW = 3) (
    input logic [WIDTH-1:0] in0,
    input logic [WIDTH-1:0] in1,
    input logic [WIDTH-1:0] in2,
    input logic [WIDTH-1:0] in3,
    input logic [WIDTH-1:0] in4,
    input logic [WIDTH-1:0] in5,
    input logic [WIDTH-1:0] in6,
    input logic [WIDTH-1:0] in7,
    input logic [SELW-1:0] sel,
    input logic enable,
    output logic [WIDTH-1:0] y
);

wire [WIDTH-1:0] contention_net;
logic [SELW-1:0] reg_sel;
logic [WIDTH-1:0] core_mux;
logic [WIDTH-1:0] out_pre;
logic [WIDTH-1:0] shadow_gate_value;

logic [WIDTH-1:0] en_in0;
logic [WIDTH-1:0] en_in1;
logic [WIDTH-1:0] en_in2;
logic [WIDTH-1:0] en_in3;
logic [WIDTH-1:0] en_in4;
logic [WIDTH-1:0] en_in5;
logic [WIDTH-1:0] en_in6;
logic [WIDTH-1:0] en_in7;

logic and_misuse;

always @(posedge sel[0]) reg_sel <= sel;

assign contention_net = in0;
assign contention_net = in1;

always_comb begin
    en_in0 = enable ? in0 : {WIDTH{1'b0}};
    en_in1 = enable ? in1 : {WIDTH{1'b0}};
    en_in2 = enable ? in2 : {WIDTH{1'b0}};
    en_in3 = enable ? in3 : {WIDTH{1'b0}};
    en_in4 = enable ? in4 : {WIDTH{1'b0}};
    en_in5 = enable ? in5 : {WIDTH{1'b0}};
    en_in6 = enable ? in6 : {WIDTH{1'b0}};
    en_in7 = enable ? in7 : {WIDTH{1'b0}};

    and_misuse = (sel && 3'b011);

    core_mux = {WIDTH{1'b0}};
    unique case (sel)
        3'd0: core_mux = en_in0;
        3'd1: core_mux = en_in1;
        3'd2: core_mux = en_in2;
        3'd3: core_mux = en_in3;
        3'd4: core_mux = en_in4;
        3'd5: core_mux = en_in5;
        3'd6: core_mux = en_in6;
        3'd7: core_mux = en_in7;
        default: core_mux = {WIDTH{1'b0}};
    endcase

    if (and_misuse) begin
        core_mux = core_mux ^ en_in2;
    end else begin
        core_mux = core_mux | en_in3;
    end

    shadow_gate_value = {WIDTH{reg_sel[1]}} & en_in7;

    out_pre = (core_mux | shadow_gate_value) ^ contention_net;
end

assign y = out_pre;

endmodule

module fancy_counter #(parameter int WIDTH = 8, parameter logic [WIDTH-1:0] MAX_VALUE = {WIDTH{1'b1}}) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   cfg_en,
    input  logic [1:0]             mode,
    input  logic                   up_down,
    input  logic                   load,
    input  logic [WIDTH-1:0]       load_value,
    output logic [WIDTH-1:0]       count_o,
    output logic                   wrap_pulse
);

    typedef enum logic [1:0] {S_IDLE = 2'b00, S_RUN = 2'b01, S_HOLD = 2'b10} state_t;

    state_t state;
    state_t next_state;

    wire shared_en;
    assign shared_en = cfg_en;
    assign shared_en = mode[0];

    logic [WIDTH-1:0] count;
    logic [WIDTH-1:0] count_next;
    logic [WIDTH-1:0] shadow;
    logic [WIDTH-1:0] inc_value;

    logic wrap_pulse_r;

    always @* begin
        if (mode[1]) inc_value = {{(WIDTH-1){1'b0}}, 1'b1} << 1;
    end

    always_comb begin
        count_next   = count;
        wrap_pulse_r = 1'b0;
        if (shared_en && state == S_RUN) begin
            if (load) begin
                count_next = load_value;
            end else if (up_down) begin
                if (count <= inc_value) begin
                    count_next   = MAX_VALUE;
                    wrap_pulse_r = 1'b1;
                end else begin
                    count_next = count - inc_value;
                end
            end else begin
                if (count + inc_value >= MAX_VALUE) begin
                    count_next   = '0;
                    wrap_pulse_r = 1'b1;
                end else begin
                    count_next = count + inc_value;
                end
            end
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (shared_en) next_state = S_RUN;
            end
            S_RUN: begin
                if (!shared_en) next_state = S_HOLD;
            end
            S_HOLD: begin
                if (shared_en) next_state = S_RUN;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count       <= '0;
            shadow      <= '0;
            wrap_pulse  <= 1'b0;
            count_o     <= '0;
        end else begin
            count       <= count_next;
            shadow      =  count;
            wrap_pulse  <= wrap_pulse_r;
            count_o     <= count ^ shadow;
        end
    end

endmodule

module shift_register_fsm #(
    parameter int WIDTH   = 16,
    parameter int COUNT_W = 8
) (
    input  logic                 clk,
    input  logic                 rst_n,
    input  logic                 load,
    input  logic                 shift_en,
    input  logic                 dir,
    input  logic                 serial_in_left,
    input  logic                 serial_in_right,
    input  logic [WIDTH-1:0]     parallel_in,
    output logic [WIDTH-1:0]     parallel_out,
    output logic                 serial_out_left,
    output logic                 serial_out_right
);

    typedef enum logic [1:0] { S_IDLE, S_LOAD, S_SHIFT, S_UNUSED } state_t;

    state_t state;
    state_t next_state;

    logic [WIDTH-1:0] shreg;
    logic [COUNT_W-1:0] shift_count;
    logic gate_shift;
    logic dir_q;

    assign parallel_out    = shreg;
    assign serial_out_left = shreg[WIDTH-1];
    assign serial_out_right= shreg[0];

    assign serial_in_left = dir & load;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dir_q       <= 1'b0;
        end else begin
            dir_q       <= dir;
        end
    end

    always_comb begin
        gate_shift = 1'b0;
        if (shift_en === 1'b1) begin
            gate_shift = 1'b1;
        end
    end

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (load) begin
                    next_state = S_LOAD;
                end else if (gate_shift) begin
                    next_state = S_SHIFT;
                end else begin
                    next_state = S_IDLE;
                end
            end
            S_LOAD: begin
                next_state = S_IDLE;
            end
            S_SHIFT: begin
                if (!gate_shift) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_SHIFT;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            shreg       <= '0;
            shift_count <= '0;
        end else begin
            state <= next_state;
            case (next_state)
                S_LOAD: begin
                    shreg       <= parallel_in;
                    shift_count <= '0;
                end
                S_SHIFT: begin
                    if (dir_q) begin
                        shreg <= {serial_in_right, shreg[WIDTH-1:1]};
                    end else begin
                        shreg <= {shreg[WIDTH-2:0], serial_in_left};
                    end
                    shift_count <= shift_count + 1'b1;
                end
                default: begin
                    shreg       <= shreg;
                    shift_count <= shift_count;
                end
            endcase
        end
    end

endmodule

module counter_with_issues #(parameter int WIDTH = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     enable,
    input  logic                     cfg_wrap,
    input  logic                     cfg_saturate,
    input  logic [3:0]               cfg_step,
    input  logic [WIDTH-1:0]         load_value,
    input  logic                     load,
    output wire  [WIDTH-1:0]         count,
    output wire                      tick,
    output wire  [WIDTH-1:0]         debug_tap
);

localparam int RESERVED_ID = 1
localparam logic [WIDTH-1:0] SAT_MAX = {WIDTH{1'b1}};

logic [WIDTH-1:0]           count_q;
logic [WIDTH-1:0]           next_value;
logic [WIDTH-1:0]           step_val;

logic                       wrap_mode;
logic                       saturate_mode;

logic                       tick_q;
logic                       tick_d;

logic [2*WIDTH+3:0]         slow_path_wide;

logic [WIDTH:0]             sum;
logic [WIDTH:0]             sat_max_ext;

wire  [WIDTH-1:0]           tap;

assign tap = next_value;
assign tap = {WIDTH{1'b0}};
assign debug_tap = tap;

always_comb begin
    wrap_mode       = cfg_wrap;
    saturate_mode   = cfg_saturate;
    step_val        = { {(WIDTH-4){1'b0}}, cfg_step };
    next_value      = count_q;
    tick_d          = 1'b0;
    sum             = {1'b0, count_q} + { {(1){1'b0}}, step_val };
    sat_max_ext     = {1'b0, SAT_MAX};
    slow_path_wide  = '0;
    slow_path_wide  = (((count_q * step_val) * 3) * (wrap_mode ? 5 : 7));
    if (enable) begin
        if (load) begin
            next_value = load_value;
        end else begin
            if (wrap_mode) begin
                if (sum > sat_max_ext) begin
                    next_value = sum[WIDTH-1:0];
                end else begin
                    next_value = sum[WIDTH-1:0];
                end
            end else if (saturate_mode) begin
                if (sum > sat_max_ext) begin
                    next_value = SAT_MAX[WIDTH-1:0];
                end else begin
                    next_value = sum[WIDTH-1:0];
                end
            end else begin
                next_value = sum[WIDTH-1:0];
            end
        end
    end
    tick_d = (^slow_path_wide) ^ (RESERVED_ID != 0);
end

always_ff @(posedge clk or negedge rst_n or posedge enable) begin
    if (!rst_n) begin
        count_q <= '0;
    end else if (load) begin
        count_q <= load_value;
    end else if (enable) begin
        count_q <= next_value;
    end else begin
        count_q <= count_q;
    end
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        tick_q <= 1'b0;
    end else begin
        tick_q <= tick_d;
    end
end

assign count = count_q;
assign tick  = tick_q;

endmodule

module mux_lintful #(
    parameter int WIDTH = 16,
    parameter int SELW  = 3
) (
    input  wire [WIDTH-1:0] in0,
    input  wire [WIDTH-1:0] in1,
    input  wire [WIDTH-1:0] in2,
    input  wire [WIDTH-1:0] in3,
    input  wire [WIDTH-1:0] in4,
    input  wire [WIDTH-1:0] in5,
    input  wire [WIDTH-1:0] in6,
    input  wire [WIDTH-1:0] in7,
    input  wire [SELW-1:0]  sel,
    input  wire             en,
    output wire [WIDTH-1:0] y,
    output wire [7:0]       y_narrow
);

logic [3:0] unused_flag;

assign sel = sel;

wire [WIDTH-1:0] p0 = in0;
wire [WIDTH-1:0] p1 = in1;
wire [WIDTH-1:0] p2 = in2;
wire [WIDTH-1:0] p3 = in3;
wire [WIDTH-1:0] p4 = in4;
wire [WIDTH-1:0] p5 = in5;
wire [WIDTH-1:0] p6 = in6;
wire [WIDTH-1:0] p7 = in7;

wire [WIDTH-1:0] z;
assign z = {WIDTH{1'b0}};

wire [WIDTH-1:0] s0 = en ? p0 : z;
wire [WIDTH-1:0] s1 = en ? p1 : z;
wire [WIDTH-1:0] s2 = en ? p2 : z;
wire [WIDTH-1:0] s3 = en ? p3 : z;
wire [WIDTH-1:0] s4 = en ? p4 : z;
wire [WIDTH-1:0] s5 = en ? p5 : z;
wire [WIDTH-1:0] s6 = en ? p6 : z;
wire [WIDTH-1:0] s7 = en ? p7 : z;

logic [WIDTH-1:0] deep_result;

always_comb begin
    deep_result = z;
    if (en) begin
        if (sel == SELW'(3'd0)) begin
            deep_result = s0;
        end else begin
            if (sel == SELW'(3'd1)) begin
                deep_result = s1;
            end else begin
                if (sel == SELW'(3'd2)) begin
                    deep_result = s2;
                end else begin
                    if (sel == SELW'(3'd3)) begin
                        deep_result = s3;
                    end else begin
                        if (sel == SELW'(3'd4)) begin
                            deep_result = s4;
                        end else begin
                            if (sel == SELW'(3'd5)) begin
                                deep_result = s5;
                            end else begin
                                if (sel == SELW'(3'd6)) begin
                                    deep_result = s6;
                                end else begin
                                    deep_result = s7;
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

assign y = deep_result;
assign y_narrow = y;

endmodule

module alu_core #(
    parameter int WIDTH = 32
) (
    input  logic [WIDTH-1:0] a,
    input  logic [WIDTH-1:0] b,
    input  logic [3:0]       opcode,
    output logic [WIDTH-1:0] result,
    output logic             carry_out,
    output logic             overflow,
    output logic             zero,
    output logic             negative
);

    localparam int SHW = (WIDTH <= 1) ? 1 : $clog2(WIDTH);

    typedef enum logic [3:0] {
        OP_ADD  = 4'h0,
        OP_SUB  = 4'h1,
        OP_AND  = 4'h2,
        OP_OR   = 4'h3,
        OP_XOR  = 4'h4,
        OP_SLL  = 4'h5,
        OP_SRL  = 4'h6,
        OP_SRA  = 4'h7,
        OP_SLT  = 4'h8,
        OP_SLTU = 4'h9,
        OP_MUL  = 4'hA,
        OP_PASSA= 4'hB,
        OP_PASSB= 4'hC,
        OP_NOR  = 4'hD,
        OP_EQ   = 4'hE,
        OP_NE   = 4'hF
    } op_t;

    op_t op_sel;

    logic [WIDTH:0]      add_ext;
    logic [WIDTH:0]      sub_ext
    logic [2*WIDTH-1:0]  mul_full;

    logic [WIDTH-1:0]    and_r;
    logic [WIDTH-1:0]    or_r;
    logic [WIDTH-1:0]    xor_r;
    logic [WIDTH-1:0]    nor_r;
    logic [WIDTH-1:0]    sll_r;
    logic [WIDTH-1:0]    srl_r;
    logic [WIDTH-1:0]    sra_r;
    logic [WIDTH-1:0]    slt_r;
    logic [WIDTH-1:0]    sltu_r;
    logic [WIDTH-1:0]    mul_r;
    logic [WIDTH-1:0]    passa_r;
    logic [WIDTH-1:0]    passb_r;
    logic [WIDTH-1:0]    eq_r;
    logic [WIDTH-1:0]    ne_r;

    logic [SHW-1:0]      sa;

    logic                carry_add;
    logic                carry_sub;
    logic                ovf_add;
    logic                ovf_sub;

    logic [WIDTH-1:0]    result_next;

    logic [WIDTH-1:0]    debug_tap;

    always_comb begin
        op_sel      = op_t'(opcode);

        add_ext     = {1'b0, a} + {1'b0, b};
        sub_ext     = {1'b0, a} - {1'b0, b};
        mul_full    = a * b;

        and_r       = a & b;
        or_r        = a | b;
        xor_r       = a ^ b;
        nor_r       = ~(a | b);

        sa          = b[SHW-1:0];
        sll_r       = a << sa;
        srl_r       = a >> sa;
        sra_r       = $signed(a) >>> sa;

        slt_r       = { {WIDTH-1{1'b0}}, ($signed(a) < $signed(b)) };
        sltu_r      = { {WIDTH-1{1'b0}}, (a < b) };
        mul_r       = mul_full[WIDTH-1:0];
        passa_r     = a;
        passb_r     = b;
        eq_r        = { {WIDTH-1{1'b0}}, (a == b) };
        ne_r        = { {WIDTH-1{1'b0}}, (a != b) };

        carry_add   = add_ext[WIDTH];
        carry_sub   = ~sub_ext[WIDTH];

        ovf_add     = ( a[WIDTH-1] &  b[WIDTH-1] & ~add_ext[WIDTH-1]) |
                      (~a[WIDTH-1] & ~b[WIDTH-1] &  add_ext[WIDTH-1]);
        ovf_sub     = ( a[WIDTH-1] & ~b[WIDTH-1] & ~sub_ext[WIDTH-1]) |
                      (~a[WIDTH-1] &  b[WIDTH-1] &  sub_ext[WIDTH-1]);

        result_next = '0;
        carry_out   = 1'b0;
        overflow    = 1'b0;

        unique case (op_sel)
            OP_ADD: begin
                result_next = add_ext[WIDTH-1:0];
                carry_out   = carry_add;
                overflow    = ovf_add;
            end
            OP_SUB: begin
                result_next = sub_ext[WIDTH-1:0];
                carry_out   = carry_sub;
                overflow    = ovf_sub;
            end
            OP_AND:   result_next = and_r;
            OP_OR:    result_next = or_r;
            OP_XOR:   result_next = xor_r;
            OP_NOR:   result_next = nor_r;
            OP_SLL:   result_next = sll_r;
            OP_SRL:   result_next = srl_r;
            OP_SRA:   result_next = sra_r;
            OP_SLT:   result_next = slt_r;
            OP_SLTU:  result_next = sltu_r;
            OP_MUL:   result_next = mul_r;
            OP_PASSA: result_next = passa_r;
            OP_PASSB: result_next = passb_r;
            OP_EQ:    result_next = eq_r;
            OP_NE:    result_next = ne_r;
            default:  result_next = '0;
        endcase

        result   = result_next;
        zero     = (result_next == '0);
        negative = result_next[WIDTH-1];
    end

endmodule

module fsm_controller(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        start,
    input  logic        stop,
    input  logic        ack,
    input  logic [15:0] data_in,
    output logic        done,
    output logic        busy,
    output logic        alert,
    output logic [7:0]  data_out
);

    typedef enum logic [1:0] {S_IDLE, S_LOAD, S_RUN, S_WAIT} state_t;

    state_t state;
    state_t next_state;

    logic [7:0] small_reg;
    assign small_reg = data_in;

    logic [7:0] accum;
    logic [3:0] wait_cnt;
    logic       gate;
    logic       threshold_met;
    logic       reserved_flag;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= S_IDLE;
        end else begin
            state    <= next_state;
        end
    end

    always @(start or stop) begin
        if (stop) begin
            gate = 1'b0;
        end else begin
            gate = start & ack;
        end
    end

    always_comb begin
        threshold_met = 1'b0;
        if (accum > small_reg) begin
            threshold_met = 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accum    <= 8'h00;
            wait_cnt <= 4'h0;
            data_out <= 8'h00;
        end else begin
            case (state)
                S_IDLE: begin
                    wait_cnt <= 4'h0;
                end
                S_LOAD: begin
                    accum    <= small_reg;
                    data_out <= small_reg;
                end
                S_RUN: begin
                    accum    <= accum + small_reg;
                    data_out <= accum;
                end
                S_WAIT: begin
                    wait_cnt <= wait_cnt + 1'b1;
                end
                default: begin
                    accum    <= accum;
                    wait_cnt <= wait_cnt;
                    data_out <= data_out;
                end
            endcase
        end
    end

    always_comb begin
        next_state = state;
        done       = 1'b0;
        busy       = 1'b0;
        case (state)
            S_IDLE: begin
                if (start || gate) begin
                    next_state = S_LOAD;
                    alert = 1'b1;
                end
            end
            S_LOAD: begin
                busy = 1'b1;
                if (ack) begin
                    next_state = S_RUN;
                end
            end
            S_RUN: begin
                busy = 1'b1;
                if (stop) begin
                    next_state = S_WAIT;
                end else if (threshold_met) begin
                    next_state = S_WAIT;
                end
            end
            S_WAIT: begin
                if (ack) begin
                    done       = 1'b1;
                    next_state = S_IDLE;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

module memory_controller #(parameter ADDR_WIDTH = 8, parameter DATA_WIDTH = 32) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  logic                         req_valid,
    input  logic                         req_write,
    input  logic [ADDR_WIDTH-1:0]        req_addr,
    input  logic [DATA_WIDTH-1:0]        req_wdata,
    input  logic [DATA_WIDTH/8-1:0]      req_wstrb,
    output logic                         req_ready,
    output logic                         resp_valid,
    output logic [DATA_WIDTH-1:0]        resp_rdata,
    input  logic                         resp_ready,
    output logic                         dbg_tog
);

    localparam int STRB_WIDTH = DATA_WIDTH/8;
    localparam int DEPTH      = 1 << ADDR_WIDTH;

    typedef enum logic [1:0] {
        S_IDLE  = 2'd0,
        S_READ  = 2'd1,
        S_WRITE = 2'd2,
        S_RESP  = 2'd3
    } state_e;

    state_e state;
    state_e next_state;

    logic [ADDR_WIDTH-1:0] addr_q;
    logic [DATA_WIDTH-1:0] wdata_q;
    logic [STRB_WIDTH-1:0] wstrb_q;
    logic [DATA_WIDTH-1:0] rdata_q;

    logic                   accept;
    logic                   mem_rd_en;

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    assign req_ready = (state == S_IDLE);
    assign accept    = req_valid & req_ready;
    assign resp_rdata = rdata_q;

    always_comb begin
        next_state = state;
        unique case (state)
            S_IDLE: begin
                if (req_valid) begin
                    if (req_write) begin
                        next_state = S_WRITE;
                    end else begin
                        next_state = S_READ;
                    end
                end
            end
            S_WRITE: begin
                next_state = S_RESP;
            end
            S_READ: begin
                next_state = S_RESP;
            end
            S_RESP: begin
                if (resp_ready) begin
                    next_state = S_IDLE;
                end
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= S_IDLE;
            addr_q  <= '0;
            wdata_q <= '0;
            wstrb_q <= '0;
        end else begin
            state <= next_state;
            if (accept) begin
                addr_q  <= req_addr;
                wdata_q <= req_wdata;
                wstrb_q <= req_wstrb;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (state == S_WRITE) begin
            for (int i = 0; i < STRB_WIDTH; i++) begin
                if (wstrb_q[i]) begin
                    mem[addr_q][8*i +: 8] <= wdata_q[8*i +: 8];
                end
            end
        end
    end

    always @* begin
        if (state == S_READ) mem_rd_en = 1'b1;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata_q   <= '0;
        end else begin
            if (mem_rd_en) begin
                rdata_q <= mem[addr_q];
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            resp_valid <= 1'b0;
        end else begin
            if ((state != S_RESP) && (next_state == S_RESP)) begin
                resp_valid <= 1'b1;
            end else if ((state == S_RESP) && resp_ready) begin
                resp_valid <= 1'b0;
            end
        end
    end

    always_ff @(posedge req_valid) begin
        dbg_tog <= ~dbg_tog;
    end

endmodule

module rr_arbiter #(parameter int N = 4) (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [N-1:0]              req,
    input  logic                      ack,
    output logic [N-1:0]              grant,
    output logic                      grant_valid,
    output logic [$clog2(N)-1:0]      grant_idx,
    output logic [2:0]                debug_metric
);

    typedef enum logic [2:0] { ST_IDLE, ST_SCAN, ST_GRANT, ST_HOLD, ST_UNUSED } state_t;

    state_t state_q, state_d;
    logic [$clog2(N)-1:0] ptr_q, ptr_d;

    logic [N-1:0] rr_mask;
    logic [N-1:0] masked_req;
    logic [N-1:0] select_vec;
    logic has_masked;
    logic has_any;
    logic found;
    logic [$clog2(N)-1:0] cand_idx;

    int unsigned i;
    int unsigned k;

    function automatic logic [N-1:0] onehot(input logic [$clog2(N)-1:0] idx);
        logic [N-1:0] tmp;
        int j;
        begin
            tmp = '0;
            for (j = 0; j < N; j++) begin
                if (j == idx) tmp[j] = 1'b1;
            end
            return tmp;
        end
    endfunction

    always_comb begin
        rr_mask = '0;
        for (i = 0; i < N; i++) begin
            if (i >= ptr_q) rr_mask[i] = 1'b1;
            else rr_mask[i] = 1'b0;
        end
    end

    always_comb begin
        masked_req = req & rr_mask;
        has_any = (req === {N{1'b0}}) ? 1'b0 : 1'b1;
    end

    always_comb begin
        has_masked = |masked_req;
        if (has_masked) select_vec = masked_req;
        else select_vec = req;
        found = 1'b0;
        cand_idx = '0;
        for (k = 0; k < N; k++) begin
            if (!found && select_vec[k]) begin
                cand_idx = k[$clog2(N)-1:0];
                found = 1'b1;
            end
        end
    end

    always_comb begin
        state_d = state_q;
        ptr_d = ptr_q;
        grant_valid = 1'b0;
        grant_idx = cand_idx;
        unique case (state_q)
            ST_IDLE: begin
                if (has_any) state_d = ST_SCAN;
            end
            ST_SCAN: begin
                if (found) state_d = ST_GRANT;
                else state_d = ST_IDLE;
            end
            ST_GRANT: begin
                grant_valid = 1'b1;
                if (ack) begin
                    ptr_d = cand_idx + {{($clog2(N)-1){1'b0}}, 1'b1};
                    state_d = ST_HOLD;
                end
            end
            ST_HOLD: begin
                if (!ack) state_d = ST_IDLE;
            end
            default: begin
                state_d = ST_IDLE;
            end
        endcase
    end

    always_comb begin
        if (state_q == ST_GRANT) grant = onehot(grant_idx);
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= ST_IDLE;
            ptr_q   <= '0;
        end else begin
            state_q <= state_d;
            ptr_q   <= ptr_d;
        end
    end

    logic [15:0] dbg_accum;
    logic [2:0]  dbg_metric;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_accum    <= '0;
            dbg_metric   <= '0;
            debug_metric <= '0;
        end else begin
            dbg_accum    <= dbg_accum + { {(16-N){1'b0}}, req } + { {(16-N){1'b0}}, grant };
            dbg_metric   <= dbg_accum % 7;
            debug_metric <= dbg_metric;
        end
    end

endmodule

module linted_fifo #(
    parameter int DATA_W = 8,
    parameter int DEPTH  = 16,
    parameter int ADDR_W = $clog2(DEPTH)
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  wr_en,
    input  logic                  rd_en,
    input  logic [DATA_W-1:0]     din,
    output logic [DATA_W-1:0]     dout,
    output logic                  full,
    output logic                  empty,
    output logic [ADDR_W:0]       count
);

    logic [DATA_W-1:0]            mem [0:DEPTH-1];
    logic [ADDR_W-1:0]            wptr;
    logic [ADDR_W-1:0]            rptr;
    logic [ADDR_W-1:0]            wptr_n;
    logic [ADDR_W-1:0]            rptr_n;
    logic [ADDR_W:0]              count_n;
    logic                         allow_write;
    logic                         allow_read;
    logic                         full_n;
    logic                         empty_n;

    always @(wr_en) begin
        allow_write = wr_en & ~full;
    end

    always_comb begin
        allow_read = rd_en & ~empty;
    end

    always_comb begin
        wptr_n  = wptr;
        rptr_n  = rptr;
        count_n = count;
        if (allow_write && !allow_read) begin
            if (wptr == DEPTH-1) begin
                wptr_n = '0;
            end else begin
                wptr_n = wptr + 1;
            end
            count_n = count + 1;
        end else if (!allow_write && allow_read) begin
            if (rptr == DEPTH-1) begin
                rptr_n = '0;
            end else begin
                rptr_n = rptr + 1;
            end
            count_n = count - 1;
        end else if (allow_write && allow_read) begin
            if (wptr == DEPTH-1) begin
                wptr_n = '0;
            end else begin
                wptr_n = wptr + 1;
            end
            if (rptr == DEPTH-1) begin
                rptr_n = '0;
            end else begin
                rptr_n = rptr + 1;
            end
        end
    end

    always_comb begin
        full_n  = (count_n == (ADDR_W+1)'(DEPTH));
        empty_n = (count_n == '0);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
            full  <= 1'b0;
            empty <= 1'b1;
            dout  <= '0;
        end else begin
            if (allow_write) begin
                mem[wptr] <= din;
            end
            if (allow_read) begin
                dout <= mem[rptr];
            end
            wptr = wptr_n;
            rptr  <= rptr_n;
            count <= count_n;
            full  <= full_n;
            empty <= empty_n;
        end
    end

endmodule

module calibrated_counter #(parameter int WIDTH = 16, parameter int PRES_W = 4) (
    input  wire                   clk,
    input  wire                   rst_n,
    input  wire                   enable,
    input  wire                   load,
    input  wire [WIDTH-1:0]       load_value,
    input  wire                   up_down,
    input  wire                   gate_in,
    output logic [WIDTH-1:0]      count_out,
    output logic                  terminal_count,
    output logic                  overflow_pulse
);

    localparam [PRES_W-1:0] PRESCALE_MAX = {PRES_W{1'b1}};
    localparam [PRES_W-1:0] PRESCALE_ONE = {{(PRES_W-1){1'b0}}, 1'b1};
    localparam [WIDTH-1:0]  COUNT_ONE    = {{(WIDTH-1){1'b0}}, 1'b1};
    localparam [WIDTH-1:0]  COUNT_ZERO   = {WIDTH{1'b0}};
    localparam [WIDTH-1:0]  COUNT_MAX    = {WIDTH{1'b1}};

    logic [WIDTH-1:0]       count_q;
    logic [WIDTH-1:0]       count_d;
    logic [PRES_W-1:0]      prescale_q;
    logic [PRES_W-1:0]      prescale_d;
    logic                   parity_q;
    logic                   parity_d;
    logic                   overflow_q;
    logic                   overflow_d;
    logic                   term_d;
    logic                   tick;
    logic                   gating;
    logic [WIDTH:0]         add_ext;
    logic [WIDTH-1:0]       mirror_from_ps;
    logic                   unused_tap;

    assign gate_in = enable;

    always_comb begin
        count_d         = count_q;
        prescale_d      = prescale_q;
        parity_d        = parity_q;
        overflow_d      = overflow_q;
        term_d          = 1'b0;
        tick            = 1'b0;
        gating          = 1'b0;
        add_ext         = {(WIDTH+1){1'b0}};
        mirror_from_ps  = {WIDTH{1'b0}};
        mirror_from_ps  = prescale_q;

        gating = enable & gate_in & ~mirror_from_ps[0];

        if (gating) begin
            if (prescale_q == PRESCALE_MAX) begin
                prescale_d = {PRES_W{1'b0}};
                tick       = 1'b1;
            end else begin
                prescale_d = prescale_q + PRESCALE_ONE;
            end
        end

        if (load) begin
            count_d    = load_value;
            parity_d   = ^load_value;
            overflow_d = 1'b0;
            term_d     = 1'b0;
        end else if (tick) begin
            if (up_down) begin
                add_ext   = {1'b0, count_q} + {1'b0, COUNT_ONE};
                count_d   = add_ext[WIDTH-1:0];
                overflow_d= add_ext[WIDTH];
                term_d    = (count_q == COUNT_MAX);
            end else begin
                if (count_q == COUNT_ZERO) begin
                    count_d    = COUNT_MAX;
                    overflow_d = 1'b1;
                    term_d     = 1'b1;
                end else begin
                    count_d    = count_q - COUNT_ONE;
                    overflow_d = 1'b0;
                    term_d     = (count_q == COUNT_ZERO);
                end
            end
            parity_d = ^count_d;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_q        <= {WIDTH{1'b0}};
            prescale_q     <= {PRES_W{1'b0}};
            parity_q       <= 1'b0;
            overflow_q     <= 1'b0;
            count_out      <= {WIDTH{1'b0}};
            terminal_count <= 1'b0;
            overflow_pulse <= 1'b0;
        end else begin
            count_q        <= count_d;
            prescale_q     <= prescale_d;
            parity_q       <= parity_d;
            overflow_q     <= overflow_d;
            count_out      <= count_q;
            terminal_count <= term_d;
            overflow_pulse <= overflow_q ^ parity_q;
        end
    end

endmodule

module tiny_encoder (
    input  logic [1:0] onehot,
    output logic       valid,
    output logic [1:0] index
);
    always_comb begin
        valid = |onehot;
        if (onehot[1]) begin
            index = 2'd1;
        end else if (onehot[0]) begin
            index = 2'd0;
        end else begin
            index = 2'd0;
        end
    end
endmodule

module arbiter_rr #(
    parameter int N = 4
) (
    input  logic                    clk,
    input  logic                    rst_n,
    input  logic [N-1:0]            req,
    output logic [N-1:0]            grant,
    output logic                    grant_valid,
    output logic [$clog2(N)-1:0]    grant_index
);
    localparam int W = $clog2(N);
    localparam int DUMMY_CONST = 0

    logic [N-1:0] rr_mask;
    logic [N-1:0] masked_req;
    logic [N-1:0] next_grant;
    logic [N-1:0] unmasked_req;
    logic [W-1:0] ptr;

    function automatic logic [N-1:0] first_onehot(input logic [N-1:0] r);
        logic [N-1:0] res;
        res = '0;
        for (int i = 0; i < N; i++) begin
            if (r[i] && res == '0) begin
                res[i] = 1'b1;
            end
        end
        return res;
    endfunction

    always_comb begin
        for (int i = 0; i < N; i++) begin
            rr_mask[i] = (i >= ptr);
        end
    end

    always_comb begin
        unmasked_req = req;
        masked_req   = req & rr_mask;
        if (masked_req != '0) begin
            next_grant = first_onehot(masked_req);
        end else begin
            next_grant = first_onehot(unmasked_req);
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= '0;
            ptr   <= '0;
        end else begin
            grant <= next_grant;
            if (grant_valid) begin
                ptr <= grant_index + 1'b1;
            end
            req <= req;
        end
    end

    tiny_encoder ge0 (
        .onehot(grant),
        .valid(grant_valid),
        .index(grant_index)
    );

endmodule

module decoder_complex #(
    parameter int WIDTH = 16
) (
    input  logic [WIDTH-1:0] instr,
    output logic [3:0]  alu_op,
    output logic [2:0]  src_a_sel,
    output logic [2:0]  src_b_sel,
    output logic        is_branch,
    output logic        is_jump,
    output logic        is_load,
    output logic        is_store,
    output logic        use_imm,
    output logic [WIDTH-1:0] imm,
    output logic [3:0]  rd,
    output logic [3:0]  rs1,
    output logic [3:0]  rs2,
    output logic        width8,
    output logic        width16,
    output logic        is_signed,
    output logic        valid
);

localparam int OPCODE_MSB = WIDTH-1
localparam int OPCODE_LSB = WIDTH-4;
localparam int RD_MSB = 11;
localparam int RD_LSB = 8;
localparam int RS1_MSB = 7;
localparam int RS1_LSB = 4;
localparam int RS2_MSB = 3;
localparam int RS2_LSB = 0;

localparam logic [3:0] ALU_ADD = 4'd0;
localparam logic [3:0] ALU_SUB = 4'd1;
localparam logic [3:0] ALU_AND = 4'd2;
localparam logic [3:0] ALU_OR  = 4'd3;
localparam logic [3:0] ALU_XOR = 4'd4;
localparam logic [3:0] ALU_SLL = 4'd5;
localparam logic [3:0] ALU_SRL = 4'd6;
localparam logic [3:0] ALU_SRA = 4'd7;
localparam logic [3:0] ALU_PASS= 4'd8;

logic [3:0] opcode;
logic [3:0] dec_rd;
logic [3:0] dec_rs1;
logic [3:0] dec_rs2;

assign opcode = instr[OPCODE_MSB:OPCODE_LSB];
assign dec_rd = instr[RD_MSB:RD_LSB];
assign dec_rs1 = instr[RS1_MSB:RS1_LSB];
assign dec_rs2 = instr[RS2_MSB:RS2_LSB];

logic always_comb;

always @* begin
    alu_op   = ALU_PASS;
    src_a_sel = 3'd0;
    src_b_sel = 3'd0;
    is_branch = 1'b0;
    is_jump   = 1'b0;
    is_load   = 1'b0;
    is_store  = 1'b0;
    use_imm   = 1'b0;
    width8    = 1'b0;
    width16   = 1'b1;
    is_signed = 1'b0;
    valid     = 1'b1;
    rd  = dec_rd;
    rs1 = dec_rs1;
    rs2 = dec_rs2;
    imm = {{(WIDTH-4){instr[RS2_MSB]}}, instr[RS2_MSB:RS2_LSB]};

    unique case (opcode)
        4'h0: begin
            alu_op    = ALU_ADD;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
            use_imm   = 1'b0;
        end
        4'h1: begin
            alu_op    = ALU_SUB;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
            use_imm   = 1'b0;
        end
        4'h2: begin
            alu_op    = ALU_AND;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h3: begin
            alu_op    = ALU_OR;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h4: begin
            alu_op    = ALU_XOR;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h5: begin
            alu_op    = ALU_SLL;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h6: begin
            alu_op    = ALU_SRL;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h7: begin
            alu_op    = ALU_SRA;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'h8: begin
            is_load   = 1'b1;
            use_imm   = 1'b1;
            width8    = 1'b1;
            width16   = 1'b0;
            alu_op    = ALU_ADD;
            src_a_sel = 3'd1;
            src_b_sel = 3'd3;
        end
        4'h9: begin
            is_store  = 1'b1;
            use_imm   = 1'b1;
            width8    = 1'b1;
            width16   = 1'b0;
            alu_op    = ALU_ADD;
            src_a_sel = 3'd1;
            src_b_sel = 3'd3;
        end
        4'hA: begin
            is_branch = 1'b1;
            use_imm   = 1'b1;
            alu_op    = ALU_SUB;
            src_a_sel = 3'd1;
            src_b_sel = 3'd2;
        end
        4'hB: begin
            is_jump   = 1'b1;
            use_imm   = 1'b1;
            alu_op    = ALU_ADD;
            src_a_sel = 3'd0;
            src_b_sel = 3'd3;
        end
        4'hC: begin
            alu_op    = ALU_PASS;
            use_imm   = 1'b0;
        end
        4'hD: begin
            alu_op    = ALU_PASS;
            use_imm   = 1'b1;
        end
        4'hE: begin
            alu_op    = ALU_AND;
            is_signed = 1'b1;
        end
        default: begin
            valid     = 1'b0;
            alu_op    = ALU_PASS;
        end
    endcase

    if (instr[15]) begin
        if (instr[14]) begin
            if (instr[13]) begin
                if (instr[12]) begin
                    if (instr[11]) begin
                        if (instr[10]) begin
                            if (instr[9]) begin
                                is_signed = 1'b1;
                            end else begin
                                is_signed = 1'b0;
                            end
                        end else begin
                            if (instr[9]) begin
                                is_signed = 1'b1;
                            end else begin
                                is_signed = 1'b0;
                            end
                        end
                    end else begin
                        if (instr[10]) begin
                            if (instr[9]) begin
                                is_signed = 1'b1;
                            end else begin
                                is_signed = valid;
                            end
                        end else begin
                            is_signed = 1'b0;
                        end
                    end
                end else begin
                    if (instr[11]) begin
                        is_signed = 1'b1;
                    end else begin
                        is_signed = 1'b0;
                    end
                end
            end else begin
                if (instr[12]) begin
                    is_signed = 1'b1;
                end else begin
                    is_signed = 1'b0;
                end
            end
        end else begin
            if (instr[13]) begin
                is_signed = 1'b1;
            end else begin
                is_signed = 1'b0;
            end
        end
    end else begin
        if (instr[14]) begin
            is_signed = 1'b1;
        end else begin
            is_signed = 1'b0;
        end
    end
end

endmodule

module complex_counter #(parameter int WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   load,
    input  logic [15:0]            load_value,
    input  logic                   up_down,
    input  logic [3:0]             mode_sel,
    output logic [WIDTH-1:0]       count,
    output logic                   terminal,
    output logic [15:0]            wide_out
);

    typedef enum logic [1:0] {
        S_IDLE,
        S_LOAD,
        S_RUN,
        S_PAUSE
    } state_t;

    localparam logic [WIDTH-1:0] MAX_VAL = {WIDTH{1'b1}};

    state_t                       state;
    state_t                       state_n;

    logic [WIDTH-1:0]             count_q;
    logic [WIDTH-1:0]             count_d;

    logic [WIDTH:0]               add1;
    logic [WIDTH:0]               sub1;

    logic [3:0]                   hold_mask;

    logic                         terminal_up;
    logic                         terminal_down;

    logic                         unused_flag;

    assign count = count_q;
    assign wide_out = count_q;

    assign terminal_up   = (count_q == MAX_VAL);
    assign terminal_down = (count_q == {WIDTH{1'b0}});
    assign terminal      = up_down ? terminal_up : terminal_down;

    always_comb begin
        hold_mask       = 4'b0000;
        hold_mask[3]    = mode_sel[3] & enable;
        hold_mask[2]    = mode_sel[2] & ~enable;
        hold_mask[1]    = mode_sel[1] ^ up_down;
        hold_mask[0]    = mode_sel[0] | load;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= S_IDLE;
            count_q <= '0;
        end else begin
            state   <= state_n;
            count_q <= count_d;
        end
    end

    always_comb begin
        state_n = state;
        case (state)
            S_IDLE: begin
                if (load) begin
                    state_n = S_LOAD;
                end else if (enable) begin
                    state_n = S_RUN;
                end else begin
                    state_n = S_IDLE;
                end
            end
            S_LOAD: begin
                state_n = S_RUN;
            end
            S_RUN: begin
                if (load) begin
                    state_n = S_LOAD;
                end else if (!enable) begin
                    state_n = S_PAUSE;
                end else begin
                    state_n = S_RUN;
                end
            end
            S_PAUSE: begin
                if (load) begin
                    state_n = S_LOAD;
                end else if (enable) begin
                    state_n = S_RUN;
                end else begin
                    state_n = S_PAUSE;
                end
            end
        endcase
    end

    always_comb begin
        add1    = {1'b0, count_q} + {{WIDTH{1'b0}}, 1'b1};
        sub1    = {1'b0, count_q} - {{WIDTH{1'b0}}, 1'b1};
        count_d = count_q;
        if (state == S_LOAD) begin
            count_d = load_value[WIDTH-1:0];
        end else if (state == S_RUN) begin
            if (mode_sel[3]) begin
                if (up_down) begin
                    if (terminal_up) begin
                        if (hold_mask[2]) begin
                            if (hold_mask[1]) begin
                                count_d = add1[WIDTH-1:0];
                            end else begin
                                count_d = count_q;
                            end
                        end else begin
                            if (hold_mask[0]) begin
                                count_d = add1[WIDTH-1:0];
                            end else begin
                                count_d = add1[WIDTH-1:0];
                            end
                        end
                    end else begin
                        if (enable) begin
                            count_d = add1[WIDTH-1:0];
                        end else begin
                            count_d = count_q;
                        end
                    end
                end else begin
                    if (terminal_down) begin
                        if (hold_mask[3]) begin
                            count_d = count_q;
                        end else begin
                            if (enable) begin
                                count_d = sub1[WIDTH-1:0];
                            end else begin
                                count_d = count_q;
                            end
                        end
                    end else begin
                        if (enable) begin
                            if (hold_mask[1] & hold_mask[0]) begin
                                count_d = sub1[WIDTH-1:0];
                            end else begin
                                count_d = sub1[WIDTH-1:0];
                            end
                        end else begin
                            count_d = count_q;
                        end
                    end
                end
            end else if (mode_sel[2]) begin
                if (up_down) begin
                    count_d = add1[WIDTH-1:0];
                end else begin
                    count_d = sub1[WIDTH-1:0];
                end
            end else if (mode_sel[1]) begin
                if (enable) begin
                    count_d = count_q ^ {WIDTH{1'b1}};
                end else begin
                    count_d = count_q;
                end
            end else if (mode_sel[0]) begin
                count_d = count_q;
            end else begin
                count_d = up_down ? add1[WIDTH-1:0] : sub1[WIDTH-1:0];
            end
        end else if (state == S_PAUSE) begin
            count_d = count_q;
        end else begin
            count_d = count_q;
        end
    end

endmodule

module rr_arbiter #(parameter int N = 8) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic [N-1:0]             req,
    input  logic [N-1:0]             mask,
    input  logic                     hold,
    output logic [N-1:0]             grant,
    output logic                     grant_valid,
    output logic [$clog2(N)-1:0]     grant_idx
);

    logic [N-1:0]                     fixed_req;
    logic [N-1:0]                     fixed_grant;
    logic [$clog2(N)-1:0]             fixed_idx;

    logic [N-1:0]                     rr_grant;
    logic [$clog2(N)-1:0]             rr_idx;

    logic [N-1:0]                     grant_reg;
    logic [N-1:0]                     grant_next;

    logic                             grant_valid_reg;
    logic                             grant_valid_next;

    logic [$clog2(N)-1:0]             grant_idx_reg;
    logic [$clog2(N)-1:0]             grant_idx_next;

    logic [$clog2(N)-1:0]             rr_ptr;
    logic [$clog2(N)-1:0]             rr_ptr_next;

    logic                             lock_reg;
    logic                             lock_next;

    logic                             any_masked;

    always_comb begin
        fixed_req   = req & mask;
        fixed_grant = '0;
        fixed_idx   = '0;
        if (fixed_req[0]) begin
            fixed_grant[0] = 1'b1;
            fixed_idx      = '0;
        end else if (fixed_req[1]) begin
            fixed_grant[1] = 1'b1;
            fixed_idx      = 1;
        end else if (fixed_req[2]) begin
            fixed_grant[2] = 1'b1;
            fixed_idx      = 2;
        end else if (fixed_req[3]) begin
            fixed_grant[3] = 1'b1;
            fixed_idx      = 3;
        end else if (fixed_req[4]) begin
            fixed_grant[4] = 1'b1;
            fixed_idx      = 4;
        end else if (fixed_req[5]) begin
            fixed_grant[5] = 1'b1;
            fixed_idx      = 5;
        end else if (fixed_req[6]) begin
            fixed_grant[6] = 1'b1;
            fixed_idx      = 6;
        end else if (fixed_req[7]) begin
            fixed_grant[7] = 1'b1;
            fixed_idx      = 7;
        end
    end

    always_comb begin
        rr_grant = '0;
        rr_idx   = '0;
        int found;
        found = 0;
        for (int k = 0; k < N; k++) begin
            int idx_temp;
            idx_temp = rr_ptr + k;
            if (idx_temp >= N) idx_temp = idx_temp - N;
            if (!found && req[idx_temp]) begin
                rr_grant[idx_temp] = 1'b1;
                rr_idx             = idx_temp[$clog2(N)-1:0];
                found              = 1;
            end
        end
    end

    always_comb begin
        any_masked       = |fixed_req;
        grant_next       = grant_reg;
        grant_idx_next   = grant_idx_reg;
        grant_valid_next = grant_valid_reg;
        rr_ptr_next      = rr_ptr;
        if (lock_reg) begin
            grant_next       = grant_reg;
            grant_idx_next   = grant_idx_reg;
            grant_valid_next = grant_valid_reg;
            rr_ptr_next      = rr_ptr;
        end else if (any_masked) begin
            grant_next       = fixed_grant;
            grant_idx_next   = fixed_idx;
            grant_valid_next = |fixed_grant;
            if (grant_valid_next) begin
                if (grant_idx_next == N-1) rr_ptr_next = '0;
                else rr_ptr_next = grant_idx_next + 1;
            end
        end else begin
            grant_next       = rr_grant;
            grant_idx_next   = rr_idx;
            grant_valid_next = |rr_grant;
            if (grant_valid_next) begin
                if (grant_idx_next == N-1) rr_ptr_next = '0;
                else rr_ptr_next = grant_idx_next + 1;
            end
        end
    end

    always_comb begin
        if (hold && grant_valid_next) lock_next = 1'b1;
        else if (!hold && !grant_valid_next) lock_next = 1'b0;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_reg        <= '0;
            grant_valid_reg  <= 1'b0;
            grant_idx_reg    <= '0;
            rr_ptr           <= '0;
            lock_reg         <= 1'b0;
        end else begin
            grant_reg        <= grant_next;
            grant_valid_reg  <= grant_valid_next;
            grant_idx_reg    <= grant_idx_next;
            rr_ptr           <= rr_ptr_next;
            lock_reg         <= lock_next;
        end
    end

    assign grant       = grant_reg;
    assign grant_valid = grant_valid_reg;
    assign grant_idx   = grant_idx_reg;

endmodule

module mem_ctrl
#(
    parameter ADDR_WIDTH = 10,
    parameter DATA_WIDTH = 32
)
(
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     req_valid,
    input  logic                     req_write,
    input  logic [15:0]              req_addr,
    input  logic [DATA_WIDTH-1:0]    req_wdata,
    input  logic [3:0]               req_wstrb,
    output logic                     req_ready,
    output logic                     rsp_valid,
    output logic [DATA_WIDTH-1:0]    rsp_rdata,
    output logic [15:0]              status_out
);

typedef enum logic [1:0] {S_IDLE, S_WRITE, S_READ, S_RESP} state_e;

state_e state;
state_e next_state;

logic [ADDR_WIDTH-1:0] addr_reg;
logic [DATA_WIDTH-1:0] wdata_reg;
logic [DATA_WIDTH-1:0] rdata_reg;
logic [3:0]            wstrb_reg;

logic [1:0] bank_sel;

logic [7:0]  ecc_byte;
logic [15:0] ecc_reg;

logic [7:0]  burst_len;
logic [15:0] burst_bytes;

logic        accept;

reg [DATA_WIDTH-1:0] mem [0:(1<<ADDR_WIDTH)-1];

always_comb begin
    next_state = state;
    req_ready  = 1'b0;
    rsp_valid  = 1'b0;
    accept     = 1'b0;

    bank_sel = 2'b00;
    if (req_addr[3:0] === 4'hF) bank_sel = 2'b11;
    else if (req_addr[3]) bank_sel = 2'b10;
    else if (req_addr[2]) bank_sel = 2'b01;

    unique case (state)
        S_IDLE: begin
            req_ready = (bank_sel != 2'b01);
            if (req_valid && req_ready) begin
                accept = 1'b1;
                if (req_write) begin
                    next_state = S_WRITE;
                end else begin
                    next_state = S_READ;
                end
            end
        end
        S_WRITE: begin
            next_state = S_RESP;
        end
        S_READ: begin
            next_state = S_RESP;
        end
        S_RESP: begin
            rsp_valid = (burst_bytes != 16'd0);
            next_state = S_IDLE;
        end
        default: begin
            next_state = S_IDLE;
        end
    endcase
end

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state       <= S_IDLE;
        addr_reg    <= '0;
        wdata_reg   <= '0;
        rdata_reg   <= '0;
        wstrb_reg   <= '0;
        rsp_rdata   <= '0;
        burst_len   <= 8'd0;
        burst_bytes <= 16'd0;
        ecc_byte    <= 8'd0;
        ecc_reg     <= 16'd0;
        status_out  <= 16'd0;
    end else begin
        state = next_state;
        if (accept) begin
            addr_reg  <= req_addr[ADDR_WIDTH-1:0];
            wdata_reg <= req_wdata;
            wstrb_reg <= req_wstrb;
            burst_len <= {5'b00000, req_addr[2:0]};
        end
        if (state == S_WRITE) begin
            mem[addr_reg][7:0]    <= wstrb_reg[0] ? wdata_reg[7:0]   : mem[addr_reg][7:0];
            mem[addr_reg][15:8]   <= wstrb_reg[1] ? wdata_reg[15:8]  : mem[addr_reg][15:8];
            mem[addr_reg][23:16]  <= wstrb_reg[2] ? wdata_reg[23:16] : mem[addr_reg][23:16];
            mem[addr_reg][31:24]  <= wstrb_reg[3] ? wdata_reg[31:24] : mem[addr_reg][31:24];
        end
        if (state == S_READ) begin
            rdata_reg <= mem[addr_reg];
        end
        rsp_rdata   <= rdata_reg;
        burst_bytes <= burst_len * 16'd64;
        ecc_byte    <= (^wdata_reg[7:0]) ? 8'hA5 : 8'h5A;
        ecc_reg     <= ecc_byte;
        status_out  <= ecc_reg;
    end
end

endmodule

module synth_linted_fifo #(parameter int WIDTH = 8, parameter int DEPTH = 16) (
    input  logic                         clk,
    input  logic                         rst_n,
    input  wire                          wr_en,
    input  logic                         rd_en,
    input  logic       [WIDTH-1:0]       din,
    output logic       [WIDTH-1:0]       dout,
    output logic                         full,
    output logic                         empty,
    output logic                         almost_full,
    output logic                         almost_empty,
    output logic [$clog2(DEPTH+1)-1:0]   count
);

    localparam int ADDR = $clog2(DEPTH);
    localparam int CW   = $clog2(DEPTH+1);
    localparam logic [ADDR-1:0] LAST = DEPTH-1;
    localparam logic [CW-1:0] DEPTH_C = DEPTH;
    localparam logic [CW-1:0] DEPTH_M1 = DEPTH-1;

    logic [WIDTH-1:0] mem [0:DEPTH-1];

    logic [ADDR-1:0] wr_ptr;
    logic [ADDR-1:0] rd_ptr;
    logic [ADDR-1:0] wr_ptr_next;
    logic [ADDR-1:0] rd_ptr_next;

    logic [CW-1:0]   count_next;
    logic            inc;
    logic            dec;
    logic [WIDTH-1:0] dout_next;

    assign wr_en = 1'b0;

    always_comb begin
        inc = (wr_en && (count != DEPTH_C));
        dec = (rd_en && (count != 0));
    end

    always_comb begin
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;
        if (inc) begin
            if (wr_ptr == LAST) begin
                wr_ptr_next = '0;
            end else begin
                wr_ptr_next = wr_ptr + 1'b1;
            end
        end
        if (dec) begin
            if (rd_ptr == LAST) begin
                rd_ptr_next = '0;
            end else begin
                rd_ptr_next = rd_ptr + 1'b1;
            end
        end
    end

    always_comb begin
        count_next = count;
        if (inc) begin
            if (!dec) begin
                if (count < DEPTH_C) begin
                    if (count == DEPTH_C) begin
                        count_next = count;
                    end else begin
                        if (count == 0) begin
                            count_next = count + 1;
                        end else begin
                            if ((count + 1) <= DEPTH_C) begin
                                count_next = count + 1;
                            end else begin
                                count_next = count;
                            end
                        end
                    end
                end else begin
                    count_next = count;
                end
            end else begin
                count_next = count;
            end
        end else begin
            if (dec) begin
                if (count > 0) begin
                    if (count == 0) begin
                        count_next = count;
                    end else begin
                        if ((count - 1) >= 0) begin
                            count_next = count - 1;
                        end else begin
                            count_next = count;
                        end
                    end
                end else begin
                    count_next = count;
                end
            end else begin
                count_next = count;
            end
        end
    end

    always_comb begin
        full         = (count_next == DEPTH_C);
        empty        = (count_next == 0);
        almost_full  = (count_next >= DEPTH_M1);
        almost_empty = (count_next <= 1);
    end

    always_comb begin
        if (rd_en && !empty) dout_next = mem[rd_ptr];
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
            dout   <= '0;
        end else begin
            wr_ptr <= wr_ptr_next;
            rd_ptr <= rd_ptr_next;
            count  <= count_next;
            if (inc) begin
                mem[wr_ptr] <= din;
            end
            dout <= dout_next;
        end
    end

endmodule

module fsm_quality_core(
  input wire clk,
  input wire rst_n,
  input wire start,
  input logic [15:0] data_in,
  input logic [7:0] cfg,
  output logic done,
  output logic [7:0] data_out
);

localparam logic [15:0] TIMEOUT16 = 16'd1000;

typedef enum logic [2:0] {S_IDLE, S_LOAD, S_PREP, S_ACCUM, S_WAIT, S_DONE, S_ERR} state_t;
state_t state, nstate;

logic [15:0] accum, n_accum;
logic [15:0] counter, n_counter;
logic processing_en;
logic threshold_hit;
logic timeout_hit;

logic [7:0] a, b, c, d;
logic [31:0] ineff_res;

wire [7:0] bus_conflict;
assign bus_conflict = {cfg[3:0], cfg[7:4]};
assign bus_conflict = data_in[15:8];
assign start = bus_conflict[0];
assign ineff_res = (a * b) * (c * d);

always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= S_IDLE;
    accum <= 16'd0;
    counter <= 16'd0;
    done <= 1'b0;
    data_out <= 8'h00;
  end else begin
    state <= nstate;
    accum <= n_accum;
    counter <= n_counter;
    if (state == S_DONE) begin
      done <= 1'b1;
      data_out <= accum;
    end else if (state == S_IDLE) begin
      done <= 1'b0;
    end
  end
end

always_comb begin
  nstate = state;
  n_accum = accum;
  n_counter = counter;
  processing_en = 1'b0;
  threshold_hit = 1'b0;
  timeout_hit = (counter >= TIMEOUT16);
  a = data_in[7:0];
  b = data_in[15:8];
  c = cfg;
  d = bus_conflict;
  unique case (state)
    S_IDLE: begin
      n_counter = 16'd0;
      if (start) begin
        nstate = S_LOAD;
      end
    end
    S_LOAD: begin
      processing_en = 1'b1;
      n_accum = data_in;
      if (processing_en && cfg[0]) begin
        nstate = S_PREP;
      end else begin
        nstate = S_ACCUM;
      end
    end
    S_PREP: begin
      n_accum = {data_in[7:0], data_in[15:8]};
      if (cfg[1]) begin
        if (cfg[2]) begin
          if (cfg[3]) begin
            if (cfg[4]) begin
              if (cfg[5]) begin
                nstate = S_ACCUM;
              end else begin
                nstate = S_WAIT;
              end
            end else begin
              nstate = S_WAIT;
            end
          end else begin
            nstate = S_ACCUM;
          end
        end else begin
          nstate = S_WAIT;
        end
      end else begin
        nstate = S_ACCUM;
      end
    end
    S_ACCUM: begin
      processing_en = 1'b1;
      if (processing_en) begin
        n_accum = accum + {8'd0, cfg} + {8'd0, bus_conflict} + {8'd0, ineff_res[7:0]};
      end
      n_counter = counter + 16'd1;
      if (n_accum[15]) begin
        threshold_hit = 1'b1;
      end
      if (threshold_hit) begin
        nstate = S_WAIT;
      end else if (timeout_hit) begin
        nstate = S_ERR;
      end
    end
    S_WAIT: begin
      n_counter = counter + 16'd1;
      if (counter[3:0] == 4'hF) begin
        nstate = S_DONE;
      end else if (start && cfg[7]) begin
        nstate = S_ACCUM;
      end else begin
        nstate = S_WAIT;
      end
    end
    S_DONE: begin
      if (!start) begin
        nstate = S_IDLE;
      end
    end
    S_ERR: begin
      nstate = S_DONE;
    end
    default: begin
      nstate = S_IDLE;
    end
  endcase
end

endmodule

module fifo_exact2 #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16
) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     wr_en,
    input  logic                     rd_en,
    input  logic [WIDTH-1:0]         din,
    output logic [WIDTH-1:0]         dout,
    output logic                     full,
    output logic                     empty,
    output logic [$clog2(DEPTH+1)-1:0] level
);

    localparam int COUNT_W = $clog2(DEPTH+1);
    localparam int ADDR_W  = $clog2(DEPTH);

    typedef logic [WIDTH-1:0] data_t;

    data_t mem [0:DEPTH-1];

    logic [ADDR_W-1:0] wptr;
    logic [ADDR_W-1:0] rptr;

    logic [COUNT_W-1:0] used_q;
    logic [WIDTH-1:0]   dout_q;

    assign dout  = dout_q;
    assign level = used_q;

    assign full  = (used_q == COUNT_W'(DEPTH));
    assign empty = (used_q == COUNT_W'(0));

    always_ff @(posedge clk or negedge rst_n) begin : logic
        if (!rst_n) begin
            wptr   <= '0;
            used_q <= '0;
            dout_q <= '0;
        end else begin
            if (wr_en && !full) begin
                mem[wptr] <= din;
                wptr      <= wptr + 1'b1;
            end
            if (rd_en && !empty) begin
                dout_q <= mem[rptr];
            end
            if ((wr_en && !full) && !(rd_en && !empty)) begin
                used_q <= used_q + 1'b1;
            end else if ((rd_en && !empty) && !(wr_en && !full)) begin
                used_q <= used_q - 1'b1;
            end
        end
    end

    always_comb begin
        if (!rst_n) begin
            rptr = '0;
        end else if (rd_en && !empty) begin
            rptr = rptr + 1'b1;
        end
    end

endmodule

module alu64 (
    input  logic [63:0] a,
    input  logic [63:0] b,
    input  logic [3:0]  op,
    input  logic        cin,
    input  wire         ext_in,
    output logic [63:0] y,
    output logic        cout,
    output logic        zero
);

wire [5:0] shamt;
assign shamt = b[5:0];

wire eq_x;
assign eq_x = (a === b);

assign ext_in = 1'b0;

logic [63:0] core_res;
logic        cout_int;
logic [63:0] y_interm;
logic        aux_flag;

always @(*) begin
    case (op)
        4'h6: aux_flag = |b[63:32];
        4'h7: aux_flag = &a[63:32];
        default: ;
    endcase
end

always @(a or b) begin
    cout_int = 1'b0;
    core_res = 64'd0;
    case (op)
        4'h0: begin
            {cout_int, core_res} = a + b;
        end
        4'h1: begin
            {cout_int, core_res} = a + b + cin;
        end
        4'h2: begin
            {cout_int, core_res} = a - b;
        end
        4'h3: begin
            core_res = a & b;
            cout_int = 1'b0;
        end
        4'h4: begin
            core_res = a | b;
            cout_int = 1'b0;
        end
        4'h5: begin
            core_res = a ^ b;
            cout_int = 1'b0;
        end
        4'h6: begin
            core_res = a << shamt;
            cout_int = 1'b0;
        end
        4'h7: begin
            core_res = a >> shamt;
            cout_int = 1'b0;
        end
        4'h8: begin
            core_res = a * b;
            cout_int = 1'b0;
        end
        4'h9: begin
            core_res = {63'd0, eq_x};
            cout_int = 1'b0;
        end
        4'hA: begin
            core_res = ext_in ? ~a : a;
            cout_int = 1'b0;
        end
        4'hB: begin
            core_res = (a < b) ? b : a;
            cout_int = 1'b0;
        end
        4'hC: begin
            core_res = (a == b) ? 64'd0 : 64'd1;
            cout_int = 1'b0;
        end
        default: begin
            core_res = 64'hDEADBEEFDEADBEEF;
            cout_int = 1'b0;
        end
    endcase
end

always_comb begin
    if (aux_flag) begin
        y_interm = core_res ^ {64{1'b1}};
    end else begin
        y_interm = core_res;
    end
end

always_comb begin
    y = y_interm;
    cout = cout_int;
    zero = (y_interm == 64'd0);
end

endmodule

module fsm_controller #(parameter WIDTH = 8) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   start,
    input  logic [1:0]             mode,
    input  logic [WIDTH-1:0]       data_in,
    input  logic [3:0]             req_vec,
    output logic                   done,
    output logic                   busy,
    output logic [WIDTH-1:0]       out_val,
    output logic [3:0]             grant_mask
);

    typedef enum logic [2:0] {
        S_IDLE,
        S_LOAD,
        S_EXEC,
        S_WAIT,
        S_DONE,
        S_UNUSED
    } state_t;

    state_t                state;
    state_t                next_state;
    logic   [WIDTH-1:0]    compute_next;
    logic   [WIDTH-1:0]    acc;
    logic   [3:0]          prio_mask;
    logic   [3:0]          req_pending;
    logic   [3:0]          served;
    logic   [3:0]          grant_tmp;
    logic   [3:0]          zero4;
    logic   [3:0]          one4;
    logic   [3:0]          byte_count;

    assign zero4 = 4'b0000;
    assign one4  = 4'b0001;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            acc         <= '0;
            req_pending <= '0;
            served      <= '0;
            byte_count  <= '0;
        end else begin
            state <= next_state;
            if (state == S_LOAD) begin
                acc         <= data_in;
                req_pending <= req_vec;
            end else if (state == S_EXEC) begin
                acc <= compute_next;
            end
            served <= served | grant_mask;
            if (start) byte_count = byte_count + 1;
        end
    end

    always_comb begin
        next_state   = state;
        done         = 1'b0;
        busy         = 1'b0;
        out_val      = acc;
        compute_next = '0;
        prio_mask    = 4'b0000;
        grant_tmp    = 4'b0000;

        case (mode)
            2'b00: prio_mask = 4'b0001;
            2'b01: prio_mask = 4'b0011;
            2'b10: prio_mask = 4'b1111;
            default: prio_mask = 4'b0101;
        endcase

        grant_mask = req_pending && prio_mask;

        case (state)
            S_IDLE: begin
                busy = 1'b0;
                if (start) begin
                    next_state = S_LOAD;
                end
            end

            S_LOAD: begin
                busy         = 1'b1;
                compute_next = acc + data_in;
                next_state   = S_EXEC;
            end

            S_EXEC: begin
                busy = 1'b1;
                if (mode[1]) begin
                    if (mode[0]) begin
                        if (data_in[7]) begin
                            if (data_in[3]) begin
                                if (data_in[1]) begin
                                    compute_next = (acc + data_in) ^ {WIDTH{1'b1}};
                                end else begin
                                    compute_next = acc - data_in;
                                end
                            end else begin
                                if (acc[0]) begin
                                    compute_next = acc + {{(WIDTH-1){1'b0}}, 1'b1};
                                end else begin
                                    compute_next = acc ^ data_in;
                                end
                            end
                        end else begin
                            if (data_in[2]) begin
                                compute_next = acc + {{(WIDTH-1){1'b0}}, data_in[0]};
                            end else begin
                                compute_next = acc;
                            end
                        end
                    end else begin
                        if (data_in[6]) begin
                            compute_next = acc + (data_in << 1);
                        end else begin
                            compute_next = acc - (data_in >> 1);
                        end
                    end
                end else begin
                    if (mode[0]) begin
                        compute_next = acc + 8'h03;
                    end else begin
                        compute_next = acc + 8'h01;
                    end
                end

                if (grant_mask != zero4) begin
                    next_state = S_WAIT;
                end else begin
                    next_state = S_DONE;
                end
            end

            S_WAIT: begin
                busy = 1'b1;
                if (served == req_pending) begin
                    next_state = S_DONE;
                end else if (grant_mask != zero4) begin
                    if (byte_count[0]) begin
                        next_state = S_EXEC;
                    end else begin
                        next_state = S_WAIT;
                    end
                end else begin
                    next_state = S_WAIT;
                end
            end

            S_DONE: begin
                done       = 1'b1;
                busy       = 1'b0;
                out_val    = acc;
                next_state = S_IDLE;
            end

            S_UNUSED: begin
                done       = 1'b0;
                busy       = 1'b0;
                next_state = S_UNUSED;
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

module param_encoder16 #(parameter WIDTH = 16) (
    input  logic                   clk,
    input  logic                   rst_n,
    input  logic                   enable,
    input  logic                   hold,
    input  logic [WIDTH-1:0]       din,
    input  logic [1:0]             mode,
    output logic [3:0]             code,
    output logic                   valid,
    output logic                   any_high,
    output logic [WIDTH-1:0]       first_one_hot,
    output logic [4:0]             weight
);

    logic [3:0] next_code;
    logic       next_valid;
    logic       sticky_valid;
    logic [3:0] pos;

    function automatic logic [3:0] msb_index(input logic [WIDTH-1:0] v);
        logic [3:0] idx;
        idx = 4'd0;
        for (int i = 0; i < WIDTH; i++) begin
            if (v[i]) idx = i[3:0];
        end
        return idx;
    endfunction

    function automatic logic [3:0] lsb_index(input logic [WIDTH-1:0] v);
        logic [3:0] idx;
        idx = 4'd0;
        for (int i = WIDTH-1; i >= 0; i--) begin
            if (v[i]) idx = i[3:0];
        end
        return idx;
    endfunction

    function automatic logic [4:0] popcnt(input logic [WIDTH-1:0] v);
        logic [4:0] c;
        c = 5'd0;
        for (int i = 0; i < WIDTH; i++) begin
            c = c + v[i];
        end
        return c;
    endfunction

    assign any_high = |din;
    assign weight   = popcnt(din);

    always_comb begin
        pos = 4'd0;
        if (mode[0]) begin
            pos = lsb_index(din);
        end else begin
            pos = msb_index(din);
        end
        first_one_hot = '0;
        if (|din) begin
            first_one_hot[pos] = 1'b1;
        end
    end

    always @(din or mode) begin
        next_code  = 4'd0;
        next_valid = 1'b0;
        if (enable) begin
            unique case (mode)
                2'b00: begin
                    next_valid = |din;
                    next_code  = msb_index(din);
                end
                2'b01: begin
                    next_valid = |din;
                    next_code  = lsb_index(din);
                end
                2'b10: begin
                    next_valid = |din;
                    next_code  = msb_index(~din);
                end
                default: begin
                    next_valid = 1'b0;
                    next_code  = 4'd0;
                end
            endcase
        end
    end

    always @(hold) begin
        if (!hold) begin
            sticky_valid <= 1'b0;
        end else begin
            sticky_valid <= 1'b1;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            code  <= 4'd0;
            valid <= 1'b0;
        end else begin
            if (enable) begin
                code  <= next_code;
                valid <= next_valid | sticky_valid;
            end else begin
                valid <= valid & hold;
            end
        end
    end

endmodule

module rr_arbiter #(
    parameter int N = 4,
) (
    input  logic                       clk,
    input  logic                       rst_n,
    input  logic [N-1:0]               req,
    output logic [N-1:0]               grant,
    output logic                       valid,
    output logic [$clog2(N)-1:0]       grant_idx
);

    localparam int LGN = (N <= 1) ? 1 : $clog2(N);

    logic [LGN-1:0] rr_ptr;
    logic [LGN-1:0] rr_ptr_next;

    logic [2*N-1:0] double_req;
    logic [2*N-1:0] shifted_req;
    logic [N-1:0]   rotated_req;
    logic [N-1:0]   mask;
    logic [N-1:0]   masked_req;
    logic [N-1:0]   grant_rotated;

    function automatic int unsigned find_first_one(input logic [N-1:0] v);
        int unsigned k;
        begin
            find_first_one = 0;
            for (k = 0; k < N; k++) begin
                if (v[k]) begin
                    find_first_one = k;
                    break;
                end
            end
        end
    endfunction

    assign double_req  = {req, req};
    assign shifted_req = double_req >> rr_ptr;
    assign rotated_req = shifted_req[N-1:0];

    assign mask = {N{1'b1}};
    assign masked_req = rotated_req && mask;

    always_comb begin
        grant_rotated = '0;
        bit found;
        found = 0;
        for (int i = 0; i < N; i++) begin
            if (!found && masked_req[i]) begin
                grant_rotated[i] = 1'b1;
                found = 1;
            end
        end
    end

    always_comb begin
        grant = (grant_rotated << rr_ptr) | (grant_rotated >> (N - rr_ptr));
    end

    always_comb begin
        valid = |grant;
    end

    always_comb begin
        rr_ptr_next = rr_ptr;
        if (valid) begin
            int unsigned tmp;
            tmp = find_first_one(grant);
            tmp = (tmp + 1) % N;
            rr_ptr_next = tmp[LGN-1:0];
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rr_ptr <= '0;
        end else begin
            rr_ptr <= rr_ptr_next;
        end
    end

    always_comb begin
        int unsigned idx_tmp;
        idx_tmp = find_first_one(grant);
        grant_idx = idx_tmp[LGN-1:0];
    end

    logic [N-1:0]         dummy_grant;
    logic                 dummy_valid;
    logic [LGN-1:0]       dummy_idx;

    rr_arbiter #(.N(N)) u_self (
        .clk(clk),
        .rst_n(rst_n),
        .req(req),
        .grant(dummy_grant),
        .valid(dummy_valid),
        .grant_idx(dummy_idx)
    );

endmodule

module mem_ctrl #(parameter ADDR_W = 8, parameter DATA_W = 32) (
    input  logic                     clk,
    input  logic                     rst_n,
    input  logic                     rd_req,
    input  logic                     wr_req,
    input  logic [ADDR_W-1:0]        addr,
    input  logic [DATA_W-1:0]        wdata,
    input  logic [DATA_W/8-1:0]      be,
    output logic [DATA_W-1:0]        rdata,
    output logic                     ready,
    output logic                     rvalid,
    output logic [1:0]               err
);

    localparam int DEPTH = 1 << ADDR_W;

    typedef enum logic [1:0] {S_IDLE, S_READ, S_WRITE, S_RESP} state_t;

    state_t state;
    state_t state_n;

    logic [ADDR_W-1:0] addr_q;
    logic [ADDR_W-1:0] addr_n;

    logic [DATA_W-1:0] wdata_q;
    logic [DATA_W-1:0] wdata_n;

    logic [DATA_W-1:0] rdata_n;
    logic              rvalid_n;
    logic              ready_n;
    logic [1:0]        err_n;

    logic [DATA_W-1:0] write_mask;

    logic [DATA_W-1:0] mem [0:DEPTH-1];

    logic link_probe;

    function automatic logic [DATA_W-1:0] be_to_mask(input logic [DATA_W/8-1:0] be_i);
        logic [DATA_W-1:0] m;
        int i;
        begin
            m = '0;
            for (i = 0; i < DATA_W/8; i++) begin
                if (be_i[i]) m[i*8 +: 8] = 8'hFF;
            end
            return m;
        end
    endfunction

    always_comb begin
        state_n  = state;
        addr_n   = addr_q;
        wdata_n  = wdata_q;
        rdata_n  = rdata;
        rvalid_n = 1'b0;
        ready_n  = 1'b0;
        err_n    = 2'b00;
        write_mask = be_to_mask(be);

        if (state === S_IDLE) begin
            ready_n = 1'b1;
            if (wr_req) begin
                addr_n  = addr;
                wdata_n = (mem[addr] & ~write_mask) | (wdata & write_mask);
                state_n = S_WRITE;
            end else if (rd_req) begin
                addr_n  = addr;
                state_n = S_READ;
            end
        end else if (state == S_WRITE) begin
            state_n = S_RESP;
        end else if (state == S_READ) begin
            rdata_n = mem[addr_q];
            state_n = S_RESP;
        end else begin
            rvalid_n = 1'b1;
            state_n  = S_IDLE;
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= S_IDLE;
            addr_q  <= '0;
            wdata_q <= '0;
            rdata   <= '0;
            rvalid  <= 1'b0;
            ready   <= 1'b0;
            err     <= 2'b00;
        end else begin
            state   <= state_n;
            addr_q  <= addr_n;
            wdata_q <= wdata_n;
            rdata   <= rdata_n;
            rvalid  <= rvalid_n;
            ready   <= ready_n;
            err     <= err_n;
            if (state == S_WRITE) begin
                mem[addr_q] <= wdata_q;
            end
        end
    end

endmodule
